begin;
-- FR-350 dependency for procurement receipts. No existing product or stock rows changed.
create table inventory.product_unit_conversions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,product_id uuid not null,
 unit_id uuid not null,base_unit_id uuid not null,numerator bigint not null check(numerator>0),denominator bigint not null check(denominator>0),
 status text not null check(status in('active','inactive')),version bigint not null default 1,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,product_id,unit_id),
 foreign key(tenant_id,legal_entity_id,product_id) references inventory.products(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,unit_id) references inventory.units(tenant_id,id),
 foreign key(tenant_id,base_unit_id) references inventory.units(tenant_id,id),check(unit_id<>base_unit_id)
);
create table inventory.product_unit_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,conversion_id uuid not null,
 version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(conversion_id,version),foreign key(tenant_id,legal_entity_id,conversion_id) references inventory.product_unit_conversions(tenant_id,legal_entity_id,id)
);
alter table inventory.product_unit_conversions enable row level security;alter table inventory.product_unit_conversions force row level security;
alter table inventory.product_unit_history enable row level security;alter table inventory.product_unit_history force row level security;
create policy product_units_read on inventory.product_unit_conversions for select to authenticated
 using(core.has_permission(tenant_id,'inventory.catalog.view',legal_entity_id,null) or core.has_permission(tenant_id,'inventory.catalog.manage',legal_entity_id,null));
create policy product_units_read on inventory.product_unit_history for select to authenticated
 using(exists(select 1 from inventory.product_unit_conversions c where c.id=conversion_id and c.tenant_id=product_unit_history.tenant_id));
create trigger product_unit_history_immutable before update or delete on inventory.product_unit_history for each row execute function workflow.reject_history_mutation();
revoke all on inventory.product_unit_conversions,inventory.product_unit_history from public,anon,authenticated;
grant select on inventory.product_unit_conversions,inventory.product_unit_history to authenticated;
create view api.product_unit_conversions with(security_invoker=true) as
select c.tenant_id,c.legal_entity_id,c.id,c.product_id,c.status,sales.flow_exact_json(to_jsonb(c))||jsonb_build_object(
 'numerator',c.numerator::text,'denominator',c.denominator::text) detail from inventory.product_unit_conversions c;
grant select on api.product_unit_conversions to authenticated;

create function api.upsert_product_unit_conversion(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_hash text;v_result jsonb;v_old inventory.product_unit_conversions%rowtype;
 v_product inventory.products%rowtype;v_num bigint;v_den bigint;v_before jsonb;v_entity jsonb;v_unit uuid:=(p_payload->>'unit_id')::uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,null);
 if p_legal_entity_id is null or p_branch_id is null or v_id is null or p_client_timestamp is null or jsonb_typeof(p_payload) is distinct from 'object' then
  raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash('inventory.product_unit.upsert',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,'inventory.product_unit.upsert',p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_product from inventory.products where id=(p_payload->>'product_id')::uuid and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' for share;
 if not found then raise exception using errcode='22023',message='PRODUCT_INVALID';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('product-unit:'||v_product.id::text||':'||v_unit::text,0));
 select * into v_old from inventory.product_unit_conversions where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
 if found then
  v_before:=sales.flow_exact_json(to_jsonb(v_old))||jsonb_build_object('numerator',v_old.numerator::text,'denominator',v_old.denominator::text);
  perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
  if v_old.product_id<>v_product.id or v_old.unit_id<>v_unit or v_old.base_unit_id<>v_product.base_unit_id then raise exception using errcode='22023',message='CONVERSION_IDENTITY_IMMUTABLE';end if;
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 if v_unit=v_product.base_unit_id or not exists(select 1 from inventory.units u join inventory.units b on b.id=v_product.base_unit_id and b.tenant_id=u.tenant_id
  where u.id=v_unit and u.tenant_id=p_tenant_id and u.status='active' and b.status='active' and u.category=b.category) then
  raise exception using errcode='22023',message='CONVERSION_UNIT_INVALID';end if;
 v_num:=sales.wave3_positive_bigint(p_payload->'numerator','numerator');v_den:=sales.wave3_positive_bigint(p_payload->'denominator','denominator');
 insert into inventory.product_unit_conversions(id,tenant_id,legal_entity_id,product_id,unit_id,base_unit_id,numerator,denominator,status,created_by,updated_by)
 values(v_id,p_tenant_id,p_legal_entity_id,v_product.id,v_unit,v_product.base_unit_id,v_num,v_den,p_payload->>'status',auth.uid(),auth.uid())
 on conflict(id) do update set numerator=excluded.numerator,denominator=excluded.denominator,status=excluded.status,version=inventory.product_unit_conversions.version+1,
  updated_by=auth.uid(),updated_at=clock_timestamp() where inventory.product_unit_conversions.tenant_id=p_tenant_id and inventory.product_unit_conversions.legal_entity_id=p_legal_entity_id;
 if not found then raise exception using errcode='22023',message='CONVERSION_IDENTITY_INVALID';end if;
 select sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('numerator',c.numerator::text,'denominator',c.denominator::text) into v_entity
  from inventory.product_unit_conversions c where c.id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,'inventory.product_unit.upsert',p_command_id,'product_unit_conversion',v_id,p_idempotency_key,v_hash,v_before,v_entity,
  p_legal_entity_id,p_branch_id,'{}',null,jsonb_build_array(jsonb_build_object('topic','inventory.product_unit.updated','payload','{}'::jsonb)));
 insert into inventory.product_unit_history(tenant_id,legal_entity_id,conversion_id,version,snapshot,actor_id)
 values(p_tenant_id,p_legal_entity_id,v_id,(v_entity->>'version')::bigint,v_entity,auth.uid());return v_result;
end $$;
revoke all on function api.upsert_product_unit_conversion(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_product_unit_conversion(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function inventory.resolve_product_unit(p_tenant uuid,p_entity uuid,p_product uuid,p_unit uuid,p_quantity jsonb,p_numerator jsonb,p_denominator jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_product inventory.products%rowtype;v_conversion inventory.product_unit_conversions%rowtype;v_quantity numeric;v_base numeric;
 v_num bigint;v_den bigint;v_precision integer;v_base_precision integer;
begin
 if auth.uid() is null or not core.is_tenant_member(p_tenant) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 v_quantity:=sales.wave3_decimal_string(p_quantity,'quantity',6,true,0,null);
 v_num:=sales.wave3_positive_bigint(p_numerator,'conversion_numerator');v_den:=sales.wave3_positive_bigint(p_denominator,'conversion_denominator');
 select precision into v_precision from inventory.units where id=p_unit and tenant_id=p_tenant and status='active';
 if not found or v_quantity<=0 or round(v_quantity,v_precision)<>v_quantity then raise exception using errcode='22023',message='TRANSACTION_UNIT_PRECISION_INVALID';end if;
 if p_product is null then
  if v_num<>1 or v_den<>1 then raise exception using errcode='22023',message='FREE_TEXT_UNIT_MUST_BE_BASE';end if;
  v_base_precision:=v_precision;
 else
  select * into v_product from inventory.products where id=p_product and tenant_id=p_tenant and legal_entity_id=p_entity and status='active';
  if not found then raise exception using errcode='22023',message='PRODUCT_INVALID';end if;
  select precision into v_base_precision from inventory.units where id=v_product.base_unit_id and tenant_id=p_tenant and status='active';
  if not found then raise exception using errcode='22023',message='BASE_UNIT_INVALID';end if;
  if p_unit=v_product.base_unit_id then
   if v_num<>1 or v_den<>1 then raise exception using errcode='22023',message='BASE_CONVERSION_MUST_BE_ONE';end if;
  else
   select * into v_conversion from inventory.product_unit_conversions where tenant_id=p_tenant and legal_entity_id=p_entity and product_id=p_product
    and unit_id=p_unit and base_unit_id=v_product.base_unit_id and status='active' for share;
   if not found or v_conversion.numerator<>v_num or v_conversion.denominator<>v_den then raise exception using errcode='22023',message='GOVERNED_CONVERSION_REQUIRED';end if;
  end if;
 end if;
 if mod(v_quantity*1000000*v_num,v_den)<>0 then raise exception using errcode='22023',message='BASE_QUANTITY_PRECISION_INVALID';end if;
 v_base:=v_quantity*v_num/v_den;
 if round(v_base,v_base_precision)<>v_base or v_base>=100000000000000 then raise exception using errcode='22023',message='BASE_QUANTITY_PRECISION_INVALID';end if;
 return jsonb_build_object('base_quantity',v_base::numeric(20,6)::text,'base_unit_id',coalesce(v_product.base_unit_id,p_unit),
  'conversion_numerator',v_num::text,'conversion_denominator',v_den::text,'conversion_id',v_conversion.id,'conversion_version',v_conversion.version);
end $$;
revoke all on function inventory.resolve_product_unit(uuid,uuid,uuid,uuid,jsonb,jsonb,jsonb) from public,anon,authenticated;
create index product_unit_unit on inventory.product_unit_conversions(tenant_id,unit_id);
create index product_unit_base on inventory.product_unit_conversions(tenant_id,base_unit_id);
create index product_unit_creator on inventory.product_unit_conversions(created_by);
create index product_unit_editor on inventory.product_unit_conversions(updated_by);
create index product_unit_history_source on inventory.product_unit_history(tenant_id,legal_entity_id,conversion_id);
create index product_unit_history_actor on inventory.product_unit_history(actor_id);

-- Candidate only: AC-309 / FR-335. Not applied. Published migrations are immutable.
-- Requisition save is deliberately separate from workflow submission/approval.
create table procurement.requisitions (
  id uuid primary key,
  tenant_id uuid not null references core.tenants(id),
  legal_entity_id uuid not null,
  branch_id uuid not null,
  requester_id uuid not null references auth.users(id),
  need_by date not null,
  justification text not null check (length(trim(justification)) between 1 and 4000),
  currency_code text not null references core.currencies(code),
  estimated_total numeric(20,6) not null check (estimated_total >= 0),
  status text not null default 'draft' check (status in ('draft','pending_approval','approved','rejected','cancelled')),
  version bigint not null default 1 check (version > 0),
  created_by uuid not null references auth.users(id),
  updated_by uuid not null references auth.users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, legal_entity_id, id),
  foreign key (tenant_id, legal_entity_id) references core.legal_entities(tenant_id,id),
  foreign key (tenant_id, branch_id) references core.branches(tenant_id,id)
);
create table procurement.requisition_lines (
  id uuid primary key,
  tenant_id uuid not null,
  legal_entity_id uuid not null,
  requisition_id uuid not null,
  ordinal integer not null check (ordinal between 1 and 500),
  product_id uuid,
  description text not null check (length(trim(description)) between 1 and 1000),
  unit_id uuid not null,
  quantity numeric(20,6) not null check (quantity > 0),
  base_quantity numeric(20,6) not null check(base_quantity>0),
  conversion_numerator bigint not null check(conversion_numerator>0),
  conversion_denominator bigint not null check(conversion_denominator>0),
  conversion_id uuid,conversion_version bigint,
  estimated_unit_price numeric(20,6) not null check (estimated_unit_price >= 0),
  estimated_total numeric(20,6) not null check (estimated_total >= 0),
  unique (requisition_id,ordinal),
  foreign key (tenant_id,legal_entity_id,requisition_id)
    references procurement.requisitions(tenant_id,legal_entity_id,id),
  foreign key (tenant_id,legal_entity_id,product_id)
    references inventory.products(tenant_id,legal_entity_id,id),
  foreign key (tenant_id,unit_id) references inventory.units(tenant_id,id)
);
create index requisitions_scope_page on procurement.requisitions(tenant_id,legal_entity_id,branch_id,id);
create index requisitions_requester on procurement.requisitions(requester_id);
create index requisitions_branch on procurement.requisitions(tenant_id,branch_id);
create index requisition_lines_source on procurement.requisition_lines(tenant_id,legal_entity_id,requisition_id);
create index requisition_lines_product on procurement.requisition_lines(tenant_id,legal_entity_id,product_id);
create index requisition_lines_unit on procurement.requisition_lines(tenant_id,unit_id);
alter table procurement.requisitions enable row level security;
alter table procurement.requisitions force row level security;
alter table procurement.requisition_lines enable row level security;
alter table procurement.requisition_lines force row level security;
create policy requisitions_read on procurement.requisitions for select to authenticated
using (core.has_permission(tenant_id,'procurement.requisitions.manage',legal_entity_id,branch_id));
create policy requisition_lines_read on procurement.requisition_lines for select to authenticated
using (exists (select 1 from procurement.requisitions r where r.id=requisition_id
  and r.tenant_id=requisition_lines.tenant_id and r.legal_entity_id=requisition_lines.legal_entity_id));
revoke all on procurement.requisitions,procurement.requisition_lines from public,anon,authenticated;
grant usage on schema procurement to authenticated;
grant select on procurement.requisitions,procurement.requisition_lines to authenticated;

create view api.purchase_requisitions with (security_invoker=true) as
select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,r.status,
  jsonb_build_object('id',r.id,'requester_id',r.requester_id,'need_by',r.need_by,
    'justification',r.justification,'currency_code',r.currency_code,
    'estimated_total',r.estimated_total::text,'status',r.status,'version',r.version,
    'lines',coalesce((select jsonb_agg(jsonb_build_object(
      'line_id',l.id,'product_id',l.product_id,'description',l.description,
      'unit_id',l.unit_id,'quantity',l.quantity::text,
      'estimated_unit_price',l.estimated_unit_price::text,
      'estimated_total',l.estimated_total::text,
      'base_quantity',l.base_quantity::text,'conversion_numerator',l.conversion_numerator::text,
      'conversion_denominator',l.conversion_denominator::text,'conversion_id',l.conversion_id,'conversion_version',l.conversion_version) order by l.ordinal)
      from procurement.requisition_lines l where l.requisition_id=r.id),'[]'::jsonb)) detail
from procurement.requisitions r;
grant select on api.purchase_requisitions to authenticated;

create function api.upsert_purchase_requisition(
  p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
  p_payload jsonb,p_expected_entity_version bigint default null
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v_actor uuid := (select auth.uid());
  v_id uuid; v_hash text; v_replay jsonb; v_before jsonb; v_entity jsonb;
  v_old procurement.requisitions%rowtype;
  v_line jsonb; v_unit jsonb; v_quantity numeric; v_price numeric; v_total numeric := 0;
  v_ordinal integer := 0; v_need_by date; v_currency text;
begin
  perform core.wave3_require_scope(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id);
  if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null
    or jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception using errcode='22023',message='INVALID_COMMAND';
  end if;
  v_hash := core.wave3_request_hash('procurement.requisition.upsert',p_command_id,
    p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
  v_replay := core.wave3_replay(p_tenant_id,'procurement.requisition.upsert',p_command_id,p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay; end if;
  v_id := (p_payload->>'id')::uuid;
  if v_id is null then raise exception using errcode='22023',message='DOCUMENT_ID_REQUIRED'; end if;
  -- Serialize create/update for the same stable document identity, including different keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('procurement.requisition:'||v_id::text,0));
  select * into v_old from procurement.requisitions where id=v_id
    and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
  if found then
    select detail into v_before from api.purchase_requisitions where id=v_id;
    perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
    if v_old.status <> 'draft' then
      raise exception using errcode='55000',message='REQUISITION_NOT_EDITABLE';
    end if;
  elsif p_expected_entity_version is not null then
    raise exception using errcode='40001',message='VERSION_CONFLICT';
  end if;
  if jsonb_typeof(p_payload->'lines') is distinct from 'array' then
    raise exception using errcode='22023',message='LINES_REQUIRED';
  end if;
  if jsonb_array_length(p_payload->'lines') not between 1 and 500
    or length(trim(coalesce(p_payload->>'justification',''))) not between 1 and 4000 then
    raise exception using errcode='22023',message='INVALID_REQUISITION';
  end if;
  if coalesce(p_payload->>'need_by','') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception using errcode='22023',message='NEED_BY_REQUIRED';
  end if;
  v_need_by := (p_payload->>'need_by')::date;
  select currency_code into v_currency from core.legal_entities
    where id=p_legal_entity_id and tenant_id=p_tenant_id;
  if p_payload->>'currency_code' is distinct from v_currency then
    raise exception using errcode='22023',message='ESTIMATE_BASE_CURRENCY_REQUIRED';
  end if;
  for v_line in select value from jsonb_array_elements(p_payload->'lines') loop
    v_quantity := sales.wave3_decimal_string(v_line->'quantity','quantity',6,true,0,null);
    v_price := sales.wave3_decimal_string(v_line->'estimated_unit_price','estimated_unit_price',6,true,0,null);
    if v_quantity <= 0 or v_quantity >= 100000000000000 or v_price >= 100000000000000 then
      raise exception using errcode='22023',message='BASE_UNIT_ESTIMATE_REQUIRED';
    end if;
    if not exists(select 1 from inventory.units u where u.id=(v_line->>'unit_id')::uuid
      and u.tenant_id=p_tenant_id and u.status='active'
      and round(v_quantity,u.precision)=v_quantity) then
      raise exception using errcode='22023',message='UNIT_INVALID';
    end if;
    if v_line->>'product_id' is not null and not exists(select 1 from inventory.products p
      where p.id=(v_line->>'product_id')::uuid and p.tenant_id=p_tenant_id
      and p.legal_entity_id=p_legal_entity_id and p.status='active' and p.can_purchase) then
      raise exception using errcode='22023',message='PRODUCT_INVALID';
    end if;
    v_total := v_total + round(v_quantity*v_price,6);
  end loop;
  if v_old.id is null then
    insert into procurement.requisitions(id,tenant_id,legal_entity_id,branch_id,requester_id,
      need_by,justification,currency_code,estimated_total,created_by,updated_by)
    values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_actor,v_need_by,
      trim(p_payload->>'justification'),v_currency,v_total,v_actor,v_actor);
  else
    update procurement.requisitions set need_by=v_need_by,justification=trim(p_payload->>'justification'),
      estimated_total=v_total,version=version+1,updated_by=v_actor,updated_at=clock_timestamp() where id=v_id;
    delete from procurement.requisition_lines where requisition_id=v_id;
  end if;
  for v_line in select value from jsonb_array_elements(p_payload->'lines') loop
    v_ordinal := v_ordinal+1;
    v_quantity := (v_line->>'quantity')::numeric; v_price := (v_line->>'estimated_unit_price')::numeric;
    v_unit:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_line->>'product_id')::uuid,(v_line->>'unit_id')::uuid,
      v_line->'quantity',v_line->'conversion_numerator',v_line->'conversion_denominator');
    insert into procurement.requisition_lines(id,tenant_id,legal_entity_id,requisition_id,ordinal,
      product_id,description,unit_id,quantity,estimated_unit_price,estimated_total,base_quantity,conversion_numerator,conversion_denominator,conversion_id,conversion_version)
    values((v_line->>'line_id')::uuid,p_tenant_id,p_legal_entity_id,v_id,v_ordinal,
      (v_line->>'product_id')::uuid,trim(v_line->>'description'),(v_line->>'unit_id')::uuid,
      v_quantity,v_price,round(v_quantity*v_price,6),(v_unit->>'base_quantity')::numeric,(v_unit->>'conversion_numerator')::bigint,
      (v_unit->>'conversion_denominator')::bigint,(v_unit->>'conversion_id')::uuid,(v_unit->>'conversion_version')::bigint);
  end loop;
  select detail into v_entity from api.purchase_requisitions where id=v_id;
  return core.wave3_finish_command(p_tenant_id,'procurement.requisition.upsert',p_command_id,
    'purchase_requisition',v_id,p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,
    '{}'::jsonb,null,jsonb_build_array(jsonb_build_object('topic','procurement.requisition.saved',
      'payload',jsonb_build_object('version',v_entity->'version'))));
end;
$$;
revoke all on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- Unapplied candidate, AC-309 FR-336. Module-owned; no shared function replacement.
alter table procurement.requisitions
 add column document_number text,
 add column workflow_snapshot jsonb,
 add column submitted_by uuid references auth.users(id),
 add column submitted_at timestamptz,
 add constraint requisition_number_unique unique(tenant_id,legal_entity_id,branch_id,document_number);
create index requisitions_submitter on procurement.requisitions(submitted_by);
create index requisitions_creator on procurement.requisitions(created_by);
create index requisitions_editor on procurement.requisitions(updated_by);
create index requisitions_currency on procurement.requisitions(currency_code);

create table procurement.requisition_history (
 id uuid primary key default gen_random_uuid(),
 tenant_id uuid not null,
 legal_entity_id uuid not null,
 requisition_id uuid not null,
 version bigint not null,
 snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),
 actor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),
 unique(requisition_id,version),
 foreign key(tenant_id,legal_entity_id,requisition_id) references procurement.requisitions(tenant_id,legal_entity_id,id)
);
create index requisition_history_source on procurement.requisition_history(tenant_id,legal_entity_id,requisition_id);
create index requisition_history_actor on procurement.requisition_history(actor_id);
alter table procurement.requisition_history enable row level security;
alter table procurement.requisition_history force row level security;
create policy requisition_history_read on procurement.requisition_history for select to authenticated
using(exists(select 1 from procurement.requisitions r where r.id=requisition_id
 and r.tenant_id=requisition_history.tenant_id and r.legal_entity_id=requisition_history.legal_entity_id));
create trigger requisition_history_immutable before update or delete on procurement.requisition_history
for each row execute function workflow.reject_history_mutation();
revoke all on procurement.requisition_history from public,anon,authenticated;
grant select on procurement.requisition_history to authenticated;

-- Do not install a trigger on shared receipts: history is written by module-owned commands.
-- Wrap only this session's unpublished requisition function; signature remains stable.
alter function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 set schema procurement;
alter function procurement.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 rename to save_requisition_draft;
revoke all on function procurement.save_requisition_draft(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;

create function procurement.record_requisition_history(p_result jsonb) returns void
language plpgsql security definer set search_path='' as $$begin
 insert into procurement.requisition_history(tenant_id,legal_entity_id,requisition_id,version,snapshot,actor_id)
 select r.tenant_id,r.legal_entity_id,r.id,(p_result#>>'{entity,version}')::bigint,p_result->'entity',auth.uid()
 from procurement.requisitions r where r.id=(p_result#>>'{entity,id}')::uuid
 on conflict(requisition_id,version) do nothing;
end $$;
create function api.upsert_purchase_requisition(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$declare v_result jsonb;begin
 v_result:=procurement.save_requisition_draft(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,
 p_client_timestamp,p_payload,p_expected_entity_version);
 perform procurement.record_requisition_history(v_result);return v_result;end $$;

create or replace view api.purchase_requisitions with(security_invoker=true) as
select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,r.status,
 jsonb_build_object('id',r.id,'requester_id',r.requester_id,'need_by',r.need_by,
 'justification',r.justification,'currency_code',r.currency_code,'document_number',r.document_number,
 'estimated_total',r.estimated_total::text,'status',r.status,'version',r.version,
 'workflow_snapshot',r.workflow_snapshot,'created_by',r.created_by,'updated_by',r.updated_by,
 'submitted_by',r.submitted_by,'submitted_at',r.submitted_at,'created_at',r.created_at,
 'lines',coalesce((select jsonb_agg(jsonb_build_object('line_id',l.id,'product_id',l.product_id,
 'description',l.description,'unit_id',l.unit_id,'quantity',l.quantity::text,
 'estimated_unit_price',l.estimated_unit_price::text,'estimated_total',l.estimated_total::text,
 'base_quantity',l.base_quantity::text,'conversion_numerator',l.conversion_numerator::text,
 'conversion_denominator',l.conversion_denominator::text,'conversion_id',l.conversion_id,'conversion_version',l.conversion_version) order by l.ordinal)
 from procurement.requisition_lines l where l.requisition_id=r.id),'[]'::jsonb)) detail
from procurement.requisitions r;

create function api.transition_purchase_requisition(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_actor uuid:=auth.uid();v_id uuid;v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';
 v_command text:='procurement.requisition.transition';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.requisitions%rowtype;v_workflow workflow.workflow_definitions%rowtype;
 v_ar workflow.approval_requests%rowtype;v_snapshot jsonb;v_step jsonb;v_first integer;v_to text;
 v_request uuid:=gen_random_uuid();v_reason text:=nullif(trim(coalesce(p_payload->>'reason',p_payload->>'note')),'');
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or jsonb_typeof(p_payload) is distinct from 'object' or (v_action is null)=(v_decision is null) then
 raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_decision is not null then
  perform core.require_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 end if;
 v_id:=(p_payload->>'document_id')::uuid;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 select * into v_doc from procurement.requisitions where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select detail into v_before from api.purchase_requisitions where id=v_id;
 perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
 v_snapshot:=v_doc.workflow_snapshot;
 if v_action='submit' then
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='REQUISITION_NOT_EDITABLE';end if;
  if not exists(select 1 from core.memberships where tenant_id=p_tenant_id and user_id=v_doc.requester_id and status='active')
  or exists(select 1 from procurement.requisition_lines l left join inventory.units u on u.id=l.unit_id and u.tenant_id=l.tenant_id
    left join inventory.products p on p.id=l.product_id and p.tenant_id=l.tenant_id and p.legal_entity_id=l.legal_entity_id
    where l.requisition_id=v_id and (u.status is distinct from 'active' or round(l.quantity,u.precision)<>l.quantity
    or (l.product_id is not null and (p.status is distinct from 'active' or not p.can_purchase)))) then
   raise exception using errcode='22023',message='REFERENCE_INVALID';end if;
  perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,l.product_id,l.unit_id,to_jsonb(l.quantity::text),
    to_jsonb(l.conversion_numerator::text),to_jsonb(l.conversion_denominator::text)) from procurement.requisition_lines l where l.requisition_id=v_id;
  select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id
   and document_type='purchase_requisition' and status='active' and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
   order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
   'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
   from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
   and (s.currency_code is null or s.currency_code=v_doc.currency_code)
   and (s.minimum_amount is null or s.minimum_amount<=v_doc.estimated_total)
   and (s.maximum_amount is null or s.maximum_amount>=v_doc.estimated_total);
  select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
  if v_first is null and v_workflow.lifecycle->'requires_approval' is distinct from 'false'::jsonb then
   raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
  v_to:=case when v_first is null then 'approved' else 'pending_approval' end;
  if v_first is null then perform sales.flow_assert_transition(v_workflow.lifecycle,'submitted','approved');end if;
  v_doc.document_number:=coalesce(v_doc.document_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,
    p_branch_id,'purchase_requisition',(v_doc.created_at at time zone 'UTC')::date,v_actor));
  if v_first is not null then
   insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
    submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,'purchase_requisition',v_id,'submitted',v_actor,
    v_workflow.id,v_workflow.revision,v_first,v_doc.estimated_total,v_doc.currency_code,p_command_id,v_request,v_request);
  end if;
 elsif v_decision is not null then
  if v_doc.status<>'pending_approval' or v_decision not in ('approved','rejected') then
   raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
  select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type='purchase_requisition'
   and document_id=v_id and status='submitted' for update;
  if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
  if v_actor in(v_doc.requester_id,v_doc.created_by,v_doc.updated_by,v_doc.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
  if v_step is null or not exists(select 1 from core.memberships m
   join core.role_assignments ra on ra.membership_id=m.id and ra.tenant_id=m.tenant_id
   join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
   where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
   and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
   and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then
   raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
  if v_decision='rejected' and v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
  insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
   approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
  values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
   v_actor,v_decision,v_reason,v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
  if v_decision='approved' then
   select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
    where (x->>'step_order')::integer>v_ar.current_step;
  end if;
  v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
  update workflow.approval_requests set current_step=coalesce(v_first,current_step),
   status=case when v_first is null then v_to else status end,
   decision_by=case when v_first is null then v_actor else decision_by end,
   decision_note=case when v_first is null then v_reason else decision_note end,
   decided_at=case when v_first is null then clock_timestamp() else decided_at end where id=v_ar.id;
 elsif v_action in('recall','cancel') then
  if v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  if v_snapshot is null then
   select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
    where tenant_id=p_tenant_id and document_type='purchase_requisition' and status='active'
    and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
    order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  end if;
  v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc.status,v_to);
  update workflow.approval_requests set status='cancelled',decision_by=v_actor,decision_note=v_reason,decided_at=clock_timestamp()
   where tenant_id=p_tenant_id and document_type='purchase_requisition' and document_id=v_id and status='submitted';
  if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 update procurement.requisitions set status=v_to,version=version+1,updated_at=clock_timestamp(),updated_by=v_actor,
  workflow_snapshot=v_snapshot,document_number=v_doc.document_number,
  submitted_by=case when v_action='submit' then v_actor else submitted_by end,
  submitted_at=case when v_action='submit' then clock_timestamp() else submitted_at end where id=v_id;
 select detail into v_entity from api.purchase_requisitions where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_requisition',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_doc.status=v_to then null else jsonb_build_object('from_status',v_doc.status,'to_status',v_to,'reason',v_reason) end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
 perform procurement.record_requisition_history(v_result);return v_result;
end $$;
revoke all on function procurement.record_requisition_history(jsonb) from public,anon,authenticated;
revoke all on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.transition_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.transition_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- AC-309 bounded reference reads. No role, membership or master-record mutations.
create function api.procurement_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_resource text,p_after uuid default null,p_search text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_items jsonb;v_more boolean;v_currency text;v_search text;
begin
 if core.has_permission(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id) then
  perform core.wave3_require_scope(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id);
 elsif core.has_permission(p_tenant_id,'procurement.rfq.manage',p_legal_entity_id,p_branch_id) then
  perform core.wave3_require_scope(p_tenant_id,'procurement.rfq.manage',p_legal_entity_id,p_branch_id);
 elsif core.has_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,p_branch_id) then
  perform core.wave3_require_scope(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,p_branch_id);
 else perform core.wave3_require_scope(p_tenant_id,'procurement.orders.manage',p_legal_entity_id,p_branch_id);end if;
 if p_legal_entity_id is null or p_branch_id is null or length(coalesce(p_search,''))>100 then
  raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 v_search:=lower(trim(coalesce(p_search,'')));
 select currency_code into v_currency from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='units' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'precision',precision) order by id)
  into v_items from(select * from inventory.units where tenant_id=p_tenant_id and status='active'
   and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='unit_conversions' then
  perform core.require_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,null);
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'detail',detail) order by id)
  into v_items from(select c.id,p.sku code,u.name,p.name||' · '||u.name label,
   c.detail||jsonb_build_object('_product_name',p.name,'_unit_name',u.name) detail
   from api.product_unit_conversions c join inventory.products p on p.id=c.product_id and p.tenant_id=c.tenant_id
   join inventory.units u on u.id=(c.detail->>'unit_id')::uuid and u.tenant_id=c.tenant_id
   where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id and (p_after is null or c.id>p_after)
   and (v_search='' or position(v_search in lower(p.sku||' '||p.name||' '||u.name))>0) order by c.id limit 51) x;
 elsif p_resource like 'product_units:%' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'conversion_numerator',numerator::text,
    'conversion_denominator',denominator::text,'conversion_id',conversion_id,'conversion_version',version) order by id)
  into v_items from(select * from (
   select u.id,u.code,u.name,1::bigint numerator,1::bigint denominator,null::uuid conversion_id,null::bigint version
   from inventory.products p join inventory.units u on u.id=p.base_unit_id and u.tenant_id=p.tenant_id
   where p.id=substring(p_resource from 15)::uuid and p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id and p.status='active' and u.status='active'
   union all
   select u.id,u.code,u.name,c.numerator,c.denominator,c.id,c.version from inventory.product_unit_conversions c
   join inventory.units u on u.id=c.unit_id and u.tenant_id=c.tenant_id
   where c.product_id=substring(p_resource from 15)::uuid and c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id and c.status='active' and u.status='active'
  ) q where (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='requisitions' then
  select jsonb_agg(jsonb_build_object('id',id,'code',detail->>'document_number','name',detail->>'justification','detail',detail) order by id)
  into v_items from(select * from api.purchase_requisitions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and status='approved' and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(detail->>'justification'))>0) order by id limit 51) x;
 elsif p_resource='selected_rfqs' then
  select jsonb_agg(jsonb_build_object('id',id,'code',detail->>'document_number','name',detail->>'title','detail',detail) order by id)
  into v_items from(select * from api.request_for_quotes where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and status='selected' and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(detail->>'title'))>0) order by id limit 51) x;
 elsif p_resource='rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,
   'currency_code',source_currency_code,'exchange_rate',rate::text,'rate_date',effective_date) order by id)
  into v_items from(select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and target_currency_code=v_currency and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51) x;
 elsif p_resource='taxes' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'rate',rate::text,'inclusive',inclusive) order by id)
  into v_items from(select * from finance.tax_definitions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and kind in('input','zero','exempt') and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource in('products','catalogue_products') then
  if p_resource='catalogue_products' then perform core.require_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,null);end if;
  select jsonb_agg(jsonb_build_object('id',id,'code',sku,'name',name,'unit_id',base_unit_id) order by id)
  into v_items from(select * from inventory.products where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and (can_purchase or p_resource='catalogue_products') and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(sku||' '||name))>0) order by id limit 51) x;
 elsif p_resource='suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id)
  into v_items from(select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both')
   and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51) x;
 elsif p_resource='warehouses' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name) order by id)
  into v_items from(select * from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and status='active' and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');v_more:=jsonb_array_length(v_items)>50;
 if v_more then v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',case when v_more then v_items#>>'{49,id}' else null end,
  'base_currency',v_currency,'limit',50);
end $$;
revoke all on function api.procurement_reference_options(uuid,uuid,uuid,text,uuid,text) from public,anon;
grant execute on function api.procurement_reference_options(uuid,uuid,uuid,text,uuid,text) to authenticated;

-- AC-309 / FR-337. Unapplied candidate. Invitations record intent; no external messages.
create table procurement.rfqs (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 requisition_id uuid not null,requisition_version bigint not null,
 invited_supplier_ids uuid[] not null check(cardinality(invited_supplier_ids) between 1 and 100),
 invited_suppliers jsonb not null,
 title text not null check(length(trim(title)) between 1 and 160),
 document_date date not null,close_date date not null,document_number text not null,
 status text not null default 'issued' check(status in('issued','selected','ordered','cancelled')),
 selected_quote_id uuid,selection_reason text,version bigint not null default 1,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id,requisition_id) references procurement.requisitions(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),check(close_date>=document_date)
);
create table procurement.rfq_lines (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 rfq_id uuid not null,source_line_id uuid not null,source_snapshot jsonb not null,
 unique(rfq_id,source_line_id),
 foreign key(tenant_id,legal_entity_id,rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id)
);
create index rfq_scope_page on procurement.rfqs(tenant_id,legal_entity_id,branch_id,id);
create index rfq_scope_status on procurement.rfqs(tenant_id,legal_entity_id,branch_id,status,id);
create table procurement.supplier_quotes (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,rfq_id uuid not null,
 supplier_id uuid not null,quote_date date not null,valid_until date not null,
 currency_code text not null references core.currencies(code),exchange_rate_id uuid,
 exchange_rate numeric(20,10) not null,rate_date date not null,
 payment_terms text not null,delivery_terms text not null,
 subtotal numeric(20,6) not null,tax_total numeric(20,6) not null,total numeric(20,6) not null,base_total numeric(20,6) not null,
 complete boolean not null,version bigint not null default 1,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(rfq_id,supplier_id),
 foreign key(tenant_id,legal_entity_id,rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id),
 check(valid_until>=quote_date),check(exchange_rate>0),check(subtotal>=0 and tax_total>=0 and total>=0 and base_total>=0),
 check(length(trim(payment_terms)) between 1 and 1000 and length(trim(delivery_terms)) between 1 and 1000)
);
alter table procurement.rfqs add constraint rfq_selected_quote_fk foreign key(tenant_id,legal_entity_id,selected_quote_id)
 references procurement.supplier_quotes(tenant_id,legal_entity_id,id);
create table procurement.supplier_quote_lines (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 quote_id uuid not null,source_line_id uuid not null,detail jsonb not null,
 unique(quote_id,source_line_id),foreign key(tenant_id,legal_entity_id,quote_id) references procurement.supplier_quotes(tenant_id,legal_entity_id,id)
);
create table procurement.rfq_history (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 rfq_id uuid not null,version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),unique(rfq_id,version),
 foreign key(tenant_id,legal_entity_id,rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id)
);
create function procurement.rfq_read_allowed(p_tenant uuid,p_entity uuid,p_rfq uuid) returns boolean
language sql stable security definer set search_path='' as $$select exists(select 1 from procurement.rfqs r
 where r.id=p_rfq and r.tenant_id=p_tenant and r.legal_entity_id=p_entity
 and (core.has_permission(r.tenant_id,'procurement.rfq.manage',r.legal_entity_id,r.branch_id)
 or core.has_permission(r.tenant_id,'procurement.orders.manage',r.legal_entity_id,r.branch_id)))$$;
alter table procurement.rfqs enable row level security;alter table procurement.rfqs force row level security;
create policy rfq_read on procurement.rfqs for select to authenticated using(procurement.rfq_read_allowed(tenant_id,legal_entity_id,id));
do $$declare t text;begin
 foreach t in array array['rfq_lines','supplier_quotes','rfq_history'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  execute format('create policy rfq_read on procurement.%I for select to authenticated using(procurement.rfq_read_allowed(tenant_id,legal_entity_id,rfq_id))',t);
 end loop;
end $$;
alter table procurement.supplier_quote_lines enable row level security;alter table procurement.supplier_quote_lines force row level security;
create policy quote_lines_read on procurement.supplier_quote_lines for select to authenticated
using(exists(select 1 from procurement.supplier_quotes q where q.id=quote_id and q.tenant_id=supplier_quote_lines.tenant_id));
create trigger rfq_history_immutable before update or delete on procurement.rfq_history for each row execute function workflow.reject_history_mutation();
create trigger rfq_sources_immutable before update or delete on procurement.rfq_lines for each row execute function workflow.reject_history_mutation();
revoke all on procurement.rfqs,procurement.rfq_lines,procurement.supplier_quotes,procurement.supplier_quote_lines,procurement.rfq_history from public,anon,authenticated;
grant select on procurement.rfqs,procurement.rfq_lines,procurement.supplier_quotes,procurement.supplier_quote_lines,procurement.rfq_history to authenticated;
revoke all on function procurement.rfq_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function procurement.rfq_read_allowed(uuid,uuid,uuid) to authenticated;

create view api.request_for_quotes with(security_invoker=true) as
select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,r.status,
 sales.flow_exact_json(to_jsonb(r))||jsonb_build_object(
 'lines',coalesce((select jsonb_agg(l.source_snapshot||jsonb_build_object('source_line_id',l.source_line_id) order by l.id)
  from procurement.rfq_lines l where l.rfq_id=r.id),'[]'),
 'quotes',coalesce((select jsonb_agg(sales.flow_exact_json(to_jsonb(q))||jsonb_build_object(
  'supplier_name',(select x->>'name' from jsonb_array_elements(r.invited_suppliers) x where x->>'id'=q.supplier_id::text),
  'lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.supplier_quote_lines l where l.quote_id=q.id),'[]'))
  order by q.base_total,q.id) from procurement.supplier_quotes q where q.rfq_id=r.id),'[]')) detail
from procurement.rfqs r;
grant select on api.request_for_quotes to authenticated;

create function api.upsert_request_for_quote(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_id uuid:=(p_payload->>'id')::uuid;v_operation text:=p_payload->>'operation';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_rfq procurement.rfqs%rowtype;v_req procurement.requisitions%rowtype;v_quote procurement.supplier_quotes%rowtype;
 v_supplier uuid;v_invites uuid[];v_sources uuid[];v_quote_id uuid;v_line jsonb;v_source jsonb;v_tax finance.tax_definitions%rowtype;
 v_lines jsonb:='[]';v_unit jsonb;v_seen uuid[]:='{}';v_line_id uuid;v_q numeric;v_price numeric;v_discount numeric;v_gross numeric;
 v_net numeric;v_tax_amount numeric;v_total numeric:=0;v_subtotal numeric:=0;v_tax_total numeric:=0;v_rate numeric;
 v_date date;v_valid date;v_rate_date date;v_currency text;v_base text;v_scale integer;v_rate_id uuid;v_complete boolean:=true;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.rfq.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_id is null
 or jsonb_typeof(p_payload) is distinct from 'object' or v_operation is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash('procurement.rfq.upsert',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,'procurement.rfq.upsert',p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('procurement.rfq:'||v_id::text,0));
 select * into v_rfq from procurement.rfqs where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  select detail into v_before from api.request_for_quotes where id=v_id;
  perform core.wave3_assert_expected_version(v_rfq.version,p_expected_entity_version,v_before);
  if v_rfq.status<>'issued' then raise exception using errcode='55000',message='RFQ_NOT_EDITABLE';end if;
 elsif v_operation<>'issue' or p_expected_entity_version is not null then
  raise exception using errcode='40001',message='VERSION_CONFLICT';
 end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if v_operation='issue' then
  if v_rfq.id is not null then raise exception using errcode='55000',message='RFQ_ALREADY_ISSUED';end if;
  select * into v_req from procurement.requisitions where id=(p_payload->>'requisition_id')::uuid and tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for share;
  if not found or v_req.status<>'approved' then raise exception using errcode='55000',message='APPROVED_REQUISITION_REQUIRED';end if;
  perform core.wave3_assert_expected_version(v_req.version,(p_payload->>'requisition_version')::bigint,'{}');
  if p_payload ? 'source_line_ids' then
   if jsonb_typeof(p_payload->'source_line_ids') is distinct from 'array' then raise exception using errcode='22023',message='RFQ_SOURCE_LINES_INVALID';end if;
   select array_agg(value::uuid) into v_sources from jsonb_array_elements_text(p_payload->'source_line_ids');
  else select array_agg(id) into v_sources from procurement.requisition_lines where requisition_id=v_req.id;end if;
  if coalesce(cardinality(v_sources),0) not between 1 and 500 or cardinality(v_sources)<>(select count(distinct x) from unnest(v_sources) x)
   or cardinality(v_sources)<>(select count(*) from procurement.requisition_lines where requisition_id=v_req.id and id=any(v_sources)) then
   raise exception using errcode='22023',message='RFQ_SOURCE_LINES_INVALID';end if;
  if jsonb_typeof(p_payload->'invited_supplier_ids') is distinct from 'array' then raise exception using errcode='22023',message='SUPPLIERS_REQUIRED';end if;
  select array_agg(value::uuid) into v_invites from jsonb_array_elements_text(p_payload->'invited_supplier_ids');
  if coalesce(cardinality(v_invites),0) not between 1 and 100 or
   cardinality(v_invites)<>(select count(distinct x) from unnest(v_invites) x) then raise exception using errcode='22023',message='SUPPLIERS_INVALID';end if;
  foreach v_supplier in array v_invites loop
   if not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
    raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
  end loop;
  v_date:=(p_payload->>'document_date')::date;
  insert into procurement.rfqs(id,tenant_id,legal_entity_id,branch_id,requisition_id,requisition_version,invited_supplier_ids,invited_suppliers,
   title,document_date,close_date,document_number,created_by,updated_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_req.id,v_req.version,v_invites,
   (select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) from crm.parties where id=any(v_invites)),trim(p_payload->>'title'),
   v_date,(p_payload->>'close_date')::date,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'request_for_quote',v_date,auth.uid()),auth.uid(),auth.uid());
  insert into procurement.rfq_lines(tenant_id,legal_entity_id,rfq_id,source_line_id,source_snapshot)
  select p_tenant_id,p_legal_entity_id,v_id,l.id,sales.flow_exact_json(to_jsonb(l)) from procurement.requisition_lines l where l.requisition_id=v_req.id and l.id=any(v_sources);
 elsif v_operation='record_quote' then
  v_supplier:=(p_payload->>'supplier_id')::uuid;v_quote_id:=(p_payload->>'quote_id')::uuid;
  if v_quote_id is null or v_supplier is null or not(v_supplier=any(v_rfq.invited_supplier_ids))
   or not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
    raise exception using errcode='22023',message='INVITED_SUPPLIER_REQUIRED';end if;
  select * into v_quote from procurement.supplier_quotes where rfq_id=v_id and supplier_id=v_supplier;
  if found and v_quote.id<>v_quote_id then raise exception using errcode='22023',message='QUOTE_ID_MISMATCH';end if;
  v_date:=(p_payload->>'quote_date')::date;v_valid:=(p_payload->>'valid_until')::date;v_currency:=p_payload->>'currency_code';
  v_rate_date:=(p_payload->>'rate_date')::date;v_rate_id:=(p_payload->>'exchange_rate_id')::uuid;
  v_rate:=sales.wave3_decimal_string(p_payload->'exchange_rate','exchange_rate',10,true,0,null);
  if v_rate<=0 or not exists(select 1 from core.currencies where code=v_currency and active) then raise exception using errcode='22023',message='CURRENCY_INVALID';end if;
  if v_currency=v_base then
   if v_rate<>1 or v_rate_id is not null then raise exception using errcode='22023',message='BASE_RATE_MUST_BE_ONE';end if;
  elsif not exists(select 1 from finance.exchange_rates where id=v_rate_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and source_currency_code=v_currency and target_currency_code=v_base and rate=v_rate and effective_date=v_rate_date) then
   raise exception using errcode='22023',message='RATE_SNAPSHOT_INVALID';end if;
  if jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 then
   raise exception using errcode='22023',message='QUOTE_LINES_REQUIRED';end if;
  for v_line in select value from jsonb_array_elements(p_payload->'lines') loop
   v_line_id:=(v_line->>'source_line_id')::uuid;
   if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='QUOTE_SOURCE_INVALID';end if;
   v_seen:=array_append(v_seen,v_line_id);
   select source_snapshot into v_source from procurement.rfq_lines where rfq_id=v_id and source_line_id=v_line_id;
   if not found then raise exception using errcode='22023',message='QUOTE_SOURCE_INVALID';end if;
   v_q:=sales.wave3_decimal_string(v_line->'quantity','quantity',6,true,0,null);
   v_price:=sales.wave3_decimal_string(v_line->'unit_price','unit_price',6,true,0,null);
   v_discount:=sales.wave3_decimal_string(coalesce(v_line->'discount_percent','"0"'),'discount_percent',6,true,0,100);
   if v_q<=0 then raise exception using errcode='22023',message='QUANTITY_INVALID';end if;
   v_unit:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_source->>'product_id')::uuid,(v_source->>'unit_id')::uuid,
    v_line->'quantity',v_source->'conversion_numerator',v_source->'conversion_denominator');
   if v_q<>(v_source->>'quantity')::numeric then v_complete:=false;end if;
   v_gross:=round(v_q*v_price,v_scale);v_discount:=round(v_gross*v_discount/100,v_scale);v_net:=v_gross-v_discount;
   v_tax:=null;v_tax_amount:=0;
   if v_line->>'tax_definition_id' is not null then
    select * into v_tax from finance.tax_definitions where id=(v_line->>'tax_definition_id')::uuid and tenant_id=p_tenant_id
     and legal_entity_id=p_legal_entity_id and status='active' and kind in('input','zero','exempt')
     and v_date>=valid_from and (valid_to is null or v_date<=valid_to);
    if not found then raise exception using errcode='22023',message='INPUT_TAX_INVALID';end if;
    v_tax_amount:=round(v_net*v_tax.rate/(case when v_tax.inclusive then 100+v_tax.rate else 100 end),v_scale);
    if v_tax.inclusive then v_net:=v_net-v_tax_amount;end if;
   end if;
   v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax_amount;v_total:=v_total+v_net+v_tax_amount;
   v_lines:=v_lines||jsonb_build_array(jsonb_build_object('source_line_id',v_line_id,'product_id',v_source->>'product_id',
    'description',v_source->>'description','unit_id',v_source->>'unit_id','quantity',v_q::text,'unit_price',v_price::text,
    'discount_percent',coalesce(v_line->>'discount_percent','0'),'discount_amount',v_discount::text,
    'tax_definition_id',v_tax.id,'tax_rate',coalesce(v_tax.rate,0)::text,'tax_inclusive',coalesce(v_tax.inclusive,false),
    'tax_definition_version',v_tax.version,'net_amount',v_net::text,'tax_amount',v_tax_amount::text,'line_total',(v_net+v_tax_amount)::text)||v_unit);
  end loop;
  v_complete:=v_complete and cardinality(v_seen)=(select count(*) from procurement.rfq_lines where rfq_id=v_id);
  insert into procurement.supplier_quotes(id,tenant_id,legal_entity_id,rfq_id,supplier_id,quote_date,valid_until,currency_code,
   exchange_rate_id,exchange_rate,rate_date,payment_terms,delivery_terms,subtotal,tax_total,total,base_total,complete,created_by,updated_by)
  values(v_quote_id,p_tenant_id,p_legal_entity_id,v_id,v_supplier,v_date,v_valid,v_currency,v_rate_id,v_rate,v_rate_date,
   trim(p_payload->>'payment_terms'),trim(p_payload->>'delivery_terms'),v_subtotal,v_tax_total,v_total,round(v_total*v_rate,v_scale),v_complete,auth.uid(),auth.uid())
  on conflict(id) do update set quote_date=excluded.quote_date,valid_until=excluded.valid_until,currency_code=excluded.currency_code,
   exchange_rate_id=excluded.exchange_rate_id,exchange_rate=excluded.exchange_rate,rate_date=excluded.rate_date,
   payment_terms=excluded.payment_terms,delivery_terms=excluded.delivery_terms,subtotal=excluded.subtotal,tax_total=excluded.tax_total,
   total=excluded.total,base_total=excluded.base_total,complete=excluded.complete,version=procurement.supplier_quotes.version+1,
   updated_by=auth.uid(),updated_at=clock_timestamp()
  where procurement.supplier_quotes.rfq_id=v_id and procurement.supplier_quotes.supplier_id=v_supplier and procurement.supplier_quotes.tenant_id=p_tenant_id;
  if not found then raise exception using errcode='22023',message='QUOTE_ID_MISMATCH';end if;
  delete from procurement.supplier_quote_lines where quote_id=v_quote_id;
  insert into procurement.supplier_quote_lines(tenant_id,legal_entity_id,quote_id,source_line_id,detail)
   select p_tenant_id,p_legal_entity_id,v_quote_id,(x->>'source_line_id')::uuid,x from jsonb_array_elements(v_lines) x;
  update procurement.rfqs set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 elsif v_operation='select' then
  select * into v_quote from procurement.supplier_quotes where id=(p_payload->>'quote_id')::uuid and rfq_id=v_id;
  if not found or not v_quote.complete or v_quote.valid_until<current_date then raise exception using errcode='55000',message='COMPLETE_VALID_QUOTE_REQUIRED';end if;
  if not exists(select 1 from crm.parties where id=v_quote.supplier_id and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
   raise exception using errcode='22023',message='SUPPLIER_INACTIVE';end if;
  if length(trim(coalesce(p_payload->>'selection_reason',''))) not between 1 and 1000 then raise exception using errcode='22023',message='SELECTION_REASON_REQUIRED';end if;
  update procurement.rfqs set status='selected',selected_quote_id=v_quote.id,selection_reason=trim(p_payload->>'selection_reason'),
   version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 else raise exception using errcode='22023',message='RFQ_OPERATION_INVALID';end if;
 select detail into v_entity from api.request_for_quotes where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,'procurement.rfq.upsert',p_command_id,'request_for_quote',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_operation='record_quote' then null else jsonb_build_object('from_status',v_rfq.status,'to_status',v_entity->>'status') end,
  jsonb_build_array(jsonb_build_object('topic','procurement.rfq.updated','payload',jsonb_build_object('operation',v_operation))));
 insert into procurement.rfq_history(tenant_id,legal_entity_id,rfq_id,version,snapshot,actor_id)
 values(p_tenant_id,p_legal_entity_id,v_id,(v_entity->>'version')::bigint,v_entity,auth.uid());
 return v_result;
end $$;
revoke all on function api.upsert_request_for_quote(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_request_for_quote(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
-- Index every reference without changing indexes on shared tables.
do $$declare c record;begin
 for c in select con.conrelid::regclass tbl,con.conname,
  (select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(con.conkey) with ordinality k(att,n)
   join pg_attribute a on a.attrelid=con.conrelid and a.attnum=k.att) cols
  from pg_constraint con join pg_class t on t.oid=con.conrelid join pg_namespace n on n.oid=t.relnamespace
  where con.contype='f' and n.nspname='procurement' and t.relname in('rfqs','rfq_lines','supplier_quotes','supplier_quote_lines','rfq_history')
 loop execute format('create index %I on %s(%s)',c.conname||'_idx',c.tbl,c.cols);end loop;
end $$;

-- AC-309 / FR-338–339. Additive development candidate; no posting effects.
create table procurement.purchase_orders(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 supplier_id uuid not null,warehouse_id uuid not null,source_rfq_id uuid,source_quote_id uuid,source_requisition_id uuid,
 source_snapshot jsonb not null,document_date date not null,promised_date date not null,document_number text,
 currency_code text not null references core.currencies(code),exchange_rate_id uuid,exchange_rate numeric(20,10) not null,
 rate_date date not null,payment_terms text not null,delivery_terms text not null,
 subtotal numeric(20,6) not null,tax_total numeric(20,6) not null,total numeric(20,6) not null,base_total numeric(20,6) not null,
 status text not null default 'draft' check(status in('draft','pending_approval','approved','rejected','cancelled','closed')),
 version bigint not null default 1,revision integer not null default 1,revision_reason text,workflow_snapshot jsonb,
 submitted_by uuid references auth.users(id),submitted_at timestamptz,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 commercial_editor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(source_quote_id),unique(source_rfq_id),
 unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id,source_rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,source_quote_id) references procurement.supplier_quotes(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,source_requisition_id) references procurement.requisitions(tenant_id,legal_entity_id,id),
 check((source_rfq_id is not null and source_quote_id is not null and source_requisition_id is null)
  or (source_rfq_id is null and source_quote_id is null and source_requisition_id is not null)),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id),
 check(promised_date>=document_date),check(exchange_rate>0),check(subtotal>=0 and tax_total>=0 and total>=0 and base_total>=0),
 check(length(trim(payment_terms)) between 1 and 1000 and length(trim(delivery_terms)) between 1 and 1000)
);
create table procurement.purchase_order_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,order_id uuid not null,
 source_line_id uuid not null,product_id uuid,unit_id uuid not null,description text not null,
 quantity numeric(20,6) not null,unit_price numeric(20,6) not null,discount_percent numeric(9,6) not null,
 cancelled_quantity numeric(20,6) not null default 0,received_quantity numeric(20,6) not null default 0,
 billed_quantity numeric(20,6) not null default 0,detail jsonb not null,
 approved_extra_quantity numeric(20,6) not null default 0 check(approved_extra_quantity>=0),
 unique(tenant_id,legal_entity_id,id),unique(order_id,source_line_id),
 foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,product_id) references inventory.products(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,unit_id) references inventory.units(tenant_id,id),
 check(quantity>0 and unit_price>=0 and discount_percent between 0 and 100),
 check(cancelled_quantity>=0 and received_quantity>=0 and billed_quantity>=0),
 constraint purchase_order_lines_received_limit check(cancelled_quantity+received_quantity<=quantity+approved_extra_quantity)
);
create index purchase_orders_scope_page on procurement.purchase_orders(tenant_id,legal_entity_id,branch_id,id);
create index purchase_orders_scope_status on procurement.purchase_orders(tenant_id,legal_entity_id,branch_id,status,id);
create index purchase_orders_supplier on procurement.purchase_orders(tenant_id,legal_entity_id,supplier_id,status,id);
create table procurement.purchase_order_revisions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 order_id uuid not null,version bigint not null,revision integer not null,snapshot jsonb not null,
 actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(order_id,version),foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id)
);
create function procurement.order_read_allowed(p_tenant uuid,p_entity uuid,p_order uuid) returns boolean
language sql stable security definer set search_path='' as $$select exists(select 1 from procurement.purchase_orders o
 where o.id=p_order and o.tenant_id=p_tenant and o.legal_entity_id=p_entity
 and core.has_permission(o.tenant_id,'procurement.orders.manage',o.legal_entity_id,o.branch_id))$$;
alter table procurement.purchase_orders enable row level security;alter table procurement.purchase_orders force row level security;
create policy order_read on procurement.purchase_orders for select to authenticated using(procurement.order_read_allowed(tenant_id,legal_entity_id,id));
do $$declare t text;begin
 foreach t in array array['purchase_order_lines','purchase_order_revisions'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  execute format('create policy order_read on procurement.%I for select to authenticated using(procurement.order_read_allowed(tenant_id,legal_entity_id,order_id))',t);
 end loop;
end $$;
create trigger order_revisions_immutable before update or delete on procurement.purchase_order_revisions
 for each row execute function workflow.reject_history_mutation();
revoke all on procurement.purchase_orders,procurement.purchase_order_lines,procurement.purchase_order_revisions from public,anon,authenticated;
grant select on procurement.purchase_orders,procurement.purchase_order_lines,procurement.purchase_order_revisions to authenticated;
revoke all on function procurement.order_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function procurement.order_read_allowed(uuid,uuid,uuid) to authenticated;
create view api.purchase_orders with(security_invoker=true) as
select o.tenant_id,o.legal_entity_id,o.branch_id,o.id,o.status,
 sales.flow_exact_json(to_jsonb(o))||jsonb_build_object('lines',coalesce((select jsonb_agg(l.detail||jsonb_build_object(
  'line_id',l.id,'source_line_id',l.source_line_id,'quantity',l.quantity::text,'unit_price',l.unit_price::text,
  'cancelled_quantity',l.cancelled_quantity::text,'received_quantity',l.received_quantity::text,
  'billed_quantity',l.billed_quantity::text,'approved_extra_quantity',l.approved_extra_quantity::text,
  'remaining_quantity',greatest(0,l.quantity-l.cancelled_quantity-l.received_quantity)::text) order by l.id)
  from procurement.purchase_order_lines l where l.order_id=o.id),'[]')) detail from procurement.purchase_orders o;
grant select on api.purchase_orders to authenticated;
create function procurement.record_order_history(p_result jsonb) returns void language sql security definer set search_path='' as $$
 insert into procurement.purchase_order_revisions(tenant_id,legal_entity_id,order_id,version,revision,snapshot,actor_id)
 select (e->>'tenant_id')::uuid,(e->>'legal_entity_id')::uuid,(e->>'id')::uuid,(e->>'version')::bigint,
 (e->>'revision')::integer,e,auth.uid() from (select p_result->'entity' e) x
 on conflict(order_id,version) do nothing
$$;
revoke all on function procurement.record_order_history(jsonb) from public,anon,authenticated;

create function api.upsert_purchase_order(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_id uuid:=(p_payload->>'id')::uuid;v_command text:='procurement.order.upsert';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.purchase_orders%rowtype;v_rfq procurement.rfqs%rowtype;v_quote procurement.supplier_quotes%rowtype;v_req procurement.requisitions%rowtype;v_source procurement.requisition_lines%rowtype;
 v_line jsonb;v_unit jsonb;v_old procurement.purchase_order_lines%rowtype;v_lines jsonb;v_snapshot jsonb;v_seen uuid[]:='{}';v_line_id uuid;
 v_supplier uuid;v_currency text;v_rate numeric;v_rate_id uuid;v_rate_date date;v_date date;v_promised date;v_warehouse uuid;
 v_q numeric;v_price numeric;v_discount numeric;v_gross numeric;v_net numeric;v_tax_amount numeric;v_tax finance.tax_definitions%rowtype;
 v_subtotal numeric:=0;v_tax_total numeric:=0;v_total numeric:=0;v_base text;v_scale integer;v_terms text;v_delivery text;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.orders.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_id is null
 or jsonb_typeof(p_payload) is distinct from 'object' then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('procurement.order:'||v_id::text,0));
 select * into v_doc from procurement.purchase_orders where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  select detail into v_before from api.purchase_orders where id=v_id;
  perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='ORDER_NOT_EDITABLE';end if;
  if (p_payload->>'source_rfq_id')::uuid is distinct from v_doc.source_rfq_id or (p_payload->>'source_quote_id')::uuid is distinct from v_doc.source_quote_id
   or (p_payload->>'source_requisition_id')::uuid is distinct from v_doc.source_requisition_id then
   raise exception using errcode='22023',message='SOURCE_IMMUTABLE';end if;
  v_lines:=p_payload->'lines';v_supplier:=(p_payload->>'supplier_id')::uuid;v_currency:=p_payload->>'currency_code';
  v_rate:=sales.wave3_decimal_string(p_payload->'exchange_rate','exchange_rate',10,true,0,null);
  v_rate_id:=(p_payload->>'exchange_rate_id')::uuid;v_rate_date:=(p_payload->>'rate_date')::date;
  v_terms:=trim(p_payload->>'payment_terms');v_delivery:=trim(p_payload->>'delivery_terms');
 else
  if p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
  if p_payload->>'source_rfq_id' is null then
   select * into v_req from procurement.requisitions where id=(p_payload->>'source_requisition_id')::uuid and tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for share;
   if not found or v_req.status<>'approved' then raise exception using errcode='55000',message='APPROVED_REQUISITION_REQUIRED';end if;
   perform core.wave3_assert_expected_version(v_req.version,(p_payload->>'source_requisition_version')::bigint,'{}');
   select detail into v_snapshot from api.purchase_requisitions where id=v_req.id;
   v_lines:=p_payload->'lines';v_supplier:=(p_payload->>'supplier_id')::uuid;v_currency:=p_payload->>'currency_code';
   v_rate:=sales.wave3_decimal_string(p_payload->'exchange_rate','exchange_rate',10,true,0,null);
   v_rate_id:=(p_payload->>'exchange_rate_id')::uuid;v_rate_date:=(p_payload->>'rate_date')::date;
   v_terms:=trim(p_payload->>'payment_terms');v_delivery:=trim(p_payload->>'delivery_terms');
  else
  select * into v_rfq from procurement.rfqs where id=(p_payload->>'source_rfq_id')::uuid and tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
  if v_rfq.status='ordered' then raise exception using errcode='55000',message='RFQ_ALREADY_ORDERED';end if;
  if v_rfq.id is null or v_rfq.status<>'selected' then raise exception using errcode='55000',message='SELECTED_RFQ_REQUIRED';end if;
  perform core.wave3_assert_expected_version(v_rfq.version,(p_payload->>'source_rfq_version')::bigint,'{}');
  select * into v_quote from procurement.supplier_quotes where id=v_rfq.selected_quote_id and rfq_id=v_rfq.id;
  if v_quote.id is distinct from (p_payload->>'source_quote_id')::uuid or not v_quote.complete or v_quote.valid_until<current_date then
   raise exception using errcode='55000',message='SELECTED_QUOTE_REQUIRED';end if;
  perform core.wave3_assert_expected_version(v_quote.version,(p_payload->>'source_quote_version')::bigint,'{}');
  select detail into v_snapshot from api.request_for_quotes where id=v_rfq.id;
  select jsonb_agg(detail||jsonb_build_object('line_id',gen_random_uuid())) into v_lines from procurement.supplier_quote_lines where quote_id=v_quote.id;
  v_supplier:=v_quote.supplier_id;v_currency:=v_quote.currency_code;v_rate:=v_quote.exchange_rate;v_rate_id:=v_quote.exchange_rate_id;
  v_rate_date:=v_quote.rate_date;v_terms:=v_quote.payment_terms;v_delivery:=v_quote.delivery_terms;
  end if;
 end if;
 v_warehouse:=(p_payload->>'warehouse_id')::uuid;v_date:=(p_payload->>'document_date')::date;v_promised:=(p_payload->>'promised_date')::date;
 if not exists(select 1 from core.warehouses where id=v_warehouse and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active') then
  raise exception using errcode='22023',message='WAREHOUSE_INVALID';end if;
 if not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
  raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if v_rate<=0 or not exists(select 1 from core.currencies where code=v_currency and active) then raise exception using errcode='22023',message='CURRENCY_INVALID';end if;
 if v_currency=v_base then
  if v_rate<>1 or v_rate_id is not null then raise exception using errcode='22023',message='BASE_RATE_MUST_BE_ONE';end if;
 elsif not exists(select 1 from finance.exchange_rates where id=v_rate_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and status='active' and source_currency_code=v_currency and target_currency_code=v_base and rate=v_rate and effective_date=v_rate_date) then
  raise exception using errcode='22023',message='RATE_SNAPSHOT_INVALID';end if;
 if v_doc.id is not null and (v_doc.supplier_id<>v_supplier or v_doc.currency_code<>v_currency or v_doc.warehouse_id<>v_warehouse)
 and exists(select 1 from procurement.purchase_order_lines where order_id=v_id and (received_quantity>0 or billed_quantity>0)) then
  raise exception using errcode='55000',message='RECEIVED_ORDER_IDENTITY_IMMUTABLE';end if;
 if jsonb_typeof(v_lines) is distinct from 'array' or jsonb_array_length(v_lines) not between 1 and 500 then
  raise exception using errcode='22023',message='ORDER_LINES_REQUIRED';end if;
 if v_doc.id is null then
  insert into procurement.purchase_orders(id,tenant_id,legal_entity_id,branch_id,supplier_id,warehouse_id,source_rfq_id,source_quote_id,source_requisition_id,
   source_snapshot,document_date,promised_date,currency_code,exchange_rate_id,exchange_rate,rate_date,payment_terms,delivery_terms,
   subtotal,tax_total,total,base_total,created_by,updated_by,commercial_editor_id)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_supplier,v_warehouse,v_rfq.id,v_quote.id,v_req.id,v_snapshot,v_date,v_promised,
   v_currency,v_rate_id,v_rate,v_rate_date,v_terms,v_delivery,0,0,0,0,auth.uid(),auth.uid(),auth.uid());
 end if;
 for v_line in select value from jsonb_array_elements(v_lines) loop
  if v_req.id is not null then
   select * into v_source from procurement.requisition_lines where requisition_id=v_req.id and id=(v_line->>'source_line_id')::uuid;
   if not found then raise exception using errcode='22023',message='REQUISITION_SOURCE_LINE_INVALID';end if;
   v_line:=v_line||jsonb_build_object('product_id',v_source.product_id,'unit_id',v_source.unit_id,'description',v_source.description,
    'conversion_numerator',v_source.conversion_numerator::text,'conversion_denominator',v_source.conversion_denominator::text);
  end if;
  v_line_id:=(v_line->>'line_id')::uuid;
  if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='ORDER_LINE_ID_INVALID';end if;
  v_seen:=array_append(v_seen,v_line_id);
  select * into v_old from procurement.purchase_order_lines where id=v_line_id and order_id=v_id for update;
  if v_doc.id is not null and not found then raise exception using errcode='22023',message='ORDER_LINE_ID_INVALID';end if;
  if v_old.id is not null and ((v_line->>'source_line_id')::uuid is distinct from v_old.source_line_id
   or (v_line->>'product_id')::uuid is distinct from v_old.product_id or (v_line->>'unit_id')::uuid is distinct from v_old.unit_id) then
   raise exception using errcode='22023',message='SOURCE_LINE_IMMUTABLE';end if;
  v_q:=sales.wave3_decimal_string(v_line->'quantity','quantity',6,true,0,null);
  v_price:=sales.wave3_decimal_string(v_line->'unit_price','unit_price',6,true,0,null);
  v_discount:=sales.wave3_decimal_string(v_line->'discount_percent','discount_percent',6,true,0,100);
  if v_q<=0 or v_q<coalesce(v_old.received_quantity,0)+coalesce(v_old.cancelled_quantity,0) or v_q<coalesce(v_old.billed_quantity,0) then
   raise exception using errcode='22023',message='ORDER_QUANTITY_INVALID';end if;
  if not exists(select 1 from inventory.units where id=(v_line->>'unit_id')::uuid and tenant_id=p_tenant_id and status='active' and round(v_q,precision)=v_q)
  or (v_line->>'product_id' is not null and not exists(select 1 from inventory.products where id=(v_line->>'product_id')::uuid
   and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and can_purchase)) then
   raise exception using errcode='22023',message='PRODUCT_UNIT_INVALID';end if;
  v_unit:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_line->>'product_id')::uuid,(v_line->>'unit_id')::uuid,
    v_line->'quantity',coalesce(v_old.detail->'conversion_numerator',v_line->'conversion_numerator'),coalesce(v_old.detail->'conversion_denominator',v_line->'conversion_denominator'));
  v_gross:=round(v_q*v_price,v_scale);v_discount:=round(v_gross*v_discount/100,v_scale);v_net:=v_gross-v_discount;v_tax_amount:=0;v_tax:=null;
  if v_line->>'tax_definition_id' is not null then
   select * into v_tax from finance.tax_definitions where id=(v_line->>'tax_definition_id')::uuid and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and status='active' and kind in('input','zero','exempt') and v_date>=valid_from and (valid_to is null or v_date<=valid_to);
   if not found then raise exception using errcode='22023',message='INPUT_TAX_INVALID';end if;
   v_tax_amount:=round(v_net*v_tax.rate/(case when v_tax.inclusive then 100+v_tax.rate else 100 end),v_scale);
   if v_tax.inclusive then v_net:=v_net-v_tax_amount;end if;
  end if;
  v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax_amount;v_total:=v_total+v_net+v_tax_amount;
  v_line:=v_line||jsonb_build_object('discount_amount',v_discount::text,'tax_rate',coalesce(v_tax.rate,0)::text,
   'tax_inclusive',coalesce(v_tax.inclusive,false),'tax_definition_version',v_tax.version,
   'net_amount',v_net::text,'tax_amount',v_tax_amount::text,'line_total',(v_net+v_tax_amount)::text)||v_unit;
  insert into procurement.purchase_order_lines(id,tenant_id,legal_entity_id,order_id,source_line_id,product_id,unit_id,description,quantity,unit_price,discount_percent,detail)
  values(v_line_id,p_tenant_id,p_legal_entity_id,v_id,(v_line->>'source_line_id')::uuid,(v_line->>'product_id')::uuid,(v_line->>'unit_id')::uuid,
   v_line->>'description',v_q,v_price,(v_line->>'discount_percent')::numeric,v_line)
  on conflict(id) do update set quantity=excluded.quantity,unit_price=excluded.unit_price,discount_percent=excluded.discount_percent,detail=excluded.detail
  where procurement.purchase_order_lines.order_id=v_id;
  if not found then raise exception using errcode='22023',message='ORDER_LINE_ID_INVALID';end if;
 end loop;
 if exists(select 1 from procurement.purchase_order_lines where order_id=v_id and not(id=any(v_seen))) then raise exception using errcode='22023',message='ORDER_LINES_MUST_BE_RETAINED';end if;
 update procurement.purchase_orders set supplier_id=v_supplier,warehouse_id=v_warehouse,document_date=v_date,promised_date=v_promised,
  currency_code=v_currency,exchange_rate_id=v_rate_id,exchange_rate=v_rate,rate_date=v_rate_date,payment_terms=v_terms,delivery_terms=v_delivery,
  subtotal=v_subtotal,tax_total=v_tax_total,total=v_total,base_total=round(v_total*v_rate,v_scale),
  version=case when v_doc.id is null then version else version+1 end,updated_at=clock_timestamp(),updated_by=auth.uid(),commercial_editor_id=auth.uid() where id=v_id;
 if v_doc.id is null and v_rfq.id is not null then
  update procurement.rfqs set status='ordered',version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_rfq.id;
  insert into procurement.rfq_history(tenant_id,legal_entity_id,rfq_id,version,snapshot,actor_id)
  select tenant_id,legal_entity_id,id,(detail->>'version')::bigint,detail,auth.uid() from api.request_for_quotes where id=v_rfq.id;
 end if;
 select detail into v_entity from api.purchase_orders where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_order',v_id,p_idempotency_key,v_hash,v_before,v_entity,
  p_legal_entity_id,p_branch_id,'{}',null,jsonb_build_array(jsonb_build_object('topic','procurement.order.saved','payload','{}'::jsonb)));
 perform procurement.record_order_history(v_result);return v_result;
end $$;
revoke all on function api.upsert_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.transition_purchase_order(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_actor uuid:=auth.uid();v_id uuid;v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';
 v_command text:='procurement.order.transition';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.purchase_orders%rowtype;v_workflow workflow.workflow_definitions%rowtype;
 v_ar workflow.approval_requests%rowtype;v_snapshot jsonb;v_step jsonb;v_first integer;v_to text;
 v_request uuid:=gen_random_uuid();v_reason text:=nullif(trim(coalesce(p_payload->>'reason',p_payload->>'note')),'');
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.orders.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or jsonb_typeof(p_payload) is distinct from 'object' or (v_action is null)=(v_decision is null) then
 raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_decision is not null then
  perform core.require_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 end if;
 v_id:=(p_payload->>'document_id')::uuid;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 select * into v_doc from procurement.purchase_orders where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select detail into v_before from api.purchase_orders where id=v_id;
 perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
 v_snapshot:=v_doc.workflow_snapshot;
 if v_action='submit' then
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='ORDER_NOT_EDITABLE';end if;
  if not exists(select 1 from crm.parties where id=v_doc.supplier_id and tenant_id=p_tenant_id and status='active' and kind in('supplier','both'))
  or not exists(select 1 from core.warehouses where id=v_doc.warehouse_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active')
  or exists(select 1 from procurement.purchase_order_lines l left join inventory.units u on u.id=l.unit_id and u.tenant_id=l.tenant_id
    left join inventory.products p on p.id=l.product_id and p.tenant_id=l.tenant_id and p.legal_entity_id=l.legal_entity_id
    where l.order_id=v_id and (u.status is distinct from 'active' or round(l.quantity,u.precision)<>l.quantity
    or (l.product_id is not null and (p.status is distinct from 'active' or not p.can_purchase)))) then
   raise exception using errcode='22023',message='REFERENCE_INVALID';end if;
  perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,l.product_id,l.unit_id,to_jsonb(l.quantity::text),
   l.detail->'conversion_numerator',l.detail->'conversion_denominator') from procurement.purchase_order_lines l where l.order_id=v_id;
  select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id
   and document_type='purchase_order' and status='active' and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
   order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
   'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
   from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
   and (s.currency_code is null or s.currency_code=v_doc.currency_code)
   and (s.minimum_amount is null or s.minimum_amount<=v_doc.total)
   and (s.maximum_amount is null or s.maximum_amount>=v_doc.total);
  select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
  if v_first is null and v_workflow.lifecycle->'requires_approval' is distinct from 'false'::jsonb then
   raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
  v_to:=case when v_first is null then 'approved' else 'pending_approval' end;
  if v_first is null then perform sales.flow_assert_transition(v_workflow.lifecycle,'submitted','approved');end if;
  v_doc.document_number:=coalesce(v_doc.document_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,
    p_branch_id,'purchase_order',v_doc.document_date,v_actor));
  if v_first is not null then
   insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
    submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,'purchase_order',v_id,'submitted',v_actor,
    v_workflow.id,v_workflow.revision,v_first,v_doc.total,v_doc.currency_code,p_command_id,v_request,v_request);
  end if;
 elsif v_decision is not null then
  if v_doc.status<>'pending_approval' or v_decision not in ('approved','rejected') then
   raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
  select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type='purchase_order'
   and document_id=v_id and status='submitted' for update;
  if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
  if v_actor in(v_doc.created_by,v_doc.commercial_editor_id,v_doc.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
  if v_step is null or not exists(select 1 from core.memberships m
   join core.role_assignments ra on ra.membership_id=m.id and ra.tenant_id=m.tenant_id
   join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
   where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
   and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
   and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then
   raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
  if v_decision='rejected' and v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
  insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
   approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
  values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
   v_actor,v_decision,v_reason,v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
  if v_decision='approved' then
   select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
    where (x->>'step_order')::integer>v_ar.current_step;
  end if;
  v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
  update workflow.approval_requests set current_step=coalesce(v_first,current_step),
   status=case when v_first is null then v_to else status end,
   decision_by=case when v_first is null then v_actor else decision_by end,
   decision_note=case when v_first is null then v_reason else decision_note end,
   decided_at=case when v_first is null then clock_timestamp() else decided_at end where id=v_ar.id;
 elsif v_action='revise' then
  if v_doc.status<>'approved' then raise exception using errcode='55000',message='APPROVED_ORDER_REQUIRED';end if;
  if v_reason is null or length(v_reason)>1000 then raise exception using errcode='22023',message='REVISION_REASON_REQUIRED';end if;
  v_to:='draft';v_snapshot:=null;
  update procurement.purchase_orders set revision=revision+1,revision_reason=v_reason,commercial_editor_id=v_actor where id=v_id;
 elsif v_action in('recall','cancel') then
  if v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  if v_action='recall' and v_doc.status not in('pending_approval','rejected') then
   raise exception using errcode='55000',message='ORDER_NOT_RECALLABLE';end if;
  if v_snapshot is null then
   select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
    where tenant_id=p_tenant_id and document_type='purchase_order' and status='active'
    and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
    order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  end if;
  v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc.status,v_to);
  update workflow.approval_requests set status='cancelled',decision_by=v_actor,decision_note=v_reason,decided_at=clock_timestamp()
   where tenant_id=p_tenant_id and document_type='purchase_order' and document_id=v_id and status='submitted';
  if v_action='recall' then v_snapshot:=null;end if;
  if v_action='cancel' then
   update procurement.purchase_order_lines set cancelled_quantity=greatest(0,quantity-greatest(received_quantity,billed_quantity)) where order_id=v_id;
  end if;
 else raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 update procurement.purchase_orders set status=v_to,version=version+1,updated_at=clock_timestamp(),updated_by=v_actor,
  workflow_snapshot=v_snapshot,document_number=v_doc.document_number,
  submitted_by=case when v_action='submit' then v_actor else submitted_by end,
  submitted_at=case when v_action='submit' then clock_timestamp() else submitted_at end where id=v_id;
 select detail into v_entity from api.purchase_orders where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_order',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_doc.status=v_to then null else jsonb_build_object('from_status',v_doc.status,'to_status',v_to,'reason',v_reason) end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
 perform procurement.record_order_history(v_result);return v_result;
end $$;
revoke all on function api.transition_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.transition_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- Reference indexes remain module-owned.
do $$declare c record;begin
 for c in select con.conrelid::regclass tbl,con.conname,
  (select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(con.conkey) with ordinality k(att,n)
   join pg_attribute a on a.attrelid=con.conrelid and a.attnum=k.att) cols
  from pg_constraint con join pg_class t on t.oid=con.conrelid join pg_namespace n on n.oid=t.relnamespace
  where con.contype='f' and n.nspname='procurement' and t.relname in('purchase_orders','purchase_order_lines','purchase_order_revisions')
 loop execute format('create index %I on %s(%s)',c.conname||'_idx',c.tbl,c.cols);end loop;
end $$;


-- AC-310 candidate. Reuses established inventory and journal tables; no business seed data.
create table procurement.receipt_controls(
 tenant_id uuid not null,legal_entity_id uuid primary key,grni_account_id uuid not null,expense_account_id uuid not null,
 maximum_over_receipt_percent numeric(9,6) not null default 0 check(maximum_over_receipt_percent between 0 and 100),
 version bigint not null default 1,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,grni_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,expense_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
create table procurement.receipt_control_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,version bigint not null,
 snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(legal_entity_id,version),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table procurement.goods_receipts(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,order_id uuid not null,
 order_revision integer not null,warehouse_id uuid not null,document_date date not null,document_number text not null,
 reference text not null,source_snapshot jsonb not null,currency_code text not null,base_currency_code text not null,
 exchange_rate numeric(20,10) not null,net_amount numeric(20,6) not null,base_amount numeric(20,6) not null,
 stock_movement_id uuid,journal_entry_id uuid,request_id uuid not null,command_id uuid not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id)
);
create table procurement.receipt_allowances(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 order_id uuid not null,order_line_id uuid not null,order_version bigint not null,
 maximum_received_quantity numeric(20,6) not null,control_version bigint not null,reason text not null,
 approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(order_line_id,order_version),
 foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,order_line_id) references procurement.purchase_order_lines(tenant_id,legal_entity_id,id)
);
alter table procurement.receipt_allowances enable row level security;
alter table procurement.receipt_allowances force row level security;
create policy allowance_read on procurement.receipt_allowances for select to authenticated using(
 core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,'procurement.receipts.post',legal_entity_id,branch_id));
create trigger allowance_immutable before update or delete on procurement.receipt_allowances
 for each row execute function workflow.reject_history_mutation();
revoke all on procurement.receipt_allowances from public,anon,authenticated;
grant select on procurement.receipt_allowances to authenticated;
create index receipt_allowances_order on procurement.receipt_allowances(tenant_id,legal_entity_id,order_id,order_version);
create function api.approve_receipt_allowance(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='procurement.receipt_allowance.approve';v_hash text;v_result jsonb;v_po procurement.purchase_orders%rowtype;
 v_l procurement.purchase_order_lines%rowtype;v_c procurement.receipt_controls%rowtype;v_extra numeric;v_max numeric;v_id uuid:=(p_payload->>'id')::uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 if v_id is null or p_client_timestamp is null or coalesce(length(trim(p_payload->>'reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='ALLOWANCE_REASON_REQUIRED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_po from procurement.purchase_orders where id=(p_payload->>'order_id')::uuid and tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='ORDER_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version(v_po.version,p_expected_entity_version,to_jsonb(v_po));
 if v_po.status<>'approved' then raise exception using errcode='55000',message='APPROVED_ORDER_REQUIRED';end if;
 if auth.uid() in(v_po.created_by,v_po.commercial_editor_id,v_po.submitted_by) then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 select * into v_l from procurement.purchase_order_lines where id=(p_payload->>'order_line_id')::uuid and order_id=v_po.id for update;
 if not found then raise exception using errcode='22023',message='RECEIPT_SOURCE_INVALID';end if;
 select * into v_c from procurement.receipt_controls where legal_entity_id=p_legal_entity_id and tenant_id=p_tenant_id for share;
 if not found then raise exception using errcode='55000',message='RECEIPT_CONTROLS_REQUIRED';end if;
 v_extra:=sales.wave3_decimal_string(p_payload->'extra_quantity','extra_quantity',6,true,0,null);
 v_max:=v_l.quantity-v_l.cancelled_quantity+v_extra;
 if v_extra<=0 or v_c.maximum_over_receipt_percent<=0 or v_extra>v_l.quantity*v_c.maximum_over_receipt_percent/100
  or v_max<=v_l.received_quantity then raise exception using errcode='22023',message='ALLOWANCE_EXCEEDS_CONTROL';end if;
 insert into procurement.receipt_allowances(id,tenant_id,legal_entity_id,branch_id,order_id,order_line_id,order_version,maximum_received_quantity,control_version,reason,approved_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_po.id,v_l.id,v_po.version,v_max,v_c.version,trim(p_payload->>'reason'),auth.uid());
 select sales.flow_exact_json(to_jsonb(a)) into v_result from procurement.receipt_allowances a where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'receipt_allowance',v_id,p_idempotency_key,v_hash,null,v_result,p_legal_entity_id,p_branch_id,
  jsonb_build_object('purchase_order_id',v_po.id),null,jsonb_build_array(jsonb_build_object('topic','procurement.receipt.allowance','payload',jsonb_build_object('order_id',v_po.id))));
end $$;
revoke all on function api.approve_receipt_allowance(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.approve_receipt_allowance(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
create table procurement.goods_receipt_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,receipt_id uuid not null,
 order_line_id uuid not null,accepted_quantity numeric(20,6) not null,rejected_quantity numeric(20,6) not null,
 base_quantity numeric(20,6) not null,net_amount numeric(20,6) not null,base_amount numeric(20,6) not null,
 detail jsonb not null,unique(tenant_id,id),unique(receipt_id,order_line_id),
 foreign key(tenant_id,receipt_id) references procurement.goods_receipts(tenant_id,id) deferrable initially deferred,
 foreign key(tenant_id,legal_entity_id,order_line_id) references procurement.purchase_order_lines(tenant_id,legal_entity_id,id),
 check(accepted_quantity>=0 and rejected_quantity>=0 and accepted_quantity+rejected_quantity>0 and base_quantity>=0)
);
create table procurement.goods_receipt_reversals(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,receipt_id uuid not null unique,
 document_date date not null,reason text not null,stock_movement_id uuid,journal_entry_id uuid,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 foreign key(tenant_id,receipt_id) references procurement.goods_receipts(tenant_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id)
);
create index goods_receipts_scope_page on procurement.goods_receipts(tenant_id,legal_entity_id,branch_id,id);
create index goods_receipts_order on procurement.goods_receipts(tenant_id,legal_entity_id,order_id,order_revision,id);
create index goods_receipt_source_line on procurement.goods_receipt_lines(tenant_id,legal_entity_id,order_line_id,receipt_id);
create index receipt_reversals_scope on procurement.goods_receipt_reversals(tenant_id,legal_entity_id,branch_id,id);
create index receipt_control_grni_fk on procurement.receipt_controls(tenant_id,legal_entity_id,grni_account_id);
create index receipt_control_expense_fk on procurement.receipt_controls(tenant_id,legal_entity_id,expense_account_id);
do $$declare t text;begin
 foreach t in array array['goods_receipts','goods_receipt_lines','goods_receipt_reversals','receipt_control_history'] loop
  execute format('create trigger immutable_receipt before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);
 end loop;
 foreach t in array array['goods_receipts','goods_receipt_lines','goods_receipt_reversals','receipt_controls','receipt_control_history'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  if t in('receipt_controls','receipt_control_history') then
   execute format('create policy receipt_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and (core.has_permission(tenant_id,''finance.setup.manage'',legal_entity_id,null) or core.has_permission(tenant_id,''procurement.receipts.post'',legal_entity_id,null)))',t);
  else
   execute format('create policy receipt_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,''procurement.receipts.post'',legal_entity_id,branch_id))',t);
  end if;
  execute format('revoke all on procurement.%I from public,anon,authenticated',t);
  execute format('grant select on procurement.%I to authenticated',t);
 end loop;
end $$;
create view api.goods_receipts with(security_invoker=true) as select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,
 sales.flow_exact_json(to_jsonb(r))||jsonb_build_object('status',case when x.id is null then 'posted' else 'reversed' end,
 'version',case when x.id is null then 1 else 2 end,'reversal',sales.flow_exact_json(to_jsonb(x)),
 'lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.goods_receipt_lines l where l.receipt_id=r.id),'[]')) detail
 from procurement.goods_receipts r left join procurement.goods_receipt_reversals x on x.receipt_id=r.id;
grant select on api.goods_receipts to authenticated;
-- Additive constraint expansion preserves all existing permitted movement kinds.
alter table inventory.stock_movements drop constraint stock_movements_movement_kind_check;
alter table inventory.stock_movements add constraint stock_movements_movement_kind_check
 check(movement_kind in('opening','delivery','sales_return','goods_receipt','goods_receipt_reversal'));

create function api.upsert_receipt_controls(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='procurement.receipt_controls.upsert';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;v_base text;
 v_old procurement.receipt_controls%rowtype;v_grni uuid:=(p_payload->>'grni_account_id')::uuid;v_expense uuid:=(p_payload->>'expense_account_id')::uuid;v_percent numeric;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 if p_client_timestamp is null or (p_payload->>'id')::uuid is distinct from p_legal_entity_id then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('receipt.controls:'||p_legal_entity_id::text,0));
 select * into v_old from procurement.receipt_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
 if found then perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,to_jsonb(v_old));
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 v_before:=to_jsonb(v_old);
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_grni,'liability',v_base);
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_expense,'expense',v_base);
 v_percent:=sales.wave3_decimal_string(coalesce(p_payload->'maximum_over_receipt_percent','"0"'),'maximum_over_receipt_percent',6,true,0,100);
 insert into procurement.receipt_controls(tenant_id,legal_entity_id,grni_account_id,expense_account_id,maximum_over_receipt_percent,updated_by)
 values(p_tenant_id,p_legal_entity_id,v_grni,v_expense,v_percent,auth.uid()) on conflict(legal_entity_id) do update set
 grni_account_id=excluded.grni_account_id,expense_account_id=excluded.expense_account_id,maximum_over_receipt_percent=excluded.maximum_over_receipt_percent,version=procurement.receipt_controls.version+1,updated_by=auth.uid(),updated_at=clock_timestamp();
 select sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id) into v_entity from procurement.receipt_controls c where legal_entity_id=p_legal_entity_id;
 insert into procurement.receipt_control_history(tenant_id,legal_entity_id,version,snapshot,actor_id)
 values(p_tenant_id,p_legal_entity_id,(v_entity->>'version')::bigint,v_entity,auth.uid());
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'receipt_controls',p_legal_entity_id,p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id);
end $$;

create function api.post_goods_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_request uuid:=gen_random_uuid();v_command text:='procurement.goods_receipt.post';
 v_hash text;v_result jsonb;v_po procurement.purchase_orders%rowtype;v_ol procurement.purchase_order_lines%rowtype;
 v_controls procurement.receipt_controls%rowtype;v_product inventory.products%rowtype;v_balance inventory.stock_balances%rowtype;
 v_input jsonb;v_lines jsonb;v_detail jsonb;v_source jsonb;v_jlines jsonb:='[]';v_seen uuid[]:='{}';v_line_id uuid;
 v_q numeric;v_reject numeric;v_base_q numeric;v_prior numeric;v_amount numeric;v_base_amount numeric;v_total numeric:=0;v_base_total numeric:=0;
 v_scale integer;v_base text;v_date date:=(p_payload->>'document_date')::date;v_warehouse uuid:=(p_payload->>'warehouse_id')::uuid;
 v_movement uuid;v_journal uuid;v_account uuid;v_lot uuid;v_serial uuid;v_serials uuid[];v_code text;v_product_id uuid;
 v_num numeric;v_den numeric;v_precision integer;v_ref text:=trim(p_payload->>'reference');
 v_allowance procurement.receipt_allowances%rowtype;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 if v_id is null or p_client_timestamp is null or p_legal_entity_id is null or p_branch_id is null or v_date is null
 or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500
 or coalesce(length(v_ref),0) not between 1 and 140 then raise exception using errcode='22023',message='INVALID_RECEIPT';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_po from procurement.purchase_orders where id=(p_payload->>'order_id')::uuid and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='ORDER_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version(v_po.version,p_expected_entity_version,to_jsonb(v_po));
 if v_po.status<>'approved' then raise exception using errcode='55000',message='APPROVED_ORDER_REQUIRED';end if;
 if v_warehouse is distinct from v_po.warehouse_id or not exists(select 1 from core.warehouses where id=v_warehouse and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active') then raise exception using errcode='22023',message='RECEIVING_WAREHOUSE_INVALID';end if;
 if v_date<v_po.document_date then raise exception using errcode='22023',message='RECEIPT_DATE_INVALID';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 select * into v_controls from procurement.receipt_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for share;
 if not found then raise exception using errcode='55000',message='RECEIPT_CONTROLS_REQUIRED';end if;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_controls.grni_account_id,'liability',v_po.currency_code);
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 select detail into v_source from api.purchase_orders where id=v_po.id;
 v_source:=v_source||jsonb_build_object('_prior_negative_quantities','{}'::jsonb);
 -- Lock all source lines, then all stock keys in deterministic order before mutation.
 perform 1 from procurement.purchase_order_lines where order_id=v_po.id order by id for update;
 for v_product_id in select distinct l.product_id from procurement.purchase_order_lines l
 join jsonb_array_elements(p_payload->'lines') x on (x->>'order_line_id')::uuid=l.id
 where l.order_id=v_po.id and l.product_id is not null order by 1 loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||v_warehouse::text||':'||v_product_id::text,0));
 end loop;
 for v_input in select value from jsonb_array_elements(p_payload->'lines') order by value->>'order_line_id' loop
  v_line_id:=(v_input->>'line_id')::uuid;
  if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='RECEIPT_LINE_ID_INVALID';end if;
  v_seen:=array_append(v_seen,v_line_id);
  select * into v_ol from procurement.purchase_order_lines where id=(v_input->>'order_line_id')::uuid and order_id=v_po.id;
  if not found then raise exception using errcode='22023',message='RECEIPT_SOURCE_INVALID';end if;
  v_q:=sales.wave3_decimal_string(v_input->'accepted_quantity','accepted_quantity',6,true,0,null);
  v_reject:=sales.wave3_decimal_string(v_input->'rejected_quantity','rejected_quantity',6,true,0,null);
  if v_q+v_reject<=0 then raise exception using errcode='22023',message='RECEIPT_QUANTITY_REQUIRED';end if;
  v_allowance:=null;
  if v_q>greatest(0,v_ol.quantity-v_ol.cancelled_quantity-v_ol.received_quantity) then
   select * into v_allowance from procurement.receipt_allowances where order_line_id=v_ol.id and order_version=v_po.version
    and control_version=v_controls.version and approved_by<>auth.uid()
    and maximum_received_quantity>=v_ol.received_quantity+v_q;
   if not found then raise exception using errcode='22023',message='RECEIPT_EXCEEDS_REMAINING';end if;
  end if;
  if v_reject>0 and coalesce(length(trim(v_input->>'rejection_reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='REJECTION_REASON_REQUIRED';end if;
  select precision into v_precision from inventory.units where id=v_ol.unit_id and tenant_id=p_tenant_id and status='active';
  if not found or round(v_q,v_precision)<>v_q or round(v_reject,v_precision)<>v_reject then raise exception using errcode='22023',message='RECEIPT_UNIT_PRECISION_INVALID';end if;
  v_num:=(v_ol.detail->>'conversion_numerator')::numeric;v_den:=(v_ol.detail->>'conversion_denominator')::numeric;
  if v_num is null or v_den is null or v_num<=0 or v_den<=0 or mod(v_q*1000000*v_num,v_den)<>0 then raise exception using errcode='22023',message='BASE_QUANTITY_PRECISION_INVALID';end if;
  v_base_q:=v_q*v_num/v_den;v_product:=null;v_lot:=null;v_serials:='{}';
  if v_ol.product_id is not null then
   select * into v_product from inventory.products where id=v_ol.product_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and can_purchase for share;
   if not found or v_product.base_unit_id is distinct from (v_ol.detail->>'base_unit_id')::uuid then raise exception using errcode='22023',message='RECEIPT_PRODUCT_INVALID';end if;
   select precision into v_precision from inventory.units where id=v_product.base_unit_id and tenant_id=p_tenant_id and status='active';
   if not found or round(v_base_q,v_precision)<>v_base_q then raise exception using errcode='22023',message='BASE_QUANTITY_PRECISION_INVALID';end if;
  end if;
  -- EC-320: keep the historical ratio, but never accept a changed/inactive master
  -- as implicit approval for a new stock quantity.
  if v_q>0 then
   perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,v_ol.product_id,v_ol.unit_id,
    v_input->'accepted_quantity',v_ol.detail->'conversion_numerator',v_ol.detail->'conversion_denominator');
  end if;
  select coalesce(sum(l.accepted_quantity),0) into v_prior from procurement.goods_receipt_lines l join procurement.goods_receipts r on r.id=l.receipt_id
   where l.order_line_id=v_ol.id and r.order_revision=v_po.revision and not exists(select 1 from procurement.goods_receipt_reversals x where x.receipt_id=r.id);
  v_amount:=round((v_ol.detail->>'net_amount')::numeric*(v_prior+v_q)/v_ol.quantity,v_scale)-round((v_ol.detail->>'net_amount')::numeric*v_prior/v_ol.quantity,v_scale);
  v_base_amount:=round(round((v_ol.detail->>'net_amount')::numeric*(v_prior+v_q)/v_ol.quantity,v_scale)*v_po.exchange_rate,v_scale)
    -round(round((v_ol.detail->>'net_amount')::numeric*v_prior/v_ol.quantity,v_scale)*v_po.exchange_rate,v_scale);
  v_account:=case when v_product.kind='stocked' then finance.flow_account(p_tenant_id,p_legal_entity_id,v_product.inventory_account_id,'asset',v_po.currency_code)
   else finance.flow_account(p_tenant_id,p_legal_entity_id,coalesce(v_product.expense_account_id,v_controls.expense_account_id),'expense',v_po.currency_code) end;
  if jsonb_typeof(coalesce(v_input->'serial_codes','[]'))<>'array' or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))>1000 then raise exception using errcode='22023',message='SERIAL_LIST_INVALID';end if;
  if v_q>0 and v_product.kind='stocked' then
   -- Match delivery lock order: balance then valuation, before lot/serial rows.
   insert into inventory.stock_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,on_hand_quantity,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,0,auth.uid(),auth.uid())
   on conflict(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id) do nothing;
   select * into v_balance from inventory.stock_balances where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and branch_id=p_branch_id and warehouse_id=v_warehouse and product_id=v_product.id for update;
   insert into inventory.stock_valuations(tenant_id,legal_entity_id,branch_id,stock_balance_id,carrying_value,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_balance.id,0,auth.uid(),auth.uid()) on conflict(tenant_id,stock_balance_id) do nothing;
   perform 1 from inventory.stock_valuations where stock_balance_id=v_balance.id for update;
   if exists(select 1 from inventory.stock_movement_lines where tenant_id=p_tenant_id and warehouse_id=v_warehouse
    and product_id=v_product.id and posting_date>v_date) then raise exception using errcode='55000',message='BACKDATED_STOCK_RECEIPT_REQUIRES_REVIEW';end if;
   -- Immutable negative movement totals distinguish later consumption without
   -- relying on transaction-start timestamps or retaining an unbounded ID list.
   v_source:=jsonb_set(v_source,array['_prior_negative_quantities',v_product.id::text],
    to_jsonb((select coalesce(sum(-base_quantity),0)::text from inventory.stock_movement_lines
     where tenant_id=p_tenant_id and warehouse_id=v_warehouse and product_id=v_product.id and base_quantity<0)));
   if v_product.tracking_mode='lot' then
    if coalesce(length(trim(v_input->>'lot_code')),0) not between 1 and 100 or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))<>0
     or (v_input->>'expiry_date')::date<v_date then raise exception using errcode='22023',message='LOT_IDENTITY_INVALID';end if;
    insert into inventory.lots(tenant_id,legal_entity_id,product_id,code,manufacture_date,expiry_date,created_by,updated_by)
    values(p_tenant_id,p_legal_entity_id,v_product.id,trim(v_input->>'lot_code'),(v_input->>'manufacture_date')::date,(v_input->>'expiry_date')::date,auth.uid(),auth.uid())
    on conflict(tenant_id,product_id,code) do nothing;
    select id into v_lot from inventory.lots where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and product_id=v_product.id
     and code=trim(v_input->>'lot_code') and status='saleable' and manufacture_date is not distinct from (v_input->>'manufacture_date')::date
     and expiry_date is not distinct from (v_input->>'expiry_date')::date for update;
    if not found then raise exception using errcode='22023',message='LOT_METADATA_CONFLICT';end if;
    insert into inventory.lot_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,lot_id,on_hand_quantity,created_by,updated_by)
    values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,v_lot,v_base_q,auth.uid(),auth.uid())
    on conflict(tenant_id,warehouse_id,lot_id) do update set on_hand_quantity=inventory.lot_balances.on_hand_quantity+excluded.on_hand_quantity,updated_by=auth.uid();
   elsif v_product.tracking_mode='serial' then
    if v_input->>'lot_code' is not null or trunc(v_base_q)<>v_base_q or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))<>v_base_q then raise exception using errcode='22023',message='SERIAL_COUNT_INVALID';end if;
    for v_code in select value#>>'{}' from jsonb_array_elements(v_input->'serial_codes') where jsonb_typeof(value)='string' order by 1 loop
     if length(trim(v_code)) not between 1 and 100 or v_code<>trim(v_code) then raise exception using errcode='22023',message='SERIAL_IDENTITY_INVALID';end if;
     insert into inventory.serials(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,code,created_by,updated_by)
     values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,v_code,auth.uid(),auth.uid()) returning id into v_serial;
     v_serials:=array_append(v_serials,v_serial);
    end loop;
    if cardinality(v_serials)<>v_base_q then raise exception using errcode='22023',message='SERIAL_IDENTITY_INVALID';end if;
   elsif v_input->>'lot_code' is not null or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))<>0 then raise exception using errcode='22023',message='TRACKING_NOT_ALLOWED';end if;
   if v_movement is null then
    v_movement:=gen_random_uuid();
    insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
    values(v_movement,p_tenant_id,p_legal_entity_id,p_branch_id,'goods_receipt',v_id,v_warehouse,v_date,'goods_receipt',v_request,p_command_id,v_request,auth.uid());
   end if;
   insert into inventory.stock_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,on_hand_quantity,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,v_base_q,auth.uid(),auth.uid())
   on conflict(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id) do update set on_hand_quantity=inventory.stock_balances.on_hand_quantity+excluded.on_hand_quantity,updated_by=auth.uid() returning * into v_balance;
   insert into inventory.stock_valuations(tenant_id,legal_entity_id,branch_id,stock_balance_id,carrying_value,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_balance.id,v_base_amount,auth.uid(),auth.uid())
   on conflict(tenant_id,stock_balance_id) do update set carrying_value=inventory.stock_valuations.carrying_value+excluded.carrying_value,updated_by=auth.uid();
   insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_movement,v_warehouse,v_product.id,v_line_id,v_base_q,v_base_amount,v_lot,v_serials,v_date,auth.uid());
  end if;
  v_detail:=jsonb_build_object('line_id',v_line_id,'order_line_id',v_ol.id,'product_id',v_ol.product_id,'description',v_ol.description,
   'unit_id',v_ol.unit_id,'conversion_numerator',v_num::text,'conversion_denominator',v_den::text,
   'accepted_quantity',v_q::text,'rejected_quantity',v_reject::text,'rejection_reason',v_input->>'rejection_reason',
   'base_quantity',v_base_q::text,'net_amount',v_amount::text,'base_amount',v_base_amount::text,'account_id',v_account,
   'lot_id',v_lot,'lot_code',v_input->>'lot_code','serial_ids',to_jsonb(v_serials),'serial_codes',coalesce(v_input->'serial_codes','[]'),'source_snapshot',v_ol.detail,
   'allowance',sales.flow_exact_json(to_jsonb(v_allowance)));
  insert into procurement.goods_receipt_lines(id,tenant_id,legal_entity_id,branch_id,receipt_id,order_line_id,accepted_quantity,rejected_quantity,base_quantity,net_amount,base_amount,detail)
  values(v_line_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_ol.id,v_q,v_reject,v_base_q,v_amount,v_base_amount,v_detail);
  update procurement.purchase_order_lines set received_quantity=received_quantity+v_q,
   approved_extra_quantity=greatest(approved_extra_quantity,received_quantity+v_q+cancelled_quantity-quantity) where id=v_ol.id;
  if v_amount<>0 or v_base_amount<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_account,v_amount,v_base_amount,v_line_id));end if;
  v_total:=v_total+v_amount;v_base_total:=v_base_total+v_base_amount;
 end loop;
 if v_total<>0 or v_base_total<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_controls.grni_account_id,-v_total,-v_base_total));end if;
 v_journal:=finance.flow_post_journal(jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'document_date',v_date,'currency_code',v_po.currency_code,'base_currency_code',v_base,'exchange_rate',v_po.exchange_rate::text,'customer_id',v_po.supplier_id),v_jlines,'goods_receipt',v_id,v_request,p_command_id);
 insert into procurement.goods_receipts(id,tenant_id,legal_entity_id,branch_id,order_id,order_revision,warehouse_id,document_date,document_number,reference,
  source_snapshot,currency_code,base_currency_code,exchange_rate,net_amount,base_amount,stock_movement_id,journal_entry_id,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_po.id,v_po.revision,v_warehouse,v_date,
  sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'goods_receipt',v_date,auth.uid()),v_ref,v_source,v_po.currency_code,v_base,v_po.exchange_rate,v_total,v_base_total,v_movement,v_journal,v_request,p_command_id,auth.uid());
 update procurement.purchase_orders set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_po.id;
 perform procurement.record_order_history(jsonb_build_object('entity',(select detail from api.purchase_orders where id=v_po.id)));
 select detail into v_result from api.goods_receipts where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'goods_receipt',v_id,p_idempotency_key,v_hash,null,v_result,p_legal_entity_id,p_branch_id,
  jsonb_build_object('purchase_order_id',v_po.id),jsonb_build_object('from_status','draft','to_status','posted'),
  jsonb_build_array(jsonb_build_object('topic','procurement.receipt.posted','payload',jsonb_build_object('receipt_id',v_id))),'[]',v_request,v_request);
end $$;

create function api.reverse_goods_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;v_reverse uuid:=gen_random_uuid();v_request uuid:=gen_random_uuid();
 v_command text:='procurement.goods_receipt.reverse';v_hash text;v_result jsonb;v_before jsonb;v_r procurement.goods_receipts%rowtype;
 v_po procurement.purchase_orders%rowtype;v_line procurement.goods_receipt_lines%rowtype;v_m inventory.stock_movement_lines%rowtype;
 v_balance inventory.stock_balances%rowtype;v_value inventory.stock_valuations%rowtype;v_movement uuid;v_journal uuid;v_jlines jsonb:='[]';
 v_date date:=(p_payload->>'document_date')::date;v_reason text:=trim(p_payload->>'reason');v_product uuid;v_serial uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 if p_client_timestamp is null or v_id is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000 then raise exception using errcode='22023',message='REVERSAL_REASON_DATE_REQUIRED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_r from procurement.goods_receipts where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id;
 if not found then raise exception using errcode='P0002',message='RECEIPT_NOT_FOUND';end if;
 -- Same aggregate lock order as posting; a receipt row is immutable.
 select * into v_po from procurement.purchase_orders where id=v_r.order_id for update;
 select detail into v_before from api.goods_receipts where id=v_id;
 perform core.wave3_assert_expected_version((v_before->>'version')::bigint,p_expected_entity_version,v_before);
 if v_before->>'status'<>'posted' then raise exception using errcode='55000',message='RECEIPT_ALREADY_REVERSED';end if;
 if v_date<v_r.document_date then raise exception using errcode='22023',message='REVERSAL_DATE_INVALID';end if;
 perform 1 from procurement.purchase_order_lines where order_id=v_po.id order by id for update;
 if exists(select 1 from procurement.purchase_order_lines l join procurement.goods_receipt_lines r on r.order_line_id=l.id where r.receipt_id=v_id and l.billed_quantity>0)
 then raise exception using errcode='55000',message='BILLED_RECEIPT_REQUIRES_RETURN';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 for v_product in select distinct product_id from inventory.stock_movement_lines where stock_movement_id=v_r.stock_movement_id order by 1 loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||v_r.warehouse_id::text||':'||v_product::text,0));
 end loop;
 for v_m in select * from inventory.stock_movement_lines where stock_movement_id=v_r.stock_movement_id order by product_id,id loop
  select * into v_balance from inventory.stock_balances where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and warehouse_id=v_r.warehouse_id and product_id=v_m.product_id for update;
  select * into v_value from inventory.stock_valuations where stock_balance_id=v_balance.id for update;
  if v_balance.id is null or v_value.id is null or v_balance.on_hand_quantity-v_balance.allocated_quantity<v_m.base_quantity
   or v_value.carrying_value<v_m.base_value or (v_balance.on_hand_quantity=v_m.base_quantity and v_value.carrying_value<>v_m.base_value)
   or (select coalesce(sum(-base_quantity),0) from inventory.stock_movement_lines
      where tenant_id=p_tenant_id and warehouse_id=v_r.warehouse_id and product_id=v_m.product_id and base_quantity<0
       and (v_movement is null or stock_movement_id<>v_movement))
     is distinct from (v_r.source_snapshot#>>array['_prior_negative_quantities',v_m.product_id::text])::numeric
  then raise exception using errcode='55000',message='CONSUMED_RECEIPT_REQUIRES_RETURN';end if;
  if v_m.lot_id is not null then
   update inventory.lot_balances set on_hand_quantity=on_hand_quantity-v_m.base_quantity,updated_by=auth.uid()
   where tenant_id=p_tenant_id and warehouse_id=v_r.warehouse_id and lot_id=v_m.lot_id and on_hand_quantity>=v_m.base_quantity;
   if not found then raise exception using errcode='55000',message='RECEIPT_LOT_UNAVAILABLE';end if;
  end if;
  foreach v_serial in array v_m.serial_ids loop
   update inventory.serials set status='disposed',updated_by=auth.uid() where id=v_serial and tenant_id=p_tenant_id
    and warehouse_id=v_r.warehouse_id and status='available';
   if not found then raise exception using errcode='55000',message='RECEIPT_SERIAL_UNAVAILABLE';end if;
  end loop;
  update inventory.stock_balances set on_hand_quantity=on_hand_quantity-v_m.base_quantity,updated_by=auth.uid() where id=v_balance.id;
  update inventory.stock_valuations set carrying_value=carrying_value-v_m.base_value,updated_by=auth.uid() where id=v_value.id;
  if v_movement is null then
   v_movement:=gen_random_uuid();
   insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
   values(v_movement,p_tenant_id,p_legal_entity_id,p_branch_id,'goods_receipt_reversal',v_reverse,v_r.warehouse_id,v_date,'goods_receipt_reversal',v_request,p_command_id,v_request,auth.uid());
  end if;
  insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,original_movement_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,v_movement,v_r.warehouse_id,v_m.product_id,v_m.source_line_id,v_m.id,-v_m.base_quantity,-v_m.base_value,v_m.lot_id,v_m.serial_ids,v_date,auth.uid());
 end loop;
 for v_line in select * from procurement.goods_receipt_lines where receipt_id=v_id order by order_line_id loop
  update procurement.purchase_order_lines set received_quantity=received_quantity-v_line.accepted_quantity where id=v_line.order_line_id;
 end loop;
 select coalesce(jsonb_agg(finance.flow_jline(account_id,transaction_credit-transaction_debit,base_credit-base_debit,source_line_id) order by line_number),'[]')
 into v_jlines from finance.journal_lines where journal_entry_id=v_r.journal_entry_id;
 v_journal:=finance.flow_post_journal(to_jsonb(v_r)||jsonb_build_object('document_date',v_date,'customer_id',v_po.supplier_id),v_jlines,'goods_receipt_reversal',v_reverse,v_request,p_command_id);
 insert into procurement.goods_receipt_reversals(id,tenant_id,legal_entity_id,branch_id,receipt_id,document_date,reason,stock_movement_id,journal_entry_id,request_id,command_id,created_by)
 values(v_reverse,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_date,v_reason,v_movement,v_journal,v_request,p_command_id,auth.uid());
 update procurement.purchase_orders set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_po.id;
 perform procurement.record_order_history(jsonb_build_object('entity',(select detail from api.purchase_orders where id=v_po.id)));
 select detail into v_result from api.goods_receipts where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'goods_receipt',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id,'{}',
 jsonb_build_object('from_status','posted','to_status','reversed','reason',v_reason),jsonb_build_array(jsonb_build_object('topic','procurement.receipt.reversed','payload',jsonb_build_object('receipt_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function api.upsert_receipt_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.post_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_receipt_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.post_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.goods_receipt_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_resource text,p_after uuid default null,p_search text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_items jsonb;v_search text:=lower(trim(coalesce(p_search,'')));v_next uuid;begin
 if p_resource='receipt_orders' then
  perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 else
  perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
  perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 end if;
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 if p_resource='receipt_orders' then
  select jsonb_agg(jsonb_build_object('id',id,'code',detail->>'document_number','name',detail->>'payment_terms','detail',detail) order by id)
  into v_items from(select * from api.purchase_orders where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and status='approved' and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(detail->>'document_number'))>0) order by id limit 51) x;
 elsif p_resource='receipt_accounts' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'account_type',account_type) order by id)
  into v_items from(select * from finance.accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and is_posting and status='active'
   and account_type in('expense','liability') and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='receipt_controls' then
  select jsonb_agg(sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id)) into v_items from procurement.receipt_controls c
  where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');
 if p_resource='receipt_orders' then
  select coalesce(jsonb_agg(jsonb_set(item,'{detail,lines}',coalesce((select jsonb_agg(line||jsonb_build_object('_tracking_mode',coalesce(p.tracking_mode,'none'),
   '_allowance',coalesce((select sales.flow_exact_json(to_jsonb(a)) from procurement.receipt_allowances a
     join procurement.receipt_controls c on c.legal_entity_id=a.legal_entity_id and c.tenant_id=a.tenant_id
     where a.order_line_id=(line->>'line_id')::uuid and a.order_version=(item#>>'{detail,version}')::bigint and a.control_version=c.version),'null'::jsonb)) order by line->>'line_id')
   from jsonb_array_elements(item#>'{detail,lines}') line left join inventory.products p
    on p.id=(line->>'product_id')::uuid and p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id),'[]')) order by item->>'id'),'[]')
   into v_items from jsonb_array_elements(v_items) item;
 end if;
 if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next);
end $$;
revoke all on function api.goods_receipt_reference_options(uuid,uuid,uuid,text,uuid,text) from public,anon;
grant execute on function api.goods_receipt_reference_options(uuid,uuid,uuid,text,uuid,text) to authenticated;

-- AC-311 candidate: receipt matching and AP; no persistent setup or business fixtures.
create table procurement.supplier_bill_controls(
 tenant_id uuid not null,legal_entity_id uuid primary key,payable_account_id uuid not null,input_tax_account_id uuid not null,variance_account_id uuid not null,
 amount_tolerance numeric(20,6) not null default 0 check(amount_tolerance>=0),price_percent_tolerance numeric(9,6) not null default 0 check(price_percent_tolerance between 0 and 100),
 version bigint not null default 1,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,payable_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,input_tax_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,variance_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
create table procurement.supplier_bills(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,supplier_id uuid not null,
 supplier_reference text not null check(length(trim(supplier_reference)) between 1 and 140),document_date date not null,due_date date not null,
 document_number text,currency_code text not null references core.currencies(code),base_currency_code text not null references core.currencies(code),
 exchange_rate_id uuid,exchange_rate numeric(20,10) not null,subtotal numeric(20,6) not null,tax_total numeric(20,6) not null,total numeric(20,6) not null,base_total numeric(20,6) not null,
 status text not null default 'draft' check(status in('draft','posted','cancelled')),version bigint not null default 1,
 match_result jsonb not null,journal_entry_id uuid,open_item_id uuid,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id),
 check(due_date>=document_date and total>=0 and base_total>=0 and exchange_rate>0)
);
create unique index supplier_reference_unique on procurement.supplier_bills(tenant_id,legal_entity_id,supplier_id,lower(trim(supplier_reference))) where status<>'cancelled';
create index supplier_bills_scope_page on procurement.supplier_bills(tenant_id,legal_entity_id,branch_id,id);
create index supplier_bills_party_date on procurement.supplier_bills(tenant_id,legal_entity_id,supplier_id,document_date,id);
create table procurement.supplier_bill_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,bill_id uuid not null,
 receipt_line_id uuid,quantity numeric(20,6) not null check(quantity>0),detail jsonb not null,
 unique(tenant_id,id),unique(bill_id,receipt_line_id),
 foreign key(tenant_id,bill_id) references procurement.supplier_bills(tenant_id,id),
 foreign key(tenant_id,receipt_line_id) references procurement.goods_receipt_lines(tenant_id,id)
);
create index supplier_bill_receipt_qty on procurement.supplier_bill_lines(tenant_id,receipt_line_id,bill_id);
create table procurement.supplier_bill_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 bill_id uuid not null,version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(bill_id,version),foreign key(tenant_id,bill_id) references procurement.supplier_bills(tenant_id,id)
);
create table procurement.supplier_bill_match_approvals(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,bill_id uuid not null,
 bill_version bigint not null,match_hash text not null,control_version bigint not null,reason text not null,
 approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(bill_id,bill_version,match_hash),
 foreign key(tenant_id,bill_id) references procurement.supplier_bills(tenant_id,id)
);
create table procurement.supplier_bill_control_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,version bigint not null,snapshot jsonb not null,
 actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(legal_entity_id,version),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create function procurement.bill_read_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean language sql stable security definer set search_path='' as $$
 select core.is_tenant_member(p_tenant) and (core.has_permission(p_tenant,'procurement.bills.view',p_entity,p_branch)
 or core.has_permission(p_tenant,'procurement.bills.manage',p_entity,p_branch) or core.has_permission(p_tenant,'procurement.bills.post',p_entity,p_branch))$$;
revoke all on function procurement.bill_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function procurement.bill_read_allowed(uuid,uuid,uuid) to authenticated;
do $$declare t text;begin
 foreach t in array array['supplier_bills','supplier_bill_lines','supplier_bill_history','supplier_bill_match_approvals','supplier_bill_controls','supplier_bill_control_history'] loop
  execute format('alter table procurement.%I enable row level security',t);execute format('alter table procurement.%I force row level security',t);
  if t in('supplier_bill_controls','supplier_bill_control_history') then
   execute format('create policy bill_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,''finance.setup.manage'',legal_entity_id,null))',t);
  else execute format('create policy bill_read on procurement.%I for select to authenticated using(procurement.bill_read_allowed(tenant_id,legal_entity_id,branch_id))',t);end if;
  execute format('revoke all on procurement.%I from public,anon,authenticated',t);execute format('grant select on procurement.%I to authenticated',t);
  if t in('supplier_bill_history','supplier_bill_match_approvals','supplier_bill_control_history') then
   execute format('create trigger immutable before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);end if;
 end loop;
end $$;
create trigger bill_immutable before update or delete on procurement.supplier_bills for each row execute function sales.flow_protect_document();
create function procurement.bill_line_guard() returns trigger language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from procurement.supplier_bills where id=coalesce((to_jsonb(new)->>'bill_id')::uuid,(to_jsonb(old)->>'bill_id')::uuid) and status<>'draft') then
 raise exception using errcode='55000',message='BILL_NOT_EDITABLE';end if;return coalesce(new,old);end $$;
create trigger bill_line_immutable before insert or update or delete on procurement.supplier_bill_lines for each row execute function procurement.bill_line_guard();
revoke all on function procurement.bill_line_guard() from public,anon,authenticated;
create view api.supplier_bills with(security_invoker=true) as select b.tenant_id,b.legal_entity_id,b.branch_id,b.id,b.status,
 sales.flow_exact_json(to_jsonb(b))||jsonb_build_object('lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.supplier_bill_lines l where l.bill_id=b.id),'[]'),
 'match_approvals',coalesce((select jsonb_agg(sales.flow_exact_json(to_jsonb(a)) order by a.created_at) from procurement.supplier_bill_match_approvals a where a.bill_id=b.id and a.bill_version=b.version),'[]')) detail
 from procurement.supplier_bills b;
grant select on api.supplier_bills to authenticated;
-- Preserve AR predicates while preventing receivables-only users from reading AP.
alter policy permitted_read on finance.open_items using(core.is_tenant_member(tenant_id) and
 ((kind='AR' and core.has_permission(tenant_id,'finance.receivables.view',legal_entity_id,branch_id))
 or (kind='AP' and procurement.bill_read_allowed(tenant_id,legal_entity_id,branch_id))));
create or replace function finance.flow_visible_residual(p_tenant uuid,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_o finance.open_items%rowtype;begin
 select * into v_o from finance.open_items where tenant_id=p_tenant and id=p_id and kind='AR';
 if not found or not core.is_tenant_member(p_tenant) or not core.has_permission(p_tenant,'finance.receivables.view',v_o.legal_entity_id,v_o.branch_id) then return null;end if;
 return finance.flow_residual(p_tenant,p_id);end $$;
create or replace view api.receivable_balances with(security_invoker=true) as
select o.id,o.tenant_id,o.legal_entity_id,o.branch_id,o.party_id,o.currency_code,o.source_type,o.source_id,o.posting_date,o.due_date,
 sales.flow_exact_json(to_jsonb(o))||finance.flow_visible_residual(o.tenant_id,o.id) as detail from finance.open_items o where o.kind='AR';

create function api.upsert_supplier_bill_controls(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='procurement.bill_controls.upsert';v_hash text;v_result jsonb;v_old procurement.supplier_bill_controls%rowtype;v_base text;
 v_ap uuid:=(p_payload->>'payable_account_id')::uuid;v_tax uuid:=(p_payload->>'input_tax_account_id')::uuid;v_var uuid:=(p_payload->>'variance_account_id')::uuid;
 v_amount numeric;v_percent numeric;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 if (p_payload->>'id')::uuid is distinct from p_legal_entity_id or p_client_timestamp is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('bill.controls:'||p_legal_entity_id::text,0));
 select * into v_old from procurement.supplier_bill_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
 if found then perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,to_jsonb(v_old));
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 select currency_code into v_base from core.legal_entities where tenant_id=p_tenant_id and id=p_legal_entity_id;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_ap,'liability',v_base);perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_tax,'asset',v_base);
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_var,'expense',v_base);
 v_amount:=sales.wave3_decimal_string(p_payload->'amount_tolerance','amount_tolerance',6,true,0,null);
 v_percent:=sales.wave3_decimal_string(p_payload->'price_percent_tolerance','price_percent_tolerance',6,true,0,100);
 insert into procurement.supplier_bill_controls(tenant_id,legal_entity_id,payable_account_id,input_tax_account_id,variance_account_id,amount_tolerance,price_percent_tolerance,updated_by)
 values(p_tenant_id,p_legal_entity_id,v_ap,v_tax,v_var,v_amount,v_percent,auth.uid()) on conflict(legal_entity_id) do update set
 payable_account_id=excluded.payable_account_id,input_tax_account_id=excluded.input_tax_account_id,variance_account_id=excluded.variance_account_id,
 amount_tolerance=excluded.amount_tolerance,price_percent_tolerance=excluded.price_percent_tolerance,version=procurement.supplier_bill_controls.version+1,updated_by=auth.uid(),updated_at=clock_timestamp();
 select sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id) into v_result from procurement.supplier_bill_controls c where legal_entity_id=p_legal_entity_id;
 insert into procurement.supplier_bill_control_history(tenant_id,legal_entity_id,version,snapshot,actor_id) values(p_tenant_id,p_legal_entity_id,(v_result->>'version')::bigint,v_result,auth.uid());
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_bill_controls',p_legal_entity_id,p_idempotency_key,v_hash,to_jsonb(v_old),v_result,p_legal_entity_id,p_branch_id);
end $$;

-- Private normalization is shared by save, match approval and posting.
create function procurement.normalize_bill(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_c procurement.supplier_bill_controls%rowtype;v_input jsonb;v_lines jsonb:='[]';v_exceptions jsonb:='[]';v_source jsonb;v_detail jsonb;
 v_rl procurement.goods_receipt_lines%rowtype;v_r procurement.goods_receipts%rowtype;v_tax finance.tax_definitions%rowtype;v_product inventory.products%rowtype;
 v_q numeric;v_price numeric;v_discount numeric;v_gross numeric;v_net numeric;v_tax_amount numeric;v_total numeric:=0;v_subtotal numeric:=0;v_tax_total numeric:=0;
 v_already numeric;v_available numeric;v_accrual numeric;v_accrual_base numeric;v_expected numeric;v_diff numeric;v_exception jsonb;
 v_currency text:=p_payload->>'currency_code';v_date date:=(p_payload->>'document_date')::date;v_due date:=(p_payload->>'due_date')::date;
 v_supplier uuid:=(p_payload->>'supplier_id')::uuid;v_id uuid:=(p_payload->>'id')::uuid;v_line_id uuid;v_seen uuid[]:='{}';v_receipts uuid[]:='{}';
 v_scale integer;v_base text;v_rate jsonb;v_account uuid;v_grni uuid;v_blocked boolean:=false;
begin
 if v_date is null or v_due is null or v_due<v_date or v_id is null or coalesce(length(trim(p_payload->>'supplier_reference')),0) not between 1 and 140
  or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 then raise exception using errcode='22023',message='BILL_INPUT_INVALID';end if;
 if not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant and status='active' and kind in('supplier','both')) then raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
 select * into v_c from procurement.supplier_bill_controls where tenant_id=p_tenant and legal_entity_id=p_entity;
 if not found then raise exception using errcode='55000',message='BILL_CONTROLS_REQUIRED';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_rate:=finance.flow_rate(p_tenant,p_entity,v_currency,v_date,(p_payload->>'exchange_rate_id')::uuid);
 for v_input in select value from jsonb_array_elements(p_payload->'lines') order by value->>'line_id' loop
  v_line_id:=(v_input->>'line_id')::uuid;
  if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='BILL_LINE_ID_INVALID';end if;
  v_seen:=array_append(v_seen,v_line_id);v_exception:='[]';v_rl:=null;v_r:=null;v_product:=null;v_source:='{}';v_account:=null;v_grni:=null;v_accrual:=0;v_accrual_base:=0;
  v_q:=sales.wave3_decimal_string(v_input->'quantity','quantity',6,true,0,null);if v_q<=0 then raise exception using errcode='22023',message='BILL_QUANTITY_INVALID';end if;
  v_price:=sales.wave3_decimal_string(v_input->'unit_price','unit_price',6,true,0,null);
  v_discount:=sales.wave3_decimal_string(v_input->'discount_percent','discount_percent',6,true,0,100);
  v_gross:=round(v_q*v_price,v_scale);v_net:=v_gross-round(v_gross*v_discount/100,v_scale);v_tax_amount:=0;v_tax:=null;
  if v_input->>'tax_definition_id' is not null then
   select * into v_tax from finance.tax_definitions where id=(v_input->>'tax_definition_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
    and status='active' and kind in('input','zero','exempt') and valid_from<=v_date and (valid_to is null or valid_to>=v_date);
   if not found then raise exception using errcode='22023',message='INPUT_TAX_INVALID';end if;
   v_tax_amount:=round(v_net*v_tax.rate/(case when v_tax.inclusive then 100+v_tax.rate else 100 end),v_scale);
   if v_tax.inclusive then v_net:=v_net-v_tax_amount;end if;
  end if;
  if v_input->>'receipt_line_id' is not null then
   if (v_input->>'receipt_line_id')::uuid=any(v_receipts) then raise exception using errcode='22023',message='DUPLICATE_RECEIPT_LINE';end if;
   v_receipts:=array_append(v_receipts,(v_input->>'receipt_line_id')::uuid);
   select * into v_rl from procurement.goods_receipt_lines where id=(v_input->>'receipt_line_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch;
   if not found then raise exception using errcode='22023',message='RECEIPT_SOURCE_INVALID';end if;
   select * into v_r from procurement.goods_receipts where id=v_rl.receipt_id;
   if (v_r.source_snapshot->>'supplier_id')::uuid<>v_supplier then raise exception using errcode='22023',message='RECEIPT_SUPPLIER_MISMATCH';end if;
   v_source:=v_rl.detail->'source_snapshot';
   select coalesce(sum(l.quantity),0) into v_already from procurement.supplier_bill_lines l join procurement.supplier_bills b on b.id=l.bill_id
    where l.receipt_line_id=v_rl.id and b.status='posted' and b.id<>v_id;
   v_available:=v_rl.accepted_quantity-v_already;
   if v_r.document_date>v_date or exists(select 1 from procurement.goods_receipt_reversals where receipt_id=v_r.id) or v_q>v_available or v_rl.accepted_quantity<=0 then
    v_blocked:=true;v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','RECEIPT_QUANTITY_UNAVAILABLE','available_quantity',greatest(v_available,0)::text,'requested_quantity',v_q::text));
   else
    v_accrual_base:=round(v_rl.base_amount*(v_already+v_q)/v_rl.accepted_quantity,v_scale)-round(v_rl.base_amount*v_already/v_rl.accepted_quantity,v_scale);
    v_accrual:=round(v_rl.net_amount*(v_already+v_q)/v_rl.accepted_quantity,v_scale)-round(v_rl.net_amount*v_already/v_rl.accepted_quantity,v_scale);
   end if;
   if not exists(select 1 from inventory.units where id=(v_source->>'unit_id')::uuid and tenant_id=p_tenant and status='active' and round(v_q,precision)=v_q) then raise exception using errcode='22023',message='BILL_UNIT_PRECISION_INVALID';end if;
   select account_id into v_grni from finance.journal_lines where journal_entry_id=v_r.journal_entry_id and base_credit>0 and source_line_id is null;
   if v_rl.base_amount<>0 and v_grni is null then raise exception using errcode='55000',message='RECEIPT_ACCRUAL_LINK_INVALID';end if;
   v_diff:=abs(v_price-(v_source->>'unit_price')::numeric);
   if v_diff>abs((v_source->>'unit_price')::numeric)*v_c.price_percent_tolerance/100 then
    v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','PRICE_VARIANCE','expected',v_source->>'unit_price','actual',v_price::text,'difference',v_diff::text));end if;
   if v_discount<>(v_source->>'discount_percent')::numeric then v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','DISCOUNT_VARIANCE','expected',v_source->>'discount_percent','actual',v_discount::text));end if;
   if (v_input->>'tax_definition_id') is distinct from (v_source->>'tax_definition_id') or coalesce(v_tax.rate,0)<>coalesce((v_source->>'tax_rate')::numeric,0)
    or coalesce(v_tax.inclusive,false)<>coalesce((v_source->>'tax_inclusive')::boolean,false) then
    v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','TAX_MISMATCH','expected_rate',v_source->>'tax_rate','actual_rate',coalesce(v_tax.rate,0)::text));end if;
   if v_currency<>v_r.currency_code then v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','CURRENCY_MISMATCH','expected',v_r.currency_code,'actual',v_currency));end if;
   v_expected:=case when v_currency=v_r.currency_code then v_accrual else round(v_accrual_base/(v_rate->>'exchange_rate')::numeric,v_scale) end;
   if abs(v_net-v_expected)>v_c.amount_tolerance then v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','TOTAL_VARIANCE','expected',v_expected::text,'actual',v_net::text,'difference',(v_net-v_expected)::text));end if;
  else
   perform core.require_permission(p_tenant,'procurement.bills.post',p_entity,p_branch);
   if v_input->>'product_id' is not null then
    select * into v_product from inventory.products where id=(v_input->>'product_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity and status='active' and can_purchase and kind in('non_stocked','service');
    if not found then raise exception using errcode='22023',message='DIRECT_BILL_NONSTOCK_REQUIRED';end if;
   end if;
   if coalesce(length(trim(v_input->>'description')),0) not between 1 and 500 then raise exception using errcode='22023',message='DIRECT_BILL_DESCRIPTION_REQUIRED';end if;
   v_account:=finance.flow_account(p_tenant,p_entity,coalesce(v_product.expense_account_id,(v_input->>'expense_account_id')::uuid),'expense',v_currency);
  end if;
  v_detail:=jsonb_build_object('line_id',v_line_id,'receipt_line_id',v_rl.id,'order_id',v_r.order_id,'order_line_id',v_rl.order_line_id,
   'description',coalesce(v_source->>'description',v_input->>'description'),'product_id',coalesce(v_source->>'product_id',v_input->>'product_id'),
   'quantity',v_q::text,'unit_price',v_price::text,'discount_percent',v_discount::text,'tax_definition_id',v_tax.id,'tax_rate',coalesce(v_tax.rate,0)::text,'tax_inclusive',coalesce(v_tax.inclusive,false),
   'net_amount',v_net::text,'tax_amount',v_tax_amount::text,'line_total',(v_net+v_tax_amount)::text,'expense_account_id',v_account,
   'accrual_amount',v_accrual::text,'accrual_base_amount',v_accrual_base::text,'grni_account_id',v_grni,'source_snapshot',v_source,'exceptions',v_exception);
  v_lines:=v_lines||jsonb_build_array(v_detail);
  if jsonb_array_length(v_exception)>0 then v_exceptions:=v_exceptions||jsonb_build_array(jsonb_build_object('line_id',v_line_id,'exceptions',v_exception));end if;
  v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax_amount;v_total:=v_total+v_net+v_tax_amount;
 end loop;
 return jsonb_build_object('lines',v_lines,'subtotal',v_subtotal::text,'tax_total',v_tax_total::text,'total',v_total::text,
  'base_total',round(v_total*(v_rate->>'exchange_rate')::numeric,v_scale)::text,'rate',v_rate,
  'match',jsonb_build_object('blocked',v_blocked,'exceptions',v_exceptions,'control_version',v_c.version,'amount_tolerance',v_c.amount_tolerance::text,'price_percent_tolerance',v_c.price_percent_tolerance::text));
end $$;
revoke all on function procurement.normalize_bill(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function procurement.bill_history(p_tenant uuid,p_id uuid) returns void language sql security definer set search_path='' as $$
 insert into procurement.supplier_bill_history(tenant_id,legal_entity_id,branch_id,bill_id,version,snapshot,actor_id)
 select tenant_id,legal_entity_id,branch_id,id,(detail->>'version')::bigint,detail,auth.uid() from api.supplier_bills where tenant_id=p_tenant and id=p_id$$;
revoke all on function procurement.bill_history(uuid,uuid) from public,anon,authenticated;

create function api.upsert_supplier_bill(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_command text:='procurement.supplier_bill.upsert';v_hash text;v_result jsonb;v_before jsonb;v_normal jsonb;v_line jsonb;v_old procurement.supplier_bills%rowtype;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.bills.manage',p_legal_entity_id,p_branch_id);
 if p_client_timestamp is null or p_legal_entity_id is null or p_branch_id is null or v_id is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('supplier.bill:'||v_id::text,0));
 select * into v_old from procurement.supplier_bills where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  if v_old.status<>'draft' then raise exception using errcode='55000',message='BILL_NOT_EDITABLE';end if;
  select detail into v_before from api.supplier_bills where id=v_id;
  perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 v_normal:=procurement.normalize_bill(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 insert into procurement.supplier_bills(id,tenant_id,legal_entity_id,branch_id,supplier_id,supplier_reference,document_date,due_date,currency_code,base_currency_code,exchange_rate_id,exchange_rate,
  subtotal,tax_total,total,base_total,match_result,created_by,updated_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,(p_payload->>'supplier_id')::uuid,trim(p_payload->>'supplier_reference'),(p_payload->>'document_date')::date,(p_payload->>'due_date')::date,
  p_payload->>'currency_code',v_normal#>>'{rate,base_currency_code}',(p_payload->>'exchange_rate_id')::uuid,(v_normal#>>'{rate,exchange_rate}')::numeric,
  (v_normal->>'subtotal')::numeric,(v_normal->>'tax_total')::numeric,(v_normal->>'total')::numeric,(v_normal->>'base_total')::numeric,v_normal->'match',auth.uid(),auth.uid())
 on conflict(id) do update set supplier_id=excluded.supplier_id,supplier_reference=excluded.supplier_reference,document_date=excluded.document_date,due_date=excluded.due_date,
 currency_code=excluded.currency_code,base_currency_code=excluded.base_currency_code,exchange_rate_id=excluded.exchange_rate_id,exchange_rate=excluded.exchange_rate,
 subtotal=excluded.subtotal,tax_total=excluded.tax_total,total=excluded.total,base_total=excluded.base_total,match_result=excluded.match_result,
 version=procurement.supplier_bills.version+1,updated_by=auth.uid(),updated_at=clock_timestamp()
 where procurement.supplier_bills.tenant_id=p_tenant_id and procurement.supplier_bills.legal_entity_id=p_legal_entity_id and procurement.supplier_bills.branch_id=p_branch_id;
 if not found then raise exception using errcode='42501',message='BILL_SCOPE_INVALID';end if;
 delete from procurement.supplier_bill_lines where bill_id=v_id;
 for v_line in select value from jsonb_array_elements(v_normal->'lines') loop
  insert into procurement.supplier_bill_lines(id,tenant_id,legal_entity_id,branch_id,bill_id,receipt_line_id,quantity,detail)
  values((v_line->>'line_id')::uuid,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,(v_line->>'receipt_line_id')::uuid,(v_line->>'quantity')::numeric,v_line);
 end loop;
 perform procurement.bill_history(p_tenant_id,v_id);select detail into v_result from api.supplier_bills where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_bill',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id);
end $$;

create function procurement.bill_action(p_action text,p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;v_command text:='procurement.supplier_bill.'||p_action;v_hash text;v_result jsonb;v_before jsonb;v_normal jsonb;v_match_hash text;
 v_b procurement.supplier_bills%rowtype;v_c procurement.supplier_bill_controls%rowtype;v_line jsonb;v_order uuid;v_jlines jsonb:='[]';v_request uuid:=gen_random_uuid();
 v_journal uuid;v_open uuid:=gen_random_uuid();v_number text;v_scale integer;v_net numeric;v_tax numeric;v_base_tax numeric;v_acc_base numeric;v_acc numeric;
 v_debits numeric:=0;v_base_debits numeric:=0;v_var numeric;v_base_var numeric;
begin
 perform core.wave3_require_scope(p_tenant_id,case when p_action='cancel' then 'procurement.bills.manage' else 'procurement.bills.post' end,p_legal_entity_id,p_branch_id);
 if p_action not in('post','approve','cancel') or v_id is null or p_client_timestamp is null or p_branch_id is null or p_legal_entity_id is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if p_action='approve' then perform core.wave3_require_scope(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_b from procurement.supplier_bills where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='BILL_NOT_FOUND';end if;
 select detail into v_before from api.supplier_bills where id=v_id;
 perform core.wave3_assert_expected_version(v_b.version,p_expected_entity_version,v_before);
 if v_b.status<>'draft' then raise exception using errcode='55000',message='BILL_NOT_EDITABLE';end if;
 if p_action='cancel' then
  if coalesce(length(trim(p_payload->>'reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='CANCELLATION_REASON_REQUIRED';end if;
  update procurement.supplier_bills set status='cancelled',version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 else
  for v_order in select distinct (detail->>'order_id')::uuid from procurement.supplier_bill_lines where bill_id=v_id and detail->>'order_id' is not null order by 1 loop
   perform 1 from procurement.purchase_orders where id=v_order for update;
   perform 1 from procurement.purchase_order_lines where order_id=v_order order by id for update;
  end loop;
  select * into v_c from procurement.supplier_bill_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for share;
  v_normal:=procurement.normalize_bill(p_tenant_id,p_legal_entity_id,p_branch_id,v_before);
  if (v_normal#>>'{match,blocked}')::boolean then raise exception using errcode='55000',message='RECEIPT_QUANTITY_UNAVAILABLE';end if;
  if (v_normal->>'total')::numeric is distinct from v_b.total or (v_normal#>>'{rate,exchange_rate}')::numeric<>v_b.exchange_rate then
   raise exception using errcode='40001',message='BILL_PRICING_CHANGED';end if;
  v_match_hash:=encode(extensions.digest((v_normal->'match')::text||'|'||(v_normal->'lines')::text,'sha256'),'hex');
  if p_action='approve' then
   if auth.uid() in(v_b.created_by,v_b.updated_by) then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
   if coalesce(length(trim(p_payload->>'reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='MATCH_REASON_REQUIRED';end if;
   insert into procurement.supplier_bill_match_approvals(tenant_id,legal_entity_id,branch_id,bill_id,bill_version,match_hash,control_version,reason,approved_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_b.version,v_match_hash,v_c.version,trim(p_payload->>'reason'),auth.uid());
  else
   if jsonb_array_length(v_normal#>'{match,exceptions}')>0 and not exists(select 1 from procurement.supplier_bill_match_approvals
    where bill_id=v_id and bill_version=v_b.version and match_hash=v_match_hash and control_version=v_c.version) then raise exception using errcode='55000',message='MATCH_APPROVAL_REQUIRED';end if;
   if v_b.total<=0 or v_b.base_total<=0 then raise exception using errcode='22023',message='POSITIVE_BILL_REQUIRED';end if;
   perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_b.document_date);
   perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_c.payable_account_id,'liability',v_b.currency_code);
   perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_c.input_tax_account_id,'asset',v_b.currency_code);
   perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_c.variance_account_id,'expense',v_b.currency_code);
   select rounding_scale into v_scale from core.legal_entities where id=p_legal_entity_id;
   for v_line in select value from jsonb_array_elements(v_normal->'lines') loop
    v_net:=(v_line->>'net_amount')::numeric;v_tax:=(v_line->>'tax_amount')::numeric;v_base_tax:=round(v_tax*v_b.exchange_rate,v_scale);
    if v_line->>'receipt_line_id' is not null then
     v_acc_base:=(v_line->>'accrual_base_amount')::numeric;
     v_acc:=round(v_acc_base/v_b.exchange_rate,v_scale);
     if v_acc_base<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline((v_line->>'grni_account_id')::uuid,v_acc,v_acc_base,(v_line->>'line_id')::uuid));end if;
     update procurement.purchase_order_lines set billed_quantity=billed_quantity+(v_line->>'quantity')::numeric where id=(v_line->>'order_line_id')::uuid;
    else
     v_acc:=v_net;v_acc_base:=round(v_net*v_b.exchange_rate,v_scale);
     if v_acc_base<>0 or v_acc<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline((v_line->>'expense_account_id')::uuid,v_acc,v_acc_base,(v_line->>'line_id')::uuid));end if;
    end if;
    if v_tax<>0 or v_base_tax<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_c.input_tax_account_id,v_tax,v_base_tax,(v_line->>'line_id')::uuid));end if;
    v_debits:=v_debits+v_acc+v_tax;v_base_debits:=v_base_debits+v_acc_base+v_base_tax;
    update procurement.supplier_bill_lines set detail=v_line where id=(v_line->>'line_id')::uuid and bill_id=v_id;
   end loop;
   v_var:=v_b.total-v_debits;v_base_var:=v_b.base_total-v_base_debits;
   if v_var<>0 or v_base_var<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_c.variance_account_id,v_var,v_base_var));end if;
   v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_c.payable_account_id,-v_b.total,-v_b.base_total));
   v_journal:=finance.flow_post_journal(to_jsonb(v_b)||jsonb_build_object('customer_id',v_b.supplier_id),v_jlines,'supplier_bill',v_id,v_request,p_command_id);
   v_number:=sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'supplier_bill',v_b.document_date,auth.uid());
   insert into finance.open_items(id,tenant_id,legal_entity_id,branch_id,kind,party_id,source_type,source_id,document_number,currency_code,base_currency_code,exchange_rate,
    original_amount,original_base_amount,posting_date,due_date,journal_entry_id,request_id,command_id,correlation_id,created_by)
   values(v_open,p_tenant_id,p_legal_entity_id,p_branch_id,'AP',v_b.supplier_id,'supplier_bill',v_id,v_number,v_b.currency_code,v_b.base_currency_code,v_b.exchange_rate,
    v_b.total,v_b.base_total,v_b.document_date,v_b.due_date,v_journal,v_request,p_command_id,v_request,auth.uid());
   update procurement.supplier_bills set status='posted',document_number=v_number,version=version+1,match_result=v_normal->'match',journal_entry_id=v_journal,open_item_id=v_open,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
   for v_order in select distinct (detail->>'order_id')::uuid from procurement.supplier_bill_lines where bill_id=v_id and detail->>'order_id' is not null order by 1 loop
    update procurement.purchase_orders set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_order;
    perform procurement.record_order_history(jsonb_build_object('entity',(select detail from api.purchase_orders where id=v_order)));
   end loop;
  end if;
 end if;
 if p_action<>'approve' then perform procurement.bill_history(p_tenant_id,v_id);end if;
 select detail into v_result from api.supplier_bills where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_bill',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id,'{}',
  case when p_action='approve' then null else jsonb_build_object('from_status','draft','to_status',v_result->>'status','reason',p_payload->>'reason') end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('bill_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function procurement.bill_action(text,uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
do $$declare v_name text;v_action text;begin
 for v_name,v_action in select * from(values('post_supplier_bill','post'),('approve_supplier_bill_match','approve'),('cancel_supplier_bill','cancel')) x loop
 execute format('create function api.%I(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language sql security definer set search_path='''' as $fn$select procurement.bill_action(%L,p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version)$fn$',v_name,v_action);
 execute format('revoke all on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon',v_name);
 execute format('grant execute on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated',v_name);
 end loop;
end $$;
revoke all on function api.upsert_supplier_bill(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.upsert_supplier_bill_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_supplier_bill(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.upsert_supplier_bill_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.supplier_bill_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;v_search text:=lower(trim(coalesce(p_search,'')));v_base text;begin
 if p_resource in('bill_controls','bill_accounts') then
  perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
  perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 else perform core.wave3_require_scope(p_tenant_id,'procurement.bills.manage',p_legal_entity_id,p_branch_id);end if;
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='bill_receipts' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'detail',detail) order by id) into v_items from (
   select l.id,r.document_number code,l.detail->>'description' name,l.detail||jsonb_build_object('receipt_line_id',l.id,
    'supplier_id',r.source_snapshot->>'supplier_id','currency_code',r.currency_code,'exchange_rate_id',r.source_snapshot->>'exchange_rate_id',
    'available_quantity',(l.accepted_quantity-coalesce((select sum(bl.quantity) from procurement.supplier_bill_lines bl join procurement.supplier_bills b on b.id=bl.bill_id
     where bl.receipt_line_id=l.id and b.status='posted'),0))::text) detail
   from procurement.goods_receipt_lines l join procurement.goods_receipts r on r.id=l.receipt_id
   where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and l.branch_id=p_branch_id and l.accepted_quantity>0
    and not exists(select 1 from procurement.goods_receipt_reversals x where x.receipt_id=r.id)
    and (p_after is null or l.id>p_after) and (v_search='' or position(v_search in lower(r.document_number||' '||(l.detail->>'description')))>0)
   order by l.id limit 51) x;
 elsif p_resource='bill_controls' then
  select jsonb_agg(sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id)) into v_items from procurement.supplier_bill_controls c
   where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id;
 elsif p_resource in('bill_accounts','bill_expenses') then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'account_type',account_type) order by id) into v_items from (
   select * from finance.accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and is_posting
    and (p_resource='bill_accounts' or account_type='expense') and (p_after is null or id>p_after)
    and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='bill_suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) into v_items from (
   select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both') and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51) x;
 elsif p_resource='bill_taxes' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'rate',rate::text,'inclusive',inclusive) order by id) into v_items from (
   select * from finance.tax_definitions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and kind in('input','zero','exempt')
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='bill_rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,'currency_code',source_currency_code,'exchange_rate',rate::text) order by id) into v_items from (
   select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and target_currency_code=v_base
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51) x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next,'base_currency',v_base);
end $$;
revoke all on function api.supplier_bill_reference_options(uuid,uuid,uuid,text,uuid,text) from public,anon;
grant execute on function api.supplier_bill_reference_options(uuid,uuid,uuid,text,uuid,text) to authenticated;

-- AC-312 candidate. Recorded settlement only; no external payment integration.
create function finance.payable_read_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean language sql stable security definer set search_path='' as $$
 select core.is_tenant_member(p_tenant) and (procurement.bill_read_allowed(p_tenant,p_entity,p_branch)
 or core.has_permission(p_tenant,'finance.payments.manage',p_entity,p_branch) or core.has_permission(p_tenant,'finance.payments.post',p_entity,p_branch))$$;
revoke all on function finance.payable_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function finance.payable_read_allowed(uuid,uuid,uuid) to authenticated;
alter policy permitted_read on finance.open_items using(core.is_tenant_member(tenant_id) and
 ((kind='AR' and core.has_permission(tenant_id,'finance.receivables.view',legal_entity_id,branch_id))
 or (kind='AP' and finance.payable_read_allowed(tenant_id,legal_entity_id,branch_id))));
alter policy permitted_read on finance.open_item_allocations using(core.is_tenant_member(tenant_id) and exists(select 1 from finance.open_items o
 where o.id=source_open_item_id and o.tenant_id=open_item_allocations.tenant_id and
 ((o.kind='AR' and core.has_permission(o.tenant_id,'finance.receivables.view',o.legal_entity_id,o.branch_id))
 or (o.kind='AP' and finance.payable_read_allowed(o.tenant_id,o.legal_entity_id,o.branch_id)))));
create table procurement.payment_proposals(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,supplier_id uuid not null,cash_bank_account_id uuid not null,
 document_date date not null,document_number text,currency_code text not null,base_currency_code text not null,exchange_rate_id uuid,exchange_rate numeric(20,10) not null,
 total numeric(20,6) not null check(total>0),base_total numeric(20,6) not null check(base_total>0),lines jsonb not null,
 status text not null default 'draft' check(status in('draft','pending_approval','approved','rejected','cancelled','posted')),
 version bigint not null default 1,workflow_snapshot jsonb,submitted_by uuid references auth.users(id),submitted_at timestamptz,
 created_by uuid not null references auth.users(id),prepared_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),foreign key(tenant_id,cash_bank_account_id) references finance.cash_bank_accounts(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id)
);
create table procurement.payment_proposal_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 proposal_id uuid not null,version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(proposal_id,version),foreign key(tenant_id,proposal_id) references procurement.payment_proposals(tenant_id,id)
);
create table procurement.payment_claims(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 proposal_id uuid not null,open_item_id uuid not null,amount numeric(20,6) not null check(amount>0),active boolean not null default true,
 created_at timestamptz not null default now(),released_at timestamptz,
 foreign key(tenant_id,proposal_id) references procurement.payment_proposals(tenant_id,id),foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id)
);
create unique index payment_claim_exclusive on procurement.payment_claims(tenant_id,open_item_id) where active;
create index payment_claim_proposal on procurement.payment_claims(tenant_id,proposal_id,active,open_item_id);
create table procurement.supplier_payments(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,proposal_id uuid not null unique,supplier_id uuid not null,
 cash_bank_account_id uuid not null,document_date date not null,document_number text not null,reference text not null,
 currency_code text not null,base_currency_code text not null,exchange_rate numeric(20,10) not null,amount numeric(20,6) not null,base_amount numeric(20,6) not null,
 journal_entry_id uuid not null,open_item_id uuid not null,allocations jsonb not null,source_snapshot jsonb not null,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,id),foreign key(tenant_id,proposal_id) references procurement.payment_proposals(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id),
 foreign key(tenant_id,cash_bank_account_id) references finance.cash_bank_accounts(tenant_id,id),foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id)
);
create index payment_proposals_scope on procurement.payment_proposals(tenant_id,legal_entity_id,branch_id,status,document_date,id);
create index supplier_payments_scope on procurement.supplier_payments(tenant_id,legal_entity_id,branch_id,document_date,id);
do $$declare t text;begin
 foreach t in array array['payment_proposals','payment_proposal_history','payment_claims','supplier_payments'] loop
 execute format('alter table procurement.%I enable row level security',t);execute format('alter table procurement.%I force row level security',t);
 execute format('create policy payment_read on procurement.%I for select to authenticated using(finance.payable_read_allowed(tenant_id,legal_entity_id,branch_id))',t);
 execute format('revoke all on procurement.%I from public,anon,authenticated',t);execute format('grant select on procurement.%I to authenticated',t);
 if t in('payment_proposal_history','supplier_payments') then execute format('create trigger immutable before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);end if;
 end loop;
end $$;
create trigger proposal_posted_immutable before update or delete on procurement.payment_proposals for each row execute function sales.flow_protect_document();
create view api.payment_proposals with(security_invoker=true) as select p.tenant_id,p.legal_entity_id,p.branch_id,p.id,p.status,sales.flow_exact_json(to_jsonb(p)) detail from procurement.payment_proposals p;
create view api.supplier_payments with(security_invoker=true) as select p.tenant_id,p.legal_entity_id,p.branch_id,p.id,
 sales.flow_exact_json(to_jsonb(p))||jsonb_build_object('status','posted','reconciliation_status','pending') detail from procurement.supplier_payments p;
grant select on api.payment_proposals,api.supplier_payments to authenticated;
create function finance.payable_residual(p_tenant uuid,p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_o finance.open_items%rowtype;begin select * into v_o from finance.open_items where tenant_id=p_tenant and id=p_id and kind='AP';
 if not found or not finance.payable_read_allowed(p_tenant,v_o.legal_entity_id,v_o.branch_id) then return null;end if;
 return finance.flow_residual(p_tenant,p_id);end $$;
revoke all on function finance.payable_residual(uuid,uuid) from public,anon;
grant execute on function finance.payable_residual(uuid,uuid) to authenticated;
create view api.payable_balances with(security_invoker=true) as select o.id,o.tenant_id,o.legal_entity_id,o.branch_id,o.party_id,o.currency_code,o.posting_date,o.due_date,
 sales.flow_exact_json(to_jsonb(o))||finance.payable_residual(o.tenant_id,o.id) detail from finance.open_items o where kind='AP';
grant select on api.payable_balances to authenticated;

create function procurement.normalize_payment_proposal(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_lock boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_bank finance.cash_bank_accounts%rowtype;v_o finance.open_items%rowtype;v_line jsonb;v_lines jsonb:='[]';v_id uuid;v_seen uuid[]:='{}';
 v_amount numeric;v_total numeric:=0;v_residual jsonb;v_rate jsonb;v_scale integer;v_date date:=(p_payload->>'document_date')::date;
begin
 if jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 or v_date is null then raise exception using errcode='22023',message='PROPOSAL_INPUT_INVALID';end if;
 if p_lock then perform 1 from finance.cash_bank_accounts where id=(p_payload->>'cash_bank_account_id')::uuid and tenant_id=p_tenant for share;end if;
 select * into v_bank from finance.cash_bank_accounts where id=(p_payload->>'cash_bank_account_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and status='active';
 if not found then raise exception using errcode='22023',message='PAYMENT_BANK_INVALID';end if;
 perform finance.flow_account(p_tenant,p_entity,v_bank.account_id,'asset',v_bank.currency_code);
 if not exists(select 1 from crm.parties where id=(p_payload->>'supplier_id')::uuid and tenant_id=p_tenant and status='active' and kind in('supplier','both')) then raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
 v_rate:=finance.flow_rate(p_tenant,p_entity,v_bank.currency_code,v_date,(p_payload->>'exchange_rate_id')::uuid);
 select rounding_scale into v_scale from core.legal_entities where tenant_id=p_tenant and id=p_entity;
 for v_line in select value from jsonb_array_elements(p_payload->'lines') order by value->>'open_item_id' loop
  v_id:=(v_line->>'open_item_id')::uuid;
  if v_id is null or v_id=any(v_seen) then raise exception using errcode='22023',message='PROPOSAL_ITEM_DUPLICATE';end if;
  v_seen:=array_append(v_seen,v_id);
  if p_lock then perform 1 from finance.open_items where id=v_id and tenant_id=p_tenant for update;end if;
  select * into v_o from finance.open_items where id=v_id and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and kind='AP'
   and party_id=(p_payload->>'supplier_id')::uuid and currency_code=v_bank.currency_code and posting_date<=v_date and (original_amount<0 or due_date<=v_date);
  if not found then raise exception using errcode='22023',message='PAYABLE_ITEM_INELIGIBLE';end if;
  if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id=v_id and active and proposal_id<>(p_payload->>'id')::uuid) then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
  if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id=v_id or target_open_item_id=v_id) and posting_date>v_date) then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
  v_amount:=sales.wave3_decimal_string(v_line->'amount','amount',6,true,0,null);v_residual:=finance.flow_residual(p_tenant,v_id);
  if v_amount<=0 or round(v_amount,v_scale)<>v_amount or v_amount>abs((v_residual->>'amount')::numeric) then raise exception using errcode='22023',message='PROPOSAL_AMOUNT_EXCEEDED';end if;
  v_total:=v_total+case when v_o.original_amount>0 then v_amount else -v_amount end;
  v_lines:=v_lines||jsonb_build_array(jsonb_build_object('open_item_id',v_id,'document_number',v_o.document_number,'kind',case when v_o.original_amount>0 then 'bill' else 'credit' end,
   'amount',v_amount::text,'residual',v_residual,'due_date',v_o.due_date,'currency_code',v_o.currency_code));
 end loop;
 if v_total<=0 then raise exception using errcode='22023',message='POSITIVE_PAYMENT_REQUIRED';end if;
 return jsonb_build_object('lines',v_lines,'currency_code',v_bank.currency_code,'rate',v_rate,'total',v_total::text,'base_total',round(v_total*(v_rate->>'exchange_rate')::numeric,v_scale)::text);
end $$;
revoke all on function procurement.normalize_payment_proposal(uuid,uuid,uuid,jsonb,boolean) from public,anon,authenticated;
create function procurement.record_payment_proposal_history(p_result jsonb) returns void language sql security definer set search_path='' as $$
 insert into procurement.payment_proposal_history(tenant_id,legal_entity_id,branch_id,proposal_id,version,snapshot,actor_id)
 select (e->>'tenant_id')::uuid,(e->>'legal_entity_id')::uuid,(e->>'branch_id')::uuid,(e->>'id')::uuid,(e->>'version')::bigint,e,auth.uid()
 from(select p_result->'entity' e)x on conflict(proposal_id,version) do nothing$$;
revoke all on function procurement.record_payment_proposal_history(jsonb) from public,anon,authenticated;
create function api.upsert_payment_proposal(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_command text:='procurement.payment_proposal.upsert';v_hash text;v_result jsonb;v_before jsonb;v_n jsonb;v_line jsonb;v_old procurement.payment_proposals%rowtype;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if v_id is null or p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('payment.proposal:'||v_id::text,0));
 select * into v_old from procurement.payment_proposals where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  if v_old.status<>'draft' then raise exception using errcode='55000',message='PROPOSAL_NOT_EDITABLE';end if;
  select detail into v_before from api.payment_proposals where id=v_id;perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 v_n:=procurement.normalize_payment_proposal(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,true);
 insert into procurement.payment_proposals(id,tenant_id,legal_entity_id,branch_id,supplier_id,cash_bank_account_id,document_date,currency_code,base_currency_code,exchange_rate_id,exchange_rate,total,base_total,lines,created_by,prepared_by,updated_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,(p_payload->>'supplier_id')::uuid,(p_payload->>'cash_bank_account_id')::uuid,(p_payload->>'document_date')::date,
 v_n->>'currency_code',v_n#>>'{rate,base_currency_code}',(p_payload->>'exchange_rate_id')::uuid,(v_n#>>'{rate,exchange_rate}')::numeric,(v_n->>'total')::numeric,(v_n->>'base_total')::numeric,v_n->'lines',auth.uid(),auth.uid(),auth.uid())
 on conflict(id) do update set supplier_id=excluded.supplier_id,cash_bank_account_id=excluded.cash_bank_account_id,document_date=excluded.document_date,currency_code=excluded.currency_code,
 base_currency_code=excluded.base_currency_code,exchange_rate_id=excluded.exchange_rate_id,exchange_rate=excluded.exchange_rate,total=excluded.total,base_total=excluded.base_total,
 lines=excluded.lines,version=procurement.payment_proposals.version+1,prepared_by=auth.uid(),updated_by=auth.uid(),updated_at=clock_timestamp()
 where procurement.payment_proposals.tenant_id=p_tenant_id and procurement.payment_proposals.legal_entity_id=p_legal_entity_id and procurement.payment_proposals.branch_id=p_branch_id;
 if not found then raise exception using errcode='42501',message='PROPOSAL_SCOPE_INVALID';end if;
 update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
 for v_line in select value from jsonb_array_elements(v_n->'lines') loop
  insert into procurement.payment_claims(tenant_id,legal_entity_id,branch_id,proposal_id,open_item_id,amount)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,v_id,(v_line->>'open_item_id')::uuid,(v_line->>'amount')::numeric);
 end loop;
 select detail into v_result from api.payment_proposals where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'payment_proposal',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id);
 perform procurement.record_payment_proposal_history(v_result);return v_result;
end $$;
revoke all on function api.upsert_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function finance.allocate_payable(p_source uuid,p_target uuid,p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_date date,p_request uuid,p_command uuid,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_s finance.open_items%rowtype;v_t finance.open_items%rowtype;v_sr jsonb;v_tr jsonb;v_rate finance.exchange_rates%rowtype;v_scale integer;
 v_source numeric;v_target numeric;v_sb numeric;v_tb numeric;v_prior numeric;v_fx numeric;v_conversion numeric:=1;v_id uuid:=gen_random_uuid();v_journal uuid;v_control uuid;v_doc jsonb;
begin
 perform 1 from finance.open_items where tenant_id=p_tenant and id in(p_source,p_target) order by id for update;
 select * into v_s from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_source;
 select * into v_t from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_target;
 if v_s.id is null or v_t.id is null or v_s.party_id<>v_t.party_id or v_s.kind<>'AP' or v_t.kind<>'AP' or v_s.original_amount>=0 or v_t.original_amount<=0
  or v_s.base_currency_code<>v_t.base_currency_code or p_date<greatest(v_s.posting_date,v_t.posting_date) then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id in(p_source,p_target) and active and proposal_id is distinct from p_proposal)
 then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id in(p_source,p_target) or target_open_item_id in(p_source,p_target)) and posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 select rounding_scale into v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_source:=sales.wave3_decimal_string(p_payload->'source_amount','source_amount',6,true,0,null);v_target:=sales.wave3_decimal_string(p_payload->'transaction_amount','transaction_amount',6,true,0,null);
 if v_source<=0 or v_target<=0 or round(v_source,v_scale)<>v_source or round(v_target,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_AMOUNT_INVALID';end if;
 if v_s.currency_code<>v_t.currency_code then
  select * into v_rate from finance.exchange_rates where id=(p_payload->>'exchange_rate_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
   and source_currency_code=v_s.currency_code and target_currency_code=v_t.currency_code and effective_date<=p_date and status='active';
  if not found then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_REQUIRED';end if;v_conversion:=v_rate.rate;
 elsif p_payload->>'exchange_rate_id' is not null then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_INVALID';end if;
 if round(v_source*v_conversion,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_CURRENCY_MISMATCH';end if;
 v_sr:=finance.flow_residual(p_tenant,p_source);v_tr:=finance.flow_residual(p_tenant,p_target);
 if v_source>-(v_sr->>'amount')::numeric or v_target>(v_tr->>'amount')::numeric then raise exception using errcode='22023',message='ALLOCATION_EXCEEDED';end if;
 v_prior:=(v_sr->>'amount')::numeric-v_s.original_amount;
 v_sb:=round((-v_s.original_base_amount)*(v_prior+v_source)/(-v_s.original_amount),v_scale)-round((-v_s.original_base_amount)*v_prior/(-v_s.original_amount),v_scale);
 v_prior:=v_t.original_amount-(v_tr->>'amount')::numeric;
 v_tb:=round(v_t.original_base_amount*(v_prior+v_target)/v_t.original_amount,v_scale)-round(v_t.original_base_amount*v_prior/v_t.original_amount,v_scale);
 if v_sb<=0 or v_tb<=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
 v_fx:=v_sb-v_tb;
 if v_fx<>0 then
  select payable_account_id into v_control from procurement.supplier_bill_controls where tenant_id=p_tenant and legal_entity_id=p_entity;
  v_control:=finance.flow_account(p_tenant,p_entity,v_control,'liability',v_s.base_currency_code);
  v_doc:=jsonb_build_object('tenant_id',p_tenant,'legal_entity_id',p_entity,'branch_id',p_branch,'document_date',p_date,'customer_id',v_s.party_id,
   'currency_code',v_s.base_currency_code,'base_currency_code',v_s.base_currency_code,'exchange_rate','1');
  v_journal:=finance.flow_post_journal(v_doc,jsonb_build_array(finance.flow_jline(v_control,-v_fx,-v_fx),
   finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,case when v_fx>0 then 'exchange_loss' else 'exchange_gain' end,v_s.base_currency_code),v_fx,v_fx)),
   'supplier_allocation',v_id,p_request,p_command);
 end if;
 insert into finance.open_item_allocations(id,tenant_id,legal_entity_id,branch_id,source_open_item_id,target_open_item_id,source_amount,transaction_amount,
  source_base_amount,target_base_amount,exchange_difference,exchange_rate_id,conversion_rate,posting_date,reason,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_id,p_tenant,p_entity,p_branch,p_source,p_target,v_source,v_target,v_sb,v_tb,v_fx,v_rate.id,v_conversion,p_date,p_payload->>'reason',v_journal,p_request,p_command,p_request,auth.uid());
 return jsonb_build_object('allocation_id',v_id,'source_open_item_id',p_source,'target_open_item_id',p_target,'source_amount',v_source::text,'transaction_amount',v_target::text,
  'exchange_difference',v_fx::text,'journal_entry_id',v_journal,'source_residual',finance.flow_residual(p_tenant,p_source),'target_residual',finance.flow_residual(p_tenant,p_target));
end $$;
revoke all on function finance.allocate_payable(uuid,uuid,uuid,uuid,uuid,jsonb,date,uuid,uuid,uuid) from public,anon,authenticated;

create function api.post_supplier_payment(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;v_command text:='procurement.supplier_payment.post';v_hash text;v_result jsonb;v_before jsonb;v_n jsonb;
 v_p procurement.payment_proposals%rowtype;v_bank finance.cash_bank_accounts%rowtype;v_control uuid;v_request uuid:=gen_random_uuid();v_open uuid:=gen_random_uuid();
 v_journal uuid;v_number text;v_line jsonb;v_target jsonb;v_sources jsonb:='[]';v_targets jsonb:='[]';v_remaining numeric;v_take numeric;v_target_remaining numeric;
 v_allocations jsonb:='[]';v_i integer;v_source uuid;v_ref text:=trim(p_payload->>'reference');
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.post',p_legal_entity_id,p_branch_id);
 if v_id is null or p_client_timestamp is null or p_legal_entity_id is null or p_branch_id is null or coalesce(length(v_ref),0) not between 1 and 140 then raise exception using errcode='22023',message='PAYMENT_REFERENCE_REQUIRED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_p from procurement.payment_proposals where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='PROPOSAL_NOT_FOUND';end if;
 select detail into v_before from api.payment_proposals where id=v_id;perform core.wave3_assert_expected_version(v_p.version,p_expected_entity_version,v_before);
 if v_p.status<>'approved' then raise exception using errcode='55000',message='PAYMENT_APPROVAL_REQUIRED';end if;
 if v_p.document_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 perform sales.flow_assert_transition(v_p.workflow_snapshot->'lifecycle','approved','posted');
 v_n:=procurement.normalize_payment_proposal(p_tenant_id,p_legal_entity_id,p_branch_id,v_before,true);
 if (v_n->>'total')::numeric<>v_p.total or (v_n->>'base_total')::numeric<>v_p.base_total or (v_n#>>'{rate,exchange_rate}')::numeric<>v_p.exchange_rate or v_n->>'currency_code'<>v_p.currency_code then raise exception using errcode='40001',message='PAYMENT_REAPPROVAL_REQUIRED';end if;
 for v_line in select value from jsonb_array_elements(v_p.lines) loop
  if not exists(select 1 from procurement.payment_claims where tenant_id=p_tenant_id and proposal_id=v_id and open_item_id=(v_line->>'open_item_id')::uuid
   and active and amount=(v_line->>'amount')::numeric) then raise exception using errcode='55000',message='PAYMENT_CLAIM_REQUIRED';end if;
 end loop;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_p.document_date);
 select * into v_bank from finance.cash_bank_accounts where id=v_p.cash_bank_account_id and tenant_id=p_tenant_id for share;
 select payable_account_id into v_control from procurement.supplier_bill_controls where legal_entity_id=p_legal_entity_id and tenant_id=p_tenant_id for share;
 v_control:=finance.flow_account(p_tenant_id,p_legal_entity_id,v_control,'liability',v_p.currency_code);
 v_journal:=finance.flow_post_journal(to_jsonb(v_p)||jsonb_build_object('customer_id',v_p.supplier_id),
  jsonb_build_array(finance.flow_jline(v_control,v_p.total,v_p.base_total),finance.flow_jline(v_bank.account_id,-v_p.total,-v_p.base_total)),
  'supplier_payment',v_id,v_request,p_command_id);
 v_number:=sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'supplier_payment',v_p.document_date,auth.uid());
 insert into finance.open_items(id,tenant_id,legal_entity_id,branch_id,kind,party_id,source_type,source_id,document_number,currency_code,base_currency_code,exchange_rate,
  original_amount,original_base_amount,posting_date,due_date,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_open,p_tenant_id,p_legal_entity_id,p_branch_id,'AP',v_p.supplier_id,'supplier_payment',v_id,v_number,v_p.currency_code,v_p.base_currency_code,v_p.exchange_rate,
  -v_p.total,-v_p.base_total,v_p.document_date,v_p.document_date,v_journal,v_request,p_command_id,v_request,auth.uid());
 for v_line in select value from jsonb_array_elements(v_p.lines) loop
  if v_line->>'kind'='credit' then v_sources:=v_sources||jsonb_build_array(v_line);else v_targets:=v_targets||jsonb_build_array(v_line);end if;
 end loop;
 v_sources:=v_sources||jsonb_build_array(jsonb_build_object('open_item_id',v_open,'amount',v_p.total::text));
 for v_line in select value from jsonb_array_elements(v_sources) loop
  v_source:=(v_line->>'open_item_id')::uuid;v_remaining:=(v_line->>'amount')::numeric;
  for v_i in 0..jsonb_array_length(v_targets)-1 loop
   exit when v_remaining=0;v_target:=v_targets->v_i;v_target_remaining:=(v_target->>'amount')::numeric;v_take:=least(v_remaining,v_target_remaining);
   if v_take=0 then continue;end if;
   v_allocations:=v_allocations||jsonb_build_array(finance.allocate_payable(v_source,(v_target->>'open_item_id')::uuid,p_tenant_id,p_legal_entity_id,p_branch_id,
    jsonb_build_object('source_amount',v_take::text,'transaction_amount',v_take::text,'reason','Approved supplier payment'),v_p.document_date,v_request,p_command_id,v_id));
   v_remaining:=v_remaining-v_take;v_targets:=jsonb_set(v_targets,array[v_i::text,'amount'],to_jsonb((v_target_remaining-v_take)::text));
  end loop;
  if v_remaining<>0 then raise exception using errcode='23514',message='PAYMENT_ALLOCATION_UNBALANCED';end if;
 end loop;
 insert into procurement.supplier_payments(id,tenant_id,legal_entity_id,branch_id,proposal_id,supplier_id,cash_bank_account_id,document_date,document_number,reference,
  currency_code,base_currency_code,exchange_rate,amount,base_amount,journal_entry_id,open_item_id,allocations,source_snapshot,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_p.supplier_id,v_p.cash_bank_account_id,v_p.document_date,v_number,v_ref,v_p.currency_code,v_p.base_currency_code,
  v_p.exchange_rate,v_p.total,v_p.base_total,v_journal,v_open,v_allocations,v_before,v_request,p_command_id,auth.uid());
 update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
 update procurement.payment_proposals set status='posted',version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 perform procurement.record_payment_proposal_history(jsonb_build_object('entity',(select detail from api.payment_proposals where id=v_id)));
 select detail into v_result from api.supplier_payments where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_payment',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id,'{}',
  jsonb_build_object('from_status','approved','to_status','posted'),jsonb_build_array(jsonb_build_object('topic','procurement.supplier_payment.recorded','payload',jsonb_build_object('payment_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function api.post_supplier_payment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.post_supplier_payment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
create function api.transition_payment_proposal(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_actor uuid:=auth.uid();v_id uuid;v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';
 v_command text:='procurement.payment_proposal.transition';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.payment_proposals%rowtype;v_workflow workflow.workflow_definitions%rowtype;
 v_ar workflow.approval_requests%rowtype;v_snapshot jsonb;v_step jsonb;v_first integer;v_to text;
 v_normalized jsonb;v_line jsonb;v_request uuid:=gen_random_uuid();v_reason text:=nullif(trim(coalesce(p_payload->>'reason',p_payload->>'note')),'');
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or jsonb_typeof(p_payload) is distinct from 'object' or (v_action is null)=(v_decision is null) then
 raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_decision is not null then
  perform core.require_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 end if;
 v_id:=(p_payload->>'document_id')::uuid;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 select * into v_doc from procurement.payment_proposals where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select detail into v_before from api.payment_proposals where id=v_id;
 perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
 v_snapshot:=v_doc.workflow_snapshot;
 if v_action='submit' then
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='PROPOSAL_NOT_EDITABLE';end if;
  v_normalized:=procurement.normalize_payment_proposal(p_tenant_id,p_legal_entity_id,p_branch_id,v_before,true);
  if (v_normalized->>'total')::numeric<>v_doc.total or (v_normalized->>'base_total')::numeric<>v_doc.base_total or (v_normalized#>>'{rate,exchange_rate}')::numeric<>v_doc.exchange_rate or v_normalized->>'currency_code'<>v_doc.currency_code then
   raise exception using errcode='40001',message='PAYMENT_REAPPROVAL_REQUIRED';end if;
  -- Recall/rejection release claims. Submission atomically reacquires every item.
  update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
  for v_line in select value from jsonb_array_elements(v_normalized->'lines') loop
   insert into procurement.payment_claims(tenant_id,legal_entity_id,branch_id,proposal_id,open_item_id,amount)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_id,(v_line->>'open_item_id')::uuid,(v_line->>'amount')::numeric);
  end loop;
  select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id
   and document_type='payment_proposal' and status='active' and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
   order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
   'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
   from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
   and (s.currency_code is null or s.currency_code=v_doc.currency_code)
   and (s.minimum_amount is null or s.minimum_amount<=v_doc.total)
   and (s.maximum_amount is null or s.maximum_amount>=v_doc.total);
  select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
  if v_first is null and v_workflow.lifecycle->'requires_approval' is distinct from 'false'::jsonb then
   raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
  v_to:=case when v_first is null then 'approved' else 'pending_approval' end;
  if v_first is null then perform sales.flow_assert_transition(v_workflow.lifecycle,'submitted','approved');end if;
  v_doc.document_number:=coalesce(v_doc.document_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,
    p_branch_id,'payment_proposal',v_doc.document_date,v_actor));
  if v_first is not null then
   insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
    submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,'payment_proposal',v_id,'submitted',v_actor,
    v_workflow.id,v_workflow.revision,v_first,v_doc.total,v_doc.currency_code,p_command_id,v_request,v_request);
  end if;
 elsif v_decision is not null then
  if v_doc.status<>'pending_approval' or v_decision not in ('approved','rejected') then
   raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
  select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type='payment_proposal'
   and document_id=v_id and status='submitted' for update;
  if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
  if v_actor in(v_doc.created_by,v_doc.prepared_by,v_doc.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
  if v_step is null or not exists(select 1 from core.memberships m
   join core.role_assignments ra on ra.membership_id=m.id and ra.tenant_id=m.tenant_id
   join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
   where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
   and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
   and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then
   raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
  if v_decision='rejected' and v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
  insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
   approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
  values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
   v_actor,v_decision,v_reason,v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
  if v_decision='approved' then
   select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
    where (x->>'step_order')::integer>v_ar.current_step;
  end if;
  v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
  update workflow.approval_requests set current_step=coalesce(v_first,current_step),
   status=case when v_first is null then v_to else status end,
   decision_by=case when v_first is null then v_actor else decision_by end,
   decision_note=case when v_first is null then v_reason else decision_note end,
   decided_at=case when v_first is null then clock_timestamp() else decided_at end where id=v_ar.id;
 elsif v_action in('recall','cancel') then
  if v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  if v_action='recall' and v_doc.status not in('pending_approval','rejected','approved') then
   raise exception using errcode='55000',message='PROPOSAL_NOT_RECALLABLE';end if;
  if v_snapshot is null then
   select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
    where tenant_id=p_tenant_id and document_type='payment_proposal' and status='active'
    and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
    order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  end if;
  v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc.status,v_to);
  update workflow.approval_requests set status='cancelled',decision_by=v_actor,decision_note=v_reason,decided_at=clock_timestamp()
   where tenant_id=p_tenant_id and document_type='payment_proposal' and document_id=v_id and status='submitted';
  if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_to in('draft','rejected','cancelled') then
  update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
 end if;
 update procurement.payment_proposals set status=v_to,version=version+1,updated_at=clock_timestamp(),updated_by=v_actor,
  workflow_snapshot=v_snapshot,document_number=v_doc.document_number,
  submitted_by=case when v_action='submit' then v_actor else submitted_by end,
  submitted_at=case when v_action='submit' then clock_timestamp() else submitted_at end where id=v_id;
 select detail into v_entity from api.payment_proposals where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'payment_proposal',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_doc.status=v_to then null else jsonb_build_object('from_status',v_doc.status,'to_status',v_to,'reason',v_reason) end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
 perform procurement.record_payment_proposal_history(v_result);return v_result;
end $$;
revoke all on function api.transition_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.transition_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;



create function api.supplier_payment_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '',
 p_supplier_id uuid default null,p_cash_bank_account_id uuid default null,p_date date default null,p_proposal_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;v_base text;v_search text:=lower(trim(coalesce(p_search,'')));begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='payment_items' then
  if p_supplier_id is null or p_cash_bank_account_id is null or p_date is null then raise exception using errcode='22023',message='PAYMENT_FILTER_REQUIRED';end if;
  select jsonb_agg(sales.flow_exact_json(to_jsonb(x)) order by id) into v_items from (
   select o.id,o.document_number,o.source_id,o.source_type,o.due_date,o.currency_code,
    case when o.original_amount<0 then 'credit' else 'bill' end kind,finance.flow_residual(p_tenant_id,o.id) residual,
    exists(select 1 from procurement.payment_claims c where c.tenant_id=p_tenant_id and c.open_item_id=o.id and c.active and c.proposal_id is distinct from p_proposal_id) claimed
   from finance.open_items o join finance.cash_bank_accounts b on b.id=p_cash_bank_account_id and b.tenant_id=o.tenant_id and b.legal_entity_id=o.legal_entity_id and b.branch_id=o.branch_id
   where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.kind='AP' and o.party_id=p_supplier_id
    and o.currency_code=b.currency_code and b.status='active' and o.posting_date<=p_date and (o.original_amount<0 or o.due_date<=p_date)
    and (p_after is null or o.id>p_after) and (v_search='' or position(v_search in lower(o.document_number))>0)
    and (finance.flow_residual(p_tenant_id,o.id)->>'amount')::numeric<>0
   order by o.id limit 51) x;
 elsif p_resource='payment_suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) into v_items from (
   select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both') and (p_after is null or id>p_after)
    and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51)x;
 elsif p_resource='payment_banks' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name||' · '||currency_code,'currency_code',currency_code) order by id) into v_items from (
   select * from finance.cash_bank_accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active'
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51)x;
 elsif p_resource='payment_rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,'currency_code',source_currency_code,'exchange_rate',rate::text) order by id) into v_items from (
   select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and target_currency_code=v_base
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51)x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next,'base_currency',v_base);
end $$;
revoke all on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) from public,anon;
grant execute on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) to authenticated;
create function api.supplier_statement(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_supplier_id uuid,
 p_currency_code text,p_as_of date,p_buckets integer[] default array[30,60,90])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;v_amount numeric;v_base numeric;v_bucket jsonb;v_count integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_supplier_id is null or p_as_of is null or p_as_of>(now() at time zone 'UTC')::date
 or p_currency_code is null or p_currency_code!~'^[A-Z]{3}$'
 or p_buckets is null or cardinality(p_buckets) not between 1 and 12 or exists(select 1 from unnest(p_buckets) x where x is null or x<=0)
 or p_buckets<>(select array_agg(distinct x order by x) from unnest(p_buckets) x) then
 raise exception using errcode='22023',message='STATEMENT_FILTER_INVALID';end if;
 select count(*) into v_count from (select id from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
 and branch_id=p_branch_id and party_id=p_supplier_id and kind='AP' and currency_code=p_currency_code and posting_date<=p_as_of limit 10001) bounded;
 if v_count>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 with items as (select o.*,finance.flow_residual(p_tenant_id,o.id,p_as_of) residual from finance.open_items o
 where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.party_id=p_supplier_id
 and o.kind='AP' and o.currency_code=p_currency_code and o.posting_date<=p_as_of), rows as (
 select id,source_type,source_id,document_number,currency_code,posting_date,due_date,original_amount::text,original_base_amount::text,
 residual->>'amount' as open_amount,residual->>'base_amount' as open_base_amount,
 case when original_amount<0 then -1 when due_date>=p_as_of then 0 else
 1+(select count(*) from unnest(p_buckets) b where p_as_of-due_date>b) end bucket from items)
 select coalesce(jsonb_agg(to_jsonb(rows) order by posting_date,id),'[]'),coalesce(sum(open_amount::numeric),0),coalesce(sum(open_base_amount::numeric),0)
 into v_rows,v_amount,v_base from rows;
 select coalesce(jsonb_agg(jsonb_build_object('bucket',bucket,'amount',amount::text,'base_amount',base_amount::text) order by bucket),'[]') into v_bucket
 from (select (x->>'bucket')::integer bucket,sum((x->>'open_amount')::numeric) amount,sum((x->>'open_base_amount')::numeric) base_amount
 from jsonb_array_elements(v_rows) x group by (x->>'bucket')::integer) b;
 return jsonb_build_object('supplier_id',p_supplier_id,'currency_code',p_currency_code,'as_of',p_as_of,
 'rows',v_rows,'aging',v_bucket,'bucket_days',p_buckets,'open_amount',v_amount::text,'open_base_amount',v_base::text,
 'basis','posting_date','unapplied_credits_separate',true);end $$;

revoke all on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) from public,anon;
grant execute on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) to authenticated;

-- Candidate only. Shared residual compatibility must be reviewed before application.
insert into core.permissions(code,module,description,privileged) values
 ('finance.payments.allocate','finance','Allocate existing supplier credits and payments.',true),
 ('finance.payments.reverse','finance','Reverse supplier allocations with retained history.',true)
on conflict(code) do nothing;
create or replace function finance.payable_read_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean language sql stable security definer set search_path='' as $$
 select core.is_tenant_member(p_tenant) and (procurement.bill_read_allowed(p_tenant,p_entity,p_branch)
 or core.has_permission(p_tenant,'finance.payments.manage',p_entity,p_branch) or core.has_permission(p_tenant,'finance.payments.post',p_entity,p_branch)
 or core.has_permission(p_tenant,'finance.payments.allocate',p_entity,p_branch) or core.has_permission(p_tenant,'finance.payments.reverse',p_entity,p_branch))$$;
create table finance.allocation_reversals(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 allocation_id uuid not null unique,posting_date date not null,reason text not null check(length(trim(reason)) between 1 and 1000),
 journal_entry_id uuid,source_snapshot jsonb not null,request_id uuid not null,command_id uuid not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,id),
 foreign key(tenant_id,allocation_id) references finance.open_item_allocations(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id)
);
create index allocation_reversal_scope on finance.allocation_reversals(tenant_id,legal_entity_id,branch_id,posting_date,id);
create index allocation_reversal_journal on finance.allocation_reversals(tenant_id,journal_entry_id);
create trigger immutable before update or delete on finance.allocation_reversals for each row execute function workflow.reject_history_mutation();
alter table finance.allocation_reversals enable row level security;
alter table finance.allocation_reversals force row level security;
revoke all on finance.allocation_reversals from public,anon,authenticated;
grant select on finance.allocation_reversals to authenticated;
create policy ap_read on finance.allocation_reversals for select to authenticated using(finance.payable_read_allowed(tenant_id,legal_entity_id,branch_id));

create or replace function finance.flow_residual(p_tenant uuid,p_id uuid,p_as_of date default null)
returns jsonb language sql stable security definer set search_path='' as $$
 with active_allocations as (
  select a.* from finance.open_item_allocations a where a.tenant_id=p_tenant
   and (a.source_open_item_id=p_id or a.target_open_item_id=p_id)
   and (p_as_of is null or a.posting_date<=p_as_of)
   and not exists(select 1 from finance.allocation_reversals r where r.tenant_id=a.tenant_id and r.allocation_id=a.id
    and (p_as_of is null or r.posting_date<=p_as_of))
 ) select jsonb_build_object('amount',(o.original_amount+
  coalesce((select sum(source_amount) from active_allocations where source_open_item_id=o.id),0)-
  coalesce((select sum(transaction_amount+write_off+discount_amount) from active_allocations where target_open_item_id=o.id),0))::text,
 'base_amount',(o.original_base_amount+
  coalesce((select sum(source_base_amount) from active_allocations where source_open_item_id=o.id),0)-
  coalesce((select sum(target_base_amount+adjustment_base_amount) from active_allocations where target_open_item_id=o.id),0))::text)
 from finance.open_items o where o.tenant_id=p_tenant and o.id=p_id and (p_as_of is null or o.posting_date<=p_as_of) $$;

create function api.allocate_supplier_credit(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='finance.supplier_credit.allocate';v_hash text;v_result jsonb;v_source finance.open_items%rowtype;
 v_line jsonb;v_results jsonb:='[]';v_request uuid:=gen_random_uuid();v_date date:=(p_payload->>'posting_date')::date;v_reason text:=trim(p_payload->>'reason');
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.allocate',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000
  or jsonb_typeof(p_payload->'allocations') is distinct from 'array' or jsonb_array_length(p_payload->'allocations') not between 1 and 500
  or p_expected_entity_version is not null then raise exception using errcode='22023',message='ALLOCATION_PAYLOAD_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 if v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 perform 1 from finance.open_items where tenant_id=p_tenant_id and (id=(p_payload->>'source_open_item_id')::uuid or id in
  (select (x->>'target_open_item_id')::uuid from jsonb_array_elements(p_payload->'allocations')x)) order by id for update;
 select * into v_source from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and id=(p_payload->>'source_open_item_id')::uuid and kind='AP' and original_amount<0;
 if not found then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 for v_line in select value from jsonb_array_elements(p_payload->'allocations') loop
  v_results:=v_results||jsonb_build_array(finance.allocate_payable(v_source.id,(v_line->>'target_open_item_id')::uuid,p_tenant_id,p_legal_entity_id,p_branch_id,
   v_line||jsonb_build_object('reason',v_reason),v_date,v_request,p_command_id));
 end loop;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_allocation',p_command_id,p_idempotency_key,v_hash,null,
  jsonb_build_object('id',p_command_id,'source_open_item_id',v_source.id,'allocations',v_results,'source_residual',finance.flow_residual(p_tenant_id,v_source.id)),
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','open','to_status','allocated','reason',v_reason),
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('source_open_item_id',v_source.id))),'[]',v_request,v_request);
end $$;

create function api.reverse_supplier_allocation(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='finance.supplier_allocation.reverse';v_hash text;v_result jsonb;v_a finance.open_item_allocations%rowtype;v_source finance.open_items%rowtype;
 v_id uuid:=gen_random_uuid();v_request uuid:=gen_random_uuid();v_date date:=(p_payload->>'posting_date')::date;v_reason text:=trim(p_payload->>'reason');
 v_journal uuid;v_original finance.journal_entries%rowtype;v_lines jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.reverse',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000
  or p_expected_entity_version is not null then raise exception using errcode='22023',message='ALLOCATION_REVERSAL_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_a from finance.open_item_allocations where id=(p_payload->>'allocation_id')::uuid and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id;
 if not found then raise exception using errcode='P0002',message='ALLOCATION_NOT_FOUND';end if;
 perform 1 from finance.open_items where tenant_id=p_tenant_id and id in(v_a.source_open_item_id,v_a.target_open_item_id) order by id for update;
 select * into v_source from finance.open_items where id=v_a.source_open_item_id and tenant_id=p_tenant_id;
 if v_source.kind<>'AP' then raise exception using errcode='22023',message='AP_ALLOCATION_REQUIRED';end if;
 if exists(select 1 from finance.allocation_reversals where allocation_id=v_a.id) then raise exception using errcode='55000',message='ALLOCATION_ALREADY_REVERSED';end if;
 if v_date<v_a.posting_date or v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='ALLOCATION_REVERSAL_DATE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant_id and open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id) and active)
  then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations a where a.tenant_id=p_tenant_id and (a.source_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)
  or a.target_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)) and a.posting_date>v_date)
  or exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id where r.tenant_id=p_tenant_id
   and (a.source_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id) or a.target_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)) and r.posting_date>v_date)
  then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 if v_a.journal_entry_id is not null then
  select * into v_original from finance.journal_entries where id=v_a.journal_entry_id and tenant_id=p_tenant_id;
  select jsonb_agg(finance.flow_jline(account_id,transaction_credit-transaction_debit,base_credit-base_debit) order by line_number) into v_lines
   from finance.journal_lines where journal_entry_id=v_original.id and tenant_id=p_tenant_id;
  v_journal:=finance.flow_post_journal(to_jsonb(v_original)||jsonb_build_object('document_date',v_date,'customer_id',v_source.party_id),v_lines,
   'supplier_allocation_reversal',v_id,v_request,p_command_id);
 end if;
 insert into finance.allocation_reversals(id,tenant_id,legal_entity_id,branch_id,allocation_id,posting_date,reason,journal_entry_id,source_snapshot,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_a.id,v_date,v_reason,v_journal,sales.flow_exact_json(to_jsonb(v_a)),v_request,p_command_id,auth.uid());
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_allocation_reversal',v_id,p_idempotency_key,v_hash,sales.flow_exact_json(to_jsonb(v_a)),
  jsonb_build_object('id',v_id,'allocation_id',v_a.id,'journal_entry_id',v_journal,'posting_date',v_date,'reason',v_reason,
   'source_residual',finance.flow_residual(p_tenant_id,v_a.source_open_item_id),'target_residual',finance.flow_residual(p_tenant_id,v_a.target_open_item_id)),
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','allocated','to_status','reversed','reason',v_reason),
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('allocation_id',v_a.id))),'[]',v_request,v_request);
end $$;
revoke all on function api.allocate_supplier_credit(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.reverse_supplier_allocation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.allocate_supplier_credit(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.reverse_supplier_allocation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
create or replace function finance.allocate_payable(p_source uuid,p_target uuid,p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_date date,p_request uuid,p_command uuid,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_s finance.open_items%rowtype;v_t finance.open_items%rowtype;v_sr jsonb;v_tr jsonb;v_rate finance.exchange_rates%rowtype;v_scale integer;
 v_source numeric;v_target numeric;v_sb numeric;v_tb numeric;v_prior numeric;v_fx numeric;v_conversion numeric:=1;v_id uuid:=gen_random_uuid();v_journal uuid;v_control uuid;v_doc jsonb;
begin
 perform 1 from finance.open_items where tenant_id=p_tenant and id in(p_source,p_target) order by id for update;
 select * into v_s from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_source;
 select * into v_t from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_target;
 if v_s.id is null or v_t.id is null or v_s.party_id<>v_t.party_id or v_s.kind<>'AP' or v_t.kind<>'AP' or v_s.original_amount>=0 or v_t.original_amount<=0
  or v_s.base_currency_code<>v_t.base_currency_code or p_date<greatest(v_s.posting_date,v_t.posting_date) then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id in(p_source,p_target) and active and proposal_id is distinct from p_proposal)
 then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id in(p_source,p_target) or target_open_item_id in(p_source,p_target)) and posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 if exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id where r.tenant_id=p_tenant
  and (a.source_open_item_id in(p_source,p_target) or a.target_open_item_id in(p_source,p_target)) and r.posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 select rounding_scale into v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_source:=sales.wave3_decimal_string(p_payload->'source_amount','source_amount',6,true,0,null);v_target:=sales.wave3_decimal_string(p_payload->'transaction_amount','transaction_amount',6,true,0,null);
 if v_source<=0 or v_target<=0 or round(v_source,v_scale)<>v_source or round(v_target,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_AMOUNT_INVALID';end if;
 if v_s.currency_code<>v_t.currency_code then
  select * into v_rate from finance.exchange_rates where id=(p_payload->>'exchange_rate_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
   and source_currency_code=v_s.currency_code and target_currency_code=v_t.currency_code and effective_date<=p_date and status='active';
  if not found then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_REQUIRED';end if;v_conversion:=v_rate.rate;
 elsif p_payload->>'exchange_rate_id' is not null then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_INVALID';end if;
 if round(v_source*v_conversion,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_CURRENCY_MISMATCH';end if;
 v_sr:=finance.flow_residual(p_tenant,p_source);v_tr:=finance.flow_residual(p_tenant,p_target);
 if v_source>-(v_sr->>'amount')::numeric or v_target>(v_tr->>'amount')::numeric then raise exception using errcode='22023',message='ALLOCATION_EXCEEDED';end if;
 -- Allocate from remaining carrying value: reversal can restore a different cent distribution.
 v_sb:=round(-(v_sr->>'base_amount')::numeric*v_source/(-(v_sr->>'amount')::numeric),v_scale);
 v_tb:=round((v_tr->>'base_amount')::numeric*v_target/(v_tr->>'amount')::numeric,v_scale);
 if v_sb<=0 or v_tb<=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
 v_fx:=v_sb-v_tb;
 if v_fx<>0 then
  select payable_account_id into v_control from procurement.supplier_bill_controls where tenant_id=p_tenant and legal_entity_id=p_entity;
  v_control:=finance.flow_account(p_tenant,p_entity,v_control,'liability',v_s.base_currency_code);
  v_doc:=jsonb_build_object('tenant_id',p_tenant,'legal_entity_id',p_entity,'branch_id',p_branch,'document_date',p_date,'customer_id',v_s.party_id,
   'currency_code',v_s.base_currency_code,'base_currency_code',v_s.base_currency_code,'exchange_rate','1');
  v_journal:=finance.flow_post_journal(v_doc,jsonb_build_array(finance.flow_jline(v_control,-v_fx,-v_fx),
   finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,case when v_fx>0 then 'exchange_loss' else 'exchange_gain' end,v_s.base_currency_code),v_fx,v_fx)),
   'supplier_allocation',v_id,p_request,p_command);
 end if;
 insert into finance.open_item_allocations(id,tenant_id,legal_entity_id,branch_id,source_open_item_id,target_open_item_id,source_amount,transaction_amount,
  source_base_amount,target_base_amount,exchange_difference,exchange_rate_id,conversion_rate,posting_date,reason,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_id,p_tenant,p_entity,p_branch,p_source,p_target,v_source,v_target,v_sb,v_tb,v_fx,v_rate.id,v_conversion,p_date,p_payload->>'reason',v_journal,p_request,p_command,p_request,auth.uid());
 return jsonb_build_object('allocation_id',v_id,'source_open_item_id',p_source,'target_open_item_id',p_target,'source_amount',v_source::text,'transaction_amount',v_target::text,
  'exchange_difference',v_fx::text,'journal_entry_id',v_journal,'source_residual',finance.flow_residual(p_tenant,p_source),'target_residual',finance.flow_residual(p_tenant,p_target));
end $$;
revoke all on function finance.allocate_payable(uuid,uuid,uuid,uuid,uuid,jsonb,date,uuid,uuid,uuid) from public,anon,authenticated;



create function api.payable_item_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_item_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_item finance.open_items%rowtype;v_rows jsonb;v_next uuid;begin
 if p_legal_entity_id is null or p_branch_id is null or not finance.payable_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 select * into v_item from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and kind='AP' and id=p_item_id;
 if not found then raise exception using errcode='P0002',message='PAYABLE_ITEM_NOT_FOUND';end if;
 select jsonb_agg(detail order by id) into v_rows from (
  select a.id,sales.flow_exact_json(to_jsonb(a))||jsonb_build_object('source_document_number',s.document_number,'target_document_number',t.document_number,
   'reversal',(select sales.flow_exact_json(to_jsonb(r)) from finance.allocation_reversals r where r.allocation_id=a.id)) detail
  from finance.open_item_allocations a join finance.open_items s on s.id=a.source_open_item_id join finance.open_items t on t.id=a.target_open_item_id
  where a.tenant_id=p_tenant_id and (a.source_open_item_id=p_item_id or a.target_open_item_id=p_item_id) and (p_after is null or a.id>p_after) order by a.id limit 51)x;
 v_rows:=coalesce(v_rows,'[]');if jsonb_array_length(v_rows)>50 then v_next:=(v_rows->49->>'id')::uuid;v_rows:=v_rows-50;end if;
 return jsonb_build_object('item',sales.flow_exact_json(to_jsonb(v_item))||finance.flow_residual(p_tenant_id,p_item_id),'allocations',v_rows,'next_cursor',v_next);
end $$;
revoke all on function api.payable_item_detail(uuid,uuid,uuid,uuid,uuid) from public,anon;
grant execute on function api.payable_item_detail(uuid,uuid,uuid,uuid,uuid) to authenticated;

create function api.payable_allocation_targets(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_source_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_source finance.open_items%rowtype;v_items jsonb;v_next uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.allocate',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='22023',message='SCOPE_REQUIRED';end if;
 select * into v_source from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_source_id and kind='AP' and original_amount<0;
 if not found then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 select jsonb_agg(detail order by id) into v_items from (
  select o.id,sales.flow_exact_json(to_jsonb(o))||finance.flow_residual(p_tenant_id,o.id) detail from finance.open_items o
  where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.party_id=v_source.party_id
   and o.kind='AP' and o.original_amount>0 and (p_after is null or o.id>p_after)
   and (finance.flow_residual(p_tenant_id,o.id)->>'amount')::numeric>0
   and not exists(select 1 from procurement.payment_claims c where c.tenant_id=p_tenant_id and c.open_item_id=o.id and c.active)
  order by o.id limit 51)x;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next);
end $$;
revoke all on function api.payable_allocation_targets(uuid,uuid,uuid,uuid,uuid) from public,anon;
grant execute on function api.payable_allocation_targets(uuid,uuid,uuid,uuid,uuid) to authenticated;
create or replace function api.supplier_statement(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_supplier_id uuid,
 p_currency_code text,p_as_of date,p_buckets integer[] default array[30,60,90])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;v_amount numeric;v_base numeric;v_bucket jsonb;v_count integer;begin
 if not finance.payable_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 if p_branch_id is null or p_supplier_id is null or p_as_of is null or p_as_of>(now() at time zone 'UTC')::date
 or p_currency_code is null or p_currency_code!~'^[A-Z]{3}$'
 or p_buckets is null or cardinality(p_buckets) not between 1 and 12 or exists(select 1 from unnest(p_buckets) x where x is null or x<=0)
 or p_buckets<>(select array_agg(distinct x order by x) from unnest(p_buckets) x) then
 raise exception using errcode='22023',message='STATEMENT_FILTER_INVALID';end if;
 select count(*) into v_count from (select id from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
 and branch_id=p_branch_id and party_id=p_supplier_id and kind='AP' and currency_code=p_currency_code and posting_date<=p_as_of limit 10001) bounded;
 if v_count>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 with items as (select o.*,finance.flow_residual(p_tenant_id,o.id,p_as_of) residual from finance.open_items o
 where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.party_id=p_supplier_id
 and o.kind='AP' and o.currency_code=p_currency_code and o.posting_date<=p_as_of), rows as (
 select id,source_type,source_id,document_number,currency_code,posting_date,due_date,original_amount::text,original_base_amount::text,
 residual->>'amount' as open_amount,residual->>'base_amount' as open_base_amount,
 case when original_amount<0 then -1 when due_date>=p_as_of then 0 else
 1+(select count(*) from unnest(p_buckets) b where p_as_of-due_date>b) end bucket from items)
 select coalesce(jsonb_agg(to_jsonb(rows) order by posting_date,id),'[]'),coalesce(sum(open_amount::numeric),0),coalesce(sum(open_base_amount::numeric),0)
 into v_rows,v_amount,v_base from rows;
 select coalesce(jsonb_agg(jsonb_build_object('bucket',bucket,'amount',amount::text,'base_amount',base_amount::text) order by bucket),'[]') into v_bucket
 from (select (x->>'bucket')::integer bucket,sum((x->>'open_amount')::numeric) amount,sum((x->>'open_base_amount')::numeric) base_amount
 from jsonb_array_elements(v_rows) x group by (x->>'bucket')::integer) b;
 return jsonb_build_object('supplier_id',p_supplier_id,'currency_code',p_currency_code,'as_of',p_as_of,
 'rows',v_rows,'aging',v_bucket,'bucket_days',p_buckets,'open_amount',v_amount::text,'open_base_amount',v_base::text,
 'basis','posting_date','unapplied_credits_separate',true);end $$;

revoke all on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) from public,anon;
grant execute on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) to authenticated;


create function api.payable_allocation_rates(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_source_currency text,p_target_currency text,p_date date,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.allocate',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_date is null then raise exception using errcode='22023',message='RATE_FILTER_INVALID';end if;
 select jsonb_agg(jsonb_build_object('id',id,'rate',rate::text,'date',effective_date) order by id) into v_items from (
  select id,rate,effective_date from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active'
   and source_currency_code=p_source_currency and target_currency_code=p_target_currency and effective_date<=p_date and (p_after is null or id>p_after) order by id limit 51)x;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next);
end $$;
revoke all on function api.payable_allocation_rates(uuid,uuid,uuid,text,text,date,uuid) from public,anon;
grant execute on function api.payable_allocation_rates(uuid,uuid,uuid,text,text,date,uuid) to authenticated;
create or replace function api.supplier_payment_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '',
 p_supplier_id uuid default null,p_cash_bank_account_id uuid default null,p_date date default null,p_proposal_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;v_base text;v_search text:=lower(trim(coalesce(p_search,'')));begin
 if p_resource='payment_suppliers' then
  if not finance.payable_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 else perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);end if;
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='payment_items' then
  if p_supplier_id is null or p_cash_bank_account_id is null or p_date is null then raise exception using errcode='22023',message='PAYMENT_FILTER_REQUIRED';end if;
  select jsonb_agg(sales.flow_exact_json(to_jsonb(x)) order by id) into v_items from (
   select o.id,o.document_number,o.source_id,o.source_type,o.due_date,o.currency_code,
    case when o.original_amount<0 then 'credit' else 'bill' end kind,finance.flow_residual(p_tenant_id,o.id) residual,
    exists(select 1 from procurement.payment_claims c where c.tenant_id=p_tenant_id and c.open_item_id=o.id and c.active and c.proposal_id is distinct from p_proposal_id) claimed
   from finance.open_items o join finance.cash_bank_accounts b on b.id=p_cash_bank_account_id and b.tenant_id=o.tenant_id and b.legal_entity_id=o.legal_entity_id and b.branch_id=o.branch_id
   where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.kind='AP' and o.party_id=p_supplier_id
    and o.currency_code=b.currency_code and b.status='active' and o.posting_date<=p_date and (o.original_amount<0 or o.due_date<=p_date)
    and (p_after is null or o.id>p_after) and (v_search='' or position(v_search in lower(o.document_number))>0)
    and (finance.flow_residual(p_tenant_id,o.id)->>'amount')::numeric<>0
   order by o.id limit 51) x;
 elsif p_resource='payment_suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) into v_items from (
   select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both') and (p_after is null or id>p_after)
    and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51)x;
 elsif p_resource='payment_banks' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name||' · '||currency_code,'currency_code',currency_code) order by id) into v_items from (
   select * from finance.cash_bank_accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active'
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51)x;
 elsif p_resource='payment_rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,'currency_code',source_currency_code,'exchange_rate',rate::text) order by id) into v_items from (
   select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and target_currency_code=v_base
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51)x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next,'base_currency',v_base);
end $$;
revoke all on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) from public,anon;
grant execute on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) to authenticated;


-- AC-312 candidate. Immutable physical returns and supplier debit effects.
create table procurement.purchase_returns(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 source_kind text not null check(source_kind in('bill','receipt')),source_id uuid not null,supplier_id uuid not null,
 document_date date not null,document_number text not null,reference text not null,reason text not null,
 currency_code text not null,base_currency_code text not null,exchange_rate numeric(20,10) not null,
 total numeric(20,6) not null,base_total numeric(20,6) not null,tax_total numeric(20,6) not null,
 stock_movement_id uuid,journal_entry_id uuid,open_item_id uuid,source_snapshot jsonb not null,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id)
);
create index purchase_returns_scope_page on procurement.purchase_returns(tenant_id,legal_entity_id,branch_id,id);
create index purchase_returns_source on procurement.purchase_returns(tenant_id,source_kind,source_id,document_date);
create table procurement.purchase_return_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,return_id uuid not null,
 bill_line_id uuid,receipt_line_id uuid,quantity numeric(20,6) not null check(quantity>0),detail jsonb not null,
 foreign key(tenant_id,return_id) references procurement.purchase_returns(tenant_id,id) deferrable initially deferred,
 foreign key(tenant_id,bill_line_id) references procurement.supplier_bill_lines(tenant_id,id),
 foreign key(tenant_id,receipt_line_id) references procurement.goods_receipt_lines(tenant_id,id),
 check(bill_line_id is not null or receipt_line_id is not null)
);
create index purchase_return_line_parent on procurement.purchase_return_lines(tenant_id,return_id);
create index purchase_return_line_bill on procurement.purchase_return_lines(tenant_id,bill_line_id);
create index purchase_return_line_receipt on procurement.purchase_return_lines(tenant_id,receipt_line_id);
do $$declare t text;begin
 foreach t in array array['purchase_returns','purchase_return_lines'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  execute format('create policy return_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,''procurement.returns.post'',legal_entity_id,branch_id))',t);
  execute format('revoke all on procurement.%I from public,anon,authenticated',t);
  execute format('grant select on procurement.%I to authenticated',t);
  execute format('create trigger immutable before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);
 end loop;
end $$;
create view api.purchase_returns with(security_invoker=true) as select r.id,r.tenant_id,r.legal_entity_id,r.branch_id,
 sales.flow_exact_json(to_jsonb(r))||jsonb_build_object('status','posted','lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.purchase_return_lines l where l.return_id=r.id),'[]')) detail
 from procurement.purchase_returns r;
grant select on api.purchase_returns to authenticated;
alter table inventory.stock_movements drop constraint stock_movements_movement_kind_check;
alter table inventory.stock_movements add constraint stock_movements_movement_kind_check
 check(movement_kind in('opening','delivery','sales_return','goods_receipt','goods_receipt_reversal','purchase_return'));

-- Extend candidate helpers without changing installed migration files. Fail on drift.
do $$declare v text;v_old text;begin
 v:=pg_get_functiondef('procurement.normalize_bill(uuid,uuid,uuid,jsonb)'::regprocedure);
 v_old:='v_available:=v_rl.accepted_quantity-v_already;';
 if position(v_old in v)=0 then raise exception 'BILL_HELPER_CONTRACT_DRIFT';end if;
 v:=replace(v,v_old,$s$v_already:=v_already+coalesce((select sum(quantity) from procurement.purchase_return_lines where receipt_line_id=v_rl.id and bill_line_id is null),0);
   v_available:=v_rl.accepted_quantity-v_already;$s$);execute v;
 v:=pg_get_functiondef('api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)'::regprocedure);
 v_old:='if exists(select 1 from procurement.purchase_order_lines l join procurement.goods_receipt_lines r';
 if position(v_old in v)=0 then raise exception 'RECEIPT_HELPER_CONTRACT_DRIFT';end if;
 v:=replace(v,v_old,$s$if exists(select 1 from procurement.purchase_return_lines l join procurement.goods_receipt_lines r on r.id=l.receipt_line_id where r.receipt_id=v_id) then
 raise exception using errcode='55000',message='RETURNED_RECEIPT_CANNOT_REVERSE';end if;
 if exists(select 1 from procurement.purchase_order_lines l join procurement.goods_receipt_lines r$s$);execute v;
end $$;

create function api.post_purchase_return(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_source_id uuid:=(p_payload->>'source_id')::uuid;v_kind text:=p_payload->>'source_kind';
 v_date date:=(p_payload->>'document_date')::date;v_reason text:=trim(p_payload->>'reason');v_ref text:=trim(p_payload->>'reference');
 v_command text:='procurement.purchase_return.post';v_hash text;v_result jsonb;v_request uuid:=gen_random_uuid();v_number text;
 v_bill procurement.supplier_bills%rowtype;v_bl procurement.supplier_bill_lines%rowtype;v_receipt procurement.goods_receipts%rowtype;v_rl procurement.goods_receipt_lines%rowtype;
 v_controls procurement.supplier_bill_controls%rowtype;v_balance inventory.stock_balances%rowtype;v_value inventory.stock_valuations%rowtype;v_original inventory.stock_movement_lines%rowtype;
 v_doc jsonb;v_input jsonb;v_detail jsonb;v_lines jsonb:='[]';v_jlines jsonb:='[]';v_seen uuid[]:='{}';v_source_line uuid;v_line uuid;v_order uuid;v_product uuid;
 v_q numeric;v_limit numeric;v_prior numeric;v_consumed numeric;v_net numeric;v_tax numeric;v_base_tax numeric;v_base_net numeric;v_base_q numeric;v_cost numeric;v_tx_cost numeric;
 v_total numeric:=0;v_base_total numeric:=0;v_tax_total numeric:=0;v_credits numeric:=0;v_base_credits numeric:=0;v_prior_total numeric;v_prior_base numeric;
 v_supplier uuid;v_currency text;v_base text;v_rate numeric;v_scale integer;v_account uuid;v_ap uuid;v_tax_account uuid;v_grni uuid;
 v_warehouse uuid;v_movement uuid;v_journal uuid;v_open uuid;v_serials uuid[];v_serial uuid;v_lot uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.returns.post',p_legal_entity_id,p_branch_id);
 if p_client_timestamp is null or v_id is null or v_source_id is null or v_kind is null or v_kind not in('bill','receipt') or v_date is null
 or coalesce(length(v_reason),0) not between 1 and 1000 or coalesce(length(v_ref),0) not between 1 and 140
 or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500
 then raise exception using errcode='22023',message='RETURN_INPUT_INVALID';end if;
 if p_expected_entity_version is not null then raise exception using errcode='22023',message='IMMUTABLE_SOURCE_VERSION_NOT_SUPPORTED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('purchase.return:'||v_id::text,0));
 if exists(select 1 from procurement.purchase_returns where id=v_id) then raise exception using errcode='23505',message='RETURN_ALREADY_POSTED';end if;
 if v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id;
 select * into v_controls from procurement.supplier_bill_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id;
 if not found then raise exception using errcode='55000',message='BILL_CONTROLS_REQUIRED';end if;
 if v_kind='bill' then
  select * into v_bill from procurement.supplier_bills where id=v_source_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='posted' for update;
  if not found or v_bill.document_date>v_date then raise exception using errcode='22023',message='RETURN_SOURCE_INVALID';end if;
  v_supplier:=v_bill.supplier_id;v_currency:=v_bill.currency_code;v_rate:=v_bill.exchange_rate;v_doc:=sales.flow_exact_json(to_jsonb(v_bill));
  select account_id into v_ap from finance.journal_lines where journal_entry_id=v_bill.journal_entry_id and source_line_id is null and base_credit>0
   and account_id in(select id from finance.accounts where account_type='liability');
  if v_ap is null then raise exception using errcode='55000',message='SOURCE_AP_LINK_INVALID';end if;
 else
  select * into v_receipt from procurement.goods_receipts where id=v_source_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id;
  if not found or v_receipt.document_date>v_date then raise exception using errcode='22023',message='RETURN_SOURCE_INVALID';end if;
  v_supplier:=(v_receipt.source_snapshot->>'supplier_id')::uuid;v_currency:=v_receipt.currency_code;v_rate:=v_receipt.exchange_rate;v_doc:=sales.flow_exact_json(to_jsonb(v_receipt));
 end if;
 -- Same order as bill posting and receipt reversal. Lock every affected PO before stock.
 if v_doc->>'base_currency_code' is distinct from v_base then raise exception using errcode='55000',message='SOURCE_BASE_CURRENCY_CHANGED';end if;
 for v_order in select distinct r.order_id from procurement.goods_receipts r where
  (v_kind='receipt' and r.id=v_source_id) or (v_kind='bill' and r.id in(select l.receipt_id from procurement.goods_receipt_lines l join procurement.supplier_bill_lines b on b.receipt_line_id=l.id where b.bill_id=v_source_id)) order by 1 loop
  perform 1 from procurement.purchase_orders where id=v_order for update;
  perform 1 from procurement.purchase_order_lines where order_id=v_order order by id for update;
 end loop;
 if exists(select 1 from procurement.purchase_returns where source_kind=v_kind and source_id=v_source_id and document_date>v_date)
 then raise exception using errcode='55000',message='LATER_RETURN_REQUIRES_REVIEW';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_controls.variance_account_id,'expense',v_currency);
 -- Prelock warehouse/product pairs in the same canonical order as stock consumers.
 for v_detail in select d from (select distinct jsonb_build_object('warehouse_id',r.warehouse_id,'product_id',l.detail->>'product_id') d
  from procurement.goods_receipt_lines l join procurement.goods_receipts r on r.id=l.receipt_id
  where (v_kind='receipt' and r.id=v_source_id) or (v_kind='bill' and l.id in(select receipt_line_id from procurement.supplier_bill_lines where bill_id=v_source_id))) pairs
  order by d->>'warehouse_id',d->>'product_id' loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||(v_detail->>'warehouse_id')||':'||(v_detail->>'product_id'),0));
 end loop;
 for v_input in select value from jsonb_array_elements(p_payload->'lines') order by value->>'source_line_id' loop
  v_line:=(v_input->>'line_id')::uuid;v_source_line:=(v_input->>'source_line_id')::uuid;v_rl:=null;v_bl:=null;v_original:=null;v_tax:=0;v_base_tax:=0;v_base_net:=0;
  if v_line is null or v_source_line is null or v_source_line=any(v_seen) then raise exception using errcode='22023',message='RETURN_LINE_IDENTITIES_INVALID';end if;
  v_seen:=array_append(v_seen,v_source_line);
  v_q:=sales.wave3_decimal_string(v_input->'quantity','quantity',6,true,0,null);
  if v_q<=0 then raise exception using errcode='22023',message='RETURN_QUANTITY_UNAVAILABLE';end if;
  if v_kind='bill' then
   select * into v_bl from procurement.supplier_bill_lines where id=v_source_line and bill_id=v_source_id;
   if not found then raise exception using errcode='22023',message='RETURN_SOURCE_LINE_INVALID';end if;
   select coalesce(sum(quantity),0) into v_prior from procurement.purchase_return_lines where bill_line_id=v_bl.id;
   v_limit:=v_bl.quantity;
   if v_q>v_limit-v_prior then raise exception using errcode='22023',message='RETURN_QUANTITY_UNAVAILABLE';end if;
   v_net:=round((v_bl.detail->>'net_amount')::numeric*(v_prior+v_q)/v_limit,v_scale)-round((v_bl.detail->>'net_amount')::numeric*v_prior/v_limit,v_scale);
   v_tax:=round((v_bl.detail->>'tax_amount')::numeric*(v_prior+v_q)/v_limit,v_scale)-round((v_bl.detail->>'tax_amount')::numeric*v_prior/v_limit,v_scale);
   if (v_bl.detail->>'tax_amount')::numeric>0 then
    select j.account_id,j.base_debit into v_tax_account,v_base_tax from finance.journal_lines j join finance.accounts a on a.id=j.account_id
     where j.journal_entry_id=v_bill.journal_entry_id and j.source_line_id=v_bl.id and a.account_type='asset' and j.base_debit>0;
    if v_tax_account is null then raise exception using errcode='55000',message='SOURCE_TAX_LINK_INVALID';end if;
    v_base_tax:=round(v_base_tax*(v_prior+v_q)/v_limit,v_scale)-round(v_base_tax*v_prior/v_limit,v_scale);
   end if;
   if v_bl.receipt_line_id is not null then select * into v_rl from procurement.goods_receipt_lines where id=v_bl.receipt_line_id;
   else v_account:=(v_bl.detail->>'expense_account_id')::uuid;v_base_net:=round(v_net*v_rate,v_scale);end if;
  else
   select * into v_rl from procurement.goods_receipt_lines where id=v_source_line and receipt_id=v_source_id;
   if not found then raise exception using errcode='22023',message='RETURN_SOURCE_LINE_INVALID';end if;
   select coalesce(sum(l.quantity),0) into v_consumed from procurement.supplier_bill_lines l join procurement.supplier_bills b on b.id=l.bill_id where l.receipt_line_id=v_rl.id and b.status='posted';
   v_consumed:=v_consumed+coalesce((select sum(quantity) from procurement.purchase_return_lines where receipt_line_id=v_rl.id and bill_line_id is null),0);
   if v_q>v_rl.accepted_quantity-v_consumed then raise exception using errcode='22023',message='RETURN_QUANTITY_UNAVAILABLE';end if;
   v_net:=round(v_rl.net_amount*(v_consumed+v_q)/v_rl.accepted_quantity,v_scale)-round(v_rl.net_amount*v_consumed/v_rl.accepted_quantity,v_scale);
   v_base_net:=round(v_rl.base_amount*(v_consumed+v_q)/v_rl.accepted_quantity,v_scale)-round(v_rl.base_amount*v_consumed/v_rl.accepted_quantity,v_scale);
   select account_id into v_grni from finance.journal_lines where journal_entry_id=v_receipt.journal_entry_id and source_line_id is null and base_credit>0;
   if v_net<>0 or v_base_net<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_grni,v_net,v_base_net,v_line));end if;
   v_base_total:=v_base_total+v_base_net;
  end if;
  if v_rl.id is not null then
   select * into v_receipt from procurement.goods_receipts where id=v_rl.receipt_id;
   if exists(select 1 from procurement.goods_receipt_reversals where receipt_id=v_receipt.id) then raise exception using errcode='22023',message='RETURN_SOURCE_INVALID';end if;
   if v_receipt.document_date>v_date or exists(select 1 from procurement.supplier_bill_lines l join procurement.supplier_bills b on b.id=l.bill_id where l.receipt_line_id=v_rl.id and b.status='posted' and b.document_date>v_date)
   then raise exception using errcode='55000',message='LATER_RECEIPT_EVENT_REQUIRES_REVIEW';end if;
   if v_q>v_rl.accepted_quantity-coalesce((select sum(quantity) from procurement.purchase_return_lines where receipt_line_id=v_rl.id),0)
   then raise exception using errcode='22023',message='RETURN_QUANTITY_UNAVAILABLE';end if;
   v_base_q:=v_q*(v_rl.detail->>'conversion_numerator')::numeric/(v_rl.detail->>'conversion_denominator')::numeric;
   perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_rl.detail->>'product_id')::uuid,(v_rl.detail->>'unit_id')::uuid,
    v_input->'quantity',v_rl.detail->'conversion_numerator',v_rl.detail->'conversion_denominator');
   if round(v_base_q,6)<>v_base_q or not exists(select 1 from inventory.units where id=(v_rl.detail->>'unit_id')::uuid and round(v_q,precision)=v_q)
   then raise exception using errcode='22023',message='RETURN_UNIT_PRECISION_INVALID';end if;
   v_product:=(v_rl.detail->>'product_id')::uuid;v_account:=(v_rl.detail->>'account_id')::uuid;
   select * into v_original from inventory.stock_movement_lines where stock_movement_id=v_receipt.stock_movement_id and source_line_id=v_rl.id;
  end if;
  if jsonb_typeof(coalesce(v_input->'serial_ids','[]'))<>'array' or jsonb_array_length(coalesce(v_input->'serial_ids','[]'))>1000 then raise exception using errcode='22023',message='SERIAL_LIST_INVALID';end if;
  select coalesce(array_agg(x::uuid order by x),'{}') into v_serials from jsonb_array_elements_text(coalesce(v_input->'serial_ids','[]')) x;
  v_cost:=0;v_tx_cost:=0;v_lot:=null;
  if v_original.id is not null then
   if v_warehouse is not null and v_warehouse<>v_receipt.warehouse_id then raise exception using errcode='22023',message='RETURN_SINGLE_WAREHOUSE_REQUIRED';end if;
   v_warehouse:=v_receipt.warehouse_id;
   select * into v_balance from inventory.stock_balances where tenant_id=p_tenant_id and warehouse_id=v_warehouse and product_id=v_product for update;
   select * into v_value from inventory.stock_valuations where stock_balance_id=v_balance.id for update;
   if v_balance.id is null or v_value.id is null or v_balance.on_hand_quantity-v_balance.allocated_quantity<v_base_q then raise exception using errcode='55000',message='RETURN_STOCK_UNAVAILABLE';end if;
   if exists(select 1 from inventory.stock_movement_lines where tenant_id=p_tenant_id and warehouse_id=v_warehouse and product_id=v_product and posting_date>v_date)
   then raise exception using errcode='55000',message='BACKDATED_STOCK_RETURN_REQUIRES_REVIEW';end if;
   v_lot:=v_original.lot_id;
   if v_lot is not null then
    update inventory.lot_balances set on_hand_quantity=on_hand_quantity-v_base_q,updated_by=auth.uid() where tenant_id=p_tenant_id and warehouse_id=v_warehouse and lot_id=v_lot and on_hand_quantity>=v_base_q;
    if not found then raise exception using errcode='55000',message='RETURN_LOT_UNAVAILABLE';end if;
   end if;
   if cardinality(v_original.serial_ids)>0 then
    if trunc(v_base_q)<>v_base_q or cardinality(v_serials)<>v_base_q or cardinality(v_serials)<>(select count(distinct s) from unnest(v_serials)s)
    then raise exception using errcode='22023',message='RETURN_SERIAL_INVALID';end if;
    foreach v_serial in array v_serials loop
     if not v_serial=any(v_original.serial_ids) then raise exception using errcode='22023',message='RETURN_SERIAL_INVALID';end if;
     update inventory.serials set status='disposed',updated_by=auth.uid() where id=v_serial and tenant_id=p_tenant_id and warehouse_id=v_warehouse and status='available';
     if not found then raise exception using errcode='55000',message='RETURN_SERIAL_UNAVAILABLE';end if;
    end loop;
   elsif cardinality(v_serials)>0 then raise exception using errcode='22023',message='RETURN_SERIAL_INVALID';end if;
   v_cost:=case when v_base_q=v_balance.on_hand_quantity then v_value.carrying_value else round(v_value.carrying_value*v_base_q/v_balance.on_hand_quantity,6) end;
   v_tx_cost:=round(v_cost/v_rate,v_scale);
   update inventory.stock_balances set on_hand_quantity=on_hand_quantity-v_base_q,updated_by=auth.uid() where id=v_balance.id;
   update inventory.stock_valuations set carrying_value=carrying_value-v_cost,updated_by=auth.uid() where id=v_value.id;
   if v_movement is null then
    v_movement:=gen_random_uuid();
    insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
    values(v_movement,p_tenant_id,p_legal_entity_id,p_branch_id,'purchase_return',v_id,v_warehouse,v_date,'purchase_return',v_request,p_command_id,v_request,auth.uid());
   end if;
   insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,original_movement_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_movement,v_warehouse,v_product,v_line,v_original.id,-v_base_q,-v_cost,v_lot,v_serials,v_date,auth.uid());
  else
   if cardinality(v_serials)>0 then raise exception using errcode='22023',message='RETURN_SERIAL_INVALID';end if;
   v_tx_cost:=v_net;v_cost:=case when v_kind='receipt' then v_base_net else round(v_net*v_rate,v_scale) end;
  end if;
  if v_cost<>0 or v_tx_cost<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_account,-v_tx_cost,-v_cost,v_line));end if;
  if v_tax<>0 or v_base_tax<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_tax_account,-v_tax,-v_base_tax,v_line));end if;
  v_credits:=v_credits+v_tx_cost+v_tax;v_base_credits:=v_base_credits+v_cost+v_base_tax;
  v_total:=v_total+v_net+v_tax;v_tax_total:=v_tax_total+v_tax;
  v_detail:=jsonb_build_object('line_id',v_line,'source_line_id',v_source_line,'bill_line_id',v_bl.id,'receipt_line_id',v_rl.id,
   'description',coalesce(v_bl.detail->>'description',v_rl.detail->>'description'),'quantity',v_q::text,'base_quantity',case when v_original.id is not null then v_base_q else 0 end::text,
   'net_amount',v_net::text,'tax_amount',v_tax::text,'lot_id',v_lot,'serial_ids',to_jsonb(v_serials),'source_snapshot',coalesce(v_bl.detail,v_rl.detail));
  insert into procurement.purchase_return_lines(id,tenant_id,legal_entity_id,branch_id,return_id,bill_line_id,receipt_line_id,quantity,detail)
  values(v_line,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_bl.id,v_rl.id,v_q,v_detail);
 end loop;
 if v_kind='bill' then
  select coalesce(sum(total),0),coalesce(sum(base_total),0) into v_prior_total,v_prior_base from procurement.purchase_returns where source_kind='bill' and source_id=v_source_id;
  v_base_total:=round((v_prior_total+v_total)*v_rate,v_scale)-v_prior_base;
  if v_total<=0 or v_base_total<=0 then raise exception using errcode='22023',message='RETURN_AMOUNT_BELOW_PRECISION';end if;
  v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_ap,v_total,v_base_total));
 end if;
 if v_credits<>v_total or v_base_credits<>v_base_total then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_controls.variance_account_id,v_credits-v_total,v_base_credits-v_base_total));end if;
 v_journal:=finance.flow_post_journal(jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'document_date',v_date,'currency_code',v_currency,'base_currency_code',v_base,'exchange_rate',v_rate::text,'customer_id',v_supplier),v_jlines,'purchase_return',v_id,v_request,p_command_id);
 v_number:=sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'purchase_return',v_date,auth.uid());
 if v_kind='bill' then
  v_open:=gen_random_uuid();
  insert into finance.open_items(id,tenant_id,legal_entity_id,branch_id,kind,party_id,source_type,source_id,document_number,currency_code,base_currency_code,exchange_rate,
   original_amount,original_base_amount,posting_date,due_date,journal_entry_id,request_id,command_id,correlation_id,created_by)
  values(v_open,p_tenant_id,p_legal_entity_id,p_branch_id,'AP',v_supplier,'purchase_return',v_id,v_number,v_currency,v_base,v_rate,-v_total,-v_base_total,v_date,v_date,v_journal,v_request,p_command_id,v_request,auth.uid());
 end if;
 insert into procurement.purchase_returns(id,tenant_id,legal_entity_id,branch_id,source_kind,source_id,supplier_id,document_date,document_number,reference,reason,
  currency_code,base_currency_code,exchange_rate,total,base_total,tax_total,stock_movement_id,journal_entry_id,open_item_id,source_snapshot,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,v_source_id,v_supplier,v_date,v_number,v_ref,v_reason,v_currency,v_base,v_rate,v_total,v_base_total,v_tax_total,v_movement,v_journal,v_open,v_doc,v_request,p_command_id,auth.uid());
 select detail into v_result from api.purchase_returns where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_return',v_id,p_idempotency_key,v_hash,null,v_result,p_legal_entity_id,p_branch_id,'{}',
  jsonb_build_object('from_status','draft','to_status','posted','reason',v_reason),jsonb_build_array(jsonb_build_object('topic','procurement.return.posted','payload',jsonb_build_object('return_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function api.post_purchase_return(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.post_purchase_return(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.purchase_return_sources(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_kind text,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;v_next uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.returns.post',p_legal_entity_id,p_branch_id);
 if p_kind not in('bill','receipt') or p_kind is null or length(coalesce(p_search,''))>100 then raise exception using errcode='22023',message='RETURN_SEARCH_INVALID';end if;
 with candidates as (
  select b.id,b.document_number,b.document_date,b.currency_code,p.display_name supplier_name from procurement.supplier_bills b join crm.parties p on p.id=b.supplier_id
  where p_kind='bill' and b.tenant_id=p_tenant_id and b.legal_entity_id=p_legal_entity_id and b.branch_id=p_branch_id and b.status='posted'
   and (p_after is null or b.id>p_after) and (coalesce(p_search,'')='' or b.document_number ilike '%'||p_search||'%' or p.display_name ilike '%'||p_search||'%')
   and exists(select 1 from procurement.supplier_bill_lines l where l.bill_id=b.id and l.quantity>coalesce((select sum(quantity) from procurement.purchase_return_lines where bill_line_id=l.id),0))
  union all
  select r.id,r.document_number,r.document_date,r.currency_code,p.display_name from procurement.goods_receipts r join crm.parties p on p.id=(r.source_snapshot->>'supplier_id')::uuid
  where p_kind='receipt' and r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and r.branch_id=p_branch_id
   and (p_after is null or r.id>p_after) and not exists(select 1 from procurement.goods_receipt_reversals where receipt_id=r.id)
   and (coalesce(p_search,'')='' or r.document_number ilike '%'||p_search||'%' or p.display_name ilike '%'||p_search||'%')
   and exists(select 1 from procurement.goods_receipt_lines l where l.receipt_id=r.id and l.accepted_quantity>
    coalesce((select sum(b.quantity) from procurement.supplier_bill_lines b join procurement.supplier_bills h on h.id=b.bill_id where b.receipt_line_id=l.id and h.status='posted'),0)
    +coalesce((select sum(quantity) from procurement.purchase_return_lines where receipt_line_id=l.id and bill_line_id is null),0))
 ), bounded as(select * from candidates order by id limit 51)
 select coalesce(jsonb_agg(to_jsonb(x) order by id),'[]') into v_rows from bounded x;
 if jsonb_array_length(v_rows)>50 then v_next:=(v_rows->49->>'id')::uuid;v_rows:=v_rows-50;end if;
 return jsonb_build_object('items',v_rows,'next_cursor',v_next);
end $$;
create function api.purchase_return_source(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_kind text,p_source_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_header jsonb;v_line jsonb;v_rows jsonb:='[]';v_l record;v_receipt procurement.goods_receipt_lines%rowtype;v_prior numeric;v_available numeric;v_stock_available numeric;v_serials jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.returns.post',p_legal_entity_id,p_branch_id);
 if p_kind='bill' then
  select sales.flow_exact_json(to_jsonb(b))||jsonb_build_object('supplier_name',p.display_name) into v_header from procurement.supplier_bills b join crm.parties p on p.id=b.supplier_id
  where b.id=p_source_id and b.tenant_id=p_tenant_id and b.legal_entity_id=p_legal_entity_id and b.branch_id=p_branch_id and b.status='posted';
 elsif p_kind='receipt' then
  select sales.flow_exact_json(to_jsonb(r))||jsonb_build_object('supplier_name',p.display_name) into v_header from procurement.goods_receipts r join crm.parties p on p.id=(r.source_snapshot->>'supplier_id')::uuid
  where r.id=p_source_id and r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and r.branch_id=p_branch_id and not exists(select 1 from procurement.goods_receipt_reversals where receipt_id=r.id);
 else raise exception using errcode='22023',message='RETURN_SOURCE_INVALID';end if;
 if v_header is null then raise exception using errcode='P0002',message='RETURN_SOURCE_NOT_FOUND';end if;
 for v_l in select id,quantity,receipt_line_id,detail from procurement.supplier_bill_lines where p_kind='bill' and bill_id=p_source_id
  union all select id,accepted_quantity,id,detail from procurement.goods_receipt_lines where p_kind='receipt' and receipt_id=p_source_id order by id limit 501 loop
  if jsonb_array_length(v_rows)>=500 then raise exception using errcode='54000',message='RETURN_SOURCE_LIMIT_EXCEEDED';end if;
  v_receipt:=null;v_serials:='[]';
  if p_kind='bill' then select coalesce(sum(quantity),0) into v_prior from procurement.purchase_return_lines where bill_line_id=v_l.id;
  else
   select coalesce(sum(l.quantity),0) into v_prior from procurement.supplier_bill_lines l join procurement.supplier_bills b on b.id=l.bill_id where l.receipt_line_id=v_l.id and b.status='posted';
   v_prior:=v_prior+coalesce((select sum(quantity) from procurement.purchase_return_lines where receipt_line_id=v_l.id and bill_line_id is null),0);
  end if;
  v_available:=greatest(v_l.quantity-v_prior,0);
  if v_l.receipt_line_id is not null then
   select * into v_receipt from procurement.goods_receipt_lines where id=v_l.receipt_line_id;
   v_stock_available:=v_receipt.accepted_quantity-coalesce((select sum(quantity) from procurement.purchase_return_lines where receipt_line_id=v_receipt.id),0);
   v_available:=least(v_available,greatest(v_stock_available,0));
   select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'code',s.code,'available',s.status='available' and s.warehouse_id=r.warehouse_id) order by s.code),'[]') into v_serials
    from inventory.serials s join procurement.goods_receipts r on r.id=v_receipt.receipt_id where s.id in(select value::uuid from jsonb_array_elements_text(v_receipt.detail->'serial_ids'));
  end if;
  v_line:=v_l.detail||jsonb_build_object('source_line_id',v_l.id,'eligible_quantity',v_available::text,'returned_quantity',v_prior::text,
   'conversion_numerator',coalesce(v_receipt.detail->>'conversion_numerator','1'),'conversion_denominator',coalesce(v_receipt.detail->>'conversion_denominator','1'),
   'lot_code',v_receipt.detail->>'lot_code','serial_options',v_serials);
  v_rows:=v_rows||jsonb_build_array(v_line);
 end loop;
 return v_header||jsonb_build_object('source_kind',p_kind,'source_id',p_source_id,'lines',v_rows,
  'rounding_scale',(select rounding_scale from core.legal_entities where id=p_legal_entity_id));
end $$;
revoke all on function api.purchase_return_sources(uuid,uuid,uuid,text,uuid,text),api.purchase_return_source(uuid,uuid,uuid,text,uuid) from public,anon;
grant execute on function api.purchase_return_sources(uuid,uuid,uuid,text,uuid,text),api.purchase_return_source(uuid,uuid,uuid,text,uuid) to authenticated;

-- Candidate only. Reuses the installed stock ledger; no applied migration is edited.
create table inventory.transfers (
 id uuid primary key, tenant_id uuid not null, legal_entity_id uuid not null,
 branch_id uuid not null, destination_branch_id uuid not null,
 source_warehouse_id uuid not null, destination_warehouse_id uuid not null,
 status text not null check(status in ('in_transit','completed','reversed')),
 version bigint not null default 1, document_date date not null, last_posting_date date not null,
 reference text not null, reason text not null,
 created_by uuid not null references auth.users(id), created_at timestamptz not null default now(),
 unique(tenant_id,id), check(source_warehouse_id<>destination_warehouse_id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,destination_branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,source_warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,destination_warehouse_id) references core.warehouses(tenant_id,id)
);
create table inventory.transfer_lines (
 id uuid primary key, tenant_id uuid not null, transfer_id uuid not null,
 product_id uuid not null, base_quantity numeric(20,6) not null check(base_quantity>0),
 carrying_value numeric(20,6) not null check(carrying_value>=0),
 lot_id uuid, serial_ids uuid[] not null, detail jsonb not null,
 foreign key(tenant_id,transfer_id) references inventory.transfers(tenant_id,id),
 foreign key(tenant_id,lot_id) references inventory.lots(tenant_id,id)
);
create table inventory.transfer_events (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null, transfer_id uuid not null,
 version bigint not null, operation text not null, posting_date date not null, reason text not null, reference text not null,
 command_id uuid not null, request_id uuid not null, destination_issue_snapshot jsonb not null default '{}', created_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(), unique(tenant_id,transfer_id,version),
 foreign key(tenant_id,transfer_id) references inventory.transfers(tenant_id,id)
);
create index transfers_scope_page on inventory.transfers(tenant_id,legal_entity_id,branch_id,id);
create index transfers_destination on inventory.transfers(tenant_id,legal_entity_id,destination_branch_id,id);
create index transfer_lines_parent on inventory.transfer_lines(tenant_id,transfer_id);
create index transfer_lines_lot on inventory.transfer_lines(tenant_id,lot_id);
create index transfer_lines_product on inventory.transfer_lines(tenant_id,product_id);
create index transfers_source_warehouse on inventory.transfers(tenant_id,source_warehouse_id);
create index transfers_destination_warehouse on inventory.transfers(tenant_id,destination_warehouse_id);
create index transfers_creator on inventory.transfers(created_by);
create index transfer_events_creator on inventory.transfer_events(created_by);
do $$declare t text;begin
 foreach t in array array['transfers','transfer_lines','transfer_events'] loop
  execute format('alter table inventory.%I enable row level security',t);
  execute format('alter table inventory.%I force row level security',t);
  execute format('revoke all on inventory.%I from public,anon,authenticated',t);
 end loop;
 foreach t in array array['transfer_lines','transfer_events'] loop
  execute format('create trigger immutable before update or delete on inventory.%I for each row execute function workflow.reject_history_mutation()',t);
 end loop;
end $$;
-- A disjoint constraint adds transfer kinds while preserving installed/candidate kinds.
do $$declare c text;begin
 select pg_get_constraintdef(oid) into c from pg_constraint
 where conrelid='inventory.stock_movements'::regclass and conname='stock_movements_movement_kind_check';
 if c is null then raise exception 'MOVEMENT_CONSTRAINT_DRIFT';end if;
 alter table inventory.stock_movements drop constraint stock_movements_movement_kind_check;
 execute 'alter table inventory.stock_movements add constraint stock_movements_movement_kind_check CHECK ('||substring(c from 7)||' OR movement_kind IN (''transfer_issue'',''transfer_receipt'',''stock_adjustment''))';
end $$;
alter table inventory.serials drop constraint serials_status_check;
alter table inventory.serials add constraint serials_status_check check(status in('available','issued','quarantine','disposed','in_transit'));

-- Private read projection deliberately excludes carrying value from command receipts.
create function inventory.transfer_document(p_tenant uuid,p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select to_jsonb(t)||jsonb_build_object('lines',coalesce((select jsonb_agg(l.detail order by l.id)
 from inventory.transfer_lines l where l.tenant_id=p_tenant and l.transfer_id=t.id),'[]'),
 'source_warehouse_name',(select name from core.warehouses where id=t.source_warehouse_id),
 'destination_warehouse_name',(select name from core.warehouses where id=t.destination_warehouse_id),
 'events',coalesce((select jsonb_agg(to_jsonb(e)-'destination_issue_snapshot' order by e.version) from inventory.transfer_events e
 where e.tenant_id=p_tenant and e.transfer_id=t.id),'[]'))
 from inventory.transfers t where t.tenant_id=p_tenant and t.id=p_id $$;
revoke all on function inventory.transfer_document(uuid,uuid) from public,anon,authenticated;

-- Apply one ledger leg under the caller's sorted warehouse/product locks.
create function inventory.transfer_leg(p_tenant uuid,p_entity uuid,p_branch uuid,p_warehouse uuid,
 p_transfer uuid,p_line inventory.transfer_lines,p_date date,p_quantity numeric,p_value numeric,
 p_operation text,p_request uuid,p_command uuid) returns void
language plpgsql security definer set search_path='' as $$
declare b inventory.stock_balances%rowtype; v inventory.stock_valuations%rowtype; m uuid;
begin
 if exists(select 1 from inventory.stock_movement_lines where tenant_id=p_tenant and warehouse_id=p_warehouse
 and product_id=p_line.product_id and posting_date>p_date) then
 raise exception using errcode='55000',message='BACKDATED_TRANSFER_REQUIRES_REVIEW';end if;
 insert into inventory.stock_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,created_by,updated_by)
 values(p_tenant,p_entity,p_branch,p_warehouse,p_line.product_id,auth.uid(),auth.uid())
 on conflict(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id) do nothing;
 select * into b from inventory.stock_balances where tenant_id=p_tenant and warehouse_id=p_warehouse and product_id=p_line.product_id for update;
 insert into inventory.stock_valuations(tenant_id,legal_entity_id,branch_id,stock_balance_id,carrying_value,created_by,updated_by)
 values(p_tenant,p_entity,p_branch,b.id,0,auth.uid(),auth.uid()) on conflict(tenant_id,stock_balance_id) do nothing;
 select * into v from inventory.stock_valuations where tenant_id=p_tenant and stock_balance_id=b.id for update;
 if b.available_quantity+p_quantity<0 or v.carrying_value+p_value<0
 or (b.on_hand_quantity+p_quantity=0 and v.carrying_value+p_value<>0) then
 raise exception using errcode='55000',message='TRANSFER_STOCK_UNAVAILABLE';end if;
 update inventory.stock_balances set on_hand_quantity=on_hand_quantity+p_quantity,updated_by=auth.uid() where id=b.id;
 update inventory.stock_valuations set carrying_value=carrying_value+p_value,updated_by=auth.uid() where id=v.id;
 if p_line.lot_id is not null then
  insert into inventory.lot_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,lot_id,on_hand_quantity,created_by,updated_by)
  values(p_tenant,p_entity,p_branch,p_warehouse,p_line.product_id,p_line.lot_id,0,auth.uid(),auth.uid())
  on conflict(tenant_id,warehouse_id,lot_id) do nothing;
  update inventory.lot_balances set on_hand_quantity=on_hand_quantity+p_quantity,updated_by=auth.uid()
  where tenant_id=p_tenant and warehouse_id=p_warehouse and lot_id=p_line.lot_id and on_hand_quantity+p_quantity>=0;
  if not found then raise exception using errcode='55000',message='TRANSFER_LOT_UNAVAILABLE';end if;
 end if;
 select id into m from inventory.stock_movements where tenant_id=p_tenant and source_type=p_operation and source_id=p_transfer;
 if m is null then
  m:=gen_random_uuid();
  insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
  values(m,p_tenant,p_entity,p_branch,p_operation,p_transfer,p_warehouse,p_date,
   case when p_operation='stock_count' then 'stock_adjustment' when p_quantity<0 then 'transfer_issue' else 'transfer_receipt' end,p_request,p_command,p_request,auth.uid());
 end if;
 insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
 values(p_tenant,p_entity,p_branch,m,p_warehouse,p_line.product_id,p_line.id,p_quantity,p_value,p_line.lot_id,p_line.serial_ids,p_date,auth.uid());
end $$;
revoke all on function inventory.transfer_leg(uuid,uuid,uuid,uuid,uuid,inventory.transfer_lines,date,numeric,numeric,text,uuid,uuid) from public,anon,authenticated;

create function api.transfer_stock(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare t inventory.transfers%rowtype; l inventory.transfer_lines%rowtype; product inventory.products%rowtype;
 b inventory.stock_balances%rowtype; v inventory.stock_valuations%rowtype;
 id uuid:=(p_payload->>'id')::uuid; op text:=p_payload->>'operation'; d date:=(p_payload->>'document_date')::date;
 reason text:=trim(p_payload->>'reason'); reference text:=trim(p_payload->>'reference');
 h text; result jsonb; before_doc jsonb; req uuid:=gen_random_uuid(); x jsonb; resolved jsonb;
 wh uuid; prod uuid; serial uuid; from_wh uuid; to_wh uuid; from_branch uuid; to_branch uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null or id is null or d is null
 or op is null or op not in('dispatch','immediate','receive','reverse')
 or coalesce(length(reason),0) not between 1 and 1000 or coalesce(length(reference),0) not between 1 and 140 then
 raise exception using errcode='22023',message='TRANSFER_INPUT_INVALID';end if;
 if d>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 h:=core.wave3_request_hash('inventory.transfer',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 -- Check both scopes even for replay, before returning any saved document.
 perform pg_advisory_xact_lock(hashtextextended('inventory.transfer:'||id::text,0));
 select * into t from inventory.transfers where tenant_id=p_tenant_id and transfers.id=id for update;
 if t.id is not null then
  if t.legal_entity_id<>p_legal_entity_id or p_branch_id not in(t.branch_id,t.destination_branch_id) then
   raise exception using errcode='42501',message='TRANSFER_SCOPE_INVALID';end if;
  perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,t.branch_id);
  perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,t.destination_branch_id);
 end if;
 result:=core.wave3_replay(p_tenant_id,'inventory.transfer',p_command_id,p_idempotency_key,h);
 if result is not null then return result;end if;
 before_doc:=inventory.transfer_document(p_tenant_id,id);
 if op in('dispatch','immediate') then
  if t.id is not null then raise exception using errcode='55000',message='TRANSFER_ALREADY_EXISTS';end if;
  if p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
  t.id:=id;t.tenant_id:=p_tenant_id;t.legal_entity_id:=p_legal_entity_id;t.branch_id:=p_branch_id;
  t.source_warehouse_id:=(p_payload->>'source_warehouse_id')::uuid;t.destination_warehouse_id:=(p_payload->>'destination_warehouse_id')::uuid;
  select branch_id into t.destination_branch_id from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and warehouses.id=t.destination_warehouse_id;
  if t.destination_branch_id is null then raise exception using errcode='22023',message='TRANSFER_WAREHOUSE_INVALID';end if;
  perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,t.destination_branch_id);
  if jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 then
   raise exception using errcode='22023',message='TRANSFER_LINES_INVALID';end if;
 else
  if t.id is null then raise exception using errcode='P0002',message='TRANSFER_NOT_FOUND';end if;
  perform core.wave3_assert_expected_version(t.version,p_expected_entity_version,before_doc);
  if t.status='reversed' or (op='receive' and t.status<>'in_transit') then raise exception using errcode='55000',message='TRANSFER_STATE_INVALID';end if;
  if d<t.last_posting_date then raise exception using errcode='55000',message='BACKDATED_TRANSFER_REQUIRES_REVIEW';end if;
 end if;
 if t.source_warehouse_id is null or t.source_warehouse_id=t.destination_warehouse_id
 or not exists(select 1 from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=t.branch_id and warehouses.id=t.source_warehouse_id and status='active')
 or not exists(select 1 from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=t.destination_branch_id and warehouses.id=t.destination_warehouse_id and status='active')
 then raise exception using errcode='22023',message='TRANSFER_WAREHOUSE_INVALID';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,d);
 for wh,prod in select distinct w,p from unnest(array[t.source_warehouse_id,t.destination_warehouse_id]) w
 cross join (select (value->>'product_id')::uuid p from jsonb_array_elements(case when op in('dispatch','immediate') then p_payload->'lines' else before_doc->'lines' end)) q order by w,p loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||wh::text||':'||prod::text,0));
 end loop;
 if op in('dispatch','immediate') then
  insert into inventory.transfers(id,tenant_id,legal_entity_id,branch_id,destination_branch_id,source_warehouse_id,destination_warehouse_id,status,document_date,last_posting_date,reference,reason,created_by)
  values(id,p_tenant_id,p_legal_entity_id,t.branch_id,t.destination_branch_id,t.source_warehouse_id,t.destination_warehouse_id,'in_transit',d,d,reference,reason,auth.uid());
  for x in select value from jsonb_array_elements(p_payload->'lines') order by value->>'product_id',value->>'line_id' loop
   l:=null;l.id:=(x->>'line_id')::uuid;l.tenant_id:=p_tenant_id;l.transfer_id:=id;l.product_id:=(x->>'product_id')::uuid;
   select * into product from inventory.products where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and products.id=l.product_id and kind='stocked' and status='active' for share;
   if not found or l.id is null then raise exception using errcode='22023',message='TRANSFER_PRODUCT_INVALID';end if;
   resolved:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,l.product_id,(x->>'unit_id')::uuid,x->'quantity',x->'conversion_numerator',x->'conversion_denominator');
   l.base_quantity:=(resolved->>'base_quantity')::numeric;l.lot_id:=(x->>'lot_id')::uuid;
   if jsonb_typeof(coalesce(x->'serial_ids','[]'))<>'array' or jsonb_array_length(coalesce(x->'serial_ids','[]'))>1000 then raise exception using errcode='22023',message='TRANSFER_TRACKING_INVALID';end if;
   select coalesce(array_agg(s::uuid order by s),'{}') into l.serial_ids from jsonb_array_elements_text(coalesce(x->'serial_ids','[]')) s;
   if (product.tracking_mode='lot' and not exists(select 1 from inventory.lots where tenant_id=p_tenant_id and product_id=l.product_id and lots.id=l.lot_id and status='saleable' and (expiry_date is null or expiry_date>=greatest(d,(clock_timestamp() at time zone 'UTC')::date))))
    or (product.tracking_mode<>'lot' and l.lot_id is not null)
    or (product.tracking_mode<>'serial' and cardinality(l.serial_ids)>0)
    or (product.tracking_mode='serial' and (cardinality(l.serial_ids)<>l.base_quantity or cardinality(l.serial_ids)<>(select count(distinct s) from unnest(l.serial_ids)s))) then
    raise exception using errcode='22023',message='TRANSFER_TRACKING_INVALID';end if;
   select * into b from inventory.stock_balances where tenant_id=p_tenant_id and warehouse_id=t.source_warehouse_id and product_id=l.product_id for update;
   select * into v from inventory.stock_valuations where tenant_id=p_tenant_id and stock_balance_id=b.id for update;
   if b.id is null or v.id is null or b.available_quantity<l.base_quantity then raise exception using errcode='55000',message='TRANSFER_STOCK_UNAVAILABLE';end if;
   l.carrying_value:=case when l.base_quantity=b.on_hand_quantity then v.carrying_value else round(v.carrying_value*l.base_quantity/b.on_hand_quantity,6) end;
   l.detail:=jsonb_build_object('line_id',l.id,'product_id',l.product_id,'product_name',product.name,'unit_id',x->>'unit_id','quantity',x->>'quantity','lot_id',l.lot_id,'serial_ids',to_jsonb(l.serial_ids))||resolved;
   insert into inventory.transfer_lines select l.*;
   perform inventory.transfer_leg(p_tenant_id,p_legal_entity_id,t.branch_id,t.source_warehouse_id,id,l,d,-l.base_quantity,-l.carrying_value,'transfer.dispatch',req,p_command_id);
   foreach serial in array l.serial_ids loop
    update inventory.serials set status='in_transit',updated_by=auth.uid() where tenant_id=p_tenant_id and serials.id=serial and product_id=l.product_id and warehouse_id=t.source_warehouse_id and status='available';
    if not found then raise exception using errcode='55000',message='TRANSFER_SERIAL_UNAVAILABLE';end if;
   end loop;
  end loop;
 end if;
 if op in('receive','immediate','reverse') then
  to_wh:=case when op='reverse' then t.source_warehouse_id else t.destination_warehouse_id end;
  to_branch:=case when op='reverse' then t.branch_id else t.destination_branch_id end;
  for l in select * from inventory.transfer_lines where tenant_id=p_tenant_id and transfer_id=id order by product_id,transfer_lines.id loop
   if op='reverse' and t.status='completed' then
    -- Conservative correction guard: any later issue of this product requires review.
    if coalesce((select sum(-ml.base_quantity) from inventory.stock_movement_lines ml join inventory.stock_movements m on m.id=ml.stock_movement_id
     where ml.tenant_id=p_tenant_id and ml.warehouse_id=t.destination_warehouse_id and ml.product_id=l.product_id and ml.base_quantity<0 and m.command_id<>p_command_id),0)
     > coalesce((select (e.destination_issue_snapshot->>l.product_id::text)::numeric from inventory.transfer_events e
       where e.transfer_id=id and e.operation in('receive','immediate') limit 1),0) then
     raise exception using errcode='55000',message='TRANSFER_DESTINATION_CONSUMED';end if;
    perform inventory.transfer_leg(p_tenant_id,p_legal_entity_id,t.destination_branch_id,t.destination_warehouse_id,id,l,d,-l.base_quantity,-l.carrying_value,'transfer.reverse.issue',req,p_command_id);
   end if;
   perform inventory.transfer_leg(p_tenant_id,p_legal_entity_id,to_branch,to_wh,id,l,d,l.base_quantity,l.carrying_value,
    case when op='reverse' then 'transfer.reverse.receipt' else 'transfer.receive' end,req,p_command_id);
   foreach serial in array l.serial_ids loop
    from_wh:=case when op='reverse' and t.status='completed' then t.destination_warehouse_id else t.source_warehouse_id end;
    update inventory.serials set status='available',warehouse_id=to_wh,branch_id=to_branch,updated_by=auth.uid()
     where tenant_id=p_tenant_id and serials.id=serial and product_id=l.product_id and warehouse_id=from_wh
     and status=case when op='reverse' and t.status='completed' then 'available' else 'in_transit' end;
    if not found then raise exception using errcode='55000',message='TRANSFER_SERIAL_UNAVAILABLE';end if;
   end loop;
  end loop;
 end if;
 update inventory.transfers set status=case when op='reverse' then 'reversed' when op in('receive','immediate') then 'completed' else 'in_transit' end,
  version=case when op in('dispatch','immediate') then 1 else version+1 end,last_posting_date=d where tenant_id=p_tenant_id and transfers.id=id returning * into t;
 insert into inventory.transfer_events(tenant_id,transfer_id,version,operation,posting_date,reason,reference,command_id,request_id,destination_issue_snapshot,created_by)
 values(p_tenant_id,id,t.version,op,d,reason,reference,p_command_id,req,
  coalesce((select jsonb_object_agg(q.product_id,q.quantity::text) from
   (select ml.product_id,sum(-ml.base_quantity) quantity from inventory.stock_movement_lines ml
    where ml.tenant_id=p_tenant_id and ml.warehouse_id=t.destination_warehouse_id and ml.base_quantity<0 group by ml.product_id)q),'{}'),auth.uid());
 return core.wave3_finish_command(p_tenant_id,'inventory.transfer',p_command_id,'inventory_transfer',id,p_idempotency_key,h,before_doc,
 inventory.transfer_document(p_tenant_id,id),p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status',before_doc->>'status','to_status',t.status,'operation',op,'reason',reason),
 jsonb_build_array(jsonb_build_object('topic','inventory.transfer','payload',jsonb_build_object('id',id,'status',t.status))),'[]',req,req);
end $$;
revoke all on function api.transfer_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.transfer_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.inventory_transfers(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(inventory.transfer_document(p_tenant_id,t.id) order by t.id),'[]') into rows from
 (select * from inventory.transfers where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
 and p_branch_id in(branch_id,destination_branch_id) and (p_after is null or id>p_after)
 and core.has_permission(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,branch_id)
 and core.has_permission(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,destination_branch_id) order by id limit 51)t;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id);
end $$;
revoke all on function api.inventory_transfers(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.inventory_transfers(uuid,uuid,uuid,uuid) to authenticated;

create function api.inventory_transfer_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,
 p_warehouse_id uuid default null,p_product_id uuid default null,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,p_branch_id);
 if length(coalesce(p_search,''))>100 then raise exception using errcode='22023',message='SEARCH_TOO_LONG';end if;
 if p_resource='warehouses' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
  (select w.id,w.name,w.code,w.branch_id from core.warehouses w where w.tenant_id=p_tenant_id and w.legal_entity_id=p_legal_entity_id
   and w.status='active' and core.has_permission(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,w.branch_id)
   and (p_after is null or w.id>p_after) and (w.name ilike '%'||p_search||'%' or w.code ilike '%'||p_search||'%') order by w.id limit 51)q;
 else
  if not exists(select 1 from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_warehouse_id and status='active') then
   raise exception using errcode='42501',message='TRANSFER_SCOPE_INVALID';end if;
  if p_resource='products' then
   select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
   (select p.id,p.name,p.sku,p.base_unit_id,p.tracking_mode,b.available_quantity::text,u.name unit_name,
    jsonb_build_array(jsonb_build_object('id',u.id,'name',u.name,'numerator','1','denominator','1'))||
    coalesce((select jsonb_agg(jsonb_build_object('id',c.unit_id,'name',cu.name,'numerator',c.numerator::text,'denominator',c.denominator::text))
     from inventory.product_unit_conversions c join inventory.units cu on cu.id=c.unit_id where c.product_id=p.id and c.status='active' and cu.status='active'),'[]') units
    from inventory.products p join inventory.stock_balances b on b.product_id=p.id and b.warehouse_id=p_warehouse_id
    join inventory.units u on u.id=p.base_unit_id and u.status='active'
    where p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id and p.status='active' and p.kind='stocked' and b.available_quantity>0
    and (p_after is null or p.id>p_after) and (p.name ilike '%'||p_search||'%' or p.sku ilike '%'||p_search||'%') order by p.id limit 51)q;
  elsif p_resource='lots' then
   select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
   (select l.id,l.code,l.expiry_date,b.on_hand_quantity::text from inventory.lots l join inventory.lot_balances b on b.lot_id=l.id and b.warehouse_id=p_warehouse_id
    where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and l.product_id=p_product_id and l.status='saleable' and b.on_hand_quantity>0
    and (l.expiry_date is null or l.expiry_date>=(clock_timestamp() at time zone 'UTC')::date)
    and (p_after is null or l.id>p_after) and l.code ilike '%'||p_search||'%' order by l.id limit 51)q;
  elsif p_resource='serials' then
   select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
   (select s.id,s.code from inventory.serials s where s.tenant_id=p_tenant_id and s.legal_entity_id=p_legal_entity_id and s.warehouse_id=p_warehouse_id
    and s.product_id=p_product_id and s.status='available' and (p_after is null or s.id>p_after) and s.code ilike '%'||p_search||'%' order by s.id limit 51)q;
  else raise exception using errcode='22023',message='TRANSFER_RESOURCE_INVALID';end if;
 end if;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id);
end $$;
revoke all on function api.inventory_transfer_options(uuid,uuid,uuid,text,uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function api.inventory_transfer_options(uuid,uuid,uuid,text,uuid,uuid,uuid,text) to authenticated;

create function api.inventory_transfer_holdings(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_as_of date,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,p_branch_id);
 if p_as_of is null or p_as_of>(clock_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='AS_OF_DATE_INVALID';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'reference',t.reference,'document_date',t.document_date,
  'source_warehouse_name',(select name from core.warehouses where id=t.source_warehouse_id),
  'destination_warehouse_name',(select name from core.warehouses where id=t.destination_warehouse_id),
  'currency_code',(select currency_code from core.legal_entities where id=t.legal_entity_id),
  'lines',(select jsonb_agg(l.detail||case when core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,t.branch_id)
    and core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,t.destination_branch_id)
    then jsonb_build_object('carrying_value',l.carrying_value::text) else '{}'::jsonb end order by l.id)
   from inventory.transfer_lines l where l.transfer_id=t.id)) order by t.id),'[]') into rows
 from (select tr.* from inventory.transfers tr where tr.tenant_id=p_tenant_id and tr.legal_entity_id=p_legal_entity_id
  and p_branch_id in(tr.branch_id,tr.destination_branch_id) and (p_after is null or tr.id>p_after)
  and tr.document_date<=p_as_of
  and exists(select 1 from inventory.transfer_events e where e.transfer_id=tr.id and e.operation='dispatch')
  and not exists(select 1 from inventory.transfer_events e where e.transfer_id=tr.id and e.operation in('receive','reverse') and e.posting_date<=p_as_of)
  and core.has_permission(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,tr.branch_id)
  and core.has_permission(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,tr.destination_branch_id)
  order by tr.id limit 51)t;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('as_of',p_as_of,'items',rows,'next_cursor',next_id);
end $$;
revoke all on function api.inventory_transfer_holdings(uuid,uuid,uuid,date,uuid) from public,anon,authenticated;
grant execute on function api.inventory_transfer_holdings(uuid,uuid,uuid,date,uuid) to authenticated;


-- Stock-count candidate. Independent aggregate; reuses installed governance and ledger primitives.
create table inventory.stock_counts (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references core.tenants(id),
 legal_entity_id uuid not null, branch_id uuid not null, warehouse_id uuid not null,
 document_type text not null default 'stock_count' check(document_type='stock_count'), corrects_count_id uuid,
 cutoff_at timestamptz not null, document_number text, document_date date not null, reason text not null check(length(trim(reason)) between 3 and 1000),
 currency_code text not null references core.currencies(code), offset_account_id uuid not null,
 lines jsonb not null check(jsonb_typeof(lines)='array' and jsonb_array_length(lines) between 1 and 100),
 grand_total numeric(20,6) not null check(grand_total>=0),
 status text not null default 'draft' check(status in ('draft','pending_approval','approved','rejected','cancelled','posted')),
 version bigint not null default 1, workflow_snapshot jsonb, submitted_by uuid references auth.users(id),
 posted_by uuid references auth.users(id), posted_at timestamptz, stock_movement_id uuid, journal_entry_id uuid,
 request_id uuid not null, command_id uuid not null, correlation_id uuid not null, client_timestamp timestamptz not null,
 prepared_by uuid not null references auth.users(id),
 created_by uuid not null references auth.users(id), updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(tenant_id,id), unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,offset_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,corrects_count_id) references inventory.stock_counts(tenant_id,id),
 check((status='posted')=(posted_at is not null)),
 check(status<>'posted' or posted_by is not null)
);
alter table inventory.stock_counts enable row level security;
alter table inventory.stock_counts force row level security;
create policy count_permitted_read on inventory.stock_counts for select to authenticated using (
 core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,'inventory.cost.view',legal_entity_id,branch_id)
 and (core.has_permission(tenant_id,'inventory.adjustments.post',legal_entity_id,branch_id)
 or core.has_permission(tenant_id,'workflow.approvals.decide',legal_entity_id,branch_id))
);
create trigger count_immutable_posted before update or delete on inventory.stock_counts
 for each row execute function sales.flow_protect_document();
create trigger count_touch before update on inventory.stock_counts
 for each row execute function core.touch_mutable_record();
create index stock_counts_scope_idx on inventory.stock_counts(tenant_id,legal_entity_id,branch_id,status,id);
-- Lead each FK index with its referencing columns; retain the scoped register index.
do $$ declare f record; begin
 for f in select c.conname, (select string_agg(quote_ident(a.attname),',' order by k.n)
 from unnest(c.conkey) with ordinality k(num,n) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.num) cols
 from pg_constraint c where c.conrelid='inventory.stock_counts'::regclass and c.contype='f' loop
 execute format('create index %I on inventory.stock_counts(%s)',f.conname||'_idx',f.cols);
 end loop;
end $$;

-- Candidate extension: a count loss never impersonates a delivery or destroys identity.
alter table inventory.serials add column count_previous_status text check(count_previous_status in ('available','quarantine'));
alter table inventory.serials drop constraint serials_status_check;
alter table inventory.serials add constraint serials_status_check check(status in ('available','issued','quarantine','disposed','in_transit','count_missing'));
alter table inventory.serials add constraint serial_count_disposition check((status='count_missing')=(count_previous_status is not null));

create function inventory.count_identities(p_tenant uuid,p_warehouse uuid,p_product uuid,p_mode text,p_input jsonb,p_old jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare rows jsonb; r jsonb; supplied jsonb; result jsonb:='[]'; q numeric; delta numeric; s inventory.serials%rowtype; lb inventory.lot_balances%rowtype;
begin
 if p_old is null then
  if p_mode='lot' then
   select coalesce(jsonb_agg(jsonb_build_object('id',x.lot_id,'code',x.code,'baseline_quantity',x.on_hand_quantity::text,
    'counted_quantity',x.on_hand_quantity::text,'baseline_version',x.version,'disposition',x.status) order by x.lot_id),'[]') into rows
   from (select b.*,l.code,l.status from inventory.lot_balances b join inventory.lots l on l.id=b.lot_id
    where b.tenant_id=p_tenant and b.warehouse_id=p_warehouse and b.product_id=p_product order by b.lot_id limit 501 for update of b,l)x;
  else
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'code',x.code,'baseline_quantity',case when x.status='count_missing' then '0' else '1' end,
    'counted_quantity',case when x.status='count_missing' then '0' else '1' end,'baseline_version',x.version,'disposition',x.status,
    'restore_status',coalesce(x.count_previous_status,x.status),'lot_id',x.lot_id) order by x.id),'[]') into rows
   from (select * from inventory.serials where tenant_id=p_tenant and warehouse_id=p_warehouse and product_id=p_product
    and status in ('available','quarantine','count_missing') order by id limit 501 for update)x;
  end if;
  if jsonb_array_length(rows)>500 then raise exception using errcode='22023',message='COUNT_IDENTITY_LIMIT';end if;
 else
  rows:=p_old;
  if jsonb_typeof(p_input) is distinct from 'array' or jsonb_array_length(p_input)<>jsonb_array_length(rows)
   or (select count(distinct value->>'id') from jsonb_array_elements(p_input))<>jsonb_array_length(rows) then
   raise exception using errcode='22023',message='COUNT_IDENTITIES_IMMUTABLE';end if;
 end if;
 for r in select value from jsonb_array_elements(rows) order by value->>'id' loop
  supplied:=r;
  if p_old is not null then
   select value into supplied from jsonb_array_elements(p_input) where value->>'id'=r->>'id';
   if supplied is null then raise exception using errcode='22023',message='COUNT_IDENTITIES_IMMUTABLE';end if;
  end if;
  q:=sales.wave3_decimal_string(supplied->'counted_quantity','identity_counted_quantity',6,true,0,null);
  delta:=q-(r->>'baseline_quantity')::numeric;
  if p_mode='serial' then
   if q not in(0,1) then raise exception using errcode='22023',message='COUNT_SERIAL_PRESENCE_REQUIRED';end if;
   select * into s from inventory.serials where tenant_id=p_tenant and warehouse_id=p_warehouse and product_id=p_product and id=(r->>'id')::uuid for update;
   if not found or s.version<>(r->>'baseline_version')::bigint or s.status<>r->>'disposition' then
    raise exception using errcode='55000',message='COUNT_SERIAL_CHANGED';end if;
  else
   select * into lb from inventory.lot_balances where tenant_id=p_tenant and warehouse_id=p_warehouse and product_id=p_product and lot_id=(r->>'id')::uuid for update;
   if not found or lb.on_hand_quantity+delta<0 then raise exception using errcode='55000',message='COUNT_LOT_UNAVAILABLE';end if;
  end if;
  result:=result||jsonb_build_array(r||jsonb_build_object('counted_quantity',q::text,'variance_quantity',delta::text));
 end loop;
 return result;
end $$;
revoke all on function inventory.count_identities(uuid,uuid,uuid,text,jsonb,jsonb) from public,anon,authenticated;

create function inventory.count_normalize(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_old jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare wh uuid:=(p_payload->>'warehouse_id')::uuid; x jsonb; old_line jsonb; product inventory.products%rowtype;
 b inventory.stock_balances%rowtype; val inventory.stock_valuations%rowtype; q numeric; baseline numeric; delta numeric; amount numeric;
 unit_cost numeric; total numeric:=0; lines jsonb:='[]'; seen uuid[]:='{}'; seen_lines uuid[]:='{}'; line_id uuid; currency text; cutoff timestamptz;
 identities jsonb; identity_row jsonb; allocated jsonb; cumulative numeric; prior_amount numeric; next_amount numeric; identity_value numeric; identity_count integer:=0;
begin
 if wh is null or not exists(select 1 from core.warehouses where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=wh and status='active')
 or coalesce(length(trim(p_payload->>'reason')),0) not between 3 and 1000
 or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 100
 or p_payload->>'document_date' is null then raise exception using errcode='22023',message='COUNT_INPUT_INVALID';end if;
 select currency_code into currency from core.legal_entities where tenant_id=p_tenant and id=p_entity;
 perform finance.flow_account(p_tenant,p_entity,(p_payload->>'offset_account_id')::uuid,'expense',currency);
 if p_payload->>'corrects_count_id' is not null and not exists(select 1 from inventory.stock_counts c where c.tenant_id=p_tenant and c.legal_entity_id=p_entity
  and c.branch_id=p_branch and c.warehouse_id=wh and c.id=(p_payload->>'corrects_count_id')::uuid and c.status='posted') then
  raise exception using errcode='22023',message='COUNT_CORRECTION_SOURCE_INVALID';end if;
 if p_old is not null and p_old->>'corrects_count_id' is distinct from p_payload->>'corrects_count_id' then raise exception using errcode='22023',message='COUNT_BASELINE_IMMUTABLE';end if;
 if p_old is not null and ((p_old->>'warehouse_id')::uuid<>wh or jsonb_array_length(p_old->'lines')<>jsonb_array_length(p_payload->'lines')) then
  raise exception using errcode='22023',message='COUNT_BASELINE_IMMUTABLE';end if;
 for x in select value from jsonb_array_elements(p_payload->'lines') order by value->>'product_id' loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||wh::text||':'||(x->>'product_id'),0));
 end loop;
 cutoff:=coalesce((p_old->>'cutoff_at')::timestamptz,clock_timestamp());
 if (p_payload->>'document_date')::date<(cutoff at time zone 'UTC')::date then raise exception using errcode='22023',message='COUNT_DATE_BEFORE_CUTOFF';end if;
 for x in select value from jsonb_array_elements(p_payload->'lines') order by value->>'product_id' loop
  line_id:=(x->>'line_id')::uuid;
  select * into product from inventory.products where tenant_id=p_tenant and legal_entity_id=p_entity and id=(x->>'product_id')::uuid and kind='stocked' and status='active' for share;
  if not found or line_id is null or product.id=any(seen) or line_id=any(seen_lines) then raise exception using errcode='22023',message='COUNT_PRODUCT_INVALID';end if;
  seen:=array_append(seen,product.id);seen_lines:=array_append(seen_lines,line_id);
  q:=sales.wave3_decimal_string(x->'counted_quantity','counted_quantity',6,true,0,null);
  if not exists(select 1 from inventory.units where tenant_id=p_tenant and id=product.base_unit_id and status='active' and round(q,precision)=q) then
   raise exception using errcode='22023',message='COUNT_UNIT_PRECISION_INVALID';end if;
  select * into b from inventory.stock_balances where tenant_id=p_tenant and warehouse_id=wh and product_id=product.id for update;
  select * into val from inventory.stock_valuations where tenant_id=p_tenant and stock_balance_id=b.id for update;
  if b.id is null or val.id is null then raise exception using errcode='55000',message='COUNT_BALANCE_REQUIRED';end if;
  old_line:=null;
  if p_old is not null then
   select value into old_line from jsonb_array_elements(p_old->'lines') where value->>'line_id'=line_id::text and value->>'product_id'=product.id::text;
   if old_line is null or old_line->>'base_unit_id'<>product.base_unit_id::text then raise exception using errcode='22023',message='COUNT_BASELINE_IMMUTABLE';end if;
  end if;
  baseline:=coalesce((old_line->>'baseline_quantity')::numeric,b.on_hand_quantity);
  identities:=null;
  if product.tracking_mode<>'none' then
   if old_line is null and p_payload->'capture_only' is distinct from 'true'::jsonb then raise exception using errcode='22023',message='COUNT_TRACKED_CAPTURE_REQUIRED';end if;
   if old_line is not null and old_line->>'tracking_mode' is distinct from product.tracking_mode then raise exception using errcode='22023',message='COUNT_BASELINE_IMMUTABLE';end if;
   identities:=inventory.count_identities(p_tenant,wh,product.id,product.tracking_mode,x->'identities',old_line->'identities');
   identity_count:=identity_count+jsonb_array_length(identities);
   if identity_count>500 then raise exception using errcode='22023',message='COUNT_IDENTITY_LIMIT';end if;
   if old_line is null and coalesce((select sum((value->>'baseline_quantity')::numeric) from jsonb_array_elements(identities)),0)<>baseline then
    raise exception using errcode='55000',message='COUNT_TRACKING_BALANCE_MISMATCH';end if;
   select coalesce(sum((value->>'counted_quantity')::numeric),0) into q from jsonb_array_elements(identities);
   if exists(select 1 from jsonb_array_elements(identities) z,inventory.units u where u.id=product.base_unit_id and round((z->>'counted_quantity')::numeric,u.precision)<>(z->>'counted_quantity')::numeric) then
    raise exception using errcode='22023',message='COUNT_UNIT_PRECISION_INVALID';end if;
  elsif old_line is not null and old_line->>'tracking_mode' not in ('none') then raise exception using errcode='22023',message='COUNT_BASELINE_IMMUTABLE';end if;
  if p_old is null and p_payload->'capture_only'='true'::jsonb then q:=baseline;end if;
  delta:=q-baseline;
  unit_cost:=sales.wave3_decimal_string(coalesce(x->'empty_unit_cost','"0"'::jsonb),'empty_unit_cost',6,true,0,null);
  if delta>0 and b.on_hand_quantity=0 and (x->>'empty_unit_cost' is null or trim(x->>'empty_unit_cost')='') then
   raise exception using errcode='22023',message='COUNT_EMPTY_STOCK_COST_REQUIRED';end if;
  if b.available_quantity+delta<0 then raise exception using errcode='55000',message='COUNT_RESERVED_STOCK_UNAVAILABLE';end if;
  amount:=case when delta=0 then 0 when b.on_hand_quantity=0 then round(delta*unit_cost,6)
   when delta=-b.on_hand_quantity then -val.carrying_value else round(val.carrying_value*delta/b.on_hand_quantity,6) end;
  perform finance.flow_account(p_tenant,p_entity,product.inventory_account_id,'asset',currency);
  if identities is null then total:=total+abs(amount);
  else
   cumulative:=0;prior_amount:=0;allocated:='[]';
   for identity_row in select value from jsonb_array_elements(identities) order by (value->>'variance_quantity')::numeric desc,value->>'id' loop
    cumulative:=cumulative+(identity_row->>'variance_quantity')::numeric;
    next_amount:=case when cumulative=delta then amount when b.on_hand_quantity=0 then round(cumulative*unit_cost,6) else round(val.carrying_value*cumulative/b.on_hand_quantity,6) end;
    identity_value:=next_amount-prior_amount;prior_amount:=next_amount;
    allocated:=allocated||jsonb_build_array(identity_row||jsonb_build_object('variance_value',identity_value::text));
    total:=total+abs(identity_value);
   end loop;
   select coalesce(jsonb_agg(z order by z->>'id'),'[]') into identities from jsonb_array_elements(allocated)z;
  end if;
  lines:=lines||jsonb_build_array(jsonb_build_object('line_id',line_id,'product_id',product.id,'product_name',product.name,'base_unit_id',product.base_unit_id,
   'baseline_quantity',baseline::text,'baseline_version',coalesce(old_line->'baseline_version',to_jsonb(b.version)),
   'counted_quantity',q::text,'variance_quantity',delta::text,'variance_value',amount::text,'empty_unit_cost',unit_cost::text,'inventory_account_id',product.inventory_account_id)
   ||case when identities is null then '{}'::jsonb else jsonb_build_object('tracking_mode',product.tracking_mode,'identities',identities) end);
 end loop;
 return jsonb_build_object('warehouse_id',wh,'document_date',p_payload->>'document_date','reason',trim(p_payload->>'reason'),
  'currency_code',currency,'offset_account_id',p_payload->>'offset_account_id','cutoff_at',cutoff,'lines',lines,'grand_total',total::text);
end $$;

create function inventory.count_revalidate(p_kind text,p_doc jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare d jsonb;begin
 if p_kind<>'stock_count' then raise exception using errcode='22023',message='DOCUMENT_TYPE_INVALID';end if;
 d:=inventory.count_normalize((p_doc->>'tenant_id')::uuid,(p_doc->>'legal_entity_id')::uuid,(p_doc->>'branch_id')::uuid,p_doc,p_doc);
 if d->'lines'<>p_doc->'lines' or d->>'currency_code'<>p_doc->>'currency_code' then
  raise exception using errcode='55000',message='COUNT_REAPPROVAL_REQUIRED';end if;
 return d;
end $$;

create function api.upsert_stock_count(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare id uuid:=(p_payload->>'id')::uuid;req uuid:=gen_random_uuid();h text;result jsonb;old_doc jsonb;d jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null or id is null then raise exception using errcode='22023',message='COUNT_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.stock_count.upsert',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.stock_count.upsert',p_command_id,p_idempotency_key,h);if result is not null then return result;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':count:'||id::text,0));
 old_doc:=inventory.count_document('stock_count',p_tenant_id,id,true);
 if old_doc is not null then
  if old_doc->>'legal_entity_id'<>p_legal_entity_id::text or old_doc->>'branch_id'<>p_branch_id::text then raise exception using errcode='42501',message='DOCUMENT_SCOPE_INVALID';end if;
  perform core.wave3_assert_expected_version((old_doc->>'version')::bigint,p_expected_entity_version,old_doc);
  if old_doc->>'status'<>'draft' then raise exception using errcode='55000',message='DOCUMENT_NOT_EDITABLE';end if;
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 d:=inventory.count_normalize(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,old_doc);
 insert into inventory.stock_counts(id,tenant_id,legal_entity_id,branch_id,warehouse_id,cutoff_at,document_date,reason,currency_code,offset_account_id,lines,grand_total,corrects_count_id,
 request_id,command_id,correlation_id,client_timestamp,prepared_by,created_by,updated_by)
 values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(d->>'warehouse_id')::uuid,(d->>'cutoff_at')::timestamptz,(d->>'document_date')::date,d->>'reason',d->>'currency_code',
 (d->>'offset_account_id')::uuid,d->'lines',(d->>'grand_total')::numeric,(p_payload->>'corrects_count_id')::uuid,req,p_command_id,req,p_client_timestamp,auth.uid(),auth.uid(),auth.uid())
 on conflict on constraint stock_counts_pkey do update set document_date=excluded.document_date,reason=excluded.reason,offset_account_id=excluded.offset_account_id,
 lines=excluded.lines,grand_total=excluded.grand_total,prepared_by=auth.uid(),updated_by=auth.uid(),request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp
 where inventory.stock_counts.tenant_id=excluded.tenant_id and inventory.stock_counts.legal_entity_id=excluded.legal_entity_id and inventory.stock_counts.branch_id=excluded.branch_id;
 if not found then raise exception using errcode='42501',message='DOCUMENT_SCOPE_INVALID';end if;
 return core.wave3_finish_command(p_tenant_id,'inventory.stock_count.upsert',p_command_id,'stock_count',id,p_idempotency_key,h,old_doc,
 inventory.count_document('stock_count',p_tenant_id,id),p_legal_entity_id,p_branch_id,'{}',null,'[]','[]',req,req);
end $$;
revoke all on inventory.stock_counts from public,anon,authenticated;
grant select on inventory.stock_counts to authenticated;
create view api.stock_counts with(security_invoker=true) as
 select id,tenant_id,legal_entity_id,branch_id,warehouse_id,document_number,document_date,status,version,
 sales.flow_exact_json(to_jsonb(o)) as detail from inventory.stock_counts o;
revoke all on api.stock_counts from public,anon,authenticated;
grant select on api.stock_counts to authenticated;

create function inventory.count_document(p_kind text,p_tenant uuid,p_id uuid,p_lock boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d inventory.stock_counts%rowtype; begin
 if p_kind is distinct from 'stock_count' then raise exception using errcode='22023',message='DOCUMENT_TYPE_INVALID';end if;
 if p_lock then select * into d from inventory.stock_counts where tenant_id=p_tenant and id=p_id for update;
 else select * into d from inventory.stock_counts where tenant_id=p_tenant and id=p_id;end if;
 if not found then return null;end if;
 return sales.flow_exact_json(to_jsonb(d))||jsonb_build_object('warehouse_name',(select name from core.warehouses where id=d.warehouse_id),
  'offset_account_name',(select name from finance.accounts where id=d.offset_account_id));
end $$;


create function api.transition_stock_count(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_kind text:='stock_count';v_id uuid:=(p_payload->>'document_id')::uuid;
 v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';v_command text;
 v_doc jsonb;v_before jsonb;v_hash text;v_replay jsonb;v_to text;v_snapshot jsonb;
 v_workflow workflow.workflow_definitions%rowtype;v_request uuid:=gen_random_uuid();v_first integer;
 v_ar workflow.approval_requests%rowtype;v_step jsonb;v_number text;
begin
 v_command:='inventory.'||v_kind||case when v_decision is null then '.transition' else '.decide' end;
 perform core.wave3_require_scope(p_tenant_id,case when v_decision is null then 'inventory.adjustments.post' else 'workflow.approvals.decide' end,p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or (p_payload ? 'document_type' and p_payload->>'document_type' is distinct from 'stock_count')
 or (v_decision is not null and v_action is not null) then raise exception using errcode='22023',message='DOCUMENT_PAYLOAD_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_replay:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
 v_doc:=inventory.count_document(v_kind,p_tenant_id,v_id,true);v_before:=v_doc;
 if v_doc is null or (v_doc->>'legal_entity_id')::uuid<>p_legal_entity_id or (v_doc->>'branch_id')::uuid<>p_branch_id then
 raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version((v_doc->>'version')::bigint,p_expected_entity_version,v_doc);
 if v_doc->>'status'='posted' then raise exception using errcode='55000',message='POSTED_DOCUMENT_IMMUTABLE';end if;
 v_snapshot:=v_doc->'workflow_snapshot';v_number:=v_doc->>'document_number';
 if v_decision is not null then
 if v_decision not in ('approved','rejected') or v_doc->>'status'<>'pending_approval' then raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
 select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type=v_kind and document_id=v_id and status='submitted' for update;
 if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
 if v_ar.submitted_by=auth.uid() or (v_doc->>'created_by')::uuid=auth.uid() or (v_doc->>'prepared_by')::uuid=auth.uid() then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
 if v_step is null or not exists(select 1 from core.memberships m join core.role_assignments ra on ra.tenant_id=m.tenant_id and ra.membership_id=m.id
 join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
 where m.tenant_id=p_tenant_id and m.user_id=auth.uid() and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
 and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
 and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
 if v_decision='rejected' and nullif(trim(p_payload->>'note'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
 perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
 insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
 approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
 values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
 auth.uid(),v_decision,p_payload->>'note',v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
 if v_decision='approved' then select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
 where (x->>'step_order')::integer>v_ar.current_step;end if;
 v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
 if v_first is null then update workflow.approval_requests set status=v_to,decision_by=auth.uid(),decision_note=p_payload->>'note',decided_at=clock_timestamp() where id=v_ar.id;
 else update workflow.approval_requests set current_step=v_first where id=v_ar.id;end if;
 elsif v_action='submit' then
 if v_doc->>'status'<>'draft' then raise exception using errcode='55000',message='DOCUMENT_NOT_EDITABLE';end if;
 perform inventory.count_revalidate(v_kind,v_doc);
 select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id and document_type=v_kind and status='active'
 and (legal_entity_id is null or legal_entity_id=p_legal_entity_id) order by (legal_entity_id is not null) desc limit 1;
 if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
 select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
 'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
 from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
 and (s.currency_code is null or s.currency_code=v_doc->>'currency_code')
 and (s.minimum_amount is null or (v_doc->>'grand_total')::numeric>=s.minimum_amount)
 and (s.maximum_amount is null or (v_doc->>'grand_total')::numeric<=s.maximum_amount);
 if v_workflow.lifecycle->'requires_approval'='false'::jsonb then
 raise exception using errcode='55000',message='COUNT_APPROVAL_REQUIRED';end if;
 select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
 if v_first is null then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
 v_to:='pending_approval';
 perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
 v_number:=coalesce(v_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,(v_doc->>'document_date')::date,auth.uid()));
 if v_first is not null then insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
 submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,v_id,'submitted',auth.uid(),v_workflow.id,v_workflow.revision,v_first,
 (v_doc->>'grand_total')::numeric,v_doc->>'currency_code',p_command_id,v_request,v_request);end if;
 elsif v_action in ('recall','cancel') then
 if nullif(trim(p_payload->>'reason'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
 if v_snapshot is null and v_doc->>'status'='draft' then
 select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
 where tenant_id=p_tenant_id and document_type=v_kind and status='active'
 and (legal_entity_id is null or legal_entity_id=p_legal_entity_id) order by (legal_entity_id is not null) desc limit 1;
 end if;
 v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
 perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc->>'status',v_to);
 update workflow.approval_requests set status='cancelled',decision_by=auth.uid(),decision_note=p_payload->>'reason',decided_at=clock_timestamp()
 where tenant_id=p_tenant_id and document_type=v_kind and document_id=v_id and status='submitted';
 if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='DOCUMENT_ACTION_INVALID';end if;
 execute format('update inventory.%I set status=$1,workflow_snapshot=$2,document_number=$3,submitted_by=case when $4=''submit'' then $5 else submitted_by end,updated_by=$5,request_id=$6,command_id=$7,correlation_id=$6,client_timestamp=$8 where tenant_id=$9 and id=$10','stock_counts')
 using v_to,v_snapshot,v_number,v_action,auth.uid(),v_request,p_command_id,p_client_timestamp,p_tenant_id,v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,v_kind,v_id,p_idempotency_key,v_hash,v_before,
 inventory.count_document(v_kind,p_tenant_id,v_id),p_legal_entity_id,p_branch_id,coalesce(p_payload->'source_context','{}'),
 case when v_doc->>'status'=v_to then null else
 jsonb_build_object('from_status',v_doc->>'status','to_status',v_to,'reason',coalesce(p_payload->>'reason',p_payload->>'note')) end,
 jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
end $$;




create function api.post_stock_adjustment(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;req uuid:=gen_random_uuid();h text;result jsonb;d jsonb;x jsonb;
 l inventory.transfer_lines%rowtype;jlines jsonb:='[]';j uuid;m uuid;q numeric;amount numeric;v_date date;identity_row jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null or v_id is null then raise exception using errcode='22023',message='COUNT_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.stock_count.post',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.stock_count.post',p_command_id,p_idempotency_key,h);if result is not null then return result;end if;
 d:=inventory.count_document('stock_count',p_tenant_id,v_id,true);
 if d is null or d->>'legal_entity_id'<>p_legal_entity_id::text or d->>'branch_id'<>p_branch_id::text then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version((d->>'version')::bigint,p_expected_entity_version,d);
 if d->>'status'<>'approved' then raise exception using errcode='55000',message='COUNT_APPROVAL_REQUIRED';end if;
 perform sales.flow_assert_transition(d#>'{workflow_snapshot,lifecycle}','approved','posted');
 if d#>'{workflow_snapshot,lifecycle,separate_poster}'='true'::jsonb and (d->>'submitted_by')::uuid=auth.uid() then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 v_date:=(d->>'document_date')::date;
 if v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 perform inventory.count_revalidate('stock_count',d);
 for x in select value from jsonb_array_elements(d->'lines') order by value->>'product_id' loop
  for identity_row in select value from jsonb_array_elements(coalesce(x->'identities',jsonb_build_array(x)))
   order by (value->>'variance_quantity')::numeric desc,value->>'id' loop
  q:=(identity_row->>'variance_quantity')::numeric;amount:=(identity_row->>'variance_value')::numeric;
  if q=0 then continue;end if;
  l:=null;l.id:=(x->>'line_id')::uuid;l.product_id:=(x->>'product_id')::uuid;l.serial_ids:='{}';
  if x ? 'identities' then l.id:=md5((x->>'line_id')||':'||(identity_row->>'id'))::uuid;end if;
  if x->>'tracking_mode'='lot' then l.lot_id:=(identity_row->>'id')::uuid;
  elsif x->>'tracking_mode'='serial' then
   l.serial_ids:=array[(identity_row->>'id')::uuid];l.lot_id:=(identity_row->>'lot_id')::uuid;
  end if;
  perform inventory.transfer_leg(p_tenant_id,p_legal_entity_id,p_branch_id,(d->>'warehouse_id')::uuid,v_id,l,v_date,q,amount,'stock_count',req,p_command_id);
  if x->>'tracking_mode'='serial' then
   update inventory.serials set status=case when q<0 then 'count_missing' else identity_row->>'restore_status' end,
    count_previous_status=case when q<0 then status else null end,updated_by=auth.uid()
    where tenant_id=p_tenant_id and id=(identity_row->>'id')::uuid and warehouse_id=(d->>'warehouse_id')::uuid
     and version=(identity_row->>'baseline_version')::bigint and status=identity_row->>'disposition';
   if not found then raise exception using errcode='55000',message='COUNT_SERIAL_CHANGED';end if;
  end if;
  if amount<>0 then jlines:=jlines||jsonb_build_array(finance.flow_jline((x->>'inventory_account_id')::uuid,amount,amount,l.id),
   finance.flow_jline((d->>'offset_account_id')::uuid,-amount,-amount,l.id));end if;
  end loop;
 end loop;
 j:=finance.flow_post_journal(d||jsonb_build_object('base_currency_code',d->>'currency_code','exchange_rate','1'),jlines,'stock_count',v_id,req,p_command_id);
 select id into m from inventory.stock_movements where tenant_id=p_tenant_id and source_type='stock_count' and source_id=v_id;
 update inventory.stock_counts set status='posted',posted_at=clock_timestamp(),posted_by=auth.uid(),updated_by=auth.uid(),stock_movement_id=m,journal_entry_id=j,
 request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp where tenant_id=p_tenant_id and id=v_id;
 return core.wave3_finish_command(p_tenant_id,'inventory.stock_count.post',p_command_id,'stock_count',v_id,p_idempotency_key,h,d,
 inventory.count_document('stock_count',p_tenant_id,v_id),p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','approved','to_status','posted','reason',d->>'reason'),
 jsonb_build_array(jsonb_build_object('topic','inventory.stock_count.post','payload',jsonb_build_object('id',v_id))),'[]',req,req);
end $$;
revoke all on function inventory.count_document(text,uuid,uuid,boolean),inventory.count_normalize(uuid,uuid,uuid,jsonb,jsonb),inventory.count_revalidate(text,jsonb) from public,anon,authenticated;
do $$declare f text;begin
 foreach f in array array['upsert_stock_count','transition_stock_count','post_stock_adjustment'] loop
  execute format('revoke all on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated',f);
  execute format('grant execute on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated',f);
 end loop;
end $$;

create function api.stock_counts_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if not core.has_permission(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id) and not core.has_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'document_number',q.document_number,'document_date',q.document_date,'status',q.status,
  'version',q.version,'currency_code',q.currency_code,'grand_total',q.grand_total::text,'warehouse_name',(select name from core.warehouses where id=q.warehouse_id)) order by q.id),'[]') into rows
 from (select * from inventory.stock_counts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and (p_after is null or id>p_after) order by id limit 51)q;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id);
end $$;
create function api.stock_count_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d jsonb;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if not core.has_permission(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id) and not core.has_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 d:=inventory.count_document('stock_count',p_tenant_id,p_id);
 if d is null or d->>'legal_entity_id' is distinct from p_legal_entity_id::text or d->>'branch_id' is distinct from p_branch_id::text then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 return d;
end $$;
revoke all on function api.stock_count_detail(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.stock_count_detail(uuid,uuid,uuid,uuid) to authenticated;
create function api.stock_count_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_warehouse_id uuid default null,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if coalesce(length(p_search),0)>100 then raise exception using errcode='22023',message='SEARCH_TOO_LONG';end if;
 if p_resource='warehouses' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
  (select id,name,code from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active'
   and (p_after is null or id>p_after) and (name ilike '%'||p_search||'%' or code ilike '%'||p_search||'%') order by id limit 51)q;
 elsif p_resource='accounts' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
  (select a.id,a.name,a.code from finance.accounts a join core.legal_entities e on e.id=a.legal_entity_id where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id
   and a.status='active' and a.is_posting and a.account_type='expense' and (a.currency_code is null or a.currency_code=e.currency_code)
   and (p_after is null or a.id>p_after) and (a.name ilike '%'||p_search||'%' or a.code ilike '%'||p_search||'%') order by a.id limit 51)q;
 elsif p_resource='products' then
  if not exists(select 1 from core.warehouses where id=p_warehouse_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active') then raise exception using errcode='42501',message='WAREHOUSE_SCOPE_INVALID';end if;
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from
  (select p.id,p.name,p.sku,b.on_hand_quantity::text from inventory.products p join inventory.stock_balances b on b.product_id=p.id and b.warehouse_id=p_warehouse_id
   where p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id and p.status='active' and p.kind='stocked'
   and (p_after is null or p.id>p_after) and (p.name ilike '%'||p_search||'%' or p.sku ilike '%'||p_search||'%') order by p.id limit 51)q;
 else raise exception using errcode='22023',message='COUNT_RESOURCE_INVALID';end if;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id);
end $$;
revoke all on function api.stock_counts_page(uuid,uuid,uuid,uuid),api.stock_count_options(uuid,uuid,uuid,text,uuid,uuid,text) from public,anon,authenticated;
grant execute on function api.stock_counts_page(uuid,uuid,uuid,uuid),api.stock_count_options(uuid,uuid,uuid,text,uuid,uuid,text) to authenticated;

-- Candidate only: governed release and immutable reservation history.
create table inventory.reservation_history_coverage (
 singleton boolean primary key default true check(singleton), starts_at timestamptz not null default clock_timestamp()
);
insert into inventory.reservation_history_coverage(singleton) values(true);
create table inventory.reservation_history (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null, reservation_id uuid not null,
 legal_entity_id uuid not null, branch_id uuid not null, version bigint not null,
 recorded_at timestamptz not null, baseline boolean not null default false, actor_id uuid references auth.users(id),
 snapshot jsonb not null, unique(tenant_id,reservation_id,version),
 foreign key(tenant_id,reservation_id) references inventory.stock_reservations(tenant_id,id)
);
create index reservation_history_scope on inventory.reservation_history(tenant_id,legal_entity_id,branch_id,reservation_id,version);
create index reservation_history_actor on inventory.reservation_history(actor_id);
alter table inventory.reservation_history enable row level security;
alter table inventory.reservation_history force row level security;
alter table inventory.reservation_history_coverage enable row level security;
alter table inventory.reservation_history_coverage force row level security;
revoke all on inventory.reservation_history,inventory.reservation_history_coverage from public,anon,authenticated;
create trigger reservation_history_immutable before update or delete on inventory.reservation_history for each row execute function workflow.reject_history_mutation();
create function inventory.capture_reservation_history() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' then
  insert into inventory.reservation_history(tenant_id,reservation_id,legal_entity_id,branch_id,version,recorded_at,baseline,actor_id,snapshot)
  select old.tenant_id,old.id,old.legal_entity_id,old.branch_id,old.version,c.starts_at,true,null,
   sales.flow_exact_json(to_jsonb(old)) from inventory.reservation_history_coverage c
  on conflict(tenant_id,reservation_id,version) do nothing;
 end if;
 insert into inventory.reservation_history(tenant_id,reservation_id,legal_entity_id,branch_id,version,recorded_at,actor_id,snapshot)
 values(new.tenant_id,new.id,new.legal_entity_id,new.branch_id,new.version,clock_timestamp(),auth.uid(),sales.flow_exact_json(to_jsonb(new)));
 return new;
end $$;
revoke all on function inventory.capture_reservation_history() from public,anon,authenticated;
create trigger reservation_history_capture after insert or update on inventory.stock_reservations for each row execute function inventory.capture_reservation_history();

create function api.release_stock_reservation(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r inventory.stock_reservations%rowtype; o sales.sales_orders%rowtype; req uuid:=gen_random_uuid(); h text; result jsonb; before_doc jsonb;
 v_id uuid:=(p_payload->>'id')::uuid; mode text:=p_payload->>'mode';reason text:=trim(p_payload->>'reason'); next_status text;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.reservations.manage',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null or v_id is null
 or mode is null or mode not in('manual','expired','retired') or coalesce(length(reason),0) not between 3 and 1000 then
  raise exception using errcode='22023',message='RESERVATION_RELEASE_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.reservation.release',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.reservation.release',p_command_id,p_idempotency_key,h);if result is not null then return result;end if;
 select * into r from inventory.stock_reservations where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=v_id;
 if not found then raise exception using errcode='P0002',message='RESERVATION_NOT_FOUND';end if;
 select * into o from sales.sales_orders where tenant_id=p_tenant_id and id=r.sales_order_id for update;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||r.warehouse_id::text||':'||r.product_id::text,0));
 select * into r from inventory.stock_reservations where tenant_id=p_tenant_id and id=v_id for update;
 before_doc:=sales.flow_exact_json(to_jsonb(r));
 perform core.wave3_assert_expected_version(r.version,p_expected_entity_version,before_doc);
 if r.status<>'active' then raise exception using errcode='55000',message='RESERVATION_NOT_ACTIVE';end if;
 if mode='expired' and r.expires_at>clock_timestamp() then raise exception using errcode='55000',message='RESERVATION_NOT_EXPIRED';end if;
 if mode='retired' and exists(select 1 from inventory.products where tenant_id=p_tenant_id and id=r.product_id and status='active') then raise exception using errcode='55000',message='PRODUCT_STILL_ACTIVE';end if;
 update inventory.stock_balances set allocated_quantity=allocated_quantity-r.base_quantity,updated_by=auth.uid()
 where tenant_id=p_tenant_id and warehouse_id=r.warehouse_id and product_id=r.product_id and allocated_quantity>=r.base_quantity;
 if not found then raise exception using errcode='55000',message='RESERVATION_PROJECTION_MISMATCH';end if;
 update sales.sales_order_lines set allocated_quantity=allocated_quantity-r.base_quantity,updated_by=auth.uid(),request_id=req,command_id=p_command_id,correlation_id=req
 where tenant_id=p_tenant_id and id=r.sales_order_line_id and allocated_quantity>=r.base_quantity;
 if not found then raise exception using errcode='55000',message='RESERVATION_PROJECTION_MISMATCH';end if;
 update inventory.stock_reservations set status=case when mode='expired' then 'expired' else 'released' end,released_at=clock_timestamp(),release_reason=reason,
 updated_by=auth.uid(),request_id=req,command_id=p_command_id,correlation_id=req where id=v_id returning * into r;
 next_status:=o.status;
 if o.status in('confirmed','reserved','partially_reserved') then
  next_status:=case when exists(select 1 from sales.sales_order_lines where sales_order_id=o.id and allocated_quantity>0) then 'partially_reserved' else 'confirmed' end;
 end if;
 update sales.sales_orders set status=next_status,updated_by=auth.uid(),request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp where id=o.id;
 return core.wave3_finish_command(p_tenant_id,'inventory.reservation.release',p_command_id,'stock_reservation',v_id,p_idempotency_key,h,before_doc,
 sales.flow_exact_json(to_jsonb(r)),p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','active','to_status',r.status,'reason',reason),
 jsonb_build_array(jsonb_build_object('topic','inventory.reservation.release','payload',jsonb_build_object('id',v_id,'sales_order_id',o.id))),'[]',req,req);
end $$;
revoke all on function api.release_stock_reservation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.release_stock_reservation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.stock_reservation_queue(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_filter text default 'active',p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.reservations.manage',p_legal_entity_id,p_branch_id);
 if p_filter is null or p_filter not in('active','expired','retired','all') or p_branch_id is null then raise exception using errcode='22023',message='RESERVATION_FILTER_INVALID';end if;
 select coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(q)) order by q.id),'[]') into rows from
 (select r.id,r.version,r.status,r.base_quantity::text,r.expires_at,r.release_reason,r.sales_order_id,o.document_number,p.name product_name,w.name warehouse_name
  from inventory.stock_reservations r join sales.sales_orders o on o.id=r.sales_order_id join inventory.products p on p.id=r.product_id join core.warehouses w on w.id=r.warehouse_id
  where r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and r.branch_id=p_branch_id and (p_after is null or r.id>p_after)
  and (p_filter='all' or r.status='active') and (p_filter<>'expired' or r.expires_at<=clock_timestamp()) and(p_filter<>'retired' or p.status<>'active') order by r.id limit 51)q;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id);
end $$;
create function api.stock_reservation_history(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,p_before_version bigint default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_version bigint;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.reservations.manage',p_legal_entity_id,p_branch_id);
 if not exists(select 1 from inventory.stock_reservations where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_id) then raise exception using errcode='P0002',message='RESERVATION_NOT_FOUND';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.version desc),'[]') into rows from
 (select version,recorded_at,baseline,actor_id,snapshot-'source_context' as snapshot from inventory.reservation_history
  where tenant_id=p_tenant_id and reservation_id=p_id and (p_before_version is null or version<p_before_version) order by version desc limit 51)q;
 if jsonb_array_length(rows)>50 then next_version:=(rows->49->>'version')::bigint;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_version',next_version,'coverage_start',(select starts_at from inventory.reservation_history_coverage));
end $$;
revoke all on function api.stock_reservation_queue(uuid,uuid,uuid,text,uuid),api.stock_reservation_history(uuid,uuid,uuid,uuid,bigint) from public,anon,authenticated;
grant execute on function api.stock_reservation_queue(uuid,uuid,uuid,text,uuid),api.stock_reservation_history(uuid,uuid,uuid,uuid,bigint) to authenticated;

create function api.stock_reservations_as_of(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_as_of timestamptz,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb; next_id uuid; coverage timestamptz;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.reservations.manage',p_legal_entity_id,p_branch_id);
 select starts_at into coverage from inventory.reservation_history_coverage;
 if p_branch_id is null or p_legal_entity_id is null or p_as_of is null or p_as_of<coverage or p_as_of>clock_timestamp() then
  raise exception using errcode='22023',message='RESERVATION_ASOF_OUTSIDE_COVERAGE';end if;
 select coalesce(jsonb_agg(q.detail order by q.id),'[]') into rows from (
  select r.id,jsonb_build_object('id',r.id,'version',(s.snapshot->>'version')::bigint,'status',s.snapshot->>'status',
   'base_quantity',s.snapshot->>'base_quantity','expires_at',s.snapshot->>'expires_at',
   'sales_order_id',r.sales_order_id,'document_number',o.document_number,'product_name',p.name,'warehouse_name',w.name) detail
  from inventory.stock_reservations r
  join sales.sales_orders o on o.tenant_id=r.tenant_id and o.id=r.sales_order_id
  join inventory.products p on p.tenant_id=r.tenant_id and p.id=r.product_id
  join core.warehouses w on w.tenant_id=r.tenant_id and w.id=r.warehouse_id
  cross join lateral (
   select coalesce(
    (select h.snapshot from inventory.reservation_history h where h.tenant_id=r.tenant_id and h.reservation_id=r.id
      and h.recorded_at<=p_as_of order by h.version desc limit 1),
    case when r.created_at<=coverage and not exists(select 1 from inventory.reservation_history h where h.tenant_id=r.tenant_id and h.reservation_id=r.id)
     then sales.flow_exact_json(to_jsonb(r)) end) snapshot
  ) s
  where r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and r.branch_id=p_branch_id
   and (p_after is null or r.id>p_after) and s.snapshot->>'status'='active'
  order by r.id limit 51
 )q;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id,'as_of',p_as_of,'coverage_start',coverage);
end $$;
revoke all on function api.stock_reservations_as_of(uuid,uuid,uuid,timestamptz,uuid) from public,anon,authenticated;
grant execute on function api.stock_reservations_as_of(uuid,uuid,uuid,timestamptz,uuid) to authenticated;

-- Candidate: quantity attribution only; existing valuation/journal engines are unchanged.
create table inventory.receipt_provenance_entries (
 id bigint generated always as identity primary key,
 tenant_id uuid not null, legal_entity_id uuid not null, branch_id uuid not null,
 movement_line_id uuid not null, origin_line_id uuid, restores_entry_id bigint,
 warehouse_id uuid not null, product_id uuid not null, lot_id uuid, serial_id uuid,
 quantity numeric(20,6) not null check(quantity<>0), recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,id),
 foreign key(tenant_id,movement_line_id) references inventory.stock_movement_lines(tenant_id,id),
 foreign key(tenant_id,origin_line_id) references inventory.stock_movement_lines(tenant_id,id),
 foreign key(tenant_id,restores_entry_id) references inventory.receipt_provenance_entries(tenant_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(product_id) references inventory.products(id),
 foreign key(tenant_id,lot_id) references inventory.lots(tenant_id,id),
 foreign key(tenant_id,serial_id) references inventory.serials(tenant_id,id)
);
create table inventory.receipt_provenance_positions (
 id bigint generated always as identity primary key,
 tenant_id uuid not null, warehouse_id uuid not null, product_id uuid not null,
 lot_id uuid, serial_id uuid, origin_line_id uuid, entry_id bigint,
 quantity numeric(20,6) not null check(quantity>=0),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(product_id) references inventory.products(id),
 foreign key(tenant_id,lot_id) references inventory.lots(tenant_id,id),
 foreign key(tenant_id,serial_id) references inventory.serials(tenant_id,id),
 foreign key(tenant_id,origin_line_id) references inventory.stock_movement_lines(tenant_id,id),
 foreign key(tenant_id,entry_id) references inventory.receipt_provenance_entries(tenant_id,id)
);
create table inventory.receipt_provenance_pools (
 tenant_id uuid not null,warehouse_id uuid not null,product_id uuid not null,lot_id uuid,serial_id uuid,
 captured_at timestamptz not null default clock_timestamp(), baseline_quantity numeric(20,6) not null check(baseline_quantity>=0),
 unique nulls not distinct(tenant_id,warehouse_id,product_id,lot_id,serial_id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(product_id) references inventory.products(id),
 foreign key(tenant_id,lot_id) references inventory.lots(tenant_id,id),
 foreign key(tenant_id,serial_id) references inventory.serials(tenant_id,id)
);
create index provenance_position_pool on inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,id) where quantity>0;
create index provenance_entry_movement on inventory.receipt_provenance_entries(tenant_id,movement_line_id,id);
create index provenance_entry_origin on inventory.receipt_provenance_entries(tenant_id,origin_line_id,id);
create index provenance_entry_restore on inventory.receipt_provenance_entries(tenant_id,restores_entry_id);
create index provenance_position_origin on inventory.receipt_provenance_positions(tenant_id,origin_line_id);
do $$declare t text; f record; begin
 foreach t in array array['receipt_provenance_entries','receipt_provenance_positions','receipt_provenance_pools'] loop
  execute format('alter table inventory.%I enable row level security',t);
  execute format('alter table inventory.%I force row level security',t);
  execute format('revoke all on inventory.%I from public,anon,authenticated',t);
  for f in select c.conname,c.conkey,(select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(c.conkey) with ordinality k(num,n)
   join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.num) cols from pg_constraint c
   where c.conrelid=format('inventory.%I',t)::regclass and c.contype='f' loop
   if exists(select 1 from pg_index i where i.indrelid=format('inventory.%I',t)::regclass and i.indisvalid and i.indpred is null
    and (select array_agg(k.num::smallint order by k.n) from unnest(i.indkey) with ordinality k(num,n) where k.n<=cardinality(f.conkey))=f.conkey) then continue;end if;
   execute format('create index %I on inventory.%I(%s)',left(t,19)||'_'||md5(f.conname)||'_fk',t,f.cols);
  end loop;
 end loop;
end $$;
create trigger immutable before update or delete on inventory.receipt_provenance_entries for each row execute function workflow.reject_history_mutation();
create trigger immutable before update or delete on inventory.receipt_provenance_pools for each row execute function workflow.reject_history_mutation();

create function inventory.record_receipt_provenance() returns trigger language plpgsql security definer set search_path='' as $$
declare m inventory.stock_movements%rowtype; related uuid; sid uuid; ids uuid[]; q numeric; prior numeric; available numeric;
 remaining numeric; take numeric; eid bigint; origin uuid; pos record; entry record; v_source_type text; steps integer:=0;
begin
 if new.base_quantity=0 then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':'||new.warehouse_id::text||':'||new.product_id::text,0));
 select * into strict m from inventory.stock_movements where tenant_id=new.tenant_id and id=new.stock_movement_id;
 related:=new.original_movement_line_id;
 if m.source_type in('transfer.receive','transfer.reverse.receipt','transfer.reverse.issue') then
  v_source_type:=case when m.source_type='transfer.receive' then 'transfer.dispatch'
   when m.source_type='transfer.reverse.issue' then 'transfer.receive'
   when exists(select 1 from inventory.stock_movements x where x.tenant_id=new.tenant_id and x.source_id=m.source_id and x.source_type='transfer.reverse.issue') then 'transfer.reverse.issue'
   else 'transfer.dispatch' end;
  select l.id into related from inventory.stock_movement_lines l join inventory.stock_movements x on x.id=l.stock_movement_id
   where x.tenant_id=new.tenant_id and x.source_id=m.source_id and x.source_type=v_source_type and l.source_line_id=new.source_line_id;
  if related is null then raise exception using errcode='55000',message='PROVENANCE_TRANSFER_SOURCE_MISSING';end if;
 end if;
 ids:=case when cardinality(new.serial_ids)>0 then new.serial_ids else array[null::uuid] end;
 if cardinality(new.serial_ids)>0 and abs(new.base_quantity)<>cardinality(new.serial_ids) then raise exception using errcode='55000',message='PROVENANCE_SERIAL_QUANTITY_MISMATCH';end if;
 foreach sid in array ids loop
  q:=case when sid is null then new.base_quantity else sign(new.base_quantity) end;
  if sid is not null and q>0 and m.source_type='stock_count' then
   -- A governed recount restores the same missing serial, not an invented receipt.
   select e.movement_line_id into related from inventory.receipt_provenance_entries e
    join inventory.stock_movement_lines ml on ml.id=e.movement_line_id join inventory.stock_movements sm on sm.id=ml.stock_movement_id
    where e.tenant_id=new.tenant_id and e.serial_id=sid and e.warehouse_id=new.warehouse_id and e.quantity<0 and sm.source_type='stock_count'
    and not exists(select 1 from inventory.receipt_provenance_entries r where r.restores_entry_id=e.id) order by e.id desc limit 1;
  end if;
  -- Transfer validates serial disposition after its ledger leg; preserve that public error.
  if sid is not null and m.source_type='transfer.dispatch' and not exists(select 1 from inventory.serials s
   where s.tenant_id=new.tenant_id and s.id=sid and s.warehouse_id=new.warehouse_id and s.status='available') then
   raise exception using errcode='55000',message='TRANSFER_SERIAL_UNAVAILABLE';end if;
  if not exists(select 1 from inventory.receipt_provenance_pools p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id
   and p.lot_id is not distinct from new.lot_id and p.serial_id is not distinct from sid) then
   if sid is not null then prior:=case when q<0 then 1 else 0 end;
   elsif new.lot_id is not null then
    select on_hand_quantity-q into prior from inventory.lot_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and lot_id=new.lot_id;
   else
    select on_hand_quantity-q into prior from inventory.stock_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and product_id=new.product_id;
    -- Untracked pool excludes independently tracked pools if legacy synthetic data mixed tracking modes.
    prior:=prior-coalesce((select sum(quantity) from inventory.receipt_provenance_positions p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id and (p.lot_id is not null or p.serial_id is not null)),0);
   end if;
   if prior is null or prior<0 then raise exception using errcode='55000',message='PROVENANCE_BASELINE_INVALID';end if;
   insert into inventory.receipt_provenance_pools(tenant_id,warehouse_id,product_id,lot_id,serial_id,baseline_quantity)
    values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,prior);
   if prior>0 then insert into inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,quantity)
    values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,prior);end if;
  end if;
  remaining:=abs(q);
  if sid is not null then
   select coalesce(sum(p.quantity),0)+q into available from inventory.receipt_provenance_positions p
    where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id and p.serial_id=sid;
   if available not in(0,1) then raise exception using errcode='55000',message='PROVENANCE_SERIAL_QUANTITY_MISMATCH';end if;
  end if;
  if sid is null then
   select coalesce(sum(p.quantity),0)+q into available from inventory.receipt_provenance_positions p
    where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id
    and p.lot_id is not distinct from new.lot_id and p.serial_id is null;
   if new.lot_id is not null then
    select on_hand_quantity into prior from inventory.lot_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and lot_id=new.lot_id;
   else
    select on_hand_quantity-coalesce((select sum(p.quantity) from inventory.receipt_provenance_positions p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id and (p.lot_id is not null or p.serial_id is not null)),0)
     into prior from inventory.stock_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and product_id=new.product_id;
   end if;
   if available is distinct from prior then raise exception using errcode='55000',message='PROVENANCE_STOCK_MISMATCH';end if;
  end if;
  if q<0 then
   for pos in select * from inventory.receipt_provenance_positions p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id
    and p.lot_id is not distinct from new.lot_id and p.serial_id is not distinct from sid and p.quantity>0
    order by case when related is not null and (p.origin_line_id=related or p.entry_id in(select e.id from inventory.receipt_provenance_entries e where e.movement_line_id=related)) then 0 else 1 end,p.id for update loop
    take:=least(remaining,pos.quantity);
    steps:=steps+1;if steps>1000 then raise exception using errcode='54000',message='PROVENANCE_MOVEMENT_LIMIT';end if;
    insert into inventory.receipt_provenance_entries(tenant_id,legal_entity_id,branch_id,movement_line_id,origin_line_id,warehouse_id,product_id,lot_id,serial_id,quantity)
     values(new.tenant_id,new.legal_entity_id,new.branch_id,new.id,pos.origin_line_id,new.warehouse_id,new.product_id,new.lot_id,sid,-take);
    update inventory.receipt_provenance_positions set quantity=quantity-take where id=pos.id;
    remaining:=remaining-take;exit when remaining=0;
   end loop;
   if remaining<>0 then raise exception using errcode='55000',message='PROVENANCE_STOCK_MISMATCH';end if;
  else
   -- Returns and transfer receipts restore the exact recorded negative attribution.
   if related is not null then
    for entry in select e.*, -e.quantity-coalesce((select sum(r.quantity) from inventory.receipt_provenance_entries r where r.restores_entry_id=e.id),0) restorable
     from inventory.receipt_provenance_entries e where e.tenant_id=new.tenant_id and e.movement_line_id=related and e.quantity<0 and e.serial_id is not distinct from sid order by e.id loop
     take:=least(remaining,entry.restorable);if take<=0 then continue;end if;
     steps:=steps+1;if steps>1000 then raise exception using errcode='54000',message='PROVENANCE_MOVEMENT_LIMIT';end if;
     insert into inventory.receipt_provenance_entries(tenant_id,legal_entity_id,branch_id,movement_line_id,origin_line_id,restores_entry_id,warehouse_id,product_id,lot_id,serial_id,quantity)
      values(new.tenant_id,new.legal_entity_id,new.branch_id,new.id,entry.origin_line_id,entry.id,new.warehouse_id,new.product_id,new.lot_id,sid,take) returning id into eid;
     insert into inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,origin_line_id,entry_id,quantity)
      values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,entry.origin_line_id,eid,take);
     remaining:=remaining-take;exit when remaining=0;
    end loop;
    if remaining<>0 and exists(select 1 from inventory.receipt_provenance_entries e where e.tenant_id=new.tenant_id and e.movement_line_id=related) then
     raise exception using errcode='55000',message='PROVENANCE_RESTORE_EXCEEDS_SOURCE';end if;
   end if;
   if remaining>0 then
    origin:=case when m.source_type='goods_receipt' then new.id end;
    insert into inventory.receipt_provenance_entries(tenant_id,legal_entity_id,branch_id,movement_line_id,origin_line_id,warehouse_id,product_id,lot_id,serial_id,quantity)
     values(new.tenant_id,new.legal_entity_id,new.branch_id,new.id,origin,new.warehouse_id,new.product_id,new.lot_id,sid,remaining) returning id into eid;
    insert into inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,origin_line_id,entry_id,quantity)
     values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,origin,eid,remaining);
   end if;
  end if;
 end loop;
 return new;
end $$;
revoke all on function inventory.record_receipt_provenance() from public,anon,authenticated;
create trigger receipt_provenance after insert on inventory.stock_movement_lines for each row execute function inventory.record_receipt_provenance();

create function api.receipt_trace_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb; cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from (
  select l.id,m.source_id receipt_id,coalesce(r.document_number,m.source_id::text) document_number,p.name product_name,w.name warehouse_name,
   l.base_quantity::text received_quantity,l.posting_date,exists(select 1 from inventory.receipt_provenance_entries e where e.tenant_id=l.tenant_id and e.origin_line_id=l.id) covered
  from inventory.stock_movement_lines l join inventory.stock_movements m on m.id=l.stock_movement_id and m.source_type='goods_receipt'
  join inventory.products p on p.id=l.product_id join core.warehouses w on w.id=l.warehouse_id
  left join procurement.goods_receipts r on r.id=m.source_id
  where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and l.branch_id=p_branch_id and l.base_quantity>0 and(p_after is null or l.id>p_after)
  order by l.id limit 51)q;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor);
end $$;
create function api.receipt_trace_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,p_after bigint default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare l inventory.stock_movement_lines%rowtype; holdings jsonb; history jsonb; cursor bigint; held numeric; transit numeric; covered boolean;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 select x.* into l from inventory.stock_movement_lines x join inventory.stock_movements m on m.id=x.stock_movement_id and m.source_type='goods_receipt'
  where x.id=p_id and x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.branch_id=p_branch_id and x.base_quantity>0;
 if not found then raise exception using errcode='P0002',message='RECEIPT_TRACE_NOT_FOUND';end if;
 if exists(select 1 from inventory.receipt_provenance_entries e where e.tenant_id=p_tenant_id and e.origin_line_id=p_id
  and (not core.has_permission(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,e.branch_id)
   or not core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,e.branch_id))) then
  raise exception using errcode='42501',message='RECEIPT_TRACE_BRANCH_SCOPE_REQUIRED';end if;
 covered:=exists(select 1 from inventory.receipt_provenance_entries e where e.tenant_id=p_tenant_id and e.origin_line_id=p_id);
 select coalesce(jsonb_agg(to_jsonb(q) order by q.warehouse_id),'[]') into holdings from (
  select p.warehouse_id,w.name warehouse_name,sum(p.quantity)::text quantity from inventory.receipt_provenance_positions p join core.warehouses w on w.id=p.warehouse_id
  where p.tenant_id=p_tenant_id and p.origin_line_id=p_id and p.quantity>0 group by p.warehouse_id,w.name order by p.warehouse_id limit 101)q;
 if jsonb_array_length(holdings)>100 then raise exception using errcode='54000',message='RECEIPT_TRACE_WAREHOUSE_LIMIT';end if;
 select coalesce(sum(quantity),0) into held from inventory.receipt_provenance_positions where tenant_id=p_tenant_id and origin_line_id=p_id;
 select coalesce(sum(-e.quantity-coalesce((select sum(r.quantity) from inventory.receipt_provenance_entries r where r.restores_entry_id=e.id),0)),0)
  into transit from inventory.receipt_provenance_entries e join inventory.stock_movement_lines ml on ml.id=e.movement_line_id
  join inventory.stock_movements m on m.id=ml.stock_movement_id where e.tenant_id=p_tenant_id and e.origin_line_id=p_id and e.quantity<0 and m.source_type in('transfer.dispatch','transfer.reverse.issue');
 select coalesce(jsonb_agg(to_jsonb(q) order by q.sequence),'[]') into history from (
  select e.id::text sequence,e.quantity::text quantity,e.recorded_at,m.source_type,m.source_id,ml.posting_date,w.name warehouse_name,
   lot.code lot_code,s.code serial_code,e.restores_entry_id::text restores_sequence
  from inventory.receipt_provenance_entries e join inventory.stock_movement_lines ml on ml.id=e.movement_line_id
  join inventory.stock_movements m on m.id=ml.stock_movement_id join core.warehouses w on w.id=e.warehouse_id
  left join inventory.lots lot on lot.id=e.lot_id left join inventory.serials s on s.id=e.serial_id
  where e.tenant_id=p_tenant_id and e.origin_line_id=p_id and (p_after is null or e.id>p_after) order by e.id limit 51)q;
 -- Preserve numeric sequence order, while exposing bigint as strings to clients.
 select coalesce(jsonb_agg(x order by (x->>'sequence')::bigint),'[]') into history from jsonb_array_elements(history)x;
 if jsonb_array_length(history)>50 then cursor:=(history->49->>'sequence')::bigint;history:=history-50;end if;
 return jsonb_build_object('id',p_id,'covered',covered,'received_quantity',l.base_quantity::text,
  'held_quantity',case when covered then held::text end,'in_transit_quantity',case when covered then transit::text end,
  'net_issued_quantity',case when covered then (l.base_quantity-held-transit)::text end,
  'holdings',holdings,'items',history,'next_cursor',cursor::text,'observed_at',statement_timestamp(),
  'attribution_rule','Oldest recorded cohort within each lot or untracked pool; exact serial identity. Weighted-average valuation is unchanged.');
end $$;
revoke all on function api.receipt_trace_page(uuid,uuid,uuid,uuid),api.receipt_trace_detail(uuid,uuid,uuid,uuid,bigint) from public,anon,authenticated;
grant execute on function api.receipt_trace_page(uuid,uuid,uuid,uuid),api.receipt_trace_detail(uuid,uuid,uuid,uuid,bigint) to authenticated;
notify pgrst, 'reload schema';



-- Unapplied candidate. Exact value-only ledger entries; no second accounting engine.
create table inventory.value_adjustments (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 receipt_line_id uuid not null,reverse_of uuid,document_date date not null,reference text not null,reason text not null,
 amount numeric(20,6) not null check(amount<>0),currency_code text not null,
 offset_account_id uuid not null,variance_account_id uuid not null,detail jsonb not null,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),
 created_at timestamptz not null default clock_timestamp(),unique(tenant_id,id),unique(tenant_id,reverse_of),
 foreign key(tenant_id,receipt_line_id) references inventory.stock_movement_lines(tenant_id,id),
 foreign key(tenant_id,reverse_of) references inventory.value_adjustments(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,offset_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,variance_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
alter table inventory.value_adjustments enable row level security;
alter table inventory.value_adjustments force row level security;
revoke all on inventory.value_adjustments from public,anon,authenticated;
create trigger immutable before update or delete on inventory.value_adjustments for each row execute function workflow.reject_history_mutation();
create index value_adjustments_scope on inventory.value_adjustments(tenant_id,legal_entity_id,branch_id,id);
create index value_adjustments_receipt on inventory.value_adjustments(tenant_id,receipt_line_id);
create index value_adjustments_actor on inventory.value_adjustments(created_by);
create index value_adjustments_offset on inventory.value_adjustments(tenant_id,legal_entity_id,offset_account_id);
create index value_adjustments_variance on inventory.value_adjustments(tenant_id,legal_entity_id,variance_account_id);
create index value_adjustments_branch on inventory.value_adjustments(tenant_id,branch_id);

alter table inventory.stock_movement_lines drop constraint stock_movement_lines_base_quantity_check;
alter table inventory.stock_movement_lines drop constraint stock_movement_lines_check;
alter table inventory.stock_movement_lines add constraint stock_movement_lines_base_quantity_check check(base_quantity<>0 or base_value<>0);
alter table inventory.stock_movement_lines add constraint stock_movement_lines_check check(base_quantity=0 or base_value=0 or sign(base_quantity)=sign(base_value));
do $$declare c text;begin
 select pg_get_constraintdef(oid) into c from pg_constraint where conrelid='inventory.stock_movements'::regclass and conname='stock_movements_movement_kind_check';
 if c is null then raise exception 'MOVEMENT_CONSTRAINT_DRIFT';end if;
 alter table inventory.stock_movements drop constraint stock_movements_movement_kind_check;
 execute 'alter table inventory.stock_movements add constraint stock_movements_movement_kind_check CHECK ('||substring(c from 7)||' OR movement_kind=''value_adjustment'')';
end $$;
create function inventory.guard_value_movement() returns trigger language plpgsql security definer set search_path='' as $$
declare m inventory.stock_movements%rowtype; seq bigint;begin
 select * into strict m from inventory.stock_movements where id=new.stock_movement_id;
 if (new.base_quantity=0) is distinct from (m.movement_kind='value_adjustment') then raise exception using errcode='23514',message='VALUE_MOVEMENT_KIND_REQUIRED';end if;
 if m.source_type='goods_receipt_reversal' and exists(select 1 from inventory.value_adjustments a
  where a.tenant_id=new.tenant_id and a.receipt_line_id=new.original_movement_line_id and a.reverse_of is null
  and not exists(select 1 from inventory.value_adjustments r where r.reverse_of=a.id)) then
  raise exception using errcode='55000',message='REVERSE_LANDED_VALUE_FIRST';end if;
 if m.source_type='transfer.reverse.issue' then
  select coalesce(max(e.id),0) into seq from inventory.receipt_provenance_entries e join inventory.stock_movement_lines ml on ml.id=e.movement_line_id
   join inventory.stock_movements sm on sm.id=ml.stock_movement_id where sm.tenant_id=new.tenant_id and sm.source_type='transfer.receive'
   and sm.source_id=m.source_id and ml.source_line_id=new.source_line_id;
  if exists(select 1 from inventory.value_adjustments a,jsonb_array_elements(a.detail->'legs') leg where a.tenant_id=new.tenant_id and a.reverse_of is null
   and not exists(select 1 from inventory.value_adjustments r where r.reverse_of=a.id)
   and leg->>'warehouse_id'=new.warehouse_id::text and leg->>'product_id'=new.product_id::text and (leg->>'provenance_sequence')::bigint>=seq) then
   raise exception using errcode='55000',message='TRANSFER_VALUE_CHANGED';end if;
 end if;
 return new;
end $$;
revoke all on function inventory.guard_value_movement() from public,anon,authenticated;
create trigger guard_value_movement before insert on inventory.stock_movement_lines for each row execute function inventory.guard_value_movement();

create function inventory.value_basis(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare ml inventory.stock_movement_lines%rowtype; receipt procurement.goods_receipts%rowtype; product inventory.products%rowtype;
 trace jsonb; row record; legs jsonb:='[]'; q numeric:=0; previous numeric:=0; next_value numeric; amount numeric; currency text; d date;
 offset_id uuid:=(p_payload->>'offset_account_id')::uuid; variance_id uuid:=(p_payload->>'variance_account_id')::uuid; result jsonb;
begin
 perform core.wave3_require_scope(p_tenant,'inventory.valuation.post',p_entity,p_branch);
 perform core.wave3_require_scope(p_tenant,'inventory.cost.view',p_entity,p_branch);
 if p_entity is null or p_branch is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 select x.* into ml from inventory.stock_movement_lines x join inventory.stock_movements m on m.id=x.stock_movement_id and m.source_type='goods_receipt'
  where x.tenant_id=p_tenant and x.legal_entity_id=p_entity and x.branch_id=p_branch and x.id=(p_payload->>'receipt_line_id')::uuid;
 if not found then raise exception using errcode='22023',message='LANDED_RECEIPT_INVALID';end if;
 select r.* into receipt from procurement.goods_receipts r where r.stock_movement_id=ml.stock_movement_id;
 if not found or exists(select 1 from procurement.goods_receipt_reversals where receipt_id=receipt.id) then raise exception using errcode='22023',message='LANDED_RECEIPT_INVALID';end if;
 select * into product from inventory.products where id=ml.product_id and status='active';
 if not found then raise exception using errcode='22023',message='LANDED_PRODUCT_INACTIVE';end if;
 select currency_code into currency from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 amount:=sales.wave3_decimal_string(p_payload->'amount','amount',6,true,0.000001,null);
 d:=(p_payload->>'document_date')::date;
 if d is null or d<ml.posting_date or d>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='LANDED_DATE_INVALID';end if;
 perform finance.flow_account(p_tenant,p_entity,offset_id,'expense',currency);
 perform finance.flow_account(p_tenant,p_entity,variance_id,'expense',currency);
 perform finance.flow_account(p_tenant,p_entity,product.inventory_account_id,'asset',currency);
 if (select count(*) from core.warehouses where tenant_id=p_tenant and legal_entity_id=p_entity)>500 then raise exception using errcode='54000',message='LANDED_WAREHOUSE_LIMIT';end if;
 -- Same sorted lock keys as transfers/receipts. Lock before reading the projection.
 for row in select id from core.warehouses where tenant_id=p_tenant and legal_entity_id=p_entity order by id loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||row.id::text||':'||ml.product_id::text,0));
 end loop;
 trace:=api.receipt_trace_detail(p_tenant,p_entity,p_branch,ml.id);
 if trace->>'covered'<>'true' or (trace->>'held_quantity')::numeric<=0 then raise exception using errcode='22023',message='LANDED_RECEIPT_CONSUMED_OR_UNCOVERED',detail=ml.id::text;end if;
 if (trace->>'in_transit_quantity')::numeric<>0 then raise exception using errcode='55000',message='LANDED_RECEIPT_IN_TRANSIT',detail=ml.id::text;end if;
 if exists(select 1 from inventory.receipt_provenance_entries e join inventory.stock_movement_lines x on x.id=e.movement_line_id
  join inventory.stock_movements m on m.id=x.stock_movement_id where e.tenant_id=p_tenant and e.origin_line_id=ml.id
  and m.source_type not in('goods_receipt','delivery','sales_return','transfer.dispatch','transfer.receive','transfer.reverse.issue','transfer.reverse.receipt')) then
  raise exception using errcode='55000',message='LANDED_RECEIPT_DISPOSITION_REVIEW',detail=ml.id::text;end if;
 for row in select p.warehouse_id,w.branch_id,w.name warehouse_name,sum(p.quantity) quantity,b.id balance_id,v.id valuation_id,v.version valuation_version,v.carrying_value,
  coalesce((select max(e.id) from inventory.receipt_provenance_entries e where e.tenant_id=p_tenant and e.warehouse_id=p.warehouse_id and e.product_id=ml.product_id),0) provenance_sequence
  from inventory.receipt_provenance_positions p join core.warehouses w on w.id=p.warehouse_id
  join inventory.stock_balances b on b.tenant_id=p_tenant and b.warehouse_id=p.warehouse_id and b.product_id=ml.product_id
  join inventory.stock_valuations v on v.stock_balance_id=b.id
  where p.tenant_id=p_tenant and p.origin_line_id=ml.id and p.quantity>0
  group by p.warehouse_id,w.branch_id,w.name,b.id,v.id,v.version,v.carrying_value order by p.warehouse_id loop
  perform core.wave3_require_scope(p_tenant,'inventory.valuation.post',p_entity,row.branch_id);
  perform core.wave3_require_scope(p_tenant,'inventory.cost.view',p_entity,row.branch_id);
  if exists(select 1 from inventory.stock_movement_lines where tenant_id=p_tenant and warehouse_id=row.warehouse_id and product_id=ml.product_id and posting_date>d) then
   raise exception using errcode='55000',message='LANDED_BACKDATED_VALUE_REVIEW';end if;
  q:=q+row.quantity;next_value:=round(amount*q/ml.base_quantity,6);
  legs:=legs||jsonb_build_array(jsonb_build_object('warehouse_id',row.warehouse_id,'warehouse_name',row.warehouse_name,'branch_id',row.branch_id,
   'product_id',ml.product_id,'quantity',row.quantity::text,'value',(next_value-previous)::text,'valuation_id',row.valuation_id,
   'valuation_version',row.valuation_version::text,'carrying_value',row.carrying_value::text,'provenance_sequence',row.provenance_sequence::text,'inventory_account_id',product.inventory_account_id));
  previous:=next_value;
 end loop;
 if q>ml.base_quantity or q<=0 or q<>(trace->>'held_quantity')::numeric then raise exception using errcode='55000',message='LANDED_PROVENANCE_MISMATCH';end if;
 result:=jsonb_build_object('receipt_line_id',ml.id,'receipt_number',receipt.document_number,'product_name',product.name,'currency_code',currency,'document_date',d,
  'received_quantity',ml.base_quantity::text,'held_quantity',q::text,'consumed_quantity',(ml.base_quantity-q)::text,'amount',amount::text,
  'inventory_amount',previous::text,'variance_amount',(amount-previous)::text,'offset_account_id',offset_id,'variance_account_id',variance_id,'legs',legs,
  'provenance_version',(select max(id)::text from inventory.receipt_provenance_entries where tenant_id=p_tenant and origin_line_id=ml.id));
 return result||jsonb_build_object('basis_hash',md5(result::text));
end $$;
revoke all on function inventory.value_basis(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function api.preview_inventory_value_adjustment(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_payload jsonb) returns jsonb
language sql security definer set search_path='' as $$select inventory.value_basis(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload)$$;

create function api.post_inventory_value_adjustment(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid; parent uuid:=(p_payload->>'reverse_of')::uuid; original inventory.value_adjustments%rowtype;
 h text; result jsonb; basis jsonb; leg jsonb; posted jsonb:='[]'; journals jsonb:='[]'; v numeric; variance numeric; amount numeric;
 req uuid:=gen_random_uuid(); mid uuid; jid uuid; version bigint; d date:=(p_payload->>'document_date')::date; doc jsonb; row record;
 reason text:=trim(p_payload->>'reason');reference text:=trim(p_payload->>'reference');offset_id uuid;variance_id uuid;currency text;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or v_id is null or p_client_timestamp is null or d is null
  or d>(clock_timestamp() at time zone 'UTC')::date or coalesce(length(reason),0) not between 3 and 1000 or coalesce(length(reference),0) not between 1 and 140 then
  raise exception using errcode='22023',message='LANDED_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.value.adjust',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.value.adjust',p_command_id,p_idempotency_key,h);
 if result is not null then
  for leg in select value from jsonb_array_elements(result#>'{entity,legs}') loop
   perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(leg->>'branch_id')::uuid);
   perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(leg->>'branch_id')::uuid);
  end loop;return result;
 end if;
 if parent is null then
  perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
  basis:=inventory.value_basis(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
  if p_payload->>'basis_hash' is distinct from basis->>'basis_hash' then raise exception using errcode='40001',message='LANDED_PREVIEW_CHANGED';end if;
 else
  select * into original from inventory.value_adjustments where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=parent for update;
  if not found or original.reverse_of is not null then raise exception using errcode='22023',message='LANDED_REVERSAL_SOURCE_INVALID';end if;
  perform core.wave3_assert_expected_version(case when exists(select 1 from inventory.value_adjustments where reverse_of=parent) then 2 else 1 end,p_expected_entity_version,'{}');
  if d<original.document_date then raise exception using errcode='22023',message='LANDED_DATE_INVALID';end if;
  basis:=original.detail;basis:=jsonb_set(basis,'{document_date}',to_jsonb(d));
  for leg in select value from jsonb_array_elements(basis->'legs') order by value->>'warehouse_id' loop
   perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(leg->>'branch_id')::uuid);
   perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(leg->>'branch_id')::uuid);
   perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||(leg->>'warehouse_id')||':'||(leg->>'product_id'),0));
   select v2.version into version from inventory.stock_valuations v2 where v2.id=(leg->>'valuation_id')::uuid for update;
   if version is distinct from (leg->>'posted_valuation_version')::bigint then raise exception using errcode='55000',message='LANDED_REVERSAL_STOCK_CHANGED';end if;
  end loop;
 end if;
 currency:=basis->>'currency_code';offset_id:=(basis->>'offset_account_id')::uuid;variance_id:=(basis->>'variance_account_id')::uuid;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,offset_id,'expense',currency);
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,variance_id,'expense',currency);
 amount:=(basis->>'amount')::numeric*case when parent is null then 1 else -1 end;
 variance:=(basis->>'variance_amount')::numeric*case when parent is null then 1 else -1 end;
 doc:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'document_date',d,'currency_code',currency,'base_currency_code',currency,'exchange_rate','1');
 for leg in select value from jsonb_array_elements(basis->'legs') order by value->>'warehouse_id' loop
  v:=(leg->>'value')::numeric*case when parent is null then 1 else -1 end;
  perform finance.flow_account(p_tenant_id,p_legal_entity_id,(leg->>'inventory_account_id')::uuid,'asset',currency);
  if v<>0 then
   update inventory.stock_valuations set carrying_value=carrying_value+v,updated_by=auth.uid()
    where id=(leg->>'valuation_id')::uuid and carrying_value+v>=0 returning stock_valuations.version into version;
   if not found then raise exception using errcode='55000',message='LANDED_VALUE_UNAVAILABLE';end if;
   mid:=gen_random_uuid();
   insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
    values(mid,p_tenant_id,p_legal_entity_id,(leg->>'branch_id')::uuid,'inventory_value_adjustment',mid,(leg->>'warehouse_id')::uuid,d,'value_adjustment',req,p_command_id,req,auth.uid());
   insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,original_movement_line_id,base_quantity,base_value,posting_date,created_by)
    values(p_tenant_id,p_legal_entity_id,(leg->>'branch_id')::uuid,mid,(leg->>'warehouse_id')::uuid,(leg->>'product_id')::uuid,v_id,(basis->>'receipt_line_id')::uuid,0,v,d,auth.uid());
   jid:=finance.flow_post_journal(doc||jsonb_build_object('branch_id',leg->>'branch_id'),jsonb_build_array(
    finance.flow_jline((leg->>'inventory_account_id')::uuid,v,v,v_id),finance.flow_jline(offset_id,-v,-v,v_id)),
    'inventory_value_adjustment',mid,req,p_command_id);
   journals:=journals||jsonb_build_array(jid);
  else version:=(leg->>'valuation_version')::bigint;end if;
  posted:=posted||jsonb_build_array(leg||jsonb_build_object('value',v::text,'posted_valuation_version',version::text,'stock_movement_id',mid));mid:=null;
 end loop;
 if variance<>0 then
  jid:=finance.flow_post_journal(doc,jsonb_build_array(finance.flow_jline(variance_id,variance,variance,v_id),finance.flow_jline(offset_id,-variance,-variance,v_id)),
   'inventory_value_variance',v_id,req,p_command_id);journals:=journals||jsonb_build_array(jid);
 end if;
 result:=basis||jsonb_build_object('id',v_id,'version',1,'status','posted','reverse_of',parent,'amount',amount::text,
  'inventory_amount',(amount-variance)::text,'variance_amount',variance::text,'legs',posted,'journal_ids',journals,'reason',reason,'reference',reference,'document_date',d);
 insert into inventory.value_adjustments(id,tenant_id,legal_entity_id,branch_id,receipt_line_id,reverse_of,document_date,reference,reason,amount,currency_code,offset_account_id,variance_account_id,detail,request_id,command_id,created_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,(basis->>'receipt_line_id')::uuid,parent,d,reference,reason,amount,currency,offset_id,variance_id,result,req,p_command_id,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'inventory.value.adjust',p_command_id,'inventory_value_adjustment',v_id,p_idempotency_key,h,null,result,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','posted','operation',case when parent is null then 'post' else 'reverse' end,'reason',reason),
  jsonb_build_array(jsonb_build_object('topic','inventory.value.adjust','payload',jsonb_build_object('id',v_id))),'[]',req,req);
end $$;
revoke all on function api.preview_inventory_value_adjustment(uuid,uuid,uuid,jsonb),api.post_inventory_value_adjustment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.preview_inventory_value_adjustment(uuid,uuid,uuid,jsonb),api.post_inventory_value_adjustment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.inventory_value_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 if p_resource='receipts' then return api.receipt_trace_page(p_tenant_id,p_legal_entity_id,p_branch_id,p_after);
 elsif p_resource='accounts' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from (select a.id,a.code,a.name from finance.accounts a join core.legal_entities e on e.id=a.legal_entity_id
   where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id and a.account_type='expense' and a.is_posting and a.status='active'
   and(a.currency_code is null or a.currency_code=e.currency_code) and(p_after is null or a.id>p_after) order by a.id limit 51)q;
 elsif p_resource='posted' then
  select coalesce(jsonb_agg(q.detail order by q.id),'[]') into rows from (
   select a.id,a.detail||jsonb_build_object('version',case when exists(select 1 from inventory.value_adjustments r where r.reverse_of=a.id) then 2 else 1 end,
    'reversed',exists(select 1 from inventory.value_adjustments r where r.reverse_of=a.id)) detail from inventory.value_adjustments a
   where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id and a.branch_id=p_branch_id and(p_after is null or a.id>p_after)
   and not exists(select 1 from jsonb_array_elements(a.detail->'legs') l where not core.has_permission(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(l->>'branch_id')::uuid)
    or not core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(l->>'branch_id')::uuid)) order by a.id limit 51)q;
 else raise exception using errcode='22023',message='LANDED_RESOURCE_INVALID';end if;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor);
end $$;
revoke all on function api.inventory_value_options(uuid,uuid,uuid,text,uuid) from public,anon,authenticated;
grant execute on function api.inventory_value_options(uuid,uuid,uuid,text,uuid) to authenticated;
notify pgrst,'reload schema';


-- Candidate only. Saved evidence from existing immutable ledgers, no new postings.
create table inventory.valuation_reports (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 as_of date not null,generated_at timestamptz not null,summary jsonb not null,evidence jsonb not null,
 created_by uuid not null references auth.users(id),unique(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(octet_length(evidence::text)<=16777216)
);
alter table inventory.valuation_reports enable row level security;
alter table inventory.valuation_reports force row level security;
revoke all on inventory.valuation_reports from public,anon,authenticated;
create trigger immutable before update or delete on inventory.valuation_reports for each row execute function workflow.reject_history_mutation();
create index valuation_reports_scope on inventory.valuation_reports(tenant_id,legal_entity_id,branch_id,id);
create index valuation_reports_branch on inventory.valuation_reports(tenant_id,branch_id);
create index valuation_reports_actor on inventory.valuation_reports(created_by);
create index stock_lines_valuation_date on inventory.stock_movement_lines(tenant_id,legal_entity_id,posting_date,id);
create index journal_lines_valuation_date on finance.journal_lines(tenant_id,legal_entity_id,account_id,posting_date,id);

create function inventory.require_valuation_report_scope(t uuid,e uuid,b uuid) returns void
language plpgsql stable security definer set search_path='' as $$declare r record;p text;begin
 if e is null or b is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 perform core.wave3_require_scope(t,'inventory.stock.view',e,b);
 if (select count(*) from core.branches where tenant_id=t and legal_entity_id=e)>500 then raise exception using errcode='54000',message='VALUATION_BRANCH_LIMIT';end if;
 for r in select id from core.branches where tenant_id=t and legal_entity_id=e loop
  foreach p in array array['inventory.stock.view','inventory.cost.view','finance.view'] loop
   perform core.require_permission(t,p,e,r.id);
  end loop;
 end loop;
end $$;
revoke all on function inventory.require_valuation_report_scope(uuid,uuid,uuid) from public,anon,authenticated;

-- STABLE deliberately fixes one database snapshot for all ledger reads below.
create function inventory.build_valuation_report(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d date:=(p->>'as_of')::date; v_accounts uuid[]; account_rows jsonb; movements jsonb;journals jsonb;transit jsonb;stock jsonb;lots jsonb;diffs jsonb;
 sv numeric;tv numeric;gv numeric;result jsonb;begin
 perform inventory.require_valuation_report_scope(t,e,b);
 if d is null or d>(statement_timestamp() at time zone 'UTC')::date or jsonb_typeof(p->'account_ids') is distinct from 'array'
  or jsonb_array_length(p->'account_ids') not between 1 and 50 then raise exception using errcode='22023',message='VALUATION_INPUT_INVALID';end if;
 select array_agg(x::uuid order by x) into v_accounts from jsonb_array_elements_text(p->'account_ids') x;
 if (select count(distinct x) from unnest(v_accounts)x)<>cardinality(v_accounts) then raise exception using errcode='22023',message='VALUATION_ACCOUNT_DUPLICATE';end if;
 select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name) order by id) into account_rows from finance.accounts
  where tenant_id=t and legal_entity_id=e and account_type='asset' and id=any(v_accounts);
 if coalesce(jsonb_array_length(account_rows),0)<>cardinality(v_accounts) then raise exception using errcode='22023',message='VALUATION_ACCOUNT_INVALID';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into movements from (
  select l.id,m.command_id,case when m.source_type like 'transfer.%' then 'transfer:'||m.source_id else 'command:'||m.command_id end evidence_key,
   m.source_type,m.source_id,l.source_line_id,l.stock_movement_id,l.warehouse_id,w.name warehouse_name,l.product_id,pr.name product_name,pr.sku,l.lot_id,lot.code lot_code,
   l.serial_ids,l.posting_date,l.base_quantity::text quantity,l.base_value::text value
  from inventory.stock_movement_lines l join inventory.stock_movements m on m.id=l.stock_movement_id
  join core.warehouses w on w.id=l.warehouse_id join inventory.products pr on pr.id=l.product_id left join inventory.lots lot on lot.id=l.lot_id
  where l.tenant_id=t and l.legal_entity_id=e and l.posting_date<=d order by l.id limit 10001)q;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,j.command_id,'command:'||j.command_id evidence_key,j.id journal_id,j.document_number,j.source_type,j.source_id,l.source_line_id,l.account_id,a.code account_code,
   l.posting_date,(l.base_debit-l.base_credit)::text value
  from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id join finance.accounts a on a.id=l.account_id
  where l.tenant_id=t and l.legal_entity_id=e and l.account_id=any(v_accounts) and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into transit from (
  select l.id,'transfer:'||tr.id evidence_key,tr.id transfer_id,tr.reference,tr.source_warehouse_id,tr.destination_warehouse_id,
   sw.name source_warehouse_name,dw.name destination_warehouse_name,l.product_id,pr.name product_name,l.lot_id,l.serial_ids,
   l.base_quantity::text quantity,l.carrying_value::text value
  from inventory.transfers tr join inventory.transfer_lines l on l.transfer_id=tr.id join inventory.products pr on pr.id=l.product_id
   join core.warehouses sw on sw.id=tr.source_warehouse_id join core.warehouses dw on dw.id=tr.destination_warehouse_id
  where tr.tenant_id=t and tr.legal_entity_id=e
   and exists(select 1 from inventory.transfer_events te where te.transfer_id=tr.id and te.operation='dispatch' and te.posting_date<=d)
   and not exists(select 1 from inventory.transfer_events te where te.transfer_id=tr.id and te.operation in('receive','reverse') and te.posting_date<=d)
  order by l.id limit 10001)q;
 if greatest(jsonb_array_length(movements),jsonb_array_length(journals),jsonb_array_length(transit))>10000 then raise exception using errcode='54000',message='VALUATION_INPUT_LIMIT';end if;
 with totals as (select x->>'warehouse_id' warehouse_id,x->>'warehouse_name' warehouse_name,x->>'product_id' product_id,x->>'product_name' product_name,x->>'sku' sku,
  sum((x->>'quantity')::numeric) q,sum((x->>'value')::numeric) v from jsonb_array_elements(movements)x group by 1,2,3,4,5)
 select coalesce(jsonb_agg(jsonb_build_object('id',warehouse_id||':'||product_id,'warehouse_id',warehouse_id,'warehouse_name',warehouse_name,'product_id',product_id,
  'product_name',product_name,'sku',sku,'quantity',q::text,'value',v::text,'average_cost',case when q<>0 then round(v/q,12)::text end,
  'exception',case when q<0 then 'NEGATIVE_QUANTITY' when q=0 and v<>0 then 'VALUE_WITHOUT_QUANTITY' end) order by warehouse_id,product_id),'[]') into stock from totals;
 if jsonb_array_length(stock)>2000 then raise exception using errcode='54000',message='VALUATION_ROW_LIMIT';end if;
 with quantities as (select x->>'warehouse_id' w,x->>'product_id' pr,x->>'lot_id' lot,x->>'lot_code' code,sum((x->>'quantity')::numeric) q
  from jsonb_array_elements(movements)x group by 1,2,3,4), shares as (
  select q.*,s->>'warehouse_name' warehouse_name,s->>'product_name' product_name,(s->>'quantity')::numeric total_q,(s->>'value')::numeric total_v,
   sum(q.q) over(partition by w,pr order by lot nulls first rows unbounded preceding) running_q
  from quantities q join jsonb_array_elements(stock)s on s->>'warehouse_id'=w and s->>'product_id'=pr where q.q<>0)
 select coalesce(jsonb_agg(jsonb_build_object('id',w||':'||pr||':'||coalesce(lot,'untracked'),'warehouse_name',warehouse_name,'product_name',product_name,
  'lot_id',lot,'lot_code',code,'quantity',q::text,'value',case when total_q<>0 then (round(total_v*running_q/total_q,6)-round(total_v*(running_q-q)/total_q,6))::text end)
  order by w,pr,lot nulls first),'[]') into lots from shares;
 with entries as (
  select x->>'evidence_key' k,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(movements)x
  union all select x->>'evidence_key',(x->>'value')::numeric,0 from jsonb_array_elements(transit)x
  union all select x->>'evidence_key',0,(x->>'value')::numeric from jsonb_array_elements(journals)x), totals as(select k,sum(v)v,sum(g)g from entries group by k)
 select coalesce(jsonb_agg(jsonb_build_object('id',k,'evidence_key',k,'inventory_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by k),'[]') into diffs from totals where v<>g;
 select coalesce(sum((x->>'value')::numeric),0) into sv from jsonb_array_elements(stock)x;
 select coalesce(sum((x->>'value')::numeric),0) into tv from jsonb_array_elements(transit)x;
 select coalesce(sum((x->>'value')::numeric),0) into gv from jsonb_array_elements(journals)x;
 result:=jsonb_build_object('summary',jsonb_build_object('id',p->>'id','version',1,'status','generated','as_of',d,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'entity_name',(select name from core.legal_entities where id=e),'currency_code',(select currency_code from core.legal_entities where id=e),'generated_at',statement_timestamp(),
  'accounts',account_rows,'warehouse_value',sv::text,'transit_value',tv::text,'inventory_value',(sv+tv)::text,'gl_value',gv::text,'difference',(sv+tv-gv)::text,
  'stock_count',jsonb_array_length(stock),'difference_count',jsonb_array_length(diffs)),
  'stock',stock,'lots',lots,'transit',transit,'differences',diffs,'movements',movements,'journals',journals);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='VALUATION_EVIDENCE_LIMIT';end if;
 return result;
end $$;
revoke all on function inventory.build_valuation_report(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create function api.generate_inventory_valuation_report(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$declare h text;r jsonb;data jsonb;summary jsonb;id uuid:=(p_payload->>'id')::uuid;req uuid:=gen_random_uuid();begin
 perform inventory.require_valuation_report_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if id is null or p_client_timestamp is null then raise exception using errcode='22023',message='VALUATION_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.valuation.report',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'inventory.valuation.report',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 data:=inventory.build_valuation_report(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);summary:=data->'summary';
 insert into inventory.valuation_reports values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(summary->>'as_of')::date,(summary->>'generated_at')::timestamptz,summary,data,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'inventory.valuation.report',p_command_id,'inventory_valuation_report',id,p_idempotency_key,h,null,summary,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','generated'),jsonb_build_array(jsonb_build_object('topic','inventory.valuation.report','payload',summary)),'[]',req,req);
end $$;
create function api.inventory_valuation_reports(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform inventory.require_valuation_report_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_resource='accounts' then
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select a.id,a.code,a.name,a.status from finance.accounts a
   where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id and a.account_type='asset' and(p_after is null or a.id>p_after) order by id limit 51)q;
 elsif p_resource='reports' then
  select coalesce(jsonb_agg(summary order by id),'[]') into rows from(select id,summary from inventory.valuation_reports
   where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and(p_after is null or id>p_after) order by id limit 51)q;
 else raise exception using errcode='22023',message='VALUATION_RESOURCE_INVALID';end if;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor);
end $$;
create function api.inventory_valuation_report_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,p_section text,p_after integer default 0,p_evidence_key text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare r inventory.valuation_reports%rowtype;rows jsonb;n integer;begin
 perform inventory.require_valuation_report_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_section is null or p_section not in('stock','lots','transit','differences','movements','journals') or p_after is null or p_after<0 or p_after>30000 then raise exception using errcode='22023',message='VALUATION_PAGE_INVALID';end if;
 select * into r from inventory.valuation_reports where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_id;
 if not found then raise exception using errcode='42501',message='VALUATION_REPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(value order by ord),'[]') into rows from(select value,ord from jsonb_array_elements(r.evidence->p_section) with ordinality x(value,ord)
  where p_evidence_key is null or value->>'evidence_key'=p_evidence_key order by ord offset p_after limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('summary',r.summary,'section',p_section,'evidence_key',p_evidence_key,'items',rows,'next_cursor',case when n>50 then (p_after+50)::text end);
end $$;
revoke all on function api.generate_inventory_valuation_report(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.inventory_valuation_reports(uuid,uuid,uuid,text,uuid),api.inventory_valuation_report_page(uuid,uuid,uuid,uuid,text,integer,text) from public,anon,authenticated;
grant execute on function api.generate_inventory_valuation_report(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.inventory_valuation_reports(uuid,uuid,uuid,text,uuid),api.inventory_valuation_report_page(uuid,uuid,uuid,uuid,text,integer,text) to authenticated;
notify pgrst,'reload schema';

-- Candidate only. Manual source aggregate; posting uses the existing journal engine.
create table finance.manual_journals (
 id uuid primary key,tenant_id uuid not null references core.tenants(id),legal_entity_id uuid not null,branch_id uuid not null,
 document_type text not null default 'manual_journal' check(document_type='manual_journal'),document_number text,document_date date not null,
 reason text not null,description text not null,currency_code text not null references core.currencies(code),
 grand_total numeric(20,6) not null check(grand_total>0),snapshot jsonb not null,reversal_of_id uuid,
 status text not null default 'draft' check(status in('draft','pending_approval','approved','rejected','cancelled','posted')),
 version bigint not null default 1,workflow_snapshot jsonb,submitted_by uuid references auth.users(id),
 prepared_by uuid not null references auth.users(id),posted_by uuid references auth.users(id),posted_at timestamptz,journal_entry_id uuid,
 request_id uuid not null,command_id uuid not null,correlation_id uuid not null,client_timestamp timestamptz not null,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,reversal_of_id) references finance.manual_journals(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),
 check((status='posted')=(posted_at is not null)),check(status<>'posted' or posted_by is not null)
);
create unique index manual_one_posted_reversal on finance.manual_journals(tenant_id,reversal_of_id) where status='posted';
create index manual_journals_scope on finance.manual_journals(tenant_id,legal_entity_id,branch_id,id);
alter table finance.manual_journals enable row level security;
alter table finance.manual_journals force row level security;
revoke all on finance.manual_journals from public,anon,authenticated;
create trigger manual_immutable before update or delete on finance.manual_journals for each row execute function sales.flow_protect_document();
create trigger manual_touch before update on finance.manual_journals for each row execute function core.touch_mutable_record();
do $$declare f record;begin
 for f in select c.conname,(select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(c.conkey) with ordinality k(num,n)
 join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.num) cols from pg_constraint c where c.conrelid='finance.manual_journals'::regclass and c.contype='f' loop
 execute format('create index %I on finance.manual_journals(%s)',f.conname||'_idx',f.cols);end loop;
end$$;

create function finance.manual_command_access(t uuid,e uuid,b uuid,p jsonb) returns void
language plpgsql security definer set search_path='' as $$declare d finance.manual_journals%rowtype;begin
 select * into d from finance.manual_journals where tenant_id=t and legal_entity_id=e and branch_id=b and id=coalesce((p->>'id')::uuid,(p->>'document_id')::uuid);
 if d.reversal_of_id is not null or p->>'reversal_of_id' is not null then perform core.require_permission(t,'finance.reversals.post',e,b);end if;
 if coalesce(jsonb_array_length(d.snapshot->'attachments'),0)>0 or (p->'attachment_ids' is not null and p->'attachment_ids'<>'[]'::jsonb) then
 perform core.require_permission(t,'core.files.view',e,b);end if;
end$$;
revoke all on function finance.manual_command_access(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create function finance.manual_document(p_kind text,t uuid,v_id uuid,p_lock boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$declare d finance.manual_journals%rowtype;begin
 if p_kind is distinct from 'manual_journal' then raise exception using errcode='22023',message='DOCUMENT_TYPE_INVALID';end if;
 if p_lock then select * into d from finance.manual_journals where tenant_id=t and id=v_id for update;
 else select * into d from finance.manual_journals where tenant_id=t and id=v_id;end if;
 if not found then return null;end if;
 return d.snapshot||(sales.flow_exact_json(to_jsonb(d))-'snapshot');
end$$;

create function finance.manual_normalize(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare d date:=(p->>'document_date')::date;c text:=p->>'currency_code';fx jsonb;rate numeric;x jsonb;a finance.accounts%rowtype;
 lines jsonb:='[]';attachments jsonb:='[]';deb numeric:=0;cred numeric:=0;prevdeb numeric:=0;prevcred numeric:=0;
 debit numeric;credit numeric;base numeric;line_id uuid;ids uuid[]:='{}';file_id uuid;f core.attachments%rowtype;
 original jsonb;rawlines jsonb;reversal uuid:=(p->>'reversal_of_id')::uuid;begin
 if d is null or d>(clock_timestamp() at time zone 'UTC')::date or length(coalesce(trim(p->>'reason'),'')) not between 3 and 1000
 or length(coalesce(trim(p->>'description'),'')) not between 3 and 1000 then raise exception using errcode='22023',message='JOURNAL_INPUT_INVALID';end if;
 perform 1 from core.legal_entities where tenant_id=t and id=e for share;
 rawlines:=p->'lines';
 if reversal is not null then
  perform core.require_permission(t,'finance.reversals.post',e,b);
  original:=finance.manual_document('manual_journal',t,reversal,true);
  if original is null or original->>'legal_entity_id'<>e::text or original->>'branch_id'<>b::text or original->>'status'<>'posted'
   or original->>'reversal_of_id' is not null then raise exception using errcode='55000',message='JOURNAL_REVERSAL_INVALID';end if;
  if d<(original->>'document_date')::date then raise exception using errcode='22023',message='REVERSAL_DATE_INVALID';end if;
  if exists(select 1 from finance.manual_journals where tenant_id=t and reversal_of_id=reversal and status='posted') then
   raise exception using errcode='55000',message='JOURNAL_ALREADY_REVERSED';end if;
  c:=original->>'currency_code';
  fx:=jsonb_build_object('base_currency_code',original->>'base_currency_code','exchange_rate',original->>'exchange_rate',
   'exchange_rate_id',original->'exchange_rate_id','rate_date',original->'rate_date');
  if fx->>'base_currency_code' is distinct from (select currency_code from core.legal_entities where tenant_id=t and id=e) then
   raise exception using errcode='55000',message='JOURNAL_REAPPROVAL_REQUIRED';end if;
  select jsonb_agg(z.item||jsonb_build_object('debit',z.item->'credit','credit',z.item->'debit','base_amount',(-(z.item->>'base_amount')::numeric)::text)
   order by ord) into rawlines from jsonb_array_elements(original->'lines') with ordinality z(item,ord);
 else
  perform 1 from finance.exchange_rates where tenant_id=t and legal_entity_id=e and id=(p->>'exchange_rate_id')::uuid for share;
  fx:=finance.flow_rate(t,e,c,d,(p->>'exchange_rate_id')::uuid);
 end if;
 rate:=(fx->>'exchange_rate')::numeric;
 if jsonb_typeof(rawlines) is distinct from 'array' or jsonb_array_length(rawlines) not between 2 and 200 then
  raise exception using errcode='22023',message='JOURNAL_LINES_INVALID';end if;
 for x in select value from jsonb_array_elements(rawlines) loop
  line_id:=(x->>'line_id')::uuid;
  if line_id is null or line_id=any(ids) or length(coalesce(x->>'description',''))>500 or length(coalesce(x->>'cost_center',''))>100
   or length(coalesce(x->>'project',''))>100 then raise exception using errcode='22023',message='JOURNAL_LINE_INVALID';end if;
  ids:=array_append(ids,line_id);
  debit:=sales.wave3_decimal_string(x->'debit','debit',6,true,0,null)::numeric;
  credit:=sales.wave3_decimal_string(x->'credit','credit',6,true,0,null)::numeric;
  if (debit>0)=(credit>0) then raise exception using errcode='22023',message='JOURNAL_LINE_SIDES_INVALID';end if;
  select * into a from finance.accounts where tenant_id=t and legal_entity_id=e and id=(x->>'account_id')::uuid and status='active' and is_posting
   and (currency_code is null or currency_code=c) for share;
  if not found then raise exception using errcode='55000',message='ACCOUNT_MAPPING_INVALID';end if;
  if exists(select 1 from finance.posting_mappings where tenant_id=t and legal_entity_id=e and account_id=a.id and purpose in('receivable_control','payable_control'))
   or exists(select 1 from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e and payable_account_id=a.id)
   or exists(select 1 from finance.journal_lines jl join finance.open_items oi on oi.journal_entry_id=jl.journal_entry_id and oi.tenant_id=jl.tenant_id
    where jl.tenant_id=t and jl.legal_entity_id=e and jl.account_id=a.id
    and ((oi.kind='AR' and a.account_type='asset' and jl.base_debit-jl.base_credit=oi.original_base_amount)
      or(oi.kind='AP' and a.account_type='liability' and jl.base_credit-jl.base_debit=oi.original_base_amount))) then
   raise exception using errcode='55000',message='SUBLEDGER_CONTROL_REQUIRES_SOURCE';end if;
  deb:=deb+debit;cred:=cred+credit;
  base:=case when debit>0 then round(deb*rate,6)-prevdeb else -(round(cred*rate,6)-prevcred) end;
  prevdeb:=round(deb*rate,6);prevcred:=round(cred*rate,6);
  if reversal is not null then base:=(x->>'base_amount')::numeric;end if;
  if base=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
  lines:=lines||jsonb_build_array(jsonb_build_object('line_id',line_id,'account_id',a.id,'account_code',a.code,'account_name',a.name,
   'debit',debit::text,'credit',credit::text,'amount',(debit-credit)::text,'base_amount',base::text,
   'description',coalesce(x->>'description',''),'cost_center',coalesce(x->>'cost_center',''),'project',coalesce(x->>'project','')));
 end loop;
 if deb<>cred or (select sum((z.item->>'base_amount')::numeric) from jsonb_array_elements(lines)z(item))<>0 then raise exception using errcode='23514',message='UNBALANCED_JOURNAL';end if;
 if jsonb_typeof(coalesce(p->'attachment_ids','[]')) is distinct from 'array' or jsonb_array_length(coalesce(p->'attachment_ids','[]'))>20 then
  raise exception using errcode='22023',message='JOURNAL_ATTACHMENTS_INVALID';end if;
 ids:='{}';
 for file_id in select value::uuid from jsonb_array_elements_text(coalesce(p->'attachment_ids','[]')) loop
  perform core.require_permission(t,'core.files.view',e,b);
  select * into f from core.attachments where tenant_id=t and id=file_id and upload_status='ready' and checksum_sha256 is not null
   and ((aggregate_type='legal_entity' and aggregate_id=e) or (aggregate_type='branch' and aggregate_id=b)) for share;
  if not found or file_id=any(ids) then raise exception using errcode='22023',message='JOURNAL_ATTACHMENT_INVALID';end if;
  ids:=array_append(ids,file_id);attachments:=attachments||jsonb_build_array(jsonb_build_object('id',f.id,'file_name',f.file_name,'checksum_sha256',f.checksum_sha256));
 end loop;
 return fx||jsonb_build_object('document_date',d,'reason',trim(p->>'reason'),'description',trim(p->>'description'),'currency_code',c,
  'lines',lines,'grand_total',deb::text,'base_total',prevdeb::text,'attachment_ids',to_jsonb(ids),'attachments',attachments,'reversal_of_id',reversal);
end$$;

create function finance.manual_revalidate(p_kind text,d jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare fresh jsonb;begin
 fresh:=finance.manual_normalize((d->>'tenant_id')::uuid,(d->>'legal_entity_id')::uuid,(d->>'branch_id')::uuid,d);
 if fresh-'reason'-'description'-'document_date' is distinct from (select snapshot-'reason'-'description'-'document_date' from finance.manual_journals where id=(d->>'id')::uuid) then
  raise exception using errcode='55000',message='JOURNAL_REAPPROVAL_REQUIRED';end if;
 return fresh;
end$$;

create function api.upsert_manual_journal(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$declare v_id uuid:=(p_payload->>'id')::uuid;req uuid:=gen_random_uuid();h text;r jsonb;old_doc jsonb;d jsonb;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.journals.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if v_id is null or p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null then raise exception using errcode='22023',message='JOURNAL_INPUT_INVALID';end if;
 perform finance.manual_command_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 h:=core.wave3_request_hash('finance.manual_journal.upsert',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.manual_journal.upsert',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':manual:'||v_id::text,0));
 old_doc:=finance.manual_document('manual_journal',p_tenant_id,v_id,true);
 if old_doc is not null then
  if old_doc->>'legal_entity_id'<>p_legal_entity_id::text or old_doc->>'branch_id'<>p_branch_id::text then raise exception using errcode='42501',message='DOCUMENT_SCOPE_INVALID';end if;
  perform core.wave3_assert_expected_version((old_doc->>'version')::bigint,p_expected_entity_version,old_doc);
  if old_doc->>'status'<>'draft' then raise exception using errcode='55000',message='DOCUMENT_NOT_EDITABLE';end if;
 else perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');end if;
 d:=finance.manual_normalize(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 if old_doc is null then
 insert into finance.manual_journals(id,tenant_id,legal_entity_id,branch_id,document_date,reason,description,currency_code,grand_total,snapshot,reversal_of_id,
 prepared_by,created_by,updated_by,request_id,command_id,correlation_id,client_timestamp)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,(d->>'document_date')::date,d->>'reason',d->>'description',d->>'currency_code',(d->>'grand_total')::numeric,d,
 (d->>'reversal_of_id')::uuid,auth.uid(),auth.uid(),auth.uid(),req,p_command_id,req,p_client_timestamp);
 else update finance.manual_journals set document_date=(d->>'document_date')::date,reason=d->>'reason',description=d->>'description',currency_code=d->>'currency_code',
 grand_total=(d->>'grand_total')::numeric,snapshot=d,reversal_of_id=(d->>'reversal_of_id')::uuid,prepared_by=auth.uid(),updated_by=auth.uid(),
 request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp where tenant_id=p_tenant_id and id=v_id;end if;
 return core.wave3_finish_command(p_tenant_id,'finance.manual_journal.upsert',p_command_id,'manual_journal',v_id,p_idempotency_key,h,old_doc,
 finance.manual_document('manual_journal',p_tenant_id,v_id),p_legal_entity_id,p_branch_id,'{}',null,
 jsonb_build_array(jsonb_build_object('topic','finance.manual_journal.upsert','payload',jsonb_build_object('id',v_id))),'[]',req,req);
end$$;

create function api.transition_manual_journal(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_kind text:='manual_journal';v_id uuid:=(p_payload->>'document_id')::uuid;
 v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';v_command text;
 v_doc jsonb;v_before jsonb;v_hash text;v_replay jsonb;v_to text;v_snapshot jsonb;
 v_workflow workflow.workflow_definitions%rowtype;v_request uuid:=gen_random_uuid();v_first integer;
 v_ar workflow.approval_requests%rowtype;v_step jsonb;v_number text;
begin
 v_command:='finance.'||v_kind||case when v_decision is null then '.transition' else '.decide' end;
 perform core.wave3_require_scope(p_tenant_id,case when v_decision is null then 'finance.journals.post' else 'workflow.approvals.decide' end,p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or (p_payload ? 'document_type' and p_payload->>'document_type' is distinct from 'manual_journal')
 or (v_decision is not null and v_action is not null) then raise exception using errcode='22023',message='DOCUMENT_PAYLOAD_INVALID';end if;
 perform finance.manual_command_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_replay:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
 v_doc:=finance.manual_document(v_kind,p_tenant_id,v_id,true);v_before:=v_doc;
 if v_doc is null or (v_doc->>'legal_entity_id')::uuid<>p_legal_entity_id or (v_doc->>'branch_id')::uuid<>p_branch_id then
 raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version((v_doc->>'version')::bigint,p_expected_entity_version,v_doc);
 if v_doc->>'status'='posted' then raise exception using errcode='55000',message='POSTED_DOCUMENT_IMMUTABLE';end if;
 v_snapshot:=v_doc->'workflow_snapshot';v_number:=v_doc->>'document_number';
 if v_decision is not null then
 if v_decision not in ('approved','rejected') or v_doc->>'status'<>'pending_approval' then raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
 select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type=v_kind and document_id=v_id and status='submitted' for update;
 if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
 if v_ar.submitted_by=auth.uid() or (v_doc->>'created_by')::uuid=auth.uid() or (v_doc->>'prepared_by')::uuid=auth.uid() then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
 if v_step is null or not exists(select 1 from core.memberships m join core.role_assignments ra on ra.tenant_id=m.tenant_id and ra.membership_id=m.id
 join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
 where m.tenant_id=p_tenant_id and m.user_id=auth.uid() and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
 and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
 and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
 if v_decision='rejected' and nullif(trim(p_payload->>'note'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
 perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
 insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
 approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
 values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
 auth.uid(),v_decision,p_payload->>'note',v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
 if v_decision='approved' then select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
 where (x->>'step_order')::integer>v_ar.current_step;end if;
 v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
 if v_first is null then update workflow.approval_requests set status=v_to,decision_by=auth.uid(),decision_note=p_payload->>'note',decided_at=clock_timestamp() where id=v_ar.id;
 else update workflow.approval_requests set current_step=v_first where id=v_ar.id;end if;
 elsif v_action='submit' then
 if v_doc->>'status'<>'draft' then raise exception using errcode='55000',message='DOCUMENT_NOT_EDITABLE';end if;
 perform finance.manual_revalidate(v_kind,v_doc);
 select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id and document_type=v_kind and status='active'
 and (legal_entity_id is null or legal_entity_id=p_legal_entity_id) order by (legal_entity_id is not null) desc limit 1;
 if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
 select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
 'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
 from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
 and (s.currency_code is null or s.currency_code=v_doc->>'currency_code')
 and (s.minimum_amount is null or (v_doc->>'grand_total')::numeric>=s.minimum_amount)
 and (s.maximum_amount is null or (v_doc->>'grand_total')::numeric<=s.maximum_amount);
 if v_workflow.lifecycle->'requires_approval'='false'::jsonb then
 raise exception using errcode='55000',message='JOURNAL_APPROVAL_REQUIRED';end if;
 select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
 if v_first is null then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
 v_to:='pending_approval';
 perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
 v_number:=coalesce(v_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,(v_doc->>'document_date')::date,auth.uid()));
 if v_first is not null then insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
 submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,v_id,'submitted',auth.uid(),v_workflow.id,v_workflow.revision,v_first,
 (v_doc->>'grand_total')::numeric,v_doc->>'currency_code',p_command_id,v_request,v_request);end if;
 elsif v_action in ('recall','cancel') then
 if nullif(trim(p_payload->>'reason'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
 if v_snapshot is null and v_doc->>'status'='draft' then
 select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
 where tenant_id=p_tenant_id and document_type=v_kind and status='active'
 and (legal_entity_id is null or legal_entity_id=p_legal_entity_id) order by (legal_entity_id is not null) desc limit 1;
 end if;
 v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
 perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc->>'status',v_to);
 update workflow.approval_requests set status='cancelled',decision_by=auth.uid(),decision_note=p_payload->>'reason',decided_at=clock_timestamp()
 where tenant_id=p_tenant_id and document_type=v_kind and document_id=v_id and status='submitted';
 if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='DOCUMENT_ACTION_INVALID';end if;
 execute format('update finance.%I set status=$1,workflow_snapshot=$2,document_number=$3,submitted_by=case when $4=''submit'' then $5 else submitted_by end,updated_by=$5,request_id=$6,command_id=$7,correlation_id=$6,client_timestamp=$8 where tenant_id=$9 and id=$10','manual_journals')
 using v_to,v_snapshot,v_number,v_action,auth.uid(),v_request,p_command_id,p_client_timestamp,p_tenant_id,v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,v_kind,v_id,p_idempotency_key,v_hash,v_before,
 finance.manual_document(v_kind,p_tenant_id,v_id),p_legal_entity_id,p_branch_id,coalesce(p_payload->'source_context','{}'),
 case when v_doc->>'status'=v_to then null else
 jsonb_build_object('from_status',v_doc->>'status','to_status',v_to,'reason',coalesce(p_payload->>'reason',p_payload->>'note')) end,
 jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
end $$;



create function api.post_manual_journal(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$declare v_id uuid:=(p_payload->>'document_id')::uuid;d jsonb;h text;r jsonb;req uuid:=gen_random_uuid();j uuid;jlines jsonb;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.journals.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if v_id is null or p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null then raise exception using errcode='22023',message='JOURNAL_INPUT_INVALID';end if;
 perform finance.manual_command_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 h:=core.wave3_request_hash('finance.manual_journal.post',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.manual_journal.post',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 d:=finance.manual_document('manual_journal',p_tenant_id,v_id,true);
 if d is null or d->>'legal_entity_id'<>p_legal_entity_id::text or d->>'branch_id'<>p_branch_id::text then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version((d->>'version')::bigint,p_expected_entity_version,d);
 if d->>'status'<>'approved' then raise exception using errcode='55000',message='JOURNAL_APPROVAL_REQUIRED';end if;
 if auth.uid() in ((d->>'prepared_by')::uuid,(d->>'submitted_by')::uuid) then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 perform sales.flow_assert_transition(d#>'{workflow_snapshot,lifecycle}','approved','posted');
 perform finance.manual_revalidate('manual_journal',d);
 select jsonb_agg(finance.flow_jline((x->>'account_id')::uuid,(x->>'amount')::numeric,(x->>'base_amount')::numeric,(x->>'line_id')::uuid) order by n)
 into jlines from jsonb_array_elements(d->'lines') with ordinality z(x,n);
 j:=finance.flow_post_journal(d,jlines,'manual_journal',v_id,req,p_command_id);
 update finance.manual_journals set status='posted',journal_entry_id=j,posted_at=clock_timestamp(),posted_by=auth.uid(),updated_by=auth.uid(),
 request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp where tenant_id=p_tenant_id and id=v_id;
 return core.wave3_finish_command(p_tenant_id,'finance.manual_journal.post',p_command_id,'manual_journal',v_id,p_idempotency_key,h,d,
 finance.manual_document('manual_journal',p_tenant_id,v_id),p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','approved','to_status','posted','reason',d->>'reason'),
 jsonb_build_array(jsonb_build_object('topic','finance.manual_journal.post','payload',jsonb_build_object('id',v_id,'journal_entry_id',j))),'[]',req,req);
end$$;

create function api.manual_journal_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare d jsonb;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 d:=finance.manual_document('manual_journal',p_tenant_id,p_id);
 if d is null or d->>'legal_entity_id'<>p_legal_entity_id::text or d->>'branch_id'<>p_branch_id::text then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 if jsonb_array_length(d->'attachments')>0 then perform core.require_permission(p_tenant_id,'core.files.view',p_legal_entity_id,p_branch_id);end if;
 return d||jsonb_build_object('reversed_by_id',(select id from finance.manual_journals where tenant_id=p_tenant_id and reversal_of_id=p_id and status='posted'),
 'ledger_lines',coalesce((select jsonb_agg(sales.flow_exact_json(to_jsonb(l)) order by line_number) from finance.journal_lines l
 where l.tenant_id=p_tenant_id and l.journal_entry_id=(d->>'journal_entry_id')::uuid),'[]'::jsonb));
end$$;

create function api.manual_journal_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql stable security definer set search_path='' as $$declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or coalesce(length(p_search),0)>100 then raise exception using errcode='22023',message='JOURNAL_OPTIONS_INVALID';end if;
 if p_resource='reports' then
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select id,document_number,document_date,description,status,version,currency_code,grand_total::text,reversal_of_id
 from finance.manual_journals where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and(p_after is null or id>p_after)
 and(description ilike '%'||p_search||'%' or document_number ilike '%'||p_search||'%') order by id limit 51)q;
 elsif p_resource='accounts' then
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select id,code,name,account_type,currency_code from finance.accounts
 where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and is_posting and(p_after is null or id>p_after)
 and(name ilike '%'||p_search||'%' or code ilike '%'||p_search||'%') order by id limit 51)q;
 elsif p_resource='rates' then
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select r.id,r.source_currency_code,r.target_currency_code,r.effective_date,r.rate::text
 from finance.exchange_rates r join core.legal_entities e on e.tenant_id=r.tenant_id and e.id=r.legal_entity_id
 where r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and r.target_currency_code=e.currency_code and r.status='active' and(p_after is null or r.id>p_after) order by r.id limit 51)q;
 elsif p_resource='attachments' then
 perform core.require_permission(p_tenant_id,'core.files.view',p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select id,file_name,checksum_sha256 from core.attachments where tenant_id=p_tenant_id
 and upload_status='ready' and checksum_sha256 is not null and((aggregate_type='legal_entity' and aggregate_id=p_legal_entity_id)or(aggregate_type='branch' and aggregate_id=p_branch_id))
 and(p_after is null or id>p_after) and file_name ilike '%'||p_search||'%' order by id limit 51)q;
 else raise exception using errcode='22023',message='JOURNAL_OPTIONS_INVALID';end if;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',next_id,'base_currency_code',(select currency_code from core.legal_entities where tenant_id=p_tenant_id and id=p_legal_entity_id));
end$$;
revoke all on function finance.manual_document(text,uuid,uuid,boolean),finance.manual_normalize(uuid,uuid,uuid,jsonb),finance.manual_revalidate(text,jsonb) from public,anon,authenticated;
do $$declare f text;begin
 foreach f in array array['upsert_manual_journal','transition_manual_journal','post_manual_journal'] loop
 execute format('revoke all on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated',f);
 execute format('grant execute on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated',f);end loop;
end$$;
revoke all on function api.manual_journal_detail(uuid,uuid,uuid,uuid),api.manual_journal_options(uuid,uuid,uuid,text,uuid,text) from public,anon,authenticated;
grant execute on function api.manual_journal_detail(uuid,uuid,uuid,uuid),api.manual_journal_options(uuid,uuid,uuid,text,uuid,text) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED AC-317 candidate. Existing ledger, journal and residual engines only.
insert into core.permissions(code,module,description,privileged) values
 ('finance.controls.reconcile','finance','Generate and read branch AR/AP control evidence.',true),
 ('finance.receipts.reverse','finance','Reverse customer allocations with reason and history.',true)
on conflict(code) do nothing;

-- A control is recovered from the immutable source journal, never today's mapping.
-- Ambiguous/unsupported historical sources fail explicitly rather than invent a basis.
create function finance.open_item_control(t uuid,i uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare ids uuid[];begin
 select array_agg(q.account_id) into ids from (
  select l.account_id from finance.open_items o join finance.journal_lines l on l.tenant_id=o.tenant_id and l.journal_entry_id=o.journal_entry_id
  join finance.accounts a on a.id=l.account_id and a.tenant_id=o.tenant_id
  where o.tenant_id=t and o.id=i and a.account_type=case o.kind when 'AR' then 'asset' else 'liability' end
  group by l.account_id,o.original_base_amount,o.kind
  having sum(l.base_debit-l.base_credit)=case o.kind when 'AR' then o.original_base_amount else -o.original_base_amount end
 )q;
 if coalesce(cardinality(ids),0)<>1 then raise exception using errcode='55000',message='OPEN_ITEM_CONTROL_BASIS_REQUIRED';end if;
 return ids[1];end $$;
revoke all on function finance.open_item_control(uuid,uuid) from public,anon,authenticated;

create or replace function finance.flow_allocate(p_source uuid,p_target uuid,p_tenant uuid,p_entity uuid,p_branch uuid,
 p_payload jsonb,p_date date,p_request uuid,p_command uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_s finance.open_items%rowtype;v_t finance.open_items%rowtype;v_sr jsonb;v_tr jsonb;
 v_source numeric;v_target numeric;v_write numeric;v_discount numeric;v_sb numeric;v_tb numeric;v_ab numeric;
 v_fx numeric;v_rate finance.exchange_rates%rowtype;v_scale integer;v_conversion numeric:=1;v_id uuid:=gen_random_uuid();
 v_journal uuid;v_lines jsonb:='[]';v_doc jsonb;v_control uuid;v_target_control uuid;v_prior numeric;v_adjust numeric;
begin
 perform 1 from finance.open_items where tenant_id=p_tenant and id in (p_source,p_target) order by id for update;
 select * into v_s from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_source;
 select * into v_t from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_target;
 if v_s.id is null or v_t.id is null or v_s.party_id<>v_t.party_id or v_s.original_amount>=0 or v_t.original_amount<=0
 or v_s.kind<>'AR' or v_t.kind<>'AR' or v_s.base_currency_code<>v_t.base_currency_code
 or p_date<greatest(v_s.posting_date,v_t.posting_date) then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and
 (source_open_item_id in (p_source,p_target) or target_open_item_id in (p_source,p_target)) and posting_date>p_date) then
 raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 if exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id
 where r.tenant_id=p_tenant and (a.source_open_item_id in(p_source,p_target) or a.target_open_item_id in(p_source,p_target)) and r.posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 select rounding_scale into v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_source:=sales.wave3_decimal_string(p_payload->'source_amount','Source amount',6,true,0,null)::numeric;
 v_target:=sales.wave3_decimal_string(p_payload->'transaction_amount','Target amount',6,true,0,null)::numeric;
 v_write:=sales.wave3_decimal_string(coalesce(p_payload->'write_off','"0"'),'Write-off',6,true,0,null)::numeric;
 v_discount:=sales.wave3_decimal_string(coalesce(p_payload->'discount_amount','"0"'),'Discount',6,true,0,null)::numeric;
 if v_source<=0 or v_target<=0 or v_source<>round(v_source,v_scale) or v_target<>round(v_target,v_scale)
 or v_write<>round(v_write,v_scale) or v_discount<>round(v_discount,v_scale) then raise exception using errcode='22023',message='ALLOCATION_AMOUNT_INVALID';end if;
 if v_write+v_discount>0 then
 perform core.wave3_require_scope(p_tenant,'finance.receipts.adjust',p_entity,p_branch);
 if nullif(trim(p_payload->>'reason'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;end if;
 if v_s.currency_code<>v_t.currency_code then
 select * into v_rate from finance.exchange_rates where tenant_id=p_tenant and legal_entity_id=p_entity and status='active'
 and id=(p_payload->>'exchange_rate_id')::uuid and source_currency_code=v_s.currency_code and target_currency_code=v_t.currency_code and effective_date<=p_date;
 if not found then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_REQUIRED';end if;v_conversion:=v_rate.rate;
 elsif p_payload->>'exchange_rate_id' is not null then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_INVALID';end if;
 if round(v_source*v_conversion,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_CURRENCY_MISMATCH';end if;
 v_sr:=finance.flow_residual(p_tenant,p_source);v_tr:=finance.flow_residual(p_tenant,p_target);
 if v_source>-(v_sr->>'amount')::numeric or v_target+v_write+v_discount>(v_tr->>'amount')::numeric then
 raise exception using errcode='22023',message='ALLOCATION_EXCEEDED';end if;
 v_sb:=round(-(v_sr->>'base_amount')::numeric*v_source/(-(v_sr->>'amount')::numeric),v_scale);
 v_tb:=round((v_tr->>'base_amount')::numeric*v_target/(v_tr->>'amount')::numeric,v_scale);
 v_ab:=round((v_tr->>'base_amount')::numeric*(v_target+v_write+v_discount)/(v_tr->>'amount')::numeric,v_scale)-v_tb;
 if v_sb<=0 or v_tb<=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
 v_fx:=v_sb-v_tb;
 v_doc:=jsonb_build_object('tenant_id',p_tenant,'legal_entity_id',p_entity,'branch_id',p_branch,'document_date',p_date,
 'customer_id',v_s.party_id,'currency_code',v_s.base_currency_code,'base_currency_code',v_s.base_currency_code,'exchange_rate','1');
 v_control:=finance.open_item_control(p_tenant,p_source);v_target_control:=finance.open_item_control(p_tenant,p_target);
 if v_fx<>0 or v_ab<>0 or v_control<>v_target_control then
 if v_control<>v_target_control then
 v_lines:=jsonb_build_array(finance.flow_jline(v_control,v_sb,v_sb),finance.flow_jline(v_target_control,-v_sb,-v_sb));end if;
 v_control:=v_target_control;
 if v_fx<>0 then
 v_lines:=v_lines||jsonb_build_array(finance.flow_jline(v_control,v_fx,v_fx),finance.flow_jline(
 finance.flow_mapping(p_tenant,p_entity,case when v_fx>0 then 'exchange_gain' else 'exchange_loss' end,v_s.base_currency_code),-v_fx,-v_fx));end if;
 if v_ab>0 then
 v_lines:=v_lines||jsonb_build_array(finance.flow_jline(v_control,-v_ab,-v_ab));
 v_adjust:=round(v_ab*v_write/(v_write+v_discount),v_scale);
 if v_adjust>0 then v_lines:=v_lines||jsonb_build_array(finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,'write_off',v_s.base_currency_code),v_adjust,v_adjust));end if;
 if v_ab-v_adjust>0 then v_lines:=v_lines||jsonb_build_array(finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,'settlement_discount',v_s.base_currency_code),v_ab-v_adjust,v_ab-v_adjust));end if;
 end if;
 v_journal:=finance.flow_post_journal(v_doc,v_lines,'customer_allocation',v_id,p_request,p_command);end if;
 insert into finance.open_item_allocations(id,tenant_id,legal_entity_id,branch_id,source_open_item_id,target_open_item_id,
 source_amount,transaction_amount,source_base_amount,target_base_amount,exchange_difference,write_off,discount_amount,
 adjustment_base_amount,exchange_rate_id,conversion_rate,posting_date,reason,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_id,p_tenant,p_entity,p_branch,p_source,p_target,v_source,v_target,v_sb,v_tb,v_fx,v_write,v_discount,v_ab,v_rate.id,v_conversion,
 p_date,p_payload->>'reason',v_journal,p_request,p_command,p_request,auth.uid());
 return jsonb_build_object('allocation_id',v_id,'journal_entry_id',v_journal,'source_open_item_id',p_source,'target_open_item_id',p_target,
 'source_amount',v_source::text,'transaction_amount',v_target::text,'exchange_difference',v_fx::text,
 'source_residual',finance.flow_residual(p_tenant,p_source),'target_residual',finance.flow_residual(p_tenant,p_target));end $$;

create or replace function finance.allocate_payable(p_source uuid,p_target uuid,p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_date date,p_request uuid,p_command uuid,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_s finance.open_items%rowtype;v_t finance.open_items%rowtype;v_sr jsonb;v_tr jsonb;v_rate finance.exchange_rates%rowtype;v_scale integer;
 v_source numeric;v_target numeric;v_sb numeric;v_tb numeric;v_prior numeric;v_fx numeric;v_conversion numeric:=1;v_id uuid:=gen_random_uuid();v_journal uuid;v_control uuid;v_target_control uuid;v_lines jsonb;v_doc jsonb;
begin
 perform 1 from finance.open_items where tenant_id=p_tenant and id in(p_source,p_target) order by id for update;
 select * into v_s from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_source;
 select * into v_t from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_target;
 if v_s.id is null or v_t.id is null or v_s.party_id<>v_t.party_id or v_s.kind<>'AP' or v_t.kind<>'AP' or v_s.original_amount>=0 or v_t.original_amount<=0
  or v_s.base_currency_code<>v_t.base_currency_code or p_date<greatest(v_s.posting_date,v_t.posting_date) then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id in(p_source,p_target) and active and proposal_id is distinct from p_proposal)
 then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id in(p_source,p_target) or target_open_item_id in(p_source,p_target)) and posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 if exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id where r.tenant_id=p_tenant
  and (a.source_open_item_id in(p_source,p_target) or a.target_open_item_id in(p_source,p_target)) and r.posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 select rounding_scale into v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_source:=sales.wave3_decimal_string(p_payload->'source_amount','source_amount',6,true,0,null);v_target:=sales.wave3_decimal_string(p_payload->'transaction_amount','transaction_amount',6,true,0,null);
 if v_source<=0 or v_target<=0 or round(v_source,v_scale)<>v_source or round(v_target,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_AMOUNT_INVALID';end if;
 if v_s.currency_code<>v_t.currency_code then
  select * into v_rate from finance.exchange_rates where id=(p_payload->>'exchange_rate_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
   and source_currency_code=v_s.currency_code and target_currency_code=v_t.currency_code and effective_date<=p_date and status='active';
  if not found then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_REQUIRED';end if;v_conversion:=v_rate.rate;
 elsif p_payload->>'exchange_rate_id' is not null then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_INVALID';end if;
 if round(v_source*v_conversion,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_CURRENCY_MISMATCH';end if;
 v_sr:=finance.flow_residual(p_tenant,p_source);v_tr:=finance.flow_residual(p_tenant,p_target);
 if v_source>-(v_sr->>'amount')::numeric or v_target>(v_tr->>'amount')::numeric then raise exception using errcode='22023',message='ALLOCATION_EXCEEDED';end if;
 -- Allocate from remaining carrying value: reversal can restore a different cent distribution.
 v_sb:=round(-(v_sr->>'base_amount')::numeric*v_source/(-(v_sr->>'amount')::numeric),v_scale);
 v_tb:=round((v_tr->>'base_amount')::numeric*v_target/(v_tr->>'amount')::numeric,v_scale);
 if v_sb<=0 or v_tb<=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
 v_fx:=v_sb-v_tb;
 v_control:=finance.open_item_control(p_tenant,p_source);v_target_control:=finance.open_item_control(p_tenant,p_target);
 if v_fx<>0 or v_control<>v_target_control then
 v_doc:=jsonb_build_object('tenant_id',p_tenant,'legal_entity_id',p_entity,'branch_id',p_branch,'document_date',p_date,'customer_id',v_s.party_id,
 'currency_code',v_s.base_currency_code,'base_currency_code',v_s.base_currency_code,'exchange_rate','1');
 v_lines:=jsonb_build_array(finance.flow_jline(v_control,-v_sb,-v_sb),finance.flow_jline(v_target_control,v_tb,v_tb));
 if v_fx<>0 then v_lines:=v_lines||jsonb_build_array(finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,
 case when v_fx>0 then 'exchange_loss' else 'exchange_gain' end,v_s.base_currency_code),v_fx,v_fx));end if;
 v_journal:=finance.flow_post_journal(v_doc,v_lines,'supplier_allocation',v_id,p_request,p_command);
 end if;
 insert into finance.open_item_allocations(id,tenant_id,legal_entity_id,branch_id,source_open_item_id,target_open_item_id,source_amount,transaction_amount,
  source_base_amount,target_base_amount,exchange_difference,exchange_rate_id,conversion_rate,posting_date,reason,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_id,p_tenant,p_entity,p_branch,p_source,p_target,v_source,v_target,v_sb,v_tb,v_fx,v_rate.id,v_conversion,p_date,p_payload->>'reason',v_journal,p_request,p_command,p_request,auth.uid());
 return jsonb_build_object('allocation_id',v_id,'source_open_item_id',p_source,'target_open_item_id',p_target,'source_amount',v_source::text,'transaction_amount',v_target::text,
  'exchange_difference',v_fx::text,'journal_entry_id',v_journal,'source_residual',finance.flow_residual(p_tenant,p_source),'target_residual',finance.flow_residual(p_tenant,p_target));
end $$;

create or replace function api.reverse_customer_allocation(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='finance.customer_allocation.reverse';v_hash text;v_result jsonb;v_a finance.open_item_allocations%rowtype;v_source finance.open_items%rowtype;
 v_id uuid:=gen_random_uuid();v_request uuid:=gen_random_uuid();v_date date:=(p_payload->>'posting_date')::date;v_reason text:=trim(p_payload->>'reason');
 v_journal uuid;v_original finance.journal_entries%rowtype;v_lines jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.receipts.reverse',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000
  or p_expected_entity_version is not null then raise exception using errcode='22023',message='ALLOCATION_REVERSAL_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_a from finance.open_item_allocations where id=(p_payload->>'allocation_id')::uuid and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id;
 if not found then raise exception using errcode='P0002',message='ALLOCATION_NOT_FOUND';end if;
 perform 1 from crm.parties where tenant_id=p_tenant_id and id=(select party_id from finance.open_items where id=v_a.source_open_item_id) for update;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 perform 1 from finance.open_items where tenant_id=p_tenant_id and id in(v_a.source_open_item_id,v_a.target_open_item_id) order by id for update;
 select * into v_source from finance.open_items where id=v_a.source_open_item_id and tenant_id=p_tenant_id;
 if v_source.kind<>'AR' then raise exception using errcode='22023',message='AR_ALLOCATION_REQUIRED';end if;
 if exists(select 1 from finance.allocation_reversals where allocation_id=v_a.id) then raise exception using errcode='55000',message='ALLOCATION_ALREADY_REVERSED';end if;
 if v_date<v_a.posting_date or v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='ALLOCATION_REVERSAL_DATE_INVALID';end if;
 if exists(select 1 from finance.open_item_allocations a where a.tenant_id=p_tenant_id and (a.source_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)
  or a.target_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)) and a.posting_date>v_date)
  or exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id where r.tenant_id=p_tenant_id
   and (a.source_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id) or a.target_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)) and r.posting_date>v_date)
  then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 if v_a.journal_entry_id is not null then
  select * into v_original from finance.journal_entries where id=v_a.journal_entry_id and tenant_id=p_tenant_id;
  select jsonb_agg(finance.flow_jline(account_id,transaction_credit-transaction_debit,base_credit-base_debit) order by line_number) into v_lines
   from finance.journal_lines where journal_entry_id=v_original.id and tenant_id=p_tenant_id;
  v_journal:=finance.flow_post_journal(to_jsonb(v_original)||jsonb_build_object('document_date',v_date,'customer_id',v_source.party_id),v_lines,
   'customer_allocation_reversal',v_id,v_request,p_command_id);
 end if;
 insert into finance.allocation_reversals(id,tenant_id,legal_entity_id,branch_id,allocation_id,posting_date,reason,journal_entry_id,source_snapshot,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_a.id,v_date,v_reason,v_journal,sales.flow_exact_json(to_jsonb(v_a)),v_request,p_command_id,auth.uid());
 perform finance.flow_refresh_credit(jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'customer_id',v_source.party_id));
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'customer_allocation_reversal',v_id,p_idempotency_key,v_hash,sales.flow_exact_json(to_jsonb(v_a)),
  jsonb_build_object('id',v_id,'allocation_id',v_a.id,'journal_entry_id',v_journal,'posting_date',v_date,'reason',v_reason,
   'source_residual',finance.flow_residual(p_tenant_id,v_a.source_open_item_id),'target_residual',finance.flow_residual(p_tenant_id,v_a.target_open_item_id)),
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','allocated','to_status','reversed','reason',v_reason),
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('allocation_id',v_a.id))),'[]',v_request,v_request);
end $$;
revoke all on function api.reverse_customer_allocation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.reverse_customer_allocation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
-- Kind-aware history RLS prevents payable-only readers from seeing AR corrections.
drop policy ap_read on finance.allocation_reversals;
create policy scoped_read on finance.allocation_reversals for select to authenticated using(exists(
 select 1 from finance.open_item_allocations a join finance.open_items o on o.id=a.source_open_item_id
 where a.id=allocation_id and a.tenant_id=allocation_reversals.tenant_id and
 ((o.kind='AP' and finance.payable_read_allowed(o.tenant_id,o.legal_entity_id,o.branch_id)) or
 (o.kind='AR' and core.has_permission(o.tenant_id,'finance.receivables.view',o.legal_entity_id,o.branch_id)))));

create function finance.require_control_scope(t uuid,e uuid,b uuid) returns void
language plpgsql stable security definer set search_path='' as $$begin
 if e is null or b is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 perform core.wave3_require_scope(t,'finance.view',e,b);
 perform core.wave3_require_scope(t,'finance.controls.reconcile',e,b);
end $$;
revoke all on function finance.require_control_scope(uuid,uuid,uuid) from public,anon,authenticated;

create table finance.control_reports(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 as_of date not null,generated_at timestamptz not null,summary jsonb not null,evidence jsonb not null,
 created_by uuid not null references auth.users(id),unique(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),check(octet_length(evidence::text)<=16777216)
);
alter table finance.control_reports enable row level security;
alter table finance.control_reports force row level security;
revoke all on finance.control_reports from public,anon,authenticated;
create trigger immutable before update or delete on finance.control_reports for each row execute function workflow.reject_history_mutation();
create index control_reports_scope on finance.control_reports(tenant_id,legal_entity_id,branch_id,id);
create index control_reports_branch on finance.control_reports(tenant_id,branch_id);
create index control_reports_actor on finance.control_reports(created_by);

-- STABLE fixes a single MVCC snapshot for all reads, including residual/reversal helpers.
create function finance.build_control_report(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d date:=(p->>'as_of')::date;k text:=p->>'kind';sgn integer;
 items jsonb;allocations jsonb;entries jsonb;journals jsonb;accounts jsonb;differences jsonb;result jsonb;
 ids uuid[];sv numeric;gv numeric;begin
 perform finance.require_control_scope(t,e,b);
 if k is null or k not in('AR','AP') or d is null or d>(statement_timestamp() at time zone 'UTC')::date then
 raise exception using errcode='22023',message='CONTROL_REPORT_INPUT_INVALID';end if;
 sgn:=case k when 'AR' then 1 else -1 end;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into items from (
  select o.id,o.party_id,party.display_name party_name,o.source_type,o.source_id,o.document_number,o.journal_entry_id,o.command_id,
  o.posting_date,o.due_date,o.currency_code,o.base_currency_code,finance.open_item_control(t,o.id)::text evidence_key,
  o.original_amount::text original_amount,o.original_base_amount::text original_base_amount,
  r->>'amount' open_amount,r->>'base_amount' open_base_amount,
  (o.original_amount-(r->>'amount')::numeric)::text settled_amount,
  (o.original_base_amount-(r->>'base_amount')::numeric)::text settled_base_amount
  from finance.open_items o join crm.parties party on party.id=o.party_id
  cross join lateral (select finance.flow_residual(t,o.id,d) r) residual
  where o.tenant_id=t and o.legal_entity_id=e and o.branch_id=b and o.kind=k and o.posting_date<=d order by o.id limit 10001)q;
 if jsonb_array_length(items)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into allocations from (
  select a.id,a.command_id,a.source_open_item_id,a.target_open_item_id,s.document_number source_document_number,z.document_number target_document_number,
  a.posting_date,a.journal_entry_id,a.source_amount::text,a.transaction_amount::text,a.source_base_amount::text,a.target_base_amount::text,
  a.write_off::text,a.discount_amount::text,a.adjustment_base_amount::text,a.exchange_difference::text,a.reason,
  finance.open_item_control(t,s.id)::text source_control,finance.open_item_control(t,z.id)::text evidence_key,
  case when r.id is not null then sales.flow_exact_json(to_jsonb(r)) end reversal
  from finance.open_item_allocations a join finance.open_items s on s.id=a.source_open_item_id join finance.open_items z on z.id=a.target_open_item_id
  left join finance.allocation_reversals r on r.allocation_id=a.id and r.posting_date<=d
  where a.tenant_id=t and a.legal_entity_id=e and a.branch_id=b and s.kind=k and a.posting_date<=d order by a.id limit 10001)q;
 if jsonb_array_length(allocations)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select array_agg(distinct id order by id) into ids from (
  select (x->>'evidence_key')::uuid id from jsonb_array_elements(items)x
  union select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='receivable_control' and k='AR'
  union select payable_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e and k='AP')a where id is not null;
 if coalesce(cardinality(ids),0) not between 1 and 50 then raise exception using errcode='55000',message='CONTROL_ACCOUNT_SETUP_REQUIRED';end if;
 -- Dated subledger movements retain original command lineage, including exact reversal effects.
 with movements as (
  select 'item:'||(x->>'id') id,x->>'evidence_key' evidence_key,x->>'command_id' command_id,x->>'source_type' source_type,x->>'source_id' source_id,
   x->>'posting_date' posting_date,(x->>'original_base_amount')::numeric value from jsonb_array_elements(items)x
  union all select 'allocation-source:'||(x->>'id'),x->>'source_control',x->>'command_id','allocation',x->>'id',x->>'posting_date',(x->>'source_base_amount')::numeric from jsonb_array_elements(allocations)x
  union all select 'allocation-target:'||(x->>'id'),x->>'evidence_key',x->>'command_id','allocation',x->>'id',x->>'posting_date',-(x->>'target_base_amount')::numeric-(x->>'adjustment_base_amount')::numeric from jsonb_array_elements(allocations)x
  union all select 'reversal-source:'||(x#>>'{reversal,id}'),x->>'source_control',x#>>'{reversal,command_id}','allocation_reversal',x#>>'{reversal,id}',x#>>'{reversal,posting_date}',-(x->>'source_base_amount')::numeric from jsonb_array_elements(allocations)x where x->'reversal'<>'null'::jsonb
  union all select 'reversal-target:'||(x#>>'{reversal,id}'),x->>'evidence_key',x#>>'{reversal,command_id}','allocation_reversal',x#>>'{reversal,id}',x#>>'{reversal,posting_date}',(x->>'target_base_amount')::numeric+(x->>'adjustment_base_amount')::numeric from jsonb_array_elements(allocations)x where x->'reversal'<>'null'::jsonb)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'evidence_key',evidence_key,'command_id',command_id,'source_type',source_type,'source_id',source_id,'posting_date',posting_date,'value',value::text) order by id),'[]') into entries from movements;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id::text evidence_key,a.code account_code,j.command_id,j.id journal_id,j.document_number,j.source_type,j.source_id,l.source_line_id,l.posting_date,
   (sgn*(l.base_debit-l.base_credit))::text value,l.base_debit::text,l.base_credit::text
  from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id join finance.accounts a on a.id=l.account_id
  where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.account_id=any(ids) and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select jsonb_agg(jsonb_build_object('id',a.id,'evidence_key',a.id,'code',a.code,'name',a.name,'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a.id)
 into accounts from finance.accounts a
 cross join lateral(select coalesce(sum((x->>'open_base_amount')::numeric),0) v from jsonb_array_elements(items)x where x->>'evidence_key'=a.id::text)s
 cross join lateral(select coalesce(sum((x->>'value')::numeric),0) g from jsonb_array_elements(journals)x where x->>'evidence_key'=a.id::text)j where a.id=any(ids);
 with effects as (
  select x->>'evidence_key' a,x->>'command_id' c,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(entries)x
  union all select x->>'evidence_key',x->>'command_id',0,(x->>'value')::numeric from jsonb_array_elements(journals)x), totals as(select a,c,sum(v)v,sum(g)g from effects group by a,c)
 select coalesce(jsonb_agg(jsonb_build_object('id',a||':'||c,'evidence_key',a,'command_id',c,'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a,c),'[]') into differences from totals where v<>g;
 if greatest(jsonb_array_length(entries),jsonb_array_length(differences))>50000 then raise exception using errcode='54000',message='CONTROL_REPORT_OUTPUT_LIMIT';end if;
 select coalesce(sum((x->>'subledger_value')::numeric),0),coalesce(sum((x->>'gl_value')::numeric),0) into sv,gv from jsonb_array_elements(accounts)x;
 if sv<>(select coalesce(sum((x->>'value')::numeric),0) from jsonb_array_elements(entries)x) then raise exception using errcode='23514',message='CONTROL_RESIDUAL_DIVERGENCE';end if;
 result:=jsonb_build_object('summary',jsonb_build_object('id',p->>'id','version',1,'status','generated','kind',k,'as_of',d,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
 'entity_name',(select name from core.legal_entities where id=e),'branch_name',(select name from core.branches where id=b),
 'currency_code',(select currency_code from core.legal_entities where id=e),'generated_at',statement_timestamp(),
 'accounts',accounts,'subledger_value',sv::text,'gl_value',gv::text,'difference',(sv-gv)::text,'item_count',jsonb_array_length(items),'difference_count',jsonb_array_length(differences)),
 'items',items,'allocations',allocations,'entries',entries,'journals',journals,'accounts',accounts,'differences',differences);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='CONTROL_REPORT_EVIDENCE_LIMIT';end if;
 return result;
end $$;
revoke all on function finance.build_control_report(uuid,uuid,uuid,jsonb) from public,anon,authenticated;


create function api.generate_control_reconciliation_report(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$declare h text;r jsonb;data jsonb;summary jsonb;id uuid:=(p_payload->>'id')::uuid;req uuid:=gen_random_uuid();begin
 perform finance.require_control_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if id is null or p_client_timestamp is null then raise exception using errcode='22023',message='CONTROL_REPORT_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('finance.controls.report',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.controls.report',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 data:=finance.build_control_report(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);summary:=data->'summary';
 insert into finance.control_reports values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(summary->>'as_of')::date,(summary->>'generated_at')::timestamptz,summary,data,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'finance.controls.report',p_command_id,'control_reconciliation_report',id,p_idempotency_key,h,null,summary,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','generated'),jsonb_build_array(jsonb_build_object('topic','finance.controls.report','payload',summary)),'[]',req,req);
end $$;
create function api.control_reconciliation_reports(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform finance.require_control_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_resource='reports' then
  select coalesce(jsonb_agg(summary order by id),'[]') into rows from(select id,summary from finance.control_reports
   where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and(p_after is null or id>p_after) order by id limit 51)q;
 else raise exception using errcode='22023',message='CONTROL_REPORT_RESOURCE_INVALID';end if;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor);
end $$;
create function api.control_reconciliation_report_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,p_section text,p_after integer default 0,p_evidence_key text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare r finance.control_reports%rowtype;rows jsonb;n integer;begin
 perform finance.require_control_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_section is null or p_section not in('items','allocations','entries','journals','accounts','differences') or p_after is null or p_after<0 or p_after>50000 then raise exception using errcode='22023',message='CONTROL_REPORT_PAGE_INVALID';end if;
 select * into r from finance.control_reports where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_id;
 if not found then raise exception using errcode='42501',message='CONTROL_REPORT_REPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(value order by ord),'[]') into rows from(select value,ord from jsonb_array_elements(r.evidence->p_section) with ordinality x(value,ord)
  where p_evidence_key is null or value->>'evidence_key'=p_evidence_key
   or (p_section='allocations' and value->>'source_control'=p_evidence_key) order by ord offset p_after limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('summary',r.summary,'section',p_section,'evidence_key',p_evidence_key,'items',rows,'next_cursor',case when n>50 then (p_after+50)::text end);
end $$;
revoke all on function api.generate_control_reconciliation_report(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.control_reconciliation_reports(uuid,uuid,uuid,text,uuid),api.control_reconciliation_report_page(uuid,uuid,uuid,uuid,text,integer,text) from public,anon,authenticated;
grant execute on function api.generate_control_reconciliation_report(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.control_reconciliation_reports(uuid,uuid,uuid,text,uuid),api.control_reconciliation_report_page(uuid,uuid,uuid,uuid,text,integer,text) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED AC-318 candidate; all verification runs end in ROLLBACK.
create table finance.bank_statements (
 id uuid primary key, tenant_id uuid not null, legal_entity_id uuid not null, branch_id uuid not null,
 bank_id uuid not null, account_id uuid not null, currency_code text not null,
 identity text not null check(length(identity) between 1 and 140), start_date date not null, end_date date not null,
 opening numeric(20,6) not null, closing numeric(20,6) not null, total numeric(20,6) not null,
 row_count integer not null check(row_count between 1 and 2000), created_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(), unique(tenant_id,id), unique(tenant_id,bank_id,identity),
 foreign key(tenant_id,bank_id) references finance.cash_bank_accounts(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(start_date<=end_date), check(opening+total=closing)
);
create table finance.bank_statement_lines (
 id uuid primary key, tenant_id uuid not null, statement_id uuid not null, bank_id uuid not null,
 line_number integer not null, posting_date date not null, reference text not null, description text not null,
 amount numeric(20,6) not null check(amount<>0), unique(tenant_id,id), unique(tenant_id,bank_id,reference),
 unique(tenant_id,statement_id,line_number),
 foreign key(tenant_id,statement_id) references finance.bank_statements(tenant_id,id),
 foreign key(tenant_id,bank_id) references finance.cash_bank_accounts(tenant_id,id)
);
create table finance.bank_matches (
 id uuid primary key, tenant_id uuid not null, legal_entity_id uuid not null, branch_id uuid not null,
 bank_id uuid not null, posting_date date not null, statement_total numeric(20,6) not null,
 journal_total numeric(20,6) not null, difference numeric(20,6) not null, currency_code text not null,
 reason text not null, statement_line_ids uuid[] not null, journal_line_ids uuid[] not null,
 adjustment_journal_id uuid, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(),
 unique(tenant_id,id), foreign key(tenant_id,bank_id) references finance.cash_bank_accounts(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,adjustment_journal_id) references finance.journal_entries(tenant_id,id),
 check(statement_total-journal_total=difference)
);
create table finance.bank_match_reversals (
 id uuid primary key, tenant_id uuid not null, match_id uuid not null, posting_date date not null,
 reason text not null, journal_entry_id uuid, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(),
 unique(tenant_id,match_id), foreign key(tenant_id,match_id) references finance.bank_matches(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id)
);
-- Private, rebuildable active claim indexes. Original memberships remain in bank_matches.
create table finance.bank_match_claims (
 tenant_id uuid not null, kind text not null check(kind in('statement','journal')), source_id uuid not null, match_id uuid not null,
 primary key(tenant_id,kind,source_id), foreign key(tenant_id,match_id) references finance.bank_matches(tenant_id,id)
);
create index bank_statements_scope on finance.bank_statements(tenant_id,legal_entity_id,branch_id,bank_id,id);
create unique index bank_statements_identity_ci on finance.bank_statements(tenant_id,bank_id,lower(btrim(identity)));
create index bank_matches_scope on finance.bank_matches(tenant_id,legal_entity_id,branch_id,bank_id,id);
create index bank_claim_match on finance.bank_match_claims(tenant_id,match_id);
do $$declare t text;f record;begin
 foreach t in array array['bank_statements','bank_statement_lines','bank_matches','bank_match_reversals','bank_match_claims'] loop
  execute format('alter table finance.%I enable row level security',t);
  execute format('alter table finance.%I force row level security',t);
  execute format('revoke all on finance.%I from public,anon,authenticated',t);
  if t<>'bank_match_claims' then execute format('create trigger immutable before update or delete on finance.%I for each row execute function workflow.reject_history_mutation()',t);end if;
  for f in select c.conname,(select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(c.conkey) with ordinality k(num,n)
   join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.num) cols from pg_constraint c where c.conrelid=('finance.'||t)::regclass and c.contype='f' loop
   execute format('create index %I on finance.%I(%s)',f.conname||'_idx',t,f.cols);end loop;
 end loop;
end$$;

create function finance.bank_protect_basis() returns trigger language plpgsql set search_path='' as $$begin
 if (new.account_id,new.currency_code,new.legal_entity_id,new.branch_id) is distinct from (old.account_id,old.currency_code,old.legal_entity_id,old.branch_id)
 and (exists(select 1 from finance.bank_statements where tenant_id=old.tenant_id and bank_id=old.id)
  or exists(select 1 from finance.journal_lines where tenant_id=old.tenant_id and legal_entity_id=old.legal_entity_id and branch_id=old.branch_id and account_id=old.account_id))
 then raise exception using errcode='55000',message='BANK_BASIS_IN_USE';end if;
 return new;
end$$;
create trigger bank_protect_basis before update on finance.cash_bank_accounts for each row execute function finance.bank_protect_basis();

create function finance.bank_scope(t uuid,e uuid,b uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if e is null or b is null then raise exception using errcode='42501',message='BRANCH_SCOPE_REQUIRED';end if;
 perform core.wave3_require_scope(t,'finance.view',e,b);
end$$;
create function finance.bank_json(j jsonb) returns jsonb language sql immutable set search_path='' as $$
 select j||case when j ? 'opening' then jsonb_build_object('opening',j->>'opening','closing',j->>'closing','total',j->>'total') else '{}'::jsonb end
 ||case when j ? 'amount' then jsonb_build_object('amount',j->>'amount') else '{}'::jsonb end
 ||case when j ? 'difference' then jsonb_build_object('statement_total',j->>'statement_total','journal_total',j->>'journal_total','difference',j->>'difference') else '{}'::jsonb end
$$;

create function finance.bank_amount(v jsonb,f text) returns numeric language plpgsql immutable set search_path='' as $$
declare s text:=v#>>'{}';begin
 if jsonb_typeof(v) is distinct from 'string' or s !~ '^-?[0-9]{1,14}([.][0-9]{1,6})?$' then
  raise exception using errcode='22023',message='BANK_EXACT_AMOUNT_REQUIRED';end if;
 return (case when left(s,1)='-' then -1 else 1 end)*sales.wave3_decimal_string(to_jsonb(ltrim(s,'-')),f,6,true,0,null);
end$$;

create function api.bank_reconciliation_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t uuid:=p_tenant_id;e uuid:=p_legal_entity_id;b uuid:=p_branch_id;p jsonb:=p_payload;act text:=p_payload->>'action';
 v_id uuid:=(p_payload->>'id')::uuid;bank finance.cash_bank_accounts%rowtype;m finance.bank_matches%rowtype;
 h text;r jsonb;result jsonb;req uuid:=gen_random_uuid();cmd text;d date;startd date;endd date;
 x jsonb;amount numeric;opening numeric;closing numeric;st numeric:=0;jt numeric:=0;diff numeric;tol numeric;
 sids uuid[];jids uuid[];n integer;cnt integer;newj uuid;fx jsonb;doc jsonb;lines jsonb;rev finance.journal_entries%rowtype;
begin
 perform finance.bank_scope(t,e,b);
 if act is null or act not in('import','match','reverse','rules') or v_id is null or p_client_timestamp is null then raise exception using errcode='22023',message='BANK_INPUT_INVALID';end if;
 perform core.wave3_require_scope(t,case when act='import' then 'finance.bank.import' when act='rules' then 'finance.bank.manage' else 'finance.bank.reconcile' end,e,b);
 cmd:='finance.bank.'||act;
 h:=core.wave3_request_hash(cmd,p_command_id,t,e,b,p,p_expected_entity_version);
 -- Current access is checked before replay, including the adjustment capability.
 if act='match' and p->>'adjustment_account_id' is not null then perform core.require_permission(t,'finance.bank.adjust',e,b);end if;
 if act='reverse' then
  select * into m from finance.bank_matches where tenant_id=t and legal_entity_id=e and branch_id=b and id=(p->>'match_id')::uuid;
  if not found then raise exception using errcode='42501',message='BANK_MATCH_SCOPE_REQUIRED';end if;
  if m.adjustment_journal_id is not null then perform core.require_permission(t,'finance.bank.adjust',e,b);end if;
 end if;
 r:=core.wave3_replay(t,cmd,p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 select * into bank from finance.cash_bank_accounts where tenant_id=t and legal_entity_id=e and branch_id=b
 and id=case when act='reverse' then m.bank_id else (p->>'bank_id')::uuid end for update;
 if not found or bank.account_kind<>'bank' or (bank.status<>'active' and act<>'reverse') then raise exception using errcode='42501',message='BANK_SCOPE_REQUIRED';end if;
 if exists(select 1 from finance.cash_bank_accounts where tenant_id=t and legal_entity_id=e and branch_id=b and account_id=bank.account_id and currency_code=bank.currency_code and id<>bank.id and status='active') then
  raise exception using errcode='55000',message='BANK_GL_BASIS_AMBIGUOUS';end if;
 if act='rules' then
  perform core.wave3_assert_expected_version(bank.version,p_expected_entity_version,'{}');
  tol:=sales.wave3_decimal_string(p->'tolerance','tolerance',6,true,0,null)::numeric;
  if length(coalesce(trim(p->>'reason'),'')) not between 3 and 1000 then raise exception using errcode='22023',message='BANK_REASON_DATE_REQUIRED';end if;
  update finance.cash_bank_accounts set reconciliation_rules=jsonb_build_object('tolerance',tol::text),updated_by=auth.uid() where finance.cash_bank_accounts.id=bank.id;
  select jsonb_build_object('id',v_id,'tenant_id',t,'legal_entity_id',e,'branch_id',b,'bank_id',bank.id,'version',1,'bank_version',a.version,'status','configured','tolerance',tol::text,'reason',trim(p->>'reason')) into result from finance.cash_bank_accounts a where a.id=bank.id;
 elsif act='import' then
  perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
  startd:=(p->>'start_date')::date;endd:=(p->>'end_date')::date;
  if startd is null or endd is null or startd>endd or endd>(clock_timestamp() at time zone 'UTC')::date
   or length(coalesce(trim(p->>'identity'),'')) not between 1 and 140
   or jsonb_typeof(p->'lines') is distinct from 'array' or jsonb_array_length(p->'lines') not between 1 and 2000
   or octet_length(p::text)>2097152 then raise exception using errcode='22023',message='BANK_STATEMENT_INVALID';end if;
  if exists(select 1 from finance.bank_statements where tenant_id=t and bank_id=bank.id and lower(btrim(identity))=lower(trim(p->>'identity'))) then
   raise exception using errcode='23505',message='BANK_STATEMENT_DUPLICATE';end if;
  opening:=finance.bank_amount(p->'opening','opening');
  closing:=finance.bank_amount(p->'closing','closing');
  for x in select value from jsonb_array_elements(p->'lines') loop
   amount:=finance.bank_amount(x->'amount','amount');d:=(x->>'date')::date;
   if amount=0 or d is null or d not between startd and endd or length(coalesce(trim(x->>'reference'),'')) not between 1 and 140
    or length(coalesce(x->>'description',''))>500 then raise exception using errcode='22023',message='BANK_LINE_INVALID';end if;
   st:=st+amount;
  end loop;
  if opening+st<>closing then raise exception using errcode='23514',message='BANK_BALANCE_MISMATCH';end if;
  insert into finance.bank_statements values(v_id,t,e,b,bank.id,bank.account_id,bank.currency_code,trim(p->>'identity'),startd,endd,opening,closing,st,jsonb_array_length(p->'lines'),auth.uid(),now());
  insert into finance.bank_statement_lines select gen_random_uuid(),t,v_id,bank.id,ord,(a.x->>'date')::date,trim(a.x->>'reference'),coalesce(a.x->>'description',''),(a.x->>'amount')::numeric
   from jsonb_array_elements(p->'lines') with ordinality a(x,ord);
  select finance.bank_json(to_jsonb(s))||jsonb_build_object('version',1,'status','imported') into result from finance.bank_statements s where s.id=v_id;
 else
  d:=(p->>'posting_date')::date;
  if d is null or d>(clock_timestamp() at time zone 'UTC')::date or length(coalesce(trim(p->>'reason'),'')) not between 3 and 1000 then raise exception using errcode='22023',message='BANK_REASON_DATE_REQUIRED';end if;
  perform finance.wave3_lock_open_period(t,e,d);
  if act='match' then
   perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
   if jsonb_typeof(p->'statement_line_ids') is distinct from 'array' or jsonb_typeof(p->'journal_line_ids') is distinct from 'array'
    or jsonb_array_length(p->'statement_line_ids') not between 1 and 100 or jsonb_array_length(p->'journal_line_ids') not between 1 and 100
    or least(jsonb_array_length(p->'statement_line_ids'),jsonb_array_length(p->'journal_line_ids'))<>1 then raise exception using errcode='22023',message='BANK_MATCH_SHAPE_INVALID';end if;
   select array_agg(v::uuid order by v) into sids from jsonb_array_elements_text(p->'statement_line_ids')a(v);
   select array_agg(v::uuid order by v) into jids from jsonb_array_elements_text(p->'journal_line_ids')a(v);
   if (select count(distinct v) from unnest(sids)v)<>cardinality(sids) or (select count(distinct v) from unnest(jids)v)<>cardinality(jids) then raise exception using errcode='22023',message='BANK_MATCH_DUPLICATE_MEMBER';end if;
   perform 1 from finance.bank_statement_lines where tenant_id=t and bank_id=bank.id and finance.bank_statement_lines.id=any(sids) order by finance.bank_statement_lines.id for update;
   select count(*),sum(l.amount) into cnt,st from finance.bank_statement_lines l join finance.bank_statements s on s.id=l.statement_id
    where l.tenant_id=t and l.bank_id=bank.id and l.id=any(sids) and l.posting_date<=d and s.account_id=bank.account_id and s.currency_code=bank.currency_code;
   if cnt<>cardinality(sids) then raise exception using errcode='42501',message='BANK_LINE_SCOPE_REQUIRED';end if;
   perform 1 from finance.journal_lines l where l.tenant_id=t and l.id=any(jids) order by l.id for update;
   select count(*),sum(l.transaction_debit-l.transaction_credit) into cnt,jt from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id
    where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.id=any(jids) and l.account_id=bank.account_id
    and l.currency_code=bank.currency_code and l.posting_date<=d and j.status='posted'
    and j.source_type not in('bank_adjustment','bank_adjustment_reversal');
   if cnt<>cardinality(jids) then raise exception using errcode='42501',message='BANK_JOURNAL_SCOPE_REQUIRED';end if;
   if st=0 or jt=0 or sign(st)<>sign(jt) then raise exception using errcode='22023',message='BANK_MATCH_SIGN_INVALID';end if;
   if exists(select 1 from finance.bank_match_claims c where c.tenant_id=t and ((c.kind='statement' and c.source_id=any(sids)) or(c.kind='journal' and c.source_id=any(jids)))) then raise exception using errcode='40001',message='BANK_LINE_ALREADY_MATCHED';end if;
   -- A rematch cannot predate the reversal that released any selected source.
   if exists(select 1 from finance.bank_match_reversals rr join finance.bank_matches mm on mm.id=rr.match_id where rr.tenant_id=t and rr.posting_date>d
    and (mm.statement_line_ids&&sids or mm.journal_line_ids&&jids)) then raise exception using errcode='22023',message='BANK_MATCH_DATE_BEFORE_HISTORY';end if;
   diff:=st-jt;
   tol:=sales.wave3_decimal_string(coalesce(bank.reconciliation_rules->'tolerance','"0"'),'tolerance',6,true,0,null)::numeric;
   if abs(diff)>tol then raise exception using errcode='22023',message='BANK_TOLERANCE_EXCEEDED';end if;
   if diff<>0 then
    perform core.require_permission(t,'finance.bank.adjust',e,b);
    if not exists(select 1 from finance.accounts a where a.tenant_id=t and a.legal_entity_id=e and a.id=(p->>'adjustment_account_id')::uuid and a.status='active' and a.is_posting and a.account_type in('expense','revenue')
      and not exists(select 1 from finance.posting_mappings pm where pm.tenant_id=t and pm.account_id=a.id and pm.purpose in('receivable_control','payable_control'))
      and not exists(select 1 from finance.cash_bank_accounts cb where cb.tenant_id=t and cb.account_id=a.id)) then raise exception using errcode='22023',message='BANK_ADJUSTMENT_ACCOUNT_INVALID';end if;
    fx:=finance.flow_rate(t,e,bank.currency_code,d,(p->>'exchange_rate_id')::uuid);
    doc:=fx||jsonb_build_object('tenant_id',t,'legal_entity_id',e,'branch_id',b,'document_date',d,'currency_code',bank.currency_code);
    amount:=round(diff*(fx->>'exchange_rate')::numeric,6);
    if amount=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
    newj:=finance.flow_post_journal(doc,jsonb_build_array(finance.flow_jline(bank.account_id,diff,amount),finance.flow_jline((p->>'adjustment_account_id')::uuid,-diff,-amount)),'bank_adjustment',v_id,req,p_command_id);
   end if;
   insert into finance.bank_matches values(v_id,t,e,b,bank.id,d,st,jt,diff,bank.currency_code,trim(p->>'reason'),sids,jids,newj,auth.uid(),now());
   insert into finance.bank_match_claims select t,'statement',v,v_id from unnest(sids)v union all select t,'journal',v,v_id from unnest(jids)v;
   select finance.bank_json(to_jsonb(mm))||jsonb_build_object('version',1,'status','matched') into result from finance.bank_matches mm where mm.id=v_id;
  else
   perform core.wave3_assert_expected_version(1,p_expected_entity_version,'{}');
   if d<m.posting_date then raise exception using errcode='22023',message='BANK_REVERSAL_DATE_INVALID';end if;
   if exists(select 1 from finance.bank_match_reversals where tenant_id=t and match_id=m.id) then raise exception using errcode='55000',message='BANK_MATCH_ALREADY_REVERSED';end if;
   if m.adjustment_journal_id is not null then
    select * into rev from finance.journal_entries where tenant_id=t and finance.journal_entries.id=m.adjustment_journal_id;
    doc:=jsonb_build_object('tenant_id',t,'legal_entity_id',e,'branch_id',b,'document_date',d,'currency_code',rev.currency_code,'base_currency_code',rev.base_currency_code,'exchange_rate',rev.exchange_rate::text);
    select jsonb_agg(finance.flow_jline(l.account_id,l.transaction_credit-l.transaction_debit,l.base_credit-l.base_debit) order by l.line_number) into lines from finance.journal_lines l where l.journal_entry_id=rev.id;
    newj:=finance.flow_post_journal(doc,lines,'bank_adjustment_reversal',v_id,req,p_command_id);
   end if;
   insert into finance.bank_match_reversals values(v_id,t,m.id,d,trim(p->>'reason'),newj,auth.uid(),now());
   delete from finance.bank_match_claims where tenant_id=t and match_id=m.id;
   result:=jsonb_build_object('id',v_id,'tenant_id',t,'legal_entity_id',e,'branch_id',b,'bank_id',bank.id,'match_id',m.id,'version',1,'status','reversed','journal_entry_id',newj);
  end if;
 end if;
 return core.wave3_finish_command(t,cmd,p_command_id,'bank_'||act,v_id,p_idempotency_key,h,null,result,e,b,'{}',jsonb_build_object('to_status',result->>'status'),jsonb_build_array(jsonb_build_object('topic',cmd,'payload',jsonb_build_object('id',v_id))),'[]',req,req);
end$$;

create function api.bank_reconciliation_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_bank_id uuid default null,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare t uuid:=p_tenant_id;e uuid:=p_legal_entity_id;b uuid:=p_branch_id;bank finance.cash_bank_accounts%rowtype;rows jsonb;cursor uuid;begin
 perform finance.bank_scope(t,e,b);
 if p_resource not in('accounts','statements','statement_lines','journal_lines','matches','offset_accounts','rates') or p_resource is null then raise exception using errcode='22023',message='BANK_RESOURCE_INVALID';end if;
 if p_resource not in('accounts','offset_accounts','rates') then
  select * into bank from finance.cash_bank_accounts where tenant_id=t and legal_entity_id=e and branch_id=b and id=p_bank_id;
  if not found then raise exception using errcode='42501',message='BANK_SCOPE_REQUIRED';end if;
 end if;
 if p_resource='accounts' then
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select id,code,name,currency_code,version,status,reconciliation_rules from finance.cash_bank_accounts where tenant_id=t and legal_entity_id=e and branch_id=b and account_kind='bank' and (p_after is null or id>p_after) order by id limit 51)q;
 elsif p_resource='offset_accounts' then
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select id,code,name from finance.accounts where tenant_id=t and legal_entity_id=e and is_posting and status='active' and account_type in('expense','revenue') and (p_after is null or id>p_after) order by id limit 51)q;
 elsif p_resource='rates' then
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select id,source_currency_code,target_currency_code,rate::text,effective_date from finance.exchange_rates where tenant_id=t and legal_entity_id=e and status='active' and (p_after is null or id>p_after) order by id limit 51)q;
 elsif p_resource='statements' then
  select coalesce(jsonb_agg(finance.bank_json(to_jsonb(q)) order by id),'[]') into rows from(select * from finance.bank_statements where tenant_id=t and legal_entity_id=e and branch_id=b and bank_id=bank.id and (p_after is null or id>p_after) order by id limit 51)q;
 elsif p_resource='statement_lines' then
  select coalesce(jsonb_agg(finance.bank_json(to_jsonb(q)) order by id),'[]') into rows from(select l.*,c.match_id from finance.bank_statement_lines l left join finance.bank_match_claims c on c.tenant_id=l.tenant_id and c.kind='statement' and c.source_id=l.id where l.tenant_id=t and l.bank_id=bank.id and (p_after is null or l.id>p_after) order by l.id limit 51)q;
 elsif p_resource='journal_lines' then
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(select l.id,j.document_number,j.source_type,j.source_id,l.posting_date,(l.transaction_debit-l.transaction_credit)::text amount,(l.base_debit-l.base_credit)::text base_amount,c.match_id from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id left join finance.bank_match_claims c on c.tenant_id=l.tenant_id and c.kind='journal' and c.source_id=l.id
   where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.account_id=bank.account_id and l.currency_code=bank.currency_code and j.status='posted' and j.source_type not in('bank_adjustment','bank_adjustment_reversal') and(p_after is null or l.id>p_after) order by l.id limit 51)q;
 else
  select coalesce(jsonb_agg(finance.bank_json(to_jsonb(q)) order by id),'[]') into rows from(select m.*,to_jsonb(rr) reversal from finance.bank_matches m left join finance.bank_match_reversals rr on rr.tenant_id=m.tenant_id and rr.match_id=m.id where m.tenant_id=t and m.legal_entity_id=e and m.branch_id=b and m.bank_id=bank.id and (p_after is null or m.id>p_after) order by m.id limit 51)q;
 end if;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor,'tenant_id',t,'legal_entity_id',e,'branch_id',b,'resource',p_resource,'bank_id',p_bank_id);
end$$;
revoke all on function finance.bank_protect_basis(),finance.bank_scope(uuid,uuid,uuid),finance.bank_json(jsonb),finance.bank_amount(jsonb,text),api.bank_reconciliation_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.bank_reconciliation_options(uuid,uuid,uuid,text,uuid,uuid) from public,anon,authenticated;
grant execute on function api.bank_reconciliation_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.bank_reconciliation_options(uuid,uuid,uuid,text,uuid,uuid) to authenticated;
notify pgrst,'reload schema';

