create table finance.budget_versions (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 root_id uuid not null,revision integer not null check(revision>0),
 period_id uuid,budget_year integer not null check(budget_year between 2000 and 2100),
 branch_id uuid,currency_code text not null references core.currencies(code),
 lines jsonb not null check(jsonb_typeof(lines)='array' and jsonb_array_length(lines) between 1 and 500),
 status text not null check(status in('draft','submitted','approved','rejected')),
 version bigint not null check(version>0),reason text not null
  check(length(trim(reason)) between 3 and 1000),
 created_by uuid not null references auth.users(id),submitted_by uuid references auth.users(id),
 decided_by uuid references auth.users(id),created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),decided_at timestamptz,
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,root_id,revision),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,period_id)
  references finance.fiscal_periods(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id)
);
create index budget_scope on finance.budget_versions(tenant_id,legal_entity_id,id);
create index budget_root on finance.budget_versions(tenant_id,root_id,revision desc);
create index budget_actor on finance.budget_versions(created_by);
alter table finance.budget_versions enable row level security;
alter table finance.budget_versions force row level security;
revoke all on finance.budget_versions from public,anon,authenticated;
create function finance.guard_budget_mutation() returns trigger
language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' or old.status in('approved','rejected')
  or new.tenant_id is distinct from old.tenant_id
  or new.legal_entity_id is distinct from old.legal_entity_id
  or new.root_id is distinct from old.root_id
  or new.revision is distinct from old.revision
  or new.period_id is distinct from old.period_id
  or new.budget_year is distinct from old.budget_year
  or new.branch_id is distinct from old.branch_id
  or new.currency_code is distinct from old.currency_code then
  raise exception using errcode='55000',message='BUDGET_HISTORY_IMMUTABLE';end if;
 return new;
end$$;
create trigger budget_guard before update or delete on finance.budget_versions
 for each row execute function finance.guard_budget_mutation();

create table finance.budget_events (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,
 legal_entity_id uuid not null,budget_id uuid not null,version bigint not null,
 action text not null,reason text not null,snapshot jsonb not null,
 actor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),unique(tenant_id,budget_id,version),
 foreign key(tenant_id,budget_id) references finance.budget_versions(tenant_id,id)
);
create index budget_events_actor on finance.budget_events(actor_id);
alter table finance.budget_events enable row level security;
alter table finance.budget_events force row level security;
revoke all on finance.budget_events from public,anon,authenticated;
create trigger immutable before update or delete on finance.budget_events
 for each row execute function workflow.reject_history_mutation();

create function finance.validate_budget_lines(t uuid,e uuid,lines jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare x jsonb;out_rows jsonb:='[]';ids uuid[]:='{}';accounts uuid[]:='{}';
 id uuid;account uuid;amount text;begin
 if jsonb_typeof(lines)<>'array' or jsonb_array_length(lines) not between 1 and 500 then
  raise exception using errcode='22023',message='BUDGET_LINES_INVALID';end if;
 for x in select value from jsonb_array_elements(lines) loop
  if jsonb_typeof(x)<>'object' or x->>'cost_centre_id' is not null
   or x->>'project_id' is not null then
   raise exception using errcode='22023',message='BUDGET_DIMENSION_UNAVAILABLE';end if;
  id:=(x->>'id')::uuid;account:=(x->>'account_id')::uuid;amount:=x->>'amount';
  if id is null or account is null or id=any(ids) or account=any(accounts)
   or jsonb_typeof(x->'amount')<>'string' or amount is null
   or amount !~ '^\d+(\.\d{1,6})?$'
   or length(amount)>35 or amount::numeric>99999999999999 then
   raise exception using errcode='22023',message='BUDGET_LINE_INVALID';end if;
  if not exists(select 1 from finance.accounts a where a.tenant_id=t
   and a.legal_entity_id=e and a.id=account and a.status='active' and a.is_posting) then
   raise exception using errcode='22023',message='BUDGET_ACCOUNT_INVALID';end if;
  ids:=array_append(ids,id);accounts:=array_append(accounts,account);
  out_rows:=out_rows||jsonb_build_array(jsonb_build_object('id',id,
   'account_id',account,'amount',(amount::numeric(20,6))::text,
   'cost_centre_id',null,'project_id',null));
 end loop;
 return out_rows;
end$$;

create function api.budget_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t uuid:=p_tenant_id;e uuid:=p_legal_entity_id;b uuid:=p_branch_id;
 act text:=p_payload->>'action';v_id uuid:=(p_payload->>'id')::uuid;
 source_id uuid:=(p_payload->>'source_id')::uuid;
 budget finance.budget_versions%rowtype;source_budget finance.budget_versions%rowtype;
 period finance.fiscal_periods%rowtype;year_value integer;budget_branch uuid;
 currency text;reason text:=trim(p_payload->>'reason');v_lines jsonb;
 before_row jsonb;result jsonb;h text;r jsonb;req uuid:=gen_random_uuid();begin
 perform core.wave3_require_scope(t,case when act in('approve','reject') then
  'finance.budgets.approve' else 'finance.budgets.manage' end,e,null);
 perform core.wave3_require_scope(t,case when act in('approve','reject') then
  'finance.budgets.approve' else 'finance.budgets.manage' end,e,b);
 if act not in('create','save','submit','approve','reject','revise') or act is null
  or v_id is null or p_client_timestamp is null or reason is null
  or length(reason) not between 3 and 1000 then
  raise exception using errcode='22023',message='BUDGET_COMMAND_INVALID';end if;
 h:=core.wave3_request_hash('finance.budgets.'||act,p_command_id,t,e,b,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(t,'finance.budgets.'||act,p_command_id,p_idempotency_key,h);
 if r is not null then return r;end if;
 if act in('create','revise') then
  if act='revise' then
   select * into source_budget from finance.budget_versions where tenant_id=t and legal_entity_id=e
    and id=source_id and status='approved' for update;
   if not found then raise exception using errcode='55000',message='BUDGET_APPROVED_SOURCE_REQUIRED';end if;
   if source_budget.branch_id is not null and source_budget.branch_id<>b then
    raise exception using errcode='42501',message='BUDGET_BRANCH_SCOPE_REQUIRED';end if;
   perform core.wave3_assert_expected_version(source_budget.version,
    p_expected_entity_version,to_jsonb(source_budget));
   if exists(select 1 from finance.budget_versions where tenant_id=t and root_id=source_budget.root_id
    and revision>source_budget.revision) then
    raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
   v_lines:=source_budget.lines;budget_branch:=source_budget.branch_id;
   year_value:=source_budget.budget_year;currency:=source_budget.currency_code;
   budget.period_id:=source_budget.period_id;
  else
   perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
   budget.period_id:=(p_payload->>'period_id')::uuid;
   year_value:=(p_payload->>'budget_year')::integer;
   budget_branch:=(p_payload->>'branch_id')::uuid;
   currency:=p_payload->>'currency_code';
   if budget_branch is not null and budget_branch<>b then
    raise exception using errcode='42501',message='BUDGET_BRANCH_SCOPE_REQUIRED';end if;
   if budget_branch is not null and not exists(select 1 from core.branches
    where tenant_id=t and legal_entity_id=e and id=budget_branch and status='active') then
    raise exception using errcode='22023',message='BUDGET_BRANCH_INVALID';end if;
   if year_value not between 2000 and 2100 or year_value is null
    or currency is null or not exists(select 1 from core.currencies where code=currency) then
    raise exception using errcode='22023',message='BUDGET_BASIS_INVALID';end if;
   if budget.period_id is not null then
    select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
     and id=budget.period_id and status='active';
    if not found or extract(year from period.start_date)::integer<>year_value then
     raise exception using errcode='22023',message='BUDGET_PERIOD_INVALID';end if;
   end if;
   v_lines:=finance.validate_budget_lines(t,e,p_payload->'lines');
  end if;
  insert into finance.budget_versions(id,tenant_id,legal_entity_id,root_id,revision,
   period_id,budget_year,branch_id,currency_code,lines,status,version,reason,created_by)
  values(v_id,t,e,case when act='create' then v_id else source_budget.root_id end,
   case when act='create' then 1 else source_budget.revision+1 end,budget.period_id,
   year_value,budget_branch,currency,v_lines,'draft',1,reason,auth.uid());
 else
  select * into budget from finance.budget_versions where tenant_id=t and legal_entity_id=e
   and id=v_id for update;
  if not found then raise exception using errcode='42501',message='BUDGET_SCOPE_REQUIRED';end if;
  if budget.branch_id is not null and budget.branch_id<>b then
   raise exception using errcode='42501',message='BUDGET_BRANCH_SCOPE_REQUIRED';end if;
  perform core.wave3_assert_expected_version(budget.version,p_expected_entity_version,to_jsonb(budget));
  before_row:=to_jsonb(budget);
  if act in('save','submit') and budget.status<>'draft' or
   act in('approve','reject') and budget.status<>'submitted' then
   raise exception using errcode='55000',message='BUDGET_STATE_INVALID';end if;
  if act in('approve','reject') and auth.uid() in(budget.created_by,budget.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  if act='save' then
   v_lines:=finance.validate_budget_lines(t,e,p_payload->'lines');
   update finance.budget_versions set lines=v_lines,version=version+1,updated_at=now()
    where tenant_id=t and id=budget.id;
  else
   update finance.budget_versions set status=case act when 'submit' then 'submitted'
    when 'approve' then 'approved' else 'rejected' end,version=version+1,
    submitted_by=case when act='submit' then auth.uid() else submitted_by end,
    decided_by=case when act in('approve','reject') then auth.uid() else decided_by end,
    decided_at=case when act in('approve','reject') then now() else decided_at end,
    updated_at=now() where tenant_id=t and id=budget.id;
  end if;
 end if;
 select * into budget from finance.budget_versions v where v.tenant_id=t and v.id=v_id;
 insert into finance.budget_events(tenant_id,legal_entity_id,budget_id,version,action,reason,snapshot,actor_id)
 values(t,e,budget.id,budget.version,act,reason,to_jsonb(budget),auth.uid());
 result:=jsonb_build_object('id',budget.id,'tenant_id',t,'legal_entity_id',e,
  'branch_id',b,'budget_branch_id',budget.branch_id,'root_id',budget.root_id,
  'revision',budget.revision,'period_id',budget.period_id,'budget_year',budget.budget_year,
  'currency_code',budget.currency_code,'line_count',jsonb_array_length(budget.lines),
  'lines',budget.lines,'status',budget.status,'version',budget.version,
  'reason',budget.reason,'created_by',budget.created_by);
 return core.wave3_finish_command(t,'finance.budgets.'||act,p_command_id,'budget',v_id,
  p_idempotency_key,h,before_row,result,e,b,
  jsonb_build_object('period_id',budget.period_id,'root_id',budget.root_id),
  jsonb_build_object('to_status',budget.status,'revision',budget.revision,'reason',reason),
  jsonb_build_array(jsonb_build_object('topic','finance.budgets.'||act,'payload',result)),
  '[]',req,req);
end$$;

create function api.budget_options(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from (
  select id,root_id,revision,period_id,budget_year,branch_id budget_branch_id,
   currency_code,status,version,lines,reason,created_by,submitted_by,decided_by,
   created_at,decided_at
  from finance.budget_versions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and (branch_id is null or branch_id=p_branch_id)
   and (p_after is null or id>p_after) order by id limit 51)q;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'items',rows,'next_cursor',cursor);
end$$;

create table finance.budget_variance_reports (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 requested_branch_id uuid not null,budget_id uuid not null,as_of date not null,
 generated_at timestamptz not null,summary jsonb not null,evidence jsonb not null,
 created_by uuid not null references auth.users(id),unique(tenant_id,id),
 foreign key(tenant_id,budget_id) references finance.budget_versions(tenant_id,id),
 check(jsonb_typeof(summary)='object' and jsonb_typeof(evidence)='object'
  and octet_length(evidence::text)<=16777216)
);
create index budget_variance_scope on finance.budget_variance_reports(tenant_id,legal_entity_id,id);
create index budget_variance_budget on finance.budget_variance_reports(tenant_id,budget_id,id);
create index budget_variance_actor on finance.budget_variance_reports(created_by);
alter table finance.budget_variance_reports enable row level security;
alter table finance.budget_variance_reports force row level security;
revoke all on finance.budget_variance_reports from public,anon,authenticated;
create trigger immutable before update or delete on finance.budget_variance_reports
 for each row execute function workflow.reject_history_mutation();

create function finance.build_budget_variance(t uuid,e uuid,b uuid,budget_id uuid,d date,report_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare budget finance.budget_versions%rowtype;period finance.fiscal_periods%rowtype;
 start_date date;end_date date;base_currency text;x jsonb;a finance.accounts%rowtype;
 actual numeric;planned numeric;total_budget numeric:=0;total_actual numeric:=0;
 rows jsonb:='[]';journals jsonb:='[]';source_rows jsonb;source_count integer;
 summary jsonb;result jsonb;begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 select * into budget from finance.budget_versions where tenant_id=t and legal_entity_id=e
  and id=budget_id and status='approved' and (branch_id is null or branch_id=b);
 if not found then raise exception using errcode='42501',message='APPROVED_BUDGET_REQUIRED';end if;
 if budget.period_id is not null then
  select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
   and id=budget.period_id;
  start_date:=period.start_date;end_date:=period.end_date;
 else start_date:=make_date(budget.budget_year,1,1);
  end_date:=make_date(budget.budget_year,12,31);end if;
 if d is null or d<start_date or d>end_date or d>(clock_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='BUDGET_VARIANCE_DATE_INVALID';end if;
 select currency_code into base_currency from core.legal_entities
  where tenant_id=t and id=e;
 for x in select value from jsonb_array_elements(budget.lines) loop
  select * into a from finance.accounts where tenant_id=t and legal_entity_id=e
   and id=(x->>'account_id')::uuid;
  select coalesce(sum(case when a.normal_balance='debit' then
    case when budget.currency_code=base_currency then l.base_debit-l.base_credit
     else l.transaction_debit-l.transaction_credit end
   else case when budget.currency_code=base_currency then l.base_credit-l.base_debit
     else l.transaction_credit-l.transaction_debit end end),0),
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'budget_line_id',x->>'id',
    'journal_entry_id',j.id,'posting_date',j.posting_date,'document_number',j.document_number,
    'account_id',a.id,'branch_id',j.branch_id,'currency_code',j.currency_code,
    'base_debit',l.base_debit::text,'base_credit',l.base_credit::text,
    'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'source_type',j.source_type,
    'source_id',j.source_id) order by j.posting_date,j.id,l.id),'[]')
   into actual,source_rows
  from finance.journal_lines l join finance.journal_entries j
   on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and l.account_id=a.id
   and j.status='posted' and j.posting_date between start_date and d
   and (budget.branch_id is null or j.branch_id=budget.branch_id)
   and (budget.currency_code=base_currency or j.currency_code=budget.currency_code);
  planned:=(x->>'amount')::numeric;total_budget:=total_budget+planned;
  total_actual:=total_actual+actual;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',x->>'id','account_id',a.id,
   'code',a.code,'name',a.name,'normal_balance',a.normal_balance,
   'budget_amount',planned::text,'actual_amount',actual::text,
   'variance',(actual-planned)::text,
   'variance_percent',case when planned=0 then null else round((actual-planned)*100/planned,6)::text end,
   'source_count',jsonb_array_length(source_rows)));
  journals:=journals||source_rows;
  if jsonb_array_length(journals)>10000 then
   raise exception using errcode='54000',message='BUDGET_VARIANCE_SOURCE_LIMIT';end if;
 end loop;
 source_count:=jsonb_array_length(journals);
 summary:=jsonb_build_object('id',report_id,'tenant_id',t,'legal_entity_id',e,
  'branch_id',b,'budget_id',budget_id,'budget_root_id',budget.root_id,
  'budget_revision',budget.revision,'period_id',budget.period_id,
  'budget_year',budget.budget_year,'budget_branch_id',budget.branch_id,
  'as_of',d,'period_start',start_date,'period_end',end_date,
  'currency_code',budget.currency_code,'base_currency_code',base_currency,
  'currency_basis',case when budget.currency_code=base_currency then 'base_all_posted'
   else 'matching_transaction_only' end,'generated_at',now(),
  'status','generated','version',1,'line_count',jsonb_array_length(rows),
  'journal_count',source_count,'budget_total',total_budget::text,
  'actual_total',total_actual::text,'variance_total',(total_actual-total_budget)::text,
  'variance_percent',case when total_budget=0 then null
   else round((total_actual-total_budget)*100/total_budget,6)::text end);
 result:=jsonb_build_object('summary',summary,'lines',rows,'journals',journals);
 if octet_length(result::text)>16777216 then
  raise exception using errcode='54000',message='BUDGET_VARIANCE_EVIDENCE_LIMIT';end if;
 return result;
end$$;

create function api.generate_budget_variance(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare id uuid:=(p_payload->>'id')::uuid;h text;r jsonb;data jsonb;
 summary jsonb;req uuid:=gen_random_uuid();begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if id is null or p_client_timestamp is null then
  raise exception using errcode='22023',message='BUDGET_VARIANCE_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('finance.budgets.variance.generate',p_command_id,p_tenant_id,
  p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.budgets.variance.generate',p_command_id,p_idempotency_key,h);
 if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 data:=finance.build_budget_variance(p_tenant_id,p_legal_entity_id,p_branch_id,
  (p_payload->>'budget_id')::uuid,(p_payload->>'as_of')::date,id);
 summary:=data->'summary';
 insert into finance.budget_variance_reports(id,tenant_id,legal_entity_id,requested_branch_id,
  budget_id,as_of,generated_at,summary,evidence,created_by)
 values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(p_payload->>'budget_id')::uuid,
  (p_payload->>'as_of')::date,(summary->>'generated_at')::timestamptz,summary,data,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'finance.budgets.variance.generate',p_command_id,
  'budget_variance_report',id,p_idempotency_key,h,null,summary,p_legal_entity_id,p_branch_id,
  jsonb_build_object('budget_id',p_payload->>'budget_id','as_of',p_payload->>'as_of'),
  jsonb_build_object('to_status','generated'),
  jsonb_build_array(jsonb_build_object('topic','finance.budgets.variance.generated','payload',summary)),
  '[]',req,req);
end$$;

create function api.budget_variance_reports(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(summary order by id),'[]') into rows from (
  select id,summary from finance.budget_variance_reports where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and requested_branch_id=p_branch_id
   and (p_after is null or id>p_after)
  order by id limit 51)q;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'items',rows,'next_cursor',cursor);
end$$;

create function api.budget_variance_page(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_report_id uuid,p_section text,p_offset integer default 0,
 p_budget_line_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare report finance.budget_variance_reports%rowtype;rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_section not in('lines','journals') or p_section is null or p_offset is null
  or p_offset<0 or p_offset>10000 then
  raise exception using errcode='22023',message='BUDGET_VARIANCE_PAGE_INVALID';end if;
 select * into report from finance.budget_variance_reports where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and requested_branch_id=p_branch_id
  and id=p_report_id;
 if not found then raise exception using errcode='42501',message='BUDGET_REPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(value order by ord),'[]') into rows from (
  select value,ord from jsonb_array_elements(report.evidence->p_section) with ordinality x(value,ord)
  where p_budget_line_id is null or
   (p_section='lines' and value->>'id'=p_budget_line_id::text) or
   (p_section='journals' and value->>'budget_line_id'=p_budget_line_id::text)
  order by ord offset p_offset limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('summary',report.summary,'section',p_section,
  'budget_line_id',p_budget_line_id,'items',rows,
  'next_offset',case when n>50 then p_offset+50 end);
end$$;

revoke all on function finance.guard_budget_mutation(),finance.validate_budget_lines(uuid,uuid,jsonb),
 finance.build_budget_variance(uuid,uuid,uuid,uuid,date,uuid),
 api.budget_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.budget_options(uuid,uuid,uuid,uuid),
 api.generate_budget_variance(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.budget_variance_reports(uuid,uuid,uuid,uuid),
 api.budget_variance_page(uuid,uuid,uuid,uuid,text,integer,uuid)
 from public,anon,authenticated;
grant execute on function api.budget_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.budget_options(uuid,uuid,uuid,uuid),
 api.generate_budget_variance(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.budget_variance_reports(uuid,uuid,uuid,uuid),
 api.budget_variance_page(uuid,uuid,uuid,uuid,text,integer,uuid)
 to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED AC-320 tax summary candidate. Exercise only inside ROLLBACK.
-- Existing posted bills without a versioned tax snapshot remain review blockers.
create table finance.tax_definition_versions (
 tenant_id uuid not null,legal_entity_id uuid not null,definition_id uuid not null,
 version bigint not null,code text not null,name text not null,kind text not null,
 rate numeric(12,6) not null,inclusive boolean not null,recoverable boolean not null,
 valid_from date not null,valid_to date,status text not null,captured_at timestamptz not null default clock_timestamp(),
 primary key(tenant_id,legal_entity_id,definition_id,version)
);
alter table finance.tax_definition_versions enable row level security;
alter table finance.tax_definition_versions force row level security;
revoke all on finance.tax_definition_versions from public,anon,authenticated;
create trigger immutable before update or delete on finance.tax_definition_versions
 for each row execute function workflow.reject_history_mutation();

create function finance.capture_tax_definition_version() returns trigger
language plpgsql security definer set search_path='' as $$begin
 insert into finance.tax_definition_versions(tenant_id,legal_entity_id,definition_id,version,
 code,name,kind,rate,inclusive,recoverable,valid_from,valid_to,status)
 values(new.tenant_id,new.legal_entity_id,new.id,new.version,new.code,new.name,new.kind,
 new.rate,new.inclusive,new.recoverable,new.valid_from,new.valid_to,new.status);
 return new;
end$$;
revoke all on function finance.capture_tax_definition_version() from public,anon,authenticated;
insert into finance.tax_definition_versions(tenant_id,legal_entity_id,definition_id,version,
 code,name,kind,rate,inclusive,recoverable,valid_from,valid_to,status)
select tenant_id,legal_entity_id,id,version,code,name,kind,rate,inclusive,recoverable,
 valid_from,valid_to,status from finance.tax_definitions;
create trigger tax_definition_version_snapshot after insert or update on finance.tax_definitions
 for each row execute function finance.capture_tax_definition_version();

-- The bill posting command rewrites draft line detail immediately before the
-- journal and status transition. Capture the effective definition on that write.
create function finance.snapshot_bill_tax() returns trigger
language plpgsql security definer set search_path='' as $$
declare d finance.tax_definitions%rowtype;bill procurement.supplier_bills%rowtype;
begin
 if new.detail->>'tax_definition_id' is null then return new;end if;
 select * into bill from procurement.supplier_bills where tenant_id=new.tenant_id and id=new.bill_id;
 select * into d from finance.tax_definitions where tenant_id=new.tenant_id
  and legal_entity_id=new.legal_entity_id and id=(new.detail->>'tax_definition_id')::uuid
  and status='active' and kind in('input','zero','exempt')
  and bill.document_date between valid_from and coalesce(valid_to,'infinity'::date);
 if not found or d.rate is distinct from (new.detail->>'tax_rate')::numeric
  or d.inclusive is distinct from (new.detail->>'tax_inclusive')::boolean then
  raise exception using errcode='55000',message='BILL_TAX_SNAPSHOT_CHANGED';end if;
 new.detail:=new.detail||jsonb_build_object('tax_code',d.code,'tax_name',d.name,
  'tax_kind',d.kind,'tax_definition_version',d.version,'tax_valid_from',d.valid_from,
  'tax_valid_to',d.valid_to,'tax_recoverable',d.recoverable);
 return new;
end$$;
revoke all on function finance.snapshot_bill_tax() from public,anon,authenticated;
create trigger bill_tax_snapshot before insert or update of detail on procurement.supplier_bill_lines
 for each row execute function finance.snapshot_bill_tax();

create table finance.tax_reports(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 requested_branch_id uuid not null,period_id uuid not null,as_of date not null,
 branch_filter_id uuid,generated_at timestamptz not null,summary jsonb not null,evidence jsonb not null,
 created_by uuid not null references auth.users(id),unique(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,requested_branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,branch_filter_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,period_id) references finance.fiscal_periods(tenant_id,legal_entity_id,id),
 check(jsonb_typeof(summary)='object' and jsonb_typeof(evidence)='object'
  and octet_length(evidence::text)<=16777216)
);
create index tax_reports_scope on finance.tax_reports(tenant_id,legal_entity_id,requested_branch_id,id);
create index tax_reports_period on finance.tax_reports(tenant_id,period_id,id);
create index tax_reports_actor on finance.tax_reports(created_by);
alter table finance.tax_reports enable row level security;
alter table finance.tax_reports force row level security;
revoke all on finance.tax_reports from public,anon,authenticated;
create trigger immutable before update or delete on finance.tax_reports
 for each row execute function workflow.reject_history_mutation();

create function finance.build_tax_summary(t uuid,e uuid,b uuid,p jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare period finance.fiscal_periods%rowtype;d date:=(p->>'as_of')::date;
 filter_branch uuid:=(p->>'branch_filter_id')::uuid;scale integer;generated timestamptz:=clock_timestamp();
 r record;definition finance.tax_definition_versions%rowtype;journal_lines jsonb;
 tax_transaction numeric;tax_base numeric;expected_transaction numeric;expected_base numeric;
 taxable_base numeric;output_base numeric:=0;input_base numeric:=0;withholding_base numeric:=0;
 zero_taxable numeric:=0;exempt_taxable numeric:=0;unverified_base numeric:=0;
 line_rows jsonb:='[]';blockers jsonb:='[]';reason text;line_count integer:=0;blocked_count integer:=0;
 summary jsonb;
begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if d is null or d>(clock_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='TAX_REPORT_DATE_INVALID';end if;
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
  and id=(p->>'period_id')::uuid and status='active';
 if not found or d not between period.start_date and period.end_date then
  raise exception using errcode='22023',message='TAX_REPORT_PERIOD_INVALID';end if;
 if filter_branch is not null then
  if not exists(select 1 from core.branches where tenant_id=t and legal_entity_id=e and id=filter_branch) then
   raise exception using errcode='22023',message='TAX_REPORT_BRANCH_INVALID';end if;
  perform core.wave3_require_scope(t,'finance.view',e,filter_branch);
 end if;
 select rounding_scale into scale from core.legal_entities where tenant_id=t and id=e;
 for r in
  select 'sales_invoice'::text source_type,s.id source_line_id,s.document_id source_id,
   s.branch_id,s.snapshot source_snapshot,s.taxable_amount,s.tax_amount,
   j.id journal_id,j.document_number,j.posting_date,j.currency_code,j.base_currency_code,j.exchange_rate
  from sales.sales_invoice_lines s join sales.sales_invoices doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
  left join finance.journal_entries j on j.tenant_id=t and j.legal_entity_id=e and j.source_type='sales_invoice'
   and j.source_id=doc.id and j.status='posted'
  where s.tenant_id=t and s.legal_entity_id=e and doc.status='posted'
   and doc.document_date between period.start_date and d
   and (filter_branch is null or s.branch_id=filter_branch)
   and s.snapshot->>'tax_definition_id' is not null
  union all
  select 'sales_return',s.id,s.document_id,s.branch_id,s.snapshot,s.taxable_amount,s.tax_amount,
   j.id,j.document_number,j.posting_date,j.currency_code,j.base_currency_code,j.exchange_rate
  from sales.sales_return_lines s join sales.sales_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
  left join finance.journal_entries j on j.tenant_id=t and j.legal_entity_id=e and j.source_type='sales_return'
   and j.source_id=doc.id and j.status='posted'
  where s.tenant_id=t and s.legal_entity_id=e and doc.status='posted'
   and doc.document_date between period.start_date and d
   and (filter_branch is null or s.branch_id=filter_branch)
   and s.snapshot->>'tax_definition_id' is not null
  union all
  select 'supplier_bill',l.id,l.bill_id,l.branch_id,l.detail,
   (l.detail->>'net_amount')::numeric,(l.detail->>'tax_amount')::numeric,
   j.id,j.document_number,j.posting_date,j.currency_code,j.base_currency_code,j.exchange_rate
  from procurement.supplier_bill_lines l join procurement.supplier_bills bill on bill.tenant_id=l.tenant_id and bill.id=l.bill_id
  left join finance.journal_entries j on j.tenant_id=t and j.legal_entity_id=e and j.source_type='supplier_bill'
   and j.source_id=bill.id and j.status='posted'
  where l.tenant_id=t and l.legal_entity_id=e and bill.status='posted'
   and bill.document_date between period.start_date and d
   and (filter_branch is null or l.branch_id=filter_branch)
   and l.detail->>'tax_definition_id' is not null
  order by posting_date,source_type,source_id,source_line_id
 loop
  line_count:=line_count+1;
  if line_count>10000 then raise exception using errcode='54000',message='TAX_REPORT_LINE_LIMIT';end if;
  reason:=null;definition:=null;
  if r.source_snapshot->>'tax_definition_version' is null then reason:='MISSING_DEFINITION_VERSION';
  else
   select * into definition from finance.tax_definition_versions where tenant_id=t
    and legal_entity_id=e and definition_id=(r.source_snapshot->>'tax_definition_id')::uuid
    and version=(r.source_snapshot->>'tax_definition_version')::bigint;
   if not found then reason:='DEFINITION_VERSION_UNAVAILABLE';
   elsif r.posting_date not between definition.valid_from and coalesce(definition.valid_to,'infinity'::date)
    or definition.status<>'active' then reason:='DEFINITION_OUTSIDE_POSTING_DATE';
   elsif definition.kind is distinct from r.source_snapshot->>'tax_kind'
    or definition.rate is distinct from (r.source_snapshot->>'tax_rate')::numeric
    or definition.inclusive is distinct from (r.source_snapshot->>'tax_inclusive')::boolean
    or definition.code is distinct from r.source_snapshot->>'tax_code' then
    reason:='DEFINITION_SNAPSHOT_MISMATCH';end if;
  end if;
  select coalesce(sum(case when r.source_type='sales_invoice' then l.transaction_credit-l.transaction_debit
    when r.source_type='sales_return' then l.transaction_debit-l.transaction_credit
    else l.transaction_debit-l.transaction_credit end),0),
   coalesce(sum(case when r.source_type='sales_invoice' then l.base_credit-l.base_debit
    when r.source_type='sales_return' then l.base_debit-l.base_credit
    else l.base_debit-l.base_credit end),0),
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'journal_entry_id',r.journal_id,
    'account_id',l.account_id,'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'base_debit',l.base_debit::text,
    'base_credit',l.base_credit::text) order by l.line_number),'[]'::jsonb)
   into tax_transaction,tax_base,journal_lines
  from finance.journal_lines l join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id
  where l.tenant_id=t and l.journal_entry_id=r.journal_id and l.source_line_id=r.source_line_id
   and a.account_type=case when r.source_type='supplier_bill' then 'asset' else 'liability' end;
  expected_transaction:=r.tax_amount;
  expected_base:=round(expected_transaction*coalesce(r.exchange_rate,0),scale);
  taxable_base:=round(r.taxable_amount*coalesce(r.exchange_rate,0),scale);
  if reason is null and (r.journal_id is null and (r.taxable_amount<>0 or r.tax_amount<>0)) then
   reason:='POSTED_JOURNAL_MISSING';end if;
  if reason is null and (tax_transaction<>expected_transaction or tax_base<>expected_base) then
   reason:='TAX_JOURNAL_MISMATCH';end if;
  if reason is null and definition.kind in('zero','exempt') and r.tax_amount<>0 then
   reason:='ZERO_TAX_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type='supplier_bill' and definition.kind not in('input','zero','exempt') then
   reason:='INPUT_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type<>'supplier_bill' and definition.kind not in('output','zero','exempt') then
   reason:='OUTPUT_TREATMENT_MISMATCH';end if;
  if reason is not null then
   blocked_count:=blocked_count+1;unverified_base:=unverified_base+expected_base;
   if blocked_count<=100 then
    blockers:=blockers||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
     'source_id',r.source_id,'source_line_id',r.source_line_id,'code',reason));end if;
  else
   if definition.kind='output' then output_base:=output_base+case when r.source_type='sales_return' then -tax_base else tax_base end;
   elsif definition.kind='input' then input_base:=input_base+tax_base;
   elsif definition.kind='withholding' then withholding_base:=withholding_base+tax_base;
   elsif definition.kind='zero' then zero_taxable:=zero_taxable+case when r.source_type='sales_return' then -taxable_base else taxable_base end;
   else exempt_taxable:=exempt_taxable+case when r.source_type='sales_return' then -taxable_base else taxable_base end;end if;
  end if;
  line_rows:=line_rows||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
   'source_id',r.source_id,'source_line_id',r.source_line_id,'branch_id',r.branch_id,
   'journal_entry_id',r.journal_id,'document_number',r.document_number,
   'posting_date',r.posting_date,'currency_code',r.currency_code,
   'base_currency_code',r.base_currency_code,'definition_id',r.source_snapshot->>'tax_definition_id',
   'definition_version',r.source_snapshot->>'tax_definition_version',
   'tax_code',r.source_snapshot->>'tax_code','tax_kind',r.source_snapshot->>'tax_kind',
   'tax_rate',r.source_snapshot->>'tax_rate','taxable_amount',r.taxable_amount::numeric(20,6)::text,
   'tax_amount',r.tax_amount::numeric(20,6)::text,'taxable_base',taxable_base::numeric(20,6)::text,
   'tax_base',tax_base::numeric(20,6)::text,'expected_tax_base',expected_base::numeric(20,6)::text,
   'review_code',reason,'journal_lines',journal_lines));
 end loop;
 summary:=jsonb_build_object('id',p->>'id','tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'period_id',period.id,'period_start',period.start_date,'period_end',period.end_date,
  'as_of',d,'branch_filter_id',filter_branch,'base_currency_code',
  (select currency_code from core.legal_entities where id=e),
  'generated_at',generated,'status',case when blocked_count>0 then 'blocked' else 'generated' end,
  'notice','NON-CERTIFIED • STATUTORY REVIEW REQUIRED',
  'line_count',line_count,'blocked_count',blocked_count,'blockers',blockers,
  'output_tax_base',output_base::numeric(20,6)::text,
  'input_tax_base',input_base::numeric(20,6)::text,
  'withholding_tax_base',withholding_base::numeric(20,6)::text,
  'zero_taxable_base',zero_taxable::numeric(20,6)::text,
  'exempt_taxable_base',exempt_taxable::numeric(20,6)::text,
  'unverified_tax_base',unverified_base::numeric(20,6)::text);
 return jsonb_build_object('summary',summary,'lines',line_rows);
end$$;
revoke all on function finance.build_tax_summary(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create function api.generate_tax_summary(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,
 p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare id uuid:=(p_payload->>'id')::uuid;h text;r jsonb;data jsonb;summary jsonb;req uuid:=gen_random_uuid();
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if id is null or p_client_timestamp is null then raise exception using errcode='22023',message='TAX_REPORT_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('finance.tax_summary.generate',p_command_id,p_tenant_id,
  p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.tax_summary.generate',p_command_id,p_idempotency_key,h);
 if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 data:=finance.build_tax_summary(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 summary:=data->'summary';
 insert into finance.tax_reports values(id,p_tenant_id,p_legal_entity_id,p_branch_id,
  (summary->>'period_id')::uuid,(summary->>'as_of')::date,
  (summary->>'branch_filter_id')::uuid,(summary->>'generated_at')::timestamptz,
  summary,data,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'finance.tax_summary.generate',p_command_id,
  'tax_summary_report',id,p_idempotency_key,h,null,summary,p_legal_entity_id,p_branch_id,
  '{}',jsonb_build_object('to_status',summary->>'status'),
  jsonb_build_array(jsonb_build_object('topic','finance.tax_summary.generated','payload',summary)),
  '[]',req,req);
end$$;

create function api.tax_summary_reports(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_after uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(summary order by id),'[]') into rows from (
  select id,summary from finance.tax_reports where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and requested_branch_id=p_branch_id
   and (p_after is null or id>p_after) order by id limit 51)q;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'items',rows,'next_cursor',cursor);
end$$;

create function api.tax_summary_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_report_id uuid,p_offset integer default 0,p_source_line_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare report finance.tax_reports%rowtype;rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_offset is null or p_offset<0 or p_offset>10000 then
  raise exception using errcode='22023',message='TAX_REPORT_PAGE_INVALID';end if;
 select * into report from finance.tax_reports where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and requested_branch_id=p_branch_id and id=p_report_id;
 if not found then raise exception using errcode='42501',message='TAX_REPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(value order by ord),'[]') into rows from (
  select value,ord from jsonb_array_elements(report.evidence->'lines') with ordinality x(value,ord)
  where p_source_line_id is null or value->>'source_line_id'=p_source_line_id::text
  order by ord offset p_offset limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('summary',report.summary,'items',rows,
  'next_offset',case when n>50 then p_offset+50 end);
end$$;

revoke all on function api.generate_tax_summary(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.tax_summary_reports(uuid,uuid,uuid,uuid),
 api.tax_summary_page(uuid,uuid,uuid,uuid,integer,uuid) from public,anon,authenticated;
grant execute on function api.generate_tax_summary(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.tax_summary_reports(uuid,uuid,uuid,uuid),
 api.tax_summary_page(uuid,uuid,uuid,uuid,integer,uuid) to authenticated;

-- Additive correction after the committed tax-summary candidate.
-- Preserve its original migration hash and install both candidates in order.
create or replace function finance.build_tax_summary(t uuid,e uuid,b uuid,p jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare period finance.fiscal_periods%rowtype;d date:=(p->>'as_of')::date;
 filter_branch uuid:=(p->>'branch_filter_id')::uuid;scale integer;generated timestamptz:=clock_timestamp();
 r record;definition finance.tax_definition_versions%rowtype;journal_lines jsonb;
 tax_transaction numeric;tax_base numeric;expected_transaction numeric;expected_base numeric;
 taxable_base numeric;output_base numeric:=0;input_base numeric:=0;withholding_base numeric:=0;
 zero_taxable numeric:=0;exempt_taxable numeric:=0;unverified_base numeric:=0;
 line_rows jsonb:='[]';blockers jsonb:='[]';reason text;line_count integer:=0;blocked_count integer:=0;
 summary jsonb;
begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if d is null or d>(clock_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='TAX_REPORT_DATE_INVALID';end if;
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
  and id=(p->>'period_id')::uuid and status='active';
 if not found or d not between period.start_date and period.end_date then
  raise exception using errcode='22023',message='TAX_REPORT_PERIOD_INVALID';end if;
 if filter_branch is not null then
  if filter_branch<>b or not exists(select 1 from core.branches
   where tenant_id=t and legal_entity_id=e and id=filter_branch) then
   raise exception using errcode='22023',message='TAX_REPORT_BRANCH_INVALID';end if;
  perform core.wave3_require_scope(t,'finance.view',e,filter_branch);
 end if;
 select rounding_scale into scale from core.legal_entities where tenant_id=t and id=e;
 for r in
  select 'sales_invoice'::text source_type,s.id source_line_id,s.document_id source_id,
   s.branch_id,s.snapshot source_snapshot,s.taxable_amount,s.tax_amount,
   j.id journal_id,j.document_number,coalesce(j.posting_date,doc.document_date) posting_date,
   coalesce(j.currency_code,doc.currency_code) currency_code,
   coalesce(j.base_currency_code,doc.base_currency_code) base_currency_code,
   coalesce(j.exchange_rate,doc.exchange_rate) exchange_rate
  from sales.sales_invoice_lines s join sales.sales_invoices doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
  left join finance.journal_entries j on j.tenant_id=t and j.legal_entity_id=e and j.source_type='sales_invoice'
   and j.source_id=doc.id and j.status='posted'
  where s.tenant_id=t and s.legal_entity_id=e and doc.status='posted'
   and doc.document_date between period.start_date and d
   and (filter_branch is null or s.branch_id=filter_branch)
   and s.snapshot->>'tax_definition_id' is not null
  union all
  select 'sales_return',s.id,s.document_id,s.branch_id,s.snapshot,s.taxable_amount,s.tax_amount,
   j.id,j.document_number,coalesce(j.posting_date,doc.document_date),
   coalesce(j.currency_code,doc.currency_code),coalesce(j.base_currency_code,doc.base_currency_code),
   coalesce(j.exchange_rate,doc.exchange_rate)
  from sales.sales_return_lines s join sales.sales_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
  left join finance.journal_entries j on j.tenant_id=t and j.legal_entity_id=e and j.source_type='sales_return'
   and j.source_id=doc.id and j.status='posted'
  where s.tenant_id=t and s.legal_entity_id=e and doc.status='posted'
   and doc.document_date between period.start_date and d
   and (filter_branch is null or s.branch_id=filter_branch)
   and s.snapshot->>'tax_definition_id' is not null
  union all
  select 'supplier_bill',l.id,l.bill_id,l.branch_id,l.detail,
   (l.detail->>'net_amount')::numeric,(l.detail->>'tax_amount')::numeric,
   j.id,j.document_number,coalesce(j.posting_date,bill.document_date),
   coalesce(j.currency_code,bill.currency_code),coalesce(j.base_currency_code,bill.base_currency_code),
   coalesce(j.exchange_rate,bill.exchange_rate)
  from procurement.supplier_bill_lines l join procurement.supplier_bills bill on bill.tenant_id=l.tenant_id and bill.id=l.bill_id
  left join finance.journal_entries j on j.tenant_id=t and j.legal_entity_id=e and j.source_type='supplier_bill'
   and j.source_id=bill.id and j.status='posted'
  where l.tenant_id=t and l.legal_entity_id=e and bill.status='posted'
   and bill.document_date between period.start_date and d
   and (filter_branch is null or l.branch_id=filter_branch)
   and l.detail->>'tax_definition_id' is not null
  order by posting_date,source_type,source_id,source_line_id
 loop
  line_count:=line_count+1;
  if line_count>10000 then raise exception using errcode='54000',message='TAX_REPORT_LINE_LIMIT';end if;
  reason:=null;definition:=null;
  if r.source_snapshot->>'tax_definition_version' is null then reason:='MISSING_DEFINITION_VERSION';
  else
   select * into definition from finance.tax_definition_versions where tenant_id=t
    and legal_entity_id=e and definition_id=(r.source_snapshot->>'tax_definition_id')::uuid
    and version=(r.source_snapshot->>'tax_definition_version')::bigint;
   if not found then reason:='DEFINITION_VERSION_UNAVAILABLE';
   elsif r.posting_date not between definition.valid_from and coalesce(definition.valid_to,'infinity'::date)
    or definition.status<>'active' then reason:='DEFINITION_OUTSIDE_POSTING_DATE';
   elsif definition.kind is distinct from r.source_snapshot->>'tax_kind'
    or definition.rate is distinct from (r.source_snapshot->>'tax_rate')::numeric
    or definition.inclusive is distinct from (r.source_snapshot->>'tax_inclusive')::boolean
    or definition.code is distinct from r.source_snapshot->>'tax_code' then
    reason:='DEFINITION_SNAPSHOT_MISMATCH';end if;
  end if;
  select coalesce(sum(case when r.source_type='sales_invoice' then l.transaction_credit-l.transaction_debit
    when r.source_type='sales_return' then l.transaction_debit-l.transaction_credit
    else l.transaction_debit-l.transaction_credit end),0),
   coalesce(sum(case when r.source_type='sales_invoice' then l.base_credit-l.base_debit
    when r.source_type='sales_return' then l.base_debit-l.base_credit
    else l.base_debit-l.base_credit end),0),
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'journal_entry_id',r.journal_id,
    'account_id',l.account_id,'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'base_debit',l.base_debit::text,
    'base_credit',l.base_credit::text) order by l.line_number),'[]'::jsonb)
   into tax_transaction,tax_base,journal_lines
  from finance.journal_lines l join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id
  where l.tenant_id=t and l.journal_entry_id=r.journal_id and l.source_line_id=r.source_line_id
   and a.account_type=case when r.source_type='supplier_bill' then 'asset' else 'liability' end;
  expected_transaction:=r.tax_amount;
  expected_base:=round(expected_transaction*coalesce(r.exchange_rate,0),scale);
  taxable_base:=round(r.taxable_amount*coalesce(r.exchange_rate,0),scale);
  if reason is null and (r.journal_id is null and (r.taxable_amount<>0 or r.tax_amount<>0)) then
   reason:='POSTED_JOURNAL_MISSING';end if;
  if reason is null and (tax_transaction<>expected_transaction or tax_base<>expected_base) then
   reason:='TAX_JOURNAL_MISMATCH';end if;
  if reason is null and definition.kind in('zero','exempt') and r.tax_amount<>0 then
   reason:='ZERO_TAX_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type='supplier_bill' and definition.kind not in('input','zero','exempt') then
   reason:='INPUT_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type<>'supplier_bill' and definition.kind not in('output','zero','exempt') then
   reason:='OUTPUT_TREATMENT_MISMATCH';end if;
  if reason is not null then
   blocked_count:=blocked_count+1;unverified_base:=unverified_base+expected_base;
   if blocked_count<=100 then
    blockers:=blockers||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
     'source_id',r.source_id,'source_line_id',r.source_line_id,'code',reason));end if;
  else
   if definition.kind='output' then output_base:=output_base+case when r.source_type='sales_return' then -tax_base else tax_base end;
   elsif definition.kind='input' then input_base:=input_base+tax_base;
   elsif definition.kind='withholding' then withholding_base:=withholding_base+tax_base;
   elsif definition.kind='zero' then zero_taxable:=zero_taxable+case when r.source_type='sales_return' then -taxable_base else taxable_base end;
   else exempt_taxable:=exempt_taxable+case when r.source_type='sales_return' then -taxable_base else taxable_base end;end if;
  end if;
  line_rows:=line_rows||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
   'source_id',r.source_id,'source_line_id',r.source_line_id,'branch_id',r.branch_id,
   'journal_entry_id',r.journal_id,'document_number',r.document_number,
   'posting_date',r.posting_date,'currency_code',r.currency_code,
   'base_currency_code',r.base_currency_code,'definition_id',r.source_snapshot->>'tax_definition_id',
   'definition_version',r.source_snapshot->>'tax_definition_version',
   'tax_code',r.source_snapshot->>'tax_code','tax_kind',r.source_snapshot->>'tax_kind',
   'tax_rate',r.source_snapshot->>'tax_rate','taxable_amount',r.taxable_amount::numeric(20,6)::text,
   'tax_amount',r.tax_amount::numeric(20,6)::text,'taxable_base',taxable_base::numeric(20,6)::text,
   'tax_base',tax_base::numeric(20,6)::text,'expected_tax_base',expected_base::numeric(20,6)::text,
   'review_code',reason,'journal_lines',journal_lines));
 end loop;
 summary:=jsonb_build_object('id',p->>'id','tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'version',1,
  'period_id',period.id,'period_start',period.start_date,'period_end',period.end_date,
  'as_of',d,'branch_filter_id',filter_branch,'base_currency_code',
  (select currency_code from core.legal_entities where id=e),
  'generated_at',generated,'status',case when blocked_count>0 then 'blocked' else 'generated' end,
  'notice','NON-CERTIFIED • STATUTORY REVIEW REQUIRED',
  'line_count',line_count,'blocked_count',blocked_count,'blockers',blockers,
  'output_tax_base',output_base::numeric(20,6)::text,
  'input_tax_base',input_base::numeric(20,6)::text,
  'withholding_tax_base',withholding_base::numeric(20,6)::text,
  'zero_taxable_base',zero_taxable::numeric(20,6)::text,
  'exempt_taxable_base',exempt_taxable::numeric(20,6)::text,
  'unverified_tax_base',unverified_base::numeric(20,6)::text);
 return jsonb_build_object('summary',summary,'lines',line_rows);
end$$;
revoke all on function finance.build_tax_summary(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

-- UNAPPLIED additive AC-320 candidate. All tests must end in ROLLBACK.
-- Source treatment remains immutable; journal and open-item engines are unchanged.
create function finance.snapshot_purchase_return_tax() returns trigger
language plpgsql security definer set search_path='' as $$
declare source procurement.supplier_bill_lines%rowtype;bill procurement.supplier_bills%rowtype;
 prior numeric;original_base numeric;expected_amount numeric;expected_base numeric;scale integer;
begin
 if new.bill_line_id is null then return new;end if;
 select * into source from procurement.supplier_bill_lines where tenant_id=new.tenant_id and id=new.bill_line_id;
 if source.detail->>'tax_definition_id' is null then return new;end if;
 select * into bill from procurement.supplier_bills where tenant_id=new.tenant_id and id=source.bill_id and status='posted';
 if bill.id is null or new.detail->'source_snapshot' is distinct from source.detail then
  raise exception using errcode='55000',message='RETURN_TAX_SOURCE_CHANGED';end if;
 select rounding_scale into scale from core.legal_entities where tenant_id=new.tenant_id and id=new.legal_entity_id;
 select coalesce(sum(quantity),0) into prior from procurement.purchase_return_lines
  where tenant_id=new.tenant_id and bill_line_id=source.id;
 select coalesce(sum(l.base_debit-l.base_credit),0) into original_base from finance.journal_lines l
  join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id
  where l.tenant_id=new.tenant_id and l.journal_entry_id=bill.journal_entry_id
   and l.source_line_id=source.id and a.account_type='asset';
 expected_amount:=round((source.detail->>'tax_amount')::numeric*(prior+new.quantity)/source.quantity,scale)
  -round((source.detail->>'tax_amount')::numeric*prior/source.quantity,scale);
 expected_base:=round(original_base*(prior+new.quantity)/source.quantity,scale)
  -round(original_base*prior/source.quantity,scale);
 if expected_amount is distinct from (new.detail->>'tax_amount')::numeric then
  raise exception using errcode='55000',message='RETURN_TAX_AMOUNT_CHANGED';end if;
 new.detail:=new.detail||jsonb_build_object('tax_basis_date',bill.document_date,
  'expected_tax_base',expected_base::numeric(20,6)::text,'source_tax_journal_id',bill.journal_entry_id);
 return new;
end$$;
revoke all on function finance.snapshot_purchase_return_tax() from public,anon,authenticated;
create trigger purchase_return_tax_snapshot before insert on procurement.purchase_return_lines
 for each row execute function finance.snapshot_purchase_return_tax();

create function finance.tax_posted_sources(t uuid,e uuid,d date)
returns table(source_type text,source_id uuid,source_line_id uuid,branch_id uuid,
 posting_date date,tax_basis_date date,currency_code text,base_currency_code text,
 exchange_rate numeric,source_snapshot jsonb,taxable_amount numeric,tax_amount numeric,
 expected_tax_base numeric,expected_base_verified boolean,journal_entry_id uuid,document_number text)
language sql stable security definer set search_path='' as $$
 select 'sales_invoice',doc.id,s.id,s.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.snapshot,s.taxable_amount,s.tax_amount,
  round(s.tax_amount*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from sales.sales_invoice_lines s join sales.sales_invoices doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='sales_invoice' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.snapshot->>'tax_definition_id' is not null or s.tax_amount<>0)
 union all
 select 'sales_return',doc.id,s.id,s.branch_id,doc.document_date,invoice.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.snapshot,s.taxable_amount,s.tax_amount,
  round(s.tax_amount*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from sales.sales_return_lines s join sales.sales_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join sales.sales_invoice_lines original on original.tenant_id=s.tenant_id and original.id=s.sales_invoice_line_id
 left join sales.sales_invoices invoice on invoice.tenant_id=original.tenant_id and invoice.id=original.document_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='sales_return' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.snapshot->>'tax_definition_id' is not null or s.tax_amount<>0)
 union all
 select 'supplier_bill',doc.id,s.id,s.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.detail,
  (s.detail->>'net_amount')::numeric,(s.detail->>'tax_amount')::numeric,
  round((s.detail->>'tax_amount')::numeric*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from procurement.supplier_bill_lines s join procurement.supplier_bills doc on doc.tenant_id=s.tenant_id and doc.id=s.bill_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='supplier_bill' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.detail->>'tax_definition_id' is not null or (s.detail->>'tax_amount')::numeric<>0)
 union all
 select 'purchase_return',doc.id,s.id,s.branch_id,doc.document_date,
  coalesce((s.detail->>'tax_basis_date')::date,bill.document_date),
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.detail->'source_snapshot',
  (s.detail->>'net_amount')::numeric,(s.detail->>'tax_amount')::numeric,
  coalesce((s.detail->>'expected_tax_base')::numeric,
   round((s.detail->>'tax_amount')::numeric*doc.exchange_rate,entity.rounding_scale)),
  s.detail->>'expected_tax_base' is not null or (s.detail->>'tax_amount')::numeric=0,j.id,doc.document_number
 from procurement.purchase_return_lines s join procurement.purchase_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.return_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join procurement.supplier_bill_lines original on original.tenant_id=s.tenant_id and original.id=s.bill_line_id
 left join procurement.supplier_bills bill on bill.tenant_id=original.tenant_id and bill.id=original.bill_id
 left join finance.journal_entries j on j.tenant_id=t and j.id=doc.journal_entry_id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.document_date<=d
  and (s.detail#>>'{source_snapshot,tax_definition_id}' is not null or (s.detail->>'tax_amount')::numeric<>0)
$$;
revoke all on function finance.tax_posted_sources(uuid,uuid,date) from public,anon,authenticated;

create or replace function finance.build_tax_summary(t uuid,e uuid,b uuid,p jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare period finance.fiscal_periods%rowtype;d date:=(p->>'as_of')::date;
 filter_branch uuid:=(p->>'branch_filter_id')::uuid;scale integer;r record;
 definition finance.tax_definition_versions%rowtype;journal_lines jsonb;
 line_rows jsonb:='[]';sources jsonb:='[]';journals jsonb;controls jsonb;diffs jsonb;
 blockers jsonb:='[]';reason text;control_reason text;account uuid;account_count integer;ids uuid[];
 tax_transaction numeric;tax_base numeric;taxable_base numeric;direction integer;
 output_base numeric:=0;input_base numeric:=0;zero_base numeric:=0;exempt_base numeric:=0;unverified numeric:=0;
 line_count integer:=0;blocked_count integer:=0;source_count integer:=0;unassigned integer;unattributed integer;reviews integer;
 source_total numeric;gl_total numeric;summary jsonb;result jsonb;
begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if d is null or d>(statement_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='TAX_REPORT_DATE_INVALID';end if;
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
  and id=(p->>'period_id')::uuid and status='active';
 if not found or d not between period.start_date and period.end_date then
  raise exception using errcode='22023',message='TAX_REPORT_PERIOD_INVALID';end if;
 if filter_branch is not null and (filter_branch<>b or not exists(select 1 from core.branches
  where tenant_id=t and legal_entity_id=e and id=filter_branch)) then
  raise exception using errcode='22023',message='TAX_REPORT_BRANCH_INVALID';end if;
 select rounding_scale into scale from core.legal_entities where tenant_id=t and id=e;
 for r in select * from finance.tax_posted_sources(t,e,d)
  where filter_branch is null or branch_id=filter_branch order by posting_date,source_type,source_line_id loop
  source_count:=source_count+1;
  if source_count>10000 then raise exception using errcode='54000',message='TAX_REPORT_LINE_LIMIT';end if;
  direction:=case when r.source_type in('sales_invoice','purchase_return') then -1 else 1 end;
  select coalesce(sum(direction*(l.transaction_debit-l.transaction_credit)),0),
   coalesce(sum(direction*(l.base_debit-l.base_credit)),0),count(distinct l.account_id),
   (array_agg(l.account_id order by l.line_number))[1],
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'journal_entry_id',r.journal_entry_id,
    'account_id',l.account_id,'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'base_debit',l.base_debit::text,
    'base_credit',l.base_credit::text) order by l.line_number),'[]')
   into tax_transaction,tax_base,account_count,account,journal_lines
  from finance.journal_lines l join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id
  where l.tenant_id=t and l.journal_entry_id=r.journal_entry_id and l.source_line_id=r.source_line_id
   and a.account_type=case when r.source_type in('supplier_bill','purchase_return') then 'asset' else 'liability' end;
  if account_count<>1 then account:=null;end if;
  control_reason:=case when not r.expected_base_verified then 'RETURN_TAX_BASE_UNVERIFIED'
   when r.tax_amount<>0 and account is null then 'TAX_CONTROL_ACCOUNT_UNPROVEN'
   when tax_transaction<>r.tax_amount or tax_base<>r.expected_tax_base then 'TAX_CONTROL_JOURNAL_MISMATCH' end;
  if r.tax_amount<>0 or tax_base<>0 then
   sources:=sources||jsonb_build_array(jsonb_build_object('id',r.source_line_id,
    'evidence_key',r.source_type||':'||r.source_id||':'||r.source_line_id,
    'source_type',r.source_type,'source_id',r.source_id,'source_line_id',r.source_line_id,
    'journal_entry_id',r.journal_entry_id,'document_number',r.document_number,'branch_id',r.branch_id,
    'posting_date',r.posting_date,'phase',case when r.posting_date<period.start_date then 'opening' else 'period' end,
    'account_id',account,'currency_code',r.currency_code,'base_currency_code',r.base_currency_code,
    'expected_base',(direction*r.expected_tax_base)::numeric(20,6)::text,
    'posted_base',(direction*tax_base)::numeric(20,6)::text,'review_code',control_reason));
  end if;
  if r.posting_date<period.start_date then continue;end if;
  line_count:=line_count+1;reason:=null;definition:=null;
  if r.source_snapshot->>'tax_definition_version' is null then reason:='MISSING_DEFINITION_VERSION';
  else
   select * into definition from finance.tax_definition_versions where tenant_id=t and legal_entity_id=e
    and definition_id=(r.source_snapshot->>'tax_definition_id')::uuid
    and version=(r.source_snapshot->>'tax_definition_version')::bigint;
   if not found then reason:='DEFINITION_VERSION_UNAVAILABLE';
   elsif r.tax_basis_date is null then reason:='SOURCE_TAX_DATE_UNAVAILABLE';
   elsif r.tax_basis_date not between definition.valid_from and coalesce(definition.valid_to,'infinity'::date)
    or definition.status<>'active' then reason:='DEFINITION_OUTSIDE_SOURCE_DATE';
   elsif definition.kind is distinct from r.source_snapshot->>'tax_kind'
    or definition.rate is distinct from (r.source_snapshot->>'tax_rate')::numeric
    or definition.inclusive is distinct from (r.source_snapshot->>'tax_inclusive')::boolean
    or definition.code is distinct from r.source_snapshot->>'tax_code' then reason:='DEFINITION_SNAPSHOT_MISMATCH';end if;
  end if;
  if reason is null and r.journal_entry_id is null and (r.taxable_amount<>0 or r.tax_amount<>0) then
   reason:='POSTED_JOURNAL_MISSING';end if;
  if reason is null then reason:=control_reason;end if;
  if reason is null and definition.kind in('zero','exempt') and r.tax_amount<>0 then reason:='ZERO_TAX_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type in('supplier_bill','purchase_return') and definition.kind not in('input','zero','exempt') then
   reason:='INPUT_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type in('sales_invoice','sales_return') and definition.kind not in('output','zero','exempt') then
   reason:='OUTPUT_TREATMENT_MISMATCH';end if;
  taxable_base:=round(r.taxable_amount*r.exchange_rate,scale);
  if reason is not null then
   blocked_count:=blocked_count+1;unverified:=unverified+abs(r.expected_tax_base);
   if blocked_count<=100 then blockers:=blockers||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
    'source_id',r.source_id,'source_line_id',r.source_line_id,'code',reason));end if;
  elsif definition.kind='output' then output_base:=output_base+case when r.source_type='sales_return' then -tax_base else tax_base end;
  elsif definition.kind='input' then input_base:=input_base+case when r.source_type='purchase_return' then -tax_base else tax_base end;
  elsif definition.kind='zero' then zero_base:=zero_base+case when r.source_type in('sales_return','purchase_return') then -taxable_base else taxable_base end;
  else exempt_base:=exempt_base+case when r.source_type in('sales_return','purchase_return') then -taxable_base else taxable_base end;end if;
  line_rows:=line_rows||jsonb_build_array(jsonb_build_object('source_type',r.source_type,'source_id',r.source_id,
   'source_line_id',r.source_line_id,'branch_id',r.branch_id,'journal_entry_id',r.journal_entry_id,
   'document_number',r.document_number,'posting_date',r.posting_date,'tax_basis_date',r.tax_basis_date,
   'currency_code',r.currency_code,'base_currency_code',r.base_currency_code,
   'definition_id',r.source_snapshot->>'tax_definition_id','definition_version',r.source_snapshot->>'tax_definition_version',
   'tax_code',r.source_snapshot->>'tax_code','tax_kind',r.source_snapshot->>'tax_kind','tax_rate',r.source_snapshot->>'tax_rate',
   'taxable_amount',r.taxable_amount::numeric(20,6)::text,'tax_amount',r.tax_amount::numeric(20,6)::text,
   'taxable_base',taxable_base::numeric(20,6)::text,'tax_base',tax_base::numeric(20,6)::text,
   'expected_tax_base',r.expected_tax_base::numeric(20,6)::text,'review_code',reason,'journal_lines',journal_lines));
 end loop;
 select coalesce(array_agg(distinct id),'{}') into ids from (
  select (x->>'account_id')::uuid id from jsonb_array_elements(sources)x where x->>'account_id' is not null
  union select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='output_tax'
  union select input_tax_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e
  union select (snapshot->>'input_tax_account_id')::uuid from procurement.supplier_bill_control_history
   where tenant_id=t and legal_entity_id=e and snapshot->>'input_tax_account_id' is not null
 ) all_accounts;
 if cardinality(ids)>50 then raise exception using errcode='54000',message='TAX_CONTROL_ACCOUNT_LIMIT';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id,j.id journal_entry_id,j.command_id,j.source_type,j.source_id,l.source_line_id,
   j.document_number,l.branch_id,l.posting_date,l.currency_code,j.base_currency_code,
   j.source_type||':'||j.source_id||':'||coalesce(l.source_line_id::text,'journal-'||l.id) evidence_key,
   case when l.posting_date<period.start_date then 'opening' else 'period' end phase,
   l.transaction_debit::text,l.transaction_credit::text,l.base_debit::text,l.base_credit::text,
   (l.base_debit-l.base_credit)::numeric(20,6)::text posted_base
  from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date<=d and l.account_id=any(ids)
   and (filter_branch is null or l.branch_id=filter_branch) order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='TAX_CONTROL_JOURNAL_LIMIT';end if;
 with entries as (
  select (x->>'account_id')::uuid id,(x->>'expected_base')::numeric v,0::numeric g,x->>'phase' phase
   from jsonb_array_elements(sources)x where x->>'account_id' is not null
  union all select (x->>'account_id')::uuid,0,(x->>'posted_base')::numeric,x->>'phase' from jsonb_array_elements(journals)x),
 totals as(select id,coalesce(sum(v) filter(where phase='opening'),0) so,coalesce(sum(g) filter(where phase='opening'),0) go,
  coalesce(sum(v) filter(where phase='period'),0) sp,coalesce(sum(g) filter(where phase='period'),0) gp from entries group by id)
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'account_id',a.id,'code',a.code,'name',a.name,'account_type',a.account_type,
  'source_opening_base',coalesce(so,0)::numeric(20,6)::text,'gl_opening_base',coalesce(go,0)::numeric(20,6)::text,
  'source_period_base',coalesce(sp,0)::numeric(20,6)::text,'gl_period_base',coalesce(gp,0)::numeric(20,6)::text,
  'source_closing_base',(coalesce(so,0)+coalesce(sp,0))::numeric(20,6)::text,
  'gl_closing_base',(coalesce(go,0)+coalesce(gp,0))::numeric(20,6)::text,
  'difference',(coalesce(so,0)+coalesce(sp,0)-coalesce(go,0)-coalesce(gp,0))::numeric(20,6)::text) order by a.id),'[]') into controls
 from finance.accounts a left join totals using(id) where a.tenant_id=t and a.legal_entity_id=e and a.id=any(ids);
 with entries as (
  select x->>'account_id' account_id,x->>'evidence_key' k,(x->>'expected_base')::numeric v,0::numeric g
   from jsonb_array_elements(sources)x
  union all select x->>'account_id',x->>'evidence_key',0,(x->>'posted_base')::numeric from jsonb_array_elements(journals)x),
 totals as(select account_id,k,sum(v) v,sum(g) g from entries group by account_id,k)
 select coalesce(jsonb_agg(jsonb_build_object('id',coalesce(account_id,'unassigned')||':'||k,'account_id',account_id,
  'evidence_key',k,'expected_base',v::numeric(20,6)::text,'posted_base',g::numeric(20,6)::text,
  'difference',(v-g)::numeric(20,6)::text) order by account_id,k),'[]') into diffs from totals where v<>g;
 if jsonb_array_length(diffs)>10000 then raise exception using errcode='54000',message='TAX_CONTROL_DIFFERENCE_LIMIT';end if;
 select count(*) filter(where x->>'account_id' is null),count(*) filter(where x->>'review_code' is not null)
  into unassigned,reviews from jsonb_array_elements(sources)x;
 select count(*) into unattributed from jsonb_array_elements(journals)x where (x->>'posted_base')::numeric<>0
  and not exists(select 1 from jsonb_array_elements(sources)s where s->>'evidence_key'=x->>'evidence_key' and s->>'account_id'=x->>'account_id');
 select coalesce(sum((x->>'source_closing_base')::numeric),0),coalesce(sum((x->>'gl_closing_base')::numeric),0)
  into source_total,gl_total from jsonb_array_elements(controls)x;
 summary:=jsonb_build_object('id',p->>'id','version',2,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'period_id',period.id,'period_start',period.start_date,'period_end',period.end_date,'as_of',d,
  'branch_filter_id',filter_branch,'base_currency_code',(select currency_code from core.legal_entities where tenant_id=t and id=e),
  'generated_at',statement_timestamp(),'status',case when blocked_count>0 or jsonb_array_length(diffs)>0 or reviews>0 then 'blocked' else 'generated' end,
  'notice','NON-CERTIFIED • STATUTORY REVIEW REQUIRED','line_count',line_count,'blocked_count',blocked_count,'blockers',blockers,
  'output_tax_base',output_base::numeric(20,6)::text,'input_tax_base',input_base::numeric(20,6)::text,
  'withholding_tax_base','0.000000','zero_taxable_base',zero_base::numeric(20,6)::text,'exempt_taxable_base',exempt_base::numeric(20,6)::text,
  'unverified_tax_base',unverified::numeric(20,6)::text,'controls',controls,
  'control_status',case when jsonb_array_length(diffs)>0 or reviews>0 then 'blocked' else 'reconciled' end,
  'control_source_count',jsonb_array_length(sources),'control_journal_count',jsonb_array_length(journals),
  'control_difference_count',jsonb_array_length(diffs),'control_review_count',reviews,
  'control_unassigned_source_count',unassigned,'unattributed_journal_count',unattributed,
  'control_source_base',source_total::numeric(20,6)::text,'control_gl_base',gl_total::numeric(20,6)::text,
  'control_difference',(source_total-gl_total)::numeric(20,6)::text);
 result:=jsonb_build_object('summary',summary,'lines',line_rows,'controls',controls,
  'control_sources',sources,'control_journals',journals,'control_differences',diffs);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='TAX_REPORT_EVIDENCE_LIMIT';end if;
 return result;
end$$;
revoke all on function finance.build_tax_summary(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create function api.tax_control_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_report_id uuid,
 p_section text,p_offset integer default 0,p_account_id uuid default null,p_evidence_key text default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare report finance.tax_reports%rowtype;rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_section is null or p_section not in('controls','control_sources','control_journals','control_differences')
  or p_offset is null or p_offset<0 or p_offset>10000 or length(coalesce(p_evidence_key,''))>220 then
  raise exception using errcode='22023',message='TAX_CONTROL_PAGE_INVALID';end if;
 select * into report from finance.tax_reports where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and requested_branch_id=p_branch_id and id=p_report_id;
 if not found then raise exception using errcode='42501',message='TAX_REPORT_SCOPE_REQUIRED';end if;
 if (report.summary->>'version')::integer<2 then raise exception using errcode='55000',message='TAX_CONTROL_EVIDENCE_UNAVAILABLE';end if;
 select coalesce(jsonb_agg(value order by ord),'[]') into rows from (
  select value,ord from jsonb_array_elements(report.evidence->p_section) with ordinality x(value,ord)
  where (p_account_id is null or value->>'account_id'=p_account_id::text)
   and (p_evidence_key is null or value->>'evidence_key'=p_evidence_key)
  order by ord offset p_offset limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('summary',report.summary,'section',p_section,'account_filter_id',p_account_id,
  'evidence_key',p_evidence_key,'items',rows,'next_offset',case when n>50 then p_offset+50 end);
end$$;
revoke all on function api.tax_control_page(uuid,uuid,uuid,uuid,text,integer,uuid,text) from public,anon,authenticated;
grant execute on function api.tax_control_page(uuid,uuid,uuid,uuid,text,integer,uuid,text) to authenticated;

alter function finance.period_close_exceptions(uuid,uuid,finance.fiscal_periods) rename to period_close_exceptions_before_tax;
create function finance.period_close_exceptions(t uuid,e uuid,p finance.fiscal_periods)
returns jsonb language plpgsql security definer set search_path='' as $$
declare issues jsonb;report jsonb;branch uuid;begin
 issues:=finance.period_close_exceptions_before_tax(t,e,p);
 if p.end_date<(statement_timestamp() at time zone 'UTC')::date and (exists(
  select 1 from finance.tax_posted_sources(t,e,p.end_date) where posting_date>=p.start_date) or exists(
  select 1 from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date between p.start_date and p.end_date
   and l.account_id in(select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='output_tax'
    union select input_tax_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e
    union select (snapshot->>'input_tax_account_id')::uuid from procurement.supplier_bill_control_history
     where tenant_id=t and legal_entity_id=e and snapshot->>'input_tax_account_id' is not null))) then
  begin
   select id into branch from core.branches where tenant_id=t and legal_entity_id=e and status='active' order by id limit 1;
   report:=finance.build_tax_summary(t,e,branch,jsonb_build_object('id',gen_random_uuid(),'period_id',p.id,'as_of',p.end_date))->'summary';
   if report->>'status'='blocked' then issues:=issues||jsonb_build_array(jsonb_build_object('code','TAX_REVIEW_BLOCKED',
    'blocked_count',report->'blocked_count','control_difference_count',report->'control_difference_count',
    'control_review_count',report->'control_review_count','control_difference',report->>'control_difference'));end if;
  exception when others then issues:=issues||jsonb_build_array(jsonb_build_object('code','TAX_REVIEW_CHECK_FAILED','sqlstate',sqlstate));end;
 end if;
 return issues;
end$$;
revoke all on function finance.period_close_exceptions_before_tax(uuid,uuid,finance.fiscal_periods),
 finance.period_close_exceptions(uuid,uuid,finance.fiscal_periods) from public,anon,authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive AC-320 candidate. Governed tax declarations reuse manual
-- journal approval, posting, reversal and immutable ledger engines unchanged.
alter function finance.manual_normalize(uuid,uuid,uuid,jsonb) rename to manual_normalize_before_tax;
create function finance.manual_normalize(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare normalized jsonb;rawlines jsonb;lines jsonb:='[]';line jsonb;raw jsonb;
 definition finance.tax_definitions%rowtype;version bigint;basis numeric;amount numeric;
 scale integer;direction integer;reversal uuid:=(p->>'reversal_of_id')::uuid;
begin
 normalized:=finance.manual_normalize_before_tax(t,e,b,p);
 select rounding_scale into scale from core.legal_entities where tenant_id=t and id=e;
 if reversal is null then rawlines:=p->'lines';
 else select snapshot->'lines' into rawlines from finance.manual_journals
  where tenant_id=t and legal_entity_id=e and branch_id=b and id=reversal and status='posted';end if;
 for line in select value from jsonb_array_elements(normalized->'lines') loop
  select value into raw from jsonb_array_elements(rawlines) where value->>'line_id'=line->>'line_id';
  if raw->>'tax_definition_id' is not null then
   if reversal is not null then
    -- A reversal cancels the original declaration, even after rate retirement.
    -- Client replacement metadata is deliberately ignored.
    line:=line||jsonb_build_object('tax_definition_id',raw->'tax_definition_id',
     'tax_definition_version',raw->'tax_definition_version','tax_code',raw->'tax_code',
     'tax_kind',raw->'tax_kind','tax_rate',raw->'tax_rate','tax_inclusive',raw->'tax_inclusive',
     'taxable_amount',raw->'taxable_amount','tax_basis_date',raw->'tax_basis_date',
     'tax_rounding_scale',raw->'tax_rounding_scale','tax_direction',-(raw->>'tax_direction')::integer,
     'expected_tax_base',abs((line->>'base_amount')::numeric)::numeric(20,6)::text);
   else
    select * into definition from finance.tax_definitions where tenant_id=t and legal_entity_id=e
     and id=(raw->>'tax_definition_id')::uuid and status='active'
     and (normalized->>'document_date')::date between valid_from and coalesce(valid_to,'infinity'::date)
     and kind in('input','output','withholding') for share;
    if not found then raise exception using errcode='55000',message='JOURNAL_TAX_DEFINITION_INVALID';end if;
    select max(v.version) into version from finance.tax_definition_versions v
     where v.tenant_id=t and v.legal_entity_id=e and v.definition_id=definition.id;
    if version is null then raise exception using errcode='55000',message='JOURNAL_TAX_VERSION_UNAVAILABLE';end if;
    basis:=sales.wave3_decimal_string(raw->'taxable_amount','taxable_amount',6,true,0,null)::numeric;
    amount:=abs((line->>'amount')::numeric);
    direction:=case when definition.kind='input' then 1 else -1 end;
    if basis<=0 or amount<>round(basis*definition.rate/100,scale) then
     raise exception using errcode='22023',message='JOURNAL_TAX_AMOUNT_INVALID';end if;
    if sign((line->>'amount')::numeric)<>direction or not exists(select 1 from finance.accounts
     where tenant_id=t and id=(line->>'account_id')::uuid
      and account_type=case when definition.kind='input' then 'asset' else 'liability' end) then
     raise exception using errcode='22023',message='JOURNAL_TAX_ACCOUNT_SIDE_INVALID';end if;
    line:=line||jsonb_build_object('tax_definition_id',definition.id,'tax_definition_version',version,
     'tax_code',definition.code,'tax_kind',definition.kind,'tax_rate',definition.rate::text,
     'tax_inclusive',definition.inclusive,'taxable_amount',basis::numeric(20,6)::text,
     'tax_basis_date',normalized->>'document_date','tax_rounding_scale',scale,'tax_direction',direction,
     'expected_tax_base',abs((line->>'base_amount')::numeric)::numeric(20,6)::text);
   end if;
  elsif raw->>'taxable_amount' is not null then
   raise exception using errcode='22023',message='JOURNAL_TAX_DEFINITION_REQUIRED';
  end if;
  lines:=lines||jsonb_build_array(line);
 end loop;
 return normalized||jsonb_build_object('lines',lines);
end$$;
revoke all on function finance.manual_normalize_before_tax(uuid,uuid,uuid,jsonb),
 finance.manual_normalize(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create or replace function finance.manual_revalidate(p_kind text,d jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare fresh jsonb;failure text;begin
 begin
  fresh:=finance.manual_normalize((d->>'tenant_id')::uuid,(d->>'legal_entity_id')::uuid,(d->>'branch_id')::uuid,d);
 exception when sqlstate '22023' or sqlstate '55000' then
  get stacked diagnostics failure=message_text;
  if failure like 'JOURNAL_TAX_%' then
   raise exception using errcode='55000',message='JOURNAL_REAPPROVAL_REQUIRED';end if;
  raise;
 end;
 if fresh-'reason'-'description'-'document_date' is distinct from (select snapshot-'reason'-'description'-'document_date'
  from finance.manual_journals where id=(d->>'id')::uuid) then
  raise exception using errcode='55000',message='JOURNAL_REAPPROVAL_REQUIRED';end if;
 return fresh;
end$$;
revoke all on function finance.manual_revalidate(text,jsonb) from public,anon,authenticated;

create function api.manual_journal_tax_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_document_date date,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.journals.post',p_legal_entity_id,p_branch_id);
 if p_document_date is null or p_document_date>(statement_timestamp() at time zone 'UTC')::date
  or length(coalesce(p_search,''))>100 then raise exception using errcode='22023',message='JOURNAL_TAX_OPTIONS_INVALID';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from (
  select d.id,d.code,d.name,d.kind,d.rate::text,d.inclusive,d.valid_from,d.valid_to,
   (select max(version) from finance.tax_definition_versions v where v.tenant_id=d.tenant_id
    and v.legal_entity_id=d.legal_entity_id and v.definition_id=d.id) version
  from finance.tax_definitions d where d.tenant_id=p_tenant_id and d.legal_entity_id=p_legal_entity_id
   and d.status='active' and d.kind in('input','output','withholding') and d.rate>0
   and p_document_date between d.valid_from and coalesce(d.valid_to,'infinity'::date)
   and (p_after is null or d.id>p_after)
   and (coalesce(p_search,'')='' or d.code ilike '%'||p_search||'%' or d.name ilike '%'||p_search||'%')
  order by d.id limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'document_date',p_document_date,'rounding_scale',(select rounding_scale from core.legal_entities
   where tenant_id=p_tenant_id and id=p_legal_entity_id),'items',rows,
  'next_cursor',case when n>50 then rows->49->>'id' end);
end$$;
revoke all on function api.manual_journal_tax_options(uuid,uuid,uuid,date,uuid,text) from public,anon,authenticated;
grant execute on function api.manual_journal_tax_options(uuid,uuid,uuid,date,uuid,text) to authenticated;


create or replace function finance.tax_posted_sources(t uuid,e uuid,d date)
returns table(source_type text,source_id uuid,source_line_id uuid,branch_id uuid,
 posting_date date,tax_basis_date date,currency_code text,base_currency_code text,
 exchange_rate numeric,source_snapshot jsonb,taxable_amount numeric,tax_amount numeric,
 expected_tax_base numeric,expected_base_verified boolean,journal_entry_id uuid,document_number text)
language sql stable security definer set search_path='' as $$
 select 'sales_invoice',doc.id,s.id,s.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.snapshot,s.taxable_amount,s.tax_amount,
  round(s.tax_amount*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from sales.sales_invoice_lines s join sales.sales_invoices doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='sales_invoice' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.snapshot->>'tax_definition_id' is not null or s.tax_amount<>0)
 union all
 select 'sales_return',doc.id,s.id,s.branch_id,doc.document_date,invoice.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.snapshot,s.taxable_amount,s.tax_amount,
  round(s.tax_amount*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from sales.sales_return_lines s join sales.sales_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join sales.sales_invoice_lines original on original.tenant_id=s.tenant_id and original.id=s.sales_invoice_line_id
 left join sales.sales_invoices invoice on invoice.tenant_id=original.tenant_id and invoice.id=original.document_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='sales_return' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.snapshot->>'tax_definition_id' is not null or s.tax_amount<>0)
 union all
 select 'supplier_bill',doc.id,s.id,s.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.detail,
  (s.detail->>'net_amount')::numeric,(s.detail->>'tax_amount')::numeric,
  round((s.detail->>'tax_amount')::numeric*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from procurement.supplier_bill_lines s join procurement.supplier_bills doc on doc.tenant_id=s.tenant_id and doc.id=s.bill_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='supplier_bill' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.detail->>'tax_definition_id' is not null or (s.detail->>'tax_amount')::numeric<>0)
 union all
 select 'purchase_return',doc.id,s.id,s.branch_id,doc.document_date,
  coalesce((s.detail->>'tax_basis_date')::date,bill.document_date),
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.detail->'source_snapshot',
  (s.detail->>'net_amount')::numeric,(s.detail->>'tax_amount')::numeric,
  coalesce((s.detail->>'expected_tax_base')::numeric,
   round((s.detail->>'tax_amount')::numeric*doc.exchange_rate,entity.rounding_scale)),
  s.detail->>'expected_tax_base' is not null or (s.detail->>'tax_amount')::numeric=0,j.id,doc.document_number
 from procurement.purchase_return_lines s join procurement.purchase_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.return_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join procurement.supplier_bill_lines original on original.tenant_id=s.tenant_id and original.id=s.bill_line_id
 left join procurement.supplier_bills bill on bill.tenant_id=original.tenant_id and bill.id=original.bill_id
 left join finance.journal_entries j on j.tenant_id=t and j.id=doc.journal_entry_id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.document_date<=d
  and (s.detail#>>'{source_snapshot,tax_definition_id}' is not null or (s.detail->>'tax_amount')::numeric<>0)
 union all
 select 'manual_journal',doc.id,(x->>'line_id')::uuid,doc.branch_id,doc.document_date,(x->>'tax_basis_date')::date,
  doc.currency_code,doc.snapshot->>'base_currency_code',(doc.snapshot->>'exchange_rate')::numeric,
  x||jsonb_build_object('reversal_of_id',doc.reversal_of_id),
  (x->>'taxable_amount')::numeric,abs((x->>'amount')::numeric),
  (x->>'expected_tax_base')::numeric,true,j.id,doc.document_number
 from finance.manual_journals doc cross join lateral jsonb_array_elements(doc.snapshot->'lines')x
 left join finance.journal_entries j on j.tenant_id=doc.tenant_id and j.id=doc.journal_entry_id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and x->>'tax_definition_id' is not null
$$;
revoke all on function finance.tax_posted_sources(uuid,uuid,date) from public,anon,authenticated;

create or replace function finance.build_tax_summary(t uuid,e uuid,b uuid,p jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare period finance.fiscal_periods%rowtype;d date:=(p->>'as_of')::date;
 filter_branch uuid:=(p->>'branch_filter_id')::uuid;scale integer;r record;
 definition finance.tax_definition_versions%rowtype;journal_lines jsonb;
 line_rows jsonb:='[]';sources jsonb:='[]';journals jsonb;controls jsonb;diffs jsonb;
 blockers jsonb:='[]';reason text;control_reason text;account uuid;account_count integer;ids uuid[];
 tax_transaction numeric;tax_base numeric;taxable_base numeric;direction integer;
 output_base numeric:=0;input_base numeric:=0;withholding_base numeric:=0;zero_base numeric:=0;exempt_base numeric:=0;unverified numeric:=0;
 line_count integer:=0;blocked_count integer:=0;source_count integer:=0;unassigned integer;unattributed integer;reviews integer;
 source_total numeric;gl_total numeric;summary jsonb;result jsonb;
begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if d is null or d>(statement_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='TAX_REPORT_DATE_INVALID';end if;
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
  and id=(p->>'period_id')::uuid and status='active';
 if not found or d not between period.start_date and period.end_date then
  raise exception using errcode='22023',message='TAX_REPORT_PERIOD_INVALID';end if;
 if filter_branch is not null and (filter_branch<>b or not exists(select 1 from core.branches
  where tenant_id=t and legal_entity_id=e and id=filter_branch)) then
  raise exception using errcode='22023',message='TAX_REPORT_BRANCH_INVALID';end if;
 select rounding_scale into scale from core.legal_entities where tenant_id=t and id=e;
 for r in select * from finance.tax_posted_sources(t,e,d)
  where filter_branch is null or branch_id=filter_branch order by posting_date,source_type,source_line_id loop
  source_count:=source_count+1;
  if source_count>10000 then raise exception using errcode='54000',message='TAX_REPORT_LINE_LIMIT';end if;
  direction:=case when r.source_type='manual_journal' then (r.source_snapshot->>'tax_direction')::integer when r.source_type in('sales_invoice','purchase_return') then -1 else 1 end;
  select coalesce(sum(direction*(l.transaction_debit-l.transaction_credit)),0),
   coalesce(sum(direction*(l.base_debit-l.base_credit)),0),count(distinct l.account_id),
   (array_agg(l.account_id order by l.line_number))[1],
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'journal_entry_id',r.journal_entry_id,
    'account_id',l.account_id,'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'base_debit',l.base_debit::text,
    'base_credit',l.base_credit::text) order by l.line_number),'[]')
   into tax_transaction,tax_base,account_count,account,journal_lines
  from finance.journal_lines l join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id
  where l.tenant_id=t and l.journal_entry_id=r.journal_entry_id and l.source_line_id=r.source_line_id
   and a.account_type=case when r.source_type='manual_journal' then case when r.source_snapshot->>'tax_kind'='input' then 'asset' else 'liability' end when r.source_type in('supplier_bill','purchase_return') then 'asset' else 'liability' end;
  if account_count<>1 then account:=null;end if;
  control_reason:=case when not r.expected_base_verified then 'RETURN_TAX_BASE_UNVERIFIED'
   when r.tax_amount<>0 and account is null then 'TAX_CONTROL_ACCOUNT_UNPROVEN'
   when tax_transaction<>r.tax_amount or tax_base<>r.expected_tax_base then 'TAX_CONTROL_JOURNAL_MISMATCH' end;
  if r.tax_amount<>0 or tax_base<>0 then
   sources:=sources||jsonb_build_array(jsonb_build_object('id',r.source_line_id,
    'evidence_key',r.source_type||':'||r.source_id||':'||r.source_line_id,
    'source_type',r.source_type,'source_id',r.source_id,'source_line_id',r.source_line_id,
    'journal_entry_id',r.journal_entry_id,'document_number',r.document_number,'branch_id',r.branch_id,
    'posting_date',r.posting_date,'phase',case when r.posting_date<period.start_date then 'opening' else 'period' end,
    'account_id',account,'currency_code',r.currency_code,'base_currency_code',r.base_currency_code,
    'expected_base',(direction*r.expected_tax_base)::numeric(20,6)::text,
    'posted_base',(direction*tax_base)::numeric(20,6)::text,'review_code',control_reason));
  end if;
  if r.posting_date<period.start_date then continue;end if;
  line_count:=line_count+1;reason:=null;definition:=null;
  if r.source_snapshot->>'tax_definition_version' is null then reason:='MISSING_DEFINITION_VERSION';
  else
   select * into definition from finance.tax_definition_versions where tenant_id=t and legal_entity_id=e
    and definition_id=(r.source_snapshot->>'tax_definition_id')::uuid
    and version=(r.source_snapshot->>'tax_definition_version')::bigint;
   if not found then reason:='DEFINITION_VERSION_UNAVAILABLE';
   elsif r.tax_basis_date is null then reason:='SOURCE_TAX_DATE_UNAVAILABLE';
   elsif r.tax_basis_date not between definition.valid_from and coalesce(definition.valid_to,'infinity'::date)
    or definition.status<>'active' then reason:='DEFINITION_OUTSIDE_SOURCE_DATE';
   elsif definition.kind is distinct from r.source_snapshot->>'tax_kind'
    or definition.rate is distinct from (r.source_snapshot->>'tax_rate')::numeric
    or definition.inclusive is distinct from (r.source_snapshot->>'tax_inclusive')::boolean
    or definition.code is distinct from r.source_snapshot->>'tax_code' then reason:='DEFINITION_SNAPSHOT_MISMATCH';end if;
  end if;
  if reason is null and r.journal_entry_id is null and (r.taxable_amount<>0 or r.tax_amount<>0) then
   reason:='POSTED_JOURNAL_MISSING';end if;
  if reason is null then reason:=control_reason;end if;
  if reason is null and definition.kind in('zero','exempt') and r.tax_amount<>0 then reason:='ZERO_TAX_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type in('supplier_bill','purchase_return') and definition.kind not in('input','zero','exempt') then
   reason:='INPUT_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type in('sales_invoice','sales_return') and definition.kind not in('output','zero','exempt') then
   reason:='OUTPUT_TREATMENT_MISMATCH';end if;
  taxable_base:=round(r.taxable_amount*r.exchange_rate,scale);
  if reason is not null then
   blocked_count:=blocked_count+1;unverified:=unverified+abs(r.expected_tax_base);
   if blocked_count<=100 then blockers:=blockers||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
    'source_id',r.source_id,'source_line_id',r.source_line_id,'code',reason));end if;
  elsif definition.kind='output' then output_base:=output_base+case when r.source_type='manual_journal' then -direction*tax_base when r.source_type='sales_return' then -tax_base else tax_base end;
  elsif definition.kind='input' then input_base:=input_base+case when r.source_type='manual_journal' then direction*tax_base when r.source_type='purchase_return' then -tax_base else tax_base end;
  elsif definition.kind='withholding' then withholding_base:=withholding_base-direction*tax_base;
  elsif definition.kind='zero' then zero_base:=zero_base+case when r.source_type in('sales_return','purchase_return') then -taxable_base else taxable_base end;
  else exempt_base:=exempt_base+case when r.source_type in('sales_return','purchase_return') then -taxable_base else taxable_base end;end if;
  line_rows:=line_rows||jsonb_build_array(jsonb_build_object('source_type',r.source_type,'source_id',r.source_id,
   'source_line_id',r.source_line_id,'branch_id',r.branch_id,'journal_entry_id',r.journal_entry_id,
   'document_number',r.document_number,'posting_date',r.posting_date,'tax_basis_date',r.tax_basis_date,
   'tax_direction',direction,'reversal_of_id',r.source_snapshot->'reversal_of_id',
   'currency_code',r.currency_code,'base_currency_code',r.base_currency_code,
   'definition_id',r.source_snapshot->>'tax_definition_id','definition_version',r.source_snapshot->>'tax_definition_version',
   'tax_code',r.source_snapshot->>'tax_code','tax_kind',r.source_snapshot->>'tax_kind','tax_rate',r.source_snapshot->>'tax_rate',
   'taxable_amount',r.taxable_amount::numeric(20,6)::text,'tax_amount',r.tax_amount::numeric(20,6)::text,
   'taxable_base',taxable_base::numeric(20,6)::text,'tax_base',tax_base::numeric(20,6)::text,
   'expected_tax_base',r.expected_tax_base::numeric(20,6)::text,'review_code',reason,'journal_lines',journal_lines));
 end loop;
 select coalesce(array_agg(distinct id),'{}') into ids from (
  select (x->>'account_id')::uuid id from jsonb_array_elements(sources)x where x->>'account_id' is not null
  union select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='output_tax'
  union select input_tax_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e
  union select (snapshot->>'input_tax_account_id')::uuid from procurement.supplier_bill_control_history
   where tenant_id=t and legal_entity_id=e and snapshot->>'input_tax_account_id' is not null
 ) all_accounts;
 if cardinality(ids)>50 then raise exception using errcode='54000',message='TAX_CONTROL_ACCOUNT_LIMIT';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id,j.id journal_entry_id,j.command_id,j.source_type,j.source_id,l.source_line_id,
   j.document_number,l.branch_id,l.posting_date,l.currency_code,j.base_currency_code,
   j.source_type||':'||j.source_id||':'||coalesce(l.source_line_id::text,'journal-'||l.id) evidence_key,
   case when l.posting_date<period.start_date then 'opening' else 'period' end phase,
   l.transaction_debit::text,l.transaction_credit::text,l.base_debit::text,l.base_credit::text,
   (l.base_debit-l.base_credit)::numeric(20,6)::text posted_base
  from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date<=d and l.account_id=any(ids)
   and (filter_branch is null or l.branch_id=filter_branch) order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='TAX_CONTROL_JOURNAL_LIMIT';end if;
 with entries as (
  select (x->>'account_id')::uuid id,(x->>'expected_base')::numeric v,0::numeric g,x->>'phase' phase
   from jsonb_array_elements(sources)x where x->>'account_id' is not null
  union all select (x->>'account_id')::uuid,0,(x->>'posted_base')::numeric,x->>'phase' from jsonb_array_elements(journals)x),
 totals as(select id,coalesce(sum(v) filter(where phase='opening'),0) so,coalesce(sum(g) filter(where phase='opening'),0) go,
  coalesce(sum(v) filter(where phase='period'),0) sp,coalesce(sum(g) filter(where phase='period'),0) gp from entries group by id)
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'account_id',a.id,'code',a.code,'name',a.name,'account_type',a.account_type,
  'source_opening_base',coalesce(so,0)::numeric(20,6)::text,'gl_opening_base',coalesce(go,0)::numeric(20,6)::text,
  'source_period_base',coalesce(sp,0)::numeric(20,6)::text,'gl_period_base',coalesce(gp,0)::numeric(20,6)::text,
  'source_closing_base',(coalesce(so,0)+coalesce(sp,0))::numeric(20,6)::text,
  'gl_closing_base',(coalesce(go,0)+coalesce(gp,0))::numeric(20,6)::text,
  'difference',(coalesce(so,0)+coalesce(sp,0)-coalesce(go,0)-coalesce(gp,0))::numeric(20,6)::text) order by a.id),'[]') into controls
 from finance.accounts a left join totals using(id) where a.tenant_id=t and a.legal_entity_id=e and a.id=any(ids);
 with entries as (
  select x->>'account_id' account_id,x->>'evidence_key' k,(x->>'expected_base')::numeric v,0::numeric g
   from jsonb_array_elements(sources)x
  union all select x->>'account_id',x->>'evidence_key',0,(x->>'posted_base')::numeric from jsonb_array_elements(journals)x),
 totals as(select account_id,k,sum(v) v,sum(g) g from entries group by account_id,k)
 select coalesce(jsonb_agg(jsonb_build_object('id',coalesce(account_id,'unassigned')||':'||k,'account_id',account_id,
  'evidence_key',k,'expected_base',v::numeric(20,6)::text,'posted_base',g::numeric(20,6)::text,
  'difference',(v-g)::numeric(20,6)::text) order by account_id,k),'[]') into diffs from totals where v<>g;
 if jsonb_array_length(diffs)>10000 then raise exception using errcode='54000',message='TAX_CONTROL_DIFFERENCE_LIMIT';end if;
 select count(*) filter(where x->>'account_id' is null),count(*) filter(where x->>'review_code' is not null)
  into unassigned,reviews from jsonb_array_elements(sources)x;
 select count(*) into unattributed from jsonb_array_elements(journals)x where (x->>'posted_base')::numeric<>0
  and not exists(select 1 from jsonb_array_elements(sources)s where s->>'evidence_key'=x->>'evidence_key' and s->>'account_id'=x->>'account_id');
 select coalesce(sum((x->>'source_closing_base')::numeric),0),coalesce(sum((x->>'gl_closing_base')::numeric),0)
  into source_total,gl_total from jsonb_array_elements(controls)x;
 summary:=jsonb_build_object('id',p->>'id','version',2,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'period_id',period.id,'period_start',period.start_date,'period_end',period.end_date,'as_of',d,
  'branch_filter_id',filter_branch,'base_currency_code',(select currency_code from core.legal_entities where tenant_id=t and id=e),
  'generated_at',statement_timestamp(),'status',case when blocked_count>0 or jsonb_array_length(diffs)>0 or reviews>0 then 'blocked' else 'generated' end,
  'notice','NON-CERTIFIED • STATUTORY REVIEW REQUIRED','line_count',line_count,'blocked_count',blocked_count,'blockers',blockers,
  'output_tax_base',output_base::numeric(20,6)::text,'input_tax_base',input_base::numeric(20,6)::text,
  'withholding_tax_base',withholding_base::numeric(20,6)::text,'zero_taxable_base',zero_base::numeric(20,6)::text,'exempt_taxable_base',exempt_base::numeric(20,6)::text,
  'unverified_tax_base',unverified::numeric(20,6)::text,'controls',controls,
  'control_status',case when jsonb_array_length(diffs)>0 or reviews>0 then 'blocked' else 'reconciled' end,
  'control_source_count',jsonb_array_length(sources),'control_journal_count',jsonb_array_length(journals),
  'control_difference_count',jsonb_array_length(diffs),'control_review_count',reviews,
  'control_unassigned_source_count',unassigned,'unattributed_journal_count',unattributed,
  'control_source_base',source_total::numeric(20,6)::text,'control_gl_base',gl_total::numeric(20,6)::text,
  'control_difference',(source_total-gl_total)::numeric(20,6)::text);
 result:=jsonb_build_object('summary',summary,'lines',line_rows,'controls',controls,
  'control_sources',sources,'control_journals',journals,'control_differences',diffs);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='TAX_REPORT_EVIDENCE_LIMIT';end if;
 return result;
end$$;
revoke all on function finance.build_tax_summary(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

-- Cumulative tax sources retain retired manual tax-control account coverage.
create or replace function finance.period_close_exceptions(t uuid,e uuid,p finance.fiscal_periods)
returns jsonb language plpgsql security definer set search_path='' as $$
declare issues jsonb;report jsonb;branch uuid;begin
 issues:=finance.period_close_exceptions_before_tax(t,e,p);
 if p.end_date<(statement_timestamp() at time zone 'UTC')::date and (exists(
  select 1 from finance.tax_posted_sources(t,e,p.end_date)) or exists(
  select 1 from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date between p.start_date and p.end_date
   and l.account_id in(select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='output_tax'
    union select input_tax_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e
    union select (snapshot->>'input_tax_account_id')::uuid from procurement.supplier_bill_control_history
     where tenant_id=t and legal_entity_id=e and snapshot->>'input_tax_account_id' is not null))) then
  begin
   select id into branch from core.branches where tenant_id=t and legal_entity_id=e and status='active' order by id limit 1;
   report:=finance.build_tax_summary(t,e,branch,jsonb_build_object('id',gen_random_uuid(),'period_id',p.id,'as_of',p.end_date))->'summary';
   if report->>'status'='blocked' then issues:=issues||jsonb_build_array(jsonb_build_object('code','TAX_REVIEW_BLOCKED',
    'blocked_count',report->'blocked_count','control_difference_count',report->'control_difference_count',
    'control_review_count',report->'control_review_count','control_difference',report->>'control_difference'));end if;
  exception when others then issues:=issues||jsonb_build_array(jsonb_build_object('code','TAX_REVIEW_CHECK_FAILED','sqlstate',sqlstate));end;
 end if;
 return issues;
end$$;
revoke all on function finance.period_close_exceptions(uuid,uuid,finance.fiscal_periods) from public,anon,authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive candidate. Tax settlements/adjustments are governed source
-- journals; they reconcile controls but do not reclassify period tax accruals.
create function finance.tax_control_accounts(t uuid,e uuid) returns setof uuid
language sql stable security definer set search_path='' as $$
 select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='output_tax'
 union select input_tax_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e
 union select (snapshot->>'input_tax_account_id')::uuid from procurement.supplier_bill_control_history
  where tenant_id=t and legal_entity_id=e and snapshot->>'input_tax_account_id' is not null
 union select (line->>'account_id')::uuid from finance.manual_journals doc,
  lateral jsonb_array_elements(doc.snapshot->'lines')line
  where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and line->>'tax_definition_id' is not null
$$;
revoke all on function finance.tax_control_accounts(uuid,uuid) from public,anon,authenticated;

alter function finance.manual_normalize(uuid,uuid,uuid,jsonb) rename to manual_normalize_before_tax_movements;
create function finance.manual_normalize(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare normalized jsonb;rawlines jsonb;line jsonb;raw jsonb;lines jsonb:='[]';kind text;
 reversal uuid:=(p->>'reversal_of_id')::uuid;begin
 normalized:=finance.manual_normalize_before_tax_movements(t,e,b,p);
 if reversal is null then rawlines:=p->'lines';
 else select snapshot->'lines' into rawlines from finance.manual_journals
  where tenant_id=t and legal_entity_id=e and branch_id=b and id=reversal and status='posted';end if;
 for line in select value from jsonb_array_elements(normalized->'lines') loop
  select value into raw from jsonb_array_elements(rawlines) where value->>'line_id'=line->>'line_id';
  if raw->>'tax_control_movement' is not null then
   if raw->>'tax_control_movement' not in('settlement','adjustment','transfer')
    or raw->>'tax_definition_id' is not null then
    raise exception using errcode='22023',message='JOURNAL_TAX_MOVEMENT_INVALID';end if;
   select account_type into kind from finance.accounts where tenant_id=t and legal_entity_id=e
    and id=(line->>'account_id')::uuid and account_type in('asset','liability')
    and (reversal is not null or id in(select * from finance.tax_control_accounts(t,e)));
   if not found then raise exception using errcode='55000',message='JOURNAL_TAX_CONTROL_UNPROVEN';end if;
   line:=line||jsonb_build_object('is_tax_control',true,'tax_control_movement',raw->>'tax_control_movement',
    'tax_account_type',kind,'tax_direction',sign((line->>'amount')::numeric)::integer,
    'expected_tax_base',abs((line->>'base_amount')::numeric)::numeric(20,6)::text);
  end if;
  lines:=lines||jsonb_build_array(line);
 end loop;
 return normalized||jsonb_build_object('lines',lines);
end$$;
revoke all on function finance.manual_normalize_before_tax_movements(uuid,uuid,uuid,jsonb),
 finance.manual_normalize(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create function api.manual_journal_tax_controls(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_after uuid default null,p_search text default '') returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.journals.post',p_legal_entity_id,p_branch_id);
 if length(coalesce(p_search,''))>100 then raise exception using errcode='22023',message='JOURNAL_TAX_OPTIONS_INVALID';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(
  select id,code,name,account_type,currency_code,true is_tax_control from finance.accounts
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and is_posting
   and account_type in('asset','liability') and id in(select * from finance.tax_control_accounts(p_tenant_id,p_legal_entity_id))
   and (p_after is null or id>p_after)
   and (coalesce(p_search,'')='' or code ilike '%'||p_search||'%' or name ilike '%'||p_search||'%')
  order by id limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'items',rows,'next_cursor',case when n>50 then rows->49->>'id' end);
end$$;
revoke all on function api.manual_journal_tax_controls(uuid,uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function api.manual_journal_tax_controls(uuid,uuid,uuid,uuid,text) to authenticated;


create or replace function finance.tax_posted_sources(t uuid,e uuid,d date)
returns table(source_type text,source_id uuid,source_line_id uuid,branch_id uuid,
 posting_date date,tax_basis_date date,currency_code text,base_currency_code text,
 exchange_rate numeric,source_snapshot jsonb,taxable_amount numeric,tax_amount numeric,
 expected_tax_base numeric,expected_base_verified boolean,journal_entry_id uuid,document_number text)
language sql stable security definer set search_path='' as $$
 select 'sales_invoice',doc.id,s.id,s.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.snapshot,s.taxable_amount,s.tax_amount,
  round(s.tax_amount*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from sales.sales_invoice_lines s join sales.sales_invoices doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='sales_invoice' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.snapshot->>'tax_definition_id' is not null or s.tax_amount<>0)
 union all
 select 'sales_return',doc.id,s.id,s.branch_id,doc.document_date,invoice.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.snapshot,s.taxable_amount,s.tax_amount,
  round(s.tax_amount*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from sales.sales_return_lines s join sales.sales_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.document_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join sales.sales_invoice_lines original on original.tenant_id=s.tenant_id and original.id=s.sales_invoice_line_id
 left join sales.sales_invoices invoice on invoice.tenant_id=original.tenant_id and invoice.id=original.document_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='sales_return' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.snapshot->>'tax_definition_id' is not null or s.tax_amount<>0)
 union all
 select 'supplier_bill',doc.id,s.id,s.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.detail,
  (s.detail->>'net_amount')::numeric,(s.detail->>'tax_amount')::numeric,
  round((s.detail->>'tax_amount')::numeric*doc.exchange_rate,entity.rounding_scale),true,j.id,doc.document_number
 from procurement.supplier_bill_lines s join procurement.supplier_bills doc on doc.tenant_id=s.tenant_id and doc.id=s.bill_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join finance.journal_entries j on j.tenant_id=t and j.source_type='supplier_bill' and j.source_id=doc.id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and (s.detail->>'tax_definition_id' is not null or (s.detail->>'tax_amount')::numeric<>0)
 union all
 select 'purchase_return',doc.id,s.id,s.branch_id,doc.document_date,
  coalesce((s.detail->>'tax_basis_date')::date,bill.document_date),
  doc.currency_code,doc.base_currency_code,doc.exchange_rate,s.detail->'source_snapshot',
  (s.detail->>'net_amount')::numeric,(s.detail->>'tax_amount')::numeric,
  coalesce((s.detail->>'expected_tax_base')::numeric,
   round((s.detail->>'tax_amount')::numeric*doc.exchange_rate,entity.rounding_scale)),
  s.detail->>'expected_tax_base' is not null or (s.detail->>'tax_amount')::numeric=0,j.id,doc.document_number
 from procurement.purchase_return_lines s join procurement.purchase_returns doc on doc.tenant_id=s.tenant_id and doc.id=s.return_id
 join core.legal_entities entity on entity.tenant_id=doc.tenant_id and entity.id=doc.legal_entity_id
 left join procurement.supplier_bill_lines original on original.tenant_id=s.tenant_id and original.id=s.bill_line_id
 left join procurement.supplier_bills bill on bill.tenant_id=original.tenant_id and bill.id=original.bill_id
 left join finance.journal_entries j on j.tenant_id=t and j.id=doc.journal_entry_id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.document_date<=d
  and (s.detail#>>'{source_snapshot,tax_definition_id}' is not null or (s.detail->>'tax_amount')::numeric<>0)
 union all
 select 'manual_journal',doc.id,(x->>'line_id')::uuid,doc.branch_id,doc.document_date,(x->>'tax_basis_date')::date,
  doc.currency_code,doc.snapshot->>'base_currency_code',(doc.snapshot->>'exchange_rate')::numeric,
  x||jsonb_build_object('reversal_of_id',doc.reversal_of_id),
  (x->>'taxable_amount')::numeric,abs((x->>'amount')::numeric),
  (x->>'expected_tax_base')::numeric,true,j.id,doc.document_number
 from finance.manual_journals doc cross join lateral jsonb_array_elements(doc.snapshot->'lines')x
 left join finance.journal_entries j on j.tenant_id=doc.tenant_id and j.id=doc.journal_entry_id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and x->>'tax_definition_id' is not null
 union all
 select 'manual_journal',doc.id,(x->>'line_id')::uuid,doc.branch_id,doc.document_date,doc.document_date,
  doc.currency_code,doc.snapshot->>'base_currency_code',(doc.snapshot->>'exchange_rate')::numeric,
  x||jsonb_build_object('tax_kind',case when x->>'tax_account_type'='asset' then 'input' else 'output' end),
  0::numeric,abs((x->>'amount')::numeric),(x->>'expected_tax_base')::numeric,true,j.id,doc.document_number
 from finance.manual_journals doc cross join lateral jsonb_array_elements(doc.snapshot->'lines')x
 left join finance.journal_entries j on j.tenant_id=doc.tenant_id and j.id=doc.journal_entry_id and j.status='posted'
 where doc.tenant_id=t and doc.legal_entity_id=e and doc.status='posted' and doc.document_date<=d
  and x->>'tax_control_movement' is not null
$$;
revoke all on function finance.tax_posted_sources(uuid,uuid,date) from public,anon,authenticated;

create or replace function finance.build_tax_summary(t uuid,e uuid,b uuid,p jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare period finance.fiscal_periods%rowtype;d date:=(p->>'as_of')::date;
 filter_branch uuid:=(p->>'branch_filter_id')::uuid;scale integer;r record;
 definition finance.tax_definition_versions%rowtype;journal_lines jsonb;
 line_rows jsonb:='[]';sources jsonb:='[]';journals jsonb;controls jsonb;diffs jsonb;
 blockers jsonb:='[]';reason text;control_reason text;account uuid;account_count integer;ids uuid[];
 tax_transaction numeric;tax_base numeric;taxable_base numeric;direction integer;
 output_base numeric:=0;input_base numeric:=0;withholding_base numeric:=0;zero_base numeric:=0;exempt_base numeric:=0;unverified numeric:=0;
 line_count integer:=0;blocked_count integer:=0;source_count integer:=0;unassigned integer;unattributed integer;reviews integer;
 source_total numeric;gl_total numeric;summary jsonb;result jsonb;
begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if d is null or d>(statement_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='TAX_REPORT_DATE_INVALID';end if;
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
  and id=(p->>'period_id')::uuid and status='active';
 if not found or d not between period.start_date and period.end_date then
  raise exception using errcode='22023',message='TAX_REPORT_PERIOD_INVALID';end if;
 if filter_branch is not null and (filter_branch<>b or not exists(select 1 from core.branches
  where tenant_id=t and legal_entity_id=e and id=filter_branch)) then
  raise exception using errcode='22023',message='TAX_REPORT_BRANCH_INVALID';end if;
 select rounding_scale into scale from core.legal_entities where tenant_id=t and id=e;
 for r in select * from finance.tax_posted_sources(t,e,d)
  where filter_branch is null or branch_id=filter_branch order by posting_date,source_type,source_line_id loop
  source_count:=source_count+1;
  if source_count>10000 then raise exception using errcode='54000',message='TAX_REPORT_LINE_LIMIT';end if;
  direction:=case when r.source_type='manual_journal' then (r.source_snapshot->>'tax_direction')::integer when r.source_type in('sales_invoice','purchase_return') then -1 else 1 end;
  select coalesce(sum(direction*(l.transaction_debit-l.transaction_credit)),0),
   coalesce(sum(direction*(l.base_debit-l.base_credit)),0),count(distinct l.account_id),
   (array_agg(l.account_id order by l.line_number))[1],
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'journal_entry_id',r.journal_entry_id,
    'account_id',l.account_id,'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'base_debit',l.base_debit::text,
    'base_credit',l.base_credit::text) order by l.line_number),'[]')
   into tax_transaction,tax_base,account_count,account,journal_lines
  from finance.journal_lines l join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id
  where l.tenant_id=t and l.journal_entry_id=r.journal_entry_id and l.source_line_id=r.source_line_id
   and a.account_type=case when r.source_type='manual_journal' then case when r.source_snapshot->>'tax_kind'='input' then 'asset' else 'liability' end when r.source_type in('supplier_bill','purchase_return') then 'asset' else 'liability' end;
  if account_count<>1 then account:=null;end if;
  control_reason:=case when not r.expected_base_verified then 'RETURN_TAX_BASE_UNVERIFIED'
   when r.tax_amount<>0 and account is null then 'TAX_CONTROL_ACCOUNT_UNPROVEN'
   when tax_transaction<>r.tax_amount or tax_base<>r.expected_tax_base then 'TAX_CONTROL_JOURNAL_MISMATCH' end;
  if r.tax_amount<>0 or tax_base<>0 then
   sources:=sources||jsonb_build_array(jsonb_build_object('id',r.source_line_id,
    'evidence_key',r.source_type||':'||r.source_id||':'||r.source_line_id,
    'source_type',r.source_type,'source_id',r.source_id,'source_line_id',r.source_line_id,
    'journal_entry_id',r.journal_entry_id,'document_number',r.document_number,'branch_id',r.branch_id,
    'posting_date',r.posting_date,'phase',case when r.posting_date<period.start_date then 'opening' else 'period' end,
    'account_id',account,'currency_code',r.currency_code,'base_currency_code',r.base_currency_code,
    'expected_base',(direction*r.expected_tax_base)::numeric(20,6)::text,
    'posted_base',(direction*tax_base)::numeric(20,6)::text,'tax_control_movement',r.source_snapshot->>'tax_control_movement','review_code',control_reason));
  end if;
  if r.posting_date<period.start_date or r.source_snapshot->>'tax_control_movement' is not null then continue;end if;
  line_count:=line_count+1;reason:=null;definition:=null;
  if r.source_snapshot->>'tax_definition_version' is null then reason:='MISSING_DEFINITION_VERSION';
  else
   select * into definition from finance.tax_definition_versions where tenant_id=t and legal_entity_id=e
    and definition_id=(r.source_snapshot->>'tax_definition_id')::uuid
    and version=(r.source_snapshot->>'tax_definition_version')::bigint;
   if not found then reason:='DEFINITION_VERSION_UNAVAILABLE';
   elsif r.tax_basis_date is null then reason:='SOURCE_TAX_DATE_UNAVAILABLE';
   elsif r.tax_basis_date not between definition.valid_from and coalesce(definition.valid_to,'infinity'::date)
    or definition.status<>'active' then reason:='DEFINITION_OUTSIDE_SOURCE_DATE';
   elsif definition.kind is distinct from r.source_snapshot->>'tax_kind'
    or definition.rate is distinct from (r.source_snapshot->>'tax_rate')::numeric
    or definition.inclusive is distinct from (r.source_snapshot->>'tax_inclusive')::boolean
    or definition.code is distinct from r.source_snapshot->>'tax_code' then reason:='DEFINITION_SNAPSHOT_MISMATCH';end if;
  end if;
  if reason is null and r.journal_entry_id is null and (r.taxable_amount<>0 or r.tax_amount<>0) then
   reason:='POSTED_JOURNAL_MISSING';end if;
  if reason is null then reason:=control_reason;end if;
  if reason is null and definition.kind in('zero','exempt') and r.tax_amount<>0 then reason:='ZERO_TAX_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type in('supplier_bill','purchase_return') and definition.kind not in('input','zero','exempt') then
   reason:='INPUT_TREATMENT_MISMATCH';end if;
  if reason is null and r.source_type in('sales_invoice','sales_return') and definition.kind not in('output','zero','exempt') then
   reason:='OUTPUT_TREATMENT_MISMATCH';end if;
  taxable_base:=round(r.taxable_amount*r.exchange_rate,scale);
  if reason is not null then
   blocked_count:=blocked_count+1;unverified:=unverified+abs(r.expected_tax_base);
   if blocked_count<=100 then blockers:=blockers||jsonb_build_array(jsonb_build_object('source_type',r.source_type,
    'source_id',r.source_id,'source_line_id',r.source_line_id,'code',reason));end if;
  elsif definition.kind='output' then output_base:=output_base+case when r.source_type='manual_journal' then -direction*tax_base when r.source_type='sales_return' then -tax_base else tax_base end;
  elsif definition.kind='input' then input_base:=input_base+case when r.source_type='manual_journal' then direction*tax_base when r.source_type='purchase_return' then -tax_base else tax_base end;
  elsif definition.kind='withholding' then withholding_base:=withholding_base-direction*tax_base;
  elsif definition.kind='zero' then zero_base:=zero_base+case when r.source_type in('sales_return','purchase_return') then -taxable_base else taxable_base end;
  else exempt_base:=exempt_base+case when r.source_type in('sales_return','purchase_return') then -taxable_base else taxable_base end;end if;
  line_rows:=line_rows||jsonb_build_array(jsonb_build_object('source_type',r.source_type,'source_id',r.source_id,
   'source_line_id',r.source_line_id,'branch_id',r.branch_id,'journal_entry_id',r.journal_entry_id,
   'document_number',r.document_number,'posting_date',r.posting_date,'tax_basis_date',r.tax_basis_date,
   'tax_direction',direction,'reversal_of_id',r.source_snapshot->'reversal_of_id',
   'currency_code',r.currency_code,'base_currency_code',r.base_currency_code,
   'definition_id',r.source_snapshot->>'tax_definition_id','definition_version',r.source_snapshot->>'tax_definition_version',
   'tax_code',r.source_snapshot->>'tax_code','tax_kind',r.source_snapshot->>'tax_kind','tax_rate',r.source_snapshot->>'tax_rate',
   'taxable_amount',r.taxable_amount::numeric(20,6)::text,'tax_amount',r.tax_amount::numeric(20,6)::text,
   'taxable_base',taxable_base::numeric(20,6)::text,'tax_base',tax_base::numeric(20,6)::text,
   'expected_tax_base',r.expected_tax_base::numeric(20,6)::text,'review_code',reason,'journal_lines',journal_lines));
 end loop;
 select coalesce(array_agg(distinct id),'{}') into ids from (
  select (x->>'account_id')::uuid id from jsonb_array_elements(sources)x where x->>'account_id' is not null
  union select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='output_tax'
  union select input_tax_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e
  union select (snapshot->>'input_tax_account_id')::uuid from procurement.supplier_bill_control_history
   where tenant_id=t and legal_entity_id=e and snapshot->>'input_tax_account_id' is not null
 ) all_accounts;
 if cardinality(ids)>50 then raise exception using errcode='54000',message='TAX_CONTROL_ACCOUNT_LIMIT';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id,j.id journal_entry_id,j.command_id,j.source_type,j.source_id,l.source_line_id,
   j.document_number,l.branch_id,l.posting_date,l.currency_code,j.base_currency_code,
   j.source_type||':'||j.source_id||':'||coalesce(l.source_line_id::text,'journal-'||l.id) evidence_key,
   case when l.posting_date<period.start_date then 'opening' else 'period' end phase,
   l.transaction_debit::text,l.transaction_credit::text,l.base_debit::text,l.base_credit::text,
   (l.base_debit-l.base_credit)::numeric(20,6)::text posted_base
  from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date<=d and l.account_id=any(ids)
   and (filter_branch is null or l.branch_id=filter_branch) order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='TAX_CONTROL_JOURNAL_LIMIT';end if;
 with entries as (
  select (x->>'account_id')::uuid id,(x->>'expected_base')::numeric v,0::numeric g,x->>'phase' phase
   from jsonb_array_elements(sources)x where x->>'account_id' is not null
  union all select (x->>'account_id')::uuid,0,(x->>'posted_base')::numeric,x->>'phase' from jsonb_array_elements(journals)x),
 totals as(select id,coalesce(sum(v) filter(where phase='opening'),0) so,coalesce(sum(g) filter(where phase='opening'),0) go,
  coalesce(sum(v) filter(where phase='period'),0) sp,coalesce(sum(g) filter(where phase='period'),0) gp from entries group by id)
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'account_id',a.id,'code',a.code,'name',a.name,'account_type',a.account_type,
  'source_opening_base',coalesce(so,0)::numeric(20,6)::text,'gl_opening_base',coalesce(go,0)::numeric(20,6)::text,
  'source_period_base',coalesce(sp,0)::numeric(20,6)::text,'gl_period_base',coalesce(gp,0)::numeric(20,6)::text,
  'source_closing_base',(coalesce(so,0)+coalesce(sp,0))::numeric(20,6)::text,
  'gl_closing_base',(coalesce(go,0)+coalesce(gp,0))::numeric(20,6)::text,
  'difference',(coalesce(so,0)+coalesce(sp,0)-coalesce(go,0)-coalesce(gp,0))::numeric(20,6)::text) order by a.id),'[]') into controls
 from finance.accounts a left join totals using(id) where a.tenant_id=t and a.legal_entity_id=e and a.id=any(ids);
 with entries as (
  select x->>'account_id' account_id,x->>'evidence_key' k,(x->>'expected_base')::numeric v,0::numeric g
   from jsonb_array_elements(sources)x
  union all select x->>'account_id',x->>'evidence_key',0,(x->>'posted_base')::numeric from jsonb_array_elements(journals)x),
 totals as(select account_id,k,sum(v) v,sum(g) g from entries group by account_id,k)
 select coalesce(jsonb_agg(jsonb_build_object('id',coalesce(account_id,'unassigned')||':'||k,'account_id',account_id,
  'evidence_key',k,'expected_base',v::numeric(20,6)::text,'posted_base',g::numeric(20,6)::text,
  'difference',(v-g)::numeric(20,6)::text) order by account_id,k),'[]') into diffs from totals where v<>g;
 if jsonb_array_length(diffs)>10000 then raise exception using errcode='54000',message='TAX_CONTROL_DIFFERENCE_LIMIT';end if;
 select count(*) filter(where x->>'account_id' is null),count(*) filter(where x->>'review_code' is not null)
  into unassigned,reviews from jsonb_array_elements(sources)x;
 select count(*) into unattributed from jsonb_array_elements(journals)x where (x->>'posted_base')::numeric<>0
  and not exists(select 1 from jsonb_array_elements(sources)s where s->>'evidence_key'=x->>'evidence_key' and s->>'account_id'=x->>'account_id');
 select coalesce(sum((x->>'source_closing_base')::numeric),0),coalesce(sum((x->>'gl_closing_base')::numeric),0)
  into source_total,gl_total from jsonb_array_elements(controls)x;
 summary:=jsonb_build_object('id',p->>'id','version',2,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'period_id',period.id,'period_start',period.start_date,'period_end',period.end_date,'as_of',d,
  'branch_filter_id',filter_branch,'base_currency_code',(select currency_code from core.legal_entities where tenant_id=t and id=e),
  'generated_at',statement_timestamp(),'status',case when blocked_count>0 or jsonb_array_length(diffs)>0 or reviews>0 then 'blocked' else 'generated' end,
  'notice','NON-CERTIFIED • STATUTORY REVIEW REQUIRED','line_count',line_count,'blocked_count',blocked_count,'blockers',blockers,
  'output_tax_base',output_base::numeric(20,6)::text,'input_tax_base',input_base::numeric(20,6)::text,
  'withholding_tax_base',withholding_base::numeric(20,6)::text,'zero_taxable_base',zero_base::numeric(20,6)::text,'exempt_taxable_base',exempt_base::numeric(20,6)::text,
  'unverified_tax_base',unverified::numeric(20,6)::text,'controls',controls,
  'control_status',case when jsonb_array_length(diffs)>0 or reviews>0 then 'blocked' else 'reconciled' end,
  'control_source_count',jsonb_array_length(sources),'control_journal_count',jsonb_array_length(journals),
  'control_difference_count',jsonb_array_length(diffs),'control_review_count',reviews,
  'control_unassigned_source_count',unassigned,'unattributed_journal_count',unattributed,
  'control_source_base',source_total::numeric(20,6)::text,'control_gl_base',gl_total::numeric(20,6)::text,
  'control_difference',(source_total-gl_total)::numeric(20,6)::text);
 result:=jsonb_build_object('summary',summary,'lines',line_rows,'controls',controls,
  'control_sources',sources,'control_journals',journals,'control_differences',diffs);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='TAX_REPORT_EVIDENCE_LIMIT';end if;
 return result;
end$$;
revoke all on function finance.build_tax_summary(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

notify pgrst,'reload schema';

-- Unapplied additive candidate. No replacement of immutable posting history.
alter table procurement.goods_receipts add column grni_account_id uuid;
alter table procurement.goods_receipts add constraint goods_receipts_grni_basis_fk
 foreign key(tenant_id,legal_entity_id,grni_account_id) references finance.accounts(tenant_id,legal_entity_id,id);
create index goods_receipts_grni_basis_idx on procurement.goods_receipts(tenant_id,legal_entity_id,grni_account_id);
create function procurement.freeze_receipt_grni_basis() returns trigger
language plpgsql security definer set search_path='' as $$declare ids uuid[];begin
 if new.base_amount<>0 or new.net_amount<>0 then
  select array_agg(q.account_id) into ids from (
   select l.account_id from finance.journal_lines l where l.tenant_id=new.tenant_id
    and l.journal_entry_id=new.journal_entry_id and l.source_line_id is null
   group by l.account_id having sum(l.base_credit-l.base_debit)=new.base_amount
    and sum(l.transaction_credit-l.transaction_debit)=new.net_amount)q;
  if coalesce(cardinality(ids),0)<>1 then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
  new.grni_account_id:=ids[1];
 else
  select grni_account_id into new.grni_account_id from procurement.receipt_controls
  where tenant_id=new.tenant_id and legal_entity_id=new.legal_entity_id;
 end if;
 if new.grni_account_id is null then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
 return new;end $$;
revoke all on function procurement.freeze_receipt_grni_basis() from public,anon,authenticated;
create trigger freeze_grni_basis before insert on procurement.goods_receipts
 for each row execute function procurement.freeze_receipt_grni_basis();

create function finance.receipt_grni_control(t uuid,i uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare r procurement.goods_receipts%rowtype;ids uuid[];begin
 select * into r from procurement.goods_receipts where tenant_id=t and id=i;
 if r.grni_account_id is not null then return r.grni_account_id;end if;
 if r.base_amount=0 and r.net_amount=0 then return null;end if;
 select array_agg(q.account_id) into ids from (
  select l.account_id from finance.journal_lines l
  where l.tenant_id=t and l.journal_entry_id=r.journal_entry_id and l.source_line_id is null
  group by l.account_id having sum(l.base_credit-l.base_debit)=r.base_amount
   and sum(l.transaction_credit-l.transaction_debit)=r.net_amount
 )q;
 if coalesce(cardinality(ids),0)<>1 then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
 return ids[1];end $$;
revoke all on function finance.receipt_grni_control(uuid,uuid) from public,anon,authenticated;

alter function finance.build_control_report(uuid,uuid,uuid,jsonb) rename to build_ar_ap_control_report_v1;
create function finance.build_control_report(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d date:=(p->>'as_of')::date;receipts jsonb;matches jsonb;returns jsonb;reversals jsonb;
 items jsonb;entries jsonb;journals jsonb;accounts jsonb;differences jsonb;result jsonb;
 ids uuid[];sv numeric;gv numeric;begin
 if p->>'kind' is distinct from 'GRNI' then return finance.build_ar_ap_control_report_v1(t,e,b,p);end if;
 perform finance.require_control_scope(t,e,b);
 if d is null or d>(statement_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='CONTROL_REPORT_INPUT_INVALID';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into receipts from (
  select r.id,r.id receipt_id,'goods_receipt'::text source_type,r.id source_id,r.command_id,r.journal_entry_id,
   r.document_number,r.document_date posting_date,r.currency_code,r.base_currency_code,
   r.source_snapshot->>'supplier_id' party_id,coalesce(r.source_snapshot->>'supplier_name',party.display_name,'Supplier') party_name,
   finance.receipt_grni_control(t,r.id)::text evidence_key,r.net_amount::text original_amount,r.base_amount::text original_base_amount
  from procurement.goods_receipts r left join crm.parties party on party.id=(r.source_snapshot->>'supplier_id')::uuid and party.tenant_id=r.tenant_id
  where r.tenant_id=t and r.legal_entity_id=e and r.branch_id=b and r.document_date<=d order by r.id limit 10001)q;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into matches from (
  select l.id,r.id receipt_id,'supplier_bill'::text source_type,h.id source_id,h.document_date posting_date,h.document_number,
   h.journal_entry_id,j.command_id,l.detail->>'grni_account_id' evidence_key,
   l.detail->>'accrual_amount' amount,l.detail->>'accrual_base_amount' base_amount
  from procurement.supplier_bill_lines l join procurement.supplier_bills h on h.id=l.bill_id and h.tenant_id=l.tenant_id
  join procurement.goods_receipt_lines rl on rl.id=l.receipt_line_id and rl.tenant_id=l.tenant_id
  join procurement.goods_receipts r on r.id=rl.receipt_id and r.tenant_id=l.tenant_id
  left join finance.journal_entries j on j.id=h.journal_entry_id and j.tenant_id=h.tenant_id
  where h.tenant_id=t and h.legal_entity_id=e and h.branch_id=b and h.status='posted' and h.document_date<=d
   and r.document_date<=d order by l.id limit 10001)q;
 if exists(select 1 from jsonb_array_elements(matches)x where x->>'evidence_key' is null or x->>'amount' is null or x->>'base_amount' is null)
 then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into returns from (
  select h.id,r.id receipt_id,'purchase_return'::text source_type,h.id source_id,h.document_date posting_date,h.document_number,
   h.journal_entry_id,h.command_id,finance.receipt_grni_control(t,r.id)::text evidence_key,h.total::text amount,h.base_total::text base_amount
  from procurement.purchase_returns h join procurement.goods_receipts r on r.id=h.source_id and r.tenant_id=h.tenant_id
  where h.tenant_id=t and h.legal_entity_id=e and h.branch_id=b and h.source_kind='receipt' and h.document_date<=d and r.document_date<=d order by h.id limit 10001)q;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into reversals from (
  select h.id,r.id receipt_id,'goods_receipt_reversal'::text source_type,h.id source_id,h.document_date posting_date,
   h.journal_entry_id,h.command_id,finance.receipt_grni_control(t,r.id)::text evidence_key,r.net_amount::text amount,r.base_amount::text base_amount
  from procurement.goods_receipt_reversals h join procurement.goods_receipts r on r.id=h.receipt_id and r.tenant_id=h.tenant_id
  where h.tenant_id=t and h.legal_entity_id=e and h.branch_id=b and h.document_date<=d and r.document_date<=d order by h.id limit 10001)q;
 if greatest(jsonb_array_length(receipts),jsonb_array_length(matches),jsonb_array_length(returns),jsonb_array_length(reversals))>10000
 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 with movements as (
  select x,1 sgn,x->>'original_amount' amount,x->>'original_base_amount' base from jsonb_array_elements(receipts)x
  union all select x,-1,x->>'amount',x->>'base_amount' from jsonb_array_elements(matches)x
  union all select x,-1,x->>'amount',x->>'base_amount' from jsonb_array_elements(returns)x
  union all select x,-1,x->>'amount',x->>'base_amount' from jsonb_array_elements(reversals)x)
 select coalesce(jsonb_agg(x||jsonb_build_object('id',(x->>'source_type')||':'||(x->>'id'),
  'transaction_value',(sgn*amount::numeric)::text,'value',(sgn*base::numeric)::text) order by x->>'source_type',x->>'id'),'[]') into entries
 from movements where x->>'evidence_key' is not null;
 with residuals as (
  select z->>'receipt_id' id,sum((z->>'transaction_value')::numeric)a,sum((z->>'value')::numeric)v
  from jsonb_array_elements(entries)z group by z->>'receipt_id')
 select coalesce(jsonb_agg(x||jsonb_build_object('settled_amount',((x->>'original_amount')::numeric-coalesce(a,0))::text,
  'settled_base_amount',((x->>'original_base_amount')::numeric-coalesce(v,0))::text,
  'open_amount',coalesce(a,0)::text,'open_base_amount',coalesce(v,0)::text) order by x->>'id'),'[]') into items
 from jsonb_array_elements(receipts)x left join residuals tot on tot.id=x->>'id';
 select array_agg(distinct id order by id) into ids from (
  select (x->>'evidence_key')::uuid id from jsonb_array_elements(entries)x
  union select grni_account_id from procurement.receipt_controls where tenant_id=t and legal_entity_id=e
  union select (snapshot->>'grni_account_id')::uuid from procurement.receipt_control_history where tenant_id=t and legal_entity_id=e)a where id is not null;
 if coalesce(cardinality(ids),0) not between 1 and 50 then raise exception using errcode='55000',message='CONTROL_ACCOUNT_SETUP_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id::text evidence_key,a.code account_code,j.command_id,j.id journal_id,j.document_number,j.source_type,j.source_id,l.source_line_id,l.posting_date,
   (l.base_credit-l.base_debit)::text value,l.base_debit::text,l.base_credit::text
  from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id and j.tenant_id=l.tenant_id
  join finance.accounts a on a.id=l.account_id and a.tenant_id=l.tenant_id
  where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.account_id=any(ids) and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select jsonb_agg(jsonb_build_object('id',a.id,'evidence_key',a.id,'code',a.code,'name',a.name,
  'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a.id) into accounts from finance.accounts a
 cross join lateral(select coalesce(sum((x->>'value')::numeric),0)v from jsonb_array_elements(entries)x where x->>'evidence_key'=a.id::text)s
 cross join lateral(select coalesce(sum((x->>'value')::numeric),0)g from jsonb_array_elements(journals)x where x->>'evidence_key'=a.id::text)j
 where a.tenant_id=t and a.legal_entity_id=e and a.id=any(ids);
 if jsonb_array_length(accounts)<>cardinality(ids) then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
 with effects as (
  select x->>'evidence_key' a,x->>'source_type' st,x->>'source_id' si,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(entries)x
  union all select x->>'evidence_key',x->>'source_type',x->>'source_id',0,(x->>'value')::numeric from jsonb_array_elements(journals)x),
 totals as(select a,st,si,sum(v)v,sum(g)g from effects group by a,st,si)
 select coalesce(jsonb_agg(jsonb_build_object('id',a||':'||st||':'||si,'evidence_key',a,'source_type',st,'source_id',si,
  'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a,st,si),'[]') into differences from totals where v<>g;
 if greatest(jsonb_array_length(entries),jsonb_array_length(differences))>50000 then raise exception using errcode='54000',message='CONTROL_REPORT_OUTPUT_LIMIT';end if;
 select coalesce(sum((x->>'subledger_value')::numeric),0),coalesce(sum((x->>'gl_value')::numeric),0) into sv,gv from jsonb_array_elements(accounts)x;
 if sv<>(select coalesce(sum((x->>'open_base_amount')::numeric),0) from jsonb_array_elements(items)x)
 then raise exception using errcode='23514',message='CONTROL_RESIDUAL_DIVERGENCE';end if;
 result:=jsonb_build_object('summary',jsonb_build_object('id',p->>'id','version',1,'status','generated','kind','GRNI','as_of',d,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'entity_name',(select name from core.legal_entities where id=e),'branch_name',(select name from core.branches where id=b),
  'currency_code',(select currency_code from core.legal_entities where id=e),'generated_at',statement_timestamp(),'accounts',accounts,
  'subledger_value',sv::text,'gl_value',gv::text,'difference',(sv-gv)::text,'item_count',jsonb_array_length(items),'difference_count',jsonb_array_length(differences)),
  'items',items,'allocations','[]'::jsonb,'entries',entries,'journals',journals,'accounts',accounts,'differences',differences);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='CONTROL_REPORT_EVIDENCE_LIMIT';end if;
 return result;end $$;
revoke all on function finance.build_control_report(uuid,uuid,uuid,jsonb),finance.build_ar_ap_control_report_v1(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive candidate. Existing immutable ledgers and posting engines.
create table finance.close_control_reviews (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 period_id uuid not null,as_of date not null,generated_at timestamptz not null,
 summary jsonb not null,evidence jsonb not null,created_by uuid not null references auth.users(id),
 unique(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(period_id) references finance.fiscal_periods(id),
 check(octet_length(evidence::text)<=16777216)
);
alter table finance.close_control_reviews enable row level security;
alter table finance.close_control_reviews force row level security;
revoke all on finance.close_control_reviews from public,anon,authenticated;
create trigger immutable before update or delete on finance.close_control_reviews
 for each row execute function workflow.reject_history_mutation();
create index close_reviews_scope on finance.close_control_reviews(tenant_id,legal_entity_id,id);
create index close_reviews_branch on finance.close_control_reviews(tenant_id,branch_id);
create index close_reviews_period on finance.close_control_reviews(period_id);
create index close_reviews_actor on finance.close_control_reviews(created_by);

create function finance.require_close_review_scope(t uuid,e uuid,b uuid) returns void
language plpgsql stable security definer set search_path='' as $$declare r record;begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.controls.reconcile',e,null);
 perform inventory.require_valuation_report_scope(t,e,b);
 for r in select id from core.branches where tenant_id=t and legal_entity_id=e order by id loop
  perform finance.require_control_scope(t,e,r.id);
 end loop;
end $$;

create function finance.close_inventory_accounts(t uuid,e uuid,d date) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare ids jsonb;begin
 select coalesce(jsonb_agg(id order by id),'[]') into ids from (
  select inventory_account_id id from inventory.products where tenant_id=t and legal_entity_id=e
  union
  select l.account_id from finance.journal_lines l join finance.journal_entries j
   on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id and a.account_type='asset'
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date<=d
   and exists(select 1 from inventory.stock_movements m where m.tenant_id=t and m.legal_entity_id=e
    and m.command_id=j.command_id and (j.source_type=m.source_type or j.source_type=m.source_type||'.stock'))
 )q where id is not null;
 if jsonb_array_length(ids)>50 then raise exception using errcode='54000',message='CLOSE_INVENTORY_ACCOUNT_LIMIT';end if;
 return ids;
end $$;

-- Cutoff match memberships are immutable; current claim indexes are not history.
create function finance.build_cash_controls(t uuid,e uuid,d date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare bank record;statement finance.bank_statements%rowtype;gl jsonb;sl jsonb;rows jsonb:='[]';sources jsonb:='[]';
 book numeric;ug numeric;us numeric;sv numeric;bad integer;n integer:=0;status text;base text;begin
 select currency_code into base from core.legal_entities where tenant_id=t and id=e;
 for bank in select * from finance.cash_bank_accounts where tenant_id=t and legal_entity_id=e order by id loop
  n:=n+1;if n>500 then raise exception using errcode='54000',message='CLOSE_CASH_ACCOUNT_LIMIT';end if;
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into gl from (
   select l.id,j.id journal_id,j.command_id,j.source_type,j.source_id,l.posting_date,bank.id bank_id,
    bank.branch_id branch_id,bank.currency_code currency_code,
    (case when bank.currency_code=base then l.base_debit-l.base_credit
     else l.transaction_debit-l.transaction_credit end)::text value,
    (bank.currency_code<>base and j.currency_code<>bank.currency_code) invalid_currency,
    exists(select 1 from finance.bank_matches m where m.tenant_id=t and l.id=any(m.journal_line_ids)
     and m.posting_date<=d and not exists(select 1 from finance.bank_match_reversals r
      where r.tenant_id=t and r.match_id=m.id and r.posting_date<=d)) matched
   from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
   where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=bank.branch_id
    and l.account_id=bank.account_id and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into sl from (
   select l.id,l.statement_id,l.bank_id,l.posting_date,bank.branch_id branch_id,bank.currency_code currency_code,
    l.reference,l.amount::text value,'bank_statement_line'::text source_type,l.id source_id,
    exists(select 1 from finance.bank_matches m where m.tenant_id=t and l.id=any(m.statement_line_ids)
     and m.posting_date<=d and not exists(select 1 from finance.bank_match_reversals r
      where r.tenant_id=t and r.match_id=m.id and r.posting_date<=d)) matched
   from finance.bank_statement_lines l join finance.bank_statements s on s.tenant_id=l.tenant_id and s.id=l.statement_id
   where l.tenant_id=t and l.bank_id=bank.id and l.posting_date<=d and s.end_date<=d
   order by l.id limit 10001)q;
  if greatest(jsonb_array_length(gl),jsonb_array_length(sl))>10000 then raise exception using errcode='54000',message='CLOSE_CASH_INPUT_LIMIT';end if;
  select coalesce(sum((x->>'value')::numeric),0),coalesce(sum((x->>'value')::numeric) filter(where not (x->>'matched')::boolean),0),
   count(*) filter(where (x->>'invalid_currency')::boolean) into book,ug,bad from jsonb_array_elements(gl)x;
  select coalesce(sum((x->>'value')::numeric) filter(where not (x->>'matched')::boolean),0) into us from jsonb_array_elements(sl)x;
  select * into statement from finance.bank_statements where tenant_id=t and bank_id=bank.id and end_date<=d
   order by end_date desc,created_at desc,id desc limit 1;
  sv:=coalesce(statement.closing,0)-us+ug;
  status:=case when bank.account_kind='cash' then 'ledger_only'
   when bad>0 then 'currency_basis_invalid'
   when exists(select 1 from finance.cash_bank_accounts cb where cb.tenant_id=t and cb.legal_entity_id=e
    and cb.branch_id=bank.branch_id and cb.account_id=bank.account_id and cb.currency_code=bank.currency_code
    and cb.id<>bank.id and (cb.status='active' or exists(select 1 from finance.bank_statements bs where bs.tenant_id=t and bs.bank_id=cb.id))) then 'ambiguous_basis'
   when statement.id is null or statement.end_date<>d then 'statement_coverage_required'
   when sv<>book then 'difference' else 'reconciled' end;
  rows:=rows||jsonb_build_array(jsonb_build_object('id','cash:'||bank.id,'component_key','cash:'||bank.id,
   'kind','CASH','branch_id',bank.branch_id,'name',bank.name,'currency_code',bank.currency_code,'status',status,
   'accounts',jsonb_build_array(jsonb_build_object('id',bank.account_id,'code',bank.code,'name',bank.name)),
   'subledger_value',case when bank.account_kind='cash' then book::text else sv::text end,'gl_value',book::text,
   'difference',case when bank.account_kind='cash' then '0' else (sv-book)::text end,
   'difference_count',case when status in('reconciled','ledger_only') then 0 else 1 end,
   'statement_id',statement.id,'statement_end',statement.end_date,'statement_closing',coalesce(statement.closing,0)::text,
   'unmatched_book',ug::text,'unmatched_bank',us::text));
  select sources||coalesce(jsonb_agg(x||jsonb_build_object('id','cash:'||bank.id||':'||(x->>'id'),
   'component_key','cash:'||bank.id,'origin','journal') order by x->>'id'),'[]') into sources from jsonb_array_elements(gl)x;
  select sources||coalesce(jsonb_agg(x||jsonb_build_object('id','bank:'||bank.id||':'||(x->>'id'),
   'component_key','cash:'||bank.id,'origin','bank') order by x->>'id'),'[]') into sources from jsonb_array_elements(sl)x;
  if jsonb_array_length(sources)>50000 then raise exception using errcode='54000',message='CLOSE_REVIEW_OUTPUT_LIMIT';end if;
 end loop;
 return jsonb_build_object('controls',rows,'sources',sources);
end $$;

-- Preserve all previous close checks and add live inventory, GRNI and bank basis.
alter function finance.period_close_exceptions(uuid,uuid,finance.fiscal_periods) rename to period_close_exceptions_before_controls;
-- These helpers only read. Freeze the complete nested report graph to one MVCC
-- statement snapshot; the hard-close command still calls it after period locking.
alter function finance.period_close_exceptions_before_controls(uuid,uuid,finance.fiscal_periods) stable;
alter function finance.period_close_exceptions_before_tax(uuid,uuid,finance.fiscal_periods) stable;
alter function finance.period_close_exceptions_before_cash_flow(uuid,uuid,finance.fiscal_periods) stable;
create function finance.period_close_exceptions(t uuid,e uuid,p finance.fiscal_periods) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare issues jsonb;branch record;data jsonb;ids jsonb;row jsonb;b uuid;begin
 issues:=finance.period_close_exceptions_before_controls(t,e,p);
 for branch in select id from core.branches where tenant_id=t and legal_entity_id=e order by id loop
  begin
   data:=finance.build_control_report(t,e,branch.id,jsonb_build_object('kind','GRNI','as_of',p.end_date,'id',gen_random_uuid()));
   if (data#>>'{summary,difference_count}')::integer>0 then
    issues:=issues||jsonb_build_array(jsonb_build_object('code','GRNI_CONTROL_DIFFERENCE','branch_id',branch.id,
     'count',data#>'{summary,difference_count}','difference',data#>'{summary,difference}'));end if;
  exception when others then
   issues:=issues||jsonb_build_array(jsonb_build_object('code','GRNI_CONTROL_CHECK_FAILED','branch_id',branch.id,'sqlstate',sqlstate));
  end;
 end loop;
 begin
  ids:=finance.close_inventory_accounts(t,e,p.end_date);
  if jsonb_array_length(ids)>0 then
   select id into b from core.branches where tenant_id=t and legal_entity_id=e order by id limit 1;
   data:=inventory.build_valuation_report(t,e,b,jsonb_build_object('id',gen_random_uuid(),'as_of',p.end_date,'account_ids',ids));
   if (data#>>'{summary,difference_count}')::integer>0 or exists(select 1 from jsonb_array_elements(data->'stock')x where x->>'exception' is not null) then
    issues:=issues||jsonb_build_array(jsonb_build_object('code','INVENTORY_CONTROL_DIFFERENCE','difference',data#>'{summary,difference}',
     'count',data#>'{summary,difference_count}','accounts',data#>'{summary,accounts}'));end if;
  elsif exists(select 1 from inventory.stock_movements where tenant_id=t and legal_entity_id=e and posting_date<=p.end_date) then
   issues:=issues||jsonb_build_array(jsonb_build_object('code','INVENTORY_CONTROL_BASIS_REQUIRED'));
  end if;
 exception when others then issues:=issues||jsonb_build_array(jsonb_build_object('code','INVENTORY_CONTROL_CHECK_FAILED','sqlstate',sqlstate));end;
 begin
  data:=finance.build_cash_controls(t,e,p.end_date);
  for row in select value from jsonb_array_elements(data->'controls') loop
   if (row->>'difference_count')::integer>0 then
    issues:=issues||jsonb_build_array(jsonb_build_object('code','CASH_CONTROL_BLOCKED','component_key',row->>'id',
     'reason',row->>'status','difference',row->>'difference'));end if;
  end loop;
 exception when others then issues:=issues||jsonb_build_array(jsonb_build_object('code','CASH_CONTROL_CHECK_FAILED','sqlstate',sqlstate));end;
 if jsonb_array_length(issues)>50000 or octet_length(issues::text)>16777216 then
  raise exception using errcode='54000',message='CLOSE_REVIEW_OUTPUT_LIMIT';end if;
 return issues;
end $$;

create function finance.build_close_control_review(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare period finance.fiscal_periods%rowtype;d date:=(p->>'as_of')::date;branch record;k text;key text;data jsonb;row jsonb;
 controls jsonb:='[]';diffs jsonb:='[]';sources jsonb:='[]';stock jsonb:='[]';transit jsonb:='[]';issues jsonb;ids jsonb;
 result jsonb;fxdiff jsonb;begin
 perform finance.require_close_review_scope(t,e,b);
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e and id=(p->>'period_id')::uuid and status='active';
 if period.id is null or d is null or d not between period.start_date and period.end_date
  or d>(statement_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='CLOSE_REVIEW_INPUT_INVALID';end if;
 -- Close exceptions use this review cutoff; no premature period-end evidence.
 period.end_date:=d;issues:=finance.period_close_exceptions(t,e,period);
 for branch in select id,name from core.branches where tenant_id=t and legal_entity_id=e order by id loop
  foreach k in array array['AR','AP','GRNI'] loop
   key:=k||':'||branch.id;
   begin
    data:=finance.build_control_report(t,e,branch.id,jsonb_build_object('id',gen_random_uuid(),'kind',k,'as_of',d));
    if k in('AR','AP') then
     select coalesce(jsonb_agg(x||jsonb_build_object('id',(x->>'evidence_key')||':'||coalesce(x->>'command_id','none'),
      'difference',x->'unexplained_difference') order by x->>'evidence_key',x->>'command_id'),'[]') into fxdiff
     from jsonb_array_elements(finance.period_control_fx_variance(t,e,branch.id,k,d,data))x;
    else fxdiff:=data->'differences';end if;
    row:=data->'summary'||jsonb_build_object('id',key,'component_key',key,'name',k||' · '||branch.name,
     'difference_count',jsonb_array_length(fxdiff),'status',case when jsonb_array_length(fxdiff)=0 then 'reconciled' else 'difference' end);
    controls:=controls||jsonb_build_array(row);
    select diffs||coalesce(jsonb_agg(x||jsonb_build_object('id',key||':'||(x->>'id'),'component_key',key) order by x->>'id'),'[]') into diffs from jsonb_array_elements(fxdiff)x;
    select sources||coalesce(jsonb_agg(x||jsonb_build_object('id',key||':source:'||(x->>'id'),'component_key',key,'origin','subledger') order by x->>'id'),'[]') into sources from jsonb_array_elements(data->'entries')x;
    select sources||coalesce(jsonb_agg(x||jsonb_build_object('id',key||':journal:'||(x->>'id'),'component_key',key,'origin','journal') order by x->>'id'),'[]') into sources from jsonb_array_elements(data->'journals')x;
   exception when sqlstate '22023' or sqlstate '55000' then
    controls:=controls||jsonb_build_array(jsonb_build_object('id',key,'component_key',key,'kind',k,'name',k||' · '||branch.name,
     'branch_id',branch.id,'currency_code',(select currency_code from core.legal_entities where tenant_id=t and id=e),
     'status','unavailable','reason',sqlerrm,'difference_count',1,'accounts','[]'::jsonb));
    issues:=issues||jsonb_build_array(jsonb_build_object('code',k||'_CONTROL_CHECK_FAILED','component_key',key,'sqlstate',sqlstate));
   end;
  end loop;
 end loop;
 ids:=finance.close_inventory_accounts(t,e,d);
 if jsonb_array_length(ids)>0 then
  data:=inventory.build_valuation_report(t,e,b,jsonb_build_object('id',gen_random_uuid(),'as_of',d,'account_ids',ids));
  row:=data->'summary'||jsonb_build_object('id','INVENTORY','component_key','INVENTORY','kind','INVENTORY','name','Entity inventory including transit',
   'subledger_value',data#>'{summary,inventory_value}','status',case when (data#>>'{summary,difference_count}')::integer=0 then 'reconciled' else 'difference' end);
  controls:=controls||jsonb_build_array(row);stock:=data->'stock';transit:=data->'transit';
  select diffs||coalesce(jsonb_agg(x||jsonb_build_object('id','INVENTORY:'||(x->>'id'),'component_key','INVENTORY',
   'subledger_value',x->'inventory_value') order by x->>'id'),'[]') into diffs from jsonb_array_elements(data->'differences')x;
  select sources||coalesce(jsonb_agg(x||jsonb_build_object('id','INVENTORY:stock:'||(x->>'id'),'component_key','INVENTORY','origin','stock') order by x->>'id'),'[]') into sources from jsonb_array_elements(data->'movements')x;
  select sources||coalesce(jsonb_agg(x||jsonb_build_object('id','INVENTORY:journal:'||(x->>'id'),'component_key','INVENTORY','origin','journal') order by x->>'id'),'[]') into sources from jsonb_array_elements(data->'journals')x;
 end if;
 data:=finance.build_cash_controls(t,e,d);controls:=controls||(data->'controls');sources:=sources||(data->'sources');
 for row in select value from jsonb_array_elements(data->'controls') loop
  if (row->>'difference_count')::integer>0 then diffs:=diffs||jsonb_build_array(row);end if;
 end loop;
 select coalesce(jsonb_agg(x||jsonb_build_object('id','issue:'||ord) order by ord),'[]') into issues from jsonb_array_elements(issues) with ordinality q(x,ord);
 if greatest(jsonb_array_length(controls),jsonb_array_length(diffs),jsonb_array_length(sources),jsonb_array_length(stock),jsonb_array_length(transit),jsonb_array_length(issues))>50000 then
  raise exception using errcode='54000',message='CLOSE_REVIEW_OUTPUT_LIMIT';end if;
 result:=jsonb_build_object('summary',jsonb_build_object('id',p->>'id','version',1,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'entity_name',(select name from core.legal_entities where tenant_id=t and id=e),'currency_code',(select currency_code from core.legal_entities where tenant_id=t and id=e),
  'period_id',period.id,'period_name',period.name,'period_version',period.version,'period_state',period.state,'period_start',period.start_date,'as_of',d,
  'generated_at',statement_timestamp(),'scope','all_entity_branches','status',case when jsonb_array_length(issues)=0 and jsonb_array_length(diffs)=0 then 'ready' else 'blocked' end,
  'control_count',jsonb_array_length(controls),'difference_count',jsonb_array_length(diffs),'blocker_count',jsonb_array_length(issues),
  'branch_count',(select count(*) from core.branches where tenant_id=t and legal_entity_id=e),
  'branches',(select jsonb_agg(jsonb_build_object('id',id,'name',name,'status',status) order by id) from core.branches where tenant_id=t and legal_entity_id=e)),
  'controls',controls,'differences',diffs,'sources',sources,'stock',stock,'transit',transit,'blockers',issues);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='CLOSE_REVIEW_EVIDENCE_LIMIT';end if;
 return result;
end $$;

create function api.generate_close_control_review(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$declare h text;r jsonb;data jsonb;s jsonb;id uuid:=(p_payload->>'id')::uuid;req uuid:=gen_random_uuid();begin
 perform finance.require_close_review_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if id is null or p_client_timestamp is null then raise exception using errcode='22023',message='CLOSE_REVIEW_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('finance.close.review',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.close.review',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 data:=finance.build_close_control_review(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);s:=data->'summary';
 insert into finance.close_control_reviews values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(s->>'period_id')::uuid,
  (s->>'as_of')::date,(s->>'generated_at')::timestamptz,s,data,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'finance.close.review',p_command_id,'close_control_review',id,p_idempotency_key,h,null,s,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status',s->>'status'),
  jsonb_build_array(jsonb_build_object('topic','finance.close.reviewed','payload',s)),'[]',req,req);
end $$;
create function api.close_control_reviews(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform finance.require_close_review_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(summary order by id),'[]') into rows from(select id,summary from finance.close_control_reviews
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and(p_after is null or id>p_after) order by id limit 51)q;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor);
end $$;
create function api.close_control_review_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,
 p_section text,p_after integer default 0,p_component_key text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare r finance.close_control_reviews%rowtype;rows jsonb;n integer;begin
 perform finance.require_close_review_scope(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_section not in('controls','differences','sources','stock','transit','blockers') or p_section is null
  or p_after is null or p_after<0 or p_after>50000 then raise exception using errcode='22023',message='CLOSE_REVIEW_PAGE_INVALID';end if;
 select * into r from finance.close_control_reviews where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and id=p_id;
 if not found then raise exception using errcode='42501',message='CLOSE_REVIEW_SCOPE_REQUIRED';end if;
 if p_component_key is not null and (p_section in('stock','transit') or not exists(select 1 from jsonb_array_elements(r.evidence->'controls')x where x->>'id'=p_component_key)) then
  raise exception using errcode='22023',message='CLOSE_REVIEW_COMPONENT_INVALID';end if;
 select count(*) into n from jsonb_array_elements(r.evidence->p_section)x where p_component_key is null or x->>'component_key'=p_component_key;
 select coalesce(jsonb_agg(x order by ord),'[]') into rows from(select x,ord from jsonb_array_elements(r.evidence->p_section) with ordinality q(x,ord)
  where p_component_key is null or x->>'component_key'=p_component_key order by ord offset p_after limit 50)q;
 return jsonb_build_object('summary',r.summary,'section',p_section,'component_key',p_component_key,'items',rows,
  'next_cursor',case when n>p_after+50 then (p_after+50)::text end);
end $$;
revoke all on function finance.require_close_review_scope(uuid,uuid,uuid),finance.close_inventory_accounts(uuid,uuid,date),
 finance.build_cash_controls(uuid,uuid,date),finance.period_close_exceptions_before_controls(uuid,uuid,finance.fiscal_periods),
 finance.period_close_exceptions(uuid,uuid,finance.fiscal_periods),finance.build_close_control_review(uuid,uuid,uuid,jsonb),
 api.generate_close_control_review(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.close_control_reviews(uuid,uuid,uuid,uuid),
 api.close_control_review_page(uuid,uuid,uuid,uuid,text,integer,text) from public,anon,authenticated;
grant execute on function api.generate_close_control_review(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.close_control_reviews(uuid,uuid,uuid,uuid),api.close_control_review_page(uuid,uuid,uuid,uuid,text,integer,text) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED. Private saved evidence only; never arbitrary tables or client rows.
insert into core.permissions(code,module,description,privileged) values
 ('finance.reports.export','finance','Export scoped frozen financial and inventory evidence.',false) on conflict(code) do nothing;

create function finance.report_export_document(t uuid,e uuid,b uuid,resource text,i uuid,section text,filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare probe jsonb;data jsonb;rows jsonb;meta jsonb;allowed text[];k text;v jsonb;result jsonb;begin
 perform core.wave3_require_scope(t,'finance.reports.export',e,null);
 perform core.wave3_require_scope(t,'finance.reports.export',e,b);
 if i is null or jsonb_typeof(filters) is distinct from 'object' then raise exception using errcode='22023',message='REPORT_EXPORT_INPUT_INVALID';end if;
 allowed:=case resource when 'statement' then array['account_id'] when 'control' then array['evidence_key']
  when 'inventory' then array['evidence_key'] when 'tax' then array['account_id','evidence_key','source_line_id']
  when 'budget' then array['budget_line_id'] when 'close' then array['component_key'] else null end;
 if allowed is null then raise exception using errcode='22023',message='REPORT_EXPORT_SOURCE_INVALID';end if;
 for k,v in select * from jsonb_each(filters) loop
  if not k=any(allowed) or (v<>'null'::jsonb and (jsonb_typeof(v)<>'string' or length(v#>>'{}')>220)) then
   raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
 end loop;
 case resource
 when 'statement' then
  probe:=api.financial_statement_page(t,e,b,i,section,0,(filters->>'account_id')::uuid);
  select evidence into data from finance.financial_reports where tenant_id=t and legal_entity_id=e and id=i;
 when 'control' then
  probe:=api.control_reconciliation_report_page(t,e,b,i,section,0,filters->>'evidence_key');
  select evidence into data from finance.control_reports where tenant_id=t and legal_entity_id=e and branch_id=b and id=i;
 when 'inventory' then
  probe:=api.inventory_valuation_report_page(t,e,b,i,section,0,filters->>'evidence_key');
  select evidence into data from inventory.valuation_reports where tenant_id=t and legal_entity_id=e and branch_id=b and id=i;
 when 'tax' then
  if section='lines' then
   if filters->>'account_id' is not null or filters->>'evidence_key' is not null then raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
   probe:=api.tax_summary_page(t,e,b,i,0,(filters->>'source_line_id')::uuid);
  else
   if filters->>'source_line_id' is not null then raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
   probe:=api.tax_control_page(t,e,b,i,section,0,(filters->>'account_id')::uuid,filters->>'evidence_key');
  end if;
  select evidence into data from finance.tax_reports where tenant_id=t and legal_entity_id=e and requested_branch_id=b and id=i;
 when 'budget' then
  probe:=api.budget_variance_page(t,e,b,i,section,0,(filters->>'budget_line_id')::uuid);
  select evidence into data from finance.budget_variance_reports where tenant_id=t and legal_entity_id=e and requested_branch_id=b and id=i;
 when 'close' then
  probe:=api.close_control_review_page(t,e,b,i,section,0,filters->>'component_key');
  select evidence into data from finance.close_control_reviews where tenant_id=t and legal_entity_id=e and id=i;
 end case;
 if data is null or jsonb_typeof(data->section) is distinct from 'array' then raise exception using errcode='42501',message='REPORT_EXPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(x order by ord),'[]') into rows from jsonb_array_elements(data->section) with ordinality q(x,ord)
 where (filters->>'account_id' is null or x->>'account_id'=filters->>'account_id')
  and (filters->>'evidence_key' is null or x->>'evidence_key'=filters->>'evidence_key')
  and (filters->>'source_line_id' is null or x->>'source_line_id'=filters->>'source_line_id')
  and (filters->>'component_key' is null or x->>'component_key'=filters->>'component_key')
  and (filters->>'budget_line_id' is null or (section='lines' and x->>'id'=filters->>'budget_line_id')
   or (section='journals' and x->>'budget_line_id'=filters->>'budget_line_id'));
 if jsonb_array_length(rows)>10000 then raise exception using errcode='54000',message='REPORT_EXPORT_ROW_LIMIT';end if;
 select coalesce(jsonb_object_agg(key,value),'{}') into meta from jsonb_each(data->'summary')
  where key in('id','version','tenant_id','legal_entity_id','branch_id','requested_branch_id','scope','entity_name','branch_name','kind','status',
   'currency_code','base_currency_code','as_of','generated_at','period_id','period_name','period_start','period_end','period_version','period_state',
   'comparative_period_id','budget_id','budget_version','budget_name','branch_filter_id','cost_centre_filter_id','project_filter_id','notice');
 result:=jsonb_build_object('version',1,'metadata',meta||jsonb_build_object('actor_id',auth.uid(),'working_branch_id',b,
  'source_type',resource,'source_id',i,'section',section,'filters',filters,'row_count',jsonb_array_length(rows)), 'rows',rows);
 if octet_length(result::text)>8388608 then raise exception using errcode='54000',message='REPORT_EXPORT_EVIDENCE_LIMIT';end if;
 return result;
end $$;
create function api.report_export_preview(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_source_type text,p_source_id uuid,p_section text,p_filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 data:=finance.report_export_document(p_tenant_id,p_legal_entity_id,p_branch_id,p_source_type,p_source_id,p_section,p_filters);
 return jsonb_build_object('canonical_text',data::text,'source_hash',encode(extensions.digest(data::text,'sha256'),'hex'));
end $$;
create function api.record_report_export(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p jsonb:=p_payload;data jsonb;h text;r jsonb;id uuid:=(p->>'id')::uuid;req uuid:=gen_random_uuid();
 source_hash text;columns jsonb;filters jsonb;result jsonb;expected_columns jsonb;begin
 -- Current source permission and export permission precede every replay.
 data:=finance.report_export_document(p_tenant_id,p_legal_entity_id,p_branch_id,p->>'source_type',(p->>'source_id')::uuid,p->>'section',p->'filters');
 source_hash:=encode(extensions.digest(data::text,'sha256'),'hex');
 select jsonb_build_array('record_type')||
  (select jsonb_agg('report.'||key order by key) from (select jsonb_object_keys(data->'metadata') key
   union select unnest(array['export_id','export_prepared_at','source_hash','file_format']))q)||
  coalesce((select jsonb_agg('data.'||key order by key) from (select distinct key
   from jsonb_array_elements(data->'rows')x cross join lateral jsonb_object_keys(x)key)q),'[]'::jsonb)
 into expected_columns;
 if id is null or p_client_timestamp is null or p->>'source_hash' is distinct from source_hash
  or p->>'file_format' not in('csv','xlsx') or p->>'file_format' is null
  or coalesce(p->>'file_name','')!~ '^[a-zA-Z0-9][a-zA-Z0-9._-]{1,180}$'
  or right(p->>'file_name',length(p->>'file_format')+1)<>'.'||(p->>'file_format')
  or coalesce(p->>'file_sha256','')!~ '^[a-f0-9]{64}$' or (p->>'file_size')::bigint not between 1 and 10485760
  or p->>'file_size' is null or jsonb_typeof(p->'columns') is distinct from 'array'
  or jsonb_array_length(p->'columns') not between 1 and 256 or p->>'prepared_at' is null
  or p->'columns' is distinct from expected_columns then
  raise exception using errcode='22023',message='REPORT_EXPORT_METADATA_INVALID';end if;
 if exists(select 1 from jsonb_array_elements(p->'columns')x where jsonb_typeof(x)<>'string' or length(x#>>'{}') not between 1 and 100)
  or (select count(distinct x) from jsonb_array_elements_text(p->'columns')x)<>jsonb_array_length(p->'columns') then
  raise exception using errcode='22023',message='REPORT_EXPORT_METADATA_INVALID';end if;
 perform (p->>'prepared_at')::timestamptz;
 h:=core.wave3_request_hash('finance.report.export',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.report.export',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 filters:=data->'metadata'||jsonb_build_object('source_hash',source_hash,'file_sha256',p->>'file_sha256','prepared_at',p->>'prepared_at',
  'artifact_state','generated_local_delivery_unconfirmed');columns:=p->'columns';
 insert into core.export_jobs(id,tenant_id,actor_id,resource,file_format,filters,columns_json,status,row_count,file_name,file_size,request_id)
  values(id,p_tenant_id,auth.uid(),'wave3.'||(p->>'source_type'),p->>'file_format',filters,columns,'completed',
   jsonb_array_length(data->'rows'),p->>'file_name',(p->>'file_size')::bigint,req);
 result:=jsonb_build_object('id',id,'version',1,'tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'actor_id',auth.uid(),'status','registered','source_type',p->>'source_type','source_id',p->>'source_id',
  'section',p->>'section','filters',p->'filters','source_hash',source_hash,'file_sha256',p->>'file_sha256',
  'file_format',p->>'file_format','file_name',p->>'file_name','file_size',(p->>'file_size')::bigint,'row_count',jsonb_array_length(data->'rows'));
 return core.wave3_finish_command(p_tenant_id,'finance.report.export',p_command_id,'report_export',id,p_idempotency_key,h,null,result,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','registered'),
  jsonb_build_array(jsonb_build_object('topic','finance.report.exported','payload',result)),'[]',req,req);
end $$;
revoke all on function finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb),
 api.report_export_preview(uuid,uuid,uuid,text,uuid,text,jsonb),
 api.record_report_export(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.report_export_preview(uuid,uuid,uuid,text,uuid,text,jsonb),
 api.record_report_export(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive governed financial dimensions. No historical backfill.
insert into core.permissions(code,module,description,privileged) values
 ('finance.dimensions.manage','finance','Manage scoped financial cost centres and project tags.',true)
 on conflict(code) do nothing;
create table finance.dimensions (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid,
 kind text not null check(kind in('cost_centre','project')),code text not null check(code~'^[A-Z0-9][A-Z0-9._-]{0,39}$'),
 name text not null check(length(trim(name)) between 2 and 160),status text not null check(status in('active','retired')),
 version bigint not null check(version>0),reason text not null check(length(trim(reason)) between 3 and 1000),
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,kind,code),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id)
);
create index dimensions_scope on finance.dimensions(tenant_id,legal_entity_id,kind,status,id);
create index dimensions_branch on finance.dimensions(tenant_id,branch_id);
create index dimensions_creator on finance.dimensions(created_by);
create index dimensions_updater on finance.dimensions(updated_by);
alter table finance.dimensions enable row level security;
alter table finance.dimensions force row level security;
revoke all on finance.dimensions from public,anon,authenticated;
create function finance.guard_dimension() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' or new.id is distinct from old.id or new.tenant_id is distinct from old.tenant_id
  or new.legal_entity_id is distinct from old.legal_entity_id or new.branch_id is distinct from old.branch_id
  or new.kind is distinct from old.kind or new.code is distinct from old.code
  or new.version<>old.version+1 or new.created_by is distinct from old.created_by then
  raise exception using errcode='55000',message='DIMENSION_IDENTITY_IMMUTABLE';end if;
 return new;
end$$;
create trigger dimension_guard before update or delete on finance.dimensions for each row execute function finance.guard_dimension();
create table finance.dimension_events (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 dimension_id uuid not null,version bigint not null,actor_id uuid not null references auth.users(id),snapshot jsonb not null,
 created_at timestamptz not null default now(),unique(tenant_id,legal_entity_id,dimension_id,version),
 foreign key(tenant_id,legal_entity_id,dimension_id) references finance.dimensions(tenant_id,legal_entity_id,id)
);
create index dimension_events_actor on finance.dimension_events(actor_id);
alter table finance.dimension_events enable row level security;
alter table finance.dimension_events force row level security;
revoke all on finance.dimension_events from public,anon,authenticated;
create trigger immutable before update or delete on finance.dimension_events for each row execute function workflow.reject_history_mutation();

create function api.financial_dimension_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare t uuid:=p_tenant_id;e uuid:=p_legal_entity_id;b uuid:=p_branch_id;p jsonb:=p_payload;
 v_id uuid:=(p->>'id')::uuid;target_branch uuid:=(p->>'dimension_branch_id')::uuid;
 oldrow finance.dimensions%rowtype;d finance.dimensions%rowtype;h text;r jsonb;req uuid:=gen_random_uuid();result jsonb;begin
 perform core.wave3_require_scope(t,'finance.dimensions.manage',e,null);
 perform core.wave3_require_scope(t,'finance.dimensions.manage',e,b);
 if v_id is null or p_client_timestamp is null or p->>'kind' not in('cost_centre','project') or p->>'kind' is null
  or coalesce(p->>'code','')!~'^[A-Z0-9][A-Z0-9._-]{0,39}$'
  or length(trim(coalesce(p->>'name',''))) not between 2 and 160
  or p->>'status' not in('active','retired') or p->>'status' is null
  or length(trim(coalesce(p->>'reason',''))) not between 3 and 1000 then
  raise exception using errcode='22023',message='DIMENSION_INPUT_INVALID';end if;
 if target_branch is not null and (target_branch<>b or not exists(select 1 from core.branches
  where tenant_id=t and legal_entity_id=e and id=target_branch and status='active')) then
  raise exception using errcode='42501',message='DIMENSION_BRANCH_SCOPE_REQUIRED';end if;
 h:=core.wave3_request_hash('finance.dimension.save',p_command_id,t,e,b,p,p_expected_entity_version);
 r:=core.wave3_replay(t,'finance.dimension.save',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':dimension:'||v_id::text,0));
 select * into oldrow from finance.dimensions where tenant_id=t and legal_entity_id=e and dimensions.id=v_id for update;
 if not found then
  perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
  insert into finance.dimensions(id,tenant_id,legal_entity_id,branch_id,kind,code,name,status,version,reason,created_by,updated_by)
  values(v_id,t,e,target_branch,p->>'kind',p->>'code',trim(p->>'name'),p->>'status',1,trim(p->>'reason'),auth.uid(),auth.uid());
 else
  if oldrow.branch_id is not null and oldrow.branch_id<>b then raise exception using errcode='42501',message='DIMENSION_BRANCH_SCOPE_REQUIRED';end if;
  perform core.wave3_assert_expected_version(oldrow.version,p_expected_entity_version,to_jsonb(oldrow));
  if oldrow.branch_id is distinct from target_branch or oldrow.kind<>p->>'kind' or oldrow.code<>p->>'code' then
   raise exception using errcode='22023',message='DIMENSION_IDENTITY_IMMUTABLE';end if;
  update finance.dimensions set name=trim(p->>'name'),status=p->>'status',reason=trim(p->>'reason'),
   version=version+1,updated_by=auth.uid(),updated_at=now() where tenant_id=t and dimensions.id=v_id;
 end if;
 select * into d from finance.dimensions where tenant_id=t and dimensions.id=v_id;
 result:=to_jsonb(d)||jsonb_build_object('dimension_branch_id',d.branch_id,'branch_id',b);
 insert into finance.dimension_events(tenant_id,legal_entity_id,dimension_id,version,actor_id,snapshot)
  values(t,e,v_id,d.version,auth.uid(),to_jsonb(d));
 return core.wave3_finish_command(t,'finance.dimension.save',p_command_id,'financial_dimension',v_id,p_idempotency_key,h,
  case when oldrow.id is not null then to_jsonb(oldrow) end,result,e,b,'{}',
  jsonb_build_object('to_status',d.status,'reason',d.reason),
  jsonb_build_array(jsonb_build_object('topic','finance.dimension.saved','payload',result)),'[]',req,req);
end$$;

create function api.financial_dimensions(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_kind text,p_after uuid default null,p_search text default '',p_active_only boolean default true) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_kind not in('cost_centre','project') or p_kind is null or length(coalesce(p_search,''))>100 or p_active_only is null then
  raise exception using errcode='22023',message='DIMENSION_PAGE_INVALID';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into rows from(
  select id,tenant_id,legal_entity_id,branch_id dimension_branch_id,kind,code,name,status,version,reason
  from finance.dimensions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and kind=p_kind and (branch_id is null or branch_id=p_branch_id)
   and (not p_active_only or status='active') and (p_after is null or id>p_after)
   and (coalesce(p_search,'')='' or position(lower(p_search) in lower(code||' '||name))>0)
  order by id limit 51)q;
 n:=jsonb_array_length(rows);
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'kind',p_kind,'items',case when n>50 then rows-50 else rows end,'next_cursor',case when n>50 then rows->49->>'id' end);
end$$;

create function finance.dimension_basis(t uuid,e uuid,b uuid,i uuid,k text) returns jsonb
language plpgsql security definer set search_path='' as $$declare d finance.dimensions%rowtype;begin
 if i is null then return null;end if;
 select * into d from finance.dimensions where tenant_id=t and legal_entity_id=e and id=i and kind=k and status='active'
  and (branch_id is null or branch_id=b) for share;
 if not found then raise exception using errcode='22023',message='BUDGET_DIMENSION_UNAVAILABLE';end if;
 return jsonb_build_object('id',d.id,'tenant_id',t,'legal_entity_id',e,'branch_id',d.branch_id,
  'kind',d.kind,'version',d.version,'code',d.code,'name',d.name);
end$$;

alter function finance.manual_normalize(uuid,uuid,uuid,jsonb) rename to manual_normalize_before_dimensions;
create function finance.manual_normalize(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare normalized jsonb;rawlines jsonb;line jsonb;raw jsonb;lines jsonb:='[]';dims jsonb;basis jsonb;
 reversal uuid:=(p->>'reversal_of_id')::uuid;k text;id_key text;begin
 normalized:=finance.manual_normalize_before_dimensions(t,e,b,p);
 if reversal is null then rawlines:=p->'lines';else select snapshot->'lines' into rawlines from finance.manual_journals
  where tenant_id=t and legal_entity_id=e and branch_id=b and id=reversal and status='posted';end if;
 for line in select value from jsonb_array_elements(normalized->'lines') loop
  select value into raw from jsonb_array_elements(rawlines) where value->>'line_id'=line->>'line_id';
  dims:='{}';
  foreach k in array array['cost_centre','project'] loop
   id_key:=k||'_id';
   if raw->>id_key is not null then
    if reversal is null then basis:=finance.dimension_basis(t,e,b,(raw->>id_key)::uuid,k);
    else
     basis:=raw#>array['dimension_snapshot',k];
     if basis->>'id' is distinct from raw->>id_key or basis->>'tenant_id' is distinct from t::text
      or basis->>'legal_entity_id' is distinct from e::text then raise exception using errcode='55000',message='DIMENSION_REVERSAL_BASIS_INVALID';end if;
    end if;
    dims:=dims||jsonb_build_object(k,basis);
    line:=line||jsonb_build_object(id_key,raw->>id_key,
     case k when 'cost_centre' then 'cost_center' else 'project' end,(basis->>'code')||' · '||(basis->>'name'));
   end if;
  end loop;
  if dims<>'{}' then line:=line||jsonb_build_object('dimension_snapshot',dims);end if;
  lines:=lines||jsonb_build_array(line);
 end loop;
 return normalized||jsonb_build_object('lines',lines);
end$$;

alter table finance.journal_lines
 add column cost_centre_id uuid,add column project_id uuid,add column dimension_snapshot jsonb,
 add foreign key(tenant_id,legal_entity_id,cost_centre_id) references finance.dimensions(tenant_id,legal_entity_id,id),
 add foreign key(tenant_id,legal_entity_id,project_id) references finance.dimensions(tenant_id,legal_entity_id,id);
create index journal_cost_centre on finance.journal_lines(tenant_id,legal_entity_id,cost_centre_id,posting_date);
create index journal_project on finance.journal_lines(tenant_id,legal_entity_id,project_id,posting_date);
create function finance.capture_manual_dimensions() returns trigger language plpgsql security definer set search_path='' as $$
declare j finance.journal_entries%rowtype;line jsonb;begin
 if new.cost_centre_id is not null or new.project_id is not null or new.dimension_snapshot is not null then
  raise exception using errcode='22023',message='DIMENSION_SOURCE_REQUIRED';end if;
 select * into j from finance.journal_entries where tenant_id=new.tenant_id and id=new.journal_entry_id;
 if j.source_type='manual_journal' then
  select x into line from finance.manual_journals d cross join lateral jsonb_array_elements(d.snapshot->'lines')x
   where d.tenant_id=j.tenant_id and d.legal_entity_id=j.legal_entity_id and d.branch_id=j.branch_id
    and d.id=j.source_id and d.status='approved' and x->>'line_id'=new.source_line_id::text;
  if line is null then raise exception using errcode='55000',message='DIMENSION_MANUAL_SOURCE_INVALID';end if;
  new.cost_centre_id:=(line->>'cost_centre_id')::uuid;new.project_id:=(line->>'project_id')::uuid;
  new.dimension_snapshot:=line->'dimension_snapshot';
 end if;
 return new;
end$$;
create trigger capture_manual_dimensions before insert on finance.journal_lines for each row execute function finance.capture_manual_dimensions();

create function finance.validate_dimension_budget_lines(t uuid,e uuid,b uuid,lines jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare x jsonb;y jsonb;out_rows jsonb:='[]';ids uuid[]:='{}';i uuid;a uuid;cost uuid;project uuid;amount text;dims jsonb;basis jsonb;k text;begin
 if jsonb_typeof(lines) is distinct from 'array' or jsonb_array_length(lines) not between 1 and 500 then
  raise exception using errcode='22023',message='BUDGET_LINES_INVALID';end if;
 for x in select value from jsonb_array_elements(lines) loop
  if jsonb_typeof(x) is distinct from 'object' then raise exception using errcode='22023',message='BUDGET_LINE_INVALID';end if;
  i:=(x->>'id')::uuid;a:=(x->>'account_id')::uuid;cost:=(x->>'cost_centre_id')::uuid;project:=(x->>'project_id')::uuid;amount:=x->>'amount';
  if i is null or a is null or i=any(ids) or jsonb_typeof(x->'amount') is distinct from 'string' or amount is null
   or amount !~ '^\d+(\.\d{1,6})?$' or length(amount)>35 or amount::numeric>99999999999999 then
   raise exception using errcode='22023',message='BUDGET_LINE_INVALID';end if;
  if not exists(select 1 from finance.accounts where tenant_id=t and legal_entity_id=e and id=a and status='active' and is_posting) then
   raise exception using errcode='22023',message='BUDGET_ACCOUNT_INVALID';end if;
  for y in select value from jsonb_array_elements(out_rows) where value->>'account_id'=a::text loop
   if (cost is null or y->>'cost_centre_id' is null or y->>'cost_centre_id'=cost::text)
    and (project is null or y->>'project_id' is null or y->>'project_id'=project::text) then
    raise exception using errcode='22023',message='BUDGET_DIMENSION_OVERLAP';end if;
  end loop;
  dims:='{}';
  foreach k in array array['cost_centre','project'] loop
   basis:=finance.dimension_basis(t,e,b,(x->>(k||'_id'))::uuid,k);
   if basis is not null then dims:=dims||jsonb_build_object(k,basis);end if;
  end loop;
  ids:=array_append(ids,i);
  out_rows:=out_rows||jsonb_build_array(jsonb_build_object('id',i,'account_id',a,'amount',(amount::numeric(20,6))::text,
   'cost_centre_id',cost,'project_id',project)||case when dims='{}' then '{}'::jsonb else jsonb_build_object('dimension_snapshot',dims) end);
 end loop;
 return out_rows;
end$$;

-- API budget/variance replacements below preserve shared engines and old unassigned budgets.
revoke all on function finance.guard_dimension(),finance.dimension_basis(uuid,uuid,uuid,uuid,text),
 finance.manual_normalize_before_dimensions(uuid,uuid,uuid,jsonb),finance.manual_normalize(uuid,uuid,uuid,jsonb),
 finance.capture_manual_dimensions(),finance.validate_dimension_budget_lines(uuid,uuid,uuid,jsonb),
 api.financial_dimension_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.financial_dimensions(uuid,uuid,uuid,text,uuid,text,boolean) from public,anon,authenticated;
grant execute on function api.financial_dimension_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.financial_dimensions(uuid,uuid,uuid,text,uuid,text,boolean) to authenticated;

create or replace function api.budget_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t uuid:=p_tenant_id;e uuid:=p_legal_entity_id;b uuid:=p_branch_id;
 act text:=p_payload->>'action';v_id uuid:=(p_payload->>'id')::uuid;
 source_id uuid:=(p_payload->>'source_id')::uuid;
 budget finance.budget_versions%rowtype;source_budget finance.budget_versions%rowtype;
 period finance.fiscal_periods%rowtype;year_value integer;budget_branch uuid;
 currency text;reason text:=trim(p_payload->>'reason');v_lines jsonb;
 before_row jsonb;result jsonb;h text;r jsonb;req uuid:=gen_random_uuid();begin
 perform core.wave3_require_scope(t,case when act in('approve','reject') then
  'finance.budgets.approve' else 'finance.budgets.manage' end,e,null);
 perform core.wave3_require_scope(t,case when act in('approve','reject') then
  'finance.budgets.approve' else 'finance.budgets.manage' end,e,b);
 if act not in('create','save','submit','approve','reject','revise') or act is null
  or v_id is null or p_client_timestamp is null or reason is null
  or length(reason) not between 3 and 1000 then
  raise exception using errcode='22023',message='BUDGET_COMMAND_INVALID';end if;
 h:=core.wave3_request_hash('finance.budgets.'||act,p_command_id,t,e,b,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(t,'finance.budgets.'||act,p_command_id,p_idempotency_key,h);
 if r is not null then return r;end if;
 if act in('create','revise') then
  if act='revise' then
   select * into source_budget from finance.budget_versions where tenant_id=t and legal_entity_id=e
    and id=source_id and status='approved' for update;
   if not found then raise exception using errcode='55000',message='BUDGET_APPROVED_SOURCE_REQUIRED';end if;
   if source_budget.branch_id is not null and source_budget.branch_id<>b then
    raise exception using errcode='42501',message='BUDGET_BRANCH_SCOPE_REQUIRED';end if;
   perform core.wave3_assert_expected_version(source_budget.version,
    p_expected_entity_version,to_jsonb(source_budget));
   if exists(select 1 from finance.budget_versions where tenant_id=t and root_id=source_budget.root_id
    and revision>source_budget.revision) then
    raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
   v_lines:=source_budget.lines;budget_branch:=source_budget.branch_id;
   year_value:=source_budget.budget_year;currency:=source_budget.currency_code;
   budget.period_id:=source_budget.period_id;
  else
   perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
   budget.period_id:=(p_payload->>'period_id')::uuid;
   year_value:=(p_payload->>'budget_year')::integer;
   budget_branch:=(p_payload->>'branch_id')::uuid;
   currency:=p_payload->>'currency_code';
   if budget_branch is not null and budget_branch<>b then
    raise exception using errcode='42501',message='BUDGET_BRANCH_SCOPE_REQUIRED';end if;
   if budget_branch is not null and not exists(select 1 from core.branches
    where tenant_id=t and legal_entity_id=e and id=budget_branch and status='active') then
    raise exception using errcode='22023',message='BUDGET_BRANCH_INVALID';end if;
   if year_value not between 2000 and 2100 or year_value is null
    or currency is null or not exists(select 1 from core.currencies where code=currency) then
    raise exception using errcode='22023',message='BUDGET_BASIS_INVALID';end if;
   if budget.period_id is not null then
    select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
     and id=budget.period_id and status='active';
    if not found or extract(year from period.start_date)::integer<>year_value then
     raise exception using errcode='22023',message='BUDGET_PERIOD_INVALID';end if;
   end if;
   v_lines:=finance.validate_dimension_budget_lines(t,e,budget_branch,p_payload->'lines');
  end if;
  insert into finance.budget_versions(id,tenant_id,legal_entity_id,root_id,revision,
   period_id,budget_year,branch_id,currency_code,lines,status,version,reason,created_by)
  values(v_id,t,e,case when act='create' then v_id else source_budget.root_id end,
   case when act='create' then 1 else source_budget.revision+1 end,budget.period_id,
   year_value,budget_branch,currency,v_lines,'draft',1,reason,auth.uid());
 else
  select * into budget from finance.budget_versions where tenant_id=t and legal_entity_id=e
   and id=v_id for update;
  if not found then raise exception using errcode='42501',message='BUDGET_SCOPE_REQUIRED';end if;
  if budget.branch_id is not null and budget.branch_id<>b then
   raise exception using errcode='42501',message='BUDGET_BRANCH_SCOPE_REQUIRED';end if;
  perform core.wave3_assert_expected_version(budget.version,p_expected_entity_version,to_jsonb(budget));
  before_row:=to_jsonb(budget);
  if act in('save','submit') and budget.status<>'draft' or
   act in('approve','reject') and budget.status<>'submitted' then
   raise exception using errcode='55000',message='BUDGET_STATE_INVALID';end if;
  if act in('approve','reject') and auth.uid() in(budget.created_by,budget.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  if act in('submit','approve') and finance.validate_dimension_budget_lines(t,e,budget.branch_id,budget.lines) is distinct from budget.lines then
   raise exception using errcode='55000',message='BUDGET_DIMENSION_REAPPROVAL_REQUIRED';end if;
  if act='save' then
   v_lines:=finance.validate_dimension_budget_lines(t,e,budget.branch_id,p_payload->'lines');
   update finance.budget_versions set lines=v_lines,version=version+1,updated_at=now()
    where tenant_id=t and id=budget.id;
  else
   update finance.budget_versions set status=case act when 'submit' then 'submitted'
    when 'approve' then 'approved' else 'rejected' end,version=version+1,
    submitted_by=case when act='submit' then auth.uid() else submitted_by end,
    decided_by=case when act in('approve','reject') then auth.uid() else decided_by end,
    decided_at=case when act in('approve','reject') then now() else decided_at end,
    updated_at=now() where tenant_id=t and id=budget.id;
  end if;
 end if;
 select * into budget from finance.budget_versions v where v.tenant_id=t and v.id=v_id;
 insert into finance.budget_events(tenant_id,legal_entity_id,budget_id,version,action,reason,snapshot,actor_id)
 values(t,e,budget.id,budget.version,act,reason,to_jsonb(budget),auth.uid());
 result:=jsonb_build_object('id',budget.id,'tenant_id',t,'legal_entity_id',e,
  'branch_id',b,'budget_branch_id',budget.branch_id,'root_id',budget.root_id,
  'revision',budget.revision,'period_id',budget.period_id,'budget_year',budget.budget_year,
  'currency_code',budget.currency_code,'line_count',jsonb_array_length(budget.lines),
  'lines',budget.lines,'status',budget.status,'version',budget.version,
  'reason',budget.reason,'created_by',budget.created_by);
 return core.wave3_finish_command(t,'finance.budgets.'||act,p_command_id,'budget',v_id,
  p_idempotency_key,h,before_row,result,e,b,
  jsonb_build_object('period_id',budget.period_id,'root_id',budget.root_id),
  jsonb_build_object('to_status',budget.status,'revision',budget.revision,'reason',reason),
  jsonb_build_array(jsonb_build_object('topic','finance.budgets.'||act,'payload',result)),
  '[]',req,req);
end$$;


create or replace function finance.build_budget_variance(t uuid,e uuid,b uuid,budget_id uuid,d date,report_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare budget finance.budget_versions%rowtype;period finance.fiscal_periods%rowtype;
 start_date date;end_date date;base_currency text;x jsonb;a finance.accounts%rowtype;
 actual numeric;planned numeric;total_budget numeric:=0;total_actual numeric:=0;
 rows jsonb:='[]';journals jsonb:='[]';source_rows jsonb;source_count integer;
 summary jsonb;result jsonb;begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 select * into budget from finance.budget_versions where tenant_id=t and legal_entity_id=e
  and id=budget_id and status='approved' and (branch_id is null or branch_id=b);
 if not found then raise exception using errcode='42501',message='APPROVED_BUDGET_REQUIRED';end if;
 if budget.period_id is not null then
  select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
   and id=budget.period_id;
  start_date:=period.start_date;end_date:=period.end_date;
 else start_date:=make_date(budget.budget_year,1,1);
  end_date:=make_date(budget.budget_year,12,31);end if;
 if d is null or d<start_date or d>end_date or d>(clock_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='BUDGET_VARIANCE_DATE_INVALID';end if;
 select currency_code into base_currency from core.legal_entities
  where tenant_id=t and id=e;
 for x in select value from jsonb_array_elements(budget.lines) loop
  select * into a from finance.accounts where tenant_id=t and legal_entity_id=e
   and id=(x->>'account_id')::uuid;
  select coalesce(sum(case when a.normal_balance='debit' then
    case when budget.currency_code=base_currency then l.base_debit-l.base_credit
     else l.transaction_debit-l.transaction_credit end
   else case when budget.currency_code=base_currency then l.base_credit-l.base_debit
     else l.transaction_credit-l.transaction_debit end end),0),
   coalesce(jsonb_agg(jsonb_build_object('id',l.id,'budget_line_id',x->>'id',
    'journal_entry_id',j.id,'posting_date',j.posting_date,'document_number',j.document_number,
    'account_id',a.id,'branch_id',j.branch_id,'currency_code',j.currency_code,
    'base_debit',l.base_debit::text,'base_credit',l.base_credit::text,
    'transaction_debit',l.transaction_debit::text,
    'transaction_credit',l.transaction_credit::text,'source_type',j.source_type,
    'source_id',j.source_id,'cost_centre_id',l.cost_centre_id,'project_id',l.project_id,
    'dimension_snapshot',l.dimension_snapshot) order by j.posting_date,j.id,l.id),'[]')
   into actual,source_rows
  from finance.journal_lines l join finance.journal_entries j
   on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and l.account_id=a.id
   and j.status='posted' and j.posting_date between start_date and d
   and (budget.branch_id is null or j.branch_id=budget.branch_id)
   and (budget.currency_code=base_currency or j.currency_code=budget.currency_code)
   and (x->>'cost_centre_id' is null or l.cost_centre_id=(x->>'cost_centre_id')::uuid)
   and (x->>'project_id' is null or l.project_id=(x->>'project_id')::uuid);
  planned:=(x->>'amount')::numeric;total_budget:=total_budget+planned;
  total_actual:=total_actual+actual;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',x->>'id','account_id',a.id,
   'code',a.code,'name',a.name,'normal_balance',a.normal_balance,
   'cost_centre_id',x->'cost_centre_id','project_id',x->'project_id',
   'dimension_snapshot',x->'dimension_snapshot',
   'budget_amount',planned::text,'actual_amount',actual::text,
   'variance',(actual-planned)::text,
   'variance_percent',case when planned=0 then null else round((actual-planned)*100/planned,6)::text end,
   'source_count',jsonb_array_length(source_rows)));
  journals:=journals||source_rows;
  if jsonb_array_length(journals)>10000 then
   raise exception using errcode='54000',message='BUDGET_VARIANCE_SOURCE_LIMIT';end if;
 end loop;
 source_count:=jsonb_array_length(journals);
 summary:=jsonb_build_object('id',report_id,'tenant_id',t,'legal_entity_id',e,
  'branch_id',b,'budget_id',budget_id,'budget_root_id',budget.root_id,
  'budget_revision',budget.revision,'period_id',budget.period_id,
  'budget_year',budget.budget_year,'budget_branch_id',budget.branch_id,
  'as_of',d,'period_start',start_date,'period_end',end_date,
  'currency_code',budget.currency_code,'base_currency_code',base_currency,
  'currency_basis',case when budget.currency_code=base_currency then 'base_all_posted'
   else 'matching_transaction_only' end,'generated_at',now(),
  'status','generated','version',1,'line_count',jsonb_array_length(rows),
  'journal_count',source_count,'budget_total',total_budget::text,
  'actual_total',total_actual::text,'variance_total',(total_actual-total_budget)::text,
  'variance_percent',case when total_budget=0 then null
   else round((total_actual-total_budget)*100/total_budget,6)::text end);
 result:=jsonb_build_object('summary',summary,'lines',rows,'journals',journals);
 if octet_length(result::text)>16777216 then
  raise exception using errcode='54000',message='BUDGET_VARIANCE_EVIDENCE_LIMIT';end if;
 return result;
end$$;


notify pgrst,'reload schema';

-- W4-02A exact civil boundary resolution. Unapplied development candidate.
-- Existing employee/calendar migrations are immutable. No grants to roles/plans.

create function people.local_instant_candidates(p_timezone text,p_local timestamp)
returns jsonb language plpgsql stable set search_path = '' as $$
declare v_result jsonb;
begin
  if p_timezone is null or p_local is null or not isfinite(p_local)
    or p_local<'0001-01-01'::timestamp or p_local>='10000-01-01'::timestamp
    or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_timezone) then
    raise exception using errcode='22023',message='CALENDAR_LOCAL_BOUNDARY_INVALID';
  end if;
  -- Sample both sides of all civil-date offset transitions, including 24-hour
  -- date-line jumps. Round-trip verification, not PostgreSQL's implicit fold/gap
  -- preference, determines whether a candidate is a valid local instant.
  with probes as (
    select (p_local at time zone 'UTC')+g*interval '1 hour' instant
    from pg_catalog.generate_series(-48,48) g
  ), offsets as (
    select distinct extract(epoch from
      (instant at time zone p_timezone)-(instant at time zone 'UTC'))::integer seconds
    from probes
  ), candidates as (
    select (p_local-seconds*interval '1 second') at time zone 'UTC' utc,seconds
    from offsets
  )
  select coalesce(jsonb_agg(jsonb_build_object('utc',
    to_char(utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'offset_seconds',seconds)
    order by utc),'[]'::jsonb) into v_result from candidates
    where utc at time zone p_timezone=p_local;
  return v_result;
end $$;

create function people.resolve_local_instant(
  p_timezone text,p_local timestamp,p_offset_seconds integer default null
) returns timestamptz language plpgsql stable set search_path = '' as $$
declare v_candidates jsonb; v_utc timestamptz;
begin
  v_candidates:=people.local_instant_candidates(p_timezone,p_local);
  if jsonb_array_length(v_candidates)=0 then
    raise exception using errcode='22023',message='CALENDAR_LOCAL_TIME_NONEXISTENT';
  end if;
  if jsonb_array_length(v_candidates)>1 and p_offset_seconds is null then
    raise exception using errcode='22023',message='CALENDAR_OFFSET_SELECTION_REQUIRED';
  end if;
  select (value->>'utc')::timestamptz into v_utc
    from jsonb_array_elements(v_candidates)
    where p_offset_seconds is null or (value->>'offset_seconds')::integer=p_offset_seconds;
  if v_utc is null then
    raise exception using errcode='22023',message='CALENDAR_OFFSET_INVALID';
  end if;
  return v_utc;
end $$;

create function api.people_calendar_local_candidates(
  p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_version_id uuid,p_date date,p_minute integer
) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_version people.work_calendar_versions%rowtype; v_local timestamp;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.calendars.view');
  select v.* into v_version from people.work_calendar_versions v
    where v.tenant_id=p_tenant_id and v.legal_entity_id=p_legal_entity_id and v.id=p_version_id;
  if not found then raise exception using errcode='P0002',message='CALENDAR_NOT_FOUND'; end if;
  if p_date is null or not isfinite(p_date) or p_minute is null
    or p_minute not between 0 and 1439
    or p_date<v_version.start_date or p_date>=v_version.end_date_exclusive then
    raise exception using errcode='22023',message='CALENDAR_LOCAL_BOUNDARY_INVALID';
  end if;
  v_local:=p_date::timestamp+p_minute*interval '1 minute';
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
    'branch_id',p_branch_id,'resolution',jsonb_build_object(
    'calendar_version_id',v_version.id,'date',p_date,'minute',p_minute,
    'timezone',v_version.timezone,'local_datetime',to_char(v_local,'YYYY-MM-DD"T"HH24:MI:SS'),
    'algorithm','pg-iana-roundtrip-v1',
    'candidates',people.local_instant_candidates(v_version.timezone,v_local)));
end $$;

revoke all on function people.local_instant_candidates(text,timestamp),
  people.resolve_local_instant(text,timestamp,integer),
  api.people_calendar_local_candidates(uuid,uuid,uuid,uuid,date,integer)
  from public,anon,authenticated;
grant execute on function api.people_calendar_local_candidates(uuid,uuid,uuid,uuid,date,integer)
  to authenticated;

-- W4-02A dated organization. Unapplied, additive synthetic development candidate.
insert into core.permissions(code,module,description,privileged) values
('people.organization.view','people','Read scoped organization history.',false),
('people.organization.manage','people','Manage dated organization with MFA.',true)
on conflict(code) do nothing;

create table people.departments (
  id uuid primary key, tenant_id uuid not null, legal_entity_id uuid not null,
  code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
  version bigint not null default 1 check(version between 1 and 9007199254740991),
  unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,code),
  foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table people.department_revisions (
  id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
  department_id uuid not null,parent_id uuid,name text not null check(length(btrim(name)) between 1 and 160),
  start_date date not null,end_date_exclusive date,
  reason text not null check(length(btrim(reason)) between 1 and 1000),
  recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
  supersedes_id uuid references people.department_revisions(id),superseded_at timestamptz,
  check(start_date>='0001-01-01'::date and start_date<='9999-12-31'::date
    and (end_date_exclusive is null or (end_date_exclusive>start_date and end_date_exclusive<='9999-12-31'::date))),
  unique(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,department_id) references people.departments(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,parent_id) references people.departments(tenant_id,legal_entity_id,id),
  exclude using gist(department_id extensions.gist_uuid_ops with =,
    daterange(start_date,end_date_exclusive,'[)') with &&) where(superseded_at is null)
);
create index department_revisions_scope_idx on people.department_revisions(tenant_id,legal_entity_id,department_id,id);
create index department_revisions_parent_idx on people.department_revisions(tenant_id,legal_entity_id,parent_id);
create index department_revisions_actor_idx on people.department_revisions(recorded_by);
create index department_revisions_supersedes_idx on people.department_revisions(supersedes_id);
create table people.organization_assignments (
  id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
  employee_id uuid not null,spell_id uuid not null,department_id uuid not null,manager_id uuid,
  calendar_version_id uuid not null,role_title text not null check(length(btrim(role_title)) between 1 and 160),
  start_date date not null,end_date_exclusive date not null,
  reason text not null check(length(btrim(reason)) between 1 and 1000),
  recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
  supersedes_id uuid references people.organization_assignments(id),superseded_at timestamptz,
  check(start_date>='0001-01-01'::date and end_date_exclusive<='9999-12-31'::date
    and end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
  unique(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,spell_id,employee_id) references people.employment_spells(tenant_id,legal_entity_id,id,employee_id),
  foreign key(tenant_id,legal_entity_id,department_id) references people.departments(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,manager_id) references people.employees(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,calendar_version_id) references people.work_calendar_versions(tenant_id,legal_entity_id,id),
  exclude using gist(employee_id extensions.gist_uuid_ops with =,
    daterange(start_date,end_date_exclusive,'[)') with &&) where(superseded_at is null)
);
create index organization_assignments_scope_idx on people.organization_assignments(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index organization_assignments_employee_idx on people.organization_assignments(tenant_id,legal_entity_id,employee_id);
create index organization_assignments_spell_idx on people.organization_assignments(tenant_id,legal_entity_id,spell_id);
create index organization_assignments_department_idx on people.organization_assignments(tenant_id,legal_entity_id,department_id);
create index organization_assignments_manager_idx on people.organization_assignments(tenant_id,legal_entity_id,manager_id);
create index organization_assignments_calendar_idx on people.organization_assignments(tenant_id,legal_entity_id,calendar_version_id);
create index organization_assignments_actor_idx on people.organization_assignments(recorded_by);
create index organization_assignments_supersedes_idx on people.organization_assignments(supersedes_id);
create table people.organization_withdrawals (
  id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
  employee_id uuid not null,revision_id uuid not null unique,
  reason text not null check(length(btrim(reason)) between 1 and 1000),
  recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
  foreign key(tenant_id,legal_entity_id,revision_id) references people.organization_assignments(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index organization_withdrawals_scope_idx on people.organization_withdrawals(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index organization_withdrawals_employee_idx on people.organization_withdrawals(tenant_id,legal_entity_id,employee_id);
create index organization_withdrawals_revision_idx on people.organization_withdrawals(tenant_id,legal_entity_id,revision_id);
create index organization_withdrawals_actor_idx on people.organization_withdrawals(recorded_by);

-- Only trusted module commands can seal dated organization inputs. A consumed
-- revision remains immutable even after an unchanged prefix is superseded.
create table people.organization_consumptions (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null,
  legal_entity_id uuid not null, revision_id uuid not null,
  source_type text not null check(source_type in ('attendance','leave','payroll','project_time','service_time')),
  source_id uuid not null, start_date date not null,end_date_exclusive date not null,
  recorded_at timestamptz not null default clock_timestamp(),
  check(end_date_exclusive>start_date),
  unique(tenant_id,legal_entity_id,source_type,source_id),
  foreign key(tenant_id,legal_entity_id,revision_id)
    references people.organization_assignments(tenant_id,legal_entity_id,id)
);
create index organization_consumptions_revision_idx on people.organization_consumptions(tenant_id,legal_entity_id,revision_id);
create function people.guard_organization_consumption() returns trigger language plpgsql set search_path='' as $$
begin raise exception using errcode='55000',message='ORGANIZATION_CONSUMPTION_IMMUTABLE'; end $$;
create trigger organization_consumption_immutable before update or delete on people.organization_consumptions
  for each row execute function people.guard_organization_consumption();
create trigger organization_withdrawal_immutable before update or delete on people.organization_withdrawals
  for each row execute function people.guard_organization_consumption();
create function people.consume_organization(p_tenant uuid,p_entity uuid,p_branch uuid,p_employee uuid,
  p_source_type text,p_source_id uuid,p_start date,p_end date) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
  perform id from people.employees where id=p_employee and tenant_id=p_tenant and legal_entity_id=p_entity for update;
  perform pg_advisory_xact_lock(hashtextextended('people.organization:'||p_tenant||':'||p_entity,0));
  select id into v_id from people.organization_assignments where employee_id=p_employee
    and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and superseded_at is null
    and daterange(start_date,end_date_exclusive,'[)') @> daterange(p_start,p_end,'[)');
  if v_id is null or p_start is null or p_end is null or p_end<=p_start then
    raise exception using errcode='55000',message='ORGANIZATION_ASSIGNMENT_REQUIRED';
  end if;
  insert into people.organization_consumptions(tenant_id,legal_entity_id,revision_id,source_type,source_id,start_date,end_date_exclusive)
    values(p_tenant,p_entity,v_id,p_source_type,p_source_id,p_start,p_end) on conflict do nothing;
  if not exists(select 1 from people.organization_consumptions where tenant_id=p_tenant and legal_entity_id=p_entity
    and revision_id=v_id and source_type=p_source_type and source_id=p_source_id and start_date=p_start and end_date_exclusive=p_end) then
    raise exception using errcode='22023',message='ORGANIZATION_CONSUMPTION_MISMATCH';
  end if;
  return v_id;
end $$;

create function people.guard_organization_revision() returns trigger language plpgsql set search_path='' as $$
begin
  if tg_op='DELETE' or new.superseded_at is null or old.superseded_at is not null
    or (to_jsonb(new)-'superseded_at') is distinct from (to_jsonb(old)-'superseded_at') then
    raise exception using errcode='55000',message='ORGANIZATION_HISTORY_IMMUTABLE';
  end if;
  return new;
end $$;
create trigger department_history_immutable before update or delete on people.department_revisions
  for each row execute function people.guard_organization_revision();
create trigger organization_history_immutable before update or delete on people.organization_assignments
  for each row execute function people.guard_organization_revision();

create function people.assert_organization(p_tenant uuid,p_entity uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
  if exists(select 1 from people.department_revisions d where d.tenant_id=p_tenant
    and d.legal_entity_id=p_entity and d.superseded_at is null and d.parent_id is not null
    and not coalesce(daterange(d.start_date,d.end_date_exclusive,'[)') <@
      (select range_agg(daterange(p.start_date,p.end_date_exclusive,'[)'))
       from people.department_revisions p where p.department_id=d.parent_id and p.superseded_at is null),false)) then
    raise exception using errcode='23514',message='DEPARTMENT_PARENT_COVERAGE_REQUIRED';
  end if;
  if exists(with recursive walk as (
    select d.department_id,d.parent_id,daterange(d.start_date,d.end_date_exclusive,'[)') span,
      array[d.department_id] path,false cycle from people.department_revisions d
      where d.tenant_id=p_tenant and d.legal_entity_id=p_entity and d.superseded_at is null
    union all select p.department_id,p.parent_id,w.span*daterange(p.start_date,p.end_date_exclusive,'[)'),
      w.path||p.department_id,p.department_id=any(w.path)
      from walk w join people.department_revisions p on p.department_id=w.parent_id
      and p.superseded_at is null and w.span && daterange(p.start_date,p.end_date_exclusive,'[)')
      where not w.cycle and cardinality(w.path)<=64
  ) select 1 from walk where cycle or cardinality(path)>64) then
    raise exception using errcode='23514',message='DEPARTMENT_CYCLE_OR_DEPTH';
  end if;
  if exists(select 1 from people.organization_assignments o
    where o.tenant_id=p_tenant and o.legal_entity_id=p_entity and o.superseded_at is null and (
      not exists(select 1 from people.employment_spells s where s.id=o.spell_id and s.employee_id=o.employee_id
        and daterange(s.start_date,s.end_date_exclusive,'[)') @> daterange(o.start_date,o.end_date_exclusive,'[)'))
      or not coalesce(daterange(o.start_date,o.end_date_exclusive,'[)') <@
        (select range_agg(daterange(a.start_date,a.end_date_exclusive,'[)')) from people.employment_assignments a
         where a.employee_id=o.employee_id and a.spell_id=o.spell_id and a.branch_id=o.branch_id),false)
      or not exists(select 1 from people.work_calendar_versions c where c.id=o.calendar_version_id
        and daterange(c.start_date,c.end_date_exclusive,'[)') @> daterange(o.start_date,o.end_date_exclusive,'[)'))
      or not coalesce(daterange(o.start_date,o.end_date_exclusive,'[)') <@
        (select range_agg(daterange(d.start_date,d.end_date_exclusive,'[)')) from people.department_revisions d
         where d.department_id=o.department_id and d.superseded_at is null),false)
      or (o.manager_id is not null and (o.manager_id=o.employee_id or not coalesce(
        daterange(o.start_date,o.end_date_exclusive,'[)') <@
        (select range_agg(daterange(s.start_date,s.end_date_exclusive,'[)')) from people.employment_spells s
          where s.employee_id=o.manager_id),false)))
    )) then raise exception using errcode='23514',message='ORGANIZATION_IMPACT_REQUIRED'; end if;
  if exists(with recursive walk as (
    select o.employee_id,o.manager_id,daterange(o.start_date,o.end_date_exclusive,'[)') span,
      array[o.employee_id] path,false cycle from people.organization_assignments o
      where o.tenant_id=p_tenant and o.legal_entity_id=p_entity and o.superseded_at is null
    union all select m.employee_id,m.manager_id,w.span*daterange(m.start_date,m.end_date_exclusive,'[)'),
      w.path||m.employee_id,m.employee_id=any(w.path) from walk w
      join people.organization_assignments m on m.employee_id=w.manager_id and m.superseded_at is null
        and w.span && daterange(m.start_date,m.end_date_exclusive,'[)')
      where not w.cycle and cardinality(w.path)<=64
  ) select 1 from walk where cycle or cardinality(path)>64) then
    raise exception using errcode='23514',message='MANAGER_CYCLE_OR_DEPTH';
  end if;
end $$;
create function people.check_organization_compatibility() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  perform people.assert_organization(coalesce(new.tenant_id,old.tenant_id),
    coalesce(new.legal_entity_id,old.legal_entity_id));
  return null;
end $$;
create constraint trigger organization_after_employment_spell after insert or update or delete on people.employment_spells
  deferrable initially deferred for each row execute function people.check_organization_compatibility();
create constraint trigger organization_after_employment_assignment after insert or update or delete on people.employment_assignments
  deferrable initially deferred for each row execute function people.check_organization_compatibility();
create constraint trigger organization_assignment_compatible after insert or update on people.organization_assignments
  deferrable initially deferred for each row execute function people.check_organization_compatibility();
create constraint trigger department_revision_compatible after insert or update on people.department_revisions
  deferrable initially deferred for each row execute function people.check_organization_compatibility();

create function people.organization_assignment_payload(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object('id',o.id,'tenant_id',o.tenant_id,'legal_entity_id',o.legal_entity_id,
    'branch_id',o.branch_id,'employee_id',o.employee_id,'spell_id',o.spell_id,
    'department_id',o.department_id,'manager_id',o.manager_id,'calendar_version_id',o.calendar_version_id,
    'role_title',o.role_title,'start_date',o.start_date,'end_date_exclusive',o.end_date_exclusive,
    'reason',o.reason,'recorded_by',o.recorded_by,'recorded_at',o.recorded_at,
    'supersedes_id',o.supersedes_id,'superseded_at',o.superseded_at)
    ||jsonb_build_object('department_name_at_start',(select name from people.department_revisions d
      where d.department_id=o.department_id and d.superseded_at is null
        and daterange(d.start_date,d.end_date_exclusive,'[)') @> o.start_date),
      'manager_display_name',(select display_name from people.employees where id=o.manager_id),
      'withdrawal',(select jsonb_build_object('id',w.id,'reason',w.reason,'recorded_by',w.recorded_by,'recorded_at',w.recorded_at)
        from people.organization_withdrawals w where w.revision_id=o.id),
      'calendar_name',(select c.name from people.work_calendars c join people.work_calendar_versions v on v.calendar_id=c.id
        where v.id=o.calendar_version_id),'calendar_timezone',(select timezone from people.work_calendar_versions where id=o.calendar_version_id))
  from people.organization_assignments o where o.id=p_id
$$;
create function api.people_organization_department(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_department_id uuid,p_as_of date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_item jsonb;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  if p_as_of is null or not isfinite(p_as_of) or p_as_of<'0001-01-01'::date or p_as_of>'9999-12-31'::date then
    raise exception using errcode='22023',message='ORGANIZATION_FILTER_INVALID';
  end if;
  select jsonb_build_object('id',d.id,'code',d.code,'version',d.version,'revision_id',r.id,'name',r.name,
    'parent_id',r.parent_id,'start_date',r.start_date,'end_date_exclusive',r.end_date_exclusive) into v_item
    from people.departments d join people.department_revisions r on r.department_id=d.id and r.superseded_at is null
      and daterange(r.start_date,r.end_date_exclusive,'[)') @> p_as_of
    where d.id=p_department_id and d.tenant_id=p_tenant_id and d.legal_entity_id=p_legal_entity_id;
  if v_item is null then raise exception using errcode='P0002',message='DEPARTMENT_NOT_FOUND'; end if;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
    'as_of',p_as_of,'department',v_item);
end $$;
create function api.people_organization_departments(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_as_of date,p_search text default '',p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  if p_as_of is null or not isfinite(p_as_of) or p_as_of<'0001-01-01'::date
    or p_as_of>'9999-12-31'::date or length(coalesce(p_search,''))>160 then
    raise exception using errcode='22023',message='ORGANIZATION_FILTER_INVALID';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'code',q.code,'version',q.version,
    'revision_id',q.revision_id,'name',q.name,'parent_id',q.parent_id,
    'start_date',q.start_date,'end_date_exclusive',q.end_date_exclusive) order by q.id),'[]') into v_items
  from (select d.id,d.code,d.version,r.id revision_id,r.name,r.parent_id,r.start_date,r.end_date_exclusive
    from people.departments d join people.department_revisions r on r.department_id=d.id
    and r.superseded_at is null and daterange(r.start_date,r.end_date_exclusive,'[)') @> p_as_of
    where d.tenant_id=p_tenant_id and d.legal_entity_id=p_legal_entity_id and (p_after is null or d.id>p_after)
    and (btrim(coalesce(p_search,''))='' or position(lower(btrim(p_search)) in lower(d.code||' '||r.name))>0)
    order by d.id limit 50) q;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
    'branch_id',p_branch_id,'as_of',p_as_of,'items',v_items);
end $$;
create function api.people_organization_employee(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_employee_id uuid,p_as_of date,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb; v_version bigint;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  perform api.people_employee_detail(p_tenant_id,p_legal_entity_id,p_branch_id,p_employee_id,p_as_of);
  select version into v_version from people.employees where id=p_employee_id;
  select coalesce(jsonb_agg(people.organization_assignment_payload(q.id) order by q.id),'[]') into v_items
    from (select id from people.organization_assignments where employee_id=p_employee_id and branch_id=p_branch_id
      and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and (p_after is null or id>p_after)
      order by id limit 50) q;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
    'employee_id',p_employee_id,'employee_version',v_version,'as_of',p_as_of,'items',v_items);
end $$;
create function api.people_organization_department_history(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_department_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  if not exists(select 1 from people.departments where id=p_department_id and tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id) then raise exception using errcode='P0002',message='DEPARTMENT_NOT_FOUND'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'name',q.name,'parent_id',q.parent_id,
    'start_date',q.start_date,'end_date_exclusive',q.end_date_exclusive,'reason',q.reason,
    'recorded_by',q.recorded_by,'recorded_at',q.recorded_at,'supersedes_id',q.supersedes_id,
    'superseded_at',q.superseded_at) order by q.id),'[]') into v_items
    from (select * from people.department_revisions where department_id=p_department_id
      and (p_after is null or id>p_after) order by id limit 50) q;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
    'branch_id',p_branch_id,'department_id',p_department_id,'items',v_items);
end $$;

create function api.people_organization_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_version bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_revision uuid;
  v_employee uuid;v_manager uuid;v_start date;v_end date;v_hash text;v_replay jsonb;v_allowed text[];
  v_before jsonb:='{}';v_entity jsonb;v_current bigint;v_old people.department_revisions%rowtype;
  v_old_org people.organization_assignments%rowtype;v_name text;v_reason text;v_parent uuid;
begin
  if coalesce(jsonb_typeof(p_payload),'null')<>'object' or v_action is null
    or v_action not in ('department_create','department_revise','assign','replace','end_assignment','withdraw_assignment')
    or p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
    or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception using errcode='22023',message='ORGANIZATION_COMMAND_INVALID';
  end if;
  v_allowed:=case v_action
    when 'department_create' then array['action','id','revision_id','code','name','parent_id','start_date','end_date_exclusive','reason']
    when 'department_revise' then array['action','id','revision_id','name','parent_id','start_date','end_date_exclusive','reason','replace_revision_id']
    when 'assign' then array['action','id','employee_id','spell_id','department_id','manager_id','calendar_version_id',
      'role_title','start_date','end_date_exclusive','reason']
    when 'replace' then array['action','id','employee_id','spell_id','department_id','manager_id','calendar_version_id',
      'role_title','start_date','end_date_exclusive','reason','replace_revision_id']
    else array['action','id','employee_id','start_date','end_date_exclusive','reason','replace_revision_id'] end;
  if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(v_allowed))
    or coalesce(jsonb_typeof(p_payload->'reason'),'null')<>'string'
    or length(btrim(p_payload->>'reason')) not between 1 and 1000
    or coalesce(p_payload->>'start_date','') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception using errcode='22023',message='ORGANIZATION_COMMAND_FIELDS_INVALID';
  end if;
  v_id:=(p_payload->>'id')::uuid;v_start:=(p_payload->>'start_date')::date;
  v_end:=nullif(p_payload->>'end_date_exclusive','')::date;v_reason:=btrim(p_payload->>'reason');
  if v_start<'0001-01-01'::date or v_start>'9999-12-31'::date or not isfinite(v_start)
    or (v_end is not null and (not isfinite(v_end) or v_end<=v_start or v_end>'9999-12-31'::date)) then
    raise exception using errcode='22023',message='ORGANIZATION_DATES_INVALID';
  end if;
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.manage');
  -- Hierarchy/manager changes can affect every branch: entity-wide management is required.
  perform core.require_permission(p_tenant_id,'people.organization.manage',p_legal_entity_id,null);
  if v_action in ('assign','replace','end_assignment','withdraw_assignment') then
    v_employee:=(p_payload->>'employee_id')::uuid;v_manager:=nullif(p_payload->>'manager_id','')::uuid;
    perform api.people_employee_detail(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_start);
    perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.calendars.view');
    if v_employee is null or v_end is null or v_end-v_start>1830 or
      (v_action not in ('end_assignment','withdraw_assignment') and (coalesce(jsonb_typeof(p_payload->'role_title'),'null')<>'string'
      or length(btrim(p_payload->>'role_title')) not between 1 and 160)) then
      raise exception using errcode='22023',message='ORGANIZATION_ASSIGNMENT_INVALID';
    end if;
  end if;
  v_hash:=core.wave3_request_hash('people.organization.'||v_action,p_command_id,
    p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
  v_replay:=core.wave3_replay(p_tenant_id,'people.organization.'||v_action,p_command_id,p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay; end if;
  if v_employee is not null then
    perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
      and id in (v_employee,v_manager) order by id for update;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('people.organization:'||p_tenant_id||':'||p_legal_entity_id,0));
  if v_action like 'department_%' then
    v_name:=btrim(p_payload->>'name');v_parent:=nullif(p_payload->>'parent_id','')::uuid;
    v_revision:=(p_payload->>'revision_id')::uuid;
    if v_revision is null or coalesce(jsonb_typeof(p_payload->'name'),'null')<>'string'
      or length(v_name) not between 1 and 160 then
      raise exception using errcode='22023',message='DEPARTMENT_FIELDS_INVALID';
    end if;
    if v_action='department_create' then
      if p_expected_version is distinct from 0 or coalesce(p_payload->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'
        or (select count(*) from people.departments where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id)>=2000 then
        raise exception using errcode='22023',message='DEPARTMENT_CREATE_INVALID';
      end if;
      insert into people.departments(id,tenant_id,legal_entity_id,code)
      values(v_id,p_tenant_id,p_legal_entity_id,p_payload->>'code');
    else
      select version into v_current from people.departments where id=v_id
        and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
      if not found then raise exception using errcode='P0002',message='DEPARTMENT_NOT_FOUND'; end if;
      perform core.wave3_assert_expected_version(v_current,p_expected_version,'{}');
      select * into v_old from people.department_revisions where id=(p_payload->>'replace_revision_id')::uuid
        and department_id=v_id and superseded_at is null;
      if not found or not daterange(v_old.start_date,v_old.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)') then
        raise exception using errcode='22023',message='DEPARTMENT_REPLACEMENT_INVALID';
      end if;
      v_before:=jsonb_build_object('id',v_id,'version',v_current,'revision_id',v_old.id);
      if exists(select 1 from people.organization_consumptions c join people.organization_assignments o on o.id=c.revision_id
        where o.department_id=v_id and daterange(c.start_date,c.end_date_exclusive,'[)') && daterange(v_start,v_end,'[)')) then
        raise exception using errcode='55000',message='ORGANIZATION_CONSUMED_IMPACT_REQUIRED';
      end if;
      update people.department_revisions set superseded_at=clock_timestamp() where id=v_old.id;
      if v_old.start_date<v_start then
        insert into people.department_revisions(id,tenant_id,legal_entity_id,department_id,parent_id,name,
          start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
        values(gen_random_uuid(),p_tenant_id,p_legal_entity_id,v_id,v_old.parent_id,v_old.name,
          v_old.start_date,v_start,v_reason,v_actor,v_old.id);
      end if;
      if v_end is not null and (v_old.end_date_exclusive is null or v_end<v_old.end_date_exclusive) then
        insert into people.department_revisions(id,tenant_id,legal_entity_id,department_id,parent_id,name,
          start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
        values(gen_random_uuid(),p_tenant_id,p_legal_entity_id,v_id,v_old.parent_id,v_old.name,
          v_end,v_old.end_date_exclusive,v_reason,v_actor,v_old.id);
      end if;
      update people.departments set version=version+1 where id=v_id;
    end if;
    insert into people.department_revisions(id,tenant_id,legal_entity_id,department_id,parent_id,name,
      start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
    values(v_revision,p_tenant_id,p_legal_entity_id,v_id,v_parent,v_name,v_start,v_end,v_reason,v_actor,
      case when v_action='department_revise' then v_old.id end);
    select jsonb_build_object('id',id,'tenant_id',tenant_id,'legal_entity_id',legal_entity_id,
      'code',code,'version',version,'revision_id',v_revision)
      into v_entity from people.departments where id=v_id;
  else
    select version into v_current from people.employees where id=v_employee;
    perform core.wave3_assert_expected_version(v_current,p_expected_version,'{}');
    if v_action in ('replace','end_assignment','withdraw_assignment') then
      select * into v_old_org from people.organization_assignments where id=(p_payload->>'replace_revision_id')::uuid
        and employee_id=v_employee and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
        and branch_id=p_branch_id and superseded_at is null;
      -- Full revision replacement retains its original dates. Partial changes use
      -- explicit successor revisions rather than silently trimming original facts.
      if not found or v_start<>v_old_org.start_date
        or (v_action in ('replace','withdraw_assignment') and v_end<>v_old_org.end_date_exclusive)
        or (v_action='end_assignment' and v_end>=v_old_org.end_date_exclusive) then
        raise exception using errcode='22023',message='ORGANIZATION_REPLACEMENT_INVALID';
      end if;
      v_before:=people.organization_assignment_payload(v_old_org.id);
      if v_action='withdraw_assignment' and v_start <=
        (clock_timestamp() at time zone (select timezone from core.legal_entities where id=p_legal_entity_id))::date then
        raise exception using errcode='55000',message='ORGANIZATION_FUTURE_WITHDRAWAL_REQUIRED';
      end if;
      if exists(select 1 from people.organization_consumptions c where c.revision_id=v_old_org.id
        and (v_action in ('replace','withdraw_assignment') or c.end_date_exclusive>v_end)) then
        raise exception using errcode='55000',message='ORGANIZATION_CONSUMED_IMPACT_REQUIRED';
      end if;
      update people.organization_assignments set superseded_at=clock_timestamp() where id=v_old_org.id;
    end if;
    if v_action='withdraw_assignment' then
      insert into people.organization_withdrawals(id,tenant_id,legal_entity_id,branch_id,employee_id,revision_id,reason,recorded_by)
        values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_old_org.id,v_reason,v_actor);
      update people.employees set version=version+1,updated_by=v_actor,updated_at=clock_timestamp() where id=v_employee;
      select jsonb_build_object('id',w.id,'tenant_id',w.tenant_id,'legal_entity_id',w.legal_entity_id,'branch_id',w.branch_id,
        'employee_id',w.employee_id,'revision_id',w.revision_id,'reason',w.reason,'recorded_by',w.recorded_by,
        'recorded_at',w.recorded_at,'employee_version',v_current+1) into v_entity from people.organization_withdrawals w where id=v_id;
    else
    insert into people.organization_assignments(id,tenant_id,legal_entity_id,branch_id,employee_id,spell_id,
      department_id,manager_id,calendar_version_id,role_title,start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
    values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
      case when v_action='end_assignment' then v_old_org.spell_id else (p_payload->>'spell_id')::uuid end,
      case when v_action='end_assignment' then v_old_org.department_id else (p_payload->>'department_id')::uuid end,
      case when v_action='end_assignment' then v_old_org.manager_id else v_manager end,
      case when v_action='end_assignment' then v_old_org.calendar_version_id else (p_payload->>'calendar_version_id')::uuid end,
      case when v_action='end_assignment' then v_old_org.role_title else btrim(p_payload->>'role_title') end,
      v_start,v_end,v_reason,v_actor,case when v_action in ('replace','end_assignment') then v_old_org.id end);
    update people.employees set version=version+1,updated_by=v_actor,updated_at=clock_timestamp() where id=v_employee;
    v_entity:=people.organization_assignment_payload(v_id)||jsonb_build_object('employee_version',v_current+1);
    end if;
  end if;
  perform people.assert_organization(p_tenant_id,p_legal_entity_id);
  return core.wave3_finish_command(p_tenant_id,'people.organization.'||v_action,p_command_id,
    case when v_employee is null then 'people.department' else 'people.organization' end,
    v_id,p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id);
end $$;

