-- UNAPPLIED additive read-plan candidate. Existing immutable engines untouched.
create index stock_movements_finance_command_source on inventory.stock_movements
 (tenant_id,legal_entity_id,command_id,source_type);

create or replace function finance.close_inventory_accounts(t uuid,e uuid,d date) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare ids jsonb;begin
 with stock_commands as materialized (
  select distinct m.command_id,s.source_type from inventory.stock_movements m
  cross join lateral(values(m.source_type),(m.source_type||'.stock'))s(source_type)
  where m.tenant_id=t and m.legal_entity_id=e and m.command_id is not null
 ), controls as (
  select inventory_account_id id from inventory.products where tenant_id=t and legal_entity_id=e
  union
  select l.account_id from finance.journal_lines l
  join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  join stock_commands s on s.command_id=j.command_id and s.source_type=j.source_type
  join finance.accounts a on a.tenant_id=l.tenant_id and a.id=l.account_id and a.account_type='asset'
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted' and l.posting_date<=d
 )
 select coalesce(jsonb_agg(id order by id),'[]') into ids
 from (select id from controls where id is not null order by id limit 51)q;
 if jsonb_array_length(ids)>50 then raise exception using errcode='54000',message='CLOSE_INVENTORY_ACCOUNT_LIMIT';end if;
 return ids;
end$$;
revoke all on function finance.close_inventory_accounts(uuid,uuid,date) from public,anon,authenticated;

-- UNAPPLIED. Contract 49; strict rollback tests precede installation.
create function core.wave3_source_descriptor(k text) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object('schema',s,'table',tbl,'permission',permission,'child',child,'parent',parent,'cost',cost)
 from (values
 ('lead','crm','leads','crm.leads.view',null,null,false),
 ('opportunity','crm','opportunities','crm.opportunities.view',null,null,false),
 ('quotation','sales','quotations','sales.quotations.view','quotation_lines','quotation_id',false),
 ('sales_order','sales','sales_orders','sales.orders.view','sales_order_lines','sales_order_id',false),
 ('delivery','sales','deliveries','sales.deliveries.view','delivery_lines','document_id',true),
 ('sales_invoice','sales','sales_invoices','sales.invoices.view','sales_invoice_lines','document_id',false),
 ('customer_receipt','sales','customer_receipts','finance.receipts.view','customer_receipt_lines','document_id',false),
 ('sales_return','sales','sales_returns','sales.returns.view','sales_return_lines','document_id',true),
 ('purchase_requisition','procurement','requisitions','procurement.requisitions.manage','requisition_lines','requisition_id',false),
 ('rfq','procurement','rfqs','procurement.rfq.manage','rfq_lines','rfq_id',false),
 ('purchase_order','procurement','purchase_orders','procurement.orders.view','purchase_order_lines','order_id',false),
 ('goods_receipt','procurement','goods_receipts','procurement.receipts.post','goods_receipt_lines','receipt_id',true),
 ('supplier_bill','procurement','supplier_bills','procurement.bills.view','supplier_bill_lines','bill_id',false),
 ('payment_proposal','procurement','payment_proposals','finance.payments.manage',null,null,false),
 ('supplier_payment','procurement','supplier_payments','finance.payments.manage',null,null,false),
 ('purchase_return','procurement','purchase_returns','procurement.returns.post','purchase_return_lines','return_id',true),
 ('inventory_transfer','inventory','transfers','inventory.stock.view','transfer_lines','transfer_id',true),
 ('stock_count','inventory','stock_counts','inventory.adjustments.post',null,null,true),
 ('inventory_value_adjustment','inventory','value_adjustments','inventory.valuation.post',null,null,true),
 ('landed_extension','inventory','landed_extensions','inventory.valuation.post',null,null,true),
 ('inventory_disposition','inventory','stock_dispositions','inventory.dispositions.post',null,null,true),
 ('manual_journal','finance','manual_journals','finance.view',null,null,false),
 ('budget','finance','budget_versions','finance.view',null,null,false),
 ('bank_statement','finance','bank_statements','finance.view','bank_statement_lines','statement_id',false),
 ('bank_match','finance','bank_matches','finance.view',null,null,false)
 ) x(kind,s,tbl,permission,child,parent,cost) where kind=k;
$$;
revoke all on function core.wave3_source_descriptor(text) from public,anon,authenticated;

create function core.wave3_source_header(t uuid,e uuid,b uuid,k text,i uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare cfg jsonb:=core.wave3_source_descriptor(k);d jsonb;actual uuid;leg jsonb;target uuid;begin
 if cfg is null or i is null or e is null or b is null then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 perform core.wave3_require_scope(t,cfg->>'permission',e,b);
 execute format('select to_jsonb(d) from %I.%I d where d.tenant_id=$1 and d.legal_entity_id=$2 and d.id=$3',
  cfg->>'schema',cfg->>'table') into d using t,e,i;
 if d is null then raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 actual:=(d->>'branch_id')::uuid;
 if actual is not null then perform core.require_permission(t,cfg->>'permission',e,actual);end if;
 if (cfg->>'cost')::boolean then
  perform core.wave3_require_scope(t,'inventory.stock.view',e,b);
  perform core.wave3_require_scope(t,'inventory.cost.view',e,b);
  if actual is not null then
   perform core.require_permission(t,'inventory.stock.view',e,actual);
   perform core.require_permission(t,'inventory.cost.view',e,actual);end if;
 end if;
 if k in('inventory_value_adjustment','landed_extension') then
  for leg in select value from jsonb_array_elements(coalesce(d#>'{detail,legs}','[]')) loop
   foreach target in array array[(leg->>'branch_id')::uuid,(leg->>'destination_branch_id')::uuid] loop
    if target is not null then
     perform core.require_permission(t,'inventory.stock.view',e,target);
     perform core.require_permission(t,'inventory.cost.view',e,target);
     perform core.require_permission(t,'inventory.valuation.post',e,target);
    end if;
   end loop;
  end loop;
 end if;
 return d;
exception when insufficient_privilege then raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';
end $$;
revoke all on function core.wave3_source_header(uuid,uuid,uuid,text,uuid) from public,anon,authenticated;

-- The file layer has no selected desktop branch. Recheck the actual source
-- branch and never let file permission alone reveal an aggregate.
create function core.wave3_attachment_access(t uuid,k text,i uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare cfg jsonb:=core.wave3_source_descriptor(k);e uuid;b uuid;d jsonb;leg jsonb;target uuid;begin
 if auth.uid() is null or t is null or i is null or cfg is null or not core.is_tenant_member(t) then return false;end if;
 execute format('select to_jsonb(d) from %I.%I d where tenant_id=$1 and id=$2',cfg->>'schema',cfg->>'table')
  into d using t,i;
 e:=(d->>'legal_entity_id')::uuid;b:=(d->>'branch_id')::uuid;
 if e is null or not core.has_permission(t,cfg->>'permission',e,b) then return false;end if;
 if (cfg->>'cost')::boolean and (not core.has_permission(t,'inventory.stock.view',e,b)
  or not core.has_permission(t,'inventory.cost.view',e,b)) then return false;end if;
 if k in('inventory_value_adjustment','landed_extension') then
  for leg in select value from jsonb_array_elements(coalesce(d#>'{detail,legs}','[]')) loop
   foreach target in array array[(leg->>'branch_id')::uuid,(leg->>'destination_branch_id')::uuid] loop
    if target is not null and (not core.has_permission(t,'inventory.stock.view',e,target)
     or not core.has_permission(t,'inventory.cost.view',e,target)
     or not core.has_permission(t,'inventory.valuation.post',e,target)) then return false;end if;
   end loop;
  end loop;
 end if;
 return true;
end $$;
revoke all on function core.wave3_attachment_access(uuid,text,uuid) from public,anon,authenticated;

create or replace function core.validate_attachment_aggregate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_exists boolean := false;
begin
  v_exists := case new.aggregate_type
    when 'tenant' then exists (
      select 1 from core.tenants as t
      where t.id = new.aggregate_id and t.id = new.tenant_id
    )
    when 'legal_entity' then exists (
      select 1 from core.legal_entities as le
      where le.tenant_id = new.tenant_id and le.id = new.aggregate_id
    )
    when 'branch' then exists (
      select 1 from core.branches as b
      where b.tenant_id = new.tenant_id and b.id = new.aggregate_id
    )
    when 'warehouse' then exists (
      select 1 from core.warehouses as w
      where w.tenant_id = new.tenant_id and w.id = new.aggregate_id
    )
    when 'party' then exists (
      select 1 from crm.parties as p
      where p.tenant_id = new.tenant_id and p.id = new.aggregate_id
    )
    when 'contact' then exists (
      select 1 from crm.contacts as c
      where c.tenant_id = new.tenant_id and c.id = new.aggregate_id
    )
    when 'unit' then exists (
      select 1 from inventory.units as u
      where u.tenant_id = new.tenant_id and u.id = new.aggregate_id
    )
    when 'product' then exists (
      select 1 from inventory.products as p
      where p.tenant_id = new.tenant_id and p.id = new.aggregate_id
    )
    when 'account' then exists (
      select 1 from finance.accounts as a
      where a.tenant_id = new.tenant_id and a.id = new.aggregate_id
    )
    when 'tax_definition' then exists (
      select 1 from finance.tax_definitions as td
      where td.tenant_id = new.tenant_id and td.id = new.aggregate_id
    )
    when 'fiscal_period' then exists (
      select 1 from finance.fiscal_periods as fp
      where fp.tenant_id = new.tenant_id and fp.id = new.aggregate_id
    )
    when 'document_sequence' then exists (
      select 1 from core.document_sequences as ds
      where ds.tenant_id = new.tenant_id and ds.id = new.aggregate_id
    )
    when 'workflow_definition' then exists (
      select 1 from workflow.workflow_definitions as wd
      where wd.tenant_id = new.tenant_id and wd.id = new.aggregate_id
    )
    when 'report_definition' then exists (
      select 1 from core.report_definitions as rd
      where rd.tenant_id = new.tenant_id and rd.id = new.aggregate_id
    )
    when 'import_job' then exists (
      select 1 from core.import_jobs as ij
      where ij.tenant_id = new.tenant_id and ij.id = new.aggregate_id
    )
    when 'export_job' then exists (
      select 1 from core.export_jobs as ej
      where ej.tenant_id = new.tenant_id and ej.id = new.aggregate_id
    )
    when 'lead' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'opportunity' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'quotation' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'sales_order' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'delivery' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'sales_invoice' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'customer_receipt' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'sales_return' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'purchase_requisition' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'rfq' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'purchase_order' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'goods_receipt' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'supplier_bill' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'payment_proposal' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'supplier_payment' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'purchase_return' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'inventory_transfer' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'stock_count' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'inventory_value_adjustment' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'manual_journal' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'budget' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'bank_statement' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    when 'bank_match' then core.wave3_attachment_access(new.tenant_id,new.aggregate_type,new.aggregate_id)
    else false
  end;

  if not v_exists then
    raise exception using
      errcode = '22023',
      message = 'Attachment aggregate is invalid.';
  end if;
  return new;
end;
$$;
create function core.wave3_document_rows(t uuid,e uuid,b uuid,k text,filters jsonb,n integer,after_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare cfg jsonb:=core.wave3_source_descriptor(k);rows jsonb;search text:=coalesce(filters->>'search','');begin
 if cfg is null or e is null or b is null or n not between 1 and 10001 or length(search)>200
  or jsonb_typeof(filters) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(filters)x where x not in('search','status','from_date','to_date'))
  or length(coalesce(filters->>'status',''))>80
  or ((filters->>'from_date')::date>(filters->>'to_date')::date) then
  raise exception using errcode='22023',message='DOCUMENT_FILTER_INVALID';end if;
 perform core.wave3_require_scope(t,cfg->>'permission',e,b);
 if (cfg->>'cost')::boolean then perform core.wave3_require_scope(t,'inventory.cost.view',e,b);
  perform core.wave3_require_scope(t,'inventory.stock.view',e,b);end if;
 execute format($q$select coalesce(jsonb_agg(sales.flow_exact_json(j)-'snapshot'-'source_snapshot'-'lines' order by id),'[]') from (
  select d.id,to_jsonb(d) j from %I.%I d
  where d.tenant_id=$1 and d.legal_entity_id=$2 and (d.branch_id=$3 or d.branch_id is null)
   and ($10 not in('inventory_value_adjustment','landed_extension') or core.wave3_attachment_access($1,$10,d.id))
   and ($4 is null or d.id>$4)
   and ($5='' or position(lower($5) in lower(concat_ws(' ',to_jsonb(d)->>'code',to_jsonb(d)->>'document_number',
    to_jsonb(d)->>'name',to_jsonb(d)->>'reference',to_jsonb(d)->>'supplier_reference'))) > 0)
   and ($6 is null or coalesce(to_jsonb(d)->>'status','posted')=$6)
   and ($7 is null or left(coalesce(to_jsonb(d)->>'document_date',to_jsonb(d)->>'posting_date',to_jsonb(d)->>'created_at'),10)::date >= $7)
   and ($8 is null or left(coalesce(to_jsonb(d)->>'document_date',to_jsonb(d)->>'posting_date',to_jsonb(d)->>'created_at'),10)::date <= $8)
  order by d.id limit $9)q$q$,cfg->>'schema',cfg->>'table') into rows
 using t,e,b,after_id,search,nullif(filters->>'status',''),(filters->>'from_date')::date,(filters->>'to_date')::date,n,k;
 return rows;
end $$;
revoke all on function core.wave3_document_rows(uuid,uuid,uuid,text,jsonb,integer,uuid) from public,anon,authenticated;

create policy wave3_attachment_source_read on core.attachments as restrictive
 for select to authenticated using (
  core.wave3_source_descriptor(aggregate_type) is null
  or core.wave3_attachment_access(tenant_id,aggregate_type,aggregate_id)
 );

create function core.wave3_storage_access(path text,needs_ready boolean default true) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare k text:=split_part(path,'/',2);a core.attachments%rowtype;t uuid;begin
 if core.wave3_source_descriptor(k) is null then return true;end if;
 t:=core.storage_object_tenant(path);
 if t is null or auth.uid() is null then return false;end if;
 select * into a from core.attachments where tenant_id=t and object_path=path
  and aggregate_type=k and aggregate_id=split_part(path,'/',3)::uuid;
 if not found or (needs_ready and a.upload_status<>'ready')
  or (not needs_ready and a.upload_status<>'staged') then return false;end if;
 return core.wave3_attachment_access(t,k,a.aggregate_id);
exception when invalid_text_representation then return false;
end $$;
revoke all on function core.wave3_storage_access(text,boolean) from public,anon,authenticated;
-- RLS expressions execute as the caller. These policy predicates expose only
-- the fixed catalogue and current-access booleans, never source document data.
grant execute on function core.wave3_source_descriptor(text),
 core.wave3_attachment_access(uuid,text,uuid),core.wave3_storage_access(text,boolean) to authenticated;
create policy wave3_storage_source_read on storage.objects as restrictive
 for select to authenticated using (core.wave3_storage_access(name,true));
create policy wave3_storage_source_insert on storage.objects as restrictive
 for insert to authenticated with check (core.wave3_storage_access(name,false));
create policy wave3_storage_no_mutation on storage.objects as restrictive
 for update to authenticated using (core.wave3_source_descriptor(split_part(name,'/',2)) is null)
 with check (core.wave3_source_descriptor(split_part(name,'/',2)) is null);

create or replace function api.register_attachment(
 p_tenant_id uuid,p_payload jsonb,p_idempotency_key uuid default gen_random_uuid())
returns jsonb language plpgsql security definer set search_path='' as $$
declare k text:=p_payload->>'aggregate_type';begin
 if core.wave3_source_descriptor(k) is not null and
  not core.wave3_attachment_access(p_tenant_id,k,(p_payload->>'aggregate_id')::uuid) then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 return core.register_attachment_impl(p_tenant_id,p_payload,p_idempotency_key);
end $$;
create or replace function api.complete_attachment(
 p_tenant_id uuid,p_attachment_id uuid,p_checksum_sha256 text,p_expected_version bigint,
 p_idempotency_key uuid default gen_random_uuid())
returns jsonb language plpgsql security definer set search_path='' as $$
declare a core.attachments%rowtype;begin
 select * into a from core.attachments where tenant_id=p_tenant_id and id=p_attachment_id;
 if a.id is not null and core.wave3_source_descriptor(a.aggregate_type) is not null and
  not core.wave3_attachment_access(p_tenant_id,a.aggregate_type,a.aggregate_id) then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 return core.complete_attachment_impl(p_tenant_id,p_attachment_id,p_checksum_sha256,p_expected_version,p_idempotency_key);
end $$;

create function api.reject_wave3_attachment(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,
 p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a core.attachments%rowtype;before jsonb;result jsonb;h text;req uuid:=gen_random_uuid();begin
 perform core.wave3_require_scope(p_tenant_id,'core.files.manage',p_legal_entity_id,p_branch_id);
 select * into a from core.attachments where tenant_id=p_tenant_id and id=(p_payload->>'id')::uuid for update;
 if a.id is null or core.wave3_source_descriptor(a.aggregate_type) is null or
  not core.wave3_attachment_access(p_tenant_id,a.aggregate_type,a.aggregate_id) then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 h:=core.wave3_request_hash('files.wave3.reject',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'files.wave3.reject',p_command_id,p_idempotency_key,h);
 if result is not null then return result;end if;
 if length(btrim(coalesce(p_payload->>'reason',''))) not between 3 and 1000 or a.upload_status='rejected' then
  raise exception using errcode='22023',message='ATTACHMENT_REJECTION_INVALID';end if;
 perform core.wave3_assert_expected_version(a.version,p_expected_entity_version,to_jsonb(a));
 before:=to_jsonb(a);
 update core.attachments set upload_status='rejected',updated_by=auth.uid() where id=a.id returning * into a;
 result:=jsonb_build_object('id',a.id,'version',a.version,'status','rejected','reason',p_payload->>'reason',
  'aggregate_type',a.aggregate_type,'aggregate_id',a.aggregate_id);
 return core.wave3_finish_command(p_tenant_id,'files.wave3.reject',p_command_id,'attachment',a.id,p_idempotency_key,h,before,result,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','rejected','reason',p_payload->>'reason'),
  jsonb_build_array(jsonb_build_object('topic','files.wave3.rejected','payload',result)),'[]',req,req);
end $$;
revoke all on function api.reject_wave3_attachment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.reject_wave3_attachment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.wave3_document_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_kind text,
 p_filters jsonb default '{}'::jsonb,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor text;begin
 rows:=core.wave3_document_rows(p_tenant_id,p_legal_entity_id,p_branch_id,p_kind,p_filters,51,p_after);
 if jsonb_array_length(rows)>50 then cursor:=rows->49->>'id';rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'kind',p_kind,'filters',p_filters,'basis','current','generated_at',statement_timestamp(),
  'date_basis','document_date_or_posting_date_or_created_utc','items',rows,'next_cursor',cursor);
end $$;

create function api.wave3_document_evidence(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_kind text,p_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d jsonb;cfg jsonb;children jsonb:='[]';cursor text;timeline jsonb;files jsonb:='[]';result jsonb;
 receipt_id uuid;
 cursor_valid boolean:=false;begin
 d:=core.wave3_source_header(p_tenant_id,p_legal_entity_id,p_branch_id,p_kind,p_id);
 if p_kind='inventory_value_adjustment' then
  select r.id into receipt_id from inventory.stock_movement_lines l
   join procurement.goods_receipts r on r.tenant_id=l.tenant_id and r.stock_movement_id=l.stock_movement_id
   where l.tenant_id=p_tenant_id and l.id=(d->>'receipt_line_id')::uuid
    and r.legal_entity_id=p_legal_entity_id and r.branch_id=(d->>'branch_id')::uuid;
  if receipt_id is null then raise exception using errcode='55000',message='SOURCE_LINEAGE_INVALID';end if;
  d:=d||jsonb_build_object('receipt_id',receipt_id);
 end if;
 cfg:=core.wave3_source_descriptor(p_kind);
 if cfg->>'child' is not null then
  if p_after is not null then
   execute format('select exists(select 1 from %I.%I where tenant_id=$1 and %I=$2 and id=$3)',
    cfg->>'schema',cfg->>'child',cfg->>'parent') into cursor_valid using p_tenant_id,p_id,p_after;
  end if;
  if p_after is not null and not cursor_valid then
   raise exception using errcode='22023',message='DOCUMENT_CURSOR_INVALID';end if;
  execute format('select coalesce(jsonb_agg(sales.flow_exact_json(j) order by id),''[]'') from
   (select l.id,to_jsonb(l) j from %I.%I l where l.tenant_id=$1 and l.%I=$2 and ($3 is null or l.id>$3) order by l.id limit 51)q',
   cfg->>'schema',cfg->>'child',cfg->>'parent') into children using p_tenant_id,p_id,p_after;
  if jsonb_array_length(children)>50 then cursor:=children->49->>'id';children:=children-50;end if;
 elsif p_kind in('stock_count','inventory_disposition') then
  if p_after is not null and not exists(select 1 from jsonb_array_elements(d->'lines') x
   where x->>'line_id'=p_after::text) then
   raise exception using errcode='22023',message='DOCUMENT_CURSOR_INVALID';end if;
  select coalesce(jsonb_agg(x order by x->>'line_id'),'[]') into children from
   (select value x from jsonb_array_elements(d->'lines')
    where p_after is null or (value->>'line_id')::uuid>p_after
    order by value->>'line_id' limit 51)q;
  if jsonb_array_length(children)>50 then cursor:=children->49->>'line_id';children:=children-50;end if;
 elsif p_after is not null then
  raise exception using errcode='22023',message='DOCUMENT_CURSOR_INVALID';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'command_id',r.command_id,'request_id',r.request_id,
  'correlation_id',r.correlation_id,'completed_at',r.completed_at,'aggregate_type',r.aggregate_type) order by r.id),'[]')
 into timeline from (select * from core.command_receipts where tenant_id=p_tenant_id and aggregate_id=p_id order by id limit 51)r;
 if jsonb_array_length(timeline)>50 then raise exception using errcode='54000',message='SOURCE_TIMELINE_LIMIT';end if;
 if core.has_permission(p_tenant_id,'core.files.view',p_legal_entity_id,p_branch_id)
  or core.has_permission(p_tenant_id,'core.files.manage',p_legal_entity_id,p_branch_id) then
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into files from (
   select id,file_name,mime_type,byte_size::text,object_path,upload_status,version,created_at from core.attachments
   where tenant_id=p_tenant_id and aggregate_type=p_kind and aggregate_id=p_id order by id limit 51)q;
  if jsonb_array_length(files)>50 then raise exception using errcode='54000',message='SOURCE_ATTACHMENT_LIMIT';end if;
 end if;
 result:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'kind',p_kind,'id',p_id,'generated_at',statement_timestamp(),'header',sales.flow_exact_json(d)-'snapshot'-'source_snapshot'-'lines',
  'items',children,'next_cursor',cursor,'commands',timeline,'attachments',files);
 if octet_length(result::text)>1048576 then raise exception using errcode='54000',message='SOURCE_EVIDENCE_LIMIT';end if;
 return result;
end $$;

create table core.operational_reports(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 kind text not null,evidence jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id)
);
alter table core.operational_reports enable row level security;
alter table core.operational_reports force row level security;
revoke all on core.operational_reports from public,anon,authenticated;
create index operational_reports_scope_idx on core.operational_reports(tenant_id,legal_entity_id,branch_id,id);
create index operational_reports_actor_idx on core.operational_reports(created_by);
create trigger immutable before update or delete on core.operational_reports for each row execute function workflow.reject_history_mutation();

create function core.operational_report_access(t uuid,e uuid,b uuid,kind text,p jsonb) returns void
language plpgsql stable security definer set search_path='' as $$declare cfg jsonb;permission text;begin
 case kind
 when 'current_list' then
  cfg:=core.wave3_source_descriptor(p->>'document_kind');
  if cfg is null then raise exception using errcode='22023',message='OPERATIONAL_REPORT_KIND_INVALID';end if;
  perform core.wave3_require_scope(t,cfg->>'permission',e,b);
  if (cfg->>'cost')::boolean then
   perform core.wave3_require_scope(t,'inventory.stock.view',e,b);
   perform core.wave3_require_scope(t,'inventory.cost.view',e,b);end if;
 when 'customer_statement' then perform core.wave3_require_scope(t,'finance.receivables.view',e,b);
 when 'supplier_statement' then
  if not finance.payable_read_allowed(t,e,b) then raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
  select allowed.code into permission from unnest(array['procurement.bills.view','procurement.bills.manage','procurement.bills.post',
   'finance.payments.manage','finance.payments.post','finance.payments.allocate','finance.payments.reverse']) allowed(code)
   where core.has_permission(t,allowed.code,e,b) limit 1;
  perform core.wave3_require_scope(t,permission,e,b);
 when 'bank_reconciliation' then perform core.wave3_require_scope(t,'finance.view',e,b);
 else raise exception using errcode='22023',message='OPERATIONAL_REPORT_KIND_INVALID';end case;
end $$;
revoke all on function core.operational_report_access(uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;

create function finance.build_branch_cash_controls(t uuid,e uuid,b uuid,d date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare bank record;statement finance.bank_statements%rowtype;gl jsonb;sl jsonb;rows jsonb:='[]';sources jsonb:='[]';
 book numeric;ug numeric;us numeric;sv numeric;bad integer;n integer:=0;status text;base text;begin
 select currency_code into base from core.legal_entities where tenant_id=t and id=e;
 for bank in select * from finance.cash_bank_accounts where tenant_id=t and legal_entity_id=e and branch_id=b order by id loop
  n:=n+1;if n>500 then raise exception using errcode='54000',message='CLOSE_CASH_ACCOUNT_LIMIT';end if;
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into gl from (
   select l.id,j.id journal_id,j.command_id,j.source_type,j.source_id,l.posting_date,bank.id bank_id,
    bank.branch_id branch_id,bank.currency_code currency_code,
    (case when bank.currency_code=base then l.base_debit-l.base_credit
     else l.transaction_debit-l.transaction_credit end)::text value,
    (bank.currency_code<>base and j.currency_code<>bank.currency_code) invalid_currency,
    exists(select 1 from finance.bank_matches m where m.tenant_id=t and l.id=any(m.journal_line_ids)
     and m.posting_date<=d and not exists(select 1 from finance.bank_match_reversals r
      where r.tenant_id=t and r.match_id=m.id and r.posting_date<=d)) matched
   from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
   where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=bank.branch_id
    and l.account_id=bank.account_id and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
  select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into sl from (
   select l.id,l.statement_id,l.bank_id,l.posting_date,bank.branch_id branch_id,bank.currency_code currency_code,
    l.reference,l.amount::text value,'bank_statement_line'::text source_type,l.id source_id,
    exists(select 1 from finance.bank_matches m where m.tenant_id=t and l.id=any(m.statement_line_ids)
     and m.posting_date<=d and not exists(select 1 from finance.bank_match_reversals r
      where r.tenant_id=t and r.match_id=m.id and r.posting_date<=d)) matched
   from finance.bank_statement_lines l join finance.bank_statements s on s.tenant_id=l.tenant_id and s.id=l.statement_id
   where l.tenant_id=t and l.bank_id=bank.id and l.posting_date<=d and s.end_date<=d
   order by l.id limit 10001)q;
  if greatest(jsonb_array_length(gl),jsonb_array_length(sl))>10000 then raise exception using errcode='54000',message='CLOSE_CASH_INPUT_LIMIT';end if;
  select coalesce(sum((x->>'value')::numeric),0),coalesce(sum((x->>'value')::numeric) filter(where not (x->>'matched')::boolean),0),
   count(*) filter(where (x->>'invalid_currency')::boolean) into book,ug,bad from jsonb_array_elements(gl)x;
  select coalesce(sum((x->>'value')::numeric) filter(where not (x->>'matched')::boolean),0) into us from jsonb_array_elements(sl)x;
  select * into statement from finance.bank_statements where tenant_id=t and bank_id=bank.id and end_date<=d
   order by end_date desc,created_at desc,id desc limit 1;
  sv:=coalesce(statement.closing,0)-us+ug;
  status:=case when bank.account_kind='cash' then 'ledger_only'
   when bad>0 then 'currency_basis_invalid'
   when exists(select 1 from finance.cash_bank_accounts cb where cb.tenant_id=t and cb.legal_entity_id=e
    and cb.branch_id=bank.branch_id and cb.account_id=bank.account_id and cb.currency_code=bank.currency_code
    and cb.id<>bank.id and (cb.status='active' or exists(select 1 from finance.bank_statements bs where bs.tenant_id=t and bs.bank_id=cb.id))) then 'ambiguous_basis'
   when statement.id is null or statement.end_date<>d then 'statement_coverage_required'
   when sv<>book then 'difference' else 'reconciled' end;
  rows:=rows||jsonb_build_array(jsonb_build_object('id','cash:'||bank.id,'component_key','cash:'||bank.id,
   'kind','CASH','branch_id',bank.branch_id,'name',bank.name,'currency_code',bank.currency_code,'status',status,
   'accounts',jsonb_build_array(jsonb_build_object('id',bank.account_id,'code',bank.code,'name',bank.name)),
   'subledger_value',case when bank.account_kind='cash' then book::text else sv::text end,'gl_value',book::text,
   'difference',case when bank.account_kind='cash' then '0' else (sv-book)::text end,
   'difference_count',case when status in('reconciled','ledger_only') then 0 else 1 end,
   'statement_id',statement.id,'statement_end',statement.end_date,'statement_closing',coalesce(statement.closing,0)::text,
   'unmatched_book',ug::text,'unmatched_bank',us::text));
  select sources||coalesce(jsonb_agg(x||jsonb_build_object('id','cash:'||bank.id||':'||(x->>'id'),
   'component_key','cash:'||bank.id,'origin','journal') order by x->>'id'),'[]') into sources from jsonb_array_elements(gl)x;
  select sources||coalesce(jsonb_agg(x||jsonb_build_object('id','bank:'||bank.id||':'||(x->>'id'),
   'component_key','cash:'||bank.id,'origin','bank') order by x->>'id'),'[]') into sources from jsonb_array_elements(sl)x;
  if jsonb_array_length(sources)>50000 then raise exception using errcode='54000',message='CLOSE_REVIEW_OUTPUT_LIMIT';end if;
 end loop;
 return jsonb_build_object('controls',rows,'sources',sources);
end $$;
revoke all on function finance.build_branch_cash_controls(uuid,uuid,uuid,date) from public,anon,authenticated;

create function api.generate_operational_report(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p jsonb:=p_payload;k text:=p->>'kind';id uuid:=(p->>'id')::uuid;d date:=(p->>'as_of')::date;
 rows jsonb;aging jsonb:='[]';data jsonb;summary jsonb;evidence jsonb;result jsonb;h text;req uuid:=gen_random_uuid();currency text;begin
 perform core.operational_report_access(p_tenant_id,p_legal_entity_id,p_branch_id,k,p);
 if id is null or d is null or d>(statement_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='OPERATIONAL_REPORT_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('operations.report',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'operations.report',p_command_id,p_idempotency_key,h);
 if result is not null then return result;end if;
 if k='current_list' and d<>(statement_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='CURRENT_LIST_HAS_NO_HISTORICAL_BASIS';end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 select le.currency_code into currency from core.legal_entities le
 where le.tenant_id=p_tenant_id and le.id=p_legal_entity_id;
 if k='current_list' then
  rows:=core.wave3_document_rows(p_tenant_id,p_legal_entity_id,p_branch_id,p->>'document_kind',coalesce(p->'filters','{}'),10001,null);
 elsif k in('customer_statement','supplier_statement') then
  if not exists(select 1 from crm.parties party where party.tenant_id=p_tenant_id and party.id=(p->>'party_id')::uuid) then
   raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
  if k='customer_statement' then data:=api.customer_statement(p_tenant_id,p_legal_entity_id,p_branch_id,(p->>'party_id')::uuid,p->>'currency_code',d,
   case when p ? 'bucket_days' then array(select value::integer from jsonb_array_elements_text(p->'bucket_days')) else array[30,60,90] end);
  else data:=api.supplier_statement(p_tenant_id,p_legal_entity_id,p_branch_id,(p->>'party_id')::uuid,p->>'currency_code',d,
   case when p ? 'bucket_days' then array(select value::integer from jsonb_array_elements_text(p->'bucket_days')) else array[30,60,90] end);end if;
  rows:=data->'rows';aging:=data->'aging';
 else data:=finance.build_branch_cash_controls(p_tenant_id,p_legal_entity_id,p_branch_id,d);
  rows:=data->'controls';end if;
 if jsonb_array_length(rows)>10000 then raise exception using errcode='54000',message='OPERATIONAL_REPORT_ROW_LIMIT';end if;
 summary:=jsonb_build_object('id',id,'version',1,'tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'kind',k,'status','generated','basis',case k when 'current_list' then 'current' else 'posting_date' end,'as_of',d,'generated_at',statement_timestamp(),
  'base_currency_code',currency,'currency_code',p->>'currency_code','currency_meaning',case k when 'current_list' then 'row_currency_no_mixed_total' else 'posted_transaction_and_base' end,
  'row_count',jsonb_array_length(rows),'inputs',p-'id','open_amount',data->>'open_amount','open_base_amount',data->>'open_base_amount');
 evidence:=jsonb_build_object('summary',summary,'rows',rows,'aging',aging,'sources',coalesce(data->'sources','[]'));
 if octet_length(evidence::text)>8388608 then raise exception using errcode='54000',message='OPERATIONAL_REPORT_EVIDENCE_LIMIT';end if;
 insert into core.operational_reports(id,tenant_id,legal_entity_id,branch_id,kind,evidence,created_by)
 values(id,p_tenant_id,p_legal_entity_id,p_branch_id,k,evidence,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'operations.report',p_command_id,'operational_report',id,p_idempotency_key,h,null,summary,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','generated'),
  jsonb_build_array(jsonb_build_object('topic','operations.report.generated','payload',summary)),'[]',req,req);
end $$;

create function core.operational_report_rows_access(t uuid,e uuid,b uuid,evidence jsonb) returns void
language plpgsql stable security definer set search_path='' as $$declare row jsonb;k text:=evidence#>>'{summary,inputs,document_kind}';begin
 if k in('inventory_value_adjustment','landed_extension') then
  for row in select value from jsonb_array_elements(evidence->'rows') loop
   perform core.wave3_source_header(t,e,b,k,(row->>'id')::uuid);
  end loop;
 end if;
end $$;
revoke all on function core.operational_report_rows_access(uuid,uuid,uuid,jsonb) from public,anon,authenticated;

create function api.operational_report_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_id uuid,p_section text default 'rows',p_after integer default 0) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare r core.operational_reports%rowtype;rows jsonb;n integer;begin
 select * into r from core.operational_reports where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_id;
 if not found then raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 perform core.operational_report_access(p_tenant_id,p_legal_entity_id,p_branch_id,r.kind,r.evidence#>'{summary,inputs}');
 perform core.operational_report_rows_access(p_tenant_id,p_legal_entity_id,p_branch_id,r.evidence);
 if p_section not in('rows','aging','sources') or p_after is null or p_after<0 then
  raise exception using errcode='22023',message='OPERATIONAL_REPORT_PAGE_INVALID';end if;
 n:=jsonb_array_length(r.evidence->p_section);
 if p_after>n then raise exception using errcode='22023',message='OPERATIONAL_REPORT_CURSOR_INVALID';end if;
 select coalesce(jsonb_agg(x order by ordinal),'[]') into rows from jsonb_array_elements(r.evidence->p_section) with ordinality q(x,ordinal)
 where ordinal>p_after and ordinal<=p_after+50;
 return jsonb_build_object('summary',r.evidence->'summary','section',p_section,'items',rows,
  'next_cursor',case when p_after+50<n then (p_after+50)::text end);
end $$;

alter function finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb) rename to report_export_document_before_operational;
create function finance.report_export_document(t uuid,e uuid,b uuid,resource text,i uuid,section text,filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare probe jsonb;data jsonb;rows jsonb;result jsonb;begin
 if resource<>'operational' then return finance.report_export_document_before_operational(t,e,b,resource,i,section,filters);end if;
 perform core.wave3_require_scope(t,'finance.reports.export',e,null);
 perform core.wave3_require_scope(t,'finance.reports.export',e,b);
 if filters is distinct from '{}'::jsonb then raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
 probe:=api.operational_report_page(t,e,b,i,section,0);
 select evidence into data from core.operational_reports where tenant_id=t and legal_entity_id=e and branch_id=b and id=i;
 rows:=data->section;
 if jsonb_array_length(rows)>10000 then raise exception using errcode='54000',message='REPORT_EXPORT_ROW_LIMIT';end if;
 result:=jsonb_build_object('version',1,'metadata',(data->'summary')||jsonb_build_object('actor_id',auth.uid(),'working_branch_id',b,
  'source_type',resource,'source_id',i,'section',section,'filters',filters,'row_count',jsonb_array_length(rows)),'rows',rows);
 if octet_length(result::text)>8388608 then raise exception using errcode='54000',message='REPORT_EXPORT_EVIDENCE_LIMIT';end if;
 return result;
end $$;
revoke all on function finance.report_export_document_before_operational(uuid,uuid,uuid,text,uuid,text,jsonb),
 finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb) from public,anon,authenticated;

create function api.wave3_dashboard(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare k text;cfg jsonb;cards jsonb:='[]';n bigint;begin
 if auth.uid() is null or p_legal_entity_id is null or p_branch_id is null or not core.is_tenant_member(p_tenant_id) then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 for k in select kind from unnest(array['lead','opportunity','quotation','sales_order','delivery','sales_invoice','customer_receipt',
  'purchase_requisition','rfq','purchase_order','goods_receipt','supplier_bill','payment_proposal','inventory_transfer','stock_count',
  'manual_journal','budget','bank_statement','bank_match'])kind loop
  cfg:=core.wave3_source_descriptor(k);
  if core.has_permission(p_tenant_id,cfg->>'permission',p_legal_entity_id,p_branch_id)
   and (not (cfg->>'cost')::boolean or (core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id)
    and core.has_permission(p_tenant_id,'inventory.stock.view',p_legal_entity_id,p_branch_id))) then
   perform core.wave3_require_scope(p_tenant_id,cfg->>'permission',p_legal_entity_id,p_branch_id);
   execute format('select count(*) from %I.%I d where d.tenant_id=$1 and d.legal_entity_id=$2 and (d.branch_id=$3 or d.branch_id is null)
    and coalesce(to_jsonb(d)->>''status'',''posted'') in(''draft'',''submitted'',''approved'',''active'',''in_transit'')',cfg->>'schema',cfg->>'table')
    into n using p_tenant_id,p_legal_entity_id,p_branch_id;
   cards:=cards||jsonb_build_array(jsonb_build_object('kind',k,'count',n::text,'basis','current_actionable',
    'tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
    'destination',case when k in('lead','opportunity') then '/crm'
     when k in('quotation','sales_order','delivery','sales_invoice','customer_receipt') then '/sales'
     when k in('purchase_requisition','rfq','purchase_order','goods_receipt','supplier_bill','payment_proposal') then '/procurement'
     when k='inventory_transfer' then '/inventory/transfers' when k='stock_count' then '/inventory/counts'
     when k='manual_journal' then '/finance/journals' when k='budget' then '/finance/budgets'
     when k in('bank_statement','bank_match') then '/finance/bank' end,
    'generated_at',statement_timestamp()));
  end if;
 end loop;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'generated_at',statement_timestamp(),'cards',cards);
end $$;

revoke all on function api.wave3_document_page(uuid,uuid,uuid,text,jsonb,uuid),
 api.wave3_document_evidence(uuid,uuid,uuid,text,uuid,uuid),api.wave3_dashboard(uuid,uuid,uuid),
 api.generate_operational_report(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.operational_report_page(uuid,uuid,uuid,uuid,text,integer) from public,anon,authenticated;
grant execute on function api.wave3_document_page(uuid,uuid,uuid,text,jsonb,uuid),
 api.wave3_document_evidence(uuid,uuid,uuid,text,uuid,uuid),api.wave3_dashboard(uuid,uuid,uuid),
 api.generate_operational_report(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.operational_report_page(uuid,uuid,uuid,uuid,text,integer) to authenticated;

-- UNAPPLIED additive historical AR/AP control coverage. Source builder SHA-256 9de77b0e06887469a682292311d9cd161d598dcb6f871a34a712dbc38aaa5e26.
-- GRNI wrapper source SHA-256 b1864d4ac1612ebfc54439873ef5c8afab790051cf399869f55bc8ba4ff67f02; only bounded preflight is added.
-- No arbitrary same-type GL account is inferred as an AR/AP control.
create table finance.control_account_basis(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null,legal_entity_id uuid not null,
 kind text not null check(kind in('AR','AP')),account_id uuid not null,
 source_type text not null check(source_type in('current_mapping','audit_before','audit_after','future_mapping_old','future_mapping_new')),
 source_id uuid not null,source_version bigint not null default 0,observed_at timestamptz not null,
 actor_id uuid references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,kind,source_type,source_id,source_version,account_id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
alter table finance.control_account_basis enable row level security;
alter table finance.control_account_basis force row level security;
revoke all on finance.control_account_basis from public,anon,authenticated;
create index control_account_basis_scope on finance.control_account_basis(tenant_id,legal_entity_id,kind,account_id,observed_at);
create index control_account_basis_actor on finance.control_account_basis(actor_id);
create trigger immutable before update or delete on finance.control_account_basis
 for each row execute function workflow.reject_history_mutation();

-- Only audited, attributable before/after snapshots enter the historical set.
insert into finance.control_account_basis(tenant_id,legal_entity_id,kind,account_id,source_type,source_id,source_version,observed_at,actor_id)
select pm.tenant_id,pm.legal_entity_id,'AR',pm.account_id,'current_mapping',pm.id,pm.version,pm.updated_at,pm.updated_by
from finance.posting_mappings pm join finance.accounts a on a.tenant_id=pm.tenant_id and a.legal_entity_id=pm.legal_entity_id
 and a.id=pm.account_id and a.account_type='asset' where pm.purpose='receivable_control';
insert into finance.control_account_basis(tenant_id,legal_entity_id,kind,account_id,source_type,source_id,source_version,observed_at,actor_id)
select c.tenant_id,c.legal_entity_id,'AP',c.payable_account_id,'current_mapping',c.legal_entity_id,c.version,c.updated_at,c.updated_by
from procurement.supplier_bill_controls c join finance.accounts a on a.tenant_id=c.tenant_id and a.legal_entity_id=c.legal_entity_id
 and a.id=c.payable_account_id and a.account_type='liability';
with snapshots as (
 select ev.*,side.source_type,side.body from audit.events ev
 cross join lateral(values('audit_before'::text,ev.before_context),('audit_after'::text,ev.after_context))side(source_type,body)
 where ev.aggregate_type in('posting_mappings','supplier_bill_controls') and ev.legal_entity_id is not null
), candidates as (
 select s.tenant_id,s.legal_entity_id,case when s.aggregate_type='posting_mappings' then 'AR' else 'AP' end kind,
  case when s.aggregate_type='posting_mappings' then s.body->>'account_id' else s.body->>'payable_account_id' end account_text,
  s.source_type,s.id source_id,s.occurred_at,s.actor_id
 from snapshots s where s.body is not null and
  (s.aggregate_type='supplier_bill_controls' or s.body->>'purpose'='receivable_control')
)
insert into finance.control_account_basis(tenant_id,legal_entity_id,kind,account_id,source_type,source_id,source_version,observed_at,actor_id)
select c.tenant_id,c.legal_entity_id,c.kind,a.id,c.source_type,c.source_id,0,c.occurred_at,c.actor_id
from candidates c join finance.accounts a on a.tenant_id=c.tenant_id and a.legal_entity_id=c.legal_entity_id
 and a.id::text=c.account_text and a.account_type=case c.kind when 'AR' then 'asset' else 'liability' end
on conflict do nothing;

create function finance.record_control_mapping_basis() returns trigger
language plpgsql security definer set search_path='' as $$
declare k text;old_account uuid;new_account uuid;source uuid;v bigint;tenant uuid;entity uuid;actor uuid;typ text;begin
 if TG_TABLE_SCHEMA='finance' then
  if new.purpose<>'receivable_control' then return new;end if;
  k:='AR';new_account:=new.account_id;source:=new.id;v:=new.version;
  tenant:=new.tenant_id;entity:=new.legal_entity_id;actor:=new.updated_by;
  if TG_OP='UPDATE' then old_account:=old.account_id;end if;
 else
  k:='AP';new_account:=new.payable_account_id;source:=new.legal_entity_id;v:=new.version;
  tenant:=new.tenant_id;entity:=new.legal_entity_id;actor:=new.updated_by;
  if TG_OP='UPDATE' then old_account:=old.payable_account_id;end if;
 end if;
 typ:=case k when 'AR' then 'asset' else 'liability' end;
 if not exists(select 1 from finance.accounts a where a.tenant_id=tenant and a.legal_entity_id=entity
  and a.id=new_account and a.account_type=typ) then
  raise exception using errcode='22023',message='CONTROL_ACCOUNT_TYPE_INVALID';end if;
 if old_account is not null and old_account is distinct from new_account then
  insert into finance.control_account_basis(tenant_id,legal_entity_id,kind,account_id,source_type,source_id,source_version,observed_at,actor_id)
  values(tenant,entity,k,old_account,'future_mapping_old',source,v,statement_timestamp(),actor) on conflict do nothing;
 end if;
 insert into finance.control_account_basis(tenant_id,legal_entity_id,kind,account_id,source_type,source_id,source_version,observed_at,actor_id)
 values(tenant,entity,k,new_account,'future_mapping_new',source,v,statement_timestamp(),actor) on conflict do nothing;
 return new;
end $$;
revoke all on function finance.record_control_mapping_basis() from public,anon,authenticated;
create trigger control_mapping_basis after insert or update of account_id,status on finance.posting_mappings
 for each row execute function finance.record_control_mapping_basis();
create trigger supplier_mapping_basis after insert or update of payable_account_id on procurement.supplier_bill_controls
 for each row execute function finance.record_control_mapping_basis();

create or replace function finance.build_ar_ap_control_report_v1(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d date:=(p->>'as_of')::date;k text:=p->>'kind';sgn integer;
 items jsonb;allocations jsonb;entries jsonb;journals jsonb;accounts jsonb;differences jsonb;result jsonb;
 ids uuid[];sv numeric;gv numeric;unsupported bigint;begin
 perform finance.require_control_scope(t,e,b);
 if k is null or k not in('AR','AP') or d is null or d>(statement_timestamp() at time zone 'UTC')::date then
 raise exception using errcode='22023',message='CONTROL_REPORT_INPUT_INVALID';end if;
 sgn:=case k when 'AR' then 1 else -1 end;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into items from (
  select o.id,o.party_id,party.display_name party_name,o.source_type,o.source_id,o.document_number,o.journal_entry_id,o.command_id,
  o.posting_date,o.due_date,o.currency_code,o.base_currency_code,finance.open_item_control(t,o.id)::text evidence_key,
  o.original_amount::text original_amount,o.original_base_amount::text original_base_amount,
  r->>'amount' open_amount,r->>'base_amount' open_base_amount,
  (o.original_amount-(r->>'amount')::numeric)::text settled_amount,
  (o.original_base_amount-(r->>'base_amount')::numeric)::text settled_base_amount
  from finance.open_items o join crm.parties party on party.id=o.party_id
  cross join lateral (select finance.flow_residual(t,o.id,d) r) residual
  where o.tenant_id=t and o.legal_entity_id=e and o.branch_id=b and o.kind=k and o.posting_date<=d order by o.id limit 10001)q;
 if jsonb_array_length(items)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into allocations from (
  select a.id,a.command_id,a.source_open_item_id,a.target_open_item_id,s.document_number source_document_number,z.document_number target_document_number,
  a.posting_date,a.journal_entry_id,a.source_amount::text,a.transaction_amount::text,a.source_base_amount::text,a.target_base_amount::text,
  a.write_off::text,a.discount_amount::text,a.adjustment_base_amount::text,a.exchange_difference::text,a.reason,
  finance.open_item_control(t,s.id)::text source_control,finance.open_item_control(t,z.id)::text evidence_key,
  case when r.id is not null then sales.flow_exact_json(to_jsonb(r)) end reversal
  from finance.open_item_allocations a join finance.open_items s on s.id=a.source_open_item_id join finance.open_items z on z.id=a.target_open_item_id
  left join finance.allocation_reversals r on r.allocation_id=a.id and r.posting_date<=d
  where a.tenant_id=t and a.legal_entity_id=e and a.branch_id=b and s.kind=k and a.posting_date<=d order by a.id limit 10001)q;
 if jsonb_array_length(allocations)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select array_agg(distinct id order by id) into ids from (
  select (x->>'evidence_key')::uuid id from jsonb_array_elements(items)x
  union select account_id from finance.posting_mappings where tenant_id=t and legal_entity_id=e and purpose='receivable_control' and k='AR'
  union select payable_account_id from procurement.supplier_bill_controls where tenant_id=t and legal_entity_id=e and k='AP'
  union select account_id from finance.control_account_basis where tenant_id=t and legal_entity_id=e and kind=k
   and observed_at < (d + 1)::timestamptz)a where id is not null;
 if coalesce(cardinality(ids),0) not between 1 and 50 then raise exception using errcode='55000',message='CONTROL_ACCOUNT_SETUP_REQUIRED';end if;
 -- Dated subledger movements retain original command lineage, including exact reversal effects.
 with movements as (
  select 'item:'||(x->>'id') id,x->>'evidence_key' evidence_key,x->>'command_id' command_id,x->>'source_type' source_type,x->>'source_id' source_id,
   x->>'posting_date' posting_date,(x->>'original_base_amount')::numeric value from jsonb_array_elements(items)x
  union all select 'allocation-source:'||(x->>'id'),x->>'source_control',x->>'command_id','allocation',x->>'id',x->>'posting_date',(x->>'source_base_amount')::numeric from jsonb_array_elements(allocations)x
  union all select 'allocation-target:'||(x->>'id'),x->>'evidence_key',x->>'command_id','allocation',x->>'id',x->>'posting_date',-(x->>'target_base_amount')::numeric-(x->>'adjustment_base_amount')::numeric from jsonb_array_elements(allocations)x
  union all select 'reversal-source:'||(x#>>'{reversal,id}'),x->>'source_control',x#>>'{reversal,command_id}','allocation_reversal',x#>>'{reversal,id}',x#>>'{reversal,posting_date}',-(x->>'source_base_amount')::numeric from jsonb_array_elements(allocations)x where x->'reversal'<>'null'::jsonb
  union all select 'reversal-target:'||(x#>>'{reversal,id}'),x->>'evidence_key',x#>>'{reversal,command_id}','allocation_reversal',x#>>'{reversal,id}',x#>>'{reversal,posting_date}',(x->>'target_base_amount')::numeric+(x->>'adjustment_base_amount')::numeric from jsonb_array_elements(allocations)x where x->'reversal'<>'null'::jsonb)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'evidence_key',evidence_key,'command_id',command_id,'source_type',source_type,'source_id',source_id,'posting_date',posting_date,'value',value::text) order by id),'[]') into entries from movements;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id::text evidence_key,a.code account_code,j.command_id,j.id journal_id,j.document_number,j.source_type,j.source_id,l.source_line_id,l.posting_date,
   (sgn*(l.base_debit-l.base_credit))::text value,l.base_debit::text,l.base_credit::text
  from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id join finance.accounts a on a.id=l.account_id
  where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.account_id=any(ids) and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select jsonb_agg(jsonb_build_object('id',a.id,'evidence_key',a.id,'code',a.code,'name',a.name,'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a.id)
 into accounts from finance.accounts a
 cross join lateral(select coalesce(sum((x->>'open_base_amount')::numeric),0) v from jsonb_array_elements(items)x where x->>'evidence_key'=a.id::text)s
 cross join lateral(select coalesce(sum((x->>'value')::numeric),0) g from jsonb_array_elements(journals)x where x->>'evidence_key'=a.id::text)j where a.id=any(ids);
 with effects as (
  select x->>'evidence_key' a,x->>'command_id' c,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(entries)x
  union all select x->>'evidence_key',x->>'command_id',0,(x->>'value')::numeric from jsonb_array_elements(journals)x), totals as(select a,c,sum(v)v,sum(g)g from effects group by a,c)
 select coalesce(jsonb_agg(jsonb_build_object('id',a||':'||c,'evidence_key',a,'command_id',c,'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a,c),'[]') into differences from totals where v<>g;
 if greatest(jsonb_array_length(entries),jsonb_array_length(differences))>50000 then raise exception using errcode='54000',message='CONTROL_REPORT_OUTPUT_LIMIT';end if;
 select coalesce(sum((x->>'subledger_value')::numeric),0),coalesce(sum((x->>'gl_value')::numeric),0) into sv,gv from jsonb_array_elements(accounts)x;
 if sv<>(select coalesce(sum((x->>'value')::numeric),0) from jsonb_array_elements(entries)x) then raise exception using errcode='23514',message='CONTROL_RESIDUAL_DIVERGENCE';end if;
 select coalesce(jsonb_agg(x||jsonb_build_object('basis',coalesce((
  select jsonb_agg(jsonb_build_object('source',basis.source_type,'source_id',basis.source_id,
   'observed_at',basis.observed_at) order by basis.observed_at,basis.id)
  from finance.control_account_basis basis where basis.tenant_id=t and basis.legal_entity_id=e
   and basis.kind=k and basis.account_id=(x->>'id')::uuid and basis.observed_at<(d+1)::timestamptz),'[]'::jsonb)) order by x->>'id'),'[]')
 into accounts from jsonb_array_elements(accounts)x;
 select count(*) into unsupported from audit.events ev cross join lateral
 (values(ev.before_context),(ev.after_context)) snapshot(body)
 where ev.tenant_id=t and ev.legal_entity_id=e and ev.aggregate_type in('posting_mappings','supplier_bill_controls')
  and ev.occurred_at<(d+1)::timestamptz
  and ((k='AR' and ev.aggregate_type='posting_mappings' and snapshot.body->>'purpose'='receivable_control'
    and snapshot.body ? 'account_id' and not exists(select 1 from finance.control_account_basis basis
     where basis.tenant_id=t and basis.kind=k and basis.source_id=ev.id and basis.account_id::text=snapshot.body->>'account_id'))
   or (k='AP' and ev.aggregate_type='supplier_bill_controls' and snapshot.body ? 'payable_account_id'
    and not exists(select 1 from finance.control_account_basis basis
     where basis.tenant_id=t and basis.kind=k and basis.source_id=ev.id and basis.account_id::text=snapshot.body->>'payable_account_id')));
 result:=jsonb_build_object('summary',jsonb_build_object('id',p->>'id','version',1,'status','generated','kind',k,'as_of',d,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
 'entity_name',(select name from core.legal_entities where id=e),'branch_name',(select name from core.branches where id=b),
 'currency_code',(select currency_code from core.legal_entities where id=e),'generated_at',statement_timestamp(),
 'accounts',accounts,'subledger_value',sv::text,'gl_value',gv::text,'difference',(sv-gv)::text,'item_count',jsonb_array_length(items),'difference_count',jsonb_array_length(differences),
 'basis_coverage',jsonb_build_object('registry_accounts',(
  select count(distinct account_id) from finance.control_account_basis
  where tenant_id=t and legal_entity_id=e and kind=k and observed_at<(d+1)::timestamptz),
  'source_accounts',(
   select count(distinct x->>'evidence_key') from jsonb_array_elements(items)x),
  'unsupported_legacy_audit_snapshots',unsupported)),
 'items',items,'allocations',allocations,'entries',entries,'journals',journals,'accounts',accounts,'differences',differences);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='CONTROL_REPORT_EVIDENCE_LIMIT';end if;
 return result;
end $$;

revoke all on function finance.build_ar_ap_control_report_v1(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create or replace function finance.build_control_report(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d date:=(p->>'as_of')::date;receipts jsonb;matches jsonb;returns jsonb;reversals jsonb;
 items jsonb;entries jsonb;journals jsonb;accounts jsonb;differences jsonb;result jsonb;
 ids uuid[];sv numeric;gv numeric;receipt_count integer;begin
 if p->>'kind' is distinct from 'GRNI' then return finance.build_ar_ap_control_report_v1(t,e,b,p);end if;
 perform finance.require_control_scope(t,e,b);
 if d is null or d>(statement_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='CONTROL_REPORT_INPUT_INVALID';end if;
 select count(*) into receipt_count from (
  select id from procurement.goods_receipts where tenant_id=t and legal_entity_id=e
   and branch_id=b and document_date<=d limit 10001) bounded;
 if receipt_count>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into receipts from (
  select r.id,r.id receipt_id,'goods_receipt'::text source_type,r.id source_id,r.command_id,r.journal_entry_id,
   r.document_number,r.document_date posting_date,r.currency_code,r.base_currency_code,
   r.source_snapshot->>'supplier_id' party_id,coalesce(r.source_snapshot->>'supplier_name',party.display_name,'Supplier') party_name,
   finance.receipt_grni_control(t,r.id)::text evidence_key,r.net_amount::text original_amount,r.base_amount::text original_base_amount
  from procurement.goods_receipts r left join crm.parties party on party.id=(r.source_snapshot->>'supplier_id')::uuid and party.tenant_id=r.tenant_id
  where r.tenant_id=t and r.legal_entity_id=e and r.branch_id=b and r.document_date<=d order by r.id limit 10001)q;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into matches from (
  select l.id,r.id receipt_id,'supplier_bill'::text source_type,h.id source_id,h.document_date posting_date,h.document_number,
   h.journal_entry_id,j.command_id,l.detail->>'grni_account_id' evidence_key,
   l.detail->>'accrual_amount' amount,l.detail->>'accrual_base_amount' base_amount
  from procurement.supplier_bill_lines l join procurement.supplier_bills h on h.id=l.bill_id and h.tenant_id=l.tenant_id
  join procurement.goods_receipt_lines rl on rl.id=l.receipt_line_id and rl.tenant_id=l.tenant_id
  join procurement.goods_receipts r on r.id=rl.receipt_id and r.tenant_id=l.tenant_id
  left join finance.journal_entries j on j.id=h.journal_entry_id and j.tenant_id=h.tenant_id
  where h.tenant_id=t and h.legal_entity_id=e and h.branch_id=b and h.status='posted' and h.document_date<=d
   and r.document_date<=d order by l.id limit 10001)q;
 if exists(select 1 from jsonb_array_elements(matches)x where x->>'evidence_key' is null or x->>'amount' is null or x->>'base_amount' is null)
 then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into returns from (
  select h.id,r.id receipt_id,'purchase_return'::text source_type,h.id source_id,h.document_date posting_date,h.document_number,
   h.journal_entry_id,h.command_id,finance.receipt_grni_control(t,r.id)::text evidence_key,h.total::text amount,h.base_total::text base_amount
  from procurement.purchase_returns h join procurement.goods_receipts r on r.id=h.source_id and r.tenant_id=h.tenant_id
  where h.tenant_id=t and h.legal_entity_id=e and h.branch_id=b and h.source_kind='receipt' and h.document_date<=d and r.document_date<=d order by h.id limit 10001)q;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into reversals from (
  select h.id,r.id receipt_id,'goods_receipt_reversal'::text source_type,h.id source_id,h.document_date posting_date,
   h.journal_entry_id,h.command_id,finance.receipt_grni_control(t,r.id)::text evidence_key,r.net_amount::text amount,r.base_amount::text base_amount
  from procurement.goods_receipt_reversals h join procurement.goods_receipts r on r.id=h.receipt_id and r.tenant_id=h.tenant_id
  where h.tenant_id=t and h.legal_entity_id=e and h.branch_id=b and h.document_date<=d and r.document_date<=d order by h.id limit 10001)q;
 if greatest(jsonb_array_length(receipts),jsonb_array_length(matches),jsonb_array_length(returns),jsonb_array_length(reversals))>10000
 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 with movements as (
  select x,1 sgn,x->>'original_amount' amount,x->>'original_base_amount' base from jsonb_array_elements(receipts)x
  union all select x,-1,x->>'amount',x->>'base_amount' from jsonb_array_elements(matches)x
  union all select x,-1,x->>'amount',x->>'base_amount' from jsonb_array_elements(returns)x
  union all select x,-1,x->>'amount',x->>'base_amount' from jsonb_array_elements(reversals)x)
 select coalesce(jsonb_agg(x||jsonb_build_object('id',(x->>'source_type')||':'||(x->>'id'),
  'transaction_value',(sgn*amount::numeric)::text,'value',(sgn*base::numeric)::text) order by x->>'source_type',x->>'id'),'[]') into entries
 from movements where x->>'evidence_key' is not null;
 with residuals as (
  select z->>'receipt_id' id,sum((z->>'transaction_value')::numeric)a,sum((z->>'value')::numeric)v
  from jsonb_array_elements(entries)z group by z->>'receipt_id')
 select coalesce(jsonb_agg(x||jsonb_build_object('settled_amount',((x->>'original_amount')::numeric-coalesce(a,0))::text,
  'settled_base_amount',((x->>'original_base_amount')::numeric-coalesce(v,0))::text,
  'open_amount',coalesce(a,0)::text,'open_base_amount',coalesce(v,0)::text) order by x->>'id'),'[]') into items
 from jsonb_array_elements(receipts)x left join residuals tot on tot.id=x->>'id';
 select array_agg(distinct id order by id) into ids from (
  select (x->>'evidence_key')::uuid id from jsonb_array_elements(entries)x
  union select grni_account_id from procurement.receipt_controls where tenant_id=t and legal_entity_id=e
  union select (snapshot->>'grni_account_id')::uuid from procurement.receipt_control_history where tenant_id=t and legal_entity_id=e)a where id is not null;
 if coalesce(cardinality(ids),0) not between 1 and 50 then raise exception using errcode='55000',message='CONTROL_ACCOUNT_SETUP_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by id),'[]') into journals from (
  select l.id,l.account_id::text evidence_key,a.code account_code,j.command_id,j.id journal_id,j.document_number,j.source_type,j.source_id,l.source_line_id,l.posting_date,
   (l.base_credit-l.base_debit)::text value,l.base_debit::text,l.base_credit::text
  from finance.journal_lines l join finance.journal_entries j on j.id=l.journal_entry_id and j.tenant_id=l.tenant_id
  join finance.accounts a on a.id=l.account_id and a.tenant_id=l.tenant_id
  where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.account_id=any(ids) and j.status='posted' and l.posting_date<=d order by l.id limit 10001)q;
 if jsonb_array_length(journals)>10000 then raise exception using errcode='54000',message='CONTROL_REPORT_INPUT_LIMIT';end if;
 select jsonb_agg(jsonb_build_object('id',a.id,'evidence_key',a.id,'code',a.code,'name',a.name,
  'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a.id) into accounts from finance.accounts a
 cross join lateral(select coalesce(sum((x->>'value')::numeric),0)v from jsonb_array_elements(entries)x where x->>'evidence_key'=a.id::text)s
 cross join lateral(select coalesce(sum((x->>'value')::numeric),0)g from jsonb_array_elements(journals)x where x->>'evidence_key'=a.id::text)j
 where a.tenant_id=t and a.legal_entity_id=e and a.id=any(ids);
 if jsonb_array_length(accounts)<>cardinality(ids) then raise exception using errcode='55000',message='GRNI_CONTROL_BASIS_REQUIRED';end if;
 with effects as (
  select x->>'evidence_key' a,x->>'source_type' st,x->>'source_id' si,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(entries)x
  union all select x->>'evidence_key',x->>'source_type',x->>'source_id',0,(x->>'value')::numeric from jsonb_array_elements(journals)x),
 totals as(select a,st,si,sum(v)v,sum(g)g from effects group by a,st,si)
 select coalesce(jsonb_agg(jsonb_build_object('id',a||':'||st||':'||si,'evidence_key',a,'source_type',st,'source_id',si,
  'subledger_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by a,st,si),'[]') into differences from totals where v<>g;
 if greatest(jsonb_array_length(entries),jsonb_array_length(differences))>50000 then raise exception using errcode='54000',message='CONTROL_REPORT_OUTPUT_LIMIT';end if;
 select coalesce(sum((x->>'subledger_value')::numeric),0),coalesce(sum((x->>'gl_value')::numeric),0) into sv,gv from jsonb_array_elements(accounts)x;
 if sv<>(select coalesce(sum((x->>'open_base_amount')::numeric),0) from jsonb_array_elements(items)x)
 then raise exception using errcode='23514',message='CONTROL_RESIDUAL_DIVERGENCE';end if;
 result:=jsonb_build_object('summary',jsonb_build_object('id',p->>'id','version',1,'status','generated','kind','GRNI','as_of',d,'tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'entity_name',(select name from core.legal_entities where id=e),'branch_name',(select name from core.branches where id=b),
  'currency_code',(select currency_code from core.legal_entities where id=e),'generated_at',statement_timestamp(),'accounts',accounts,
  'subledger_value',sv::text,'gl_value',gv::text,'difference',(sv-gv)::text,'item_count',jsonb_array_length(items),'difference_count',jsonb_array_length(differences)),
  'items',items,'allocations','[]'::jsonb,'entries',entries,'journals',journals,'accounts',accounts,'differences',differences);
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='CONTROL_REPORT_EVIDENCE_LIMIT';end if;
 return result;end $$;

revoke all on function finance.build_control_report(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED bounded reservation lifecycle maintenance. All effects use the
-- existing release command, which locks order, product/warehouse and projection.
create index reservation_maintenance_cursor on inventory.stock_reservations
 (tenant_id,legal_entity_id,branch_id,status,sales_order_id,id)
 include(expires_at,product_id);

create function api.maintain_stock_reservations(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,
 p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_mode text:=p_payload->>'mode';
 v_reason text:=btrim(coalesce(p_payload->>'reason',''));
 v_limit integer:=(p_payload->>'limit')::integer;
 v_after_order uuid:=(p_payload->>'after_order_id')::uuid;
 v_after_reservation uuid:=(p_payload->>'after_reservation_id')::uuid;
 v_last_order uuid:=v_after_order;v_last_reservation uuid:=v_after_reservation;
 v_hash text;v_replay jsonb;v_child jsonb;v_result jsonb;v_rows jsonb:='[]';
 v_count integer:=0;v_more boolean;v_request uuid:=gen_random_uuid();r record;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.reservations.manage',p_legal_entity_id,p_branch_id);
 if v_id is null or p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
  or p_command_id is null or p_idempotency_key is null or v_mode is null
  or v_mode not in('expired','retired') or v_limit is null
  or v_limit not between 1 and 50 or length(v_reason) not between 3 and 1000
  or (v_after_order is null) is distinct from (v_after_reservation is null)
  or jsonb_typeof(p_payload) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(p_payload) key
   where key not in('id','mode','reason','limit','after_order_id','after_reservation_id')) then
  raise exception using errcode='22023',message='RESERVATION_MAINTENANCE_INPUT_INVALID';end if;
 v_hash:=core.wave3_request_hash('inventory.reservation.maintain',p_command_id,p_tenant_id,
  p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_replay:=core.wave3_replay(p_tenant_id,'inventory.reservation.maintain',p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 for r in
  select res.id,res.version,res.sales_order_id from inventory.stock_reservations res
  join inventory.products product on product.tenant_id=res.tenant_id and product.id=res.product_id
  where res.tenant_id=p_tenant_id and res.legal_entity_id=p_legal_entity_id and res.branch_id=p_branch_id
   and res.status='active'
   and (v_after_order is null or (res.sales_order_id,res.id)>(v_after_order,v_after_reservation))
   and ((v_mode='expired' and res.expires_at<=statement_timestamp())
    or (v_mode='retired' and product.status<>'active'))
  order by res.sales_order_id,res.id limit v_limit
 loop
  v_child:=api.release_stock_reservation(p_tenant_id,p_legal_entity_id,p_branch_id,
   gen_random_uuid(),gen_random_uuid(),p_client_timestamp,
   jsonb_build_object('id',r.id,'mode',v_mode,'reason',v_reason),r.version);
  v_rows:=v_rows||jsonb_build_array(jsonb_build_object('reservation_id',r.id,
   'sales_order_id',r.sales_order_id,'receipt_id',v_child->>'request_id'));
  v_last_order:=r.sales_order_id;v_last_reservation:=r.id;v_count:=v_count+1;
 end loop;
 select exists(
  select 1 from inventory.stock_reservations res
  join inventory.products product on product.tenant_id=res.tenant_id and product.id=res.product_id
  where res.tenant_id=p_tenant_id and res.legal_entity_id=p_legal_entity_id and res.branch_id=p_branch_id
   and res.status='active'
   and (v_last_order is null or (res.sales_order_id,res.id)>(v_last_order,v_last_reservation))
   and ((v_mode='expired' and res.expires_at<=statement_timestamp())
    or (v_mode='retired' and product.status<>'active'))
 ) into v_more;
 v_result:=jsonb_build_object('id',v_id,'status','completed','tenant_id',p_tenant_id,
  'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'mode',v_mode,
  'processed_count',v_count,'processed',v_rows,'has_more',v_more,
  'next_cursor',case when v_more and v_count>0 then
   jsonb_build_object('after_order_id',v_last_order,'after_reservation_id',v_last_reservation) end);
 return core.wave3_finish_command(p_tenant_id,'inventory.reservation.maintain',p_command_id,
  'reservation_maintenance',v_id,p_idempotency_key,v_hash,null,v_result,
  p_legal_entity_id,p_branch_id,'{}',null,
  jsonb_build_array(jsonb_build_object('topic','inventory.reservation.maintained','payload',
   jsonb_build_object('id',v_id,'mode',v_mode,'processed_count',v_count))),
  '[]',v_request,v_request);
end $$;
revoke all on function api.maintain_stock_reservations(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.maintain_stock_reservations(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive read contract; no posting engine or historical writes.
create function api.posted_journal_evidence(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_journal_id uuid,p_after_line integer default 0) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare j finance.journal_entries%rowtype;header jsonb;rows jsonb;result jsonb;n integer;
 debit numeric;credit numeric;tx_debit numeric;tx_credit numeric;next_line integer;stock_branch uuid;branches uuid[];
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then
  raise exception using errcode='42501',message='JOURNAL_UNAVAILABLE';end if;
 select * into j from finance.journal_entries where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=p_journal_id and status='posted';
 if not found then raise exception using errcode='42501',message='JOURNAL_UNAVAILABLE';end if;
 -- Historical source branches may be retired. Authorization is still current.
 perform core.require_permission(p_tenant_id,'finance.view',p_legal_entity_id,j.branch_id);
 if not exists(select 1 from core.branches where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=j.branch_id) then
  raise exception using errcode='42501',message='JOURNAL_UNAVAILABLE';end if;
 select array_agg(branch_id) into branches from(select distinct branch_id from inventory.stock_movements
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and command_id=j.command_id limit 501)q;
 if cardinality(branches)>500 then raise exception using errcode='54000',message='JOURNAL_BRANCH_LIMIT';end if;
 if cardinality(branches)>0 then
  branches:=branches||array[p_branch_id,j.branch_id];
  for stock_branch in select distinct unnest(branches) loop
   perform core.require_permission(p_tenant_id,'inventory.stock.view',p_legal_entity_id,stock_branch);
   perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,stock_branch);
  end loop;
 end if;
 if p_after_line is null or p_after_line<0 or p_after_line>10000 or (p_after_line>0 and not exists(
  select 1 from finance.journal_lines where tenant_id=p_tenant_id and journal_entry_id=j.id and line_number=p_after_line)) then
  raise exception using errcode='22023',message='JOURNAL_CURSOR_INVALID';end if;
 select count(*),sum(base_debit),sum(base_credit),sum(transaction_debit),sum(transaction_credit)
  into n,debit,credit,tx_debit,tx_credit from finance.journal_lines where tenant_id=p_tenant_id and journal_entry_id=j.id;
 if n>10000 then raise exception using errcode='54000',message='JOURNAL_LINE_LIMIT';end if;
 if n<2 or debit<>credit then raise exception using errcode='55000',message='JOURNAL_BALANCE_INVALID';end if;
 header:=sales.flow_exact_json(jsonb_build_object('id',j.id,'tenant_id',j.tenant_id,'legal_entity_id',j.legal_entity_id,
  'branch_id',j.branch_id,'branch_name',(select name from core.branches where tenant_id=j.tenant_id and id=j.branch_id),
  'branch_status',(select status from core.branches where tenant_id=j.tenant_id and id=j.branch_id),
  'document_number',j.document_number,'posting_date',j.posting_date,'status',j.status,'fiscal_period_id',j.fiscal_period_id,
  'currency_code',j.currency_code,'base_currency_code',j.base_currency_code,'exchange_rate',j.exchange_rate,
  'source_type',j.source_type,'source_id',j.source_id,'command_id',j.command_id,'request_id',j.request_id,
  'correlation_id',j.correlation_id,'rule_version',j.rule_version,'created_at',j.created_at,'created_by',j.created_by,
  'transaction_debit',tx_debit,'transaction_credit',tx_credit,'base_debit',debit,'base_credit',credit))
  ||jsonb_build_object('line_count',n,'label_basis','current_catalogue','stock_cost_access_required',coalesce(cardinality(branches)>0,false));
 select coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(q)) order by line_number),'[]') into rows from(
  select l.id,l.tenant_id,l.legal_entity_id,l.branch_id,l.journal_entry_id,l.line_number,l.account_id,
   a.code account_code,a.name account_name,a.status account_status,l.party_id,l.source_line_id,l.currency_code,
   l.transaction_debit,l.transaction_credit,l.base_debit,l.base_credit,l.posting_date,
   l.cost_centre_id,l.project_id,l.dimension_snapshot
  from finance.journal_lines l join finance.accounts a on a.tenant_id=l.tenant_id and a.legal_entity_id=l.legal_entity_id and a.id=l.account_id
  where l.tenant_id=p_tenant_id and l.journal_entry_id=j.id and l.line_number>p_after_line order by l.line_number limit 51)q;
 if jsonb_array_length(rows)=51 then rows:=rows-50;next_line:=(rows->49->>'line_number')::integer;end if;
 result:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'journal_id',j.id,'after_line',p_after_line,'journal',header,'items',rows,'next_cursor',next_line);
 if octet_length(result::text)>1048576 then raise exception using errcode='54000',message='JOURNAL_RESPONSE_LIMIT';end if;
 return result;
end$$;
revoke all on function api.posted_journal_evidence(uuid,uuid,uuid,uuid,integer) from public,anon,authenticated;
grant execute on function api.posted_journal_evidence(uuid,uuid,uuid,uuid,integer) to authenticated;
notify pgrst,'reload schema';

-- W4-03A synthetic attendance and the shared payable interval arbiter.
-- Candidate only; depends on W4-02A organization and IANA resolver installation.
-- No existing role, plan, subscriber or employee/calendar fact is changed.
create extension if not exists btree_gist with schema extensions;

insert into core.permissions(code,module,description,privileged) values
 ('people.attendance.view','people','Read scoped attendance and work history',false),
 ('people.attendance.manage','people','Prepare scoped attendance revisions',true),
 ('people.attendance.import','people','Import immutable raw clock events',true),
 ('people.attendance.approve','people','Independently decide attendance',true),
 ('people.work_claims.view','people','Read authorized payable interval claims',false)
on conflict(code) do nothing;

create table people.raw_clock_events(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 source_system text not null check(length(btrim(source_system)) between 1 and 80),
 source_key text not null check(length(btrim(source_key)) between 1 and 160),
 observed_utc timestamptz not null,checksum text not null check(checksum ~ '^[a-f0-9]{64}$'),
 imported_by uuid not null references auth.users(id),imported_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,source_system,source_key),unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index raw_clock_events_scope_idx on people.raw_clock_events(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index raw_clock_events_actor_idx on people.raw_clock_events(imported_by);

create table people.attendance_entries(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 current_revision_id uuid not null,
 status text not null check(status in ('draft','submitted','approved','rejected','cancelled')),
 submitted_by uuid references auth.users(id),decided_by uuid references auth.users(id),
 active_claim_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index attendance_entries_scope_idx on people.attendance_entries(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index attendance_entries_creator_idx on people.attendance_entries(created_by);
create index attendance_entries_submitter_idx on people.attendance_entries(submitted_by);
create index attendance_entries_decider_idx on people.attendance_entries(decided_by);

create table people.attendance_revisions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,entry_id uuid not null,
 version bigint not null check(version between 1 and 9007199254740991),
 calendar_version_id uuid not null,
 start_local timestamp not null,start_offset_seconds integer not null,
 end_local timestamp not null,end_offset_seconds integer not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 breaks jsonb not null default '[]'::jsonb,
 gross_seconds bigint not null check(gross_seconds between 1 and 129600),
 break_seconds bigint not null check(break_seconds>=0),
 payable_seconds bigint not null check(payable_seconds>0 and payable_seconds<=129600),
 raw_start_id uuid,raw_end_id uuid,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 supersedes_revision_id uuid,
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,entry_id,version),
 unique(tenant_id,legal_entity_id,employee_id,entry_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,entry_id)
  references people.attendance_entries(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,calendar_version_id)
  references people.work_calendar_versions(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,raw_start_id)
  references people.raw_clock_events(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,raw_end_id)
  references people.raw_clock_events(tenant_id,legal_entity_id,employee_id,id),
 foreign key(supersedes_revision_id) references people.attendance_revisions(id),
 check(end_utc>start_utc and gross_seconds=extract(epoch from end_utc-start_utc)::bigint
   and gross_seconds=break_seconds+payable_seconds),
 check((raw_start_id is null and raw_end_id is null) or
   (raw_start_id is not null and raw_end_id is not null and raw_start_id<>raw_end_id))
);
create index attendance_revisions_entry_idx on people.attendance_revisions(tenant_id,legal_entity_id,entry_id,id);
create index attendance_revisions_calendar_idx on people.attendance_revisions(tenant_id,legal_entity_id,calendar_version_id);
create index attendance_revisions_raw_start_idx on people.attendance_revisions(raw_start_id);
create index attendance_revisions_raw_end_idx on people.attendance_revisions(raw_end_id);
create index attendance_revisions_actor_idx on people.attendance_revisions(recorded_by);
create index attendance_revisions_supersedes_idx on people.attendance_revisions(supersedes_revision_id);
alter table people.attendance_entries add foreign key(tenant_id,legal_entity_id,employee_id,id,current_revision_id)
 references people.attendance_revisions(tenant_id,legal_entity_id,employee_id,entry_id,id)
 deferrable initially deferred;

create table people.work_claims(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 source_kind text not null check(source_kind in ('attendance','project','service','leave')),
 source_id uuid not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 gross_seconds bigint not null check(gross_seconds between 1 and 129600),
 break_seconds bigint not null check(break_seconds>=0),
 payable_seconds bigint not null check(payable_seconds>=0),
 calendar_version_id uuid not null,
 active boolean not null default true,revoked_at timestamptz,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,id),
 unique(tenant_id,legal_entity_id,source_kind,source_id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,calendar_version_id)
  references people.work_calendar_versions(tenant_id,legal_entity_id,id),
 check(end_utc>start_utc and gross_seconds=extract(epoch from end_utc-start_utc)::bigint),
 check((source_kind='leave' and break_seconds=0 and payable_seconds=0) or
   (source_kind<>'leave' and gross_seconds=break_seconds+payable_seconds)),
 check(active=(revoked_at is null)),
 check((source_kind='leave' and payable_seconds=0) or
   (source_kind<>'leave' and payable_seconds>0))
);
create index work_claims_scope_idx on people.work_claims(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index work_claims_calendar_idx on people.work_claims(tenant_id,legal_entity_id,calendar_version_id);
create index work_claims_creator_idx on people.work_claims(created_by);
create table people.work_claim_segments(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 employee_id uuid not null,claim_id uuid not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 active boolean not null default true,
 foreign key(tenant_id,legal_entity_id,employee_id,claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id),
 check(end_utc>start_utc),
 exclude using gist(employee_id extensions.gist_uuid_ops with =,
   tstzrange(start_utc,end_utc,'[)') with &&) where(active)
);
create index work_claim_segments_claim_idx on people.work_claim_segments(claim_id);
create table people.work_allocations(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,claim_id uuid not null,
 source_kind text not null check(source_kind in ('project','service')),
 source_id uuid not null,start_utc timestamptz not null,end_utc timestamptz not null,
 active boolean not null default true,revoked_at timestamptz,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,source_kind,source_id),
 foreign key(tenant_id,legal_entity_id,employee_id,claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 check(end_utc>start_utc and active=(revoked_at is null)),
 exclude using gist(employee_id extensions.gist_uuid_ops with =,
  tstzrange(start_utc,end_utc,'[)') with &&) where(active)
);
create index work_allocations_claim_idx on people.work_allocations(claim_id);
create index work_allocations_scope_idx on people.work_allocations(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index work_allocations_actor_idx on people.work_allocations(created_by);
create table people.work_input_seals(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 employee_id uuid not null,run_id uuid not null,claim_id uuid not null,
 source_version bigint not null check(source_version>0),seconds bigint not null check(seconds>=0),
 digest text not null check(digest ~ '^[a-f0-9]{64}$'),sealed_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,run_id,claim_id),
 foreign key(tenant_id,legal_entity_id,employee_id,claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id)
);
create index work_input_seals_claim_idx on people.work_input_seals(claim_id);

create table people.attendance_events(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,entry_id uuid not null,revision_id uuid not null,
 action text not null check(action in ('create','correct','submit','approve','reject','cancel')),
 before_status text,after_status text not null,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 actor_id uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 command_id uuid not null,unique(tenant_id,legal_entity_id,command_id),
 foreign key(tenant_id,legal_entity_id,employee_id,entry_id,revision_id)
  references people.attendance_revisions(tenant_id,legal_entity_id,employee_id,entry_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index attendance_events_entry_idx on people.attendance_events(tenant_id,legal_entity_id,branch_id,entry_id,id);
create index attendance_events_actor_idx on people.attendance_events(actor_id);

do $$declare v_table regclass;begin
 foreach v_table in array array[
  'people.raw_clock_events'::regclass,'people.attendance_entries'::regclass,
  'people.attendance_revisions'::regclass,'people.work_claims'::regclass,
  'people.work_claim_segments'::regclass,'people.work_allocations'::regclass,
  'people.work_input_seals'::regclass,
  'people.attendance_events'::regclass] loop
  execute format('alter table %s enable row level security',v_table);
  execute format('alter table %s force row level security',v_table);
  execute format('revoke all on %s from public,anon,authenticated',v_table);
 end loop;
end $$;

create function people.work_history_guard() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='UPDATE' and tg_table_name='work_claims' then
  if old.active and not new.active and new.revoked_at is not null
   and (to_jsonb(new)-'active'-'revoked_at')=(to_jsonb(old)-'active'-'revoked_at') then
   return new;end if;
 elsif tg_op='UPDATE' and tg_table_name='work_claim_segments' then
  if old.active and not new.active
   and (to_jsonb(new)-'active')=(to_jsonb(old)-'active') then return new;end if;
 elsif tg_op='UPDATE' and tg_table_name='work_allocations' then
  if old.active and not new.active and new.revoked_at is not null
   and (to_jsonb(new)-'active'-'revoked_at')=(to_jsonb(old)-'active'-'revoked_at') then
   return new;end if;
 end if;
 raise exception using errcode='55000',message='WORK_HISTORY_IMMUTABLE';
end $$;
create trigger raw_clock_immutable before update or delete on people.raw_clock_events
 for each row execute function people.work_history_guard();
create trigger attendance_revision_immutable before update or delete on people.attendance_revisions
 for each row execute function people.work_history_guard();
create trigger attendance_event_immutable before update or delete on people.attendance_events
 for each row execute function people.work_history_guard();
create trigger work_claim_guard before update or delete on people.work_claims
 for each row execute function people.work_history_guard();
create trigger work_segment_guard before update or delete on people.work_claim_segments
 for each row execute function people.work_history_guard();
create trigger work_allocation_guard before update or delete on people.work_allocations
 for each row execute function people.work_history_guard();
create trigger work_seal_immutable before update or delete on people.work_input_seals
 for each row execute function people.work_history_guard();

create function people.work_break_seconds(p_start timestamptz,p_end timestamptz,p_breaks jsonb)
returns bigint language plpgsql immutable set search_path='' as $$
declare v jsonb;v_start timestamptz;v_end timestamptz;v_cursor timestamptz:=p_start;
 v_seconds bigint:=0;begin
 if p_start is null or p_end is null or p_end<=p_start
  or extract(epoch from p_start)%1<>0 or extract(epoch from p_end)%1<>0
  or p_end-p_start>interval '36 hours'
  or coalesce(jsonb_typeof(p_breaks),'null')<>'array'
  or jsonb_array_length(p_breaks)>16 then
  raise exception using errcode='22023',message='WORK_INTERVAL_INVALID';end if;
 for v in select value from jsonb_array_elements(p_breaks) loop
  if jsonb_typeof(v)<>'object' or not(v ? 'start_utc' and v ? 'end_utc')
   or (select count(*) from jsonb_object_keys(v))<>2
   or coalesce(v->>'start_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$'
   or coalesce(v->>'end_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' then
   raise exception using errcode='22023',message='WORK_BREAK_INVALID';end if;
  v_start:=(v->>'start_utc')::timestamptz;v_end:=(v->>'end_utc')::timestamptz;
  if v_start<v_cursor or v_end<=v_start or v_end>p_end
   or extract(epoch from v_start)%1<>0 or extract(epoch from v_end)%1<>0 then
   raise exception using errcode='22023',message='WORK_BREAK_INVALID';end if;
  v_seconds:=v_seconds+extract(epoch from v_end-v_start)::bigint;
  v_cursor:=v_end;
 end loop;
 if v_seconds>=extract(epoch from p_end-p_start)::bigint then
  raise exception using errcode='22023',message='WORK_BREAK_INVALID';end if;
 return v_seconds;
end $$;

create function people.work_local_coverage(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_calendar_version uuid,p_start_local timestamp,p_end_local timestamp)
returns void language plpgsql security definer set search_path='' as $$
declare v_start date;v_end date;begin
 if p_start_local is null or p_end_local is null
  or p_start_local<'0001-01-01'::timestamp or p_end_local>='10000-01-01'::timestamp then
  raise exception using errcode='22023',message='WORK_LOCAL_BOUNDARY_INVALID';end if;
 v_start:=p_start_local::date;
 v_end:=greatest((p_end_local-interval '1 microsecond')::date+1,v_start+1);
 if v_end-v_start>3 then raise exception using errcode='22023',message='WORK_LOCAL_BOUNDARY_INVALID';end if;
 if not exists(select 1 from people.organization_assignments o
  join people.work_calendar_versions c on c.id=o.calendar_version_id
  where o.tenant_id=p_t and o.legal_entity_id=p_e and o.branch_id=p_b
   and o.employee_id=p_employee and o.calendar_version_id=p_calendar_version
   and o.superseded_at is null
   and daterange(o.start_date,o.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)')
   and daterange(c.start_date,c.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)'))
  or not exists(select 1 from people.employment_assignments a
   join people.employment_spells s on s.id=a.spell_id
   where a.tenant_id=p_t and a.legal_entity_id=p_e and a.branch_id=p_b
    and a.employee_id=p_employee
    and daterange(a.start_date,a.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)')
    and daterange(s.start_date,s.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)')) then
  raise exception using errcode='55000',message='WORK_COVERAGE_REQUIRED';end if;
end $$;

create function people.make_work_claim(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_kind text,p_source uuid,p_start timestamptz,p_end timestamptz,p_breaks jsonb,
 p_calendar_version uuid,p_actor uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid:=gen_random_uuid();v_break bigint;v_gross bigint;
 v jsonb;v_cursor timestamptz:=p_start;v_start timestamptz;v_end timestamptz;begin
 if p_kind not in ('attendance','project','service','leave') or p_source is null
  or p_actor is null or p_employee is null or p_calendar_version is null then
  raise exception using errcode='22023',message='WORK_CLAIM_INVALID';end if;
 v_break:=people.work_break_seconds(p_start,p_end,p_breaks);
 v_gross:=extract(epoch from p_end-p_start)::bigint;
 if p_kind='leave' and v_break<>0 then
  raise exception using errcode='22023',message='WORK_CLAIM_INVALID';end if;
 insert into people.work_claims(id,tenant_id,legal_entity_id,branch_id,employee_id,
  source_kind,source_id,start_utc,end_utc,gross_seconds,break_seconds,payable_seconds,
  calendar_version_id,created_by)
 values(v_id,p_t,p_e,p_b,p_employee,p_kind,p_source,p_start,p_end,v_gross,v_break,
  case when p_kind='leave' then 0 else v_gross-v_break end,p_calendar_version,p_actor);
 if p_kind='leave' then
  insert into people.work_claim_segments(tenant_id,legal_entity_id,employee_id,claim_id,start_utc,end_utc)
   values(p_t,p_e,p_employee,v_id,p_start,p_end);
 else
  for v in select value from jsonb_array_elements(p_breaks) loop
   v_start:=(v->>'start_utc')::timestamptz;v_end:=(v->>'end_utc')::timestamptz;
   if v_start>v_cursor then
    insert into people.work_claim_segments(tenant_id,legal_entity_id,employee_id,claim_id,start_utc,end_utc)
     values(p_t,p_e,p_employee,v_id,v_cursor,v_start);end if;
   v_cursor:=v_end;
  end loop;
  if v_cursor<p_end then
   insert into people.work_claim_segments(tenant_id,legal_entity_id,employee_id,claim_id,start_utc,end_utc)
    values(p_t,p_e,p_employee,v_id,v_cursor,p_end);end if;
 end if;
 return v_id;
end $$;

create function people.revoke_work_claim(p_t uuid,p_e uuid,p_employee uuid,p_claim uuid)
returns void language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from people.work_allocations where tenant_id=p_t and legal_entity_id=p_e
  and employee_id=p_employee and claim_id=p_claim and active) then
  raise exception using errcode='55000',message='WORK_ALLOCATION_IMPACT_REQUIRED';end if;
 if exists(select 1 from people.work_input_seals where tenant_id=p_t and legal_entity_id=p_e
  and employee_id=p_employee and claim_id=p_claim) then
  raise exception using errcode='55000',message='PAYROLL_INPUT_SEALED';end if;
 update people.work_claims set active=false,revoked_at=clock_timestamp()
 where tenant_id=p_t and legal_entity_id=p_e and employee_id=p_employee
  and id=p_claim and active;
 if not found then raise exception using errcode='55000',message='WORK_CLAIM_NOT_ACTIVE';end if;
 update people.work_claim_segments set active=false where claim_id=p_claim and active;
end $$;

create function people.allocate_work(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_claim uuid,p_source_kind text,p_source uuid,p_start timestamptz,p_end timestamptz,p_actor uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_claim people.work_claims%rowtype;v_id uuid:=gen_random_uuid();begin
 if p_source_kind not in ('project','service') or p_source is null or p_actor is null
  or p_start is null or p_end is null or p_end<=p_start
  or extract(epoch from p_start)%1<>0 or extract(epoch from p_end)%1<>0 then
  raise exception using errcode='22023',message='WORK_ALLOCATION_INVALID';end if;
 perform id from people.employees where tenant_id=p_t and legal_entity_id=p_e
  and id=p_employee for update;
 select * into v_claim from people.work_claims where tenant_id=p_t and legal_entity_id=p_e
  and branch_id=p_b and employee_id=p_employee and id=p_claim and active for update;
 if v_claim.id is null or v_claim.source_kind='leave'
  or not exists(select 1 from people.work_claim_segments s where s.claim_id=p_claim and s.active
   and tstzrange(s.start_utc,s.end_utc,'[)') @> tstzrange(p_start,p_end,'[)')) then
  raise exception using errcode='55000',message='WORK_ALLOCATION_SOURCE_INVALID';end if;
 insert into people.work_allocations(id,tenant_id,legal_entity_id,branch_id,
  employee_id,claim_id,source_kind,source_id,start_utc,end_utc,created_by)
 values(v_id,p_t,p_e,p_b,p_employee,p_claim,p_source_kind,p_source,p_start,p_end,p_actor);
 return v_id;
end $$;
create function people.revoke_work_allocation(p_t uuid,p_e uuid,p_employee uuid,p_allocation uuid)
returns void language plpgsql security definer set search_path='' as $$begin
 update people.work_allocations set active=false,revoked_at=clock_timestamp()
 where tenant_id=p_t and legal_entity_id=p_e and employee_id=p_employee
  and id=p_allocation and active;
 if not found then raise exception using errcode='55000',message='WORK_ALLOCATION_NOT_ACTIVE';end if;
end $$;

alter table people.attendance_entries add foreign key(tenant_id,legal_entity_id,employee_id,active_claim_id)
 references people.work_claims(tenant_id,legal_entity_id,employee_id,id);

create function people.attendance_payload(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'legal_entity_id',e.legal_entity_id,
  'branch_id',e.branch_id,'employee_id',e.employee_id,'version',e.version,
  'status',e.status,'submitted_by',e.submitted_by,'decided_by',e.decided_by,
  'active_claim_id',e.active_claim_id,'created_by',e.created_by,'created_at',e.created_at,
  'revision',jsonb_build_object('id',r.id,'version',r.version,
   'calendar_version_id',r.calendar_version_id,'start_local',r.start_local,
   'start_offset_seconds',r.start_offset_seconds,'end_local',r.end_local,
   'end_offset_seconds',r.end_offset_seconds,'start_utc',r.start_utc,'end_utc',r.end_utc,
   'breaks',r.breaks,'gross_seconds',r.gross_seconds,'break_seconds',r.break_seconds,
   'payable_seconds',r.payable_seconds,'raw_start_id',r.raw_start_id,'raw_end_id',r.raw_end_id,
   'reason',r.reason,'supersedes_revision_id',r.supersedes_revision_id,
   'recorded_by',r.recorded_by,'recorded_at',r.recorded_at))
 from people.attendance_entries e join people.attendance_revisions r on r.id=e.current_revision_id
 where e.id=p_id
$$;

create function api.people_attendance_entries(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.attendance.view');
 if p_employee_id is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='ATTENDANCE_SCOPE_DENIED';end if;
 select coalesce(jsonb_agg(people.attendance_payload(q.id) order by q.id),'[]'::jsonb)
 into v_items from(select id from people.attendance_entries where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_attendance_detail(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_entry_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_entry people.attendance_entries%rowtype;v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.attendance.view');
 select * into v_entry from people.attendance_entries where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_entry_id;
 if not found then raise exception using errcode='P0002',message='ATTENDANCE_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'version',q.version,
  'start_utc',q.start_utc,'end_utc',q.end_utc,'breaks',q.breaks,
  'payable_seconds',q.payable_seconds,'reason',q.reason,
  'supersedes_revision_id',q.supersedes_revision_id,'recorded_by',q.recorded_by,
  'recorded_at',q.recorded_at) order by q.id),'[]'::jsonb) into v_items
 from(select * from people.attendance_revisions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and entry_id=p_entry_id and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'entry',people.attendance_payload(p_entry_id),
  'history',v_items-50,'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_attendance_raw_events(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.attendance.view');
 if p_employee_id is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='ATTENDANCE_SCOPE_DENIED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'source_system',q.source_system,
  'source_key',q.source_key,'observed_utc',q.observed_utc,'checksum',q.checksum,
  'imported_by',q.imported_by,'imported_at',q.imported_at) order by q.id),'[]'::jsonb)
 into v_items from(select * from people.raw_clock_events where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_work_claims(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.work_claims.view');
 if p_employee_id is null then raise exception using errcode='22023',message='WORK_EMPLOYEE_REQUIRED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'source_kind',q.source_kind,
  'source_id',q.source_id,'start_utc',q.start_utc,'end_utc',q.end_utc,
  'gross_seconds',q.gross_seconds,'break_seconds',q.break_seconds,
  'payable_seconds',q.payable_seconds,'active',q.active,'revoked_at',q.revoked_at,
  'calendar_version_id',q.calendar_version_id) order by q.id),'[]'::jsonb)
 into v_items from(select * from people.work_claims where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_attendance_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_action text:=p_payload->>'action';v_id uuid;
 v_employee_id uuid;v_allowed text[];v_cap text;v_hash text;v_replay jsonb;
 v_entry people.attendance_entries%rowtype;v_rev people.attendance_revisions%rowtype;
 v_calendar people.work_calendar_versions%rowtype;v_reason text;v_before jsonb:='{}'::jsonb;
 v_after jsonb;v_start_local timestamp;v_end_local timestamp;
 v_start timestamptz;v_end timestamptz;v_breaks jsonb;v_break_seconds bigint;
 v_gross bigint;v_new_revision uuid;v_claim uuid;v_raw_start uuid;v_raw_end uuid;
 v_start_date date;v_end_date date;v_request uuid:=gen_random_uuid();begin
 if p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or p_payload is null or jsonb_typeof(p_payload)<>'object'
  or p_expected_version is null or p_expected_version<0
  or p_expected_version>9007199254740991
  or v_action is null or v_action not in ('raw_import','create','correct','submit','approve','reject','cancel')
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'employee_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  raise exception using errcode='22023',message='ATTENDANCE_COMMAND_INVALID';end if;
 v_id:=(p_payload->>'id')::uuid;v_employee_id:=(p_payload->>'employee_id')::uuid;
 v_allowed:=case v_action
  when 'raw_import' then array['action','id','employee_id','source_system','source_key','observed_utc','checksum']
  when 'create' then array['action','id','employee_id','calendar_version_id','start_local',
   'start_offset_seconds','end_local','end_offset_seconds','breaks','raw_start_id','raw_end_id','reason']
  when 'correct' then array['action','id','employee_id','calendar_version_id','start_local',
   'start_offset_seconds','end_local','end_offset_seconds','breaks','raw_start_id','raw_end_id','reason']
  else array['action','id','employee_id','reason'] end;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(v_allowed)) then
  raise exception using errcode='22023',message='ATTENDANCE_FIELDS_INVALID';end if;
 v_cap:=case when v_action='raw_import' then 'people.attendance.import'
  when v_action in ('approve','reject','cancel') then 'people.attendance.approve'
  else 'people.attendance.manage' end;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,v_cap);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='ATTENDANCE_MFA_REQUIRED';end if;
 if not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=v_employee_id) then
  raise exception using errcode='42501',message='ATTENDANCE_SCOPE_DENIED';end if;
 v_hash:=core.wave3_request_hash('people.attendance.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.attendance.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and id=v_employee_id for update;
 if not found then raise exception using errcode='P0002',message='ATTENDANCE_EMPLOYEE_NOT_FOUND';end if;
 if v_action='raw_import' then
  if p_expected_version<>0 or length(btrim(coalesce(p_payload->>'source_system',''))) not between 1 and 80
   or length(btrim(coalesce(p_payload->>'source_key',''))) not between 1 and 160
   or coalesce(p_payload->>'checksum','') !~ '^[a-f0-9]{64}$'
   or coalesce(p_payload->>'observed_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' then
   raise exception using errcode='22023',message='ATTENDANCE_RAW_INVALID';end if;
  insert into people.raw_clock_events(id,tenant_id,legal_entity_id,branch_id,employee_id,
   source_system,source_key,observed_utc,checksum,imported_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
   p_payload->>'source_system',p_payload->>'source_key',(p_payload->>'observed_utc')::timestamptz,
   p_payload->>'checksum',v_actor);
  v_after:=jsonb_build_object('id',v_id,'employee_id',v_employee_id,
   'source_system',p_payload->>'source_system','source_key',p_payload->>'source_key',
   'observed_utc',p_payload->>'observed_utc','checksum',p_payload->>'checksum');
 else
  if v_action<>'create' then
   select * into v_entry from people.attendance_entries where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=v_employee_id
    and id=v_id for update;
   if not found then raise exception using errcode='P0002',message='ATTENDANCE_NOT_FOUND';end if;
   v_before:=people.attendance_payload(v_id);
   perform core.wave3_assert_expected_version(v_entry.version,p_expected_version,v_before);
   select * into v_rev from people.attendance_revisions where id=v_entry.current_revision_id;
  elsif p_expected_version<>0 then
   raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
  v_reason:=btrim(coalesce(p_payload->>'reason',''));
  if length(v_reason) not between 1 and 1000 then
   raise exception using errcode='22023',message='ATTENDANCE_REASON_REQUIRED';end if;
  if v_action in ('create','correct') then
   if v_action='correct' and v_entry.status not in ('draft','rejected','approved') then
    raise exception using errcode='55000',message='ATTENDANCE_STATE_INVALID';end if;
   if coalesce(p_payload->>'start_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
    or coalesce(p_payload->>'end_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
    or coalesce(p_payload->>'calendar_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or coalesce(p_payload->>'start_offset_seconds','') !~ '^-?[0-9]{1,5}$'
    or coalesce(p_payload->>'end_offset_seconds','') !~ '^-?[0-9]{1,5}$' then
    raise exception using errcode='22023',message='ATTENDANCE_BOUNDARY_INVALID';end if;
   select * into v_calendar from people.work_calendar_versions where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and id=(p_payload->>'calendar_version_id')::uuid;
   if not found then raise exception using errcode='P0002',message='ATTENDANCE_CALENDAR_NOT_FOUND';end if;
   v_start_local:=(p_payload->>'start_local')::timestamp;
   v_end_local:=(p_payload->>'end_local')::timestamp;
   v_start:=people.resolve_local_instant(v_calendar.timezone,v_start_local,
    (p_payload->>'start_offset_seconds')::integer);
   v_end:=people.resolve_local_instant(v_calendar.timezone,v_end_local,
    (p_payload->>'end_offset_seconds')::integer);
   perform people.work_local_coverage(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
    v_calendar.id,v_start_local,v_end_local);
   v_breaks:=coalesce(p_payload->'breaks','[]'::jsonb);
   v_break_seconds:=people.work_break_seconds(v_start,v_end,v_breaks);
   v_gross:=extract(epoch from v_end-v_start)::bigint;
   v_raw_start:=nullif(p_payload->>'raw_start_id','')::uuid;
   v_raw_end:=nullif(p_payload->>'raw_end_id','')::uuid;
   if (v_raw_start is null)<>(v_raw_end is null) or
    (v_raw_start is not null and
     (not exists(select 1 from people.raw_clock_events where id=v_raw_start
       and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
       and employee_id=v_employee_id and observed_utc=v_start)
      or not exists(select 1 from people.raw_clock_events where id=v_raw_end
       and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
       and employee_id=v_employee_id and observed_utc=v_end))) then
    raise exception using errcode='22023',message='ATTENDANCE_RAW_PAIR_INVALID';end if;
   if v_action='correct' and v_entry.active_claim_id is not null then
    perform people.revoke_work_claim(p_tenant_id,p_legal_entity_id,v_employee_id,v_entry.active_claim_id);
   end if;
   v_new_revision:=gen_random_uuid();
   if v_action='create' then
    insert into people.attendance_entries(id,tenant_id,legal_entity_id,branch_id,employee_id,
     current_revision_id,status,created_by)
    values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,v_new_revision,'draft',v_actor);
   else
    update people.attendance_entries set version=version+1,current_revision_id=v_new_revision,
     status='draft',submitted_by=null,decided_by=null,active_claim_id=null where id=v_id;
   end if;
   insert into people.attendance_revisions(id,tenant_id,legal_entity_id,branch_id,employee_id,
    entry_id,version,calendar_version_id,start_local,start_offset_seconds,end_local,
    end_offset_seconds,start_utc,end_utc,breaks,gross_seconds,break_seconds,payable_seconds,
    raw_start_id,raw_end_id,reason,supersedes_revision_id,recorded_by)
   values(v_new_revision,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,v_id,
    case when v_action='create' then 1 else v_entry.version+1 end,v_calendar.id,
    v_start_local,(p_payload->>'start_offset_seconds')::integer,
    v_end_local,(p_payload->>'end_offset_seconds')::integer,v_start,v_end,
    v_breaks,v_gross,v_break_seconds,v_gross-v_break_seconds,
    v_raw_start,v_raw_end,v_reason,case when v_action='correct' then v_rev.id end,v_actor);
  elsif v_action='submit' then
   if v_entry.status not in ('draft','rejected') then
    raise exception using errcode='55000',message='ATTENDANCE_STATE_INVALID';end if;
   update people.attendance_entries set version=version+1,status='submitted',
    submitted_by=v_actor,decided_by=null where id=v_id;
  elsif v_action='approve' then
   if v_entry.status<>'submitted' or v_entry.submitted_by=v_actor or v_rev.recorded_by=v_actor then
    raise exception using errcode='55000',message='ATTENDANCE_INDEPENDENT_APPROVAL_REQUIRED';end if;
   perform people.work_local_coverage(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
    v_rev.calendar_version_id,v_rev.start_local,v_rev.end_local);
   v_start_date:=v_rev.start_local::date;
   v_end_date:=greatest((v_rev.end_local-interval '1 microsecond')::date+1,v_start_date+1);
   perform people.consume_organization(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
    'attendance',v_rev.id,v_start_date,v_end_date);
   begin
    v_claim:=people.make_work_claim(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
     'attendance',v_rev.id,v_rev.start_utc,v_rev.end_utc,v_rev.breaks,
     v_rev.calendar_version_id,v_actor);
   exception when exclusion_violation then
    raise exception using errcode='23514',message='WORK_INTERVAL_CONFLICT';
   end;
   update people.attendance_entries set version=version+1,status='approved',
    decided_by=v_actor,active_claim_id=v_claim where id=v_id;
  elsif v_action='reject' then
   if v_entry.status<>'submitted' or v_entry.submitted_by=v_actor or v_rev.recorded_by=v_actor then
    raise exception using errcode='55000',message='ATTENDANCE_INDEPENDENT_APPROVAL_REQUIRED';end if;
   update people.attendance_entries set version=version+1,status='rejected',decided_by=v_actor
    where id=v_id;
  else
   if v_entry.status<>'approved' or v_entry.active_claim_id is null then
    raise exception using errcode='55000',message='ATTENDANCE_STATE_INVALID';end if;
   perform people.revoke_work_claim(p_tenant_id,p_legal_entity_id,v_employee_id,v_entry.active_claim_id);
   update people.attendance_entries set version=version+1,status='cancelled',
    active_claim_id=null,decided_by=v_actor where id=v_id;
  end if;
  select current_revision_id into v_new_revision from people.attendance_entries where id=v_id;
  v_after:=people.attendance_payload(v_id);
  insert into people.attendance_events(tenant_id,legal_entity_id,branch_id,employee_id,
   entry_id,revision_id,action,before_status,after_status,reason,actor_id,command_id)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,v_id,v_new_revision,
   v_action,v_before->>'status',v_after->>'status',v_reason,v_actor,p_command_id);
 end if;
 return core.wave3_finish_command(p_tenant_id,'people.attendance.'||v_action,p_command_id,
  case when v_action='raw_import' then 'people.raw_clock' else 'people.attendance' end,
  v_id,p_idempotency_key,v_hash,v_before,v_after,p_legal_entity_id,p_branch_id,
  p_source_context=>jsonb_build_object('employee_id',v_employee_id,'action',v_action),
  p_request_id=>v_request);
end $$;

revoke all on function people.work_history_guard(),people.work_break_seconds(timestamptz,timestamptz,jsonb),
 people.work_local_coverage(uuid,uuid,uuid,uuid,uuid,timestamp,timestamp),
 people.make_work_claim(uuid,uuid,uuid,uuid,text,uuid,timestamptz,timestamptz,jsonb,uuid,uuid),
 people.revoke_work_claim(uuid,uuid,uuid,uuid),people.attendance_payload(uuid),
 people.allocate_work(uuid,uuid,uuid,uuid,uuid,text,uuid,timestamptz,timestamptz,uuid),
 people.revoke_work_allocation(uuid,uuid,uuid,uuid),
 api.people_attendance_entries(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_raw_events(uuid,uuid,uuid,uuid,uuid),
 api.people_work_claims(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.people_attendance_entries(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_raw_events(uuid,uuid,uuid,uuid,uuid),
 api.people_work_claims(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;
notify pgrst,'reload schema';

-- W4-03B synthetic leave policy, append-only grants/effects and independent decisions.
-- Candidate only; depends on 20260928082234 and reviewed W4-02A prerequisites.
insert into core.permissions(code,module,description,privileged) values
 ('people.leave.view','people','Read scoped leave requests and balance',false),
 ('people.leave.manage','people','Prepare and submit scoped leave requests',true),
 ('people.leave.approve','people','Independently decide and cancel leave',true),
 ('people.leave.policy.manage','people','Publish synthetic leave policy versions',true),
 ('people.leave.adjust','people','Post reasoned synthetic leave grants',true)
on conflict(code) do nothing;

create table people.leave_policies(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
 name text not null check(length(btrim(name)) between 1 and 160),
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,code),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create index leave_policies_creator_idx on people.leave_policies(created_by);

create table people.leave_policy_versions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 policy_id uuid not null,version bigint not null check(version between 1 and 9007199254740991),
 start_date date not null,end_date_exclusive date not null,
 unit text not null check(unit in ('hours','days')),
 day_seconds integer not null check(day_seconds between 1 and 86400),
 accrual_frequency text not null check(accrual_frequency in ('monthly','once')),
 accrual_seconds bigint not null check(accrual_seconds between 1 and 9007199254740991),
 carry_cap_seconds bigint not null check(carry_cap_seconds between 0 and 9007199254740991),
 expiry_days integer not null check(expiry_days between 1 and 3650),
 eligible_types text[] not null check(cardinality(eligible_types) between 1 and 4
  and eligible_types <@ array['permanent','fixed_term','casual','contractor']::text[]),
 allow_unpaid boolean not null default false,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 published_by uuid not null references auth.users(id),published_at timestamptz not null default clock_timestamp(),
 check(end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,policy_id,id),
 unique(tenant_id,legal_entity_id,policy_id,version),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id),
 exclude using gist(policy_id extensions.gist_uuid_ops with =,
  daterange(start_date,end_date_exclusive,'[)') with &&)
);
create index leave_versions_scope_idx on people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id);
create index leave_versions_publisher_idx on people.leave_policy_versions(published_by);

create table people.leave_grants(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 policy_id uuid not null,policy_version_id uuid not null,
 source_kind text not null check(source_kind in ('accrual','adjustment','carry')),
 source_key text not null check(length(btrim(source_key)) between 1 and 160),
 effective_date date not null,expiry_date date not null,
 seconds bigint not null check(seconds between 1 and 9007199254740991),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,source_kind,source_key),
 unique(tenant_id,legal_entity_id,employee_id,id),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,policy_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id),
 check(expiry_date>effective_date)
);
create index leave_grants_balance_idx on people.leave_grants(tenant_id,legal_entity_id,employee_id,policy_id,expiry_date,id);
create index leave_grants_version_idx on people.leave_grants(policy_version_id);
create index leave_grants_actor_idx on people.leave_grants(recorded_by);

create table people.leave_accounts(
 tenant_id uuid not null,legal_entity_id uuid not null,employee_id uuid not null,
 policy_id uuid not null,version bigint not null default 0
  check(version between 0 and 9007199254740991),
 primary key(tenant_id,legal_entity_id,employee_id,policy_id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id)
);
create index leave_accounts_policy_idx on people.leave_accounts(tenant_id,legal_entity_id,policy_id);

create table people.leave_requests(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 policy_id uuid not null,policy_version_id uuid not null,calendar_version_id uuid not null,
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 start_local timestamp not null,start_offset_seconds integer not null,
 end_local timestamp not null,end_offset_seconds integer not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 charge_seconds bigint not null check(charge_seconds between 1 and 129600),
 unpaid_seconds bigint not null default 0 check(unpaid_seconds>=0 and unpaid_seconds<=charge_seconds),
 status text not null check(status in ('draft','submitted','approved','rejected','cancelled')),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 submitted_by uuid references auth.users(id),decided_by uuid references auth.users(id),
 active_claim_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,policy_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,calendar_version_id)
  references people.work_calendar_versions(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,active_claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id),
 check(end_utc>start_utc and end_utc-start_utc<=interval '36 hours')
);
create index leave_requests_scope_idx on people.leave_requests(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index leave_requests_policy_idx on people.leave_requests(policy_version_id);
create index leave_requests_claim_idx on people.leave_requests(active_claim_id);
create index leave_requests_creator_idx on people.leave_requests(created_by);
create index leave_requests_submitter_idx on people.leave_requests(submitted_by);
create index leave_requests_decider_idx on people.leave_requests(decided_by);

create table people.leave_adjustments(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,policy_id uuid not null,
 policy_version_id uuid not null,source_key text not null check(length(btrim(source_key)) between 1 and 160),
 effective_date date not null,seconds bigint not null
  check(seconds<>0 and seconds between -9007199254740991 and 9007199254740991),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,source_key),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,policy_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id)
);
create index leave_adjustments_scope_idx on people.leave_adjustments(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index leave_adjustments_actor_idx on people.leave_adjustments(recorded_by);

create table people.leave_carry_events(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,policy_id uuid not null,
 prior_version_id uuid not null,new_version_id uuid not null,
 boundary_date date not null,source_seconds bigint not null check(source_seconds>=0),
 carried_seconds bigint not null check(carried_seconds>=0 and carried_seconds<=source_seconds),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,boundary_date),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,prior_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,new_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id)
);
create index leave_carry_scope_idx on people.leave_carry_events(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index leave_carry_prior_idx on people.leave_carry_events(prior_version_id);
create index leave_carry_new_idx on people.leave_carry_events(new_version_id);
create index leave_carry_actor_idx on people.leave_carry_events(recorded_by);

create table people.leave_effects(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 employee_id uuid not null,policy_id uuid not null,grant_id uuid not null,
 request_id uuid,adjustment_id uuid,effective_date date not null,
 seconds bigint not null check(seconds<>0 and seconds between -9007199254740991 and 9007199254740991),
 reversal_of uuid unique,recorded_by uuid not null references auth.users(id),
 recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,policy_id,grant_id)
  references people.leave_grants(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,request_id)
  references people.leave_requests(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,policy_id,adjustment_id)
  references people.leave_adjustments(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,reversal_of)
  references people.leave_effects(tenant_id,legal_entity_id,employee_id,id),
 check((request_id is null)<>(adjustment_id is null)),
 check((reversal_of is null and seconds<0) or (reversal_of is not null and seconds>0))
);
create index leave_effects_grant_idx on people.leave_effects(tenant_id,legal_entity_id,employee_id,grant_id);
create index leave_effects_request_idx on people.leave_effects(tenant_id,legal_entity_id,employee_id,request_id);
create index leave_effects_actor_idx on people.leave_effects(recorded_by);

create table people.leave_events(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,request_id uuid not null,
 action text not null check(action in ('create','submit','approve','reject','cancel')),
 before_status text,after_status text not null,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 actor_id uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 command_id uuid not null,unique(tenant_id,legal_entity_id,command_id),
 foreign key(tenant_id,legal_entity_id,employee_id,request_id)
  references people.leave_requests(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index leave_events_request_idx on people.leave_events(tenant_id,legal_entity_id,branch_id,request_id,id);
create index leave_events_actor_idx on people.leave_events(actor_id);

do $$declare v_table regclass;begin
 foreach v_table in array array[
  'people.leave_policies'::regclass,'people.leave_policy_versions'::regclass,
  'people.leave_grants'::regclass,'people.leave_accounts'::regclass,
  'people.leave_requests'::regclass,
  'people.leave_adjustments'::regclass,'people.leave_carry_events'::regclass,
  'people.leave_effects'::regclass,
  'people.leave_events'::regclass] loop
  execute format('alter table %s enable row level security',v_table);
  execute format('alter table %s force row level security',v_table);
  execute format('revoke all on %s from public,anon,authenticated',v_table);
 end loop;
end $$;

create function people.leave_history_guard() returns trigger language plpgsql set search_path='' as $$begin
 raise exception using errcode='55000',message='LEAVE_HISTORY_IMMUTABLE';
end $$;
create trigger leave_version_immutable before update or delete on people.leave_policy_versions
 for each row execute function people.leave_history_guard();
create trigger leave_grant_immutable before update or delete on people.leave_grants
 for each row execute function people.leave_history_guard();
create trigger leave_adjustment_immutable before update or delete on people.leave_adjustments
 for each row execute function people.leave_history_guard();
create trigger leave_carry_immutable before update or delete on people.leave_carry_events
 for each row execute function people.leave_history_guard();
create trigger leave_effect_immutable before update or delete on people.leave_effects
 for each row execute function people.leave_history_guard();
create trigger leave_event_immutable before update or delete on people.leave_events
 for each row execute function people.leave_history_guard();
create function people.leave_effect_insert_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_original people.leave_effects%rowtype;begin
 if new.reversal_of is not null then
  select * into v_original from people.leave_effects where id=new.reversal_of;
  if v_original.id is null or v_original.tenant_id<>new.tenant_id
   or v_original.legal_entity_id<>new.legal_entity_id
   or v_original.employee_id<>new.employee_id or v_original.policy_id<>new.policy_id
   or v_original.grant_id<>new.grant_id or v_original.request_id is distinct from new.request_id
   or v_original.seconds>=0 or v_original.reversal_of is not null
   or new.seconds<>-v_original.seconds then
   raise exception using errcode='23514',message='LEAVE_REVERSAL_MISMATCH';end if;
 end if;
 return new;
end $$;
create trigger leave_effect_exact_reversal before insert on people.leave_effects
 for each row execute function people.leave_effect_insert_guard();

create function people.leave_slot_charge(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_policy_version uuid,p_calendar_version uuid,p_start_local timestamp,p_end_local timestamp,
 p_start_utc timestamptz,p_end_utc timestamptz)
returns bigint language plpgsql stable security definer set search_path='' as $$
declare v_policy people.leave_policy_versions%rowtype;v_calendar people.work_calendar_versions%rowtype;
 v_slot jsonb;v_count integer;v_slot_start timestamp;v_slot_end timestamp;v_day date;
 v_type text;v_charge bigint;begin
 select * into v_policy from people.leave_policy_versions where tenant_id=p_t
  and legal_entity_id=p_e and id=p_policy_version;
 select * into v_calendar from people.work_calendar_versions where tenant_id=p_t
  and legal_entity_id=p_e and id=p_calendar_version;
 if v_policy.id is null or v_calendar.id is null or p_start_local is null or p_end_local is null
  or p_end_local<=p_start_local or p_end_utc<=p_start_utc
  or p_end_utc-p_start_utc>interval '36 hours' then
  raise exception using errcode='22023',message='LEAVE_SLOT_INVALID';end if;
 v_day:=p_start_local::date;
 if not daterange(v_policy.start_date,v_policy.end_date_exclusive,'[)') @>
  daterange(v_day,(p_end_local-interval '1 microsecond')::date+1,'[)') then
  raise exception using errcode='55000',message='LEAVE_POLICY_NOT_EFFECTIVE';end if;
 perform people.work_local_coverage(p_t,p_e,p_b,p_employee,p_calendar_version,p_start_local,p_end_local);
 if exists(select 1 from jsonb_array_elements(v_calendar.date_overrides) o
  where o->>'date'=v_day::text and (o->>'is_working_day')::boolean=false) then
  raise exception using errcode='55000',message='LEAVE_NONWORKING_DAY';end if;
 select count(*),jsonb_agg(value)->0 into v_count,v_slot
 from jsonb_array_elements(v_calendar.weekly_intervals) value
 where (value->>'day_of_week')::integer=extract(isodow from v_day)::integer;
 if v_count<>1 then
  raise exception using errcode='55000',message='LEAVE_SINGLE_WORK_SLOT_REQUIRED';end if;
 v_slot_start:=v_day::timestamp+(v_slot->>'start_minute')::integer*interval '1 minute';
 v_slot_end:=v_day::timestamp+(v_slot->>'end_day_offset')::integer*interval '1 day'
  +(v_slot->>'end_minute')::integer*interval '1 minute';
 if p_start_local<v_slot_start or p_end_local>v_slot_end then
  raise exception using errcode='22023',message='LEAVE_OUTSIDE_WORK_SLOT';end if;
 select a.employment_type into v_type from people.employment_assignments a
 where a.tenant_id=p_t and a.legal_entity_id=p_e and a.branch_id=p_b
  and a.employee_id=p_employee and daterange(a.start_date,a.end_date_exclusive,'[)') @> v_day;
 if v_type is null or not(v_type=any(v_policy.eligible_types)) then
  raise exception using errcode='42501',message='LEAVE_NOT_ELIGIBLE';end if;
 if v_policy.unit='days' then
  if p_start_local<>v_slot_start or p_end_local<>v_slot_end then
   raise exception using errcode='22023',message='LEAVE_FULL_DAY_REQUIRED';end if;
  v_charge:=v_policy.day_seconds;
 else v_charge:=extract(epoch from p_end_utc-p_start_utc)::bigint;end if;
 if v_charge<1 or v_charge>129600 then
  raise exception using errcode='22023',message='LEAVE_CHARGE_INVALID';end if;
 return v_charge;
end $$;

create function people.leave_policy_payload(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'code',p.code,'name',p.name,'version',p.version,
  'versions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'version',v.version,
   'start_date',v.start_date,'end_date_exclusive',v.end_date_exclusive,
   'unit',v.unit,'day_seconds',v.day_seconds,'accrual_frequency',v.accrual_frequency,
   'accrual_seconds',v.accrual_seconds,'carry_cap_seconds',v.carry_cap_seconds,
   'expiry_days',v.expiry_days,'eligible_types',to_jsonb(v.eligible_types),
   'allow_unpaid',v.allow_unpaid,'reason',v.reason,'published_by',v.published_by,
   'published_at',v.published_at) order by v.version)
   from (select * from people.leave_policy_versions
    where policy_id=p.id order by version desc limit 1) v),'[]'::jsonb))
 from people.leave_policies p where p.id=p_id
$$;

create function api.people_leave_policies(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 select coalesce(jsonb_agg(people.leave_policy_payload(q.id) order by q.id),'[]'::jsonb)
 into v_items from(select id from people.leave_policies where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and (p_after is null or id>p_after)
  order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_policy_versions(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_policy_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_policy_id is null or not exists(select 1 from people.leave_policies
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and id=p_policy_id) then
  raise exception using errcode='P0002',message='LEAVE_POLICY_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'version',q.version,
  'start_date',q.start_date,'end_date_exclusive',q.end_date_exclusive,
  'unit',q.unit,'day_seconds',q.day_seconds,'accrual_frequency',q.accrual_frequency,
  'accrual_seconds',q.accrual_seconds,'carry_cap_seconds',q.carry_cap_seconds,
  'expiry_days',q.expiry_days,'eligible_types',to_jsonb(q.eligible_types),
  'allow_unpaid',q.allow_unpaid,'reason',q.reason,'published_by',q.published_by,
  'published_at',q.published_at) order by q.id),'[]'::jsonb) into v_items
 from(select * from people.leave_policy_versions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and policy_id=p_policy_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'policy_id',p_policy_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_policy_for_version(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_version_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_policy uuid;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 select policy_id into v_policy from people.leave_policy_versions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=p_version_id;
 if not found then raise exception using errcode='P0002',message='LEAVE_POLICY_VERSION_NOT_FOUND';end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'policy_version_id',p_version_id,'policy',people.leave_policy_payload(v_policy));
end $$;

create function api.people_leave_policy_command(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_version_id uuid;
 v_policy people.leave_policies%rowtype;v_before jsonb:='{}'::jsonb;v_after jsonb;
 v_hash text;v_replay jsonb;v_start date;v_end date;v_types text[];
 v_request uuid:=gen_random_uuid();begin
 if true=any(array[
  p_command_id is null,p_idempotency_key is null,p_client_timestamp is null,
  coalesce(jsonb_typeof(p_payload),'null')<>'object',
  v_action is null or v_action not in ('create','publish'),
  coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
  coalesce(p_payload->>'version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
  coalesce(p_payload->>'start_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
  coalesce(p_payload->>'end_date_exclusive','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
  coalesce(jsonb_typeof(p_payload->'eligible_types'),'null')<>'array',
  p_expected_version is null]) then
  raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(
  case when v_action='create' then array['action','id','version_id','code','name',
   'start_date','end_date_exclusive','unit','day_seconds','accrual_frequency',
   'accrual_seconds','carry_cap_seconds','expiry_days','eligible_types','allow_unpaid','reason']
  else array['action','id','version_id','start_date','end_date_exclusive','unit',
   'day_seconds','accrual_frequency','accrual_seconds','carry_cap_seconds','expiry_days',
   'eligible_types','allow_unpaid','reason'] end)) then
  raise exception using errcode='22023',message='LEAVE_POLICY_FIELDS_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.policy.manage');
 perform core.require_permission(p_tenant_id,'people.leave.policy.manage',p_legal_entity_id,null);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='LEAVE_MFA_REQUIRED';end if;
 v_id:=(p_payload->>'id')::uuid;v_version_id:=(p_payload->>'version_id')::uuid;
 v_hash:=core.wave3_request_hash('people.leave.policy.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.leave.policy.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 v_start:=(p_payload->>'start_date')::date;v_end:=(p_payload->>'end_date_exclusive')::date;
 if not isfinite(v_start) or not isfinite(v_end) or v_end<=v_start
  or v_end-v_start>1830 or length(btrim(coalesce(p_payload->>'reason',''))) not between 1 and 1000
  or p_payload->>'unit' not in ('hours','days')
  or p_payload->>'accrual_frequency' not in ('monthly','once')
  or coalesce(p_payload->>'day_seconds','') !~ '^[0-9]{1,5}$'
  or coalesce(p_payload->>'accrual_seconds','') !~ '^[0-9]{1,16}$'
  or coalesce(p_payload->>'carry_cap_seconds','') !~ '^[0-9]{1,16}$'
  or coalesce(p_payload->>'expiry_days','') !~ '^[0-9]{1,4}$'
  or jsonb_array_length(p_payload->'eligible_types') not between 1 and 4
  or coalesce(jsonb_typeof(p_payload->'allow_unpaid'),'null')<>'boolean' then
  raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
 select array_agg(x order by x) into v_types
 from jsonb_array_elements_text(p_payload->'eligible_types') x;
 if v_types is null or cardinality(v_types)<>cardinality(array(select distinct unnest(v_types)))
  or not(v_types <@ array['permanent','fixed_term','casual','contractor']::text[])
  or (p_payload->>'day_seconds')::integer not between 1 and 86400
  or (p_payload->>'accrual_seconds')::bigint not between 1 and 9007199254740991
  or (p_payload->>'carry_cap_seconds')::bigint not between 0 and 9007199254740991
  or (p_payload->>'expiry_days')::integer not between 1 and 3650 then
  raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended('people.leave.policy:'||p_tenant_id||':'||p_legal_entity_id,0));
 if v_action='create' then
  if p_expected_version<>0 or coalesce(p_payload->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'
   or length(btrim(coalesce(p_payload->>'name',''))) not between 1 and 160 then
   raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
  insert into people.leave_policies(id,tenant_id,legal_entity_id,code,name,created_by)
   values(v_id,p_tenant_id,p_legal_entity_id,p_payload->>'code',p_payload->>'name',v_actor);
 else
  select * into v_policy from people.leave_policies where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and id=v_id for update;
  if not found then raise exception using errcode='P0002',message='LEAVE_POLICY_NOT_FOUND';end if;
  v_before:=people.leave_policy_payload(v_id);
  perform core.wave3_assert_expected_version(v_policy.version,p_expected_version,v_before);
  update people.leave_policies set version=version+1 where id=v_id;
 end if;
 insert into people.leave_policy_versions(id,tenant_id,legal_entity_id,policy_id,version,
  start_date,end_date_exclusive,unit,day_seconds,accrual_frequency,accrual_seconds,
  carry_cap_seconds,expiry_days,eligible_types,allow_unpaid,reason,published_by)
 values(v_version_id,p_tenant_id,p_legal_entity_id,v_id,
  case when v_action='create' then 1 else v_policy.version+1 end,
  v_start,v_end,p_payload->>'unit',(p_payload->>'day_seconds')::integer,
  p_payload->>'accrual_frequency',(p_payload->>'accrual_seconds')::bigint,
  (p_payload->>'carry_cap_seconds')::bigint,(p_payload->>'expiry_days')::integer,
  v_types,(p_payload->>'allow_unpaid')::boolean,btrim(p_payload->>'reason'),v_actor);
 v_after:=people.leave_policy_payload(v_id);
 return core.wave3_finish_command(p_tenant_id,'people.leave.policy.'||v_action,p_command_id,
  'people.leave.policy',v_id,p_idempotency_key,v_hash,v_before,v_after,
  p_legal_entity_id,p_branch_id,p_request_id=>v_request);
end $$;

create function people.leave_available(p_t uuid,p_e uuid,p_employee uuid,p_policy uuid,
 p_on date,p_recorded_before timestamptz default null)
returns bigint language plpgsql stable security definer set search_path='' as $$
declare v_total numeric;begin
 select coalesce(sum(g.seconds+coalesce((select sum(x.seconds) from people.leave_effects x
   where x.tenant_id=p_t and x.legal_entity_id=p_e and x.employee_id=p_employee
    and x.policy_id=p_policy and x.grant_id=g.id
    and x.effective_date<=p_on and (p_recorded_before is null or x.recorded_at<=p_recorded_before)),0)),0)
 into v_total from people.leave_grants g where g.tenant_id=p_t and g.legal_entity_id=p_e
  and g.employee_id=p_employee and g.policy_id=p_policy
  and g.effective_date<=p_on and g.expiry_date>p_on
  and (p_recorded_before is null or g.recorded_at<=p_recorded_before);
 if v_total<0 or v_total>9007199254740991 then
  raise exception using errcode='23514',message='LEAVE_BALANCE_INVALID';end if;
 return v_total::bigint;
end $$;

create function people.allocate_leave(p_t uuid,p_e uuid,p_employee uuid,p_policy uuid,
 p_request uuid,p_adjustment uuid,p_valid_on date,p_effective date,p_seconds bigint,
 p_actor uuid,p_allow_partial boolean default false)
returns bigint language plpgsql security definer set search_path='' as $$
declare v_grant people.leave_grants%rowtype;v_available numeric;v_take bigint;
 v_remaining bigint:=p_seconds;begin
 if (p_request is null)=(p_adjustment is null) or p_seconds is null or p_seconds<1
  or p_seconds>9007199254740991 or p_actor is null or p_valid_on is null
  or p_effective is null then
  raise exception using errcode='22023',message='LEAVE_ALLOCATION_INVALID';end if;
 -- The caller owns the employee row lock; grant row locks document and reinforce
 -- the same deterministic expiry/effective/ID allocation order.
 for v_grant in select * from people.leave_grants where tenant_id=p_t and legal_entity_id=p_e
  and employee_id=p_employee and policy_id=p_policy and effective_date<=p_valid_on
  and expiry_date>p_valid_on order by expiry_date,effective_date,id for update loop
  select v_grant.seconds+coalesce(sum(x.seconds),0) into v_available
   from people.leave_effects x where x.tenant_id=p_t and x.legal_entity_id=p_e
    and x.employee_id=p_employee and x.policy_id=p_policy and x.grant_id=v_grant.id;
  if v_available<0 or v_available>v_grant.seconds then
   raise exception using errcode='23514',message='LEAVE_GRANT_BALANCE_INVALID';end if;
  if v_available=0 then continue;end if;
  v_take:=least(v_remaining,v_available)::bigint;
  insert into people.leave_effects(tenant_id,legal_entity_id,employee_id,policy_id,grant_id,
   request_id,adjustment_id,effective_date,seconds,recorded_by)
  values(p_t,p_e,p_employee,p_policy,v_grant.id,p_request,p_adjustment,p_effective,-v_take,p_actor);
  v_remaining:=v_remaining-v_take;
  if v_remaining=0 then exit;end if;
 end loop;
 if v_remaining>0 and not p_allow_partial then
  raise exception using errcode='23514',message='LEAVE_BALANCE_INSUFFICIENT';end if;
 return v_remaining;
end $$;

create function api.people_leave_balance(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_policy_id uuid,p_as_of date,
 p_recorded_before timestamptz default null,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_total bigint;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_employee_id is null or p_policy_id is null or p_as_of is null or not isfinite(p_as_of)
  or not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 v_total:=people.leave_available(p_tenant_id,p_legal_entity_id,p_employee_id,p_policy_id,
  p_as_of,p_recorded_before);
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'source_kind',q.source_kind,
  'source_key',q.source_key,'effective_date',q.effective_date,'expiry_date',q.expiry_date,
  'seconds',q.seconds,'remaining_seconds',q.remaining_seconds,
  'policy_version_id',q.policy_version_id,'recorded_at',q.recorded_at) order by q.id),'[]'::jsonb)
 into v_items from(select g.*,
  g.seconds+coalesce((select sum(x.seconds) from people.leave_effects x
   where x.grant_id=g.id and x.effective_date<=p_as_of
    and (p_recorded_before is null or x.recorded_at<=p_recorded_before)),0) remaining_seconds
  from people.leave_grants g where g.tenant_id=p_tenant_id and g.legal_entity_id=p_legal_entity_id
   and g.employee_id=p_employee_id and g.policy_id=p_policy_id
   and (p_after is null or g.id>p_after) and
   (p_recorded_before is null or g.recorded_at<=p_recorded_before)
  order by g.id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'policy_id',p_policy_id,
  'as_of',p_as_of,'recorded_before',p_recorded_before,'available_seconds',v_total,
  'account_version',coalesce((select version from people.leave_accounts where
   tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and employee_id=p_employee_id
   and policy_id=p_policy_id),0),
  'grants',v_items-50,'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_grant_command(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_employee uuid;
 v_policy people.leave_policy_versions%rowtype;v_prior people.leave_policy_versions%rowtype;
 v_account people.leave_accounts%rowtype;
 v_hash text;v_replay jsonb;v_effective date;v_today date;v_type text;
 v_amount bigint;v_source_amount numeric;v_source text;v_before jsonb;v_after jsonb;
 v_request uuid:=gen_random_uuid();begin
 if p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or coalesce(jsonb_typeof(p_payload),'null')<>'object'
  or v_action is null or v_action not in ('accrue','adjust','carry')
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'employee_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'policy_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or p_expected_version is null then
  raise exception using errcode='22023',message='LEAVE_GRANT_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(
  case when v_action='accrue' then array['action','id','employee_id','policy_version_id',
   'period_start','reason']
  when v_action='carry' then array['action','id','employee_id','policy_version_id',
   'prior_version_id','boundary_date','reason']
  else array['action','id','employee_id','policy_version_id',
   'effective_date','source_key','seconds','reason'] end)) then
  raise exception using errcode='22023',message='LEAVE_GRANT_FIELDS_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,
  case when v_action in ('accrue','carry') then 'people.leave.policy.manage'
   else 'people.leave.adjust' end);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='LEAVE_MFA_REQUIRED';end if;
 v_id:=(p_payload->>'id')::uuid;v_employee:=(p_payload->>'employee_id')::uuid;
 select * into v_policy from people.leave_policy_versions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=(p_payload->>'policy_version_id')::uuid;
 if not found then raise exception using errcode='P0002',message='LEAVE_POLICY_NOT_FOUND';end if;
 if not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and employee_id=v_employee) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 v_hash:=core.wave3_request_hash('people.leave.grant.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.leave.grant.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and id=v_employee for update;
 if not found then raise exception using errcode='P0002',message='LEAVE_EMPLOYEE_NOT_FOUND';end if;
 insert into people.leave_accounts(tenant_id,legal_entity_id,employee_id,policy_id)
 values(p_tenant_id,p_legal_entity_id,v_employee,v_policy.policy_id) on conflict do nothing;
 select * into v_account from people.leave_accounts where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and employee_id=v_employee
  and policy_id=v_policy.policy_id for update;
 perform core.wave3_assert_expected_version(v_account.version,p_expected_version,
  jsonb_build_object('account_version',v_account.version));
 select timezone into v_type from core.legal_entities where tenant_id=p_tenant_id
  and id=p_legal_entity_id;
 v_today:=(now() at time zone v_type)::date;
 if v_action='accrue' then
  if coalesce(p_payload->>'period_start','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
   raise exception using errcode='22023',message='LEAVE_ACCRUAL_PERIOD_INVALID';end if;
  v_effective:=(p_payload->>'period_start')::date;
  if (v_policy.accrual_frequency='monthly' and extract(day from v_effective)<>1)
   or (v_policy.accrual_frequency='once' and v_effective<>v_policy.start_date)
   or v_effective>=v_policy.end_date_exclusive
   or v_effective+interval '1 month'<=v_policy.start_date then
   raise exception using errcode='22023',message='LEAVE_ACCRUAL_PERIOD_INVALID';end if;
  v_source:=to_char(v_effective,'YYYY-MM');
  v_effective:=greatest(v_effective,v_policy.start_date);
  v_amount:=v_policy.accrual_seconds;
 elsif v_action='carry' then
  if coalesce(p_payload->>'prior_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'boundary_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
   raise exception using errcode='22023',message='LEAVE_CARRY_INVALID';end if;
  select * into v_prior from people.leave_policy_versions where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and policy_id=v_policy.policy_id
   and id=(p_payload->>'prior_version_id')::uuid;
  v_effective:=(p_payload->>'boundary_date')::date;
  if v_prior.id is null or v_prior.id=v_policy.id
   or v_prior.end_date_exclusive<>v_effective or v_policy.start_date<>v_effective then
   raise exception using errcode='22023',message='LEAVE_CARRY_INVALID';end if;
  v_source:='carry:'||v_prior.id::text||':'||v_effective::text;
  select coalesce(sum(g.seconds+coalesce((select sum(x.seconds) from people.leave_effects x
   where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id
    and x.employee_id=v_employee and x.policy_id=v_policy.policy_id and x.grant_id=g.id),0)),0)
  into v_source_amount from people.leave_grants g where g.tenant_id=p_tenant_id
   and g.legal_entity_id=p_legal_entity_id and g.employee_id=v_employee
   and g.policy_id=v_policy.policy_id and g.policy_version_id=v_prior.id
   and g.expiry_date=v_effective;
  if v_source_amount<0 or v_source_amount>9007199254740991 then
   raise exception using errcode='23514',message='LEAVE_CARRY_BALANCE_INVALID';end if;
  v_amount:=least(v_source_amount,v_policy.carry_cap_seconds)::bigint;
 else
  if coalesce(p_payload->>'effective_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or coalesce(p_payload->>'seconds','') !~ '^-?[0-9]{1,16}$'
   or length(btrim(coalesce(p_payload->>'source_key',''))) not between 1 and 160 then
   raise exception using errcode='22023',message='LEAVE_ADJUSTMENT_INVALID';end if;
  v_effective:=(p_payload->>'effective_date')::date;
  v_amount:=(p_payload->>'seconds')::bigint;
  v_source:=btrim(p_payload->>'source_key');
  if v_amount=0 or abs(v_amount)>9007199254740991 then
   raise exception using errcode='22023',message='LEAVE_ADJUSTMENT_INVALID';end if;
 end if;
 if v_effective<v_policy.start_date or v_effective>=v_policy.end_date_exclusive
  or v_effective>v_today or v_effective+v_policy.expiry_days>date '9999-12-31'
  or length(btrim(coalesce(p_payload->>'reason',''))) not between 1 and 1000 then
  raise exception using errcode='22023',message='LEAVE_GRANT_DATE_INVALID';end if;
 select a.employment_type into v_type from people.employment_assignments a
 where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id
  and a.branch_id=p_branch_id and a.employee_id=v_employee
  and daterange(a.start_date,a.end_date_exclusive,'[)') @> v_effective;
 if v_type is null or not(v_type=any(v_policy.eligible_types)) then
  raise exception using errcode='42501',message='LEAVE_NOT_ELIGIBLE';end if;
 v_before:=jsonb_build_object('account_version',v_account.version,
  'available_seconds',people.leave_available(p_tenant_id,p_legal_entity_id,
   v_employee,v_policy.policy_id,v_today));
 if v_action='adjust' then
  insert into people.leave_adjustments(id,tenant_id,legal_entity_id,branch_id,
   employee_id,policy_id,policy_version_id,source_key,effective_date,seconds,reason,recorded_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,
   v_policy.id,v_source,v_effective,v_amount,btrim(p_payload->>'reason'),v_actor);
 elsif v_action='carry' then
  insert into people.leave_carry_events(id,tenant_id,legal_entity_id,branch_id,
   employee_id,policy_id,prior_version_id,new_version_id,boundary_date,
   source_seconds,carried_seconds,reason,recorded_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,
   v_prior.id,v_policy.id,v_effective,v_source_amount::bigint,v_amount,
   btrim(p_payload->>'reason'),v_actor);
 end if;
 if v_amount>0 then
  insert into people.leave_grants(id,tenant_id,legal_entity_id,branch_id,
   employee_id,policy_id,policy_version_id,source_kind,source_key,
   effective_date,expiry_date,seconds,reason,recorded_by)
  values(case when v_action='accrue' then v_id else gen_random_uuid() end,
   p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,v_policy.id,
   case when v_action='accrue' then 'accrual'
    when v_action='carry' then 'carry' else 'adjustment' end,
   v_source,v_effective,v_effective+v_policy.expiry_days,v_amount,
   btrim(p_payload->>'reason'),v_actor);
 elsif v_amount<0 then
  perform people.allocate_leave(p_tenant_id,p_legal_entity_id,v_employee,v_policy.policy_id,
   null,v_id,v_effective,v_today,-v_amount,v_actor);
 end if;
 update people.leave_accounts set version=version+1 where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and employee_id=v_employee and policy_id=v_policy.policy_id;
 v_after:=jsonb_build_object('id',v_id,'employee_id',v_employee,'policy_id',v_policy.policy_id,
  'policy_version_id',v_policy.id,'source_kind',v_action,'source_key',v_source,
  'effective_date',v_effective,'seconds',v_amount,'account_version',v_account.version+1,
  'available_seconds',people.leave_available(p_tenant_id,p_legal_entity_id,
   v_employee,v_policy.policy_id,v_today));
 return core.wave3_finish_command(p_tenant_id,'people.leave.grant.'||v_action,p_command_id,
  'people.leave.grant',v_id,p_idempotency_key,v_hash,v_before,v_after,
  p_legal_entity_id,p_branch_id,p_request_id=>v_request);
end $$;

create function people.leave_request_summary(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',r.id,'employee_id',r.employee_id,'policy_id',r.policy_id,
  'policy_version_id',r.policy_version_id,'calendar_version_id',r.calendar_version_id,
  'version',r.version,'status',r.status,'start_utc',r.start_utc,'end_utc',r.end_utc,
  'charge_seconds',r.charge_seconds,'unpaid_seconds',r.unpaid_seconds,
  'active_claim_id',r.active_claim_id,'created_by',r.created_by,
  'submitted_by',r.submitted_by,'decided_by',r.decided_by)
 from people.leave_requests r where r.id=p_id
$$;
create function people.leave_request_private(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select people.leave_request_summary(r.id)||jsonb_build_object(
  'tenant_id',r.tenant_id,'legal_entity_id',r.legal_entity_id,'branch_id',r.branch_id,
  'start_local',r.start_local,'start_offset_seconds',r.start_offset_seconds,
  'end_local',r.end_local,'end_offset_seconds',r.end_offset_seconds,
  'reason',r.reason,'created_at',r.created_at)
 from people.leave_requests r where r.id=p_id
$$;
create function api.people_leave_requests(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_employee_id is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and branch_id=p_branch_id and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 select coalesce(jsonb_agg(people.leave_request_private(q.id) order by q.id),'[]'::jsonb)
 into v_items from(select id from people.leave_requests where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;
create function api.people_leave_detail(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_request_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_request people.leave_requests%rowtype;v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 select * into v_request from people.leave_requests where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_request_id;
 if not found then raise exception using errcode='P0002',message='LEAVE_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'action',q.action,
  'before_status',q.before_status,'after_status',q.after_status,
  'reason',q.reason,'actor_id',q.actor_id,'recorded_at',q.recorded_at) order by q.id),'[]'::jsonb)
 into v_items from(select * from people.leave_events where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and request_id=p_request_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'request',people.leave_request_private(p_request_id),
  'history',v_items-50,'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_request_command(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_employee uuid;
 v_request people.leave_requests%rowtype;v_policy people.leave_policy_versions%rowtype;
 v_calendar people.work_calendar_versions%rowtype;v_account people.leave_accounts%rowtype;
 v_start_local timestamp;v_end_local timestamp;v_start timestamptz;v_end timestamptz;
 v_reason text;v_today date;v_timezone text;v_charge bigint;v_unpaid bigint;
 v_claim uuid;v_hash text;v_replay jsonb;v_before jsonb:='{}'::jsonb;v_after jsonb;
 v_request_id uuid:=gen_random_uuid();begin
 if p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or coalesce(jsonb_typeof(p_payload),'null')<>'object'
  or v_action is null or v_action not in ('create','submit','approve','reject','cancel')
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'employee_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or p_expected_version is null then
  raise exception using errcode='22023',message='LEAVE_REQUEST_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(
  case when v_action='create' then array['action','id','employee_id','policy_version_id',
   'calendar_version_id','start_local','start_offset_seconds','end_local',
   'end_offset_seconds','reason']
  when v_action in ('approve','cancel') then array['action','id','employee_id','balance_version','reason']
  else array['action','id','employee_id','reason'] end)) then
  raise exception using errcode='22023',message='LEAVE_REQUEST_FIELDS_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,
  case when v_action in ('approve','reject','cancel') then 'people.leave.approve'
   else 'people.leave.manage' end);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='LEAVE_MFA_REQUIRED';end if;
 v_id:=(p_payload->>'id')::uuid;v_employee:=(p_payload->>'employee_id')::uuid;
 if not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and employee_id=v_employee) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 v_hash:=core.wave3_request_hash('people.leave.request.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.leave.request.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and id=v_employee for update;
 if not found then raise exception using errcode='P0002',message='LEAVE_EMPLOYEE_NOT_FOUND';end if;
 v_reason:=btrim(coalesce(p_payload->>'reason',''));
 if length(v_reason) not between 1 and 1000 then
  raise exception using errcode='22023',message='LEAVE_REASON_REQUIRED';end if;
 select timezone into v_timezone from core.legal_entities where tenant_id=p_tenant_id
  and id=p_legal_entity_id;
 v_today:=(now() at time zone v_timezone)::date;
 if v_action='create' then
  if p_expected_version<>0
   or coalesce(p_payload->>'policy_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'calendar_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'start_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
   or coalesce(p_payload->>'end_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
   or coalesce(p_payload->>'start_offset_seconds','') !~ '^-?[0-9]{1,5}$'
   or coalesce(p_payload->>'end_offset_seconds','') !~ '^-?[0-9]{1,5}$' then
   raise exception using errcode='22023',message='LEAVE_BOUNDARY_INVALID';end if;
  select * into v_policy from people.leave_policy_versions where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and id=(p_payload->>'policy_version_id')::uuid;
  select * into v_calendar from people.work_calendar_versions where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and id=(p_payload->>'calendar_version_id')::uuid;
  if v_policy.id is null or v_calendar.id is null then
   raise exception using errcode='P0002',message='LEAVE_CONFIGURATION_NOT_FOUND';end if;
  v_start_local:=(p_payload->>'start_local')::timestamp;
  v_end_local:=(p_payload->>'end_local')::timestamp;
  v_start:=people.resolve_local_instant(v_calendar.timezone,v_start_local,
   (p_payload->>'start_offset_seconds')::integer);
  v_end:=people.resolve_local_instant(v_calendar.timezone,v_end_local,
   (p_payload->>'end_offset_seconds')::integer);
  v_charge:=people.leave_slot_charge(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
   v_policy.id,v_calendar.id,v_start_local,v_end_local,v_start,v_end);
  insert into people.leave_requests(id,tenant_id,legal_entity_id,branch_id,employee_id,
   policy_id,policy_version_id,calendar_version_id,start_local,start_offset_seconds,
   end_local,end_offset_seconds,start_utc,end_utc,charge_seconds,status,reason,created_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,
   v_policy.id,v_calendar.id,v_start_local,(p_payload->>'start_offset_seconds')::integer,
   v_end_local,(p_payload->>'end_offset_seconds')::integer,v_start,v_end,v_charge,
   'draft',v_reason,v_actor);
 else
  select * into v_request from people.leave_requests where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=v_employee and id=v_id for update;
  if not found then raise exception using errcode='P0002',message='LEAVE_NOT_FOUND';end if;
  v_before:=people.leave_request_summary(v_id);
  perform core.wave3_assert_expected_version(v_request.version,p_expected_version,v_before);
  if v_action='submit' then
   if v_request.status not in ('draft','rejected') then
    raise exception using errcode='55000',message='LEAVE_STATE_INVALID';end if;
   update people.leave_requests set version=version+1,status='submitted',submitted_by=v_actor,
    decided_by=null where id=v_id;
  elsif v_action in ('approve','reject') then
   if v_request.status<>'submitted' or v_request.submitted_by=v_actor
    or v_request.created_by=v_actor then
    raise exception using errcode='55000',message='LEAVE_INDEPENDENT_DECISION_REQUIRED';end if;
   if v_action='reject' then
    update people.leave_requests set version=version+1,status='rejected',decided_by=v_actor
     where id=v_id;
   else
    select * into v_policy from people.leave_policy_versions where id=v_request.policy_version_id;
    v_charge:=people.leave_slot_charge(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
     v_policy.id,v_request.calendar_version_id,v_request.start_local,v_request.end_local,
     v_request.start_utc,v_request.end_utc);
    if v_charge<>v_request.charge_seconds then
     raise exception using errcode='55000',message='LEAVE_INPUT_CHANGED';end if;
    insert into people.leave_accounts(tenant_id,legal_entity_id,employee_id,policy_id)
     values(p_tenant_id,p_legal_entity_id,v_employee,v_request.policy_id) on conflict do nothing;
    select * into v_account from people.leave_accounts where tenant_id=p_tenant_id
     and legal_entity_id=p_legal_entity_id and employee_id=v_employee
     and policy_id=v_request.policy_id for update;
    if coalesce(p_payload->>'balance_version','') !~ '^[0-9]{1,16}$' then
     raise exception using errcode='22023',message='LEAVE_BALANCE_VERSION_REQUIRED';end if;
    perform core.wave3_assert_expected_version(v_account.version,
     (p_payload->>'balance_version')::bigint,jsonb_build_object('account_version',v_account.version));
    perform people.consume_organization(p_tenant_id,p_legal_entity_id,p_branch_id,
     v_employee,'leave',v_id,v_request.start_local::date,
     (v_request.end_local-interval '1 microsecond')::date+1);
    begin
     v_claim:=people.make_work_claim(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
      'leave',v_id,v_request.start_utc,v_request.end_utc,'[]'::jsonb,
      v_request.calendar_version_id,v_actor);
    exception when exclusion_violation then
     raise exception using errcode='23514',message='WORK_INTERVAL_CONFLICT';
    end;
    v_unpaid:=people.allocate_leave(p_tenant_id,p_legal_entity_id,v_employee,
     v_request.policy_id,v_id,null,v_request.start_local::date,v_today,
     v_request.charge_seconds,v_actor,v_policy.allow_unpaid);
    update people.leave_accounts set version=version+1 where tenant_id=p_tenant_id
     and legal_entity_id=p_legal_entity_id and employee_id=v_employee
     and policy_id=v_request.policy_id;
    update people.leave_requests set version=version+1,status='approved',decided_by=v_actor,
     active_claim_id=v_claim,unpaid_seconds=v_unpaid where id=v_id;
   end if;
  else
   if v_request.status<>'approved' or v_request.active_claim_id is null
    or v_request.submitted_by=v_actor or v_request.created_by=v_actor then
    raise exception using errcode='55000',message='LEAVE_CANCELLATION_INVALID';end if;
   if coalesce(p_payload->>'balance_version','') !~ '^[0-9]{1,16}$' then
    raise exception using errcode='22023',message='LEAVE_BALANCE_VERSION_REQUIRED';end if;
   select * into v_account from people.leave_accounts where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and employee_id=v_employee
    and policy_id=v_request.policy_id for update;
   perform core.wave3_assert_expected_version(v_account.version,
    (p_payload->>'balance_version')::bigint,jsonb_build_object('account_version',v_account.version));
   perform people.revoke_work_claim(p_tenant_id,p_legal_entity_id,v_employee,v_request.active_claim_id);
   insert into people.leave_effects(tenant_id,legal_entity_id,employee_id,policy_id,
    grant_id,request_id,effective_date,seconds,reversal_of,recorded_by)
   select x.tenant_id,x.legal_entity_id,x.employee_id,x.policy_id,x.grant_id,x.request_id,
    v_today,-x.seconds,x.id,v_actor from people.leave_effects x
    where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id
     and x.employee_id=v_employee and x.request_id=v_id and x.seconds<0;
   update people.leave_accounts set version=version+1 where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and employee_id=v_employee
    and policy_id=v_request.policy_id;
   update people.leave_requests set version=version+1,status='cancelled',decided_by=v_actor,
    active_claim_id=null where id=v_id;
  end if;
 end if;
 v_after:=people.leave_request_summary(v_id);
 insert into people.leave_events(tenant_id,legal_entity_id,branch_id,employee_id,
  request_id,action,before_status,after_status,reason,actor_id,command_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_id,v_action,
  v_before->>'status',v_after->>'status',v_reason,v_actor,p_command_id);
 return core.wave3_finish_command(p_tenant_id,'people.leave.request.'||v_action,p_command_id,
  'people.leave.request',v_id,p_idempotency_key,v_hash,v_before,v_after,
  p_legal_entity_id,p_branch_id,p_source_context=>jsonb_build_object(
   'employee_id',v_employee,'action',v_action),p_request_id=>v_request_id);
end $$;

create function api.people_workforce_authorize(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_capability text) returns jsonb
language plpgsql stable security definer set search_path='' as $$begin
 if p_capability is null or p_capability not in (
  'people.attendance.view','people.attendance.manage','people.attendance.import',
  'people.attendance.approve','people.work_claims.view','people.leave.view',
  'people.leave.manage','people.leave.approve','people.leave.policy.manage','people.leave.adjust') then
  raise exception using errcode='22023',message='WORKFORCE_CAPABILITY_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_capability);
 if p_employee_id is null and p_capability not in ('people.leave.view','people.leave.policy.manage')
  or p_employee_id is not null and not exists(select 1 from people.employment_assignments
   where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and branch_id=p_branch_id and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='WORKFORCE_SCOPE_DENIED';end if;
 return jsonb_build_object('authorized',true,'actor_id',auth.uid(),
  'employee_id',p_employee_id,'capability',p_capability);
end $$;

-- An expired encrypted draft keeps only its command identity locally. This
-- actor-scoped lookup permits reconciliation without retaining private reasons.
create function api.people_leave_own_receipt(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_receipt core.command_receipts%rowtype;v_action text;v_employee uuid;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_command_id is null then raise exception using errcode='22023',message='LEAVE_COMMAND_REQUIRED';end if;
 select * into v_receipt from core.command_receipts where actor_id=auth.uid()
  and command_id=p_command_id and tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and command_name like 'people.leave.request.%';
 if not found then return null;end if;
 v_action:=substr(v_receipt.command_name,length('people.leave.request.')+1);
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,
  case when v_action in ('approve','reject','cancel') then 'people.leave.approve'
   else 'people.leave.manage' end);
 v_employee:=(v_receipt.response->'entity'->>'employee_id')::uuid;
 if v_employee is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and employee_id=v_employee) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 return v_receipt.response;
end $$;

revoke all on function people.leave_history_guard(),people.leave_effect_insert_guard(),
 people.leave_slot_charge(uuid,uuid,uuid,uuid,uuid,uuid,timestamp,timestamp,timestamptz,timestamptz),
 people.leave_available(uuid,uuid,uuid,uuid,date,timestamptz),
 people.allocate_leave(uuid,uuid,uuid,uuid,uuid,uuid,date,date,bigint,uuid,boolean),
 people.leave_policy_payload(uuid),
 people.leave_request_summary(uuid),people.leave_request_private(uuid),
 api.people_leave_policies(uuid,uuid,uuid,uuid),
 api.people_leave_policy_versions(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_policy_for_version(uuid,uuid,uuid,uuid),
 api.people_leave_balance(uuid,uuid,uuid,uuid,uuid,date,timestamptz,uuid),
 api.people_leave_grant_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_requests(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_request_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_own_receipt(uuid,uuid,uuid,uuid),
 api.people_workforce_authorize(uuid,uuid,uuid,uuid,text),
 api.people_leave_policy_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.people_leave_policies(uuid,uuid,uuid,uuid),
 api.people_leave_policy_versions(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_policy_for_version(uuid,uuid,uuid,uuid),
 api.people_leave_balance(uuid,uuid,uuid,uuid,uuid,date,timestamptz,uuid),
 api.people_leave_grant_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_requests(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_request_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_own_receipt(uuid,uuid,uuid,uuid),
 api.people_workforce_authorize(uuid,uuid,uuid,uuid,text),
 api.people_leave_policy_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;
notify pgrst,'reload schema';

-- Unapplied Wave 3 candidate. In-app notice creation remains in the source
-- command transaction; external delivery workers are never in the posting path.
create table core.wave3_notification_subscriptions (
 id uuid primary key, tenant_id uuid not null, legal_entity_id uuid, branch_id uuid,
 recipient_id uuid not null, event_class text not null check(event_class in
  ('submission','decision','posting','exception','due','allocation','reconciliation','close','reversal')),
 enabled boolean not null, version bigint not null check(version>0),
 created_by uuid not null references auth.users(id), updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,id),
 unique nulls not distinct(tenant_id,legal_entity_id,branch_id,recipient_id,event_class),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,recipient_id) references core.memberships(tenant_id,user_id),
 check(branch_id is null or legal_entity_id is not null)
);
alter table core.wave3_notification_subscriptions enable row level security;
alter table core.wave3_notification_subscriptions force row level security;
revoke all on core.wave3_notification_subscriptions from public,anon,authenticated;
create index wave3_notification_subscriptions_delivery on core.wave3_notification_subscriptions
 (tenant_id,event_class,enabled,legal_entity_id,branch_id,recipient_id);
create index wave3_notification_subscriptions_actor on core.wave3_notification_subscriptions(updated_by);
create index wave3_notification_subscriptions_creator on core.wave3_notification_subscriptions(created_by);
create index wave3_notification_subscriptions_member on core.wave3_notification_subscriptions(tenant_id,recipient_id);
create index wave3_notification_subscriptions_branch on core.wave3_notification_subscriptions(tenant_id,branch_id);
create index wave3_notification_subscriptions_entity on core.wave3_notification_subscriptions(tenant_id,legal_entity_id);
create unique index wave3_notification_command_recipient_class on workflow.notifications
 (tenant_id,command_id,recipient_id,notification_type)
 where command_id is not null and notification_type like 'wave3.%'
  and not (notification_type='wave3.due' and source_context ? 'due_key');

create function api.configure_wave3_notification_subscription(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,
 p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;recipient uuid:=(p_payload->>'recipient_id')::uuid;
 cls text:=p_payload->>'event_class';v_enabled boolean;old_row core.wave3_notification_subscriptions%rowtype;
 new_row core.wave3_notification_subscriptions%rowtype;h text;replay jsonb;before_row jsonb;result jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'core.roles.manage',p_legal_entity_id,p_branch_id);
 if v_id is null or recipient is null or cls is null or cls not in
  ('submission','decision','posting','exception','due','allocation','reconciliation','close','reversal')
  or jsonb_typeof(p_payload->'enabled') is distinct from 'boolean'
  or jsonb_typeof(p_payload) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(p_payload) x where x not in('id','recipient_id','event_class','enabled')) then
  raise exception using errcode='22023',message='NOTIFICATION_SUBSCRIPTION_INVALID';end if;
 v_enabled:=(p_payload->>'enabled')::boolean;
 h:=core.wave3_request_hash('workflow.wave3.notification.configure',p_command_id,p_tenant_id,
  p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 replay:=core.wave3_replay(p_tenant_id,'workflow.wave3.notification.configure',p_command_id,p_idempotency_key,h);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':wave3-notification:'||cls,0));
 if not exists(select 1 from core.memberships where tenant_id=p_tenant_id and user_id=recipient
  and (not v_enabled or status='active')) then
  raise exception using errcode='42501',message='NOTIFICATION_RECIPIENT_UNAVAILABLE';end if;
 select * into old_row from core.wave3_notification_subscriptions
  where tenant_id=p_tenant_id and id=v_id for update;
 if old_row.id is not null and
  (old_row.recipient_id<>recipient or old_row.event_class<>cls
   or old_row.legal_entity_id is distinct from p_legal_entity_id
   or old_row.branch_id is distinct from p_branch_id) then
  raise exception using errcode='22023',message='NOTIFICATION_SUBSCRIPTION_IDENTITY_IMMUTABLE';end if;
 perform core.wave3_assert_expected_version(coalesce(old_row.version,0),p_expected_entity_version,
  case when old_row.id is null then '{}'::jsonb else to_jsonb(old_row) end);
 if v_enabled and (old_row.id is null or not old_row.enabled)
  and (select count(*) from core.wave3_notification_subscriptions
    where tenant_id=p_tenant_id and event_class=cls and enabled)>=100 then
  raise exception using errcode='54000',message='NOTIFICATION_RECIPIENT_LIMIT';end if;
 before_row:=case when old_row.id is null then null else to_jsonb(old_row) end;
 if old_row.id is null then
  insert into core.wave3_notification_subscriptions(id,tenant_id,legal_entity_id,branch_id,
   recipient_id,event_class,enabled,version,created_by,updated_by)
   values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,recipient,cls,v_enabled,1,auth.uid(),auth.uid())
   returning * into new_row;
 else
  update core.wave3_notification_subscriptions set enabled=v_enabled,version=version+1,
   updated_by=auth.uid(),updated_at=clock_timestamp()
   where id=v_id returning * into new_row;
 end if;
 result:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'id',v_id,'recipient_id',recipient,'event_class',cls,
  'enabled',new_row.enabled,'version',new_row.version);
 return core.wave3_finish_command(p_tenant_id,'workflow.wave3.notification.configure',p_command_id,
  'wave3_notification_subscription',v_id,p_idempotency_key,h,before_row,result,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status',case when v_enabled then 'enabled' else 'disabled' end));
end $$;
revoke all on function api.configure_wave3_notification_subscription(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.configure_wave3_notification_subscription(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;

create function core.wave3_notification_classes(topic text) returns text[]
language sql immutable set search_path='' as $$
 select array_remove(array[
  case when topic ~ '(^|[.])(submit|submitted|issue|issued)$' then 'submission' end,
  case when topic ~ '(^|[.])(approve|approved|reject|rejected|decide|decision)$' then 'decision' end,
  case when topic ~ '(^|[.])(post|posted|record|recorded|confirm|confirmed|received|dispatch|dispatched|convert|converted|adjust)$' then 'posting' end,
  case when topic ~ '(^|[.])(exception|variance|shortage|failed|blocked)$' then 'exception' end,
  case when topic ~ '(^|[.])(overdue|due)$' then 'due' end,
  case when topic ~ '(^|[.])(allocate|allocated|reserve|reserved|release|released|maintained)$' then 'allocation' end,
  case when topic ~ '(^|[.])(reconcile|reconciled|match|matched|unmatch|unmatched)$' then 'reconciliation' end,
  case when topic ~ '(^|[.])(close|closed|reopen|reopened|reviewed)$' then 'close' end,
  case when topic ~ '(^|[.])(reverse|reversed|recall|recalled)$' then 'reversal' end
 ],null)::text[]
$$;
revoke all on function core.wave3_notification_classes(text) from public,anon,authenticated;

create function core.wave3_notify_command() returns trigger
language plpgsql security definer set search_path='' as $$
declare cfg jsonb;classes text[]:='{}';cls text;recipient record;v_topic text;event_status text;
 v_kind text;v_permission text;
begin
 if new.command_id is null or new.aggregate_id is null or new.legal_entity_id is null
  or new.command_name like 'people.%' or new.aggregate_type='wave3_notification_subscription' then
  return new;end if;
 v_kind:=case new.aggregate_type when 'request_for_quote' then 'rfq' else new.aggregate_type end;
 cfg:=core.wave3_source_descriptor(v_kind);
 v_permission:=coalesce(cfg->>'permission',case new.aggregate_type
  when 'stock_reservation' then 'inventory.stock.view'
  when 'close_control_review' then 'finance.view'
  when 'fiscal_period_event' then 'finance.view'
  when 'fx_revaluation' then 'finance.view'
  when 'customer_allocation' then 'finance.receipts.view'
  when 'customer_allocation_reversal' then 'finance.receipts.view'
  when 'supplier_allocation' then 'finance.payments.manage'
  when 'supplier_allocation_reversal' then 'finance.payments.manage'
  when 'bank_unmatch' then 'finance.view' end);
 if v_permission is null then
  return new;end if;
 for v_topic in select distinct o.topic from core.outbox_events o
  where o.tenant_id=new.tenant_id and o.command_id=new.command_id loop
  classes:=classes||core.wave3_notification_classes(v_topic);
 end loop;
 for event_status in select distinct to_status from workflow.process_events
  where tenant_id=new.tenant_id and command_id=new.command_id loop
  classes:=classes||core.wave3_notification_classes(coalesce(event_status,''));
 end loop;
 if new.aggregate_type='supplier_bill' and
  (coalesce((new.response#>>'{entity,match,blocked}')::boolean,false)
   or jsonb_array_length(coalesce(new.response#>'{entity,match,exceptions}','[]'))>0) then
  classes:=classes||array['exception'];end if;
 if new.response#>>'{entity,reverse_of}' is not null then
  classes:=classes||array['reversal'];end if;
 for cls in select distinct x from unnest(classes) x loop
  for recipient in
   select distinct s.recipient_id from core.wave3_notification_subscriptions s
   join core.memberships m on m.tenant_id=s.tenant_id and m.user_id=s.recipient_id and m.status='active'
   where s.tenant_id=new.tenant_id and s.event_class=cls and s.enabled
    and (s.legal_entity_id is null or s.legal_entity_id=new.legal_entity_id)
    and (s.branch_id is null or s.branch_id=new.branch_id)
    and exists(
     select 1 from core.role_assignments ra join core.role_permissions rp
      on rp.tenant_id=ra.tenant_id and rp.role_id=ra.role_id
     where ra.tenant_id=new.tenant_id and ra.membership_id=m.id
      and rp.permission_code=v_permission
      and (ra.legal_entity_id is null or ra.legal_entity_id=new.legal_entity_id)
      and (ra.branch_id is null or ra.branch_id=new.branch_id))
    and (cfg is null or not (cfg->>'cost')::boolean or not exists(
     select 1 from unnest(array['inventory.stock.view','inventory.cost.view']) required(permission)
     where not exists(select 1 from core.role_assignments ra join core.role_permissions rp
      on rp.tenant_id=ra.tenant_id and rp.role_id=ra.role_id
      where ra.tenant_id=new.tenant_id and ra.membership_id=m.id
       and rp.permission_code=required.permission
       and (ra.legal_entity_id is null or ra.legal_entity_id=new.legal_entity_id)
       and (ra.branch_id is null or ra.branch_id=new.branch_id))))
  loop
   insert into workflow.notifications(tenant_id,recipient_id,notification_type,title,body,
    aggregate_type,aggregate_id,legal_entity_id,branch_id,actor_id,request_id,command_id,
    correlation_id,source_context,created_by,updated_by)
   values(new.tenant_id,recipient.recipient_id,'wave3.'||cls,'Wave 3 '||initcap(cls),
    'A subscribed business event is ready for review.',
    case when cfg is null then null else v_kind end,
    case when cfg is null then null else new.aggregate_id end,
    new.legal_entity_id,new.branch_id,new.actor_id,new.request_id,new.command_id,
    new.correlation_id,jsonb_build_object('event_class',cls),new.actor_id,new.actor_id)
   on conflict do nothing;
  end loop;
 end loop;
 return new;
end $$;
revoke all on function core.wave3_notify_command() from public,anon,authenticated;
create trigger wave3_notify_command after insert on core.command_receipts
 for each row execute function core.wave3_notify_command();

create index wave3_due_notification_scan on finance.open_items
 (tenant_id,legal_entity_id,branch_id,kind,id) include(due_date,posting_date,source_type,source_id)
 where original_amount>0;
create unique index wave3_due_notification_identity on workflow.notifications
 (tenant_id,recipient_id,notification_type,(source_context->>'due_key'))
 where notification_type='wave3.due' and source_context ? 'due_key';

create function api.scan_wave3_due_notifications(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,
 p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_kind text:=p_payload->>'kind';v_cutoff date:=(p_payload->>'as_of')::date;
 v_after uuid:=(p_payload->>'after_id')::uuid;v_last uuid;v_count int:=0;v_emitted int:=0;
 v_more boolean:=false;v_row finance.open_items%rowtype;v_cfg jsonb;v_recipient record;
 v_residual numeric;v_hash text;v_replay jsonb;v_result jsonb;v_inserted int;
 v_request uuid:=gen_random_uuid();v_due_key text;
begin
 perform core.wave3_require_scope(p_tenant_id,'core.roles.manage',p_legal_entity_id,p_branch_id);
 if jsonb_typeof(p_payload) is distinct from 'object' or v_kind is null or v_kind not in('AR','AP')
  or v_cutoff is null or (p_payload->>'as_of') !~ '^\d{4}-\d{2}-\d{2}$'
  or v_cutoff>(clock_timestamp() at time zone 'UTC')::date
  or p_expected_entity_version is not null
  or exists(select 1 from jsonb_object_keys(p_payload) x where x not in('kind','as_of','after_id')) then
  raise exception using errcode='22023',message='NOTIFICATION_DUE_SCAN_INVALID';end if;
 perform core.wave3_require_scope(p_tenant_id,case v_kind when 'AR' then 'finance.receipts.view'
  else 'finance.payments.manage' end,p_legal_entity_id,p_branch_id);
 v_hash:=core.wave3_request_hash('workflow.wave3.due.scan',p_command_id,p_tenant_id,
  p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_replay:=core.wave3_replay(p_tenant_id,'workflow.wave3.due.scan',p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_legal_entity_id::text||':'||
  p_branch_id::text||':wave3-due:'||v_kind||':'||v_cutoff::text,0));
 for v_row in select o.* from finance.open_items o where o.tenant_id=p_tenant_id
  and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.kind=v_kind
  and o.original_amount>0 and o.posting_date<=v_cutoff and o.due_date<=v_cutoff
  and (v_after is null or o.id>v_after) order by o.id limit 101
 loop
  if v_count=100 then v_more:=true;exit;end if;
  v_count:=v_count+1;v_last:=v_row.id;
  v_residual:=(finance.flow_residual(p_tenant_id,v_row.id,v_cutoff)->>'amount')::numeric;
  if v_residual<=0 then continue;end if;
  v_cfg:=core.wave3_source_descriptor(v_row.source_type);
  if v_cfg is null then raise exception using errcode='55000',message='NOTIFICATION_DUE_SOURCE_UNSUPPORTED';end if;
  perform core.wave3_source_header(p_tenant_id,p_legal_entity_id,p_branch_id,v_row.source_type,v_row.source_id);
  v_due_key:=v_row.id::text||':'||v_cutoff::text;
  for v_recipient in select distinct s.recipient_id from core.wave3_notification_subscriptions s
   join core.memberships m on m.tenant_id=s.tenant_id and m.user_id=s.recipient_id and m.status='active'
   where s.tenant_id=p_tenant_id and s.event_class='due' and s.enabled
    and (s.legal_entity_id is null or s.legal_entity_id=p_legal_entity_id)
    and (s.branch_id is null or s.branch_id=p_branch_id)
    and exists(select 1 from core.role_assignments ra join core.role_permissions rp
     on rp.tenant_id=ra.tenant_id and rp.role_id=ra.role_id
     where ra.tenant_id=p_tenant_id and ra.membership_id=m.id
      and rp.permission_code=v_cfg->>'permission'
      and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id)
      and (ra.branch_id is null or ra.branch_id=p_branch_id))
  loop
   insert into workflow.notifications(tenant_id,recipient_id,notification_type,title,body,
    aggregate_type,aggregate_id,legal_entity_id,branch_id,actor_id,request_id,command_id,
    correlation_id,source_context,created_by,updated_by)
   values(p_tenant_id,v_recipient.recipient_id,'wave3.due','Wave 3 due item',
    'A subscribed business item is due for review.',v_row.source_type,v_row.source_id,
    p_legal_entity_id,p_branch_id,auth.uid(),v_request,p_command_id,v_request,
    jsonb_build_object('event_class','due','as_of',v_cutoff,'due_key',v_due_key),auth.uid(),auth.uid())
   on conflict do nothing;
   get diagnostics v_inserted=row_count;v_emitted:=v_emitted+v_inserted;
  end loop;
 end loop;
 v_result:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'id',p_command_id,'kind',v_kind,'as_of',v_cutoff,
  'examined',v_count,'emitted',v_emitted,'has_more',v_more,
  'next_after',case when v_more then v_last else null end);
 return core.wave3_finish_command(p_tenant_id,'workflow.wave3.due.scan',p_command_id,
  'wave3_due_scan',p_command_id,p_idempotency_key,v_hash,null,v_result,p_legal_entity_id,p_branch_id,
  '{}',jsonb_build_object('to_status','scanned'),'[]','[]',v_request,v_request);
end $$;
revoke all on function api.scan_wave3_due_notifications(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.scan_wave3_due_notifications(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;
create function api.wave3_notification_admin_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_resource text,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'core.roles.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_resource is null or p_resource not in('members','subscriptions') then
  raise exception using errcode='22023',message='NOTIFICATION_ADMIN_PAGE_INVALID';end if;
 if p_resource='members' then
  select coalesce(jsonb_agg(x.row order by x.id),'[]') into rows from(
   select m.user_id id,jsonb_build_object('id',m.user_id,'status',m.status) row
   from core.memberships m where m.tenant_id=p_tenant_id and m.status='active'
    and (p_after is null or m.user_id>p_after) order by m.user_id limit 51)x;
 else
  select coalesce(jsonb_agg(x.row order by x.id),'[]') into rows from(
   select s.id,jsonb_build_object('id',s.id,'recipient_id',s.recipient_id,'event_class',s.event_class,
    'enabled',s.enabled,'version',s.version,'recipient_status',m.status) row
   from core.wave3_notification_subscriptions s join core.memberships m on m.tenant_id=s.tenant_id and m.user_id=s.recipient_id
   where s.tenant_id=p_tenant_id and s.legal_entity_id=p_legal_entity_id and s.branch_id=p_branch_id
    and (p_after is null or s.id>p_after) order by s.id limit 51)x;
 end if;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'resource',p_resource,'items',rows,'next_cursor',cursor);
end $$;
revoke all on function api.wave3_notification_admin_page(uuid,uuid,uuid,text,uuid) from public,anon,authenticated;
grant execute on function api.wave3_notification_admin_page(uuid,uuid,uuid,text,uuid) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive candidate. Receipt attribution is quantity evidence, never
-- original carrying-cost provenance. All amounts are exact six-place decimals.
create table inventory.landed_extensions (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 correction_of uuid,root_id uuid not null,document_date date not null,
 reference text not null,reason text not null,total_amount numeric(20,6) not null check(total_amount>=0),
 amount numeric(20,6) not null check(amount<>0),detail jsonb not null,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),
 created_at timestamptz not null default clock_timestamp(),unique(tenant_id,id),unique(tenant_id,correction_of),
 foreign key(tenant_id,correction_of) references inventory.landed_extensions(tenant_id,id),
 foreign key(tenant_id,root_id) references inventory.landed_extensions(tenant_id,id) deferrable initially deferred,
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(octet_length(detail::text)<=1048576)
);
create table inventory.landed_extension_transit (
 id uuid primary key,tenant_id uuid not null,extension_id uuid not null,
 origin_line_id uuid not null,transfer_id uuid not null,transfer_line_id uuid not null,
 dispatch_entry_id bigint not null references inventory.receipt_provenance_entries(id),
 amount numeric(20,6) not null check(amount<>0),inventory_account_id uuid not null,
 posting_date date not null,branch_id uuid not null,
 foreign key(tenant_id,extension_id) references inventory.landed_extensions(tenant_id,id) deferrable initially deferred,
 foreign key(tenant_id,origin_line_id) references inventory.stock_movement_lines(tenant_id,id),
 foreign key(tenant_id,transfer_id) references inventory.transfers(tenant_id,id),
 foreign key(transfer_line_id) references inventory.transfer_lines(id)
);
create table inventory.landed_extension_settlements (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,transit_id uuid not null,
 operation text not null check(operation in('transfer.receive','transfer.reverse.issue','transfer.reverse.receipt')),
 posting_date date not null,movement_line_id uuid not null,amount numeric(20,6) not null check(amount<>0),
 foreign key(transit_id) references inventory.landed_extension_transit(id),
 foreign key(tenant_id,movement_line_id) references inventory.stock_movement_lines(tenant_id,id),
 unique(transit_id,operation)
);
create index landed_extensions_scope on inventory.landed_extensions(tenant_id,legal_entity_id,branch_id,id);
create index landed_extensions_root on inventory.landed_extensions(tenant_id,root_id);
create index landed_extension_transit_transfer on inventory.landed_extension_transit(tenant_id,transfer_id,transfer_line_id);
create index landed_extension_transit_origin on inventory.landed_extension_transit(tenant_id,origin_line_id);
create index landed_extension_settlement_movement on inventory.landed_extension_settlements(tenant_id,movement_line_id);
do $$declare n text;begin
 foreach n in array array['landed_extensions','landed_extension_transit','landed_extension_settlements'] loop
  execute format('alter table inventory.%I enable row level security',n);
  execute format('alter table inventory.%I force row level security',n);
  execute format('revoke all on inventory.%I from public,anon,authenticated',n);
  execute format('create trigger immutable before update or delete on inventory.%I for each row execute function workflow.reject_history_mutation()',n);
 end loop;
end $$;

-- Called only under existing sorted warehouse/product locks and an open period.
-- A value movement changes pooled carrying value without touching quantities.
create function inventory.landed_extension_stock_value(t uuid,e uuid,b uuid,w uuid,p uuid,origin uuid,
 source uuid,d date,v numeric,req uuid,cmd uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare balance uuid;mid uuid:=gen_random_uuid();lid uuid:=gen_random_uuid();begin
 if v=0 then return null;end if;
 select id into balance from inventory.stock_balances where tenant_id=t and warehouse_id=w and product_id=p for update;
 update inventory.stock_valuations set carrying_value=carrying_value+v,updated_by=auth.uid()
 where tenant_id=t and stock_balance_id=balance and carrying_value+v>=0;
 if not found then raise exception using errcode='55000',message='LANDED_EXTENSION_VALUE_UNAVAILABLE';end if;
 insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,warehouse_id,source_type,source_id,
 posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
 values(mid,t,e,b,w,'landed_extension',mid,d,'value_adjustment',req,cmd,req,auth.uid());
 insert into inventory.stock_movement_lines(id,tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,
 product_id,source_line_id,original_movement_line_id,base_quantity,base_value,posting_date,created_by)
 values(lid,t,e,b,mid,w,p,source,origin,0,v,d,auth.uid());
 return lid;
end $$;
revoke all on function inventory.landed_extension_stock_value(uuid,uuid,uuid,uuid,uuid,uuid,uuid,date,numeric,uuid,uuid) from public,anon,authenticated;

create function inventory.landed_extension_basis(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare prior inventory.landed_extensions%rowtype;ml inventory.stock_movement_lines%rowtype;prod inventory.products%rowtype;
 receipts jsonb:='[]';legs jsonb:='[]';inputs jsonb;item jsonb;trace jsonb;r record;
 locked_transfers uuid[];mode text;currency text;d date:=(p->>'document_date')::date;
 target numeric;delta numeric;weight numeric;weight_total numeric:=0;running numeric:=0;previous numeric:=0;share numeric;
 held numeric;transit numeric;consumed numeric;q numeric;prev numeric;nextv numeric;held_value numeric:=0;transit_value numeric:=0;
 offset_id uuid;variance_id uuid;account_id uuid;result jsonb;root uuid;begin
 perform core.wave3_require_scope(t,'inventory.valuation.post',e,b);
 perform core.wave3_require_scope(t,'inventory.cost.view',e,b);
 if e is null or b is null or d is null or d>(clock_timestamp() at time zone 'UTC')::date
  or jsonb_typeof(p) is distinct from 'object' then raise exception using errcode='22023',message='LANDED_EXTENSION_INPUT_INVALID';end if;
 target:=sales.wave3_decimal_string(p->'total_amount','total_amount',6,true,0,99999999999999.999999);
 if p->>'correction_of' is not null then
  select * into prior from inventory.landed_extensions where tenant_id=t and legal_entity_id=e and branch_id=b and id=(p->>'correction_of')::uuid;
  if not found then raise exception using errcode='22023',message='LANDED_EXTENSION_CORRECTION_INVALID';end if;
  if exists(select 1 from inventory.landed_extensions where tenant_id=t and correction_of=prior.id) then
   raise exception using errcode='40001',message='LANDED_EXTENSION_CORRECTION_CHANGED';end if;
  if d<prior.document_date then raise exception using errcode='22023',message='LANDED_EXTENSION_DATE_INVALID';end if;
  inputs:=prior.detail->'receipts';mode:=prior.detail->>'basis_mode';offset_id:=(prior.detail->>'offset_account_id')::uuid;
  variance_id:=(prior.detail->>'variance_account_id')::uuid;root:=prior.root_id;delta:=target-prior.total_amount;
  if p ? 'receipts' or p ? 'basis_mode' or p ? 'offset_account_id' or p ? 'variance_account_id' then
   raise exception using errcode='22023',message='LANDED_EXTENSION_CORRECTION_BASIS_IMMUTABLE';end if;
 else
  inputs:=p->'receipts';mode:=p->>'basis_mode';offset_id:=(p->>'offset_account_id')::uuid;variance_id:=(p->>'variance_account_id')::uuid;
  delta:=target;root:=(p->>'id')::uuid;
  if mode is null or mode not in('quantity','original_value','manual') then raise exception using errcode='22023',message='LANDED_EXTENSION_BASIS_INVALID';end if;
 end if;
 if delta=0 or jsonb_typeof(inputs) is distinct from 'array' or jsonb_array_length(inputs) not between 1 and 50
  or exists(select 1 from jsonb_array_elements(inputs)x where x->>'receipt_line_id' is null)
  or (select count(*)<>count(distinct x->>'receipt_line_id') from jsonb_array_elements(inputs)x) then
  raise exception using errcode='22023',message='LANDED_EXTENSION_RECEIPTS_INVALID';end if;
 select currency_code into currency from core.legal_entities where tenant_id=t and id=e;
 perform finance.flow_account(t,e,offset_id,'expense',currency);
 perform finance.flow_account(t,e,variance_id,'expense',currency);
 if (select count(*) from core.warehouses where tenant_id=t and legal_entity_id=e)>500 then raise exception using errcode='54000',message='LANDED_EXTENSION_WAREHOUSE_LIMIT';end if;
 -- Transfer command locks transfer identity, then period, then warehouse/product.
 -- Acquire every known transfer identity first. A newly discovered dispatch after
 -- these keys were enumerated fails rather than acquiring an inverted lock.
 select coalesce(array_agg(distinct m.source_id order by m.source_id),'{}') into locked_transfers
 from inventory.receipt_provenance_entries pe join inventory.stock_movement_lines x on x.id=pe.movement_line_id
 join inventory.stock_movements m on m.id=x.stock_movement_id
 where pe.tenant_id=t and pe.origin_line_id in(select (x->>'receipt_line_id')::uuid from jsonb_array_elements(inputs)x)
 and m.source_type like 'transfer.%';
 if cardinality(locked_transfers)>500 then raise exception using errcode='54000',message='LANDED_EXTENSION_TRANSFER_LIMIT';end if;
 for r in select unnest(locked_transfers) id order by id loop
  perform pg_advisory_xact_lock(hashtextextended('inventory.transfer:'||r.id::text,0));
 end loop;
 perform finance.wave3_lock_open_period(t,e,d);
 for r in select distinct w.id warehouse_id,x.product_id from core.warehouses w cross join inventory.stock_movement_lines x
 where w.tenant_id=t and w.legal_entity_id=e and x.tenant_id=t and x.legal_entity_id=e
 and x.id in(select (i->>'receipt_line_id')::uuid from jsonb_array_elements(inputs)i) order by w.id,x.product_id loop
  perform pg_advisory_xact_lock(hashtextextended(t::text||':'||r.warehouse_id::text||':'||r.product_id::text,0));
 end loop;
 if exists(select 1 from inventory.receipt_provenance_entries pe join inventory.stock_movement_lines x on x.id=pe.movement_line_id
 join inventory.stock_movements m on m.id=x.stock_movement_id where pe.tenant_id=t
 and pe.origin_line_id in(select (x->>'receipt_line_id')::uuid from jsonb_array_elements(inputs)x)
 and m.source_type like 'transfer.%' and not(m.source_id=any(locked_transfers))) then
  raise exception using errcode='40001',message='LANDED_EXTENSION_PREVIEW_CHANGED';end if;
 for item in select value from jsonb_array_elements(inputs) order by value->>'receipt_line_id' loop
  select x.* into ml from inventory.stock_movement_lines x join inventory.stock_movements m on m.id=x.stock_movement_id
   join procurement.goods_receipts gr on gr.stock_movement_id=m.id
   where x.tenant_id=t and x.legal_entity_id=e and x.branch_id=b and x.id=(item->>'receipt_line_id')::uuid
   and m.source_type='goods_receipt' and x.base_quantity>0
   and not exists(select 1 from procurement.goods_receipt_reversals rr where rr.receipt_id=gr.id);
  if not found then raise exception using errcode='22023',message='LANDED_EXTENSION_RECEIPT_INVALID',detail=item->>'receipt_line_id';end if;
  if d<ml.posting_date then raise exception using errcode='22023',message='LANDED_EXTENSION_DATE_INVALID',detail=ml.id::text;end if;
  select * into prod from inventory.products where tenant_id=t and legal_entity_id=e and id=ml.product_id;
  if prior.id is null and prod.status<>'active' then raise exception using errcode='22023',message='LANDED_EXTENSION_PRODUCT_INACTIVE',detail=ml.id::text;end if;
  account_id:=case when prior.id is not null then (item->>'inventory_account_id')::uuid else prod.inventory_account_id end;
  perform finance.flow_account(t,e,account_id,'asset',currency);
  weight:=case when prior.id is not null then (item->>'weight')::numeric when mode='quantity' then ml.base_quantity when mode='original_value' then ml.base_value
   else sales.wave3_decimal_string(item->'weight','weight',6,true,0.000001,99999999999999.999999) end;
  if weight is null or weight<=0 then raise exception using errcode='22023',message='LANDED_EXTENSION_WEIGHT_INVALID',detail=ml.id::text;end if;
  trace:=api.receipt_trace_detail(t,e,b,ml.id);
  held:=(trace->>'held_quantity')::numeric;transit:=(trace->>'in_transit_quantity')::numeric;consumed:=ml.base_quantity-held-transit;
  if trace->>'covered'<>'true' or held is null or held<0 or transit<0 or consumed<0
   or (prior.id is null and held+transit<=0) then
   raise exception using errcode='22023',message='LANDED_EXTENSION_CONSUMED_OR_UNCOVERED',detail=ml.id::text;end if;
  if (select count(*) from inventory.receipt_provenance_entries where tenant_id=t and origin_line_id=ml.id)>10000 then
   raise exception using errcode='54000',message='LANDED_EXTENSION_PROVENANCE_LIMIT',detail=ml.id::text;end if;
  if exists(select 1 from inventory.stock_movement_lines where tenant_id=t and product_id=ml.product_id and posting_date>d) then
   raise exception using errcode='55000',message='LANDED_EXTENSION_BACKDATED_REVIEW',detail=ml.id::text;end if;
  weight_total:=weight_total+weight;
  receipts:=receipts||jsonb_build_array(jsonb_build_object('receipt_line_id',ml.id,'product_id',ml.product_id,'weight',weight::text,
   'inventory_account_id',account_id,'received_quantity',ml.base_quantity::text,'original_value',ml.base_value::text,
   'held_quantity',held::text,'transit_quantity',transit::text,'consumed_quantity',consumed::text,
   'previous_allocation',coalesce(item->>'target_allocation','0'),
   'provenance_version',(select coalesce(max(id),0)::text from inventory.receipt_provenance_entries where tenant_id=t and origin_line_id=ml.id)));
 end loop;
 inputs:=receipts;receipts:='[]';
 for item in select value from jsonb_array_elements(inputs) order by value->>'receipt_line_id' loop
  running:=running+(item->>'weight')::numeric;
  nextv:=round(target*running/weight_total,6);share:=nextv-previous-(item->>'previous_allocation')::numeric;
  item:=item||jsonb_build_object('target_allocation',(nextv-previous)::text,'incremental_amount',share::text);previous:=nextv;
  receipts:=receipts||jsonb_build_array(item);q:=0;prev:=0;
  for r in select pos.warehouse_id,w.branch_id,sum(pos.quantity) quantity,sb.version balance_version,sv.id valuation_id,sv.version valuation_version,sv.carrying_value
   from inventory.receipt_provenance_positions pos join core.warehouses w on w.id=pos.warehouse_id
   left join inventory.stock_balances sb on sb.tenant_id=t and sb.warehouse_id=pos.warehouse_id and sb.product_id=pos.product_id
   left join inventory.stock_valuations sv on sv.tenant_id=t and sv.stock_balance_id=sb.id
   where pos.tenant_id=t and pos.origin_line_id=(item->>'receipt_line_id')::uuid and pos.quantity>0
   group by pos.warehouse_id,w.branch_id,sb.version,sv.id,sv.version,sv.carrying_value order by pos.warehouse_id loop
   if r.valuation_id is null then raise exception using errcode='55000',message='LANDED_EXTENSION_PROJECTION_REQUIRED';end if;
   perform core.wave3_require_scope(t,'inventory.valuation.post',e,r.branch_id);perform core.wave3_require_scope(t,'inventory.cost.view',e,r.branch_id);
   q:=q+r.quantity;nextv:=round(share*q/(item->>'received_quantity')::numeric,6);
   legs:=legs||jsonb_build_array(item||jsonb_build_object('kind','held','warehouse_id',r.warehouse_id,'branch_id',r.branch_id,'quantity',r.quantity::text,
    'value',(nextv-prev)::text,'valuation_id',r.valuation_id,'valuation_version',r.valuation_version::text,'balance_version',r.balance_version::text,'carrying_value',r.carrying_value::text));
   held_value:=held_value+nextv-prev;prev:=nextv;
  end loop;
  if q<>(item->>'held_quantity')::numeric then raise exception using errcode='55000',message='LANDED_EXTENSION_PROJECTION_REQUIRED';end if;
  for r in select pe.id,sm.source_id transfer_id,x.source_line_id transfer_line_id,tr.branch_id,tr.destination_branch_id,tr.version transfer_version,
    -pe.quantity-coalesce((select sum(rest.quantity) from inventory.receipt_provenance_entries rest where rest.restores_entry_id=pe.id),0) quantity
   from inventory.receipt_provenance_entries pe join inventory.stock_movement_lines x on x.id=pe.movement_line_id
   join inventory.stock_movements sm on sm.id=x.stock_movement_id join inventory.transfers tr on tr.tenant_id=t and tr.id=sm.source_id
   where pe.tenant_id=t and pe.origin_line_id=(item->>'receipt_line_id')::uuid and pe.quantity<0 and sm.source_type in('transfer.dispatch','transfer.reverse.issue')
   order by pe.id loop
   if r.quantity=0 then continue;end if;
   if r.quantity<0 or not exists(select 1 from inventory.transfers where tenant_id=t and id=r.transfer_id and status='in_transit') then
    raise exception using errcode='55000',message='LANDED_EXTENSION_TRANSIT_BASIS_REQUIRED';end if;
   perform core.wave3_require_scope(t,'inventory.valuation.post',e,r.branch_id);perform core.wave3_require_scope(t,'inventory.cost.view',e,r.branch_id);
   perform core.wave3_require_scope(t,'inventory.valuation.post',e,r.destination_branch_id);perform core.wave3_require_scope(t,'inventory.cost.view',e,r.destination_branch_id);
   q:=q+r.quantity;nextv:=round(share*q/(item->>'received_quantity')::numeric,6);
   legs:=legs||jsonb_build_array(item||jsonb_build_object('kind','transit','transfer_id',r.transfer_id,'transfer_line_id',r.transfer_line_id,
    'dispatch_entry_id',r.id::text,'branch_id',r.branch_id,'destination_branch_id',r.destination_branch_id,'transfer_version',r.transfer_version::text,'quantity',r.quantity::text,'value',(nextv-prev)::text));
   transit_value:=transit_value+nextv-prev;prev:=nextv;
  end loop;
  if q<>(item->>'held_quantity')::numeric+(item->>'transit_quantity')::numeric then raise exception using errcode='55000',message='LANDED_EXTENSION_TRANSIT_BASIS_REQUIRED';end if;
  legs:=legs||jsonb_build_array(item||jsonb_build_object('kind','consumed','branch_id',b,'quantity',item->>'consumed_quantity','value',(share-prev)::text));
 end loop;
 if jsonb_array_length(legs)>1000 then raise exception using errcode='54000',message='LANDED_EXTENSION_LEG_LIMIT';end if;
 result:=jsonb_build_object('tenant_id',t,'legal_entity_id',e,'branch_id',b,'root_id',root,'correction_of',prior.id,'document_date',d,'currency_code',currency,'basis_mode',mode,
  'offset_account_id',offset_id,'variance_account_id',variance_id,'total_amount',target::text,'amount',delta::text,
  'inventory_amount',held_value::text,'transit_amount',transit_value::text,'variance_amount',(delta-held_value-transit_value)::text,
  'receipts',receipts,'legs',legs,'attribution_rule','Recorded receipt quantities; original receipt value is an allocation weight, not carrying-cost provenance.');
 if octet_length(result::text)>1048576 then raise exception using errcode='54000',message='LANDED_EXTENSION_EVIDENCE_LIMIT';end if;
 return result||jsonb_build_object('basis_hash',md5(result::text));
end $$;
revoke all on function inventory.landed_extension_basis(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function api.preview_landed_extension(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_payload jsonb) returns jsonb
language sql security definer set search_path='' as $$select inventory.landed_extension_basis(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload)$$;

create function api.post_landed_extension(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;parent uuid:=(p_payload->>'correction_of')::uuid;basis jsonb;h text;result jsonb;leg jsonb;
 req uuid:=gen_random_uuid();lid uuid;jid uuid;journals jsonb:='[]';v numeric;doc jsonb;account uuid;reason text:=btrim(p_payload->>'reason');reference text:=btrim(p_payload->>'reference');begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if v_id is null or p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or coalesce(length(reason),0) not between 3 and 1000 or coalesce(length(reference),0) not between 1 and 140 then
  raise exception using errcode='22023',message='LANDED_EXTENSION_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.landed.extension',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.landed.extension',p_command_id,p_idempotency_key,h);
 if result is not null then
  for leg in select value from jsonb_array_elements(result#>'{entity,legs}') loop
   perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(leg->>'branch_id')::uuid);
   perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(leg->>'branch_id')::uuid);
   if leg->>'destination_branch_id' is not null then
    perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(leg->>'destination_branch_id')::uuid);
    perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(leg->>'destination_branch_id')::uuid);
   end if;
  end loop;return result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('landed.extension:'||coalesce(parent,v_id)::text,0));
 perform core.wave3_assert_expected_version(case when parent is null then 0 else 1 end,p_expected_entity_version,'{}');
 basis:=inventory.landed_extension_basis(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 if basis->>'basis_hash' is distinct from p_payload->>'basis_hash' then raise exception using errcode='40001',message='LANDED_EXTENSION_PREVIEW_CHANGED';end if;
 doc:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'document_date',basis->>'document_date',
  'currency_code',basis->>'currency_code','base_currency_code',basis->>'currency_code','exchange_rate','1');
 for leg in select value from jsonb_array_elements(basis->'legs') loop
  v:=(leg->>'value')::numeric;if v=0 then continue;end if;
  account:=case when leg->>'kind'='consumed' then (basis->>'variance_account_id')::uuid else (leg->>'inventory_account_id')::uuid end;
  if leg->>'kind'='held' then
   lid:=inventory.landed_extension_stock_value(p_tenant_id,p_legal_entity_id,(leg->>'branch_id')::uuid,(leg->>'warehouse_id')::uuid,
    (leg->>'product_id')::uuid,(leg->>'receipt_line_id')::uuid,v_id,(basis->>'document_date')::date,v,req,p_command_id);
  elsif leg->>'kind'='transit' then
   if v<0 and (select l.carrying_value+coalesce((select sum(s.amount) from inventory.landed_extension_transit s where s.tenant_id=p_tenant_id and s.transfer_line_id=l.id
    and not exists(select 1 from inventory.landed_extension_settlements z where z.transit_id=s.id)),0)+v from inventory.transfer_lines l where l.id=(leg->>'transfer_line_id')::uuid)<0 then
    raise exception using errcode='55000',message='LANDED_EXTENSION_TRANSIT_VALUE_UNAVAILABLE';end if;
   insert into inventory.landed_extension_transit(id,tenant_id,extension_id,origin_line_id,transfer_id,transfer_line_id,dispatch_entry_id,amount,inventory_account_id,posting_date,branch_id)
   values(gen_random_uuid(),p_tenant_id,v_id,(leg->>'receipt_line_id')::uuid,(leg->>'transfer_id')::uuid,(leg->>'transfer_line_id')::uuid,
    (leg->>'dispatch_entry_id')::bigint,v,account,(basis->>'document_date')::date,(leg->>'branch_id')::uuid);
  end if;
  jid:=finance.flow_post_journal(doc||jsonb_build_object('branch_id',leg->>'branch_id'),jsonb_build_array(
   finance.flow_jline(account,v,v,v_id),finance.flow_jline((basis->>'offset_account_id')::uuid,-v,-v,v_id)),
   'landed_extension',gen_random_uuid(),req,p_command_id);journals:=journals||jsonb_build_array(jid);
 end loop;
 result:=basis||jsonb_build_object('id',v_id,'version',1,'status','posted','reference',reference,'reason',reason,'journal_ids',journals);
 insert into inventory.landed_extensions(id,tenant_id,legal_entity_id,branch_id,correction_of,root_id,document_date,reference,reason,total_amount,amount,detail,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,parent,(basis->>'root_id')::uuid,(basis->>'document_date')::date,reference,reason,
  (basis->>'total_amount')::numeric,(basis->>'amount')::numeric,result,req,p_command_id,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'inventory.landed.extension',p_command_id,'landed_extension',v_id,p_idempotency_key,h,null,result,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','posted','operation',case when parent is null then 'post' else 'correct' end,'reason',reason),
  jsonb_build_array(jsonb_build_object('topic','inventory.landed.extension','payload',jsonb_build_object('id',v_id))),'[]',req,req);
end $$;

-- Delegate transfer quantity/original cost to the established primitive. Separate
-- value-only settlement movements preserve the dispatch line and trace identities.
alter function inventory.transfer_leg(uuid,uuid,uuid,uuid,uuid,inventory.transfer_lines,date,numeric,numeric,text,uuid,uuid) rename to landed_extension_original_transfer_leg;
create function inventory.transfer_leg(p_tenant uuid,p_entity uuid,p_branch uuid,p_warehouse uuid,p_transfer uuid,p_line inventory.transfer_lines,
 p_date date,p_quantity numeric,p_value numeric,p_operation text,p_request uuid,p_command uuid) returns void
language plpgsql security definer set search_path='' as $$declare r record;lid uuid;v numeric;begin
 if p_operation='transfer.reverse.issue' and exists(select 1 from inventory.landed_extensions a,jsonb_array_elements(a.detail->'legs') leg
  where a.tenant_id=p_tenant and leg->>'kind'='held' and leg->>'warehouse_id'=p_warehouse::text and leg->>'product_id'=p_line.product_id::text
  and (leg->>'value')::numeric<>0 and a.created_at>(select min(created_at) from inventory.transfer_events where tenant_id=p_tenant and transfer_id=p_transfer and operation in('receive','immediate'))) then
  raise exception using errcode='55000',message='LANDED_EXTENSION_TRANSFER_CORRECTION_REVIEW';end if;
 if p_operation='transfer.reverse.issue' then
  for r in select s.*,a.command_id,a.request_id from inventory.landed_extension_transit s join inventory.landed_extensions a on a.id=s.extension_id
   where s.tenant_id=p_tenant and s.transfer_line_id=p_line.id and exists(select 1 from inventory.landed_extension_settlements z where z.transit_id=s.id and z.operation='transfer.receive') order by s.id loop
   if p_date<r.posting_date then raise exception using errcode='55000',message='LANDED_EXTENSION_BACKDATED_REVIEW';end if;
   lid:=inventory.landed_extension_stock_value(p_tenant,p_entity,p_branch,p_warehouse,p_line.product_id,r.origin_line_id,r.extension_id,p_date,-r.amount,p_request,p_command);
   insert into inventory.landed_extension_settlements(tenant_id,transit_id,operation,posting_date,movement_line_id,amount)
   values(p_tenant,r.id,p_operation,p_date,lid,-r.amount);
  end loop;
 end if;
 perform inventory.landed_extension_original_transfer_leg(p_tenant,p_entity,p_branch,p_warehouse,p_transfer,p_line,p_date,p_quantity,p_value,p_operation,p_request,p_command);
 if p_operation in('transfer.receive','transfer.reverse.receipt') then
  for r in select s.* from inventory.landed_extension_transit s where s.tenant_id=p_tenant and s.transfer_line_id=p_line.id
   and (not exists(select 1 from inventory.landed_extension_settlements z where z.transit_id=s.id)
    or (p_operation='transfer.reverse.receipt' and exists(select 1 from inventory.landed_extension_settlements z where z.transit_id=s.id and z.operation='transfer.reverse.issue')))
   order by s.id loop
   if p_date<r.posting_date then raise exception using errcode='55000',message='LANDED_EXTENSION_BACKDATED_REVIEW';end if;
   lid:=inventory.landed_extension_stock_value(p_tenant,p_entity,p_branch,p_warehouse,p_line.product_id,r.origin_line_id,r.extension_id,p_date,r.amount,p_request,p_command);
   insert into inventory.landed_extension_settlements(tenant_id,transit_id,operation,posting_date,movement_line_id,amount)
   values(p_tenant,r.id,p_operation,p_date,lid,r.amount);
  end loop;
 end if;
end $$;
revoke all on function inventory.transfer_leg(uuid,uuid,uuid,uuid,uuid,inventory.transfer_lines,date,numeric,numeric,text,uuid,uuid) from public,anon,authenticated;

-- Original-cost receipt reversal must not strand an incremental charge. A chain
-- reduced to zero may proceed through the existing independent stock guards.
create function inventory.guard_landed_extension_receipt() returns trigger language plpgsql security definer set search_path='' as $$
declare m inventory.stock_movements%rowtype;begin
 select * into m from inventory.stock_movements where id=new.stock_movement_id;
 if m.source_type='goods_receipt_reversal' and exists(select 1 from inventory.landed_extensions a,jsonb_array_elements(a.detail->'receipts') r
  where a.tenant_id=new.tenant_id and r->>'receipt_line_id'=new.original_movement_line_id::text and (r->>'target_allocation')::numeric<>0
  and not exists(select 1 from inventory.landed_extensions c where c.tenant_id=a.tenant_id and c.correction_of=a.id)) then
  raise exception using errcode='55000',message='LANDED_EXTENSION_CORRECT_FIRST';end if;
 return new;
end $$;
revoke all on function inventory.guard_landed_extension_receipt() from public,anon,authenticated;
create trigger guard_landed_extension_receipt before insert on inventory.stock_movement_lines for each row execute function inventory.guard_landed_extension_receipt();

-- Dated reports include immutable supplements until their first settlement. The
-- same wrapper is used by close controls; no saved historical report is changed.
alter function inventory.build_valuation_report(uuid,uuid,uuid,jsonb) rename to landed_extension_original_valuation_report;
create function inventory.build_valuation_report(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;extra jsonb;movements jsonb;diffs jsonb;transit jsonb;held numeric;tv numeric;gv numeric;d date:=(p->>'as_of')::date;begin
 result:=inventory.landed_extension_original_valuation_report(t,e,b,p);
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'evidence_key','command:'||a.command_id,'extension_id',a.id,'transfer_id',s.transfer_id,
  'transfer_line_id',s.transfer_line_id,'receipt_line_id',s.origin_line_id,'quantity','0','value',s.amount::text,'posting_date',s.posting_date,
  'kind','landed_extension_transit') order by s.id),'[]') into extra
 from inventory.landed_extension_transit s join inventory.landed_extensions a on a.id=s.extension_id
 where s.tenant_id=t and a.legal_entity_id=e and s.posting_date<=d
 and not exists(select 1 from inventory.landed_extension_settlements z where z.transit_id=s.id and z.posting_date<=d);
 transit:=(result->'transit')||extra;
 -- Settlement movements are real ledger evidence of an already posted charge;
 -- attribute them to that charge while preserving the actual transfer command.
 select coalesce(jsonb_agg(case when s.id is null then x else x||jsonb_build_object('transfer_command_id',x->>'command_id',
  'evidence_key','command:'||a.command_id,'landed_extension_id',a.id) end order by x->>'id'),'[]') into movements
 from jsonb_array_elements(result->'movements')x left join inventory.landed_extension_settlements z on z.tenant_id=t and z.movement_line_id=(x->>'id')::uuid
 left join inventory.landed_extension_transit s on s.id=z.transit_id left join inventory.landed_extensions a on a.id=s.extension_id;
 if greatest(jsonb_array_length(transit),jsonb_array_length(movements))>10000 then raise exception using errcode='54000',message='VALUATION_INPUT_LIMIT';end if;
 with entries as(select x->>'evidence_key' k,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(movements)x
  union all select x->>'evidence_key',(x->>'value')::numeric,0 from jsonb_array_elements(transit)x
  union all select x->>'evidence_key',0,(x->>'value')::numeric from jsonb_array_elements(result->'journals')x),totals as(select k,sum(v)v,sum(g)g from entries group by k)
 select coalesce(jsonb_agg(jsonb_build_object('id',k,'evidence_key',k,'inventory_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by k),'[]') into diffs from totals where v<>g;
 select coalesce(sum((x->>'value')::numeric),0) into tv from jsonb_array_elements(transit)x;
 held:=(result#>>'{summary,warehouse_value}')::numeric;gv:=(result#>>'{summary,gl_value}')::numeric;
 result:=result||jsonb_build_object('movements',movements,'transit',transit,'differences',diffs,'summary',(result->'summary')||
  jsonb_build_object('transit_value',tv::text,'inventory_value',(held+tv)::text,'difference',(held+tv-gv)::text,'difference_count',jsonb_array_length(diffs)));
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='VALUATION_EVIDENCE_LIMIT';end if;
 return result;
end $$;
revoke all on function inventory.build_valuation_report(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function api.landed_extension_documents(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(x.detail order by x.id),'[]') into rows from(
  select a.id,a.detail||jsonb_build_object('has_correction',exists(select 1 from inventory.landed_extensions c where c.tenant_id=a.tenant_id and c.correction_of=a.id)) detail
  from inventory.landed_extensions a where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id and a.branch_id=p_branch_id and (p_after is null or a.id>p_after)
  and not exists(select 1 from jsonb_array_elements(a.detail->'legs')leg
   where not core.has_permission(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(leg->>'branch_id')::uuid)
    or not core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(leg->>'branch_id')::uuid)
    or (leg->>'destination_branch_id' is not null and (
     not core.has_permission(p_tenant_id,'inventory.valuation.post',p_legal_entity_id,(leg->>'destination_branch_id')::uuid)
     or not core.has_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,(leg->>'destination_branch_id')::uuid))))
  order by a.id limit 51)x;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('items',rows,'next_cursor',cursor);
end $$;
revoke all on function api.landed_extension_documents(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.landed_extension_documents(uuid,uuid,uuid,uuid) to authenticated;
revoke all on function api.preview_landed_extension(uuid,uuid,uuid,jsonb),api.post_landed_extension(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.preview_landed_extension(uuid,uuid,uuid,jsonb),api.post_landed_extension(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
notify pgrst,'reload schema';

-- Additive count partition candidate. Capture is bounded to 10,000 identities;
-- approval and posting remain independent existing stock-count transactions.
create table inventory.stock_count_partition_groups (
 id uuid primary key, tenant_id uuid not null references core.tenants(id), legal_entity_id uuid not null,
 branch_id uuid not null, warehouse_id uuid not null, product_id uuid not null,
 cutoff_at timestamptz not null, identity_count integer not null check(identity_count between 1 and 10000),
 partition_count integer not null check(partition_count between 1 and 20),
 baseline_quantity numeric(20,6) not null check(baseline_quantity>=0),
 created_by uuid not null references auth.users(id), created_at timestamptz not null default now(),
 unique(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,product_id) references inventory.products(tenant_id,legal_entity_id,id),
 check(partition_count=(identity_count+499)/500)
);
create table inventory.stock_count_partitions (
 tenant_id uuid not null, group_id uuid not null, count_id uuid not null,
 ordinal integer not null check(ordinal between 1 and 20), identity_count integer not null check(identity_count between 1 and 500),
 baseline_quantity numeric(20,6) not null check(baseline_quantity>=0),
 primary key(tenant_id,group_id,ordinal), unique(tenant_id,count_id), unique(tenant_id,group_id,count_id),
 foreign key(tenant_id,group_id) references inventory.stock_count_partition_groups(tenant_id,id),
 foreign key(tenant_id,count_id) references inventory.stock_counts(tenant_id,id)
);
create table inventory.stock_count_partition_identities (
 tenant_id uuid not null, group_id uuid not null, identity_id uuid not null, count_id uuid not null,
 baseline jsonb not null check(jsonb_typeof(baseline)='object'),
 primary key(tenant_id,group_id,identity_id),
 foreign key(tenant_id,group_id) references inventory.stock_count_partition_groups(tenant_id,id),
 foreign key(tenant_id,group_id,count_id) references inventory.stock_count_partitions(tenant_id,group_id,count_id)
);
create index stock_count_partition_identities_count_idx on inventory.stock_count_partition_identities(tenant_id,count_id,identity_id);
create index stock_count_partition_group_scope_idx on inventory.stock_count_partition_groups(tenant_id,legal_entity_id,branch_id,id);
-- Tenant-leading indexes also cover every referencing foreign key.
do $$declare t text; f record;begin
 foreach t in array array['stock_count_partition_groups','stock_count_partitions','stock_count_partition_identities'] loop
  for f in select c.conname,(select string_agg(quote_ident(a.attname),',' order by k.n)
   from unnest(c.conkey) with ordinality k(num,n) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.num) cols
   from pg_constraint c where c.conrelid=('inventory.'||t)::regclass and c.contype='f' loop
   execute format('create index %I on inventory.%I(%s)',t||'_fk_'||substr(md5(f.conname),1,12)||'_idx',t,f.cols);
  end loop;
 end loop;
end $$;
create function inventory.count_partition_immutable() returns trigger language plpgsql set search_path='' as $$begin
 raise exception using errcode='55000',message='COUNT_PARTITION_BASELINE_IMMUTABLE';
end $$;
revoke all on function inventory.count_partition_immutable() from public,anon,authenticated;
do $$declare t text;begin
 foreach t in array array['stock_count_partition_groups','stock_count_partitions','stock_count_partition_identities'] loop
  execute format('alter table inventory.%I enable row level security',t);
  execute format('alter table inventory.%I force row level security',t);
  execute format('revoke all on inventory.%I from public,anon,authenticated',t);
  execute format('grant select on inventory.%I to authenticated',t);
  execute format('create trigger count_partition_immutable before update or delete on inventory.%I for each row execute function inventory.count_partition_immutable()',t);
 end loop;
end $$;
create policy count_partition_group_read on inventory.stock_count_partition_groups for select to authenticated using (
 core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,'inventory.cost.view',legal_entity_id,branch_id)
 and (core.has_permission(tenant_id,'inventory.adjustments.post',legal_entity_id,branch_id)
 or core.has_permission(tenant_id,'workflow.approvals.decide',legal_entity_id,branch_id))
);
create policy count_partition_read on inventory.stock_count_partitions for select to authenticated using (
 exists(select 1 from inventory.stock_count_partition_groups g where g.tenant_id=stock_count_partitions.tenant_id and g.id=group_id)
);
create policy count_partition_identity_read on inventory.stock_count_partition_identities for select to authenticated using (
 exists(select 1 from inventory.stock_count_partition_groups g where g.tenant_id=stock_count_partition_identities.tenant_id and g.id=group_id)
);

-- Retain the original exact engine. A partition uses its own frozen baseline,
-- never a caller-supplied slice masquerading as the whole product baseline.
alter function inventory.count_normalize(uuid,uuid,uuid,jsonb,jsonb) rename to count_normalize_unpartitioned;
create function inventory.count_normalize(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_old jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare part inventory.stock_count_partitions%rowtype; g inventory.stock_count_partition_groups%rowtype; baseline_rows jsonb;
begin
 select * into part from inventory.stock_count_partitions where tenant_id=p_tenant and count_id=(p_old->>'id')::uuid;
 if part.count_id is null then
  if p_payload ?| array['partition_group_id','partition_ordinal','partition_identity_count','partition_count','partition_baseline_quantity'] then
   raise exception using errcode='22023',message='COUNT_PARTITION_METADATA_SERVER_ONLY';end if;
 else
  select * into g from inventory.stock_count_partition_groups where tenant_id=p_tenant and id=part.group_id;
  if g.legal_entity_id<>p_entity or g.branch_id<>p_branch or g.warehouse_id<>(p_old->>'warehouse_id')::uuid
   or g.cutoff_at<>(p_old->>'cutoff_at')::timestamptz or jsonb_array_length(p_old->'lines')<>1
   or (p_old#>>'{lines,0,product_id}')::uuid<>g.product_id
   or (p_old#>>'{lines,0,baseline_quantity}')::numeric<>part.baseline_quantity then
   raise exception using errcode='55000',message='COUNT_PARTITION_BASELINE_IMMUTABLE';end if;
  if (p_payload ? 'partition_group_id' and p_payload->>'partition_group_id' is distinct from part.group_id::text)
   or (p_payload ? 'partition_ordinal' and (p_payload->>'partition_ordinal')::integer is distinct from part.ordinal)
   or (p_payload ? 'partition_identity_count' and (p_payload->>'partition_identity_count')::integer is distinct from part.identity_count)
   or (p_payload ? 'partition_count' and (p_payload->>'partition_count')::integer is distinct from g.partition_count)
   or (p_payload ? 'partition_baseline_quantity' and (p_payload->>'partition_baseline_quantity')::numeric is distinct from part.baseline_quantity)
   or (p_payload ? 'cutoff_at' and (p_payload->>'cutoff_at')::timestamptz is distinct from g.cutoff_at) then
   raise exception using errcode='22023',message='COUNT_PARTITION_BASELINE_IMMUTABLE';end if;
  select jsonb_agg(baseline order by identity_id) into baseline_rows from inventory.stock_count_partition_identities
   where tenant_id=p_tenant and group_id=part.group_id and count_id=part.count_id;
  if coalesce(jsonb_array_length(baseline_rows),0)<>part.identity_count
   or coalesce(jsonb_array_length(p_old#>'{lines,0,identities}'),0)<>part.identity_count or exists (
   select 1 from jsonb_array_elements(baseline_rows) b where not exists (
    select 1 from jsonb_array_elements(p_old#>'{lines,0,identities}') x where x->>'id'=b->>'id'
     and x->>'baseline_version'=b->>'baseline_version'
     and x-'counted_quantity'-'variance_quantity'-'variance_value'-'baseline_version'
       =b-'counted_quantity'-'variance_quantity'-'variance_value'-'baseline_version')) then
   raise exception using errcode='55000',message='COUNT_PARTITION_BASELINE_IMMUTABLE';end if;
 end if;
 return inventory.count_normalize_unpartitioned(p_tenant,p_entity,p_branch,p_payload,p_old);
end $$;
revoke all on function inventory.count_normalize(uuid,uuid,uuid,jsonb,jsonb) from public,anon,authenticated;
alter function inventory.count_document(text,uuid,uuid,boolean) rename to count_document_unpartitioned;
create function inventory.count_document(p_kind text,p_tenant uuid,p_id uuid,p_lock boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d jsonb; m jsonb;begin
 d:=inventory.count_document_unpartitioned(p_kind,p_tenant,p_id,p_lock);
 if d->'workflow_snapshot'='null'::jsonb then d:=d-'workflow_snapshot';end if;
 select jsonb_build_object('partition_group_id',p.group_id,'partition_ordinal',p.ordinal,
  'partition_count',g.partition_count,'partition_identity_count',p.identity_count,'partition_baseline_quantity',p.baseline_quantity::text)
 into m from inventory.stock_count_partitions p join inventory.stock_count_partition_groups g on g.tenant_id=p.tenant_id and g.id=p.group_id
 where p.tenant_id=p_tenant and p.count_id=p_id;
 return d||coalesce(m,'{}');
end $$;
revoke all on function inventory.count_document(text,uuid,uuid,boolean) from public,anon,authenticated;

create function api.stock_count_partitions_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_group_id uuid,
 p_after integer default 0,p_limit integer default 50)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare g inventory.stock_count_partition_groups%rowtype; rows jsonb; captured integer; posted integer; cancelled integer;
 member_count integer; declared_count integer; baseline numeric; counted numeric; total numeric; missing jsonb; next_ordinal integer;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if not core.has_permission(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id)
  and not core.has_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id) then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 if p_after is null or p_after<0 or p_limit is null or p_limit not between 1 and 50 then
  raise exception using errcode='22023',message='COUNT_PARTITION_PAGE_INVALID';end if;
 select * into g from inventory.stock_count_partition_groups where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and branch_id=p_branch_id and id=p_group_id;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select count(*)::integer,count(*) filter(where c.status='posted')::integer,count(*) filter(where c.status='cancelled')::integer,
  coalesce(sum(p.identity_count),0)::integer,coalesce(sum(p.baseline_quantity),0),coalesce(sum((c.lines#>>'{0,counted_quantity}')::numeric),0),coalesce(sum(c.grand_total),0)
 into captured,posted,cancelled,declared_count,baseline,counted,total
 from inventory.stock_count_partitions p join inventory.stock_counts c on c.tenant_id=p.tenant_id and c.id=p.count_id
 where p.tenant_id=p_tenant_id and p.group_id=p_group_id;
 select count(*)::integer into member_count from inventory.stock_count_partition_identities where tenant_id=p_tenant_id and group_id=p_group_id;
 select coalesce(jsonb_agg(n order by n),'[]') into missing from generate_series(1,g.partition_count)n where not exists(
  select 1 from inventory.stock_count_partitions p join inventory.stock_counts c on c.tenant_id=p.tenant_id and c.id=p.count_id
   where p.tenant_id=p_tenant_id and p.group_id=p_group_id and p.ordinal=n);
 select coalesce(jsonb_agg(jsonb_build_object('id',q.count_id,'partition_ordinal',q.ordinal,'identity_count',q.identity_count,
  'baseline_quantity',q.baseline_quantity::text,'counted_quantity',q.lines#>>'{0,counted_quantity}',
  'variance_quantity',q.lines#>>'{0,variance_quantity}','grand_total',q.grand_total::text,'status',q.status,'version',q.version) order by q.ordinal),'[]')
 into rows from (select p.*,c.lines,c.grand_total,c.status,c.version from inventory.stock_count_partitions p
  join inventory.stock_counts c on c.tenant_id=p.tenant_id and c.id=p.count_id
  where p.tenant_id=p_tenant_id and p.group_id=p_group_id and p.ordinal>p_after order by p.ordinal limit p_limit+1)q;
 if jsonb_array_length(rows)>p_limit then next_ordinal:=(rows->(p_limit-1)->>'partition_ordinal')::integer;rows:=rows-p_limit;end if;
 return jsonb_build_object('id',g.id,'version','1','warehouse_id',g.warehouse_id,'product_id',g.product_id,'cutoff_at',g.cutoff_at,
  'expected_identity_count',g.identity_count,'captured_identity_count',member_count,'expected_partition_count',g.partition_count,
  'captured_partition_count',captured,'posted_partition_count',posted,'cancelled_partition_count',cancelled,
  'missing_partition_ordinals',missing,'baseline_quantity',g.baseline_quantity::text,'counted_quantity',counted::text,
  'variance_quantity',(counted-g.baseline_quantity)::text,'grand_total',total::text,
  'capture_complete',captured=g.partition_count and declared_count=member_count and member_count=g.identity_count and baseline=g.baseline_quantity and missing='[]'::jsonb,
  'posting_complete',posted=g.partition_count and cancelled=0 and declared_count=member_count and member_count=g.identity_count
   and baseline=g.baseline_quantity and missing='[]'::jsonb,'items',rows,'next_cursor',next_ordinal);
end $$;

create function api.capture_stock_count_partitions(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare gid uuid:=(p_payload->>'id')::uuid;wh uuid:=(p_payload->>'warehouse_id')::uuid;pid uuid:=(p_payload->>'product_id')::uuid;
 req uuid:=gen_random_uuid();h text;replay jsonb;product inventory.products%rowtype;b inventory.stock_balances%rowtype;
 identities jsonb;page jsonb;row jsonb;seed jsonb;normalized jsonb;summary jsonb;cutoff timestamptz;n integer;ordinal integer;
 cid uuid;line_id uuid;baseline numeric;group_baseline numeric;currency text;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if gid is null or wh is null or pid is null or p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null
  or (p_payload ? 'partition_size' and p_payload->>'partition_size' is distinct from '500')
  or p_payload ?| array['lines','cutoff_at','partition_group_id','partition_ordinal','corrects_count_id'] then
  raise exception using errcode='22023',message='COUNT_PARTITION_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.stock_count_partitions.capture',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 replay:=core.wave3_replay(p_tenant_id,'inventory.stock_count_partitions.capture',p_command_id,p_idempotency_key,h);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':count-partition-group:'||gid::text,0));
 if p_expected_entity_version is not null or exists(select 1 from inventory.stock_count_partition_groups where id=gid) then
  raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 if not exists(select 1 from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=wh and status='active') then
  raise exception using errcode='22023',message='COUNT_INPUT_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||wh::text||':'||pid::text,0));
 select * into product from inventory.products where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and id=pid and kind='stocked' and status='active' for share;
 if not found or product.tracking_mode not in ('lot','serial') then raise exception using errcode='22023',message='COUNT_PRODUCT_INVALID';end if;
 select * into b from inventory.stock_balances where tenant_id=p_tenant_id and warehouse_id=wh and product_id=pid for update;
 if not found then raise exception using errcode='55000',message='COUNT_BALANCE_REQUIRED';end if;
 -- All captured rows are frozen under the same warehouse/product lock. The extra
 -- row detects overflow explicitly; no prefix is ever accepted as completeness.
 if product.tracking_mode='lot' then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.lot_id,'code',x.code,'baseline_quantity',x.on_hand_quantity::text,
   'counted_quantity',x.on_hand_quantity::text,'baseline_version',x.version,'disposition',x.status) order by x.lot_id),'[]') into identities
  from (select lb.*,l.code,l.status from inventory.lot_balances lb join inventory.lots l on l.tenant_id=lb.tenant_id and l.id=lb.lot_id
   where lb.tenant_id=p_tenant_id and lb.warehouse_id=wh and lb.product_id=pid order by lb.lot_id limit 10001 for update of lb,l)x;
 else
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'code',x.code,'baseline_quantity',case when x.status='count_missing' then '0' else '1' end,
   'counted_quantity',case when x.status='count_missing' then '0' else '1' end,'baseline_version',x.version,'disposition',x.status,
   'restore_status',coalesce(x.count_previous_status,x.status),'lot_id',x.lot_id) order by x.id),'[]') into identities
  from (select * from inventory.serials where tenant_id=p_tenant_id and warehouse_id=wh and product_id=pid
   and status in ('available','quarantine','count_missing') order by id limit 10001 for update)x;
 end if;
 n:=jsonb_array_length(identities);
 if n>10000 then raise exception using errcode='22023',message='LIMIT_EXCEEDED';end if;
 if n=0 then raise exception using errcode='22023',message='COUNT_IDENTITIES_REQUIRED';end if;
 select sum((value->>'baseline_quantity')::numeric) into group_baseline from jsonb_array_elements(identities);
 if group_baseline<>b.on_hand_quantity then raise exception using errcode='55000',message='COUNT_TRACKING_BALANCE_MISMATCH';end if;
 cutoff:=clock_timestamp();
 insert into inventory.stock_count_partition_groups(id,tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,cutoff_at,identity_count,partition_count,baseline_quantity,created_by)
 values(gid,p_tenant_id,p_legal_entity_id,p_branch_id,wh,pid,cutoff,n,(n+499)/500,group_baseline,auth.uid());
 for ordinal in 1..((n+499)/500) loop
  cid:=md5(gid::text||':count-partition:'||ordinal)::uuid;line_id:=md5(cid::text||':line')::uuid;
  select jsonb_agg(value order by idx),sum((value->>'baseline_quantity')::numeric) into page,baseline
   from jsonb_array_elements(identities) with ordinality x(value,idx) where idx>(ordinal-1)*500 and idx<=ordinal*500;
  seed:=p_payload||jsonb_build_object('id',cid,'corrects_count_id',null,'cutoff_at',cutoff,'warehouse_id',wh,
   'lines',jsonb_build_array(jsonb_build_object('line_id',line_id,'product_id',pid,'base_unit_id',product.base_unit_id,
    'tracking_mode',product.tracking_mode,'baseline_quantity',baseline::text,'baseline_version',b.version,
    'counted_quantity',baseline::text,'empty_unit_cost','0','identities',page)));
  normalized:=inventory.count_normalize_unpartitioned(p_tenant_id,p_legal_entity_id,p_branch_id,seed,seed);
  insert into inventory.stock_counts(id,tenant_id,legal_entity_id,branch_id,warehouse_id,cutoff_at,document_date,reason,currency_code,offset_account_id,lines,grand_total,
   request_id,command_id,correlation_id,client_timestamp,prepared_by,created_by,updated_by)
  values(cid,p_tenant_id,p_legal_entity_id,p_branch_id,wh,cutoff,(normalized->>'document_date')::date,normalized->>'reason',normalized->>'currency_code',
   (normalized->>'offset_account_id')::uuid,normalized->'lines',(normalized->>'grand_total')::numeric,req,p_command_id,req,p_client_timestamp,auth.uid(),auth.uid(),auth.uid());
  insert into inventory.stock_count_partitions(tenant_id,group_id,count_id,ordinal,identity_count,baseline_quantity)
   values(p_tenant_id,gid,cid,ordinal,jsonb_array_length(page),baseline);
  insert into inventory.stock_count_partition_identities(tenant_id,group_id,identity_id,count_id,baseline)
   select p_tenant_id,gid,(value->>'id')::uuid,cid,value from jsonb_array_elements(page);
 end loop;
 summary:=api.stock_count_partitions_page(p_tenant_id,p_legal_entity_id,p_branch_id,gid)-'items'-'next_cursor';
 return core.wave3_finish_command(p_tenant_id,'inventory.stock_count_partitions.capture',p_command_id,'stock_count_partition_group',gid,
  p_idempotency_key,h,null,summary,p_legal_entity_id,p_branch_id,'{}',null,
  jsonb_build_array(jsonb_build_object('topic','inventory.stock_count_partitions.capture','payload',jsonb_build_object('id',gid,'partition_count',(n+499)/500))),'[]',req,req);
end $$;
revoke all on function api.capture_stock_count_partitions(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.stock_count_partitions_page(uuid,uuid,uuid,uuid,integer,integer) from public,anon,authenticated;
grant execute on function api.capture_stock_count_partitions(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.stock_count_partitions_page(uuid,uuid,uuid,uuid,integer,integer) to authenticated;

-- UNAPPLIED candidate. Contract 51. No transfer ledger helper or movement labels.
insert into core.permissions(code,module,description,privileged)
values('inventory.dispositions.post','inventory','Post approved inventory disposition and linked corrections.',true)
on conflict(code) do nothing;
insert into core.role_permissions(tenant_id,role_id,permission_code)
select tenant_id,id,'inventory.dispositions.post' from core.roles where code='tenant_owner'
on conflict(role_id,permission_code) do nothing;
-- Stock disposition candidate. Independent aggregate; reuses installed governance and ledger primitives.
create table inventory.stock_dispositions (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references core.tenants(id),
 legal_entity_id uuid not null, branch_id uuid not null, warehouse_id uuid not null,
 document_type text not null default 'inventory_disposition' check(document_type='inventory_disposition'), corrects_disposition_id uuid, reverses_disposition_id uuid, post_state jsonb,
 cutoff_at timestamptz not null, document_number text, document_date date not null, reason text not null check(length(trim(reason)) between 3 and 1000),
 currency_code text not null references core.currencies(code), offset_account_id uuid not null,
 lines jsonb not null check(jsonb_typeof(lines)='array' and jsonb_array_length(lines) between 1 and 100),
 grand_total numeric(20,6) not null check(grand_total>=0),
 status text not null default 'draft' check(status in ('draft','pending_approval','approved','rejected','cancelled','posted')),
 version bigint not null default 1, workflow_snapshot jsonb, submitted_by uuid references auth.users(id),
 posted_by uuid references auth.users(id), posted_at timestamptz, stock_movement_id uuid, journal_entry_id uuid,
 request_id uuid not null, command_id uuid not null, correlation_id uuid not null, client_timestamp timestamptz not null,
 prepared_by uuid not null references auth.users(id),
 created_by uuid not null references auth.users(id), updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(tenant_id,id), unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,offset_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,corrects_disposition_id) references inventory.stock_dispositions(tenant_id,id),
 foreign key(tenant_id,reverses_disposition_id) references inventory.stock_dispositions(tenant_id,id),
 check(corrects_disposition_id is null or reverses_disposition_id is null),
 check((status='posted')=(posted_at is not null)),
 check(status<>'posted' or posted_by is not null)
);
alter table inventory.stock_dispositions enable row level security;
alter table inventory.stock_dispositions force row level security;
create policy disposition_permitted_read on inventory.stock_dispositions for select to authenticated using (
 core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,'inventory.cost.view',legal_entity_id,branch_id)
 and (core.has_permission(tenant_id,'inventory.dispositions.post',legal_entity_id,branch_id)
 or core.has_permission(tenant_id,'workflow.approvals.decide',legal_entity_id,branch_id))
);
create trigger disposition_immutable_posted before update or delete on inventory.stock_dispositions
 for each row execute function sales.flow_protect_document();
create trigger disposition_touch before update on inventory.stock_dispositions
 for each row execute function core.touch_mutable_record();
create index stock_dispositions_scope_idx on inventory.stock_dispositions(tenant_id,legal_entity_id,branch_id,status,id);
-- Lead each FK index with its referencing columns; retain the scoped register index.
do $$ declare f record; begin
 for f in select c.conname, (select string_agg(quote_ident(a.attname),',' order by k.n)
 from unnest(c.conkey) with ordinality k(num,n) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.num) cols
 from pg_constraint c where c.conrelid='inventory.stock_dispositions'::regclass and c.contype='f' loop
 execute format('create index %I on inventory.stock_dispositions(%s)',f.conname||'_idx',f.cols);
 end loop;
end $$;

create function api.post_stock_disposition(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid; req uuid:=gen_random_uuid(); h text; result jsonb; d jsonb; x jsonb;
 jlines jsonb:='[]'; j uuid; m uuid:=gen_random_uuid(); q numeric; amount numeric; v_date date; sid uuid; state jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.dispositions.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null or v_id is null then
 raise exception using errcode='22023',message='DISPOSITION_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.stock_disposition.post',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.stock_disposition.post',p_command_id,p_idempotency_key,h);if result is not null then return result;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':disposition:'||v_id::text,0));
 d:=inventory.disposition_document('inventory_disposition',p_tenant_id,v_id,true);
 if d is null or d->>'legal_entity_id'<>p_legal_entity_id::text or d->>'branch_id'<>p_branch_id::text then
 raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version((d->>'version')::bigint,p_expected_entity_version,d);
 if d->>'status'<>'approved' then raise exception using errcode='55000',message='DISPOSITION_APPROVAL_REQUIRED';end if;
 perform sales.flow_assert_transition(d#>'{workflow_snapshot,lifecycle}','approved','posted');
 if d#>'{workflow_snapshot,lifecycle,separate_poster}'='true'::jsonb and (d->>'submitted_by')::uuid=auth.uid() then
 raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 v_date:=(d->>'document_date')::date;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 perform inventory.disposition_revalidate('inventory_disposition',d);
 insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,
 posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
 values(m,p_tenant_id,p_legal_entity_id,p_branch_id,'inventory_disposition',v_id,(d->>'warehouse_id')::uuid,
 v_date,case when d->>'reverses_disposition_id' is null then 'disposition' else 'disposition_reversal' end,req,p_command_id,req,auth.uid());
 for x in select value from jsonb_array_elements(d->'lines') order by value->>'product_id',value->>'line_id' loop
  q:=(x->>'base_quantity')::numeric;amount:=(x->>'carrying_value')::numeric;
  if d->>'reverses_disposition_id' is null then q:=-q;amount:=-amount;end if;
  update inventory.stock_balances set on_hand_quantity=on_hand_quantity+q,updated_by=auth.uid()
  where tenant_id=p_tenant_id and warehouse_id=(d->>'warehouse_id')::uuid and product_id=(x->>'product_id')::uuid
  and available_quantity+q>=0;
  if not found then raise exception using errcode='55000',message='DISPOSITION_STOCK_UNAVAILABLE';end if;
  update inventory.stock_valuations v set carrying_value=carrying_value+amount,updated_by=auth.uid()
  from inventory.stock_balances b where v.tenant_id=p_tenant_id and v.stock_balance_id=b.id
  and b.tenant_id=p_tenant_id and b.warehouse_id=(d->>'warehouse_id')::uuid and b.product_id=(x->>'product_id')::uuid
  and v.carrying_value+amount>=0 and (b.on_hand_quantity<>0 or v.carrying_value+amount=0);
  if not found then raise exception using errcode='55000',message='DISPOSITION_VALUE_UNAVAILABLE';end if;
  if x->>'lot_id' is not null then
   update inventory.lot_balances set on_hand_quantity=on_hand_quantity+q,updated_by=auth.uid()
   where tenant_id=p_tenant_id and warehouse_id=(d->>'warehouse_id')::uuid and lot_id=(x->>'lot_id')::uuid
   and on_hand_quantity+q>=0;
   if not found then raise exception using errcode='55000',message='DISPOSITION_LOT_UNAVAILABLE';end if;
  end if;
  for sid in select value::uuid from jsonb_array_elements_text(x->'serial_ids') loop
   update inventory.serials set status='disposed',updated_by=auth.uid()
   where tenant_id=p_tenant_id and id=sid and warehouse_id=(d->>'warehouse_id')::uuid and status in('available','quarantine');
   if not found then raise exception using errcode='55000',message='DISPOSITION_SERIAL_UNAVAILABLE';end if;
  end loop;
  -- The existing receipt-provenance trigger consumes/restores exact source cohorts atomically.
  insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,
  product_id,source_line_id,original_movement_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,m,(d->>'warehouse_id')::uuid,(x->>'product_id')::uuid,
  (x->>'line_id')::uuid,(x->>'original_movement_line_id')::uuid,q,amount,(x->>'lot_id')::uuid,
  array(select value::uuid from jsonb_array_elements_text(x->'serial_ids')),v_date,auth.uid());
  if amount<>0 then jlines:=jlines||jsonb_build_array(finance.flow_jline((x->>'inventory_account_id')::uuid,amount,amount,(x->>'line_id')::uuid),
  finance.flow_jline((d->>'offset_account_id')::uuid,-amount,-amount,(x->>'line_id')::uuid));end if;
 end loop;
 j:=finance.flow_post_journal(d||jsonb_build_object('base_currency_code',d->>'currency_code','exchange_rate','1'),jlines,'inventory_disposition',v_id,req,p_command_id);
 select jsonb_object_agg(b.product_id::text,jsonb_build_object('balance_version',b.version,'valuation_version',v.version,
 'on_hand_quantity',b.on_hand_quantity::text,'carrying_value',v.carrying_value::text)) into state
 from inventory.stock_balances b join inventory.stock_valuations v on v.stock_balance_id=b.id and v.tenant_id=b.tenant_id
 where b.tenant_id=p_tenant_id and b.warehouse_id=(d->>'warehouse_id')::uuid
 and b.product_id in(select (value->>'product_id')::uuid from jsonb_array_elements(d->'lines'));
 update inventory.stock_dispositions set status='posted',posted_at=clock_timestamp(),posted_by=auth.uid(),updated_by=auth.uid(),
 stock_movement_id=m,journal_entry_id=j,post_state=state,request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp
 where tenant_id=p_tenant_id and id=v_id;
 return core.wave3_finish_command(p_tenant_id,'inventory.stock_disposition.post',p_command_id,'inventory_disposition',v_id,p_idempotency_key,h,d,
 inventory.disposition_document('inventory_disposition',p_tenant_id,v_id),p_legal_entity_id,p_branch_id,'{}',
 jsonb_build_object('from_status','approved','to_status','posted','reason',d->>'reason'),
 jsonb_build_array(jsonb_build_object('topic','inventory.stock_disposition.post','payload',jsonb_build_object('id',v_id))),'[]',req,req);
end $$;


-- Preserve every existing movement kind; this additive kind describes the actual source.
do $$declare c text;begin
 select pg_get_constraintdef(oid) into c from pg_constraint where conrelid='inventory.stock_movements'::regclass
 and conname='stock_movements_movement_kind_check';
 if c is null then raise exception 'MOVEMENT_CONSTRAINT_DRIFT';end if;
 alter table inventory.stock_movements drop constraint stock_movements_movement_kind_check;
 execute 'alter table inventory.stock_movements add constraint stock_movements_movement_kind_check CHECK ('||substring(c from 7)||' OR movement_kind IN (''disposition'',''disposition_reversal''))';
end $$;
create unique index one_posted_disposition_reversal on inventory.stock_dispositions(tenant_id,reverses_disposition_id)
where status='posted' and reverses_disposition_id is not null;
-- A disposed serial remains disposed even if a future command attempts to receive/return it.
create function inventory.disposition_protect_serial() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then
  if old.status='disposed' then raise exception using errcode='55000',message='DISPOSED_SERIAL_IMMUTABLE';end if;
  return old;
 end if;
 if old.status='disposed' and (new.status<>'disposed' or new.warehouse_id<>old.warehouse_id or new.product_id<>old.product_id
 or new.tenant_id<>old.tenant_id or new.lot_id is distinct from old.lot_id) then
 raise exception using errcode='55000',message='DISPOSED_SERIAL_IMMUTABLE';end if;
 return new;
end $$;
create trigger disposition_serial_permanent before update or delete on inventory.serials
for each row execute function inventory.disposition_protect_serial();
revoke all on function inventory.disposition_protect_serial() from public,anon,authenticated;

-- Normalize under the same sorted locks used by delivery, transfers and valuation.
-- Exact cumulative allocation avoids a rounding leak when several selected lots share one pool.
create function inventory.disposition_normalize(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_old jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare wh uuid:=(p_payload->>'warehouse_id')::uuid; x jsonb; z jsonb; source jsonb; source_line jsonb;
 product inventory.products%rowtype; b inventory.stock_balances%rowtype; val inventory.stock_valuations%rowtype;
 lot inventory.lots%rowtype; lb inventory.lot_balances%rowtype; s inventory.serials%rowtype;
 resolved jsonb; q numeric; amount numeric; cumulative numeric; prior_amount numeric; total numeric:=0;
 lines jsonb:='[]'; serial_rows jsonb; serial_ids uuid[]; seen_serials uuid[]:='{}'; seen_lines uuid[]:='{}';
 seen_lots uuid[]:='{}'; line_id uuid; sid uuid; lid uuid; currency text; previous_product uuid;
 reversal uuid:=(p_payload->>'reverses_disposition_id')::uuid; correction uuid:=(p_payload->>'corrects_disposition_id')::uuid;
 serial_count integer:=0; original uuid; state jsonb;
begin
 if wh is null or not exists(select 1 from core.warehouses where tenant_id=p_tenant and legal_entity_id=p_entity
 and branch_id=p_branch and id=wh and status='active') or coalesce(length(trim(p_payload->>'reason')),0) not between 3 and 1000
 or p_payload->>'document_date' is null or (reversal is not null and correction is not null)
 then raise exception using errcode='22023',message='DISPOSITION_INPUT_INVALID';end if;
 if (p_payload->>'document_date')::date>(clock_timestamp() at time zone 'UTC')::date then
 raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 if p_old is not null and (p_old->>'warehouse_id' is distinct from p_payload->>'warehouse_id'
 or p_old->>'corrects_disposition_id' is distinct from p_payload->>'corrects_disposition_id'
 or p_old->>'reverses_disposition_id' is distinct from p_payload->>'reverses_disposition_id') then
 raise exception using errcode='22023',message='DISPOSITION_LINK_IMMUTABLE';end if;
 select currency_code into currency from core.legal_entities where tenant_id=p_tenant and id=p_entity;
 perform finance.flow_account(p_tenant,p_entity,(p_payload->>'offset_account_id')::uuid,'expense',currency);
 if coalesce(reversal,correction) is not null then
  perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':disposition:'||coalesce(reversal,correction)::text,0));
  select sales.flow_exact_json(to_jsonb(d)) into source from inventory.stock_dispositions d
  where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and warehouse_id=wh
  and id=coalesce(reversal,correction) and status='posted' and reverses_disposition_id is null for share;
  if source is null or (p_payload->>'document_date')::date<(source->>'document_date')::date then
  raise exception using errcode='22023',message='DISPOSITION_CORRECTION_SOURCE_INVALID';end if;
 end if;
 if reversal is not null then
  if exists(select 1 from inventory.stock_dispositions where tenant_id=p_tenant and reverses_disposition_id=reversal and status='posted') then
  raise exception using errcode='55000',message='DISPOSITION_ALREADY_REVERSED';end if;
  if exists(select 1 from jsonb_array_elements(source->'lines') l where l->>'tracking_mode'='serial') then
  raise exception using errcode='55000',message='DISPOSITION_SERIAL_REVERSAL_DENIED';end if;
  if p_payload->'lines' is not null and p_old is null then raise exception using errcode='22023',message='DISPOSITION_REVERSAL_LINES_SERVER_OWNED';end if;
  if (p_payload->>'offset_account_id')::uuid<>(source->>'offset_account_id')::uuid then
  raise exception using errcode='22023',message='DISPOSITION_REVERSAL_ACCOUNT_IMMUTABLE';end if;
 end if;
 z:=case when reversal is not null then source->'lines' else p_payload->'lines' end;
 if jsonb_typeof(z) is distinct from 'array' or jsonb_array_length(z) not between 1 and 100 then
 raise exception using errcode='22023',message='DISPOSITION_LINES_INVALID';end if;
 for x in select value from jsonb_array_elements(z) order by value->>'product_id',value->>'line_id' loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||wh::text||':'||(x->>'product_id'),0));
 end loop;
 for x in select value from jsonb_array_elements(z) order by value->>'product_id',value->>'line_id' loop
  line_id:=case when reversal is null then (x->>'line_id')::uuid else md5((p_payload->>'id')||':'||(x->>'line_id'))::uuid end;
  select * into product from inventory.products where tenant_id=p_tenant and legal_entity_id=p_entity
  and id=(x->>'product_id')::uuid and kind='stocked' and status='active' for share;
  if not found or line_id is null or line_id=any(seen_lines) then raise exception using errcode='22023',message='DISPOSITION_PRODUCT_INVALID';end if;
  seen_lines:=array_append(seen_lines,line_id);
  if previous_product is distinct from product.id then cumulative:=0;prior_amount:=0;end if;
  previous_product:=product.id;
  select * into b from inventory.stock_balances where tenant_id=p_tenant and warehouse_id=wh and product_id=product.id for update;
  select * into val from inventory.stock_valuations where tenant_id=p_tenant and stock_balance_id=b.id for update;
  if b.id is null or val.id is null then raise exception using errcode='55000',message='DISPOSITION_BALANCE_REQUIRED';end if;
  if exists(select 1 from inventory.stock_movement_lines where tenant_id=p_tenant and warehouse_id=wh
  and product_id=product.id and posting_date>(p_payload->>'document_date')::date) then
  raise exception using errcode='55000',message='BACKDATED_DISPOSITION_REQUIRES_REVIEW';end if;
  perform finance.flow_account(p_tenant,p_entity,product.inventory_account_id,'asset',currency);
  original:=null;
  if reversal is null then
   resolved:=inventory.resolve_product_unit(p_tenant,p_entity,product.id,(x->>'unit_id')::uuid,x->'quantity',x->'conversion_numerator',x->'conversion_denominator');
   q:=(resolved->>'base_quantity')::numeric;
   cumulative:=cumulative+q;
   if b.available_quantity<cumulative then raise exception using errcode='55000',message='DISPOSITION_STOCK_UNAVAILABLE';end if;
   amount:=case when cumulative=b.on_hand_quantity then val.carrying_value else round(val.carrying_value*cumulative/nullif(b.on_hand_quantity,0),6) end-prior_amount;
   prior_amount:=prior_amount+amount;
  else
   q:=(x->>'base_quantity')::numeric;amount:=(x->>'carrying_value')::numeric;
   state:=source->'post_state'->product.id::text;
   if state is null or b.version<>(state->>'balance_version')::bigint or val.version<>(state->>'valuation_version')::bigint
   or b.on_hand_quantity<>(state->>'on_hand_quantity')::numeric or val.carrying_value<>(state->>'carrying_value')::numeric then
   raise exception using errcode='55000',message='DISPOSITION_LATER_HISTORY';end if;
   select ml.id into original from inventory.stock_movement_lines ml where tenant_id=p_tenant
   and stock_movement_id=(source->>'stock_movement_id')::uuid and source_line_id=(x->>'line_id')::uuid;
   if original is null then raise exception using errcode='55000',message='DISPOSITION_SOURCE_MOVEMENT_MISSING';end if;
   resolved:=x;
  end if;
  lid:=(x->>'lot_id')::uuid;serial_rows:='[]';serial_ids:='{}';lot:=null;lb:=null;
  if product.tracking_mode='none' and (lid is not null or coalesce(jsonb_array_length(x->'serial_ids'),0)>0) then
  raise exception using errcode='22023',message='DISPOSITION_TRACKING_INVALID';end if;
  if lid is not null then
   select * into lot from inventory.lots where tenant_id=p_tenant and legal_entity_id=p_entity and product_id=product.id and id=lid for update;
   select * into lb from inventory.lot_balances where tenant_id=p_tenant and warehouse_id=wh and product_id=product.id and lot_id=lid for update;
   if lot.id is null or lb.id is null or lot.status='disposed' or (reversal is null and lb.on_hand_quantity<q) or lid=any(seen_lots) then
   raise exception using errcode='55000',message='DISPOSITION_LOT_UNAVAILABLE';end if;
   -- Expiry is deliberately accepted here; saleable deliveries retain their expiry guard.
   seen_lots:=array_append(seen_lots,lid);
  elsif product.tracking_mode='lot' then raise exception using errcode='22023',message='DISPOSITION_TRACKING_INVALID';end if;
  if product.tracking_mode='serial' then
   if jsonb_typeof(x->'serial_ids') is distinct from 'array' or jsonb_array_length(x->'serial_ids')<>q or q<>trunc(q) then
   raise exception using errcode='22023',message='DISPOSITION_SERIAL_QUANTITY_INVALID';end if;
   for sid in select value::text::uuid from jsonb_array_elements_text(x->'serial_ids') order by value loop
    serial_count:=serial_count+1;
    if sid=any(seen_serials) or serial_count>500 then raise exception using errcode='22023',message='DISPOSITION_SERIAL_DUPLICATE_OR_LIMIT';end if;
    select * into s from inventory.serials where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch
    and warehouse_id=wh and product_id=product.id and id=sid and status in('available','quarantine') for update;
    if not found or s.lot_id is distinct from lid then raise exception using errcode='55000',message='DISPOSITION_SERIAL_UNAVAILABLE';end if;
    seen_serials:=array_append(seen_serials,sid);serial_ids:=array_append(serial_ids,sid);
    serial_rows:=serial_rows||jsonb_build_array(jsonb_build_object('id',sid,'version',s.version,'status',s.status));
   end loop;
  elsif coalesce(jsonb_array_length(x->'serial_ids'),0)<>0 then raise exception using errcode='22023',message='DISPOSITION_TRACKING_INVALID';end if;
  total:=total+amount;
  lines:=lines||jsonb_build_array(resolved||jsonb_build_object('line_id',line_id,'product_id',product.id,'product_name',product.name,
   'unit_id',coalesce(x->>'unit_id',product.base_unit_id::text),'quantity',coalesce(x->>'quantity',q::text),
   'conversion_numerator',coalesce(x->>'conversion_numerator','1'),'conversion_denominator',coalesce(x->>'conversion_denominator','1'),
   'base_quantity',q::text,'carrying_value',amount::text,'tracking_mode',product.tracking_mode,'inventory_account_id',product.inventory_account_id,
   'lot_id',lid,'lot_version',lot.version,'lot_balance_version',lb.version,'serial_ids',to_jsonb(serial_ids),'serial_snapshot',serial_rows,
   'baseline_version',b.version,'valuation_version',val.version,'original_movement_line_id',original));
 end loop;
 return jsonb_build_object('warehouse_id',wh,'document_date',p_payload->>'document_date','reason',trim(p_payload->>'reason'),
 'currency_code',currency,'offset_account_id',p_payload->>'offset_account_id','cutoff_at',coalesce(p_old->>'cutoff_at',clock_timestamp()::text),
 'lines',sales.flow_exact_json(lines),'grand_total',total::text);
end $$;

create function inventory.disposition_revalidate(p_kind text,p_doc jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare d jsonb;begin
 if p_kind<>'inventory_disposition' then raise exception using errcode='22023',message='DOCUMENT_TYPE_INVALID';end if;
 d:=inventory.disposition_normalize((p_doc->>'tenant_id')::uuid,(p_doc->>'legal_entity_id')::uuid,(p_doc->>'branch_id')::uuid,p_doc,p_doc);
 if d->'lines'<>p_doc->'lines' or d->>'currency_code'<>p_doc->>'currency_code' then
 raise exception using errcode='55000',message='DISPOSITION_REAPPROVAL_REQUIRED';end if;
 return d;
end $$;

create function api.upsert_stock_disposition(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare id uuid:=(p_payload->>'id')::uuid;req uuid:=gen_random_uuid();h text;result jsonb;old_doc jsonb;d jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.dispositions.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null or id is null then raise exception using errcode='22023',message='DISPOSITION_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('inventory.stock_disposition.upsert',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 result:=core.wave3_replay(p_tenant_id,'inventory.stock_disposition.upsert',p_command_id,p_idempotency_key,h);if result is not null then return result;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':count:'||id::text,0));
 old_doc:=inventory.disposition_document('inventory_disposition',p_tenant_id,id,true);
 if old_doc is not null then
  if old_doc->>'legal_entity_id'<>p_legal_entity_id::text or old_doc->>'branch_id'<>p_branch_id::text then raise exception using errcode='42501',message='DOCUMENT_SCOPE_INVALID';end if;
  perform core.wave3_assert_expected_version((old_doc->>'version')::bigint,p_expected_entity_version,old_doc);
  if old_doc->>'status'<>'draft' then raise exception using errcode='55000',message='DOCUMENT_NOT_EDITABLE';end if;
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 d:=inventory.disposition_normalize(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,old_doc);
 insert into inventory.stock_dispositions(id,tenant_id,legal_entity_id,branch_id,warehouse_id,cutoff_at,document_date,reason,currency_code,offset_account_id,lines,grand_total,corrects_disposition_id,reverses_disposition_id,
 request_id,command_id,correlation_id,client_timestamp,prepared_by,created_by,updated_by)
 values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(d->>'warehouse_id')::uuid,(d->>'cutoff_at')::timestamptz,(d->>'document_date')::date,d->>'reason',d->>'currency_code',
 (d->>'offset_account_id')::uuid,d->'lines',(d->>'grand_total')::numeric,(p_payload->>'corrects_disposition_id')::uuid,(p_payload->>'reverses_disposition_id')::uuid,req,p_command_id,req,p_client_timestamp,auth.uid(),auth.uid(),auth.uid())
 on conflict on constraint stock_dispositions_pkey do update set document_date=excluded.document_date,reason=excluded.reason,offset_account_id=excluded.offset_account_id,
 lines=excluded.lines,grand_total=excluded.grand_total,prepared_by=auth.uid(),updated_by=auth.uid(),request_id=req,command_id=p_command_id,correlation_id=req,client_timestamp=p_client_timestamp
 where inventory.stock_dispositions.tenant_id=excluded.tenant_id and inventory.stock_dispositions.legal_entity_id=excluded.legal_entity_id and inventory.stock_dispositions.branch_id=excluded.branch_id;
 if not found then raise exception using errcode='42501',message='DOCUMENT_SCOPE_INVALID';end if;
 return core.wave3_finish_command(p_tenant_id,'inventory.stock_disposition.upsert',p_command_id,'inventory_disposition',id,p_idempotency_key,h,old_doc,
 inventory.disposition_document('inventory_disposition',p_tenant_id,id),p_legal_entity_id,p_branch_id,'{}',null,'[]','[]',req,req);
end $$;
revoke all on inventory.stock_dispositions from public,anon,authenticated;
grant select on inventory.stock_dispositions to authenticated;
create view api.stock_dispositions with(security_invoker=true) as
 select id,tenant_id,legal_entity_id,branch_id,warehouse_id,document_number,document_date,status,version,
 sales.flow_exact_json(to_jsonb(o)) as detail from inventory.stock_dispositions o;
revoke all on api.stock_dispositions from public,anon,authenticated;
grant select on api.stock_dispositions to authenticated;

create function inventory.disposition_document(p_kind text,p_tenant uuid,p_id uuid,p_lock boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d inventory.stock_dispositions%rowtype; begin
 if p_kind is distinct from 'inventory_disposition' then raise exception using errcode='22023',message='DOCUMENT_TYPE_INVALID';end if;
 if p_lock then select * into d from inventory.stock_dispositions where tenant_id=p_tenant and id=p_id for update;
 else select * into d from inventory.stock_dispositions where tenant_id=p_tenant and id=p_id;end if;
 if not found then return null;end if;
 return sales.flow_exact_json(to_jsonb(d))||jsonb_build_object('warehouse_name',(select name from core.warehouses where id=d.warehouse_id),
  'offset_account_name',(select name from finance.accounts where id=d.offset_account_id));
end $$;


create function api.transition_stock_disposition(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_kind text:='inventory_disposition';v_id uuid:=(p_payload->>'document_id')::uuid;
 v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';v_command text;
 v_doc jsonb;v_before jsonb;v_hash text;v_replay jsonb;v_to text;v_snapshot jsonb;
 v_workflow workflow.workflow_definitions%rowtype;v_request uuid:=gen_random_uuid();v_first integer;
 v_ar workflow.approval_requests%rowtype;v_step jsonb;v_number text;
begin
 v_command:='inventory.'||v_kind||case when v_decision is null then '.transition' else '.decide' end;
 perform core.wave3_require_scope(p_tenant_id,case when v_decision is null then 'inventory.dispositions.post' else 'workflow.approvals.decide' end,p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or (p_payload ? 'document_type' and p_payload->>'document_type' is distinct from 'inventory_disposition')
 or (v_decision is not null and v_action is not null) then raise exception using errcode='22023',message='DOCUMENT_PAYLOAD_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_replay:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
 v_doc:=inventory.disposition_document(v_kind,p_tenant_id,v_id,true);v_before:=v_doc;
 if v_doc is null or (v_doc->>'legal_entity_id')::uuid<>p_legal_entity_id or (v_doc->>'branch_id')::uuid<>p_branch_id then
 raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version((v_doc->>'version')::bigint,p_expected_entity_version,v_doc);
 if v_doc->>'status'='posted' then raise exception using errcode='55000',message='POSTED_DOCUMENT_IMMUTABLE';end if;
 v_snapshot:=v_doc->'workflow_snapshot';v_number:=v_doc->>'document_number';
 if v_decision is not null then
 if v_decision not in ('approved','rejected') or v_doc->>'status'<>'pending_approval' then raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
 select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type=v_kind and document_id=v_id and status='submitted' for update;
 if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
 if v_ar.submitted_by=auth.uid() or (v_doc->>'created_by')::uuid=auth.uid() or (v_doc->>'prepared_by')::uuid=auth.uid() then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
 if v_step is null or not exists(select 1 from core.memberships m join core.role_assignments ra on ra.tenant_id=m.tenant_id and ra.membership_id=m.id
 join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
 where m.tenant_id=p_tenant_id and m.user_id=auth.uid() and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
 and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
 and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
 if v_decision='rejected' and nullif(trim(p_payload->>'note'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
 perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
 insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
 approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
 values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
 auth.uid(),v_decision,p_payload->>'note',v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
 if v_decision='approved' then select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
 where (x->>'step_order')::integer>v_ar.current_step;end if;
 v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
 if v_first is null then update workflow.approval_requests set status=v_to,decision_by=auth.uid(),decision_note=p_payload->>'note',decided_at=clock_timestamp() where id=v_ar.id;
 else update workflow.approval_requests set current_step=v_first where id=v_ar.id;end if;
 elsif v_action='submit' then
 if v_doc->>'status'<>'draft' then raise exception using errcode='55000',message='DOCUMENT_NOT_EDITABLE';end if;
 perform inventory.disposition_revalidate(v_kind,v_doc);
 select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id and document_type=v_kind and status='active'
 and (legal_entity_id is null or legal_entity_id=p_legal_entity_id) order by (legal_entity_id is not null) desc limit 1;
 if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
 select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
 'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
 from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
 and (s.currency_code is null or s.currency_code=v_doc->>'currency_code')
 and (s.minimum_amount is null or (v_doc->>'grand_total')::numeric>=s.minimum_amount)
 and (s.maximum_amount is null or (v_doc->>'grand_total')::numeric<=s.maximum_amount);
 if v_workflow.lifecycle->'requires_approval' is distinct from 'true'::jsonb then
 raise exception using errcode='55000',message='DISPOSITION_APPROVAL_REQUIRED';end if;
 select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
 if v_first is null then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
 v_to:='pending_approval';
 perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
 v_number:=coalesce(v_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,(v_doc->>'document_date')::date,auth.uid()));
 if v_first is not null then insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
 submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,v_kind,v_id,'submitted',auth.uid(),v_workflow.id,v_workflow.revision,v_first,
 (v_doc->>'grand_total')::numeric,v_doc->>'currency_code',p_command_id,v_request,v_request);end if;
 elsif v_action in ('recall','cancel') then
 if nullif(trim(p_payload->>'reason'),'') is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
 if (v_snapshot is null or v_snapshot='null'::jsonb) and v_doc->>'status'='draft' then
 select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
 where tenant_id=p_tenant_id and document_type=v_kind and status='active'
 and (legal_entity_id is null or legal_entity_id=p_legal_entity_id) order by (legal_entity_id is not null) desc limit 1;
 end if;
 v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
 perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc->>'status',v_to);
 update workflow.approval_requests set status='cancelled',decision_by=auth.uid(),decision_note=p_payload->>'reason',decided_at=clock_timestamp()
 where tenant_id=p_tenant_id and document_type=v_kind and document_id=v_id and status='submitted';
 if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='DOCUMENT_ACTION_INVALID';end if;
 execute format('update inventory.%I set status=$1,workflow_snapshot=$2,document_number=$3,submitted_by=case when $4=''submit'' then $5 else submitted_by end,updated_by=$5,request_id=$6,command_id=$7,correlation_id=$6,client_timestamp=$8 where tenant_id=$9 and id=$10','stock_dispositions')
 using v_to,v_snapshot,v_number,v_action,auth.uid(),v_request,p_command_id,p_client_timestamp,p_tenant_id,v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,v_kind,v_id,p_idempotency_key,v_hash,v_before,
 inventory.disposition_document(v_kind,p_tenant_id,v_id),p_legal_entity_id,p_branch_id,coalesce(p_payload->'source_context','{}'),
 case when v_doc->>'status'=v_to then null else
 jsonb_build_object('from_status',v_doc->>'status','to_status',v_to,'reason',coalesce(p_payload->>'reason',p_payload->>'note')) end,
 jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
end $$;




create function api.stock_dispositions_page(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if not core.has_permission(p_tenant_id,'inventory.dispositions.post',p_legal_entity_id,p_branch_id) and not core.has_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'document_number',q.document_number,'document_date',q.document_date,'status',q.status,
  'version',q.version,'currency_code',q.currency_code,'grand_total',q.grand_total::text,'warehouse_name',(select name from core.warehouses where id=q.warehouse_id)) order by q.id),'[]') into rows
 from (select * from inventory.stock_dispositions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and (p_after is null or id>p_after) order by id limit 51)q;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'items',rows,'next_cursor',next_id);
end $$;
create function api.stock_disposition_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d jsonb;begin
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if not core.has_permission(p_tenant_id,'inventory.dispositions.post',p_legal_entity_id,p_branch_id) and not core.has_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 d:=inventory.disposition_document('inventory_disposition',p_tenant_id,p_id);
 if d is null or d->>'legal_entity_id' is distinct from p_legal_entity_id::text or d->>'branch_id' is distinct from p_branch_id::text then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 return d;
end $$;
revoke all on function api.stock_disposition_detail(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.stock_disposition_detail(uuid,uuid,uuid,uuid) to authenticated;

-- Bounded picker. A product is mandatory for lot/serial identities; expired held lots are visible.
create function api.stock_disposition_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,
 p_warehouse_id uuid default null,p_product_id uuid default null,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;next_id uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.dispositions.post',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 if p_resource in('products','lots','serials') and not exists(select 1 from core.warehouses where tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_warehouse_id and status='active') then
 raise exception using errcode='42501',message='DISPOSITION_WAREHOUSE_SCOPE_REQUIRED';end if;
 if p_resource in('lots','serials') and not exists(select 1 from inventory.products where tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and id=p_product_id and status='active' and kind='stocked') then
 raise exception using errcode='22023',message='DISPOSITION_PRODUCT_REQUIRED';end if;
 if p_resource='warehouses' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from(select id,name,code from core.warehouses
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active'
  and(p_after is null or id>p_after) order by id limit 51)q;
 elsif p_resource='products' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from(select p.id,p.name,p.sku,p.base_unit_id,
  p.tracking_mode,b.available_quantity::text available_quantity from inventory.products p join inventory.stock_balances b
  on b.product_id=p.id and b.tenant_id=p.tenant_id and b.warehouse_id=p_warehouse_id
  where p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id and p.kind='stocked' and p.status='active'
  and b.available_quantity>0 and(p_after is null or p.id>p_after) order by p.id limit 51)q;
 elsif p_resource='lots' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from(select l.id,l.code,l.expiry_date,l.status,
  b.on_hand_quantity::text held_quantity,l.version,b.version balance_version from inventory.lots l join inventory.lot_balances b
  on b.tenant_id=l.tenant_id and b.lot_id=l.id and b.warehouse_id=p_warehouse_id
  where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and l.product_id=p_product_id
  and l.status in('saleable','quarantine') and b.on_hand_quantity>0 and(p_after is null or l.id>p_after) order by l.id limit 51)q;
 elsif p_resource='serials' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from(select id,code,lot_id,status,version from inventory.serials
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and warehouse_id=p_warehouse_id
  and product_id=p_product_id and status in('available','quarantine') and(p_after is null or id>p_after) order by id limit 51)q;
 elsif p_resource='accounts' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') into rows from(select id,name,code from finance.accounts
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and account_type='expense' and is_posting and status='active'
  and (currency_code is null or currency_code=(select currency_code from core.legal_entities where tenant_id=p_tenant_id and id=p_legal_entity_id))
  and(p_after is null or id>p_after) order by id limit 51)q;
 else raise exception using errcode='22023',message='RESOURCE_INVALID';end if;
 if jsonb_array_length(rows)>50 then next_id:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'resource',p_resource,'items',rows,'next_cursor',next_id);
end $$;

revoke all on function inventory.disposition_document(text,uuid,uuid,boolean),
 inventory.disposition_normalize(uuid,uuid,uuid,jsonb,jsonb),inventory.disposition_revalidate(text,jsonb)
from public,anon,authenticated;
revoke all on function api.stock_dispositions_page(uuid,uuid,uuid,uuid),
