-- UNAPPLIED: contract49. Stable scoped metrics, never a second posting engine.
create index wave3_dashboard_budget_review on finance.budget_variance_reports
 (tenant_id,legal_entity_id,requested_branch_id,budget_id,generated_at desc,id desc);
create index wave3_dashboard_close_review on finance.close_control_reviews
 (tenant_id,legal_entity_id,branch_id,generated_at desc,id desc);
create function finance.wave3_dashboard_aging(t uuid,e uuid,b uuid,k text,d date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare n int;rows jsonb;begin
 perform core.wave3_require_scope(t,case k when 'AR' then 'finance.receivables.view'
  when 'AP' then 'finance.payments.manage' end,e,b);
 if k is null or k not in('AR','AP') or d is null then
  raise exception using errcode='22023',message='DASHBOARD_AGING_INVALID';end if;
 select count(*) into n from(select id from finance.open_items where tenant_id=t
  and legal_entity_id=e and branch_id=b and kind=k and posting_date<=d limit 10001)q;
 if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 with residuals as materialized(select o.currency_code,o.original_amount,o.due_date,
  (finance.flow_residual(t,o.id,d)->>'amount')::numeric amount from finance.open_items o
  where o.tenant_id=t and o.legal_entity_id=e and o.branch_id=b and o.kind=k and o.posting_date<=d),
 grouped as(select currency_code,case when original_amount<0 then 'credit'
  when due_date>=d then 'current' when d-due_date<=30 then '1–30'
  when d-due_date<=60 then '31–60' when d-due_date<=90 then '61–90' else '90+' end bucket,
  sum(amount)::text amount,count(*)::text item_count from residuals where amount<>0 group by 1,2)
 select coalesce(jsonb_agg(to_jsonb(grouped) order by currency_code,bucket),'[]') into rows from grouped;
 return jsonb_build_object('kind',k,'as_of',d,'item_count',n::text,'buckets',rows);
end $$;
revoke all on function finance.wave3_dashboard_aging(uuid,uuid,uuid,text,date) from public,anon,authenticated;

alter function api.wave3_dashboard(uuid,uuid,uuid) rename to wave3_dashboard_queues;
revoke all on function api.wave3_dashboard_queues(uuid,uuid,uuid) from public,anon,authenticated;
create function api.wave3_dashboard(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare t uuid:=p_tenant_id;e uuid:=p_legal_entity_id;b uuid:=p_branch_id;
 d date:=(statement_timestamp() at time zone 'UTC')::date;result jsonb;metrics jsonb:='[]';
 data jsonb;rows jsonb;kind text;perm text;common jsonb;n int;
begin
 result:=api.wave3_dashboard_queues(t,e,b);
 if not exists(select 1 from core.branches where tenant_id=t and legal_entity_id=e and id=b and status='active')
  or not exists(select 1 from core.legal_entities where tenant_id=t and id=e and status='active') then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 common:=jsonb_build_object('tenant_id',t,'legal_entity_id',e,'branch_id',b,
  'generated_at',statement_timestamp(),'as_of',d);
 if core.has_permission(t,'crm.opportunities.view',e,b) and core.has_permission(t,'crm.leads.view',e,b) then
  perform core.wave3_require_scope(t,'crm.opportunities.view',e,b);
  perform core.wave3_require_scope(t,'crm.leads.view',e,b);
  data:=api.get_crm_pipeline_summary(t,e,b,d);
  metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind','pipeline','basis','dated_pipeline',
   'destination','/crm','data',data));
 end if;
 for kind,perm in select * from(values('AR','finance.receivables.view'),('AP','finance.payments.manage'))x loop
  if core.has_permission(t,perm,e,b) then
   data:=finance.wave3_dashboard_aging(t,e,b,kind,d);
   metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind',lower(kind)||'_aging','basis','dated_open_items',
    'destination',case kind when 'AR' then '/receivables' else '/procurement/payments' end,'data',data));
  end if;
 end loop;
 if core.has_permission(t,'finance.view',e,b) then
  perform core.wave3_require_scope(t,'finance.view',e,b);
  data:=finance.build_branch_cash_controls(t,e,b,d);
  metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind','cash_bank','basis','dated_posted_controls',
   'destination','/finance/bank','data',data->'controls'));
  if core.has_permission(t,'finance.view',e,null) then
  perform core.wave3_require_scope(t,'finance.view',e,null);
  select count(*) into n from(select id from finance.fiscal_periods where tenant_id=t and legal_entity_id=e limit 10001)q;
  if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'state',state,
   'start_date',start_date,'end_date',end_date) order by start_date,id),'[]') into rows
   from finance.fiscal_periods where tenant_id=t and legal_entity_id=e;
  metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind','periods','basis','current_period_state',
   'destination','/finance/periods','data',rows));
  end if;
  select count(*) into n from(select id from procurement.supplier_bills where tenant_id=t and legal_entity_id=e
   and branch_id=b and status='draft' limit 10001)q;
  if core.has_permission(t,'procurement.bills.view',e,b) then
   perform core.wave3_require_scope(t,'procurement.bills.view',e,b);
   if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
   select count(*) into n from procurement.supplier_bills where tenant_id=t and legal_entity_id=e and branch_id=b
    and status='draft' and (coalesce((match_result->>'blocked')::boolean,false)
     or jsonb_array_length(coalesce(match_result->'exceptions','[]'))>0);
   metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind','bill_exceptions','basis','current_match_exceptions',
    'destination','/procurement/bills','data',jsonb_build_object('exception_count',n::text)));
  end if;
 end if;
 if core.has_permission(t,'finance.view',e,null) and core.has_permission(t,'finance.view',e,b) then
  perform core.wave3_require_scope(t,'finance.view',e,null);
  select count(*) into n from(select id from finance.budget_versions where tenant_id=t and legal_entity_id=e
   and (branch_id=b or branch_id is null) limit 10001)q;
  if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'year',v.budget_year,'revision',v.revision,
   'status',v.status,'currency_code',v.currency_code,'review',r.summary) order by v.budget_year,v.root_id,v.revision),'[]')
   into rows from finance.budget_versions v left join lateral(select summary from finance.budget_variance_reports
    where tenant_id=t and legal_entity_id=e and requested_branch_id=b and budget_id=v.id
    order by generated_at desc,id desc limit 1)r on true
   where v.tenant_id=t and v.legal_entity_id=e and(v.branch_id=b or v.branch_id is null);
  metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind','budgets','basis','current_state_and_saved_review',
   'destination','/finance/budgets','data',rows));
  if core.has_permission(t,'finance.controls.reconcile',e,null)
   and core.has_permission(t,'inventory.cost.view',e,null) and core.has_permission(t,'inventory.stock.view',e,null)
   and not exists(select 1 from core.branches br where br.tenant_id=t and br.legal_entity_id=e
    and(not core.has_permission(t,'finance.view',e,br.id) or not core.has_permission(t,'finance.controls.reconcile',e,br.id)
     or not core.has_permission(t,'inventory.cost.view',e,br.id) or not core.has_permission(t,'inventory.stock.view',e,br.id))) then
   perform finance.require_close_review_scope(t,e,b);
   select summary into data from finance.close_control_reviews where tenant_id=t and legal_entity_id=e and branch_id=b
    order by generated_at desc,id desc limit 1;
   metrics:=metrics||jsonb_build_array(common||jsonb_build_object('kind','close_review','basis','latest_saved_review',
    'destination','/finance/close-review','data',data));
  end if;
 end if;
 result:=result||jsonb_build_object('metrics',metrics,'as_of',d);
 if octet_length(result::text)>1048576 then raise exception using errcode='54000',message='DASHBOARD_EVIDENCE_LIMIT';end if;
 return result;
end $$;
revoke all on function api.wave3_dashboard(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave3_dashboard(uuid,uuid,uuid) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED additive candidate: contract 53, metadata only, no payload exposure.
create index wave3_dead_letter_scope on core.outbox_events(tenant_id,command_id,id)
 where status='dead_letter';
create function api.wave3_observability_status(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare n integer;
begin
 perform core.wave3_require_scope(p_tenant_id,'core.roles.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then
  raise exception using errcode='22023',message='OBSERVABILITY_SCOPE_REQUIRED';end if;
 if not exists(select 1 from core.legal_entities where tenant_id=p_tenant_id and id=p_legal_entity_id and status='active')
  or not exists(select 1 from core.branches where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and id=p_branch_id and status='active') then
  raise exception using errcode='42501',message='SOURCE_UNAVAILABLE';end if;
 select count(*) into n from (
  select o.id from core.outbox_events o join core.command_receipts r
    on r.tenant_id=o.tenant_id and r.command_id=o.command_id
  where o.tenant_id=p_tenant_id and o.status='dead_letter'
    and r.legal_entity_id=p_legal_entity_id and r.branch_id=p_branch_id
    and (o.aggregate_type in ('sales_quotation','sales_order','delivery','sales_invoice','customer_receipt','sales_return',
      'purchase_requisition','request_for_quote','purchase_order','goods_receipt','supplier_bill','supplier_payment',
      'purchase_return','manual_journal','stock_count','inventory_transfer','stock_reservation','landed_value_adjustment',
      'landed_extension','stock_disposition','inventory_disposition','inventory_value_adjustment',
      'bank_reconciliation','close_control_review','control_reconciliation_report',
      'financial_statement','tax_summary','budget','fx_valuation',
      'crm_lead','crm_opportunity','crm_activity','customer_allocation','customer_allocation_reversal',
      'supplier_allocation','supplier_allocation_reversal','financial_dimension','financial_statement_report',
      'tax_summary_report','budget_variance_report','cash_flow_mapping','fiscal_period_event','fx_revaluation',
      'inventory_valuation_report','operational_report','report_export','payment_proposal','receipt_controls',
      'receipt_allowance','supplier_bill_controls','product_unit_conversion','reservation_maintenance',
      'stock_count_partition_group','wave3_notification_subscription','wave3_due_scan')
      or o.aggregate_type like 'bank\_%' escape '\')
  limit 10001
 )q;
 if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
   'observed_at',statement_timestamp(),'dead_letter_depth',n::text);
end $$;
revoke all on function api.wave3_observability_status(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave3_observability_status(uuid,uuid,uuid) to authenticated;
notify pgrst,'reload schema';

-- W4-04. Unapplied synthetic development candidate, isolated private payroll.
-- Dependencies: installed employee/calendar/private-HR; candidate resolver,
-- organization, attendance and leave. No plan or role grants.
create schema people_payroll;
revoke all on schema people_payroll from public,anon,authenticated;
insert into core.permissions(code,module,description,privileged) values
 ('people.payroll.view','people','Read scoped synthetic payroll configuration/runs',false),
 ('people.payroll.configure','people','Publish synthetic payroll configuration with MFA',true),
 ('people.payroll.prepare','people','Prepare synthetic frozen payroll with MFA',true),
 ('people.payroll.approve','people','Independently approve exact payroll revision with MFA',true),
 ('people.payroll.post','people','Post synthetic payroll obligations/journal with MFA',true),
 ('people.payroll.reverse','people','Reverse original synthetic payroll effects with MFA',true),
 ('people.payroll.payslip.view','people','Read private scoped synthetic payslips',true),
 ('people.payroll.payslip.self','people','Read own synthetic payslips through an accepted employee link',true),
 ('people.payroll.export','people','Export exact private synthetic payslip revision',true),
 ('people.payroll.settle','people','Record synthetic payroll settlement evidence with MFA',true)
on conflict(code) do nothing;

create table people_payroll.components(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
 name text not null check(length(btrim(name)) between 1 and 160),
 classification text not null check(classification in('earning','deduction','employer_cost')),
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,code),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table people_payroll.rule_versions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,component_id uuid not null,
 version bigint not null check(version between 1 and 9007199254740991),
 start_date date not null,end_date_exclusive date not null,
 currency_code text not null references core.currencies(code),
 basis text not null check(basis in('fixed','hourly','earnings_ratio')),
 proration text not null check(proration in('none','eligible_days','paid_seconds')),
 rounding text not null check(rounding in('half_away','half_even','truncate','floor')),
 precision integer not null check(precision between 0 and 6),
 amount numeric(20,6) not null check(amount>=0),
 ratio_numerator bigint not null check(ratio_numerator between 0 and 9007199254740991),
 ratio_denominator bigint not null check(ratio_denominator between 1 and 9007199254740991),
 cap numeric(20,6) check(cap>=0),expense_account_id uuid,liability_account_id uuid,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 published_by uuid not null references auth.users(id),published_at timestamptz not null default clock_timestamp(),
 check(start_date>='0001-01-01'::date and end_date_exclusive<='9999-12-31'::date
  and end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
 check((basis='fixed' or proration='none') and
  ((basis='earnings_ratio' and amount=0) or (basis<>'earnings_ratio' and ratio_numerator=1 and ratio_denominator=1))),
 check(cap is null or cap=round(cap,precision)),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,component_id,id),
 unique(tenant_id,legal_entity_id,component_id,version),
 foreign key(tenant_id,legal_entity_id,component_id) references people_payroll.components(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,expense_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,liability_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 exclude using gist(component_id extensions.gist_uuid_ops with =,daterange(start_date,end_date_exclusive,'[)') with &&)
);
create index payroll_rules_scope_idx on people_payroll.rule_versions(tenant_id,legal_entity_id,component_id,id);
create index payroll_rules_expense_idx on people_payroll.rule_versions(tenant_id,legal_entity_id,expense_account_id);
create index payroll_rules_liability_idx on people_payroll.rule_versions(tenant_id,legal_entity_id,liability_account_id);
create index payroll_rules_actor_idx on people_payroll.rule_versions(published_by);
create table people_payroll.component_assignments(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 employee_id uuid not null,component_id uuid not null,start_date date not null,end_date_exclusive date not null,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 check(end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
 unique(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,component_id) references people_payroll.components(tenant_id,legal_entity_id,id),
 exclude using gist(employee_id extensions.gist_uuid_ops with =,component_id extensions.gist_uuid_ops with =,
  daterange(start_date,end_date_exclusive,'[)') with &&)
);
create index payroll_assignments_scope_idx on people_payroll.component_assignments(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index payroll_assignments_component_idx on people_payroll.component_assignments(tenant_id,legal_entity_id,component_id);
create index payroll_assignments_actor_idx on people_payroll.component_assignments(recorded_by);
create table people_payroll.settings_versions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 version bigint not null check(version between 1 and 9007199254740991),
 net_account_id uuid not null,reason text not null check(length(btrim(reason)) between 1 and 1000),
 published_by uuid not null references auth.users(id),published_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,version),
 foreign key(tenant_id,legal_entity_id,net_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
create index payroll_settings_account_idx on people_payroll.settings_versions(tenant_id,legal_entity_id,net_account_id);
create index payroll_settings_actor_idx on people_payroll.settings_versions(published_by);
create table people_payroll.runs(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 160),
 start_date date not null,end_date_exclusive date not null,posting_date date not null,
 currency_code text not null references core.currencies(code),
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 status text not null default 'draft' check(status in('draft','prepared','submitted','approved','posted','cancelled','reversed')),
 current_revision_id uuid,approved_revision_id uuid,approved_digest text check(approved_digest ~ '^[a-f0-9]{64}$'),
 prepared_by uuid references auth.users(id),submitted_by uuid references auth.users(id),approved_by uuid references auth.users(id),
 posted_journal_id uuid,reversal_journal_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 check(start_date>='0001-01-01'::date and end_date_exclusive<='9999-12-31'::date
  and end_date_exclusive>start_date and end_date_exclusive-start_date<=366),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,branch_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,posted_journal_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,reversal_journal_id) references finance.journal_entries(tenant_id,id)
);
create index payroll_runs_scope_idx on people_payroll.runs(tenant_id,legal_entity_id,branch_id,id);
create index payroll_runs_creator_idx on people_payroll.runs(created_by);
create index payroll_runs_preparer_idx on people_payroll.runs(prepared_by);
create index payroll_runs_submitter_idx on people_payroll.runs(submitted_by);
create index payroll_runs_approver_idx on people_payroll.runs(approved_by);
create index payroll_runs_journal_idx on people_payroll.runs(tenant_id,posted_journal_id);
create index payroll_runs_reverse_idx on people_payroll.runs(tenant_id,reversal_journal_id);
create table people_payroll.run_employees(
 tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,run_id uuid not null,employee_id uuid not null,
 primary key(tenant_id,legal_entity_id,run_id,employee_id),
 foreign key(tenant_id,legal_entity_id,branch_id,run_id) references people_payroll.runs(tenant_id,legal_entity_id,branch_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id)
);
create index payroll_run_employee_idx on people_payroll.run_employees(tenant_id,legal_entity_id,employee_id);
create table people_payroll.run_revisions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,run_id uuid not null,
 version bigint not null,settings_version_id uuid not null,digest text not null check(digest ~ '^[a-f0-9]{64}$'),
 employee_count integer not null check(employee_count between 1 and 200),
 prepared_by uuid not null references auth.users(id),prepared_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,run_id,id),
 foreign key(tenant_id,legal_entity_id,run_id) references people_payroll.runs(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,settings_version_id) references people_payroll.settings_versions(tenant_id,legal_entity_id,id)
);
