revoke all on function api.reserve_sales_order_stock_without_negative_policy(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
create function api.reserve_sales_order_stock(
  p_tenant_id uuid,
  p_legal_entity_id uuid,
  p_branch_id uuid,
  p_command_id uuid,
  p_idempotency_key uuid,
  p_client_timestamp timestamptz,
  p_payload jsonb,
  p_expected_entity_version bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_command_name constant text := 'inventory.sales_order.reserve';
  v_request_hash text;
  v_replay jsonb;
  v_order_id uuid := (p_payload->>'sales_order_id')::uuid;
  v_order sales.sales_orders%rowtype;
  v_line sales.sales_order_lines%rowtype;
  v_balance inventory.stock_balances%rowtype;
  v_reservation inventory.stock_reservations%rowtype;
  v_item jsonb;
  v_ordinal integer;
  v_requested numeric(20, 6);
  v_remaining numeric(20, 6);
  v_available numeric(20, 6);
  v_allocate numeric(20, 6);
  v_shortfall boolean := false;
  v_before jsonb;
  v_entity jsonb;
  v_request_id uuid := gen_random_uuid();
  v_source_context jsonb := coalesce(p_payload->'source_context', '{}'::jsonb);
  v_to_status text;
  v_policy inventory.negative_stock_policy_versions%rowtype;
  v_basis inventory.negative_stock_cost_bases%rowtype;
  v_val inventory.stock_valuations%rowtype;
  v_tracking text;
  v_has_override boolean := coalesce(p_payload ? 'negative_stock_override',false);
  v_used_override boolean := false;
  v_warnings jsonb := '[]'::jsonb;
begin
  if not v_has_override then
    if (p_payload->'source_context') ? 'negative_stock_override' then
      raise exception using errcode='22023',message='NEGATIVE_STOCK_OVERRIDE_INPUT_INVALID';
    end if;
  end if;
  if v_has_override then
  perform core.wave3_require_scope(p_tenant_id,'inventory.reservations.manage',p_legal_entity_id,p_branch_id);
  perform core.wave3_require_scope(p_tenant_id,'inventory.stock.override',p_legal_entity_id,p_branch_id);
  v_request_hash := core.wave3_request_hash(v_command_name,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
  v_replay := core.wave3_replay(p_tenant_id,v_command_name,p_command_id,p_idempotency_key,v_request_hash);
  if v_replay is not null then return v_replay;end if;
  v_policy := inventory.require_negative_stock_policy(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload->'negative_stock_override');
  v_source_context := v_source_context || jsonb_build_object('negative_stock_override',jsonb_build_object(
    'policy_version',v_policy.version::text,'reason',trim(p_payload#>>'{negative_stock_override,reason}'),'policy_id',v_policy.id,'authorized_by',auth.uid()));
  end if;
  perform core.wave3_require_scope(
    p_tenant_id, 'inventory.reservations.manage', p_legal_entity_id, p_branch_id
  );
  if p_branch_id is null or p_client_timestamp is null
     or jsonb_typeof(p_payload->'lines') <> 'array'
     or jsonb_array_length(p_payload->'lines') not between 1 and 500
     or (p_payload->>'expires_at')::timestamptz <= greatest(clock_timestamp(), p_client_timestamp)
     or jsonb_typeof(v_source_context) <> 'object' then
    raise exception using errcode = '22023', message = 'Stock reservation payload is invalid.';
  end if;
  v_request_hash := core.wave3_request_hash(
    v_command_name, p_command_id, p_tenant_id, p_legal_entity_id,
    p_branch_id, p_payload, p_expected_entity_version
  );
  v_replay := core.wave3_replay(
    p_tenant_id, v_command_name, p_command_id, p_idempotency_key, v_request_hash
  );
  if v_replay is not null then return v_replay; end if;
  select o.* into v_order
  from sales.sales_orders as o
  where o.tenant_id = p_tenant_id and o.legal_entity_id = p_legal_entity_id
    and o.branch_id = p_branch_id and o.id = v_order_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Sales order was not found.';
  end if;
  v_before := sales.order_entity(v_order_id);
  perform core.wave3_assert_expected_version(
    v_order.version, p_expected_entity_version, v_before
  );
  if v_order.status not in ('confirmed', 'partially_reserved', 'reserved') then
    raise exception using errcode = '55000', message = 'SALES_ORDER_NOT_RESERVABLE';
  end if;

  if not exists (
    select 1 from core.warehouses w
    where w.tenant_id = p_tenant_id and w.legal_entity_id = p_legal_entity_id
      and w.branch_id = p_branch_id and w.id = v_order.warehouse_id
      and w.status = 'active'
  ) then
    raise exception using errcode = '55000', message = 'WAREHOUSE_INACTIVE';
  end if;

  -- Deterministic product locks serialize competing reservations without
  -- creating an inventory movement or changing on-hand quantity.
  for v_line in
    select distinct on (l.product_id) l.*
    from jsonb_array_elements(p_payload->'lines') as item
    join sales.sales_order_lines as l
      on l.id = (item->>'sales_order_line_id')::uuid
    where l.tenant_id = p_tenant_id and l.sales_order_id = v_order_id
    order by l.product_id, l.id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        p_tenant_id::text || ':' || v_order.warehouse_id::text || ':' || v_line.product_id::text,
        0
      )
    );
  end loop;

  for v_item, v_ordinal in
    select value, ordinality::integer
    from jsonb_array_elements(p_payload->'lines') with ordinality
  loop
    select l.* into v_line
    from sales.sales_order_lines as l
    where l.tenant_id = p_tenant_id and l.sales_order_id = v_order_id
      and l.id = (v_item->>'sales_order_line_id')::uuid
    for update;
    if not found then
      raise exception using errcode = '22023', message = 'Sales-order line is outside scope.';
    end if;
    if v_line.product_kind <> 'stocked' then
      raise exception using errcode = '22023', message = 'Only stocked products can be reserved.';
    end if;
    if not exists (
      select 1 from inventory.products p
      where p.tenant_id = p_tenant_id and p.legal_entity_id = p_legal_entity_id
        and p.id = v_line.product_id and p.kind = 'stocked' and p.status = 'active'
    ) then
      raise exception using errcode = '55000', message = 'PRODUCT_NOT_RESERVABLE';
    end if;
    v_requested := sales.wave3_decimal_string(
      v_item->'requested_base_quantity', 'Requested base quantity', 6, true, 0, null
    )::numeric(20, 6);
    if v_requested <= 0 then
      raise exception using errcode = '22023', message = 'Requested quantity must be positive.';
    end if;
    select b.* into v_balance
    from inventory.stock_balances as b
    where b.tenant_id = p_tenant_id and b.legal_entity_id = p_legal_entity_id
      and b.branch_id = p_branch_id and b.warehouse_id = v_order.warehouse_id
      and b.product_id = v_line.product_id
    for update;
    v_remaining := greatest(
      v_line.base_ordered_quantity - v_line.cancelled_quantity
        - v_line.allocated_quantity - v_line.delivered_quantity,
      0
    )::numeric(20, 6);
    v_available := case when v_balance.id is null then 0
      else greatest(v_balance.available_quantity, 0) end::numeric(20, 6);
    if v_has_override and least(v_requested,v_remaining)>v_available then
      select tracking_mode into v_tracking from inventory.products where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and id=v_line.product_id;
      if v_tracking<>'none' then raise exception using errcode='55000',message='NEGATIVE_STOCK_TRACKING_REQUIRED';end if;
      v_basis := inventory.capture_negative_stock_basis(p_tenant_id,p_legal_entity_id,p_branch_id,v_order.warehouse_id,v_line.product_id,
        jsonb_build_object('sales_order_id',v_order_id,'sales_order_line_id',v_line.id,'command_id',p_command_id));
      v_available := v_remaining;
    end if;
    v_allocate := least(v_requested, v_remaining, v_available)::numeric(20, 6);
    if v_allocate < v_requested then v_shortfall := true; end if;
    if v_allocate > 0 then
      select r.* into v_reservation
      from inventory.stock_reservations as r
      where r.tenant_id = p_tenant_id and r.warehouse_id = v_order.warehouse_id
        and r.sales_order_line_id = v_line.id and r.status = 'active'
      for update;
      if found then
        update inventory.stock_reservations set
          base_quantity = base_quantity + v_allocate,
          expires_at = greatest(expires_at, (p_payload->>'expires_at')::timestamptz),
          request_id = v_request_id, command_id = p_command_id,
          correlation_id = v_request_id, source_context = v_source_context,
          updated_by = v_actor
        where id = v_reservation.id;
      else
        insert into inventory.stock_reservations (
          id, tenant_id, legal_entity_id, branch_id, warehouse_id, product_id,
          sales_order_id, sales_order_line_id, base_quantity, status,
          expires_at, request_id, command_id, correlation_id, source_context,
          created_by, updated_by
        ) values (
          core.wave2_derived_uuid(p_command_id, v_ordinal),
          p_tenant_id, p_legal_entity_id, p_branch_id, v_order.warehouse_id,
          v_line.product_id, v_order_id, v_line.id, v_allocate, 'active',
          (p_payload->>'expires_at')::timestamptz,
          v_request_id, p_command_id, v_request_id, v_source_context,
          v_actor, v_actor
        );
      end if;
      if v_balance.allocated_quantity+v_allocate>v_balance.on_hand_quantity then
        select * into v_val from inventory.stock_valuations where tenant_id=p_tenant_id and stock_balance_id=v_balance.id for update;
        perform inventory.authorize_negative_stock_projection(v_balance,v_val,v_policy.id,'reserve',v_order_id,v_line.id,p_command_id,v_request_id,
          v_allocate,trim(p_payload#>>'{negative_stock_override,reason}'),v_balance.on_hand_quantity,v_balance.allocated_quantity+v_allocate,v_val.carrying_value);
        v_used_override := true;
      end if;
      update inventory.stock_balances set
        allocated_quantity = allocated_quantity + v_allocate,
        updated_by = v_actor, source_context = v_source_context
      where id = v_balance.id;
      update sales.sales_order_lines set
        allocated_quantity = allocated_quantity + v_allocate,
        request_id = v_request_id, command_id = p_command_id,
        correlation_id = v_request_id, source_context = v_source_context,
        updated_by = v_actor
      where id = v_line.id;
    end if;
  end loop;
  if exists (
    select 1 from sales.sales_order_lines as l
    where l.tenant_id = p_tenant_id and l.sales_order_id = v_order_id
      and l.product_kind = 'stocked'
      and l.base_ordered_quantity - l.cancelled_quantity - l.allocated_quantity - l.delivered_quantity > 0
  ) then
    v_to_status := 'partially_reserved';
  else
    v_to_status := 'reserved';
  end if;
  if v_shortfall then
    v_warnings := jsonb_build_array('PARTIAL_STOCK_RESERVATION');
  end if;
  if v_used_override then v_warnings := v_warnings || jsonb_build_array('NEGATIVE_STOCK_OVERRIDDEN'); end if;
  update sales.sales_orders set
    status = v_to_status, request_id = v_request_id, command_id = p_command_id,
    correlation_id = v_request_id, source_context = v_source_context,
    client_timestamp = p_client_timestamp, updated_by = v_actor
  where id = v_order_id;
  v_entity := sales.order_entity(v_order_id);
  return core.wave3_finish_command(
    p_tenant_id, v_command_name, p_command_id, 'sales_order', v_order_id,
    p_idempotency_key, v_request_hash, v_before, v_entity,
    p_legal_entity_id, p_branch_id, v_source_context,
    jsonb_build_object(
      'from_status', case when v_order.status=v_to_status then null else v_order.status end, 'to_status', v_to_status,
      'owner_id', v_order.salesperson_id
    ),
    jsonb_build_array(jsonb_build_object(
      'topic', v_command_name,
      'payload', jsonb_build_object('status', v_to_status)
    )), v_warnings, v_request_id, v_request_id
  );
end;
$$;
alter function sales.flow_post_stock(text,jsonb,uuid,uuid) rename to flow_post_stock_without_negative_policy;
revoke all on function sales.flow_post_stock_without_negative_policy(text,jsonb,uuid,uuid) from public,anon,authenticated;
create function sales.flow_post_stock(p_kind text,p_doc jsonb,p_request uuid,p_command uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_t uuid:=(p_doc->>'tenant_id')::uuid;v_e uuid:=(p_doc->>'legal_entity_id')::uuid;
 v_b uuid:=(p_doc->>'branch_id')::uuid;v_date date:=(p_doc->>'document_date')::date;v_id uuid:=(p_doc->>'id')::uuid;
 v_movement uuid;v_line jsonb;v_snapshot jsonb;v_product inventory.products%rowtype;v_order sales.sales_orders%rowtype;
 v_ol sales.sales_order_lines%rowtype;v_balance inventory.stock_balances%rowtype;v_value inventory.stock_valuations%rowtype;
 v_res inventory.stock_reservations%rowtype;v_original inventory.stock_movement_lines%rowtype;
 v_lot inventory.lots%rowtype;v_lb inventory.lot_balances%rowtype;v_serial inventory.serials%rowtype;
 v_serial_ids uuid[];v_serial_id uuid;v_warehouse uuid;v_lot_id uuid;v_q numeric;v_cost numeric;v_prior numeric;
 v_negative_policy inventory.negative_stock_policy_versions%rowtype;v_basis inventory.negative_stock_cost_bases%rowtype;
 v_deficit_quantity numeric;v_provisional numeric;v_override bigint;v_mline uuid;v_def inventory.negative_stock_deficits%rowtype;
 v_inventory uuid;v_cogs uuid;v_jlines jsonb:='[]';v_sign integer:=case when p_kind='delivery' then -1 else 1 end;
begin
 if p_kind='delivery' then perform pg_advisory_xact_lock(hashtextextended('negative-policy:'||v_t::text||':'||v_e::text,0));end if;
 -- Lock stock products with exactly the same advisory identity as reservations.
 for v_warehouse,v_serial_id in select distinct
 case when p_kind='delivery' then (p_doc->>'warehouse_id')::uuid else d.warehouse_id end, (x->>'product_id')::uuid
 from jsonb_array_elements(p_doc->'lines') x
 left join sales.delivery_lines dl on dl.tenant_id=v_t and dl.id=(x->>'delivery_line_id')::uuid
 left join sales.deliveries d on d.tenant_id=v_t and d.id=dl.document_id
 where x#>>'{snapshot,product_kind}'='stocked' order by 1,2 loop
 perform pg_advisory_xact_lock(hashtextextended(v_t::text||':'||v_warehouse::text||':'||v_serial_id::text,0));end loop;
 for v_line in select value from jsonb_array_elements(p_doc->'lines') loop
 v_snapshot:=v_line->'snapshot';v_q:=(v_line->>'base_quantity')::numeric;v_mline:=gen_random_uuid();v_deficit_quantity:=0;v_provisional:=0;
 if v_snapshot->>'product_kind'<>'stocked' then
 if p_kind='delivery' then update sales.sales_order_lines set delivered_quantity=delivered_quantity+v_q,updated_by=auth.uid()
 where tenant_id=v_t and id=(v_line->>'sales_order_line_id')::uuid;end if;continue;end if;
 if p_kind='sales_return' and v_snapshot->>'disposition'='no_restock' then continue;end if;
 select * into v_product from inventory.products where tenant_id=v_t and legal_entity_id=v_e and id=(v_line->>'product_id')::uuid;
 v_original:=null;v_lot:=null;v_lb:=null;v_def:=null;
 if p_kind='sales_return' then
 select ml.* into v_original from inventory.stock_movement_lines ml join inventory.stock_movements m on m.id=ml.stock_movement_id
 where ml.tenant_id=v_t and ml.source_line_id=(v_line->>'delivery_line_id')::uuid and m.movement_kind='delivery';
 if not found then raise exception using errcode='22023',message='RETURN_STOCK_SOURCE_REQUIRED';end if;
 v_warehouse:=v_original.warehouse_id;v_lot_id:=v_original.lot_id;
 select coalesce(sum(base_quantity),0) into v_prior from inventory.stock_movement_lines where tenant_id=v_t and original_movement_line_id=v_original.id;
 if v_prior+v_q> -v_original.base_quantity then raise exception using errcode='22023',message='SOURCE_QUANTITY_EXCEEDED';end if;
 v_cost:=round((-v_original.base_value)*(v_prior+v_q)/(-v_original.base_quantity),6)-round((-v_original.base_value)*v_prior/(-v_original.base_quantity),6);
 else
 v_warehouse:=(p_doc->>'warehouse_id')::uuid;v_lot_id:=(v_snapshot#>>'{tracking,lot_id}')::uuid;
 end if;
 if not exists(select 1 from core.warehouses w where w.tenant_id=v_t and w.legal_entity_id=v_e and w.branch_id=v_b and w.id=v_warehouse and w.status='active') then
 raise exception using errcode='22023',message='WAREHOUSE_INACTIVE';end if;
 if v_movement is not null and exists(select 1 from inventory.stock_movements where id=v_movement and warehouse_id<>v_warehouse) then
 raise exception using errcode='22023',message='RETURN_SINGLE_WAREHOUSE_REQUIRED';end if;
 select * into v_balance from inventory.stock_balances where tenant_id=v_t and legal_entity_id=v_e and branch_id=v_b and warehouse_id=v_warehouse and product_id=v_product.id for update;
 if not found then raise exception using errcode='55000',message='STOCK_BALANCE_UNAVAILABLE';end if;
 select * into v_value from inventory.stock_valuations where tenant_id=v_t and stock_balance_id=v_balance.id for update;
 if not found then raise exception using errcode='55000',message='INVENTORY_COST_UNAVAILABLE';end if;
 if v_product.tracking_mode='lot' then
 select * into v_lot from inventory.lots where tenant_id=v_t and legal_entity_id=v_e and product_id=v_product.id and id=v_lot_id and status='saleable';
 if not found or (v_lot.expiry_date is not null and v_lot.expiry_date<greatest(v_date,(clock_timestamp() at time zone 'UTC')::date)) then
 raise exception using errcode='22023',message='LOT_NOT_SALEABLE';end if;
 select * into v_lb from inventory.lot_balances where tenant_id=v_t and warehouse_id=v_warehouse and product_id=v_product.id and lot_id=v_lot_id for update;
 if not found or (p_kind='delivery' and v_lb.on_hand_quantity<v_q) then raise exception using errcode='22023',message='LOT_QUANTITY_UNAVAILABLE';end if;
 elsif v_lot_id is not null and v_product.tracking_mode='none' then raise exception using errcode='22023',message='TRACKING_INPUT_INVALID';end if;
 select coalesce(array_agg(x::uuid order by x),'{}'::uuid[]) into v_serial_ids
 from jsonb_array_elements_text(coalesce(v_snapshot#>'{tracking,serial_ids}','[]')) x;
 if v_product.tracking_mode='serial' then
 if v_q<>trunc(v_q) or cardinality(v_serial_ids)<>v_q or cardinality(v_serial_ids)<>(select count(distinct x) from unnest(v_serial_ids) x) then
 raise exception using errcode='22023',message='SERIAL_CONFLICT';end if;
 foreach v_serial_id in array v_serial_ids loop
 select * into v_serial from inventory.serials where tenant_id=v_t and legal_entity_id=v_e and branch_id=v_b and product_id=v_product.id and id=v_serial_id for update;
 if not found or v_serial.warehouse_id<>v_warehouse or (p_kind='delivery' and v_serial.status<>'available')
 or (p_kind='sales_return' and (v_serial.status<>'issued' or v_serial.last_delivery_line_id<>(v_line->>'delivery_line_id')::uuid
 or not v_serial.id=any(v_original.serial_ids))) then raise exception using errcode='22023',message='SERIAL_CONFLICT';end if;
 update inventory.serials set status=case when p_kind='delivery' then 'issued' else 'available' end,
 last_delivery_line_id=case when p_kind='delivery' then (v_line->>'id')::uuid else last_delivery_line_id end,updated_by=auth.uid() where id=v_serial_id;
 end loop;
 elsif cardinality(v_serial_ids)>0 then raise exception using errcode='22023',message='TRACKING_INPUT_INVALID';end if;
 if p_kind='delivery' then
 select * into v_ol from sales.sales_order_lines where tenant_id=v_t and id=(v_line->>'sales_order_line_id')::uuid for update;
 select * into v_res from inventory.stock_reservations where tenant_id=v_t and sales_order_line_id=v_ol.id and warehouse_id=v_warehouse and status='active' for update;
 if not found or v_res.expires_at<=clock_timestamp() or v_res.base_quantity<v_q or v_ol.allocated_quantity<v_q then
 raise exception using errcode='55000',message='RESERVATION_INSUFFICIENT';end if;
 if v_balance.allocated_quantity<v_q then raise exception using errcode='55000',message='INSUFFICIENT_STOCK';end if;
 if v_product.tracking_mode='none' and v_balance.on_hand_quantity>0 then
  v_basis:=inventory.capture_negative_stock_basis(v_t,v_e,v_b,v_warehouse,v_product.id,jsonb_build_object('delivery_id',v_id,'delivery_line_id',v_line->>'id','command_id',p_command));
 end if;
 if v_balance.on_hand_quantity<v_q then
  if v_product.tracking_mode<>'none' then raise exception using errcode='55000',message='NEGATIVE_STOCK_TRACKING_REQUIRED';end if;
  v_negative_policy:=inventory.require_negative_stock_policy(v_t,v_e,v_b,v_res.source_context->'negative_stock_override');
  if not exists(select 1 from inventory.negative_stock_overrides a where a.tenant_id=v_t and a.balance_id=v_balance.id and a.effect='reserve'
   and a.source_id=(p_doc->>'sales_order_id')::uuid and a.source_line_id=v_ol.id and a.command_id=v_res.command_id
   and a.policy_id=v_negative_policy.id and a.created_by::text=v_res.source_context#>>'{negative_stock_override,authorized_by}'
   and a.reason=trim(v_res.source_context#>>'{negative_stock_override,reason}')) then
   raise exception using errcode='55000',message='NEGATIVE_STOCK_RESERVATION_AUTHORIZATION_REQUIRED';end if;
  v_basis:=inventory.capture_negative_stock_basis(v_t,v_e,v_b,v_warehouse,v_product.id,jsonb_build_object('delivery_id',v_id,'delivery_line_id',v_line->>'id','command_id',p_command));
  v_deficit_quantity:=v_q-greatest(v_balance.on_hand_quantity,0);
  v_provisional:=round(v_basis.carrying_value*v_deficit_quantity/v_basis.positive_quantity,6);
  v_cost:=case when v_balance.on_hand_quantity>0 then v_value.carrying_value else 0 end+v_provisional;
  v_override:=inventory.authorize_negative_stock_projection(v_balance,v_value,v_negative_policy.id,'issue',v_id,(v_line->>'id')::uuid,p_command,p_request,
   v_deficit_quantity,v_res.source_context#>>'{negative_stock_override,reason}',v_balance.on_hand_quantity-v_q,v_balance.allocated_quantity-v_q,v_value.carrying_value-v_cost);
  insert into inventory.negative_stock_deficits(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,issue_movement_line_id,policy_id,basis_id,override_id,
   quantity,provisional_value,inventory_account_id,cogs_account_id,posting_date,command_id,created_by)
  values(v_t,v_e,v_b,v_warehouse,v_product.id,v_mline,v_negative_policy.id,v_basis.id,v_override,v_deficit_quantity,v_provisional,
   v_product.inventory_account_id,v_product.cogs_account_id,v_date,p_command,auth.uid());
 else
  v_cost:=case when v_q=v_balance.on_hand_quantity then v_value.carrying_value else round(v_value.carrying_value*v_q/v_balance.on_hand_quantity,6) end;
 end if;
 if v_res.base_quantity=v_q then update inventory.stock_reservations set status='fulfilled',released_at=clock_timestamp(),release_reason='Delivery posted',updated_by=auth.uid() where id=v_res.id;
 else update inventory.stock_reservations set base_quantity=base_quantity-v_q,updated_by=auth.uid() where id=v_res.id;end if;
 update inventory.stock_balances set on_hand_quantity=on_hand_quantity-v_q,allocated_quantity=allocated_quantity-v_q,updated_by=auth.uid() where id=v_balance.id;
 update sales.sales_order_lines set allocated_quantity=allocated_quantity-v_q,delivered_quantity=delivered_quantity+v_q,updated_by=auth.uid() where id=v_ol.id;
 else
  select * into v_def from inventory.negative_stock_deficits where tenant_id=v_t and issue_movement_line_id=v_original.id;
  if found then
   v_cost:=inventory.negative_stock_return_cost(v_original,v_mline,v_q,v_date,p_command,p_request);
   perform inventory.authorize_negative_stock_projection(v_balance,v_value,v_def.policy_id,'customer_return',v_id,(v_line->>'id')::uuid,p_command,p_request,
    v_q,'Source-linked customer return',v_balance.on_hand_quantity+v_q,v_balance.allocated_quantity,v_value.carrying_value+v_cost);
  end if;
  update inventory.stock_balances set on_hand_quantity=on_hand_quantity+v_q,updated_by=auth.uid() where id=v_balance.id;end if;
 update inventory.stock_valuations set carrying_value=carrying_value+v_sign*v_cost,updated_by=auth.uid() where id=v_value.id;
 if v_lb.id is not null then update inventory.lot_balances set on_hand_quantity=on_hand_quantity+v_sign*v_q,updated_by=auth.uid() where id=v_lb.id;end if;
 if v_movement is null then
 v_movement:=gen_random_uuid();
 insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
 values(v_movement,v_t,v_e,v_b,p_kind,v_id,v_warehouse,v_date,p_kind,p_request,p_command,p_request,auth.uid());end if;
 insert into inventory.stock_movement_lines(id,tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,
 source_line_id,original_movement_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
 values(v_mline,v_t,v_e,v_b,v_movement,v_warehouse,v_product.id,(v_line->>'id')::uuid,v_original.id,v_sign*v_q,v_sign*v_cost,v_lot_id,v_serial_ids,v_date,auth.uid());
 if v_cost>0 then
 v_inventory:=v_product.inventory_account_id;
 v_cogs:=v_product.cogs_account_id;
 if p_kind='sales_return' then
 if v_def.id is not null then v_inventory:=v_def.inventory_account_id;v_cogs:=v_def.cogs_account_id;
 else
 select jl.account_id into v_inventory from finance.journal_lines jl join finance.journal_entries j on j.id=jl.journal_entry_id
 join finance.accounts a on a.id=jl.account_id where jl.tenant_id=v_t and jl.source_line_id=v_original.source_line_id
 and j.source_type='delivery.stock' and a.account_type='asset';
 select jl.account_id into v_cogs from finance.journal_lines jl join finance.journal_entries j on j.id=jl.journal_entry_id
 join finance.accounts a on a.id=jl.account_id where jl.tenant_id=v_t and jl.source_line_id=v_original.source_line_id
 and j.source_type='delivery.stock' and a.account_type='expense';
 end if;end if;
 perform finance.flow_account(v_t,v_e,v_inventory,'asset',p_doc->>'base_currency_code');
 perform finance.flow_account(v_t,v_e,v_cogs,'expense',p_doc->>'base_currency_code');
 v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_inventory,v_sign*v_cost,v_sign*v_cost,(v_line->>'id')::uuid),
 finance.flow_jline(v_cogs,-v_sign*v_cost,-v_sign*v_cost,(v_line->>'id')::uuid));end if;
 end loop;
 if p_kind='delivery' then
 update sales.sales_orders o set status=case when not exists(select 1 from sales.sales_order_lines l where l.tenant_id=v_t and l.sales_order_id=o.id
 and l.delivered_quantity+l.cancelled_quantity<l.base_ordered_quantity) then 'fulfilled'
 when exists(select 1 from sales.sales_order_lines l where l.tenant_id=v_t and l.sales_order_id=o.id and l.product_kind='stocked'
 and l.allocated_quantity+l.delivered_quantity+l.cancelled_quantity<l.base_ordered_quantity) then 'partially_reserved' else 'reserved' end,
 updated_by=auth.uid(),request_id=p_request,command_id=p_command,correlation_id=p_request
 where o.tenant_id=v_t and o.id=(p_doc->>'sales_order_id')::uuid;end if;
 return jsonb_build_object('movement_id',v_movement,'journal_lines',v_jlines);end $$;
-- Trigger bindings resolve by OID. Reattach it to the additive dispatcher;
-- the renamed original trigger helper retains its byte-identical body.
alter function inventory.record_receipt_provenance() rename to record_receipt_provenance_without_negative_policy;
create function inventory.record_receipt_provenance() returns trigger language plpgsql security definer set search_path='' as $$
declare m inventory.stock_movements%rowtype; related uuid; sid uuid; ids uuid[]; q numeric; prior numeric; available numeric;
 remaining numeric; take numeric; eid bigint; origin uuid; pos record; entry record; v_source_type text; steps integer:=0;
begin
 if inventory.negative_stock_provenance(new) then return new;end if;
 if new.base_quantity=0 then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':'||new.warehouse_id::text||':'||new.product_id::text,0));
 select * into strict m from inventory.stock_movements where tenant_id=new.tenant_id and id=new.stock_movement_id;
 related:=new.original_movement_line_id;
 if m.source_type in('transfer.receive','transfer.reverse.receipt','transfer.reverse.issue') then
  v_source_type:=case when m.source_type='transfer.receive' then 'transfer.dispatch'
   when m.source_type='transfer.reverse.issue' then 'transfer.receive'
   when exists(select 1 from inventory.stock_movements x where x.tenant_id=new.tenant_id and x.source_id=m.source_id and x.source_type='transfer.reverse.issue') then 'transfer.reverse.issue'
   else 'transfer.dispatch' end;
  select l.id into related from inventory.stock_movement_lines l join inventory.stock_movements x on x.id=l.stock_movement_id
   where x.tenant_id=new.tenant_id and x.source_id=m.source_id and x.source_type=v_source_type and l.source_line_id=new.source_line_id;
  if related is null then raise exception using errcode='55000',message='PROVENANCE_TRANSFER_SOURCE_MISSING';end if;
 end if;
 ids:=case when cardinality(new.serial_ids)>0 then new.serial_ids else array[null::uuid] end;
 if cardinality(new.serial_ids)>0 and abs(new.base_quantity)<>cardinality(new.serial_ids) then raise exception using errcode='55000',message='PROVENANCE_SERIAL_QUANTITY_MISMATCH';end if;
 foreach sid in array ids loop
  q:=case when sid is null then new.base_quantity else sign(new.base_quantity) end;
  if sid is not null and q>0 and m.source_type='stock_count' then
   -- A governed recount restores the same missing serial, not an invented receipt.
   select e.movement_line_id into related from inventory.receipt_provenance_entries e
    join inventory.stock_movement_lines ml on ml.id=e.movement_line_id join inventory.stock_movements sm on sm.id=ml.stock_movement_id
    where e.tenant_id=new.tenant_id and e.serial_id=sid and e.warehouse_id=new.warehouse_id and e.quantity<0 and sm.source_type='stock_count'
    and not exists(select 1 from inventory.receipt_provenance_entries r where r.restores_entry_id=e.id) order by e.id desc limit 1;
  end if;
  -- Transfer validates serial disposition after its ledger leg; preserve that public error.
  if sid is not null and m.source_type='transfer.dispatch' and not exists(select 1 from inventory.serials s
   where s.tenant_id=new.tenant_id and s.id=sid and s.warehouse_id=new.warehouse_id and s.status='available') then
   raise exception using errcode='55000',message='TRANSFER_SERIAL_UNAVAILABLE';end if;
  if not exists(select 1 from inventory.receipt_provenance_pools p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id
   and p.lot_id is not distinct from new.lot_id and p.serial_id is not distinct from sid) then
   if sid is not null then prior:=case when q<0 then 1 else 0 end;
   elsif new.lot_id is not null then
    select on_hand_quantity-q into prior from inventory.lot_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and lot_id=new.lot_id;
   else
    select on_hand_quantity-q into prior from inventory.stock_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and product_id=new.product_id;
    -- Untracked pool excludes independently tracked pools if legacy synthetic data mixed tracking modes.
    prior:=prior-coalesce((select sum(quantity) from inventory.receipt_provenance_positions p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id and (p.lot_id is not null or p.serial_id is not null)),0);
   end if;
   if prior is null or prior<0 then raise exception using errcode='55000',message='PROVENANCE_BASELINE_INVALID';end if;
   insert into inventory.receipt_provenance_pools(tenant_id,warehouse_id,product_id,lot_id,serial_id,baseline_quantity)
    values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,prior);
   if prior>0 then insert into inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,quantity)
    values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,prior);end if;
  end if;
  remaining:=abs(q);
  if sid is not null then
   select coalesce(sum(p.quantity),0)+q into available from inventory.receipt_provenance_positions p
    where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id and p.serial_id=sid;
   if available not in(0,1) then raise exception using errcode='55000',message='PROVENANCE_SERIAL_QUANTITY_MISMATCH';end if;
  end if;
  if sid is null then
   select coalesce(sum(p.quantity),0)+q into available from inventory.receipt_provenance_positions p
    where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id
    and p.lot_id is not distinct from new.lot_id and p.serial_id is null;
   if new.lot_id is not null then
    select on_hand_quantity into prior from inventory.lot_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and lot_id=new.lot_id;
   else
    select on_hand_quantity-coalesce((select sum(p.quantity) from inventory.receipt_provenance_positions p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id and (p.lot_id is not null or p.serial_id is not null)),0)
     into prior from inventory.stock_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and product_id=new.product_id;
   end if;
   if available is distinct from prior then raise exception using errcode='55000',message='PROVENANCE_STOCK_MISMATCH';end if;
  end if;
  if q<0 then
   for pos in select * from inventory.receipt_provenance_positions p where p.tenant_id=new.tenant_id and p.warehouse_id=new.warehouse_id and p.product_id=new.product_id
    and p.lot_id is not distinct from new.lot_id and p.serial_id is not distinct from sid and p.quantity>0
    order by case when related is not null and (p.origin_line_id=related or p.entry_id in(select e.id from inventory.receipt_provenance_entries e where e.movement_line_id=related)) then 0 else 1 end,p.id for update loop
    take:=least(remaining,pos.quantity);
    steps:=steps+1;if steps>1000 then raise exception using errcode='54000',message='PROVENANCE_MOVEMENT_LIMIT';end if;
    insert into inventory.receipt_provenance_entries(tenant_id,legal_entity_id,branch_id,movement_line_id,origin_line_id,warehouse_id,product_id,lot_id,serial_id,quantity)
     values(new.tenant_id,new.legal_entity_id,new.branch_id,new.id,pos.origin_line_id,new.warehouse_id,new.product_id,new.lot_id,sid,-take);
    update inventory.receipt_provenance_positions set quantity=quantity-take where id=pos.id;
    remaining:=remaining-take;exit when remaining=0;
   end loop;
   if remaining<>0 then raise exception using errcode='55000',message='PROVENANCE_STOCK_MISMATCH';end if;
  else
   -- Returns and transfer receipts restore the exact recorded negative attribution.
   if related is not null then
    for entry in select e.*, -e.quantity-coalesce((select sum(r.quantity) from inventory.receipt_provenance_entries r where r.restores_entry_id=e.id),0) restorable
     from inventory.receipt_provenance_entries e where e.tenant_id=new.tenant_id and e.movement_line_id=related and e.quantity<0 and e.serial_id is not distinct from sid order by e.id loop
     take:=least(remaining,entry.restorable);if take<=0 then continue;end if;
     steps:=steps+1;if steps>1000 then raise exception using errcode='54000',message='PROVENANCE_MOVEMENT_LIMIT';end if;
     insert into inventory.receipt_provenance_entries(tenant_id,legal_entity_id,branch_id,movement_line_id,origin_line_id,restores_entry_id,warehouse_id,product_id,lot_id,serial_id,quantity)
      values(new.tenant_id,new.legal_entity_id,new.branch_id,new.id,entry.origin_line_id,entry.id,new.warehouse_id,new.product_id,new.lot_id,sid,take) returning id into eid;
     insert into inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,origin_line_id,entry_id,quantity)
      values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,entry.origin_line_id,eid,take);
     remaining:=remaining-take;exit when remaining=0;
    end loop;
    if remaining<>0 and exists(select 1 from inventory.receipt_provenance_entries e where e.tenant_id=new.tenant_id and e.movement_line_id=related) then
     raise exception using errcode='55000',message='PROVENANCE_RESTORE_EXCEEDS_SOURCE';end if;
   end if;
   if remaining>0 then
    origin:=case when m.source_type='goods_receipt' then new.id end;
    insert into inventory.receipt_provenance_entries(tenant_id,legal_entity_id,branch_id,movement_line_id,origin_line_id,warehouse_id,product_id,lot_id,serial_id,quantity)
     values(new.tenant_id,new.legal_entity_id,new.branch_id,new.id,origin,new.warehouse_id,new.product_id,new.lot_id,sid,remaining) returning id into eid;
    insert into inventory.receipt_provenance_positions(tenant_id,warehouse_id,product_id,lot_id,serial_id,origin_line_id,entry_id,quantity)
     values(new.tenant_id,new.warehouse_id,new.product_id,new.lot_id,sid,origin,eid,remaining);
   end if;
  end if;
 end loop;
 -- All legacy projection changes precede the movement insert. Capture only the
 -- aligned final positive quantity/value after normal provenance succeeds.
 if new.lot_id is null and cardinality(new.serial_ids)=0
  and exists(select 1 from inventory.products p where p.tenant_id=new.tenant_id and p.id=new.product_id and p.tracking_mode='none')
  and exists(select 1 from inventory.stock_balances b join inventory.stock_valuations v on v.tenant_id=b.tenant_id and v.stock_balance_id=b.id
   where b.tenant_id=new.tenant_id and b.warehouse_id=new.warehouse_id and b.product_id=new.product_id and b.on_hand_quantity>0 and v.carrying_value>=0) then
  perform inventory.capture_negative_stock_basis(new.tenant_id,new.legal_entity_id,new.branch_id,new.warehouse_id,new.product_id,jsonb_build_object('movement_line_id',new.id,'snapshot_stage','after_aligned_movement'));
 end if;
 return new;
end $$;
drop trigger receipt_provenance on inventory.stock_movement_lines;
create trigger receipt_provenance after insert on inventory.stock_movement_lines for each row execute function inventory.record_receipt_provenance();
-- Take policy before the original source/order locks, as reservation does.
alter function sales.flow_post(text,uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) rename to flow_post_without_negative_policy;
create function sales.flow_post(p_kind text,p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$begin
 if p_kind='delivery' then perform pg_advisory_xact_lock(hashtextextended('negative-policy:'||p_tenant_id::text||':'||p_legal_entity_id::text,0));end if;
 return sales.flow_post_without_negative_policy(p_kind,p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version);
end $$;
-- END GENERATED ADDITIVE SUPERSESSIONS.






create function inventory.guard_negative_stock_operation() returns trigger language plpgsql security definer set search_path='' as $$
declare m inventory.stock_movements%rowtype;bal inventory.stock_balances%rowtype;begin
 select * into m from inventory.stock_movements where tenant_id=new.tenant_id and id=new.stock_movement_id;
 select * into bal from inventory.stock_balances where tenant_id=new.tenant_id and warehouse_id=new.warehouse_id and product_id=new.product_id;
 if m.source_type not in('delivery','goods_receipt','sales_return') and (
  bal.on_hand_quantity<0 or bal.on_hand_quantity-new.base_quantity<0 or bal.on_hand_quantity-bal.allocated_quantity<0
  or bal.on_hand_quantity-new.base_quantity-bal.allocated_quantity<0
  or exists(select 1 from inventory.negative_stock_deficits x where x.tenant_id=new.tenant_id and x.warehouse_id=new.warehouse_id and x.product_id=new.product_id
   and inventory.negative_stock_open_quantity(x.tenant_id,x.id)>0)) then
  raise exception using errcode='55000',message='NEGATIVE_STOCK_OPERATION_REQUIRES_REVIEW';end if;
 if m.source_type='sales_return' and exists(select 1 from inventory.negative_stock_deficits x where x.tenant_id=new.tenant_id and x.warehouse_id=new.warehouse_id
  and x.product_id=new.product_id and inventory.negative_stock_open_quantity(x.tenant_id,x.id)>0)
  and not exists(select 1 from inventory.negative_stock_return_allocations a where a.tenant_id=new.tenant_id and a.return_movement_line_id=new.id) then
  raise exception using errcode='55000',message='NEGATIVE_STOCK_RETURN_REQUIRES_CORRECTION';end if;
 return new;
end $$;
create trigger negative_stock_operation_guard before insert on inventory.stock_movement_lines for each row execute function inventory.guard_negative_stock_operation();

alter function api.upsert_stock_count(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) rename to upsert_stock_count_without_negative_policy;
create function api.upsert_stock_count(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.adjustments.post',p_legal_entity_id,p_branch_id);
 -- Delegate saved retries to the unchanged routine so it checks current cost
 -- permission and the complete request hash before returning the receipt.
 if exists(select 1 from core.command_receipts r where r.actor_id=auth.uid() and r.idempotency_key=p_idempotency_key and r.response is not null) then
  return api.upsert_stock_count_without_negative_policy(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version);
 end if;
 if exists(select 1 from inventory.stock_balances bal join jsonb_array_elements(p_payload->'lines')x on bal.product_id=(x->>'product_id')::uuid
  where bal.tenant_id=p_tenant_id and bal.legal_entity_id=p_legal_entity_id and bal.branch_id=p_branch_id and bal.warehouse_id=(p_payload->>'warehouse_id')::uuid
  and (bal.on_hand_quantity<0 or bal.allocated_quantity>bal.on_hand_quantity
   or exists(select 1 from inventory.negative_stock_deficits d where d.tenant_id=bal.tenant_id and d.warehouse_id=bal.warehouse_id and d.product_id=bal.product_id
    and inventory.negative_stock_open_quantity(d.tenant_id,d.id)>0))) then
  raise exception using errcode='55000',message='NEGATIVE_STOCK_OPERATION_REQUIRES_REVIEW';end if;
 return api.upsert_stock_count_without_negative_policy(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version);
end $$;
alter function api.transfer_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) rename to transfer_stock_without_negative_policy;
create function api.transfer_stock(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.transfers.post',p_legal_entity_id,p_branch_id);
 -- The original routine rechecks both affected branch scopes and the hash.
 if exists(select 1 from core.command_receipts r where r.actor_id=auth.uid() and r.idempotency_key=p_idempotency_key and r.response is not null) then
  return api.transfer_stock_without_negative_policy(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version);
 end if;
 if exists(select 1 from inventory.stock_balances bal join jsonb_array_elements(coalesce(p_payload->'lines','[]'))x on bal.product_id=(x->>'product_id')::uuid
  where bal.tenant_id=p_tenant_id and bal.legal_entity_id=p_legal_entity_id and bal.warehouse_id in((p_payload->>'source_warehouse_id')::uuid,(p_payload->>'destination_warehouse_id')::uuid)
  and (bal.on_hand_quantity<0 or bal.allocated_quantity>bal.on_hand_quantity
   or exists(select 1 from inventory.negative_stock_deficits d where d.tenant_id=bal.tenant_id and d.warehouse_id=bal.warehouse_id and d.product_id=bal.product_id
    and inventory.negative_stock_open_quantity(d.tenant_id,d.id)>0))) then
  raise exception using errcode='55000',message='NEGATIVE_STOCK_OPERATION_REQUIRES_REVIEW';end if;
 return api.transfer_stock_without_negative_policy(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version);
end $$;

alter function api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) rename to reverse_goods_receipt_without_negative_policy;
create function api.reverse_goods_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 if exists(select 1 from procurement.goods_receipts r join inventory.stock_movement_lines ml on ml.stock_movement_id=r.stock_movement_id
  join inventory.negative_stock_covers c on c.tenant_id=ml.tenant_id and c.movement_line_id=ml.id and c.kind='receipt'
  where r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and r.branch_id=p_branch_id and r.id=(p_payload->>'document_id')::uuid) then
  raise exception using errcode='55000',message='NEGATIVE_STOCK_RECEIPT_REVERSAL_REQUIRES_CORRECTION';end if;
 return api.reverse_goods_receipt_without_negative_policy(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version);
end $$;

alter function inventory.build_valuation_report(uuid,uuid,uuid,jsonb) rename to negative_stock_original_valuation_report;
create function inventory.build_valuation_report(t uuid,e uuid,b uuid,p jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;extra jsonb;movements jsonb;diffs jsonb;stock jsonb;lots jsonb;deficits jsonb;sv numeric;tv numeric;gv numeric;d date:=(p->>'as_of')::date;begin
 result:=inventory.negative_stock_original_valuation_report(t,e,b,p);
 select coalesce(jsonb_agg(jsonb_build_object('id','negative-cover:'||c.id,'evidence_key','command:'||c.command_id,'command_id',c.command_id,
  'source_type','negative_stock.cover','source_id',c.id::text,'receipt_movement_line_id',c.movement_line_id,'issue_movement_line_id',x.issue_movement_line_id,
  'policy_id',x.policy_id,'warehouse_id',x.warehouse_id,'product_id',x.product_id,'quantity','0','value',(-c.variance)::text,'posting_date',c.posting_date,
  'covered_quantity',c.quantity::text,'actual_value',c.actual_value::text,'provisional_value',c.provisional_value::text,'variance',c.variance::text,'journal_entry_id',c.journal_entry_id) order by c.id),'[]') into extra
 from inventory.negative_stock_covers c join inventory.negative_stock_deficits x on x.tenant_id=c.tenant_id and x.id=c.deficit_id
 where c.tenant_id=t and c.legal_entity_id=e and c.kind='receipt' and c.posting_date<=d;
 movements:=(result->'movements')||extra;
 if jsonb_array_length(movements)>10000 then raise exception using errcode='54000',message='VALUATION_INPUT_LIMIT';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id::text,'issue_movement_line_id',x.issue_movement_line_id,'policy_id',x.policy_id,
  'warehouse_id',x.warehouse_id,'product_id',x.product_id,'posting_date',x.posting_date,'quantity',x.quantity::text,'provisional_value',x.provisional_value::text,
  'open_quantity',(x.quantity-coalesce(c.covered,0))::text,
  'open_provisional_value',(x.provisional_value-round(x.provisional_value*coalesce(c.covered,0)/x.quantity,6))::text) order by x.id),'[]') into deficits
 from inventory.negative_stock_deficits x left join lateral(select sum(quantity) covered from inventory.negative_stock_covers z where z.tenant_id=x.tenant_id and z.deficit_id=x.id and z.posting_date<=d)c on true
 where x.tenant_id=t and x.legal_entity_id=e and x.posting_date<=d;
 if jsonb_array_length(deficits)>2000 then raise exception using errcode='54000',message='NEGATIVE_STOCK_EVIDENCE_LIMIT';end if;
 with rows as(select s,coalesce((select sum((c->>'value')::numeric) from jsonb_array_elements(extra)c where c->>'warehouse_id'=s->>'warehouse_id' and c->>'product_id'=s->>'product_id'),0) correction,
  coalesce((select sum((x->>'open_quantity')::numeric) from jsonb_array_elements(deficits)x where x->>'warehouse_id'=s->>'warehouse_id' and x->>'product_id'=s->>'product_id'),0) open_q,
  coalesce((select sum((x->>'open_provisional_value')::numeric) from jsonb_array_elements(deficits)x where x->>'warehouse_id'=s->>'warehouse_id' and x->>'product_id'=s->>'product_id'),0) open_v
  from jsonb_array_elements(result->'stock')s)
 select coalesce(jsonb_agg(s||jsonb_build_object('value',((s->>'value')::numeric+correction)::text,
  'average_cost',case when (s->>'quantity')::numeric>0 then round(((s->>'value')::numeric+correction)/(s->>'quantity')::numeric,12)::text end,
  'provisional_quantity',open_q::text,'provisional_value',open_v::text,'valuation_status',case when open_q>0 then 'provisional_deficit' else 'authoritative' end) order by s->>'id'),'[]') into stock from rows;
 select coalesce(jsonb_agg(case when x->>'lot_id' is null and exists(select 1 from jsonb_array_elements(deficits)nd
   where nd->>'warehouse_id'=s->>'warehouse_id' and nd->>'product_id'=s->>'product_id')
   then x||jsonb_build_object('value',s->>'value') else x end order by x->>'id'),'[]') into lots
 from jsonb_array_elements(result->'lots')x left join jsonb_array_elements(stock)s on s->>'id'=split_part(x->>'id',':',1)||':'||split_part(x->>'id',':',2);
 with entries as(select x->>'evidence_key' k,(x->>'value')::numeric v,0::numeric g from jsonb_array_elements(movements)x
  union all select x->>'evidence_key',(x->>'value')::numeric,0 from jsonb_array_elements(result->'transit')x
  union all select x->>'evidence_key',0,(x->>'value')::numeric from jsonb_array_elements(result->'journals')x),totals as(select k,sum(v)v,sum(g)g from entries group by k)
 select coalesce(jsonb_agg(jsonb_build_object('id',k,'evidence_key',k,'inventory_value',v::text,'gl_value',g::text,'difference',(v-g)::text) order by k),'[]') into diffs from totals where v<>g;
 select coalesce(sum((x->>'value')::numeric),0) into sv from jsonb_array_elements(stock)x;
 tv:=(result#>>'{summary,transit_value}')::numeric;gv:=(result#>>'{summary,gl_value}')::numeric;
 result:=result||jsonb_build_object('movements',movements,'stock',stock,'lots',lots,'differences',diffs,'negative_stock_deficits',deficits,
  'summary',(result->'summary')||jsonb_build_object('warehouse_value',sv::text,'inventory_value',(sv+tv)::text,'difference',(sv+tv-gv)::text,'difference_count',jsonb_array_length(diffs)));
 if octet_length(result::text)>16777216 then raise exception using errcode='54000',message='VALUATION_EVIDENCE_LIMIT';end if;
 return result;
end $$;

create function api.negative_stock_evidence(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after bigint default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor bigint;begin
 perform core.wave3_require_scope(p_tenant_id,'inventory.stock.view',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'inventory.cost.view',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='42501',message='OPERATIONAL_SCOPE_REQUIRED';end if;
 if p_resource='deficits' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.sequence),'[]') into rows from(
   select x.id::text id,x.id sequence,x.issue_movement_line_id,x.policy_id,pol.version::text policy_version,x.basis_id::text basis_id,x.warehouse_id,x.product_id,
    x.quantity::text quantity,x.provisional_value::text provisional_value,inventory.negative_stock_open_quantity(x.tenant_id,x.id)::text open_quantity,
    x.posting_date,x.command_id,x.created_at,x.created_by
   from inventory.negative_stock_deficits x join inventory.negative_stock_policy_versions pol on pol.tenant_id=x.tenant_id and pol.id=x.policy_id
   where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.branch_id=p_branch_id and(p_after is null or x.id>p_after) order by x.id limit 51)q;
 elsif p_resource='covers' then
  select coalesce(jsonb_agg(to_jsonb(q) order by q.sequence),'[]') into rows from(
   select x.id::text id,x.id sequence,x.deficit_id::text deficit_id,x.movement_line_id,x.kind,x.quantity::text quantity,x.provisional_value::text provisional_value,
    x.actual_value::text actual_value,x.variance::text variance,x.journal_entry_id,x.posting_date,x.command_id,x.request_id,x.created_at,x.created_by
   from inventory.negative_stock_covers x where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.branch_id=p_branch_id
    and(p_after is null or x.id>p_after) order by x.id limit 51)q;
 else raise exception using errcode='22023',message='NEGATIVE_STOCK_EVIDENCE_RESOURCE_INVALID';end if;
 -- Sequence participates in server sorting only and never crosses as JSON number.
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'sequence')::bigint;rows:=rows-50;end if;
 select coalesce(jsonb_agg(x-'sequence' order by (x->>'sequence')::bigint),'[]') into rows from jsonb_array_elements(rows)x;
 return jsonb_build_object('items',rows,'next_cursor',cursor::text);
end $$;

-- No alternate API name or internal helper exposes an unchecked write path.
revoke all on function api.reverse_goods_receipt_without_negative_policy(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
revoke all on function api.upsert_stock_count_without_negative_policy(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.transfer_stock_without_negative_policy(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
revoke all on function sales.flow_post_without_negative_policy(text,uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),sales.flow_post(text,uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 sales.flow_post_stock(text,jsonb,uuid,uuid),inventory.record_receipt_provenance(),inventory.record_receipt_provenance_without_negative_policy(),
 inventory.negative_stock_original_valuation_report(uuid,uuid,uuid,jsonb),inventory.build_valuation_report(uuid,uuid,uuid,jsonb),
 inventory.negative_stock_policy_entity(inventory.negative_stock_policy_versions),inventory.require_negative_stock_policy(uuid,uuid,uuid,jsonb),
 inventory.capture_negative_stock_basis(uuid,uuid,uuid,uuid,uuid,jsonb),inventory.authorize_negative_stock_projection(inventory.stock_balances,inventory.stock_valuations,uuid,text,uuid,uuid,uuid,uuid,numeric,text,numeric,numeric,numeric),
 inventory.guard_negative_stock_balance(),inventory.guard_negative_stock_value(),inventory.guard_negative_stock_operation(),inventory.negative_stock_open_quantity(uuid,bigint),
 inventory.negative_stock_return_cost(inventory.stock_movement_lines,uuid,numeric,date,uuid,uuid),inventory.negative_stock_provenance(inventory.stock_movement_lines) from public,anon,authenticated;
revoke all on function api.negative_stock_policy(uuid,uuid,uuid),api.configure_negative_stock_policy(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.negative_stock_evidence(uuid,uuid,uuid,text,bigint),api.reserve_sales_order_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
revoke all on function api.upsert_stock_count(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.transfer_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.negative_stock_policy(uuid,uuid,uuid),api.configure_negative_stock_policy(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.negative_stock_evidence(uuid,uuid,uuid,text,bigint),api.reserve_sales_order_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
grant execute on function api.upsert_stock_count(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.transfer_stock(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
notify pgrst,'reload schema';

-- Uninstalled additive milestone candidate. Requires projects/time and finance.
-- Existing permission codes are used; no role, plan, entitlement or provider activation.
create table projects.milestones(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,project_id uuid not null,
 version bigint not null default 1 check(version between 1 and 9007199254740990),current_revision_id uuid not null,
 status text not null default 'draft' check(status in('draft','submitted','approved','rejected','cancelled')),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),submitted_by uuid references auth.users(id),
 unique(tenant_id,legal_entity_id,project_id,id),
 foreign key(tenant_id,legal_entity_id,project_id) references projects.register(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create table projects.milestone_revisions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,project_id uuid not null,milestone_id uuid not null,version bigint not null,
 plan_id uuid not null,task_id uuid not null,task_name text not null,owner_id uuid not null,owner_name text not null,
 customer_id uuid not null,customer_name text not null,currency_code text not null references core.currencies(code),precision integer not null check(precision between 0 and 6),
 name text not null,due_date date not null,amount numeric(20,6) not null check(amount>=0),commercial_terms text not null,
 payment_terms text not null,payment_due_days integer not null check(payment_due_days between 0 and 365),evidence_reference text not null,
 digest text not null check(digest~'^[a-f0-9]{64}$'),reason text not null,supersedes_id uuid references projects.milestone_revisions(id),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,project_id,milestone_id,id),unique(milestone_id,version),
 foreign key(tenant_id,legal_entity_id,project_id,milestone_id) references projects.milestones(tenant_id,legal_entity_id,project_id,id),
 foreign key(tenant_id,legal_entity_id,project_id,plan_id,task_id) references projects.tasks(tenant_id,legal_entity_id,project_id,plan_id,id),
 foreign key(tenant_id,legal_entity_id,owner_id) references people.employees(tenant_id,legal_entity_id,id),foreign key(tenant_id,customer_id) references crm.parties(tenant_id,id)
);
alter table projects.milestones add constraint milestone_current_revision foreign key(tenant_id,legal_entity_id,project_id,id,current_revision_id)
 references projects.milestone_revisions(tenant_id,legal_entity_id,project_id,milestone_id,id) deferrable initially deferred;
create table projects.milestone_events(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,project_id uuid not null,
 milestone_id uuid not null,revision_id uuid not null,version bigint not null,action text not null,digest text not null,reason text not null,
 eligibility jsonb not null default '{}',actor_id uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(milestone_id,version),foreign key(tenant_id,legal_entity_id,project_id,milestone_id,revision_id)
 references projects.milestone_revisions(tenant_id,legal_entity_id,project_id,milestone_id,id)
);
create index milestone_scope_idx on projects.milestones(tenant_id,legal_entity_id,branch_id,project_id,id);
create index milestone_revision_scope_idx on projects.milestone_revisions(tenant_id,legal_entity_id,project_id,milestone_id,id);
create index milestone_event_scope_idx on projects.milestone_events(tenant_id,legal_entity_id,branch_id,project_id,milestone_id,id);
do $$declare n text;begin foreach n in array array['milestones','milestone_revisions','milestone_events'] loop
 execute format('alter table projects.%I enable row level security',n);execute format('alter table projects.%I force row level security',n);
 execute format('revoke all on projects.%I from public,anon,authenticated,service_role',n);
 if n<>'milestones' then execute format('create trigger immutable before update or delete on projects.%I for each row execute function projects.immutable()',n);end if;
end loop;end $$;
create function projects.milestone_cap(a text) returns text language sql immutable set search_path='' as $$
 select case when a in('create','correct','submit','cancel') then 'projects.manage' when a in('approve','reject') then 'projects.approve' end $$;
create function projects.milestone_summary(p uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',m.id,'tenant_id',m.tenant_id,'legal_entity_id',m.legal_entity_id,'branch_id',m.branch_id,'project_id',m.project_id,
 'version',m.version,'status',m.status,'revision_id',r.id,'plan_id',r.plan_id,'task_id',r.task_id,'task_name',r.task_name,'owner_id',r.owner_id,'owner_name',r.owner_name,
 'customer_id',r.customer_id,'customer_name',r.customer_name,'currency_code',r.currency_code,'precision',r.precision,'name',r.name,'due_date',r.due_date,
 'amount',r.amount::text,'commercial_terms',r.commercial_terms,'payment_terms',r.payment_terms,'payment_due_days',r.payment_due_days,
 'evidence_reference',r.evidence_reference,'digest',r.digest,'recorded_by',r.recorded_by,'reason',r.reason,'unit_status',u.status)
 from projects.milestones m join projects.milestone_revisions r on r.id=m.current_revision_id
 left join projects.billable_units u on u.source_kind='milestone' and u.source_id=r.id where m.id=p $$;
create function projects.milestone_owner(t uuid,e uuid,b uuid,employee uuid,d date) returns text language plpgsql security definer set search_path='' as $$
declare answer text;begin
 select x.display_name into answer from people.employees x where x.tenant_id=t and x.legal_entity_id=e and x.id=employee
 and exists(select 1 from people.employment_assignments a join people.employment_spells s on s.id=a.spell_id
  where a.tenant_id=t and a.legal_entity_id=e and a.branch_id=b and a.employee_id=x.id
  and daterange(a.start_date,a.end_date_exclusive,'[)') @> d and daterange(s.start_date,s.end_date_exclusive,'[)') @> d);
 if answer is null then raise exception using errcode='55000',message='MILESTONE_OWNER_COVERAGE_REQUIRED';end if;return answer;end $$;
create function api.project_milestone_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_issued_at timestamptz,p_payload jsonb,p_expected_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare act text:=p_payload->>'action';id uuid;project uuid;cap text;hash text;replay jsonb;reason text;allowed text[];
 pr projects.register%rowtype;m projects.milestones%rowtype;r projects.milestone_revisions%rowtype;task projects.tasks%rowtype;
 new_revision uuid:=gen_random_uuid();owner uuid;owner_name text;customer_name text;amount numeric;due date;digest text;version bigint;
 before_state jsonb:='{}';after_state jsonb;progress projects.task_progress%rowtype;eligibility jsonb:='{}';begin
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>65536 or p_command_id is null or p_idempotency_key is null
  or p_issued_at is null or p_issued_at>clock_timestamp()+interval '5 minutes' or p_expected_version is null or p_expected_version not between 0 and 9007199254740990 then
  raise exception using errcode='22023',message='MILESTONE_COMMAND_INVALID';end if;
 cap:=projects.milestone_cap(act);perform projects.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,cap,true);
 id:=(p_payload->>'id')::uuid;project:=(p_payload->>'project_id')::uuid;reason:=projects.text(p_payload->'reason',1000);
 if id is null or project is null then raise exception using errcode='22023',message='MILESTONE_ID_REQUIRED';end if;
 allowed:=case when act in('create','correct') then array['action','id','project_id','plan_id','task_id','owner_id','name','due_date','amount','commercial_terms','payment_terms','payment_due_days','evidence_reference','reason'] else array['action','id','project_id','digest','reason'] end;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(allowed)) then raise exception using errcode='22023',message='MILESTONE_FIELDS_INVALID';end if;
 hash:=core.wave3_request_hash('projects.milestone.'||act,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 replay:=core.wave3_replay(p_tenant_id,'projects.milestone.'||act,p_command_id,p_idempotency_key,hash);if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('projects:'||p_tenant_id||':'||p_legal_entity_id,0));
 select x.* into m from projects.milestones x where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.branch_id=p_branch_id and x.project_id=project and x.id=id;
 select x.* into r from projects.milestone_revisions x where x.id=m.current_revision_id;
 owner:=case when act in('create','correct') then(p_payload->>'owner_id')::uuid else r.owner_id end;
 perform x.id from people.employees x where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.id=owner for update;
 select x.* into pr from projects.register x where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.branch_id=p_branch_id and x.id=project for update;
 if pr.id is null then raise exception using errcode='P0002',message='PROJECT_NOT_FOUND';end if;
 if pr.status<>'open' then raise exception using errcode='55000',message='PROJECT_CLOSED';end if;
 select x.* into m from projects.milestones x where x.id=id and x.project_id=project for update;
 if act='create' then
  if m.id is not null or p_expected_version<>0 then raise exception using errcode='40001',message='MILESTONE_VERSION_CONFLICT';end if;version:=1;
 else
  if m.id is null then raise exception using errcode='P0002',message='MILESTONE_NOT_FOUND';end if;
  before_state:=jsonb_build_object('id',m.id,'version',m.version,'status',m.status,'revision_id',m.current_revision_id);
  perform core.wave3_assert_expected_version(m.version,p_expected_version,before_state);version:=m.version+1;
 end if;
 if act in('create','correct') then
  if act='correct' then
   if m.status not in('draft','rejected','approved') then raise exception using errcode='55000',message='MILESTONE_STATE_CONFLICT';end if;
   if exists(select 1 from projects.billable_units where source_kind='milestone' and source_id=m.current_revision_id and status not in('available','cancelled')) then
    raise exception using errcode='55000',message='MILESTONE_BILLING_IMPACT_REQUIRED';end if;
   update projects.billable_units set status='cancelled' where source_kind='milestone' and source_id=m.current_revision_id and status='available';
  end if;
  if pr.customer_id is null or pr.current_plan_id is distinct from(p_payload->>'plan_id')::uuid or not exists(select 1 from projects.plans x where x.id=pr.current_plan_id and x.status='approved') then
   raise exception using errcode='55000',message='MILESTONE_APPROVED_PLAN_REQUIRED';end if;
  select x.* into task from projects.tasks x where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id and x.project_id=project and x.plan_id=pr.current_plan_id and x.id=(p_payload->>'task_id')::uuid;
  if coalesce(p_payload->>'due_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception using errcode='22023',message='MILESTONE_DUE_TASK_INVALID';end if;
  due:=(p_payload->>'due_date')::date;
  if task.id is null or due is null or due<task.start_date or due>=task.end_date_exclusive or due<pr.start_date or due>=pr.end_date_exclusive then
   raise exception using errcode='22023',message='MILESTONE_DUE_TASK_INVALID';end if;
  owner_name:=projects.milestone_owner(p_tenant_id,p_legal_entity_id,p_branch_id,owner,due);
  select x.display_name into customer_name from crm.parties x where x.tenant_id=p_tenant_id and x.id=pr.customer_id and x.status='active' and x.kind in('customer','both');
  if customer_name is null then raise exception using errcode='55000',message='MILESTONE_ACTIVE_CUSTOMER_REQUIRED';end if;
  amount:=projects.amount(p_payload->'amount');if amount<>projects.ratio(amount*1000000,1,pr.precision) then raise exception using errcode='22023',message='PROJECT_AMOUNT_PRECISION';end if;
  if jsonb_typeof(p_payload->'payment_due_days') is distinct from 'number' or coalesce(p_payload->>'payment_due_days','') !~ '^(0|[1-9][0-9]{0,2})$'
   or(p_payload->>'payment_due_days')::integer>365 then raise exception using errcode='22023',message='MILESTONE_PAYMENT_DAYS_INVALID';end if;
  digest:=encode(extensions.digest((p_payload||jsonb_build_object('customer_id',pr.customer_id,'currency_code',pr.currency_code,'precision',pr.precision,'plan_terms',(select terms from projects.plans where id=pr.current_plan_id)))::text,'sha256'),'hex');
  if act='create' then insert into projects.milestones(id,tenant_id,legal_entity_id,branch_id,project_id,current_revision_id,created_by)
   values(id,p_tenant_id,p_legal_entity_id,p_branch_id,project,new_revision,auth.uid());end if;
  insert into projects.milestone_revisions(id,tenant_id,legal_entity_id,project_id,milestone_id,version,plan_id,task_id,task_name,owner_id,owner_name,customer_id,customer_name,
   currency_code,precision,name,due_date,amount,commercial_terms,payment_terms,payment_due_days,evidence_reference,digest,reason,supersedes_id,recorded_by)
  values(new_revision,p_tenant_id,p_legal_entity_id,project,id,version,pr.current_plan_id,task.id,task.name,owner,owner_name,pr.customer_id,customer_name,pr.currency_code,pr.precision,
   projects.text(p_payload->'name',160),due,amount,projects.text(p_payload->'commercial_terms',2000),projects.text(p_payload->'payment_terms',1000),
   (p_payload->>'payment_due_days')::integer,projects.text(p_payload->'evidence_reference',160),digest,reason,m.current_revision_id,auth.uid());
  if act='correct' then update projects.milestones set current_revision_id=new_revision,version=version,status='draft',submitted_by=null where milestones.id=id;end if;
 else
  if r.digest is distinct from p_payload->>'digest' then raise exception using errcode='40001',message='MILESTONE_VERSION_CONFLICT';end if;
  if act='submit' then
   if m.status<>'draft' then raise exception using errcode='55000',message='MILESTONE_STATE_CONFLICT';end if;
   update projects.milestones set status='submitted',submitted_by=auth.uid(),version=version where milestones.id=id;
  elsif act in('approve','reject') then
   if m.status<>'submitted' then raise exception using errcode='55000',message='MILESTONE_STATE_CONFLICT';end if;
   if auth.uid() in(r.recorded_by,m.submitted_by) then raise exception using errcode='42501',message='MILESTONE_INDEPENDENT_APPROVAL_REQUIRED';end if;
   if act='approve' then
    if pr.current_plan_id is distinct from r.plan_id or not exists(select 1 from projects.plans where plans.id=r.plan_id and status='approved') then raise exception using errcode='55000',message='MILESTONE_APPROVED_PLAN_REQUIRED';end if;
    select x.* into progress from projects.task_progress x where x.project_id=project and x.plan_id=r.plan_id and x.task_id=r.task_id order by x.project_version desc limit 1;
    if progress.id is null or progress.progress<>10000 then raise exception using errcode='55000',message='MILESTONE_TASK_INCOMPLETE';end if;
    perform projects.milestone_owner(p_tenant_id,p_legal_entity_id,p_branch_id,r.owner_id,r.due_date);
    if not exists(select 1 from crm.parties x where x.tenant_id=p_tenant_id and x.id=r.customer_id and x.status='active' and x.kind in('customer','both')) then
     raise exception using errcode='55000',message='MILESTONE_ACTIVE_CUSTOMER_REQUIRED';end if;
    eligibility:=jsonb_build_object('plan_id',r.plan_id,'task_id',r.task_id,'progress_event_id',progress.id,'project_version',pr.version,'progress',10000,'completion_evidence',r.evidence_reference);
    insert into projects.billable_units(id,tenant_id,legal_entity_id,project_id,branch_id,source_kind,source_id,source_version,source_digest,amount)
     values(gen_random_uuid(),p_tenant_id,p_legal_entity_id,project,p_branch_id,'milestone',r.id,version,r.digest,r.amount);
   end if;
   update projects.milestones set status=case act when 'approve' then 'approved' else 'rejected' end,version=version where milestones.id=id;
  elsif act='cancel' then
   if m.status='cancelled' then raise exception using errcode='55000',message='MILESTONE_STATE_CONFLICT';end if;
   if exists(select 1 from projects.billable_units where source_kind='milestone' and source_id=r.id and status not in('available','cancelled')) then raise exception using errcode='55000',message='MILESTONE_BILLING_IMPACT_REQUIRED';end if;
   update projects.billable_units set status='cancelled' where source_kind='milestone' and source_id=r.id and status='available';
   update projects.milestones set status='cancelled',version=version where milestones.id=id;
  end if;
  new_revision:=r.id;digest:=r.digest;
 end if;
 insert into projects.milestone_events(tenant_id,legal_entity_id,branch_id,project_id,milestone_id,revision_id,version,action,digest,reason,eligibility,actor_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,project,id,new_revision,version,act,digest,reason,eligibility,auth.uid());
 select jsonb_build_object('id',x.id,'tenant_id',x.tenant_id,'legal_entity_id',x.legal_entity_id,'branch_id',x.branch_id,'project_id',x.project_id,
 'version',x.version,'status',x.status,'revision_id',x.current_revision_id) into after_state from projects.milestones x where x.id=id;
 return core.wave3_finish_command(p_tenant_id,'projects.milestone.'||act,p_command_id,'projects.milestone',id,p_idempotency_key,hash,before_state,after_state,p_legal_entity_id,p_branch_id);
end $$;
create function api.project_milestones(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_project_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$declare items jsonb;begin
 perform projects.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'projects.view');
 if not exists(select 1 from projects.register where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_project_id) then raise exception using errcode='P0002',message='PROJECT_NOT_FOUND';end if;
 select coalesce(jsonb_agg(projects.milestone_summary(x.id) order by x.id),'[]') into items from(select id from projects.milestones where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and project_id=p_project_id and(p_after is null or id>p_after) order by id limit 50) x;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'project_id',p_project_id,'items',items,'next_after',case when jsonb_array_length(items)=50 then items->49->>'id' end);end $$;
create function api.project_milestone_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_project_id uuid,p_id uuid,p_after uuid default null,p_kind text default 'events')
returns jsonb language plpgsql stable security definer set search_path='' as $$declare body jsonb;events jsonb;begin
 perform projects.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'projects.view');
 if not exists(select 1 from projects.milestones where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and project_id=p_project_id and id=p_id) then raise exception using errcode='P0002',message='MILESTONE_NOT_FOUND';end if;
 body:=projects.milestone_summary(p_id);
 if p_kind='events' then
  select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') into events from(select * from projects.milestone_events where milestone_id=p_id and(p_after is null or id>p_after) order by id limit 50) x;
 elsif p_kind='revisions' then
  select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('amount',x.amount::text) order by x.id),'[]') into events from(select * from projects.milestone_revisions where milestone_id=p_id and(p_after is null or id>p_after) order by id limit 50) x;
 else raise exception using errcode='22023',message='MILESTONE_DETAIL_KIND_INVALID';end if;
 return jsonb_build_object('record',body,'kind',p_kind,'rows',events,'next_after',case when jsonb_array_length(events)=50 then events->49->>'id' end);end $$;
create function api.project_milestone_own_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_project_id uuid,p_idempotency_key uuid,p_action text)
returns jsonb language plpgsql stable security definer set search_path='' as $$declare body jsonb;begin
 perform projects.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,projects.milestone_cap(p_action),true);
 select response into body from core.command_receipts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
 and actor_id=auth.uid() and command_name='projects.milestone.'||p_action and idempotency_key=p_idempotency_key and(response#>>'{entity,project_id}')::uuid=p_project_id;
 return body;end $$;
create function projects.milestone_billing_terms(t uuid,e uuid,b uuid,source uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare body jsonb;begin
 select jsonb_build_object('customer_id',r.customer_id,'currency_code',r.currency_code,'amount',r.amount::text,'source_version',u.source_version,'digest',r.digest,
 'payment_due_days',r.payment_due_days,'payment_terms',r.payment_terms) into body
 from projects.milestone_revisions r join projects.milestones m on m.id=r.milestone_id join projects.billable_units u on u.source_id=r.id and u.source_kind='milestone'
 where m.tenant_id=t and m.legal_entity_id=e and m.branch_id=b and r.id=source
 and u.tenant_id=t and u.legal_entity_id=e and u.branch_id=b and u.project_id=m.project_id and u.source_digest=r.digest and u.amount=r.amount
 and exists(select 1 from projects.milestone_events a where a.milestone_id=m.id and a.revision_id=r.id and a.version=u.source_version and a.action='approve' and a.digest=r.digest);
 if body is null then raise exception using errcode='55000',message='MILESTONE_BILLING_SOURCE_CHANGED';end if;return body;end $$;
create function projects.milestone_closure_guard(t uuid,e uuid,project uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from projects.milestones where tenant_id=t and legal_entity_id=e and project_id=project and status in('draft','submitted','rejected'))
 or exists(select 1 from projects.billable_units where tenant_id=t and legal_entity_id=e and project_id=project and source_kind='milestone' and status in('available','reserved')) then
  raise exception using errcode='55000',message='MILESTONE_CLOSURE_IMPACT_REQUIRED';end if;end $$;
revoke all on function projects.milestone_cap(text),projects.milestone_summary(uuid),projects.milestone_owner(uuid,uuid,uuid,uuid,date),
 projects.milestone_billing_terms(uuid,uuid,uuid,uuid),projects.milestone_closure_guard(uuid,uuid,uuid) from public,anon,authenticated,service_role;
revoke all on function api.project_milestone_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.project_milestones(uuid,uuid,uuid,uuid,uuid),
 api.project_milestone_detail(uuid,uuid,uuid,uuid,uuid,uuid,text),api.project_milestone_own_receipt(uuid,uuid,uuid,uuid,uuid,text) from public,anon,authenticated,service_role;
grant execute on function api.project_milestone_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.project_milestones(uuid,uuid,uuid,uuid,uuid),
 api.project_milestone_detail(uuid,uuid,uuid,uuid,uuid,uuid,text),api.project_milestone_own_receipt(uuid,uuid,uuid,uuid,uuid,text) to authenticated;

-- UNAPPLIED additive Service + Assets operational association. No capitalization.
create table service.asset_equipment_links(
 equipment_id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 asset_id uuid not null,asset_version bigint not null check(asset_version between 1 and 9007199254740991),
 source_digest text not null check(source_digest ~ '^[0-9a-f]{64}$'),source_basis jsonb not null,
 reason text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,asset_id),
 foreign key(tenant_id,legal_entity_id,equipment_id) references service.equipment(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,asset_id) references assets.register(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
alter table service.asset_equipment_links enable row level security;
alter table service.asset_equipment_links force row level security;
revoke all on service.asset_equipment_links from public,anon,authenticated;
create trigger service_asset_link_immutable before update or delete on service.asset_equipment_links
 for each row execute function service.immutable();
alter table service.tickets alter column customer_id drop not null;

create function service.asset_source(t uuid,e uuid,b uuid,p_asset uuid,p_lock boolean default false,p_eligible boolean default true)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a assets.register%rowtype;basis jsonb;begin
 perform service.require_access(t,e,b,'service.view');perform assets.require_access(t,e,b,'assets.view');
 if p_lock then select * into a from assets.register where tenant_id=t and legal_entity_id=e and id=p_asset for update;
 else select * into a from assets.register where tenant_id=t and legal_entity_id=e and id=p_asset;end if;
 if a.id is null or p_eligible and(a.status<>'active' or a.branch_id<>b) then
  raise exception using errcode='55000',message='SERVICE_ASSET_NOT_ELIGIBLE';end if;
 basis:=jsonb_build_object('id',a.id,'tenant_id',t,'legal_entity_id',e,'branch_id',a.branch_id,
  'code',a.code,'name',a.name,'ownership',a.ownership,'in_service',a.in_service,'location_id',a.location_id,
  'location_name',(select name from assets.locations where id=a.location_id),'custodian_id',a.custodian_id,
  'custodian_name',(select display_name from people.employees where tenant_id=t and legal_entity_id=e and id=a.custodian_id),
  'status',a.status,'version',a.version);
 return basis||jsonb_build_object('digest',encode(extensions.digest(basis::text,'sha256'),'hex'));
end $$;
create function service.asset_equipment_for(p_kind text,p_id uuid) returns uuid language plpgsql stable security definer set search_path='' as $$
declare eq uuid;begin
 case p_kind
 when 'equipment' then eq:=p_id;
 when 'ticket' then select equipment_id into eq from service.tickets where id=p_id;
 when 'coverage' then select equipment_id into eq from service.coverage_versions where id=p_id;
 when 'order' then select t.equipment_id into eq from service.work_orders w join service.tickets t on t.id=w.ticket_id where w.id=p_id;
 when 'labor' then select t.equipment_id into eq from service.labor l join service.work_orders w on w.id=l.order_id join service.tickets t on t.id=w.ticket_id where l.id=p_id;
 when 'plan' then select equipment_id into eq from service.maintenance_plans where id=p_id;
 when 'reading' then select equipment_id into eq from service.meter_readings where id=p_id;
 when 'occurrence' then select p.equipment_id into eq from service.maintenance_occurrences o join service.maintenance_plans p on p.id=o.plan_id where o.id=p_id;
 else eq:=null;end case;
 return eq;
end $$;
create function service.asset_equipment_guard(t uuid,e uuid,b uuid,p_equipment uuid,p_lock boolean default false,p_eligible boolean default true)
returns void language plpgsql security definer set search_path='' as $$
declare l service.asset_equipment_links%rowtype;q service.equipment%rowtype;begin
 select * into q from service.equipment where tenant_id=t and legal_entity_id=e and branch_id=b and id=p_equipment;
 if q.id is null then raise exception using errcode='P0002',message='SERVICE_NOT_FOUND';end if;
 if q.kind='asset' then
  select * into l from service.asset_equipment_links where tenant_id=t and legal_entity_id=e and branch_id=b and equipment_id=q.id and asset_id=q.provider_id;
  if l.equipment_id is null or q.customer_id is not null then raise exception using errcode='55000',message='SERVICE_ASSET_LINK_REQUIRED';end if;
  perform service.asset_source(t,e,b,l.asset_id,p_lock,p_eligible);
 end if;
end $$;

create function api.service_asset_authorize(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_capability text)
returns jsonb language plpgsql stable security definer set search_path='' as $$begin
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_capability);
 perform assets.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'assets.view');
 return jsonb_build_object('actor_id',auth.uid(),'tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'capability',p_capability,'authorized',true);
end $$;
create function api.service_asset_sources(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_after uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$declare items jsonb;begin
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'service.configure');
 perform assets.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'assets.view');
 select coalesce(jsonb_agg(service.asset_source(p_tenant_id,p_legal_entity_id,p_branch_id,q.id) order by q.id),'[]') into items
 from(select a.id from assets.register a where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id and a.branch_id=p_branch_id and a.status='active'
  and(p_after is null or a.id>p_after) and not exists(select 1 from service.asset_equipment_links l where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and l.asset_id=a.id)
  order by a.id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'items',items-50,
  'next_cursor',case when jsonb_array_length(items)>50 then items->49->>'id' end);
end $$;
create function api.service_asset_equipment_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_issued_at timestamptz,p_payload jsonb,p_expected_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare id uuid;source jsonb;hash text;replay jsonb;reason text;begin
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'service.configure');
 perform assets.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'assets.view');
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>8192
  or p_payload->>'action' is distinct from 'equipment' or p_payload->>'kind' is distinct from 'asset' or p_payload->>'customer_id' is not null
  or p_expected_version is distinct from 0 or p_command_id is null or p_idempotency_key is null or p_issued_at is null or p_issued_at>clock_timestamp()+interval '5 minutes'
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'provider_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(array['action','id','reason','code','name','identity','kind','customer_id','provider_id','provider_version','provider_digest'])) then
  raise exception using errcode='22023',message='SERVICE_ASSET_COMMAND_INVALID';end if;
 id:=(p_payload->>'id')::uuid;reason:=service.text(p_payload->'reason',1000);
 perform service.text(p_payload->'name',160);perform service.text(p_payload->'identity',160);
 if coalesce(p_payload->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' or jsonb_typeof(p_payload->'provider_version') is distinct from 'number'
  or coalesce(p_payload->>'provider_digest','') !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='SERVICE_ASSET_COMMAND_INVALID';end if;
 hash:=core.wave3_request_hash('service.asset_equipment',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 -- Fresh authorities above precede actor replay. Historical exact replay remains an original receipt.
 replay:=core.wave3_replay(p_tenant_id,'service.asset_equipment',p_command_id,p_idempotency_key,hash);if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended('people.payroll:'||p_tenant_id||':'||p_legal_entity_id,0));
 perform pg_advisory_xact_lock(hashtextextended('projects:'||p_tenant_id||':'||p_legal_entity_id,0));
 perform pg_advisory_xact_lock(hashtextextended('service:'||p_tenant_id||':'||p_legal_entity_id,0));
 source:=service.asset_source(p_tenant_id,p_legal_entity_id,p_branch_id,(p_payload->>'provider_id')::uuid,true);
 if source->'version'<>p_payload->'provider_version' or source->>'digest'<>p_payload->>'provider_digest' then raise exception using errcode='40001',message='SERVICE_ASSET_SOURCE_CHANGED';end if;
 insert into service.equipment(id,tenant_id,legal_entity_id,branch_id,code,name,identity,kind,customer_id,provider_id,created_by)
 values(id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload->>'code',p_payload->>'name',p_payload->>'identity','asset',null,(p_payload->>'provider_id')::uuid,auth.uid());
 insert into service.asset_equipment_links(equipment_id,tenant_id,legal_entity_id,branch_id,asset_id,asset_version,source_digest,source_basis,reason,created_by)
 values(id,p_tenant_id,p_legal_entity_id,p_branch_id,(source->>'id')::uuid,(source->>'version')::bigint,source->>'digest',source,reason,auth.uid());
 insert into service.events(tenant_id,legal_entity_id,branch_id,aggregate_id,kind,version,action,reason,facts,actor_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,id,'equipment',1,'asset_equipment',reason,service.snapshot('equipment',id),auth.uid());
 return core.wave3_finish_command(p_tenant_id,'service.asset_equipment',p_command_id,'service.equipment',id,p_idempotency_key,hash,null,
  jsonb_build_object('id',id,'tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'kind','equipment','version',1,'status','active'),p_legal_entity_id,p_branch_id);
end $$;
create function api.service_asset_link(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_equipment_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$declare l service.asset_equipment_links%rowtype;begin
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'service.view');perform assets.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'assets.view');
 select * into l from service.asset_equipment_links where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and equipment_id=p_equipment_id;
 if l.equipment_id is null then raise exception using errcode='P0002',message='SERVICE_NOT_FOUND';end if;
 return to_jsonb(l);
end $$;
create function api.service_asset_own_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_idempotency_key uuid)
returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'service.configure');perform assets.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'assets.view');
 select response into r from core.command_receipts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and actor_id=auth.uid() and command_name='service.asset_equipment' and idempotency_key=p_idempotency_key;
 if r is not null and(r->'entity'->>'legal_entity_id'<>p_legal_entity_id::text or r->'entity'->>'branch_id'<>p_branch_id::text) then return null;end if;return r;
end $$;

-- Preserve the reviewed customer implementation while governing internal sources.
alter function service.ticket_create(uuid,uuid,uuid,uuid,jsonb) rename to ticket_create_customer;
create function service.ticket_create(t uuid,e uuid,b uuid,id uuid,p jsonb) returns void language plpgsql security definer set search_path='' as $$
declare eq service.equipment%rowtype;policy service.sla_policies%rowtype;at timestamptz;begin
 select * into eq from service.equipment where tenant_id=t and legal_entity_id=e and branch_id=b and equipment.id=(p->>'equipment_id')::uuid and status='active';
 if eq.kind is distinct from 'asset' then perform service.ticket_create_customer(t,e,b,id,p);return;end if;
 perform service.asset_equipment_guard(t,e,b,eq.id,true);
 at:=service.utc(p->'observed_utc');select * into policy from service.sla_policies where tenant_id=t and legal_entity_id=e and branch_id=b and sla_policies.id=(p->>'policy_id')::uuid;
 if p->>'customer_id' is not null or p->>'contact_id' is not null or policy.id is null
  or coalesce(p->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$' or coalesce(p->>'priority','') not in('low','normal','high','urgent') or at>clock_timestamp()+interval '5 minutes'
  or p->>'coverage_id' is not null and not exists(select 1 from service.coverage_versions c where c.tenant_id=t and c.legal_entity_id=e and c.branch_id=b and c.id=(p->>'coverage_id')::uuid and c.equipment_id=eq.id
   and daterange(c.start_date,c.end_date_exclusive,'[)') @> (at at time zone(select timezone from core.legal_entities where tenant_id=t and legal_entities.id=e))::date) then
  raise exception using errcode='22023',message='SERVICE_INTERNAL_TICKET_INVALID';end if;
 insert into service.tickets(id,tenant_id,legal_entity_id,branch_id,code,name,classification,customer_id,contact_id,equipment_id,coverage_id,policy_id,priority,owner_id,started_utc,clock_start_utc,response_due,resolution_due,created_by)
 values(id,t,e,b,p->>'code',service.text(p->'name',160),service.text(p->'classification',80),null,null,eq.id,(p->>'coverage_id')::uuid,policy.id,p->>'priority',(p->>'owner_id')::uuid,
  at,at,service.due(policy.windows,at,policy.response_seconds),service.due(policy.windows,at,policy.resolution_seconds),auth.uid());
end $$;
alter function api.service_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) rename to service_command_customer_base;
create function api.service_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_issued_at timestamptz,p_payload jsonb,p_expected_version bigint)
returns jsonb language plpgsql security definer set search_path='' as $$declare act text:=p_payload->>'action';eq uuid;original jsonb;begin
 if service.capability(act) is null or coalesce(jsonb_typeof(p_payload),'null')<>'object' or octet_length(p_payload::text)>65536 or p_command_id is null or p_idempotency_key is null
  or p_issued_at is null or p_issued_at>clock_timestamp()+interval '5 minutes' or p_expected_version is null or p_expected_version not between 0 and 9007199254740990
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(service.fields(act))) then raise exception using errcode='22023',message='SERVICE_COMMAND_INVALID';end if;
 perform service.text(p_payload->'reason',1000);
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,service.capability(act));
 eq:=case when act in('ticket','coverage','plan','reading') then(p_payload->>'equipment_id')::uuid
  when act='order' then service.asset_equipment_for('ticket',(p_payload->>'ticket_id')::uuid)
  when act='labor' then service.asset_equipment_for('order',(p_payload->>'order_id')::uuid)
  else null end;
 -- The ordinary action-to-kind helper is explicit; no provider identity comes from client labels.
 if eq is null then eq:=service.asset_equipment_for(case when act in('dispatch','accept','start','complete','close','cancel_order') then 'order'
  when act in('approve_labor','cancel_labor') then 'labor' when act='generate' then 'plan' when act='defer' then 'occurrence'
  when act in('pause','resume','evaluate','reprioritize','cancel_ticket') then 'ticket' else null end,(p_payload->>'id')::uuid);end if;
 if exists(select 1 from service.equipment where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=eq and kind='asset') then
  perform assets.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'assets.view');
  original:=core.wave3_replay(p_tenant_id,'service.'||act,p_command_id,p_idempotency_key,
   core.wave3_request_hash('service.'||act,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version));
  if original is not null then return original;end if;
  perform pg_advisory_xact_lock(hashtextextended('people.payroll:'||p_tenant_id||':'||p_legal_entity_id,0));
  perform pg_advisory_xact_lock(hashtextextended('projects:'||p_tenant_id||':'||p_legal_entity_id,0));
  perform pg_advisory_xact_lock(hashtextextended('service:'||p_tenant_id||':'||p_legal_entity_id,0));
  perform service.asset_equipment_guard(p_tenant_id,p_legal_entity_id,p_branch_id,eq,true,act in('ticket','coverage','plan','reading','generate','order','dispatch','accept','start','labor'));
  if act='labor' and coalesce(p_payload->>'billing_kind','nonbillable')<>'nonbillable' then raise exception using errcode='55000',message='SERVICE_INTERNAL_NONBILLABLE';end if;
  if act='complete' and(p_payload->>'customer_confirmed' is distinct from 'false' or nullif(btrim(p_payload->>'exception_reason'),'') is null) then
   raise exception using errcode='22023',message='SERVICE_INTERNAL_CONFIRMATION_REQUIRED';end if;
 end if;
 return api.service_command_customer_base(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_issued_at,p_payload,p_expected_version);
end $$;
create or replace function api.service_list(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_kind text,p_after uuid default null,p_parent uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare items jsonb;tablename text:=service.table_for(p_kind);parent_column text;cost boolean;begin
 perform service.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'service.view');
 if tablename is null then raise exception using errcode='22023',message='SERVICE_KIND_INVALID';end if;
 cost:=core.has_permission(p_tenant_id,'service.cost.view',p_legal_entity_id,p_branch_id);
 parent_column:=case p_kind when 'coverage' then 'equipment_id' when 'order' then 'ticket_id' when 'labor' then 'order_id' when 'reading' then 'equipment_id' when 'occurrence' then 'plan_id' end;
 if p_parent is not null and parent_column is null then raise exception using errcode='22023',message='SERVICE_PARENT_INVALID';end if;
 execute format('select coalesce(jsonb_agg(service.public_snapshot($1,q.id,$6) order by q.id),''[]''::jsonb) from(select id from service.%I where tenant_id=$2 and legal_entity_id=$3 and branch_id=$4 and($5 is null or id>$5) and service.asset_read_allowed($2,$3,$4,$1,id)%s order by id limit 51) q',
  tablename,case when p_parent is null then '' else format(' and %I=$7',parent_column) end)
 into items using p_kind,p_tenant_id,p_legal_entity_id,p_branch_id,p_after,cost,p_parent;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'kind',p_kind,'items',items-50,'next_cursor',case when jsonb_array_length(items)>50 then items->49->>'id' end);end $$;

-- Scope/asset authority is checked before all historical internal projections.
create function service.asset_read_allowed(t uuid,e uuid,b uuid,p_kind text,p_id uuid) returns boolean language plpgsql stable security definer set search_path='' as $$
declare eq uuid:=service.asset_equipment_for(p_kind,p_id);begin
 if not exists(select 1 from service.equipment where id=eq and kind='asset') then return true;end if;
 return core.has_permission(t,'assets.view',e,b) and exists(select 1 from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
  where s.tenant_id=t and p.entitlement_code='module.assets' and p.enabled and
   ((s.status='trialing' and s.trial_ends_at>now()) or(s.status='active' and(s.current_period_ends_at is null or s.current_period_ends_at>now()))));
end $$;
-- Guard snapshots centrally: customer rows remain readable; internal rows require both authorities.
alter function service.public_snapshot(text,uuid,boolean) rename to public_snapshot_customer_base;
create function service.public_snapshot(kind text,id uuid,cost boolean) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r jsonb;begin
 r:=service.public_snapshot_customer_base(kind,id,cost);
 if r is not null and not service.asset_read_allowed((r->>'tenant_id')::uuid,(r->>'legal_entity_id')::uuid,(r->>'branch_id')::uuid,kind,id) then
  raise exception using errcode='42501',message='SERVICE_ASSET_ACCESS_REQUIRED';end if;return r;
end $$;
alter function api.service_own_receipt(uuid,uuid,uuid,uuid,text) rename to service_own_receipt_customer_base;
create function api.service_own_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_idempotency_key uuid,p_action text)
returns jsonb language plpgsql stable security definer set search_path='' as $$declare r jsonb;begin
 r:=api.service_own_receipt_customer_base(p_tenant_id,p_legal_entity_id,p_branch_id,p_idempotency_key,p_action);
 if r is not null and not service.asset_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id,r#>>'{entity,kind}',(r#>>'{entity,id}')::uuid) then
  raise exception using errcode='42501',message='SERVICE_ASSET_ACCESS_REQUIRED';end if;return r;
end $$;
create function service.internal_ticket_invariant() returns trigger language plpgsql set search_path='' as $$declare k text;begin
 select kind into k from service.equipment where tenant_id=new.tenant_id and legal_entity_id=new.legal_entity_id and id=new.equipment_id;
 if(k='asset' and(new.customer_id is not null or new.contact_id is not null)) or(k='customer' and new.customer_id is null) then
  raise exception using errcode='22023',message='SERVICE_INTERNAL_TICKET_INVALID';end if;return new;
end $$;
create trigger service_internal_ticket_invariant before insert or update on service.tickets for each row execute function service.internal_ticket_invariant();
create function service.internal_labor_invariant() returns trigger language plpgsql set search_path='' as $$begin
 if new.billing_kind<>'nonbillable' and exists(select 1 from service.work_orders w join service.tickets t on t.id=w.ticket_id
  where w.id=new.order_id and t.customer_id is null) then raise exception using errcode='55000',message='SERVICE_INTERNAL_NONBILLABLE';end if;return new;
end $$;
create trigger service_internal_labor_invariant before insert or update on service.labor for each row execute function service.internal_labor_invariant();
alter function service.billing_source(uuid,uuid,uuid,uuid) rename to billing_source_customer_base;
create function service.billing_source(t uuid,e uuid,b uuid,p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from service.labor l join service.work_orders w on w.id=l.order_id join service.tickets q on q.id=w.ticket_id
  where l.tenant_id=t and l.legal_entity_id=e and l.branch_id=b and l.id=p_id and q.customer_id is null) then raise exception using errcode='55000',message='SERVICE_INTERNAL_NONBILLABLE';end if;
 return service.billing_source_customer_base(t,e,b,p_id);
end $$;
revoke all on all functions in schema service from public,anon,authenticated;
revoke all on function api.service_command_customer_base(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.service_own_receipt_customer_base(uuid,uuid,uuid,uuid,text),
 api.service_asset_authorize(uuid,uuid,uuid,text),api.service_asset_sources(uuid,uuid,uuid,uuid),api.service_asset_equipment_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.service_asset_link(uuid,uuid,uuid,uuid),api.service_asset_own_receipt(uuid,uuid,uuid,uuid),
 api.service_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.service_own_receipt(uuid,uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function api.service_asset_authorize(uuid,uuid,uuid,text),api.service_asset_sources(uuid,uuid,uuid,uuid),api.service_asset_equipment_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.service_asset_link(uuid,uuid,uuid,uuid),api.service_asset_own_receipt(uuid,uuid,uuid,uuid),
 api.service_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.service_own_receipt(uuid,uuid,uuid,uuid,text) to authenticated;

-- UNAPPLIED protected project-expense evidence candidate. No role/plan grants.
-- Separate privacy unit, bucket and worker; no core.files or private-HR linkage.
create schema expense_private;
revoke all on schema expense_private from public,anon,authenticated,service_role;
insert into core.permissions(code,module,description,privileged) values
 ('projects.expenses.evidence.view','projects','Read a scoped private expense evidence document',true),
 ('projects.expenses.evidence.export','projects','Export a scoped expense evidence document',true),
 ('projects.expenses.retention.manage','projects','Set expense evidence retention and document holds',true)
on conflict(code) do nothing;
create table expense_private.policies(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 retention_days integer not null check(retention_days between 1 and 3650),
 purpose text not null,digest_key bytea not null default extensions.gen_random_bytes(32),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table expense_private.documents(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 project_id uuid not null,expense_id uuid not null,policy_id uuid not null references expense_private.policies(id),
 version bigint not null default 1 check(version between 1 and 9007199254740990),
 content_version bigint not null default 1 check(content_version=1),digest text not null check(digest~'^[a-f0-9]{64}$'),
 mime text not null check(mime in('text/plain','image/png','image/jpeg','application/pdf')),
 byte_size integer not null check(byte_size between 1 and 10485760),checksum text not null check(checksum~'^[a-f0-9]{64}$'),
 purpose text not null,status text not null default 'reserved' check(status in('reserved','verified','active','retired','purging','purged')),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 verified_at timestamptz,activated_at timestamptz,retired_at timestamptz,purge_after timestamptz,purged_at timestamptz,
 hold_reason text,hold_review_date date,
 unique(tenant_id,legal_entity_id,branch_id,project_id,expense_id,id),
 foreign key(tenant_id,legal_entity_id,project_id) references projects.register(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 check((hold_reason is null)=(hold_review_date is null))
);
create table expense_private.events(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 document_id uuid not null references expense_private.documents(id),action text not null,
 version bigint not null,reason text,actor_id uuid references auth.users(id),recorded_at timestamptz not null default clock_timestamp()
);
create table expense_private.tickets(
 id uuid primary key default gen_random_uuid(),document_id uuid not null references expense_private.documents(id),
 user_id uuid not null references auth.users(id),operation text not null check(operation in('upload','download','export')),
 issued_aal text not null,expires_at timestamptz not null default clock_timestamp()+interval '30 seconds',
 consumed_at timestamptz,verified_at timestamptz
);
create table expense_private.worker_readiness(
 contract text primary key check(contract='w4-expense-evidence-v1'),artifact_digest text not null check(artifact_digest~'^[a-f0-9]{64}$'),
 storage_probe_digest text not null check(storage_probe_digest~'^[a-f0-9]{64}$'),verified_at timestamptz not null default clock_timestamp()
);
create table expense_private.purge_jobs(
 id uuid primary key default gen_random_uuid(),document_id uuid not null unique references expense_private.documents(id),
 lease_id uuid,lease_until timestamptz,status text not null default 'pending' check(status in('pending','complete')),
 completed_at timestamptz
);
create index expense_evidence_scope on expense_private.documents(tenant_id,legal_entity_id,branch_id,project_id,expense_id,id);
create index expense_evidence_expiry on expense_private.documents(status,purge_after,created_at);
create index expense_evidence_tickets_expiry on expense_private.tickets(expires_at);
create trigger immutable before update or delete on expense_private.policies for each row execute function projects.immutable();
create trigger immutable before update or delete on expense_private.events for each row execute function projects.immutable();
create function expense_private.document_guard() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' or(to_jsonb(new)-array['version','status','verified_at','activated_at','retired_at','purge_after','purged_at','hold_reason','hold_review_date'])
  is distinct from(to_jsonb(old)-array['version','status','verified_at','activated_at','retired_at','purge_after','purged_at','hold_reason','hold_review_date']) then
  raise exception using errcode='55000',message='EXPENSE_EVIDENCE_IMMUTABLE';end if;
 return new;
end $$;
create trigger immutable_content before update or delete on expense_private.documents for each row execute function expense_private.document_guard();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('jentra-project-expense-private','jentra-project-expense-private',false,10485760,array['text/plain','image/png','image/jpeg','application/pdf']);
create policy wave4_expense_evidence_no_direct_storage on storage.objects as restrictive
 for all to anon,authenticated using(bucket_id<>'jentra-project-expense-private') with check(bucket_id<>'jentra-project-expense-private');

create function expense_private.lock_scope(t uuid,e uuid) returns void language plpgsql set search_path='' as $$begin
 perform pg_advisory_xact_lock(hashtextextended('people.payroll:'||t||':'||e,0));
 perform pg_advisory_xact_lock(hashtextextended('projects:'||t||':'||e,0));
 perform pg_advisory_xact_lock(hashtextextended('service:'||t||':'||e,0));
end $$;
create function expense_private.require_access(t uuid,e uuid,b uuid,p uuid,x uuid,cap text) returns void
language plpgsql security definer set search_path='' as $$begin
 perform projects.finance_access(t,e,b,'projects.cost.view',true);
 if cap not in('projects.cost.view','projects.expenses.manage','projects.expenses.evidence.view','projects.expenses.evidence.export','projects.expenses.retention.manage') then
  raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
 perform core.wave3_require_scope(t,'projects.expenses.evidence.view',e,b);
 perform core.wave3_require_scope(t,cap,e,b);
 if p is not null and not exists(select 1 from projects.register r where r.tenant_id=t and r.legal_entity_id=e and r.branch_id=b and r.id=p) then
  raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
 if x is not null and exists(select 1 from projects.expenses where id=x) and not exists(select 1 from projects.expenses z
  where z.tenant_id=t and z.legal_entity_id=e and z.branch_id=b and z.project_id=p and z.id=x) then
  raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
end $$;
-- Service tickets recheck the actual human's current membership, scope, both
-- entitlements and MFA. Service credentials never stand in for human authority.
create function expense_private.user_has(t uuid,e uuid,b uuid,u uuid,cap text,aal text) returns boolean
language sql stable security definer set search_path='' as $$
 select aal='aal2' and exists(select 1 from core.memberships m join core.role_assignments a
  on a.tenant_id=m.tenant_id and a.membership_id=m.id join core.roles r on r.tenant_id=a.tenant_id and r.id=a.role_id
  join core.role_permissions rp on rp.tenant_id=r.tenant_id and rp.role_id=r.id
  where m.tenant_id=t and m.user_id=u and m.status='active' and rp.permission_code=cap
  and(a.legal_entity_id is null or a.legal_entity_id=e) and(a.branch_id is null or a.branch_id=b))
 and not exists(select 1 from unnest(array['module.projects','module.finance']) required where not exists(
  select 1 from billing.tenant_subscriptions s join billing.plan_entitlements pe on pe.plan_code=s.plan_code
  where s.tenant_id=t and pe.entitlement_code=required and pe.enabled and
  ((s.status='active' and(s.current_period_ends_at is null or s.current_period_ends_at>now())) or(s.status='trialing' and s.trial_ends_at>now()))))
 and exists(select 1 from core.tenants where id=t and status in('trial','active'))
 and exists(select 1 from core.legal_entities where tenant_id=t and id=e and status='active')
 and exists(select 1 from core.branches where tenant_id=t and legal_entity_id=e and id=b and status='active')
$$;
create function expense_private.service_only() returns void language plpgsql stable set search_path='' as $$begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception using errcode='42501',message='EXPENSE_TRUSTED_SERVICE_REQUIRED';end if;
end $$;
create function expense_private.ready(t uuid,e uuid,w boolean default false) returns void language plpgsql stable security definer set search_path='' as $$begin
 if not exists(select 1 from expense_private.policies where tenant_id=t and legal_entity_id=e) then
  raise exception using errcode='55000',message='EXPENSE_RETENTION_POLICY_REQUIRED';end if;
 if w and not exists(select 1 from expense_private.worker_readiness where contract='w4-expense-evidence-v1' and verified_at>now()-interval '26 hours') then
  raise exception using errcode='55000',message='EXPENSE_RETENTION_WORKER_UNAVAILABLE';end if;
end $$;
create function expense_private.proof(d expense_private.documents) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('id',d.id,'version',d.content_version,'digest',d.digest) $$;
create function expense_private.summary(d expense_private.documents) returns jsonb language sql immutable set search_path='' as $$
 select expense_private.proof(d)||jsonb_build_object('record_version',d.version,'status',d.status,'purpose',d.purpose,
  'mime',d.mime,'byte_size',d.byte_size,'checksum',d.checksum,'policy_id',d.policy_id,'retired_at',d.retired_at,
  'purge_after',d.purge_after,'hold_review_date',d.hold_review_date) $$;

-- Owner-only integration: empty evidence is explicit and remains valid for
-- synthetic narrative fixtures. Real proofs cannot be inferred from text/URLs.
create function projects.expense_evidence_assert(t uuid,e uuid,b uuid,p uuid,x uuid,proofs jsonb,mode text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v jsonb;d expense_private.documents%rowtype;outcome jsonb:='[]';seen uuid[]:='{}';begin
 if mode not in('freeze','read','decision') or jsonb_typeof(proofs) is distinct from 'array' or jsonb_array_length(proofs)>10 then
  raise exception using errcode='22023',message='EXPENSE_EVIDENCE_PROOF_INVALID';end if;
 perform projects.finance_access(t,e,b,'projects.cost.view',true);
 perform expense_private.lock_scope(t,e);
 if jsonb_array_length(proofs)=0 then return '[]';end if;
 perform expense_private.require_access(t,e,b,p,x,case when mode='freeze' then 'projects.expenses.manage' else 'projects.expenses.evidence.view' end);
 perform expense_private.ready(t,e,mode<>'read');
 for v in select value from jsonb_array_elements(proofs) loop
  if jsonb_typeof(v) is distinct from 'object' or not(v ?& array['id','version','digest'])
   or exists(select 1 from jsonb_object_keys(v) k where k<>all(array['id','version','digest']))
   or jsonb_typeof(v->'version') is distinct from 'number' or v->>'version'<>'1' or v->>'digest'!~'^[a-f0-9]{64}$' then
   raise exception using errcode='22023',message='EXPENSE_EVIDENCE_PROOF_INVALID';end if;
  if(v->>'id')::uuid=any(seen) then raise exception using errcode='22023',message='EXPENSE_EVIDENCE_PROOF_INVALID';end if;
  seen:=array_append(seen,(v->>'id')::uuid);
  select * into d from expense_private.documents where id=(v->>'id')::uuid and tenant_id=t and legal_entity_id=e
   and branch_id=b and project_id=p and expense_id=x for share;
  if d.id is null or expense_private.proof(d) is distinct from v then raise exception using errcode='40001',message='EXPENSE_EVIDENCE_CONFLICT';end if;
  -- Historical financial reads retain the original proof after an authorized
  -- retention purge; byte delivery and new decisions still require active data.
  if (mode='read' and d.status not in('active','retired','purging','purged')) or(mode<>'read' and d.status<>'active') then
   raise exception using errcode='55000',message='EXPENSE_EVIDENCE_CONTENT_UNAVAILABLE';end if;
  outcome:=outcome||jsonb_build_array(expense_private.proof(d));
 end loop;
 return(select coalesce(jsonb_agg(value order by value->>'id'),'[]') from jsonb_array_elements(outcome));
exception when invalid_text_representation then raise exception using errcode='22023',message='EXPENSE_EVIDENCE_PROOF_INVALID';
end $$;
create function api.projects_expense_evidence_access(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_project_id uuid,p_expense_id uuid,p_capability text default 'projects.expenses.evidence.view')
returns jsonb language plpgsql security definer set search_path='' as $$begin
 perform expense_private.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_project_id,p_expense_id,p_capability);
 if p_project_id is null and p_capability='projects.expenses.retention.manage' then
  perform core.wave3_require_scope(p_tenant_id,'projects.expenses.retention.manage',p_legal_entity_id,null);end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'project_id',p_project_id,
  'expense_id',p_expense_id,'actor_id',auth.uid(),'authorized',true,'available',exists(select 1 from expense_private.policies where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id)
  and exists(select 1 from expense_private.worker_readiness where contract='w4-expense-evidence-v1' and verified_at>now()-interval '26 hours'));
end $$;
create function api.projects_expense_evidence_list(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_project_id uuid,p_expense_id uuid,p_after uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$declare rows jsonb;begin
 perform expense_private.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_project_id,p_expense_id,'projects.expenses.evidence.view');
 select coalesce(jsonb_agg(expense_private.summary(d) order by d.id),'[]') into rows from(select * from expense_private.documents
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and project_id=p_project_id and expense_id=p_expense_id
  and(p_after is null or id>p_after) order by id limit 51) d;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'project_id',p_project_id,
  'expense_id',p_expense_id,'items',rows-50,'next_after',case when jsonb_array_length(rows)>50 then rows->49->>'id' end);
end $$;

create function api.projects_expense_evidence_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_issued_at timestamptz,p_payload jsonb,p_expected_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare act text:=p_payload->>'action';id uuid:=(p_payload->>'id')::uuid;p uuid:=(p_payload->>'project_id')::uuid;x uuid:=(p_payload->>'expense_id')::uuid;
 cap text;allowed text[];hash text;replay jsonb;result jsonb;d expense_private.documents%rowtype;policy expense_private.policies%rowtype;body jsonb;v_digest text;reason text;begin
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>8192 or id is null or p_command_id is null or p_idempotency_key is null
  or p_issued_at is null or p_issued_at>clock_timestamp()+interval '5 minutes' or p_expected_version is null or p_expected_version not between 0 and 9007199254740990 then
  raise exception using errcode='22023',message='EXPENSE_EVIDENCE_COMMAND_INVALID';end if;
 cap:=case when act in('policy_create','hold','release_hold','retire') then 'projects.expenses.retention.manage'
  when act in('reserve','complete') then 'projects.expenses.manage' end;
 allowed:=case act when 'policy_create' then array['action','id','retention_days','purpose']
  when 'reserve' then array['action','id','project_id','expense_id','mime','byte_size','checksum','purpose']
  when 'complete' then array['action','id','project_id','expense_id']
  when 'hold' then array['action','id','project_id','expense_id','reason','review_date']
  when 'release_hold' then array['action','id','project_id','expense_id','reason']
  when 'retire' then array['action','id','project_id','expense_id','reason'] end;
 if cap is null or exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(allowed)) or(act<>'policy_create' and(p is null or x is null)) then
  raise exception using errcode='22023',message='EXPENSE_EVIDENCE_FIELDS_INVALID';end if;
 perform expense_private.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p,x,cap);
 if act='policy_create' then perform core.wave3_require_scope(p_tenant_id,'projects.expenses.retention.manage',p_legal_entity_id,null);end if;
 perform expense_private.lock_scope(p_tenant_id,p_legal_entity_id);
 perform expense_private.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p,x,cap);
 if act='policy_create' then perform core.wave3_require_scope(p_tenant_id,'projects.expenses.retention.manage',p_legal_entity_id,null);end if;
 if act<>'policy_create' then perform expense_private.ready(p_tenant_id,p_legal_entity_id,act in('reserve','complete'));end if;
 hash:=core.wave3_request_hash('projects.expense_evidence.'||act,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 -- Mutable permissions and worker readiness were checked before receipt replay.
 replay:=core.wave3_replay(p_tenant_id,'projects.expense_evidence.'||act,p_command_id,p_idempotency_key,hash);if replay is not null then return replay;end if;
 if act='policy_create' then
  if p_expected_version<>0 or jsonb_typeof(p_payload->'retention_days') is distinct from 'number' or p_payload->>'retention_days'!~'^[0-9]+$'
   or(p_payload->>'retention_days')::numeric not between 1 and 3650 or exists(select 1 from expense_private.policies where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id) then
   raise exception using errcode='22023',message='EXPENSE_RETENTION_POLICY_INVALID';end if;
  insert into expense_private.policies(id,tenant_id,legal_entity_id,retention_days,purpose,created_by)
  values(id,p_tenant_id,p_legal_entity_id,(p_payload->>'retention_days')::integer,projects.text(p_payload->'purpose',160),auth.uid());
  result:=jsonb_build_object('id',id,'version',1,'action',act);
 else
  select * into policy from expense_private.policies where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id;
  select * into d from expense_private.documents where documents.id=id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and project_id=p and expense_id=x for update;
  if act='reserve' then
   if p_expected_version<>0 or d.id is not null or p_payload->>'mime' not in('text/plain','image/png','image/jpeg','application/pdf')
    or jsonb_typeof(p_payload->'byte_size') is distinct from 'number' or p_payload->>'byte_size'!~'^[0-9]+$'
    or(p_payload->>'byte_size')::numeric not between 1 and 10485760 or p_payload->>'checksum'!~'^[a-f0-9]{64}$'
    or p_payload->>'mime' is null or p_payload->>'checksum' is null then raise exception using errcode='22023',message='EXPENSE_EVIDENCE_METADATA_INVALID';end if;
   if(select count(*) from expense_private.documents where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and project_id=p and expense_id=x and status<>'purged')>=10 then
    raise exception using errcode='55000',message='EXPENSE_EVIDENCE_DOCUMENT_LIMIT';end if;
   if exists(select 1 from projects.expenses where expenses.id=x and status not in('draft','rejected')) then raise exception using errcode='55000',message='EXPENSE_EVIDENCE_SOURCE_IMMUTABLE';end if;
   body:=jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,'project_id',p,'expense_id',x,
    'id',id,'version',1,'mime',p_payload->>'mime','byte_size',(p_payload->>'byte_size')::integer,'checksum',p_payload->>'checksum','policy_id',policy.id);
   v_digest:=encode(extensions.hmac(convert_to(body::text,'UTF8'),policy.digest_key,'sha256'),'hex');
   insert into expense_private.documents(id,tenant_id,legal_entity_id,branch_id,project_id,expense_id,policy_id,digest,mime,byte_size,checksum,purpose,created_by)
    values(id,p_tenant_id,p_legal_entity_id,p_branch_id,p,x,policy.id,v_digest,p_payload->>'mime',(p_payload->>'byte_size')::integer,p_payload->>'checksum',projects.text(p_payload->'purpose',160),auth.uid()) returning * into d;
  else
   if d.id is null or d.version<>p_expected_version then raise exception using errcode='40001',message='EXPENSE_EVIDENCE_CONFLICT';end if;
   if d.status in('purging','purged') then raise exception using errcode='55000',message='EXPENSE_EVIDENCE_CONTENT_UNAVAILABLE';end if;
   if act='complete' then
    if d.status<>'verified' or d.verified_at is null then raise exception using errcode='55000',message='EXPENSE_EVIDENCE_VERIFICATION_REQUIRED';end if;
    update expense_private.documents set status='active',version=version+1,activated_at=clock_timestamp() where documents.id=id returning * into d;
   elsif act='hold' then
    reason:=projects.text(p_payload->'reason',1000);
    if(p_payload->>'review_date')::date<current_date or(p_payload->>'review_date')::date>current_date+366 or p_payload->>'review_date' is null then
     raise exception using errcode='22023',message='EXPENSE_RETENTION_HOLD_INVALID';end if;
    update expense_private.documents set hold_reason=reason,hold_review_date=(p_payload->>'review_date')::date,version=version+1 where documents.id=id returning * into d;
   elsif act='release_hold' then
    reason:=projects.text(p_payload->'reason',1000);
    if d.hold_reason is null then raise exception using errcode='55000',message='EXPENSE_RETENTION_HOLD_REQUIRED';end if;
    update expense_private.documents set hold_reason=null,hold_review_date=null,version=version+1 where documents.id=id returning * into d;
   elsif act='retire' then
    reason:=projects.text(p_payload->'reason',1000);
    if d.status not in('reserved','verified','active') or not exists(select 1 from projects.expenses z where z.id=x and z.tenant_id=p_tenant_id
     and z.legal_entity_id=p_legal_entity_id and z.branch_id=p_branch_id and z.project_id=p and z.status in('cancelled','rejected','reversed')) then
     raise exception using errcode='55000',message='EXPENSE_FINANCIAL_RETENTION_REQUIRED';end if;
    update expense_private.documents set status='retired',version=version+1,retired_at=clock_timestamp(),purge_after=clock_timestamp()+make_interval(days=>policy.retention_days)
     where documents.id=id returning * into d;
   end if;
  end if;
  insert into expense_private.events(tenant_id,legal_entity_id,document_id,action,version,reason,actor_id)
   values(p_tenant_id,p_legal_entity_id,id,act,d.version,reason,auth.uid());
  result:=expense_private.proof(d)||jsonb_build_object('record_version',d.version,'status',d.status,'project_id',p,'expense_id',x,'action',act);
 end if;
 result:=result||jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id);
 return core.wave3_finish_command(p_tenant_id,'projects.expense_evidence.'||act,p_command_id,'projects.expense_evidence',id,p_idempotency_key,hash,'{}',result,p_legal_entity_id,p_branch_id);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
 raise exception using errcode='22023',message='EXPENSE_EVIDENCE_FIELDS_INVALID';
end $$;

create function api.projects_expense_evidence_ticket(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_project_id uuid,p_expense_id uuid,p_document_id uuid,p_operation text)
returns jsonb language plpgsql security definer set search_path='' as $$declare d expense_private.documents%rowtype;ticket uuid;begin
 if p_operation not in('upload','download','export') or p_operation is null then raise exception using errcode='22023',message='EXPENSE_EVIDENCE_OPERATION_INVALID';end if;
 perform expense_private.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_project_id,p_expense_id,
  case when p_operation='upload' then 'projects.expenses.manage' when p_operation='export' then 'projects.expenses.evidence.export' else 'projects.cost.view' end);
 perform expense_private.lock_scope(p_tenant_id,p_legal_entity_id);
 perform expense_private.ready(p_tenant_id,p_legal_entity_id,p_operation='upload');
 select * into d from expense_private.documents where id=p_document_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and branch_id=p_branch_id and project_id=p_project_id and expense_id=p_expense_id for share;
 if d.id is null or(p_operation='upload' and d.status not in('reserved','verified','active')) or(p_operation<>'upload' and d.status<>'active') then
  raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
 insert into expense_private.tickets(document_id,user_id,operation,issued_aal) values(d.id,auth.uid(),p_operation,coalesce(auth.jwt()->>'aal','aal1')) returning id into ticket;
 return jsonb_build_object('ticket_id',ticket,'expires_at',clock_timestamp()+interval '30 seconds');
end $$;
create function api.projects_expense_evidence_own_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$declare r core.command_receipts%rowtype;act text;cap text;begin
 perform projects.finance_access(p_tenant_id,p_legal_entity_id,p_branch_id,'projects.cost.view',true);
 select * into r from core.command_receipts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and actor_id=auth.uid() and command_id=p_command_id and command_name like 'projects.expense_evidence.%';
 if r.command_id is null then return null;end if;
 act:=r.response->'entity'->>'action';
 cap:=case when act in('policy_create','hold','release_hold','retire') then 'projects.expenses.retention.manage' else 'projects.expenses.manage' end;
 perform expense_private.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,(r.response->'entity'->>'project_id')::uuid,
  (r.response->'entity'->>'expense_id')::uuid,cap);
 if act='policy_create' then perform core.wave3_require_scope(p_tenant_id,'projects.expenses.retention.manage',p_legal_entity_id,null);end if;
 if act in('reserve','complete') then perform expense_private.ready(p_tenant_id,p_legal_entity_id,true);end if;
 return r.response;
end $$;
create function expense_private.ticket_authority(v expense_private.tickets,d expense_private.documents,u uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if v.id is null or d.id is null or v.user_id is distinct from u or not expense_private.user_has(d.tenant_id,d.legal_entity_id,d.branch_id,u,'projects.view',v.issued_aal)
  or not expense_private.user_has(d.tenant_id,d.legal_entity_id,d.branch_id,u,'projects.cost.view',v.issued_aal)
  or not expense_private.user_has(d.tenant_id,d.legal_entity_id,d.branch_id,u,'projects.expenses.evidence.view',v.issued_aal)
  or not expense_private.user_has(d.tenant_id,d.legal_entity_id,d.branch_id,u,
   case when v.operation='upload' then 'projects.expenses.manage' when v.operation='export' then 'projects.expenses.evidence.export' else 'projects.cost.view' end,v.issued_aal)
  or not exists(select 1 from projects.register where tenant_id=d.tenant_id and legal_entity_id=d.legal_entity_id and branch_id=d.branch_id and id=d.project_id) then
  raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
end $$;
create function api.projects_expense_evidence_service_document(p_ticket_id uuid,p_user_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare v expense_private.tickets%rowtype;d expense_private.documents%rowtype;begin
 perform expense_private.service_only();
 select * into v from expense_private.tickets where id=p_ticket_id;select * into d from expense_private.documents where id=v.document_id;
 perform expense_private.lock_scope(d.tenant_id,d.legal_entity_id);
 select * into v from expense_private.tickets where id=p_ticket_id for update;select * into d from expense_private.documents where id=v.document_id for share;
 perform expense_private.ticket_authority(v,d,p_user_id);
 if v.expires_at<=clock_timestamp() or v.consumed_at is not null or(v.operation='upload' and d.status not in('reserved','verified','active'))
  or(v.operation<>'upload' and d.status<>'active') then raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
 perform expense_private.ready(d.tenant_id,d.legal_entity_id,v.operation='upload');
 update expense_private.tickets set consumed_at=clock_timestamp() where id=p_ticket_id;
 return expense_private.summary(d)||jsonb_build_object('ticket_id',v.id,'document_id',d.id,'tenant_id',d.tenant_id,'legal_entity_id',d.legal_entity_id,
  'branch_id',d.branch_id,'project_id',d.project_id,'expense_id',d.expense_id,'operation',v.operation,
  'object_path',d.tenant_id||'/'||d.legal_entity_id||'/'||d.project_id||'/'||d.expense_id||'/'||d.id);
end $$;
create function api.projects_expense_evidence_service_verify(p_ticket_id uuid,p_user_id uuid,p_checksum text,p_byte_size integer) returns jsonb
language plpgsql security definer set search_path='' as $$declare v expense_private.tickets%rowtype;d expense_private.documents%rowtype;begin
 perform expense_private.service_only();select * into v from expense_private.tickets where id=p_ticket_id;select * into d from expense_private.documents where id=v.document_id;
 perform expense_private.lock_scope(d.tenant_id,d.legal_entity_id);
 select * into v from expense_private.tickets where id=p_ticket_id for update;select * into d from expense_private.documents where id=v.document_id for update;
 perform expense_private.ticket_authority(v,d,p_user_id);
 if v.operation<>'upload' or v.consumed_at is null or v.expires_at+interval '2 minutes'<=clock_timestamp() or d.status not in('reserved','verified','active') then
  raise exception using errcode='42501',message='EXPENSE_EVIDENCE_DENIED';end if;
 perform expense_private.ready(d.tenant_id,d.legal_entity_id,true);
 if d.checksum is distinct from p_checksum or d.byte_size is distinct from p_byte_size then raise exception using errcode='22023',message='EXPENSE_EVIDENCE_BYTES_MISMATCH';end if;
 if d.status='reserved' then update expense_private.documents set status='verified',verified_at=clock_timestamp() where id=d.id;end if;
 update expense_private.tickets set verified_at=clock_timestamp() where id=p_ticket_id;return jsonb_build_object('verified',true);
end $$;
create function api.projects_expense_evidence_worker_register(p_artifact_digest text,p_storage_probe_digest text) returns jsonb language plpgsql security definer set search_path='' as $$begin
 perform expense_private.service_only();
 if p_artifact_digest is null or p_storage_probe_digest is null or p_artifact_digest!~'^[a-f0-9]{64}$' or p_storage_probe_digest!~'^[a-f0-9]{64}$' then
  raise exception using errcode='22023',message='EXPENSE_WORKER_PROOF_INVALID';end if;
 insert into expense_private.worker_readiness(contract,artifact_digest,storage_probe_digest) values('w4-expense-evidence-v1',p_artifact_digest,p_storage_probe_digest)
 on conflict(contract) do update set artifact_digest=excluded.artifact_digest,storage_probe_digest=excluded.storage_probe_digest,verified_at=clock_timestamp();
 return jsonb_build_object('contract','w4-expense-evidence-v1','ready',true);
end $$;
create function api.projects_expense_evidence_worker_claim(p_limit integer default 50) returns jsonb language plpgsql security definer set search_path='' as $$
declare candidate record;d expense_private.documents%rowtype;j expense_private.purge_jobs%rowtype;lease uuid;items jsonb:='[]';begin
 perform expense_private.service_only();
 if p_limit is null or p_limit not between 1 and 50 then raise exception using errcode='22023',message='EXPENSE_WORKER_LIMIT';end if;
 if not exists(select 1 from expense_private.worker_readiness where verified_at>now()-interval '26 hours') then
  raise exception using errcode='55000',message='EXPENSE_RETENTION_WORKER_UNAVAILABLE';end if;
 -- Bound the scan as well as response. No document lock precedes entity locks.
 for candidate in select id,tenant_id,legal_entity_id from expense_private.documents where hold_reason is null and
  ((status='retired' and purge_after<=clock_timestamp()) or(status in('reserved','verified') and created_at<clock_timestamp()-interval '24 hours') or status='purging')
  order by tenant_id,legal_entity_id,id limit 50 loop
  exit when jsonb_array_length(items)>=p_limit;
  perform expense_private.lock_scope(candidate.tenant_id,candidate.legal_entity_id);
  select * into d from expense_private.documents where id=candidate.id for update skip locked;
  if d.id is null or d.hold_reason is not null or not((d.status='retired' and d.purge_after<=clock_timestamp())
   or(d.status in('reserved','verified') and d.created_at<clock_timestamp()-interval '24 hours') or d.status='purging') then continue;end if;
  if exists(select 1 from projects.expenses z where z.id=d.expense_id and z.status not in('cancelled','rejected','reversed')) then continue;end if;
  insert into expense_private.purge_jobs(document_id) values(d.id) on conflict(document_id) do nothing;
  select * into j from expense_private.purge_jobs where document_id=d.id for update;
  if j.status='complete' or j.lease_until>clock_timestamp() then continue;end if;
  lease:=gen_random_uuid();update expense_private.purge_jobs set lease_id=lease,lease_until=clock_timestamp()+interval '30 minutes' where id=j.id;
  if d.status<>'purging' then update expense_private.documents set status='purging',version=version+1 where id=d.id;end if;
  items:=items||jsonb_build_array(jsonb_build_object('job_id',j.id,'lease_id',lease,'object_paths',jsonb_build_array(
   d.tenant_id||'/'||d.legal_entity_id||'/'||d.project_id||'/'||d.expense_id||'/'||d.id)));
 end loop;
 delete from expense_private.tickets where id in(select id from expense_private.tickets where expires_at<now()-interval '3 minutes' order by expires_at limit 500);
 return jsonb_build_object('items',items);
end $$;
create function api.projects_expense_evidence_worker_complete(p_job_id uuid,p_lease_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare j expense_private.purge_jobs%rowtype;d expense_private.documents%rowtype;begin
 perform expense_private.service_only();select * into j from expense_private.purge_jobs where id=p_job_id;select * into d from expense_private.documents where id=j.document_id;
 perform expense_private.lock_scope(d.tenant_id,d.legal_entity_id);
 select * into d from expense_private.documents where id=j.document_id for update;select * into j from expense_private.purge_jobs where id=p_job_id for update;
 if j.id is null or j.status<>'pending' or j.lease_id is distinct from p_lease_id or j.lease_until<=clock_timestamp() or d.status<>'purging' or d.hold_reason is not null then
  raise exception using errcode='42501',message='EXPENSE_WORKER_LEASE_INVALID';end if;
 update expense_private.documents set status='purged',version=version+1,purged_at=clock_timestamp() where id=d.id;
 insert into expense_private.events(tenant_id,legal_entity_id,document_id,action,version) values(d.tenant_id,d.legal_entity_id,d.id,'purged',d.version+1);
 update expense_private.purge_jobs set status='complete',completed_at=clock_timestamp(),lease_until=null where id=j.id;
 return jsonb_build_object('job_id',j.id,'complete',true);
end $$;
do $$declare v record;begin
 for v in select tablename from pg_tables where schemaname='expense_private' loop
  execute format('alter table expense_private.%I enable row level security',v.tablename);
  execute format('alter table expense_private.%I force row level security',v.tablename);
  execute format('revoke all on expense_private.%I from public,anon,authenticated,service_role',v.tablename);
 end loop;
 for v in select p.oid::regprocedure fn,p.proname,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='expense_private' or(n.nspname='api' and p.proname like 'projects_expense_evidence_%')
  or(n.nspname='projects' and p.proname='expense_evidence_assert') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',v.fn);
  if v.nspname='api' then
   if v.proname like 'projects_expense_evidence_worker_%' or v.proname like 'projects_expense_evidence_service_%' then
    execute format('grant execute on function %s to service_role',v.fn);
   else execute format('grant execute on function %s to authenticated',v.fn);end if;
  end if;
 end loop;
end $$;

-- Additive UNAPPLIED candidate. Uses the installed immutable CRM history.
-- No source history, entitlements, role assignments or acceptance fixtures seeded.
create function api.wave5_pipeline_history(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_as_of timestamptz,p_recorded_through timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare rows jsonb;n integer;result jsonb;begin
 perform analytics.pipeline_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_as_of is null or p_recorded_through is null or not isfinite(p_as_of) or not isfinite(p_recorded_through)
  or p_as_of>p_recorded_through or p_recorded_through>statement_timestamp() then
  raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if exists(select 1 from crm.opportunities o where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id
  and (p_branch_id is null or o.branch_id=p_branch_id) and o.created_at<=p_as_of
  and not exists(select 1 from crm.pipeline_history h where h.tenant_id=o.tenant_id and h.entity_type='opportunity'
   and h.entity_id=o.id and h.recorded_at<=p_as_of and h.recorded_at<=p_recorded_through)) then
  raise exception using errcode='55000',message='HISTORY_COHORT_INCOMPLETE';end if;
 -- Retain all revisions up to the cutoff: a last-known row alone cannot certify
 -- stage entry. Recheck each historical branch, including a later scope move.
 select coalesce(jsonb_agg(jsonb_build_object('id',h.entity_id,'revisionId',h.id,'version',h.version::text,
  'tenantId',h.tenant_id,'legalEntityId',h.legal_entity_id,'branchId',h.branch_id,
  'recordedAt',analytics.process_utc(h.recorded_at),'createdAt',analytics.process_utc((h.snapshot->>'created_at')::timestamptz),
  'stage',h.snapshot->>'stage','status',h.snapshot->>'status','ownerId',h.snapshot->>'owner_id',
  'amount',h.snapshot->>'expected_value','probability',h.snapshot->>'probability',
  'currency',h.snapshot->>'currency_code') order by h.entity_id,h.version),'[]'),count(*) into rows,n
 from (select h.* from crm.pipeline_history h where h.tenant_id=p_tenant_id and h.legal_entity_id=p_legal_entity_id
  and h.entity_type='opportunity' and h.recorded_at<=p_as_of and h.recorded_at<=p_recorded_through
  and exists(select 1 from crm.pipeline_history selected where selected.tenant_id=h.tenant_id
   and selected.entity_type=h.entity_type and selected.entity_id=h.entity_id and selected.recorded_at<=p_as_of
   and selected.recorded_at<=p_recorded_through and (p_branch_id is null or selected.branch_id=p_branch_id))
  order by h.entity_id,h.version limit 10001) h;
 if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 if exists(select 1 from jsonb_array_elements(rows) r group by r->>'id'
  having min((r->>'version')::bigint)<>1 or count(*)<>max((r->>'version')::bigint)) then
  raise exception using errcode='55000',message='HISTORY_REVISION_GAP';end if;
 if exists(select 1 from jsonb_array_elements(rows) r where
  not (core.has_permission(p_tenant_id,'crm.opportunities.view',p_legal_entity_id,(r->>'branchId')::uuid)
   or core.has_permission(p_tenant_id,'crm.opportunities.manage',p_legal_entity_id,(r->>'branchId')::uuid))) then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 result:=jsonb_build_object('contractRevision',1,'sourceContract','crm.pipeline_history.v1',
  'scope',jsonb_build_object('tenantId',p_tenant_id,'legalEntityId',p_legal_entity_id,'branchId',p_branch_id),
  'asOf',analytics.process_utc(p_as_of),'recordedThrough',analytics.process_utc(p_recorded_through),
  'complete',true,'revisions',rows);
 if octet_length(result::text)>8388608 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 return jsonb_build_object('canonicalText',result::text,'sourceHash',encode(extensions.digest(result::text,'sha256'),'hex'));
end $$;
revoke all on function api.wave5_pipeline_history(uuid,uuid,uuid,timestamptz,timestamptz) from public,anon,authenticated;
grant execute on function api.wave5_pipeline_history(uuid,uuid,uuid,timestamptz,timestamptz) to authenticated;

-- Realized result is explicitly posted invoice gross less posted credit-return
-- gross, grouped in original transaction currency. It is not ledger revenue.
create function api.wave5_pipeline_realized(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_forecast_id uuid,p_as_of timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare f jsonb;rows jsonb;n integer;begin
 f:=api.get_pipeline_forecast(p_tenant_id,p_legal_entity_id,p_branch_id,p_forecast_id);
 perform core.wave3_require_scope(p_tenant_id,'finance.receivables.view',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'sales.returns.view',p_legal_entity_id,p_branch_id);
 if p_as_of is null or not isfinite(p_as_of) or p_as_of>statement_timestamp()
  or p_as_of<(f#>>'{evidence,asOf}')::timestamptz then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if p_as_of<(f#>>'{evidence,horizonEnd}')::date::timestamptz then
  raise exception using errcode='55000',message='REALIZED_HORIZON_OPEN';end if;
 if (f#>>'{evidence,asOf}')::timestamptz>=(f#>>'{evidence,horizonEnd}')::date::timestamptz then
  raise exception using errcode='55000',message='FORECAST_NOT_PROSPECTIVE';end if;
 with cohort as (select (x->>'id')::uuid id from jsonb_array_elements(f#>'{evidence,observations}') x),
 documents as (
  select i.id,(o.source_snapshot->>'opportunity_id')::uuid opportunity_id,i.branch_id,i.currency_code,i.grand_total amount,i.version,'invoice' kind,i.posted_at
  from sales.sales_invoices i join sales.sales_orders o on o.tenant_id=i.tenant_id and o.id=i.sales_order_id
  join cohort c on c.id=(o.source_snapshot->>'opportunity_id')::uuid
  where i.tenant_id=p_tenant_id and i.legal_entity_id=p_legal_entity_id and (p_branch_id is null or i.branch_id=p_branch_id)
   and i.status='posted' and i.posted_at<=p_as_of and i.document_date>=(f#>>'{evidence,horizonStart}')::date
   and i.document_date<(f#>>'{evidence,horizonEnd}')::date
  union all
  select r.id,(o.source_snapshot->>'opportunity_id')::uuid,r.branch_id,r.currency_code,-r.grand_total,r.version,'credit_return',r.posted_at
  from sales.sales_returns r join sales.sales_orders o on o.tenant_id=r.tenant_id and o.id=r.sales_order_id
  join cohort c on c.id=(o.source_snapshot->>'opportunity_id')::uuid
  where r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and (p_branch_id is null or r.branch_id=p_branch_id)
   and r.status='posted' and r.posted_at<=p_as_of and r.document_date>=(f#>>'{evidence,horizonStart}')::date
   and r.document_date<(f#>>'{evidence,horizonEnd}')::date
 ) select coalesce(jsonb_agg(jsonb_build_object('id',id,'opportunityId',opportunity_id,'branchId',branch_id,
  'currency',currency_code,'amount',amount::text,'version',version::text,'kind',kind,'postedAt',analytics.process_utc(posted_at)) order by id),'[]'),count(*)
 into rows,n from (select * from documents order by id limit 10001) d;
 if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 -- A line-linked return without an order header can affect the frozen cohort.
 -- Until an exact header/line apportionment exists, do not report a partial zero.
 if exists(select 1 from sales.sales_returns r join sales.sales_return_lines l on l.tenant_id=r.tenant_id and l.document_id=r.id
  join sales.sales_invoice_lines il on il.tenant_id=l.tenant_id and il.id=l.sales_invoice_line_id
  join sales.sales_invoices i on i.tenant_id=il.tenant_id and i.id=il.document_id
  join sales.sales_orders o on o.tenant_id=i.tenant_id and o.id=i.sales_order_id
  where r.tenant_id=p_tenant_id and r.legal_entity_id=p_legal_entity_id and (p_branch_id is null or r.branch_id=p_branch_id)
   and r.sales_order_id is null and r.status='posted' and r.posted_at<=p_as_of
   and r.document_date>=(f#>>'{evidence,horizonStart}')::date and r.document_date<(f#>>'{evidence,horizonEnd}')::date
   and exists(select 1 from jsonb_array_elements(f#>'{evidence,observations}') x where x->>'id'=o.source_snapshot->>'opportunity_id')) then
  raise exception using errcode='55000',message='REALIZED_MAPPING_INCOMPLETE';end if;
 if exists(select 1 from jsonb_array_elements(rows) r where
  not core.has_permission(p_tenant_id,'finance.receivables.view',p_legal_entity_id,(r->>'branchId')::uuid)
  or not core.has_permission(p_tenant_id,'sales.returns.view',p_legal_entity_id,(r->>'branchId')::uuid)) then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 return jsonb_build_object('contractRevision',1,'forecastId',p_forecast_id,'sourceHash',f->>'sourceHash',
  'definition','posted_invoice_less_order_linked_credit_gross.v1','asOf',analytics.process_utc(p_as_of),'complete',true,'documents',rows);
end $$;
revoke all on function api.wave5_pipeline_realized(uuid,uuid,uuid,uuid,timestamptz) from public,anon,authenticated;
grant execute on function api.wave5_pipeline_realized(uuid,uuid,uuid,uuid,timestamptz) to authenticated;

-- UNAPPLIED synthetic-development candidate. No hosts, keys, credentials,
-- subscriptions, worker deployment or entitlement activation are provisioned.
insert into core.permissions(code,module,description,privileged) values
 ('integrations.manage','integrations','Manage scoped reviewed integrations',true)
 on conflict(code) do nothing;
create table intelligence_control.integration_hosts(hostname text primary key,
 check(hostname ~ '^[a-z0-9][a-z0-9.-]{1,250}[a-z0-9]$'));
create table intelligence_control.integration_subscriptions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid,
 created_by uuid not null references auth.users(id),url text not null,hostname text not null references intelligence_control.integration_hosts,
 version bigint not null default 1,key_version integer not null default 1,key_ref text not null,
 enabled boolean not null default true,created_at timestamptz not null default statement_timestamp(),
 unique(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(version>0 and key_version>0 and key_ref ~ '^[a-zA-Z0-9_/-]{1,180}$'),
 check(url ~ '^https://[^/@:#?]+(:443)?(/[^#]*)?$' and length(url)<=2048));
create table intelligence_control.integration_changes(
 id uuid primary key,tenant_id uuid not null,subscription_id uuid not null,version bigint not null,
 actor_id uuid not null references auth.users(id),action text not null,evidence jsonb not null,
 recorded_at timestamptz not null default statement_timestamp(),unique(tenant_id,subscription_id,version),
 foreign key(tenant_id,subscription_id) references intelligence_control.integration_subscriptions(tenant_id,id));
create table intelligence_control.delivery_heads(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,subscription_id uuid not null,event_id uuid not null references core.outbox_events(id),
 invocation_id uuid not null default gen_random_uuid(),usage_event_id uuid not null default gen_random_uuid(),
 attempt integer not null default 0 check(attempt between 0 and 8),state text not null default 'pending'
 check(state in('pending','leased','retry','unknown','acknowledged','dead_letter')),
 available_at timestamptz not null default statement_timestamp(),lease_id uuid,lease_until timestamptz,
 period_start timestamptz,period_end timestamptz,generation integer not null default 0 check(generation>=0),replay_of uuid,
 unique(tenant_id,subscription_id,event_id,generation),unique(tenant_id,id),
 foreign key(tenant_id,replay_of) references intelligence_control.delivery_heads(tenant_id,id),
 foreign key(tenant_id,subscription_id) references intelligence_control.integration_subscriptions(tenant_id,id));
create table intelligence_control.delivery_attempts(
 tenant_id uuid not null,delivery_id uuid not null,attempt integer not null,lease_id uuid not null unique,
 key_version integer not null,subscription_version bigint not null,claimed_at timestamptz not null default statement_timestamp(),
 primary key(tenant_id,delivery_id,attempt),foreign key(tenant_id,delivery_id) references intelligence_control.delivery_heads(tenant_id,id));
create table intelligence_control.delivery_outcomes(
 tenant_id uuid not null,delivery_id uuid not null,attempt integer not null,state text not null,
 http_status integer,recorded_at timestamptz not null default statement_timestamp(),
 primary key(tenant_id,delivery_id,attempt),foreign key(tenant_id,delivery_id,attempt)
 references intelligence_control.delivery_attempts(tenant_id,delivery_id,attempt),
 check(state in('acknowledged','retry','unknown','dead_letter')),
 check(http_status is null or http_status between 100 and 599));
create table intelligence_control.delivery_reviews(
 id uuid primary key,tenant_id uuid not null,delivery_id uuid not null,actor_id uuid not null references auth.users(id),
 action text not null check(action in('replay','acknowledged','not_sent')),reason text not null check(length(trim(reason)) between 8 and 500),
 recorded_at timestamptz not null default statement_timestamp(),
 foreign key(tenant_id,delivery_id) references intelligence_control.delivery_heads(tenant_id,id));
do $$declare rel text;begin
 foreach rel in array array['integration_hosts','integration_subscriptions','integration_changes','delivery_heads','delivery_attempts','delivery_outcomes','delivery_reviews'] loop
  execute format('alter table intelligence_control.%I enable row level security',rel);
  execute format('alter table intelligence_control.%I force row level security',rel);
  execute format('revoke all on intelligence_control.%I from public,anon,authenticated',rel);
  if rel not in('integration_subscriptions','delivery_heads') then
   execute format('create trigger immutable before update or delete on intelligence_control.%I for each row execute function analytics.immutable_evidence()',rel);
  end if;
 end loop;
end $$;
create index delivery_ready_idx on intelligence_control.delivery_heads(state,available_at,id);
create index delivery_subscription_idx on intelligence_control.delivery_heads(tenant_id,subscription_id,id);
create index integration_scope_idx on intelligence_control.integration_subscriptions(tenant_id,legal_entity_id,branch_id,id);

create function api.wave5_integration_manage(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_action text,p_id uuid,p_expected_version bigint,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s intelligence_control.integration_subscriptions%rowtype;prior intelligence_control.integration_changes%rowtype;host text;h text;receipt jsonb;begin
 perform analytics.pipeline_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'integrations.manage',p_legal_entity_id,p_branch_id);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='APPROVAL_REQUIRED';end if;
 if p_id is null or p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,58));
 if p_expected_version is null or p_expected_version<0 or p_action is null then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 h:=encode(extensions.digest(jsonb_build_object('scope',jsonb_build_array(p_tenant_id,p_legal_entity_id,p_branch_id),'action',p_action,'payload',p_payload)::text,'sha256'),'hex');
 select * into prior from intelligence_control.integration_changes where tenant_id=p_tenant_id and subscription_id=p_id and version=p_expected_version+1;
 if found then
  if prior.actor_id<>auth.uid() or prior.action<>p_action or prior.evidence->>'requestHash' is distinct from h then
   raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
  return prior.evidence->'receipt';end if;
 if p_action='register' then
  if p_expected_version<>0 or p_expected_version is null or (p_payload-array['url','keyRef'])<>'{}'
   or not(p_payload ?& array['url','keyRef']) or jsonb_typeof(p_payload->'url')<>'string' or jsonb_typeof(p_payload->'keyRef')<>'string' then
   raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
  host:=substring(p_payload->>'url' from '^https://([^/:?#]+)');
  if host is null or not exists(select 1 from intelligence_control.integration_hosts where hostname=host) then
   raise exception using errcode='42501',message='UNREVIEWED_DESTINATION';end if;
  insert into intelligence_control.integration_subscriptions(id,tenant_id,legal_entity_id,branch_id,created_by,url,hostname,key_ref)
   values(p_id,p_tenant_id,p_legal_entity_id,p_branch_id,auth.uid(),p_payload->>'url',host,p_payload->>'keyRef') returning * into s;
 else
  select * into s from intelligence_control.integration_subscriptions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id is not distinct from p_branch_id and id=p_id for update;
  if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
  if s.version is distinct from p_expected_version then raise exception using errcode='40001',message='CONFLICT';end if;
  if p_action='rotate' and (p_payload-'keyRef')='{}' and jsonb_typeof(p_payload->'keyRef')='string' then
   update intelligence_control.integration_subscriptions set key_ref=p_payload->>'keyRef',key_version=key_version+1,version=version+1 where id=p_id returning * into s;
  elsif p_action='revoke' and p_payload='{}' then
   update intelligence_control.integration_subscriptions set enabled=false,version=version+1 where id=p_id returning * into s;
  else raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 end if;
 receipt:=jsonb_build_object('id',s.id,'version',s.version::text,'keyVersion',s.key_version,'enabled',s.enabled);
 insert into intelligence_control.integration_changes values(gen_random_uuid(),p_tenant_id,p_id,s.version,auth.uid(),p_action,
  jsonb_build_object('requestHash',h,'receipt',receipt),statement_timestamp());
 return receipt;
end $$;

create function intelligence_control.delivery_authorize(p_delivery_id uuid,p_lease_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare d intelligence_control.delivery_heads%rowtype;s intelligence_control.integration_subscriptions%rowtype;
 f analytics.pipeline_forecasts%rowtype;a intelligence_control.delivery_attempts%rowtype;saved_claims text;begin
 select * into d from intelligence_control.delivery_heads where id=p_delivery_id and lease_id=p_lease_id and state='leased' and lease_until>statement_timestamp();
 if not found then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
 select * into s from intelligence_control.integration_subscriptions where tenant_id=d.tenant_id and id=d.subscription_id and enabled;
 select * into a from intelligence_control.delivery_attempts where tenant_id=d.tenant_id and delivery_id=d.id and attempt=d.attempt;
 if s.id is null or a.lease_id is null or s.version<>a.subscription_version or s.key_version<>a.key_version then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 perform intelligence_control.quota_limit(d.tenant_id,'webhook.deliveries');
 select f0.* into f from core.outbox_events o join analytics.pipeline_forecasts f0 on f0.tenant_id=o.tenant_id and f0.id=o.aggregate_id
 where o.id=d.event_id and o.tenant_id=s.tenant_id and o.topic='analytics.freeze_pipeline' and o.aggregate_type='pipeline_forecast'
  and f0.legal_entity_id=s.legal_entity_id and f0.branch_id is not distinct from s.branch_id;
 if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 -- Explicit subscription delegation uses AAL1. It never fabricates human MFA;
 -- the installed scope, role, entitlement and every captured-branch check run.
 saved_claims:=current_setting('request.jwt.claims',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s.created_by,'role','authenticated','aal','aal1')::text,true);
 perform core.wave3_require_scope(s.tenant_id,'integrations.manage',s.legal_entity_id,s.branch_id);
 perform api.get_pipeline_forecast(s.tenant_id,s.legal_entity_id,s.branch_id,f.id);
 perform set_config('request.jwt.claims',coalesce(saved_claims,''),true);
 return jsonb_build_object('event',jsonb_build_object('eventId',d.event_id,'type','analytics.forecast.frozen.v1',
  'tenantId',s.tenant_id,'legalEntityId',s.legal_entity_id,'branchId',s.branch_id,'forecastId',f.id,'definitionVersion',1,'sourceHash',f.source_hash),
  'subscription',jsonb_build_object('id',s.id,'scope',jsonb_build_object('tenantId',s.tenant_id,'legalEntityId',s.legal_entity_id,'branchId',s.branch_id),
  'enabled',true,'url',s.url,'allowedHosts',jsonb_build_array(s.hostname),'keyVersion',s.key_version),
  'deliveryId',d.id,'leaseId',d.lease_id,'invocationId',d.invocation_id,'usageEventId',d.usage_event_id,
  'periodStart',analytics.process_utc(d.period_start),'periodEnd',analytics.process_utc(d.period_end),'attempt',d.attempt);
end $$;
revoke all on function intelligence_control.delivery_authorize(uuid,uuid) from public,anon,authenticated;

create function api.wave5_delivery_worker(p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare d intelligence_control.delivery_heads%rowtype;s intelligence_control.integration_subscriptions%rowtype;
 o intelligence_control.delivery_outcomes%rowtype;subscription billing.tenant_subscriptions%rowtype;v_state text;status integer;begin
 perform intelligence_control.worker_required();
 if p_action='readiness' then return jsonb_build_object('contractRevision',1,'ready',true,'providers',jsonb_build_object('committed_webhook.v1',1,'synthetic_subscription.v1',1));end if;
 if p_action='claim' then
  -- A lease lost after send cannot be auto-retried. ACK rows can be reconciled
  -- separately; expired attempts with no outcome retain uncertain reservations.
  update intelligence_control.delivery_heads set state='unknown' where state='leased' and lease_until<=statement_timestamp();
  insert into intelligence_control.delivery_heads(tenant_id,subscription_id,event_id)
   select s0.tenant_id,s0.id,e.id from intelligence_control.integration_subscriptions s0
   join analytics.pipeline_forecasts f on f.tenant_id=s0.tenant_id and f.legal_entity_id=s0.legal_entity_id and f.branch_id is not distinct from s0.branch_id
   join core.outbox_events e on e.tenant_id=f.tenant_id and e.aggregate_id=f.id and e.aggregate_type='pipeline_forecast' and e.topic='analytics.freeze_pipeline'
   where s0.enabled and e.created_at>=s0.created_at and not exists(select 1 from intelligence_control.delivery_heads h
    where h.tenant_id=s0.tenant_id and h.subscription_id=s0.id and h.event_id=e.id and h.generation=0)
   order by e.created_at,e.id limit 1000 on conflict do nothing;
  select * into d from intelligence_control.delivery_heads where state in('pending','retry') and available_at<=statement_timestamp()
   and attempt<8 order by available_at,id for update skip locked limit 1;
  if not found then return null;end if;
  select * into s from intelligence_control.integration_subscriptions where tenant_id=d.tenant_id and id=d.subscription_id and enabled;
  if not found then update intelligence_control.delivery_heads set state='dead_letter' where id=d.id;return null;end if;
  select * into subscription from billing.tenant_subscriptions where tenant_id=d.tenant_id;
  if d.period_start is null then
   d.period_start:=case when subscription.status='trialing' then coalesce(subscription.trial_started_at,subscription.created_at)
    else coalesce((select period_start from intelligence_control.quota_periods where tenant_id=d.tenant_id and metric_code='webhook.deliveries'
     and period_end=subscription.current_period_ends_at limit 1),date_trunc('month',statement_timestamp())) end;
   d.period_end:=case when subscription.status='trialing' then subscription.trial_ends_at else subscription.current_period_ends_at end;
  end if;
  if d.period_end is null then raise exception using errcode='55000',message='BILLING_PERIOD_UNAVAILABLE';end if;
  update intelligence_control.delivery_heads set attempt=attempt+1,state='leased',lease_id=gen_random_uuid(),lease_until=statement_timestamp()+interval '60 seconds',
   period_start=d.period_start,period_end=d.period_end where id=d.id returning * into d;
  insert into intelligence_control.delivery_attempts values(d.tenant_id,d.id,d.attempt,d.lease_id,s.key_version,s.version,statement_timestamp());
  begin
   return intelligence_control.delivery_authorize(d.id,d.lease_id);
  exception when insufficient_privilege then
   -- No send occurred. Keep this denied item from starving another tenant's
   -- queue; replay still requires a reasoned MFA review after access is fixed.
   update intelligence_control.delivery_heads set state='dead_letter' where id=d.id;
   return null;
  end;
 end if;
 if p_action='authorize' then return intelligence_control.delivery_authorize((p_payload->>'deliveryId')::uuid,(p_payload->>'leaseId')::uuid);end if;
 if p_action='key_ref' then
  perform intelligence_control.delivery_authorize((p_payload->>'deliveryId')::uuid,(p_payload->>'leaseId')::uuid);
  return to_jsonb((select s0.key_ref from intelligence_control.delivery_heads d0 join intelligence_control.integration_subscriptions s0 on s0.tenant_id=d0.tenant_id and s0.id=d0.subscription_id where d0.id=(p_payload->>'deliveryId')::uuid));
 end if;
 if p_action='outcome' then
  select * into d from intelligence_control.delivery_heads where id=(p_payload->>'deliveryId')::uuid and lease_id=(p_payload->>'leaseId')::uuid for update;
  if not found then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
  v_state:=p_payload->>'state';status:=(p_payload->>'httpStatus')::integer;
  if v_state not in('acknowledged','retry','unknown','dead_letter') or v_state is null
   or (v_state='acknowledged' and (status is null or status not between 200 and 299))
   or (v_state='unknown' and status is not null) or (v_state in('retry','dead_letter') and (status is null or status between 200 and 299))
   or (v_state='retry' and d.attempt>=8) or (v_state='dead_letter' and d.attempt<>8) then
   raise exception using errcode='22023',message='OUTCOME_MISMATCH';end if;
  select * into o from intelligence_control.delivery_outcomes where tenant_id=d.tenant_id and delivery_id=d.id and attempt=d.attempt;
  if found then
   if o.state<>v_state or o.http_status is distinct from status then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;return '{}'::jsonb;
  end if;
  insert into intelligence_control.delivery_outcomes values(d.tenant_id,d.id,d.attempt,v_state,status,statement_timestamp());
  update intelligence_control.delivery_heads set state=v_state,available_at=statement_timestamp()+make_interval(secs=>least(3600,15*power(2,d.attempt-1)::integer)) where id=d.id;
  return '{}'::jsonb;
 end if;
 if p_action='settle_acknowledged' then
  for d in select * from intelligence_control.delivery_heads h where h.state='acknowledged'
   and not exists(select 1 from intelligence_control.usage_events u where u.tenant_id=h.tenant_id and u.invocation_id=h.invocation_id)
   order by h.id for update skip locked limit 100 loop
   perform api.wave5_settle_usage(d.tenant_id,d.invocation_id,d.usage_event_id,'1');
  end loop;return '{}'::jsonb;
 end if;
 raise exception using errcode='22023',message='VALIDATION_ERROR';
end $$;
revoke all on function api.wave5_integration_manage(uuid,uuid,uuid,text,uuid,bigint,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_integration_manage(uuid,uuid,uuid,text,uuid,bigint,jsonb) to authenticated;
revoke all on function api.wave5_delivery_worker(text,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_delivery_worker(text,jsonb) to service_role;

create function api.wave5_delivery_review(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_delivery_id uuid,p_review_id uuid,p_action text,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare d intelligence_control.delivery_heads%rowtype;r intelligence_control.delivery_reviews%rowtype;next_id uuid;begin
 perform analytics.pipeline_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'integrations.manage',p_legal_entity_id,p_branch_id);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='APPROVAL_REQUIRED';end if;
 select h.* into d from intelligence_control.delivery_heads h join intelligence_control.integration_subscriptions s on s.tenant_id=h.tenant_id and s.id=h.subscription_id
 where h.tenant_id=p_tenant_id and h.id=p_delivery_id and s.legal_entity_id=p_legal_entity_id and s.branch_id is not distinct from p_branch_id for update of h;
 if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 select * into r from intelligence_control.delivery_reviews where id=p_review_id;
 if found then
  if r.tenant_id<>p_tenant_id or r.delivery_id<>p_delivery_id or r.actor_id<>auth.uid() or r.action<>p_action or r.reason<>p_reason then
   raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
  select id into next_id from intelligence_control.delivery_heads where replay_of=d.id;
  if next_id is not null then return jsonb_build_object('id',next_id,'state','pending','replayOf',d.id);end if;
  return jsonb_build_object('id',d.id,'state',case when p_action='acknowledged' then 'acknowledged' else 'retry' end);
 end if;
 if p_action not in('replay','acknowledged','not_sent') or p_action is null or p_reason is null
  or length(trim(p_reason)) not between 8 and 500 or p_review_id is null
  or (d.state='unknown' and p_action='replay') or (p_action='replay' and d.state<>'dead_letter')
  or (p_action in('acknowledged','not_sent') and d.state<>'unknown') then
  raise exception using errcode='22023',message='OUTCOME_REVIEW_REQUIRED';end if;
 insert into intelligence_control.delivery_reviews values(p_review_id,p_tenant_id,p_delivery_id,auth.uid(),p_action,p_reason,statement_timestamp());
 -- Each reviewed replay creates a new generation. It preserves the committed
 -- event, original invocation/quota and all earlier immutable attempt identities.
 if p_action='replay' or (p_action='not_sent' and d.attempt>=8) then
  if exists(select 1 from intelligence_control.delivery_heads where replay_of=d.id) then
   raise exception using errcode='40001',message='REPLAY_ALREADY_REVIEWED';end if;
  insert into intelligence_control.delivery_heads(tenant_id,subscription_id,event_id,invocation_id,usage_event_id,period_start,period_end,generation,replay_of)
   values(d.tenant_id,d.subscription_id,d.event_id,d.invocation_id,d.usage_event_id,d.period_start,d.period_end,d.generation+1,d.id) returning id into next_id;
  return jsonb_build_object('id',next_id,'state','pending','replayOf',d.id);
 end if;
 update intelligence_control.delivery_heads set state=case when p_action='acknowledged' then 'acknowledged' else 'retry' end,
  available_at=statement_timestamp() where id=d.id returning * into d;
 return jsonb_build_object('id',d.id,'state',d.state);
end $$;
revoke all on function api.wave5_delivery_review(uuid,uuid,uuid,uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function api.wave5_delivery_review(uuid,uuid,uuid,uuid,uuid,text,text) to authenticated;

create function api.wave5_integration_list(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_subscription_after uuid default null,p_delivery_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;deliveries jsonb;subscription_next text;delivery_next text;begin
 perform analytics.pipeline_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'integrations.manage',p_legal_entity_id,p_branch_id);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='APPROVAL_REQUIRED';end if;
 with selected as (select s.*,row_number() over(order by id) ordinal from intelligence_control.integration_subscriptions s
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id is not distinct from p_branch_id
  and (p_subscription_after is null or id>p_subscription_after) order by id limit 51)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'url',url,'version',version::text,'keyVersion',key_version,'enabled',enabled) order by id)
  filter(where ordinal<=50),'[]'),case when count(*)>50 then max(id::text) filter(where ordinal=50) end
 into rows,subscription_next from selected;
 with selected as (select d.*,row_number() over(order by d.id) ordinal from intelligence_control.delivery_heads d
  join intelligence_control.integration_subscriptions s on s.tenant_id=d.tenant_id and s.id=d.subscription_id
  where s.tenant_id=p_tenant_id and s.legal_entity_id=p_legal_entity_id and s.branch_id is not distinct from p_branch_id
  and (p_delivery_after is null or d.id>p_delivery_after) order by d.id limit 51)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'subscriptionId',subscription_id,'state',state,'attempt',attempt,'generation',generation) order by id)
  filter(where ordinal<=50),'[]'),case when count(*)>50 then max(id::text) filter(where ordinal=50) end
 into deliveries,delivery_next from selected;
 return jsonb_build_object('contractRevision',1,'subscriptions',rows,'deliveries',deliveries,
  'subscriptionNext',subscription_next,'deliveryNext',delivery_next);
end $$;
revoke all on function api.wave5_integration_list(uuid,uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_integration_list(uuid,uuid,uuid,uuid,uuid) to authenticated;

create function api.wave5_integration_authorize(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$begin
 perform analytics.pipeline_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'integrations.manage',p_legal_entity_id,p_branch_id);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='APPROVAL_REQUIRED';end if;
 return auth.uid();end $$;
revoke all on function api.wave5_integration_authorize(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_integration_authorize(uuid,uuid,uuid) to authenticated;

-- Observations come from durable queue and metering rows, never desktop claims.
-- An absent current quota period remains unknown; it is not published as zero.
create function api.wave5_health_collect(p_collection_id uuid,p_tenant_id uuid default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare lag_seconds numeric;retries bigint;dead bigint;quota numeric;used numeric;observations jsonb;prior jsonb;r jsonb;begin
 perform intelligence_control.worker_required();
 if p_collection_id is null then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_collection_id::text,530));
 select jsonb_agg(jsonb_build_object('code',code,'exactValue',exact_value::text,'observedAt',analytics.process_utc(observed_at)) order by code)
  into prior from intelligence_control.health_probes where tenant_id is not distinct from p_tenant_id and id in(
   select md5(p_collection_id::text||':'||code)::uuid from unnest(array['worker_lag_seconds','retry_count','dead_letter_count','quota_remaining'])code);
 if prior is not null then return jsonb_build_object('contractRevision',1,'probes',prior);end if;
 select coalesce(greatest(0,floor(extract(epoch from statement_timestamp()-min(available_at) filter(where state in('pending','retry') and available_at<=statement_timestamp())))),0),
  count(*) filter(where state='retry'),count(*) filter(where state='dead_letter') into lag_seconds,retries,dead
  from intelligence_control.delivery_heads where p_tenant_id is null or tenant_id=p_tenant_id;
 observations:=jsonb_build_array(jsonb_build_object('code','worker_lag_seconds','exactValue',lag_seconds::text),
  jsonb_build_object('code','retry_count','exactValue',retries::text),jsonb_build_object('code','dead_letter_count','exactValue',dead::text));
 if p_tenant_id is not null then
  begin
   quota:=intelligence_control.quota_limit(p_tenant_id,'webhook.deliveries');
   select settled_units+reserved_units into used from intelligence_control.quota_periods where tenant_id=p_tenant_id and metric_code='webhook.deliveries'
    and period_start<=statement_timestamp() and period_end>statement_timestamp();
   if used is not null then observations:=observations||jsonb_build_array(jsonb_build_object('code','quota_remaining','exactValue',greatest(0,quota-used)::text));end if;
  exception when insufficient_privilege then null;end;
 end if;
 select jsonb_agg(value||jsonb_build_object('observedAt',analytics.process_utc(statement_timestamp())) order by value->>'code')
  into observations from jsonb_array_elements(observations);
 for r in select * from jsonb_array_elements(observations) loop
  perform api.record_wave5_health_probe(md5(p_collection_id::text||':'||(r->>'code'))::uuid,p_tenant_id,r->>'code',r->>'exactValue',statement_timestamp());
 end loop;
 return jsonb_build_object('contractRevision',1,'probes',observations);
end $$;
revoke all on function api.wave5_health_collect(uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_health_collect(uuid,uuid) to service_role;

-- UNAPPLIED. No credential, model provider, secret or entitlement is enabled.
insert into billing.plan_entitlements(plan_code,entitlement_code,enabled)
 select code,'quota.integration.commands',false from billing.plans on conflict do nothing;
create table intelligence_control.integration_credentials(
 id uuid primary key,token_hash text not null unique check(token_hash ~ '^[0-9a-f]{64}$'),
 tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid,actor_id uuid not null references auth.users(id),
 starts_at timestamptz not null,expires_at timestamptz not null,revoked_at timestamptz,
 unique(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(isfinite(starts_at) and isfinite(expires_at) and expires_at>starts_at and expires_at-starts_at<=interval '366 days'));
create table intelligence_control.external_periods(
 tenant_id uuid not null references core.tenants(id),period_start timestamptz not null,period_end timestamptz not null,
 reserved numeric(20,0) not null default 0 check(reserved>=0),primary key(tenant_id,period_start),check(period_end>period_start));
create table intelligence_control.external_requests(
 tenant_id uuid not null,credential_id uuid not null,command_id uuid not null,idempotency_key uuid not null,
 request_hash text not null,request jsonb not null,period_start timestamptz not null,response jsonb,
 created_at timestamptz not null default statement_timestamp(),primary key(tenant_id,credential_id,command_id),
 unique(tenant_id,credential_id,idempotency_key),foreign key(tenant_id,credential_id) references intelligence_control.integration_credentials(tenant_id,id),
 foreign key(tenant_id,period_start) references intelligence_control.external_periods(tenant_id,period_start));
create table intelligence_control.external_throttles(
 credential_id uuid not null references intelligence_control.integration_credentials(id),window_start timestamptz not null,
 count integer not null check(count between 0 and 60),primary key(credential_id,window_start));
create table intelligence_control.model_invocations(
 invocation_id uuid primary key,tenant_id uuid not null references core.tenants(id),source_id uuid not null,
 source_hash text not null check(source_hash ~ '^[0-9a-f]{64}$'),manifest_hash text not null check(manifest_hash ~ '^[0-9a-f]{64}$'),
 request jsonb not null,created_at timestamptz not null default statement_timestamp(),
 foreign key(tenant_id,source_id) references analytics.pipeline_forecasts(tenant_id,id));
create table intelligence_control.model_outcomes(
 invocation_id uuid primary key references intelligence_control.model_invocations(invocation_id),state text not null check(state in('settled','unknown')),
 tokens numeric(20,0),suggestion jsonb,recorded_at timestamptz not null default statement_timestamp(),
 check((state='unknown' and tokens is null and suggestion is null) or (state='settled' and tokens is not null and tokens>=0 and suggestion is not null and jsonb_typeof(suggestion)='object')));
do $$declare rel text;begin foreach rel in array array['integration_credentials','external_periods','external_requests','external_throttles','model_invocations','model_outcomes'] loop
 execute format('alter table intelligence_control.%I enable row level security',rel);
 execute format('alter table intelligence_control.%I force row level security',rel);
 execute format('revoke all on intelligence_control.%I from public,anon,authenticated',rel);
 if rel in('model_invocations','model_outcomes') then
 execute format('create trigger immutable before update or delete on intelligence_control.%I for each row execute function analytics.immutable_evidence()',rel);end if;
end loop;end $$;
create index credential_scope_idx on intelligence_control.integration_credentials(tenant_id,legal_entity_id,branch_id,id);
create index model_source_idx on intelligence_control.model_invocations(tenant_id,source_id,invocation_id);

create function api.wave5_credential_manage(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_action text,p_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command uuid;v_hash text;v_receipt jsonb;
begin
 if p_id is null then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 perform analytics.pipeline_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'integrations.manage',p_legal_entity_id,p_branch_id);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='APPROVAL_REQUIRED';end if;
 -- Each credential has one immutable registration and one revocation identity.
 -- Repeating the original request reopens its audited receipt after live access.
 v_command:=md5('wave5.credential:'||p_id::text||':'||p_action||':'||auth.uid()::text)::uuid;
 v_hash:=core.wave3_request_hash('integration.credential.'||p_action,v_command,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,null);
 v_receipt:=core.wave3_replay(p_tenant_id,'integration.credential.'||p_action,v_command,v_command,v_hash);
 if v_receipt is not null then return v_receipt;end if;
 if p_action='register' and (p_payload-array['tokenHash','startsAt','expiresAt'])='{}' and p_payload ?& array['tokenHash','startsAt','expiresAt'] then
  insert into intelligence_control.integration_credentials values(p_id,p_payload->>'tokenHash',p_tenant_id,p_legal_entity_id,p_branch_id,
   auth.uid(),(p_payload->>'startsAt')::timestamptz,(p_payload->>'expiresAt')::timestamptz,null);
 elsif p_action='revoke' and p_payload='{}' then
  update intelligence_control.integration_credentials set revoked_at=coalesce(revoked_at,statement_timestamp()) where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id is not distinct from p_branch_id and id=p_id;
  if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 else raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 -- Immutable system audit plus outbox; never a token or hash in public receipt.
 return core.wave3_finish_command(p_tenant_id,'integration.credential.'||p_action,v_command,'integration_credential',p_id,v_command,
  v_hash,null,jsonb_build_object('id',p_id,'version','1','state',p_action),p_legal_entity_id,p_branch_id);
end $$;

create function api.wave5_external_worker(p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c intelligence_control.integration_credentials%rowtype;r intelligence_control.external_requests%rowtype;
 req jsonb:=p_payload->'request';s jsonb;h text;v_period_start timestamptz;v_period_end timestamptz;cap numeric;used numeric;
 window_at timestamptz:=date_trunc('minute',statement_timestamp());throttle integer;saved_claims text;result jsonb;begin
 perform intelligence_control.worker_required();
 select * into c from intelligence_control.integration_credentials where token_hash=p_payload->>'tokenHash';
 if not found or c.revoked_at is not null or c.starts_at>statement_timestamp() or c.expires_at<=statement_timestamp() then
  raise exception using errcode='42501',message='INTEGRATION_ACCESS_DENIED';end if;
 if p_action='credential' then return jsonb_build_object('id',c.id,'tokenHash',c.token_hash,
  'scope',jsonb_build_object('tenantId',c.tenant_id,'legalEntityId',c.legal_entity_id,'branchId',c.branch_id),
  'startsAt',floor(extract(epoch from c.starts_at))::bigint,'expiresAt',floor(extract(epoch from c.expires_at))::bigint,'revokedAt',null,
  'commands',jsonb_build_array('analytics.freeze_pipeline.v1'));end if;
 if req is null or req->>'commandCode' is distinct from 'analytics.freeze_pipeline.v1' or req->>'schemaVersion' is distinct from '1'
  or (req-array['schemaVersion','scope','commandCode','commandId','idempotencyKey','clientTimestamp','horizonStart','horizonEnd'])<>'{}'
  or not(req ?& array['schemaVersion','scope','commandCode','commandId','idempotencyKey','clientTimestamp','horizonStart','horizonEnd'])
  or req->'scope' is distinct from jsonb_build_object('tenantId',c.tenant_id,'legalEntityId',c.legal_entity_id,'branchId',c.branch_id) then
  raise exception using errcode='42501',message='INTEGRATION_ACCESS_DENIED';end if;
 -- Credential-bound delegation uses AAL1 only. It cannot forge human MFA or
 -- cross into a privileged command. The named domain command rechecks authority.
 saved_claims:=current_setting('request.jwt.claims',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c.actor_id,'role','authenticated','aal','aal1')::text,true);
 perform analytics.pipeline_access(c.tenant_id,c.legal_entity_id,c.branch_id);
 perform set_config('request.jwt.claims',coalesce(saved_claims,''),true);
 perform 1 from billing.tenant_subscriptions where tenant_id=c.tenant_id for update;
 select case when status='trialing' then coalesce(trial_started_at,created_at) else date_trunc('month',statement_timestamp()) end,
  case when status='trialing' then trial_ends_at else current_period_ends_at end into v_period_start,v_period_end
  from billing.tenant_subscriptions where tenant_id=c.tenant_id;
 if v_period_end is null then raise exception using errcode='55000',message='BILLING_PERIOD_UNAVAILABLE';end if;
 perform pg_advisory_xact_lock(hashtextextended(c.tenant_id::text||':integration.commands',58));
 cap:=intelligence_control.quota_limit(c.tenant_id,'integration.commands');
 h:=encode(extensions.digest(req::text,'sha256'),'hex');
 select * into r from intelligence_control.external_requests where tenant_id=c.tenant_id and credential_id=c.id
  and (command_id=(req->>'commandId')::uuid or idempotency_key=(req->>'idempotencyKey')::uuid) for update;
 if found then
  if r.request_hash<>h then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
 else
  if p_action<>'reserve' then raise exception using errcode='42501',message='RESERVATION_REQUIRED';end if;
  if exists(select 1 from intelligence_control.external_periods x where x.tenant_id=c.tenant_id and x.period_start<>v_period_start
   and x.period_start<v_period_end and x.period_end>v_period_start) then raise exception using errcode='22023',message='PERIOD_CONFLICT';end if;
  insert into intelligence_control.external_periods values(c.tenant_id,v_period_start,v_period_end,0) on conflict do nothing;
  select x.reserved into used from intelligence_control.external_periods x where x.tenant_id=c.tenant_id and x.period_start=v_period_start for update;
  if used+1>cap then raise exception using errcode='54000',message='QUOTA_EXCEEDED';end if;
  insert into intelligence_control.external_throttles values(c.id,window_at,0) on conflict do nothing;
  select count into throttle from intelligence_control.external_throttles where credential_id=c.id and window_start=window_at for update;
  if throttle>=60 then raise exception using errcode='54000',message='THROTTLED';end if;
  update intelligence_control.external_throttles set count=count+1 where credential_id=c.id and window_start=window_at;
  update intelligence_control.external_periods x set reserved=reserved+1 where x.tenant_id=c.tenant_id and x.period_start=v_period_start;
  insert into intelligence_control.external_requests values(c.tenant_id,c.id,(req->>'commandId')::uuid,(req->>'idempotencyKey')::uuid,h,req,v_period_start,null,statement_timestamp()) returning * into r;
 end if;
 if p_action='reserve' then return jsonb_build_object('quotaReserved',true,'throttleReserved',true);end if;
 if p_action<>'dispatch' then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if r.response is not null then return r.response;end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c.actor_id,'role','authenticated','aal','aal1')::text,true);
 result:=api.freeze_pipeline_forecast(c.tenant_id,c.legal_entity_id,c.branch_id,(req->>'commandId')::uuid,(req->>'idempotencyKey')::uuid,
  (req->>'clientTimestamp')::timestamptz,(req->>'horizonStart')::date,(req->>'horizonEnd')::date);
 perform set_config('request.jwt.claims',coalesce(saved_claims,''),true);
 update intelligence_control.external_requests set response=result where tenant_id=c.tenant_id and credential_id=c.id and command_id=r.command_id;
 return result;
end $$;

create function api.wave5_model_worker(p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare i intelligence_control.model_invocations%rowtype;o intelligence_control.model_outcomes%rowtype;begin
 perform intelligence_control.worker_required();
 if p_action='readiness' then return jsonb_build_object('contractRevision',1,'ready',true);end if;
 perform pg_advisory_xact_lock(hashtextextended(p_payload->>'invocationId',59));
 if p_action='begin' then
  select * into i from intelligence_control.model_invocations where invocation_id=(p_payload->>'invocationId')::uuid;
  if found then
   if i.request<>p_payload then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
   select * into o from intelligence_control.model_outcomes where invocation_id=i.invocation_id;
   return case when o.invocation_id is null then jsonb_build_object('state','pending')
    else jsonb_build_object('state',o.state,'tokens',o.tokens::text,'suggestion',o.suggestion) end;
  end if;
  if p_payload->>'policyRevision' is distinct from '1' or coalesce(p_payload->>'maxTokens','')!~ '^[1-9][0-9]{0,6}$'
   or not exists(select 1 from analytics.pipeline_forecasts where tenant_id=(p_payload->>'tenantId')::uuid
    and id=(p_payload->>'sourceId')::uuid and source_hash=p_payload->>'sourceHash') then raise exception using errcode='22023',message='MODEL_BASIS_MISMATCH';end if;
  insert into intelligence_control.model_invocations values((p_payload->>'invocationId')::uuid,(p_payload->>'tenantId')::uuid,
   (p_payload->>'sourceId')::uuid,p_payload->>'sourceHash',p_payload->>'manifestHash',p_payload,statement_timestamp());
  return jsonb_build_object('state','new');
 elsif p_action='outcome' then
  select * into i from intelligence_control.model_invocations where invocation_id=(p_payload->>'invocationId')::uuid;
  if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
  if p_payload->>'state' is null or p_payload->>'state' not in('settled','unknown') or
   (p_payload->>'state'='unknown' and ((p_payload-array['invocationId','state'])<>'{}')) then
   raise exception using errcode='22023',message='MODEL_OUTCOME_MISMATCH';end if;
  if p_payload->>'state'='settled' and (
   (p_payload-array['invocationId','state','tokens','suggestion'])<>'{}' or not(p_payload ?& array['invocationId','state','tokens','suggestion'])
   or jsonb_typeof(p_payload->'tokens') is distinct from 'string' or coalesce(p_payload->>'tokens','')!~ '^(0|[1-9][0-9]{0,6})$'
   or (p_payload->>'tokens')::numeric>(i.request->>'maxTokens')::numeric
   or jsonb_typeof(p_payload->'suggestion') is distinct from 'object'
   or ((p_payload->'suggestion')-array['commandCode','sourceId','sourceHash','horizonStart','horizonEnd'])<>'{}'
   or not((p_payload->'suggestion') ?& array['commandCode','sourceId','sourceHash','horizonStart','horizonEnd'])
   or p_payload#>>'{suggestion,commandCode}' is distinct from 'analytics.freeze_pipeline.v1'
   or p_payload#>>'{suggestion,sourceId}' is distinct from i.source_id::text or p_payload#>>'{suggestion,sourceHash}' is distinct from i.source_hash
   or not exists(select 1 from analytics.pipeline_forecasts f where f.id=i.source_id and f.tenant_id=i.tenant_id
    and f.horizon_start::text=(p_payload#>>'{suggestion,horizonStart}') and f.horizon_end::text=(p_payload#>>'{suggestion,horizonEnd}'))) then
   raise exception using errcode='22023',message='MODEL_OUTCOME_MISMATCH';end if;
  select * into o from intelligence_control.model_outcomes where invocation_id=i.invocation_id;
  if found then
   if o.state<>p_payload->>'state' or o.tokens is distinct from (p_payload->>'tokens')::numeric
    or o.suggestion is distinct from p_payload->'suggestion' then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;return '{}'::jsonb;
  end if;
  insert into intelligence_control.model_outcomes values(i.invocation_id,p_payload->>'state',(p_payload->>'tokens')::numeric,p_payload->'suggestion',statement_timestamp());
  return '{}'::jsonb;
 end if;
 raise exception using errcode='22023',message='VALIDATION_ERROR';
end $$;
revoke all on function api.wave5_credential_manage(uuid,uuid,uuid,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_credential_manage(uuid,uuid,uuid,text,uuid,jsonb) to authenticated;
revoke all on function api.wave5_external_worker(text,jsonb),api.wave5_model_worker(text,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_external_worker(text,jsonb),api.wave5_model_worker(text,jsonb) to service_role;

create function api.wave5_worker_entitlement(p_scope jsonb) returns boolean
language plpgsql stable security definer set search_path='' as $$
declare tenant uuid:=(p_scope->>'tenantId')::uuid;begin
 perform intelligence_control.worker_required();
 perform intelligence_control.quota_limit(tenant,'integration.commands');
 return exists(select 1 from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
  where s.tenant_id=tenant and p.entitlement_code='analytics' and p.enabled
  and ((s.status='trialing' and coalesce(s.trial_started_at,s.created_at)<=statement_timestamp() and s.trial_ends_at>statement_timestamp())
   or (s.status='active' and (s.current_period_ends_at is null or s.current_period_ends_at>statement_timestamp()))));
end $$;
revoke all on function api.wave5_worker_entitlement(jsonb) from public,anon,authenticated;
grant execute on function api.wave5_worker_entitlement(jsonb) to service_role;

-- Only explicitly allowlisted synthetic tenants enter scheduled application.
-- The existing installed apply RPC owns billing locks, MFA-grant revalidation,
-- seat admission and stable command identity. No tenant is enabled here.
create function api.wave5_subscription_due(p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;n integer;cursor uuid;begin
 perform intelligence_control.worker_required();
 select coalesce(jsonb_agg(jsonb_build_object('tenantId',tenant_id,'revisionId',id) order by id),'[]'),count(*) into rows,n
 from (select r.id,r.tenant_id from intelligence_control.subscription_revisions r
  join intelligence_control.synthetic_tenants t on t.tenant_id=r.tenant_id and t.allowed
  where r.trial_starts_at<=statement_timestamp() and r.trial_ends_at>statement_timestamp()
   and (p_after is null or r.id>p_after) and not exists(select 1 from intelligence_control.subscription_activations a
    where a.tenant_id=r.tenant_id and a.revision_id=r.id) order by r.id limit 51) q;
 if n>50 then cursor:=(rows->49->>'revisionId')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('contractRevision',1,'items',rows,'nextCursor',cursor);
end $$;
revoke all on function api.wave5_subscription_due(uuid) from public,anon,authenticated;
grant execute on function api.wave5_subscription_due(uuid) to service_role;

-- UNAPPLIED candidate. Uses posted journals, immutable AR items, and corrected
-- AP residuals. W4 payroll/project reimbursements lack authoritative payment
-- due dates and are explicitly unavailable from this provider.
create function analytics.cash_access(t uuid,e uuid,b uuid) returns void
language plpgsql stable security definer set search_path='' as $$begin
 if auth.uid() is null or e is null then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 perform core.wave3_require_scope(t,'analytics.view',e,b);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 perform core.wave3_require_scope(t,'finance.receivables.view',e,b);
 if not exists(select 1 from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
  where s.tenant_id=t and p.entitlement_code='analytics' and p.enabled
  and ((s.status='trialing' and coalesce(s.trial_started_at,s.created_at)<=statement_timestamp() and s.trial_ends_at>statement_timestamp())
   or (s.status='active' and (s.current_period_ends_at is null or s.current_period_ends_at>statement_timestamp())))) then
  raise exception using errcode='42501',message='ENTITLEMENT_REQUIRED';end if;
end $$;
revoke all on function analytics.cash_access(uuid,uuid,uuid) from public,anon,authenticated;

create function api.wave5_cash_authorize(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$begin
 perform analytics.cash_access(p_tenant_id,p_legal_entity_id,p_branch_id);return auth.uid();end $$;

-- Use separately owned AP read/reversal providers when installed. The fallback
-- only recognizes existing payment capabilities and never invents a bill API.
create function analytics.cash_payables_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean
language plpgsql stable security definer set search_path='' as $$declare allowed boolean;begin
 if pg_catalog.to_regprocedure('finance.payable_read_allowed(uuid,uuid,uuid)') is not null then
  execute 'select finance.payable_read_allowed($1,$2,$3)' into allowed using p_tenant,p_entity,p_branch;
  return coalesce(allowed,false);
 end if;
 return core.is_tenant_member(p_tenant) and (core.has_permission(p_tenant,'finance.payments.manage',p_entity,p_branch)
  or core.has_permission(p_tenant,'finance.payments.post',p_entity,p_branch));
end $$;
create function analytics.cash_ap_reversal_evidence(p_tenant uuid,p_allocation uuid,p_before date,p_through timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare evidence jsonb;begin
 if pg_catalog.to_regclass('finance.allocation_reversals') is null then return null;end if;
 execute 'select jsonb_build_object(''id'',r.id,''postingDate'',r.posting_date::text) from finance.allocation_reversals r
  where r.tenant_id=$1 and r.allocation_id=$2 and r.posting_date<$3 and r.created_at<=$4 limit 1'
  into evidence using p_tenant,p_allocation,p_before,p_through;
 return evidence;
end $$;
revoke all on function analytics.cash_payables_allowed(uuid,uuid,uuid),analytics.cash_ap_reversal_evidence(uuid,uuid,date,timestamptz) from public,anon,authenticated;

create function api.wave5_cash_basis(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_start date,p_end date,p_recorded_through timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare controls jsonb;obligations jsonb;sources jsonb;result jsonb;n integer;
 can_read_payables boolean;providers jsonb:='["bank_cash","receivables"]'::jsonb;provider_status jsonb;begin
 perform analytics.cash_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 can_read_payables:=analytics.cash_payables_allowed(p_tenant_id,p_legal_entity_id,p_branch_id);
 if can_read_payables then providers:=providers||jsonb_build_array('payables');end if;
 provider_status:=jsonb_build_object('bank_cash','available','receivables','available',
  'payables',case when can_read_payables then 'available' else 'permission_required' end,
  'payroll','missing_authoritative_due_date','project_reimbursements','missing_authoritative_due_date');
 if p_start is null or p_end is null or p_end<=p_start or p_end-p_start>366 or not isfinite(p_start) or not isfinite(p_end)
  or p_recorded_through is null or not isfinite(p_recorded_through) or p_recorded_through>statement_timestamp()
  or p_start::timestamptz>p_recorded_through then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 -- Current cash-account configuration has no historical mapping journal.
 -- Reject a date predating its latest revision instead of inventing that mapping.
 if exists(select 1 from finance.cash_bank_accounts c where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id
  and (p_branch_id is null or c.branch_id=p_branch_id) and c.updated_at>p_start::timestamptz) then
  raise exception using errcode='55000',message='CASH_MAPPING_HISTORY_REQUIRED';end if;
 if exists(select account_id from finance.cash_bank_accounts c where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id
  and (p_branch_id is null or c.branch_id=p_branch_id) and c.status='active' group by account_id having count(*)>1) then
  raise exception using errcode='55000',message='CASH_CONTROL_MAPPING_AMBIGUOUS';end if;
 if exists(select 1 from finance.cash_bank_accounts c join finance.journal_lines l on l.tenant_id=c.tenant_id and l.account_id=c.account_id
  join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id and (p_branch_id is null or c.branch_id=p_branch_id)
   and (p_branch_id is null or l.branch_id=p_branch_id) and c.status='active' and j.status='posted'
   and l.posting_date<p_start and j.created_at<=p_recorded_through and l.currency_code<>c.currency_code
   and l.transaction_debit<>l.transaction_credit) then
  raise exception using errcode='55000',message='CASH_CURRENCY_MAPPING_REQUIRED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'accountId',c.account_id,'branchId',c.branch_id,'currency',c.currency_code,
  'version',c.version::text,'amount',coalesce((select sum(l.transaction_debit-l.transaction_credit)
   from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
   where l.tenant_id=c.tenant_id and l.legal_entity_id=c.legal_entity_id and l.account_id=c.account_id and l.currency_code=c.currency_code
    and (p_branch_id is null or l.branch_id=p_branch_id) and l.posting_date<p_start and j.status='posted' and j.created_at<=p_recorded_through),0)::text) order by c.id),'[]')
 into controls from finance.cash_bank_accounts c where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id
  and (p_branch_id is null or c.branch_id=p_branch_id) and c.status='active';
 with ar_remaining as (select o.*,o.original_amount+
  coalesce((select sum(a.source_amount) from finance.open_item_allocations a where a.tenant_id=o.tenant_id and a.source_open_item_id=o.id
   and a.posting_date<p_start and a.created_at<=p_recorded_through),0)-
  coalesce((select sum(a.transaction_amount+a.write_off+a.discount_amount) from finance.open_item_allocations a where a.tenant_id=o.tenant_id and a.target_open_item_id=o.id
   and a.posting_date<p_start and a.created_at<=p_recorded_through),0) remaining
  from finance.open_items o where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and (p_branch_id is null or o.branch_id=p_branch_id)
   and o.kind='AR' and o.original_amount>0 and o.posting_date<p_start and o.created_at<=p_recorded_through and o.due_date>=p_start and o.due_date<p_end),
 ap_remaining as (select o.*,o.original_amount+
  coalesce((select sum(a.source_amount) from finance.open_item_allocations a where a.tenant_id=o.tenant_id and a.source_open_item_id=o.id
   and a.posting_date<p_start and a.created_at<=p_recorded_through),0)-
  coalesce((select sum(a.transaction_amount+a.write_off+a.discount_amount) from finance.open_item_allocations a where a.tenant_id=o.tenant_id and a.target_open_item_id=o.id
   and a.posting_date<p_start and a.created_at<=p_recorded_through
   and analytics.cash_ap_reversal_evidence(a.tenant_id,a.id,p_start,p_recorded_through) is null),0) remaining
  from finance.open_items o where can_read_payables and o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id
   and (p_branch_id is null or o.branch_id=p_branch_id) and o.kind='AP' and o.original_amount>0 and o.posting_date<p_start
   and o.created_at<=p_recorded_through and o.due_date>=p_start and o.due_date<p_end),
 all_rows as (select id,branch_id,currency_code,due_date,remaining,'receivables'::text provider from ar_remaining where remaining>0
  union all select id,branch_id,currency_code,due_date,remaining,'payables'::text provider from ap_remaining where remaining>0),
 bounded as (select * from all_rows order by provider,id limit 10001)
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'branchId',branch_id,'currency',currency_code,'dueDate',due_date::text,
  'amount',remaining::text,'version','1','provider',provider) order by provider,id),'[]'),count(*) into obligations,n from bounded;
 if n+jsonb_array_length(controls)>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 -- Retain each contributing posted journal/allocation identity, bounded as a
 -- complete manifest. Mutable document text and customer PII are excluded.
 with refs as (
 select jsonb_build_object('kind','cash_journal','id',l.id,'branchId',l.branch_id,'version','1',
  'debit',l.transaction_debit::text,'credit',l.transaction_credit::text,'currency',l.currency_code) value
 from finance.journal_lines l join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
 where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and (p_branch_id is null or l.branch_id=p_branch_id)
  and l.posting_date<p_start and j.status='posted' and j.created_at<=p_recorded_through
  and exists(select 1 from jsonb_array_elements(controls) c where c->>'accountId'=l.account_id::text)
 union all select jsonb_build_object('kind','ar_allocation','id',a.id,'branchId',a.branch_id,'version','1',
  'sourceAmount',a.source_amount::text,'targetAmount',a.transaction_amount::text,'writeOff',a.write_off::text,'discount',a.discount_amount::text)
 from finance.open_item_allocations a where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id
  and a.posting_date<p_start and a.created_at<=p_recorded_through
  and exists(select 1 from jsonb_array_elements(obligations) o where o->>'provider'='receivables' and o->>'id' in(a.source_open_item_id::text,a.target_open_item_id::text))
 union all select jsonb_build_object('kind','ap_allocation','id',a.id,'branchId',a.branch_id,'version','1',
  'sourceAmount',a.source_amount::text,'targetAmount',a.transaction_amount::text,'writeOff',a.write_off::text,'discount',a.discount_amount::text,
  'reversal',analytics.cash_ap_reversal_evidence(a.tenant_id,a.id,p_start,p_recorded_through))
 from finance.open_item_allocations a where can_read_payables and a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id
  and a.posting_date<p_start and a.created_at<=p_recorded_through
  and exists(select 1 from jsonb_array_elements(obligations) o where o->>'provider'='payables' and o->>'id' in(a.source_open_item_id::text,a.target_open_item_id::text)))
 select coalesce(jsonb_agg(value order by value->>'id'),'[]'),count(*) into sources,n from (select * from refs limit 10001) r;
 if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 if exists(select 1 from jsonb_array_elements(controls||obligations||sources) r where not core.has_permission(p_tenant_id,'finance.view',p_legal_entity_id,(r->>'branchId')::uuid)
  or (r->>'provider'='receivables' and not core.has_permission(p_tenant_id,'finance.receivables.view',p_legal_entity_id,(r->>'branchId')::uuid))
  or (r->>'kind' like 'ar_%' and not core.has_permission(p_tenant_id,'finance.receivables.view',p_legal_entity_id,(r->>'branchId')::uuid))
  or ((r->>'provider'='payables' or r->>'kind' like 'ap_%') and not analytics.cash_payables_allowed(p_tenant_id,p_legal_entity_id,(r->>'branchId')::uuid))) then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 result:=jsonb_build_object('contractRevision',2,'definition','dated_transaction_cash_ar_and_ap.v2',
  'scope',jsonb_build_object('tenantId',p_tenant_id,'legalEntityId',p_legal_entity_id,'branchId',p_branch_id),
  'horizonStart',p_start::text,'horizonEnd',p_end::text,'recordedThrough',analytics.process_utc(p_recorded_through),
  'completeProviders',providers,'providerStatus',provider_status,'controls',controls,'obligations',obligations,'sources',sources,
  'exclusions',jsonb_build_array('overdue_before_horizon','unallocated_credits','payroll','project_reimbursements'));
 if octet_length(result::text)>8388608 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 return jsonb_build_object('canonicalText',result::text,'sourceHash',encode(extensions.digest(result::text,'sha256'),'hex'));
end $$;
create table analytics.cash_scenario_revisions(id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid,
 actor_id uuid not null references auth.users(id),source_hash text not null check(source_hash ~ '^[a-f0-9]{64}$'),
 canonical_text text not null,evidence jsonb not null,parameters jsonb not null,created_at timestamptz not null default statement_timestamp(),
 unique(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(octet_length(canonical_text)<=8388608 and octet_length(parameters::text)<=8388608),
 check(source_hash=encode(extensions.digest(convert_to(canonical_text,'UTF8'),'sha256'),'hex') and evidence=canonical_text::jsonb));
alter table analytics.cash_scenario_revisions enable row level security;
alter table analytics.cash_scenario_revisions force row level security;
revoke all on analytics.cash_scenario_revisions from public,anon,authenticated;
create trigger immutable before update or delete on analytics.cash_scenario_revisions for each row execute function analytics.immutable_evidence();
create function api.wave5_cash_save(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,p_source_hash text,p_parameters jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$declare old analytics.cash_scenario_revisions%rowtype;basis jsonb;data jsonb;k text;v jsonb;begin
 perform analytics.cash_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 if p_id is null or p_parameters is null or jsonb_typeof(p_parameters)<>'object' or (p_parameters-array['horizonStart','horizonEnd','recordedThrough','overrides'])<>'{}'
  or not(p_parameters ?& array['horizonStart','horizonEnd','recordedThrough','overrides']) or jsonb_typeof(p_parameters->'overrides')<>'object' then
  raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,509));
 select * into old from analytics.cash_scenario_revisions where id=p_id;
 if found then
  if old.tenant_id<>p_tenant_id or old.legal_entity_id<>p_legal_entity_id or old.branch_id is distinct from p_branch_id or old.actor_id<>auth.uid()
   or old.source_hash is distinct from p_source_hash or old.parameters<>p_parameters then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;
  perform api.wave5_cash_get(p_tenant_id,p_legal_entity_id,p_branch_id,p_id);
  return jsonb_build_object('id',p_id,'sourceHash',p_source_hash,'version','1');end if;
 basis:=api.wave5_cash_basis(p_tenant_id,p_legal_entity_id,p_branch_id,(p_parameters->>'horizonStart')::date,(p_parameters->>'horizonEnd')::date,(p_parameters->>'recordedThrough')::timestamptz);
 if basis->>'sourceHash' is distinct from p_source_hash then raise exception using errcode='40001',message='SOURCE_BASIS_CHANGED';end if;
 data:=(basis->>'canonicalText')::jsonb;
 if not (data->'completeProviders' ? 'payables') then raise exception using errcode='42501',message='PAYABLES_PERMISSION_REQUIRED';end if;
 for k,v in select * from jsonb_each(p_parameters->'overrides') loop
  if not exists(select 1 from jsonb_array_elements(data->'obligations') o where o->>'id'=k)
   or jsonb_typeof(v)<>'object' or (v-array['dueDate','remainingUnits','reasonCode'])<>'{}' or not(v ?& array['dueDate','remainingUnits','reasonCode'])
   or jsonb_typeof(v->'remainingUnits')<>'string' or coalesce(v->>'remainingUnits','')!~ '^(0|[1-9][0-9]{0,19})$'
   or jsonb_typeof(v->'dueDate')<>'string' or coalesce(v->>'dueDate','')!~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or coalesce(v->>'reasonCode','') not in('collection_delay','payment_delay','reviewed_amount')
   or (v->>'dueDate')::date<(p_parameters->>'horizonStart')::date or (v->>'dueDate')::date>=(p_parameters->>'horizonEnd')::date then
   raise exception using errcode='22023',message='INVALID_SCENARIO_OVERRIDE';end if;
 end loop;
 insert into analytics.cash_scenario_revisions values(p_id,p_tenant_id,p_legal_entity_id,p_branch_id,auth.uid(),p_source_hash,basis->>'canonicalText',data,p_parameters,statement_timestamp());
 perform core.wave3_finish_command(p_tenant_id,'analytics.cash_scenario',p_id,'cash_scenario',p_id,p_id,
  core.wave3_request_hash('analytics.cash_scenario',p_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_parameters,null),null,
  jsonb_build_object('id',p_id,'sourceHash',p_source_hash,'version','1'),p_legal_entity_id,p_branch_id);
 return jsonb_build_object('id',p_id,'sourceHash',p_source_hash,'version','1');end $$;
create function api.wave5_cash_get(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare s analytics.cash_scenario_revisions%rowtype;begin
 perform analytics.cash_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 select * into s from analytics.cash_scenario_revisions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id is not distinct from p_branch_id and id=p_id;
 if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 if (s.evidence->'completeProviders' ? 'payables') and not analytics.cash_payables_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 if exists(select 1 from jsonb_array_elements((s.evidence->'controls')||(s.evidence->'obligations')||(s.evidence->'sources')) r where
  not core.has_permission(p_tenant_id,'finance.view',p_legal_entity_id,(r->>'branchId')::uuid)
  or (r->>'provider'='receivables' and not core.has_permission(p_tenant_id,'finance.receivables.view',p_legal_entity_id,(r->>'branchId')::uuid))
  or (r->>'kind' like 'ar_%' and not core.has_permission(p_tenant_id,'finance.receivables.view',p_legal_entity_id,(r->>'branchId')::uuid))
  or ((r->>'provider'='payables' or r->>'kind' like 'ap_%') and not analytics.cash_payables_allowed(p_tenant_id,p_legal_entity_id,(r->>'branchId')::uuid))) then
  raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 return jsonb_build_object('id',s.id,'sourceHash',s.source_hash,'canonicalText',s.canonical_text,'parameters',s.parameters);end $$;
revoke all on function api.wave5_cash_authorize(uuid,uuid,uuid),api.wave5_cash_basis(uuid,uuid,uuid,date,date,timestamptz),api.wave5_cash_save(uuid,uuid,uuid,uuid,text,jsonb),api.wave5_cash_get(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_cash_authorize(uuid,uuid,uuid),api.wave5_cash_basis(uuid,uuid,uuid,date,date,timestamptz),api.wave5_cash_save(uuid,uuid,uuid,uuid,text,jsonb),api.wave5_cash_get(uuid,uuid,uuid,uuid) to authenticated;

-- UNAPPLIED extension. Requires the existing reviewed Wave 3 governed-export
-- candidate 20260926009000 first. Reuses its command, jobs, audit and file codec.
alter function finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb) rename to wave3_report_export_document;
create function finance.report_export_document(t uuid,e uuid,b uuid,resource text,i uuid,section text,filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare f jsonb;s jsonb;data jsonb;rows jsonb;meta jsonb;start_date date;end_date date;n integer;begin
 if resource is null then raise exception using errcode='22023',message='REPORT_EXPORT_SOURCE_INVALID';end if;
 if resource not in('w5_pipeline','w5_cash') then return finance.wave3_report_export_document(t,e,b,resource,i,section,filters);end if;
 perform core.wave3_require_scope(t,'finance.reports.export',e,b);
 if i is null or filters is null or jsonb_typeof(filters)<>'object' or (filters-'currency')<>'{}'
  or (filters ? 'currency' and (jsonb_typeof(filters->'currency')<>'string' or coalesce(filters->>'currency','')!~ '^[A-Z]{3}$')) then
  raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
 if resource='w5_pipeline' then
  if section is distinct from 'currencies' then raise exception using errcode='22023',message='REPORT_EXPORT_SOURCE_INVALID';end if;
  f:=api.get_pipeline_forecast(t,e,b,i);data:=f->'evidence';
  select coalesce(jsonb_agg(x order by x->>'currency'),'[]') into rows from jsonb_array_elements(data->'currencies') x
   where filters->>'currency' is null or x->>'currency'=filters->>'currency';
  meta:=jsonb_build_object('as_of',data->>'asOf','generated_at',data->>'generatedAt','horizon_start',data->>'horizonStart','horizon_end',data->>'horizonEnd',
   'calculation','pipeline.current_weighted.v1','source_basis_hash',f->>'sourceHash');
 else
  if section is distinct from 'buckets' then raise exception using errcode='22023',message='REPORT_EXPORT_SOURCE_INVALID';end if;
  s:=api.wave5_cash_get(t,e,b,i);data:=(s->>'canonicalText')::jsonb;start_date:=(data->>'horizonStart')::date;end_date:=(data->>'horizonEnd')::date;
  if exists(select 1 from jsonb_array_elements(data->'obligations') o where not exists(select 1 from jsonb_array_elements(data->'controls') c where c->>'currency'=o->>'currency')) then
   raise exception using errcode='55000',message='CASH_CURRENCY_MAPPING_REQUIRED';end if;
  with opening as(select x->>'currency' currency,sum((x->>'amount')::numeric) balance from jsonb_array_elements(data->'controls') x group by x->>'currency'),
   flows as(select o->>'currency' currency,coalesce((s#>>array['parameters','overrides',o->>'id','dueDate'])::date,(o->>'dueDate')::date) due_date,
    case when o->>'provider'='receivables' then coalesce((s#>>array['parameters','overrides',o->>'id','remainingUnits'])::numeric/1000000,(o->>'amount')::numeric) else 0 end inflow,
    case when o->>'provider'='payables' then coalesce((s#>>array['parameters','overrides',o->>'id','remainingUnits'])::numeric/1000000,(o->>'amount')::numeric) else 0 end outflow
    from jsonb_array_elements(data->'obligations') o),
   days as(select c.currency,c.balance,d::date bucket_date from opening c cross join generate_series(start_date,end_date-1,interval '1 day') d
    where filters->>'currency' is null or c.currency=filters->>'currency'),
   buckets as(select d.currency,d.bucket_date,d.balance,coalesce(sum(f.inflow),0) inflow,coalesce(sum(f.outflow),0) outflow
    from days d left join flows f on f.currency=d.currency and f.due_date=d.bucket_date group by d.currency,d.bucket_date,d.balance)
  select coalesce(jsonb_agg(jsonb_build_object('date',bucket_date::text,'currency',currency,'inflow',inflow::text,'outflow',outflow::text,'balance',total::text) order by currency,bucket_date),'[]'),count(*) into rows,n
  from(select currency,bucket_date,inflow,outflow,balance+sum(inflow-outflow) over(partition by currency order by bucket_date) total from buckets order by currency,bucket_date limit 10001) projected;
  if n>10000 then raise exception using errcode='54000',message='REPORT_EXPORT_ROW_LIMIT';end if;
  meta:=jsonb_build_object('as_of',data->>'horizonStart','generated_at',data->>'recordedThrough','horizon_start',data->>'horizonStart','horizon_end',data->>'horizonEnd',
   'calculation','dated_transaction_cash_ar_and_ap.v2','source_basis_hash',s->>'sourceHash','scenario_parameters',s->'parameters','exclusions',data->'exclusions');
 end if;
 meta:=meta||jsonb_build_object('id',i,'version',1,'tenant_id',t,'legal_entity_id',e,'branch_id',b,'actor_id',auth.uid(),'working_branch_id',b,
  'source_type',resource,'source_id',i,'section',section,'filters',filters,'row_count',jsonb_array_length(rows));
 f:=jsonb_build_object('version',1,'metadata',meta,'rows',rows);
 if octet_length(f::text)>8388608 then raise exception using errcode='54000',message='REPORT_EXPORT_EVIDENCE_LIMIT';end if;return f;
end $$;
revoke all on function finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb) from public,anon,authenticated;
create function api.wave5_export_reopen(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_export_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare job core.export_jobs%rowtype;data jsonb;begin
 select * into job from core.export_jobs where tenant_id=p_tenant_id and id=p_export_id and actor_id=auth.uid();
 if not found or job.filters->>'legal_entity_id' is distinct from p_legal_entity_id::text or job.filters->>'working_branch_id' is distinct from p_branch_id::text
  or job.filters->>'source_type' not in('w5_pipeline','w5_cash') then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 data:=finance.report_export_document(p_tenant_id,p_legal_entity_id,p_branch_id,job.filters->>'source_type',(job.filters->>'source_id')::uuid,job.filters->>'section',job.filters->'filters');
 if encode(extensions.digest(data::text,'sha256'),'hex')<>job.filters->>'source_hash' then raise exception using errcode='55000',message='EXPORT_BASIS_CHANGED';end if;
 return jsonb_build_object('id',job.id,'canonicalText',data::text,'sourceHash',job.filters->>'source_hash','fileHash',job.filters->>'file_sha256',
  'preparedAt',job.filters->>'prepared_at','format',job.file_format,'fileName',job.file_name);end $$;
revoke all on function api.wave5_export_reopen(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_export_reopen(uuid,uuid,uuid,uuid) to authenticated;

-- UNAPPLIED. Requires the separately owned Wave 3 financial-statement provider.
-- No classifications, financial publications, entitlements or roles are seeded.
insert into core.permissions(code,module,description,privileged) values
 ('finance.classifications.approve','finance','Approve immutable statement account classifications',true)
 on conflict(code) do nothing;
create table analytics.statement_classifications(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 profit_loss_id uuid not null,balance_sheet_id uuid not null,labels jsonb not null,
 reason text not null check(length(trim(reason)) between 8 and 500),actor_id uuid not null references auth.users(id),
 profit_loss_hash text not null,balance_sheet_hash text not null,created_at timestamptz not null default statement_timestamp(),
 unique(tenant_id,id),foreign key(tenant_id,profit_loss_id) references finance.financial_reports(tenant_id,id),
 foreign key(tenant_id,balance_sheet_id) references finance.financial_reports(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(jsonb_typeof(labels)='object' and octet_length(labels::text)<=1048576),
 check(profit_loss_hash ~ '^[a-f0-9]{64}$' and balance_sheet_hash ~ '^[a-f0-9]{64}$'));
alter table analytics.statement_classifications enable row level security;
alter table analytics.statement_classifications force row level security;
revoke all on analytics.statement_classifications from public,anon,authenticated;
create trigger immutable before update or delete on analytics.statement_classifications for each row execute function analytics.immutable_evidence();
create index statement_classification_scope on analytics.statement_classifications(tenant_id,legal_entity_id,branch_id,id);

create function analytics.statement_access(t uuid,e uuid,b uuid) returns void
language plpgsql stable security definer set search_path='' as $$begin
 if auth.uid() is null or e is null or b is null then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 perform core.wave3_require_scope(t,'analytics.view',e,b);
 -- The Wave 3 statements are entity-wide, even when requested at a branch.
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if not exists(select 1 from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
  where s.tenant_id=t and p.entitlement_code='analytics' and p.enabled
  and ((s.status='trialing' and coalesce(s.trial_started_at,s.created_at)<=statement_timestamp() and s.trial_ends_at>statement_timestamp())
   or (s.status='active' and (s.current_period_ends_at is null or s.current_period_ends_at>statement_timestamp())))) then
  raise exception using errcode='42501',message='ENTITLEMENT_REQUIRED';end if;
end $$;

create function analytics.statement_bundle(t uuid,e uuid,b uuid,p uuid,q uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare pl finance.financial_reports%rowtype;bs finance.financial_reports%rowtype;k text;begin
 perform analytics.statement_access(t,e,b);
 select * into pl from finance.financial_reports where tenant_id=t and legal_entity_id=e and requested_branch_id=b and id=p and kind='profit_loss';
 select * into bs from finance.financial_reports where tenant_id=t and legal_entity_id=e and requested_branch_id=b and id=q and kind='balance_sheet';
 if pl.id is null or bs.id is null or pl.summary->>'status'<>'generated' or bs.summary->>'status'<>'generated'
  or pl.summary->>'version'<>'1' or bs.summary->>'version'<>'1' then
  raise exception using errcode='42501',message='STATEMENT_BUNDLE_REQUIRED';end if;
 foreach k in array array['tenant_id','legal_entity_id','branch_id','period_id','period_start','period_end','as_of','base_currency_code'] loop
  if pl.summary->k is distinct from bs.summary->k then raise exception using errcode='22023',message='STATEMENT_BUNDLE_MISMATCH';end if;
 end loop;
 if pl.evidence->'journals' is distinct from bs.evidence->'journals'
  or jsonb_array_length(pl.evidence->'accounts')<>jsonb_array_length(bs.evidence->'accounts')
  or exists(select 1 from jsonb_array_elements(pl.evidence->'accounts') a full join jsonb_array_elements(bs.evidence->'accounts') z
   on a->>'account_id'=z->>'account_id' where a is null or z is null or a->>'account_type' is distinct from z->>'account_type') then
  raise exception using errcode='22023',message='STATEMENT_SOURCE_MISMATCH';end if;
 return jsonb_build_object('profitLoss',pl.evidence,'balanceSheet',bs.evidence,
  'profitLossHash',encode(extensions.digest(pl.evidence::text,'sha256'),'hex'),
  'balanceSheetHash',encode(extensions.digest(bs.evidence::text,'sha256'),'hex'));
end $$;
revoke all on function analytics.statement_access(uuid,uuid,uuid),analytics.statement_bundle(uuid,uuid,uuid,uuid,uuid) from public,anon,authenticated;

create function api.wave5_classification_authorize(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$begin
 perform analytics.statement_access(p_tenant_id,p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'finance.classifications.approve',p_legal_entity_id,p_branch_id);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='APPROVAL_REQUIRED';end if;
 return auth.uid();end $$;

create function api.wave5_classification_publish(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_id uuid,p_profit_loss_id uuid,p_balance_sheet_id uuid,p_labels jsonb,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare bundle jsonb;a jsonb;tag text;h text;receipt jsonb;payload jsonb;begin
 perform api.wave5_classification_authorize(p_tenant_id,p_legal_entity_id,p_branch_id);
 bundle:=analytics.statement_bundle(p_tenant_id,p_legal_entity_id,p_branch_id,p_profit_loss_id,p_balance_sheet_id);
 if p_id is null or jsonb_typeof(p_labels) is distinct from 'object' or octet_length(p_labels::text)>1048576
  or p_reason is null or length(trim(p_reason)) not between 8 and 500
  or (select count(*) from jsonb_object_keys(p_labels))<>jsonb_array_length(bundle#>'{profitLoss,accounts}') then
  raise exception using errcode='22023',message='CLASSIFICATION_COVERAGE_REQUIRED';end if;
 for a in select * from jsonb_array_elements(bundle#>'{profitLoss,accounts}') loop
  tag:=p_labels->>(a->>'account_id');
  if jsonb_typeof(p_labels->(a->>'account_id')) is distinct from 'string' or tag is null or
   not(case a->>'account_type' when 'asset' then tag in('current_asset','inventory','noncurrent_asset')
    when 'liability' then tag in('current_liability','noncurrent_liability') when 'revenue' then tag='revenue'
    when 'expense' then tag in('cost_of_sales','operating_expense') when 'equity' then tag='equity' else false end) then
   raise exception using errcode='22023',message='CLASSIFICATION_TYPE_MISMATCH';end if;
 end loop;
 payload:=jsonb_build_object('profitLossId',p_profit_loss_id,'balanceSheetId',p_balance_sheet_id,'labels',p_labels,'reason',p_reason,
  'profitLossHash',bundle->>'profitLossHash','balanceSheetHash',bundle->>'balanceSheetHash');
 h:=core.wave3_request_hash('analytics.classifications.publish',p_id,p_tenant_id,p_legal_entity_id,p_branch_id,payload,null);
 receipt:=core.wave3_replay(p_tenant_id,'analytics.classifications.publish',p_id,p_id,h);
 if receipt is not null then return receipt;end if;
 insert into analytics.statement_classifications values(p_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_profit_loss_id,p_balance_sheet_id,
  p_labels,p_reason,auth.uid(),bundle->>'profitLossHash',bundle->>'balanceSheetHash',statement_timestamp());
 return core.wave3_finish_command(p_tenant_id,'analytics.classifications.publish',p_id,'statement_classification',p_id,p_id,h,null,
  jsonb_build_object('id',p_id,'version','1','profitLossHash',bundle->>'profitLossHash','balanceSheetHash',bundle->>'balanceSheetHash'),p_legal_entity_id,p_branch_id);
end $$;

create function analytics.exact_named_ratio(n numeric,d numeric) returns jsonb
language sql immutable set search_path='' as $$select jsonb_build_object('numerator',n::text,'denominator',d::text,
 'exactValue',case when d>0 then round(n/d,6)::text else null end,
 'unavailableReason',case when d=0 then 'ZERO_DENOMINATOR' when d<0 then 'NEGATIVE_DENOMINATOR' end)$$;

create function api.wave5_financial_ratios(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_profit_loss_id uuid,p_balance_sheet_id uuid,p_classification_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare bundle jsonb;pl jsonb;bs jsonb;c analytics.statement_classifications%rowtype;ratios jsonb;result jsonb;
 revenue numeric;profit numeric;assets numeric;liabilities numeric;equity numeric;ca numeric;inventory numeric;cl numeric;cogs numeric;begin
 bundle:=analytics.statement_bundle(p_tenant_id,p_legal_entity_id,p_branch_id,p_profit_loss_id,p_balance_sheet_id);
 pl:=bundle#>'{profitLoss,summary}';bs:=bundle#>'{balanceSheet,summary}';
 revenue:=(pl->>'revenue')::numeric;profit:=(pl->>'net_profit')::numeric;
 assets:=(bs->>'assets')::numeric;liabilities:=(bs->>'liabilities')::numeric;equity:=(bs->>'equity')::numeric+(bs->>'current_earnings')::numeric;
 ratios:=jsonb_build_object('net_profit_margin',analytics.exact_named_ratio(profit,revenue),
  'liabilities_to_assets',analytics.exact_named_ratio(liabilities,assets),'assets_to_equity',analytics.exact_named_ratio(assets,equity));
 if p_classification_id is not null then
  select * into c from analytics.statement_classifications where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and id=p_classification_id and profit_loss_id=p_profit_loss_id and balance_sheet_id=p_balance_sheet_id;
  if not found or c.profit_loss_hash is distinct from bundle->>'profitLossHash' or c.balance_sheet_hash is distinct from bundle->>'balanceSheetHash' then
   raise exception using errcode='42501',message='CLASSIFICATION_PUBLICATION_REQUIRED';end if;
  select coalesce(sum((a->>'amount')::numeric) filter(where c.labels->>(a->>'account_id') in('current_asset','inventory')),0),
   coalesce(sum((a->>'amount')::numeric) filter(where c.labels->>(a->>'account_id')='inventory'),0),
   coalesce(sum((a->>'amount')::numeric) filter(where c.labels->>(a->>'account_id')='current_liability'),0)
   into ca,inventory,cl from jsonb_array_elements(bundle#>'{balanceSheet,accounts}') a;
  select coalesce(sum((a->>'amount')::numeric) filter(where c.labels->>(a->>'account_id')='cost_of_sales'),0)
   into cogs from jsonb_array_elements(bundle#>'{profitLoss,accounts}') a;
  ratios:=ratios||jsonb_build_object('current_ratio',analytics.exact_named_ratio(ca,cl),
   'quick_ratio',analytics.exact_named_ratio(ca-inventory,cl),'gross_profit_margin',analytics.exact_named_ratio(revenue-cogs,revenue));
 end if;
 result:=jsonb_build_object('contractRevision',1,'formulaVersion',1,'scope',jsonb_build_object('tenantId',p_tenant_id,'legalEntityId',p_legal_entity_id,'branchId',p_branch_id),
  'profitLossId',p_profit_loss_id,'balanceSheetId',p_balance_sheet_id,'classificationId',p_classification_id,
  'profitLossHash',bundle->>'profitLossHash','balanceSheetHash',bundle->>'balanceSheetHash',
  'currency',pl->>'base_currency_code','periodStart',pl->>'period_start','asOf',pl->>'as_of','ratios',ratios);
 return jsonb_build_object('canonicalText',result::text,'sourceHash',encode(extensions.digest(result::text,'sha256'),'hex'));
end $$;
revoke all on function analytics.exact_named_ratio(numeric,numeric),api.wave5_classification_authorize(uuid,uuid,uuid),
 api.wave5_classification_publish(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text),api.wave5_financial_ratios(uuid,uuid,uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_classification_authorize(uuid,uuid,uuid),api.wave5_classification_publish(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text),
 api.wave5_financial_ratios(uuid,uuid,uuid,uuid,uuid,uuid) to authenticated;

-- UNAPPLIED W5-owned date authority. W4 stores, functions and grants are unchanged.
-- Depends on W5 dated-cash/export candidates. W4 providers are optional at install.
insert into core.permissions(code,module,description,privileged) values
 ('analytics.cash_dates.prepare','analytics','Propose authoritative obligation payment dates',true),
 ('analytics.cash_dates.approve','analytics','Independently review obligation payment dates',true)
on conflict(code) do nothing;

create table analytics.cash_date_proposals(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 source_kind text not null check(source_kind in('payroll_obligation','payroll_correction','project_reimbursement')),
 source_id uuid not null,source_hash text not null check(source_hash ~ '^[a-f0-9]{64}$'),
 expected_version bigint not null check(expected_version between 0 and 9007199254740990),
 due_date date not null check(due_date between date '0001-01-01' and date '9999-12-31'),
 reason_code text not null check(reason_code in('payroll_calendar','payment_terms','reviewed_reschedule','correction_recovery')),
 proposal_hash text not null check(proposal_hash ~ '^[a-f0-9]{64}$'),
 prepared_by uuid not null references auth.users(id),prepared_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,branch_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index cash_date_proposal_source_idx on analytics.cash_date_proposals(tenant_id,legal_entity_id,branch_id,source_kind,source_id,prepared_at,id);
create index cash_date_proposal_actor_idx on analytics.cash_date_proposals(prepared_by);
create table analytics.cash_date_decisions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 proposal_id uuid not null unique,source_kind text not null,source_id uuid not null,
 decision text not null check(decision in('approved','rejected')),
 approved_version bigint check(approved_version between 1 and 9007199254740991),
 actor_id uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,source_kind,source_id,approved_version),
 foreign key(tenant_id,legal_entity_id,branch_id,proposal_id) references analytics.cash_date_proposals(tenant_id,legal_entity_id,branch_id,id),
 check((decision='approved')=(approved_version is not null))
);
create index cash_date_decision_source_idx on analytics.cash_date_decisions(tenant_id,legal_entity_id,branch_id,source_kind,source_id,recorded_at);
create index cash_date_decision_actor_idx on analytics.cash_date_decisions(actor_id);
alter table analytics.cash_date_proposals enable row level security;
alter table analytics.cash_date_proposals force row level security;
alter table analytics.cash_date_decisions enable row level security;
alter table analytics.cash_date_decisions force row level security;
revoke all on analytics.cash_date_proposals,analytics.cash_date_decisions from public,anon,authenticated;
create trigger immutable before update or delete on analytics.cash_date_proposals for each row execute function analytics.immutable_evidence();
create trigger immutable before update or delete on analytics.cash_date_decisions for each row execute function analytics.immutable_evidence();

create function analytics.cash_date_access(t uuid,e uuid,b uuid,k text,act text default 'read') returns void
language plpgsql stable security definer set search_path='' as $$declare branch uuid;cap text;module_code text;begin
 perform analytics.cash_access(t,e,b);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='CASH_DATES_MFA_REQUIRED';end if;
 if k not in('payroll_obligation','payroll_correction','project_reimbursement') or k is null or act not in('read','prepare','approve') or act is null then
  raise exception using errcode='22023',message='CASH_DATE_SOURCE_INVALID';end if;
 module_code:=case k when 'project_reimbursement' then 'module.projects' else 'module.people' end;
 if not exists(select 1 from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
  where s.tenant_id=t and p.entitlement_code=module_code and p.enabled
   and ((s.status='trialing' and coalesce(s.trial_started_at,s.created_at)<=statement_timestamp() and s.trial_ends_at>statement_timestamp())
    or (s.status='active' and (s.current_period_ends_at is null or s.current_period_ends_at>statement_timestamp())))) then
  raise exception using errcode='42501',message='CASH_DATE_SOURCE_ENTITLEMENT_REQUIRED';end if;
 if k='project_reimbursement' then
  perform core.wave3_require_scope(t,'projects.view',e,b);perform core.wave3_require_scope(t,'projects.cost.view',e,b);
  if not exists(select 1 from billing.tenant_subscriptions s join billing.plan_entitlements p on p.plan_code=s.plan_code
   where s.tenant_id=t and p.entitlement_code='module.finance' and p.enabled
    and ((s.status='trialing' and coalesce(s.trial_started_at,s.created_at)<=statement_timestamp() and s.trial_ends_at>statement_timestamp())
     or (s.status='active' and (s.current_period_ends_at is null or s.current_period_ends_at>statement_timestamp())))) then
   raise exception using errcode='42501',message='CASH_DATE_SOURCE_ENTITLEMENT_REQUIRED';end if;
 else
  perform core.wave3_require_scope(t,'people.view',e,b);perform core.wave3_require_scope(t,'people.payroll.view',e,b);
 end if;
 if act<>'read' then
  if b is null then raise exception using errcode='42501',message='CASH_DATE_BRANCH_REQUIRED';end if;
  perform core.wave3_require_scope(t,'analytics.cash_dates.'||act,e,b);
 end if;
 -- Entity-wide completeness is conservative: every active branch must be readable.
 for branch in select id from core.branches where tenant_id=t and legal_entity_id=e and status='active' and (b is null or id=b) loop
  if k='project_reimbursement' then
   cap:=case act when 'prepare' then 'projects.expenses.settle' when 'approve' then 'projects.expenses.approve' else 'projects.cost.view' end;
   if to_regprocedure('projects.finance_access(uuid,uuid,uuid,text,boolean)') is null then
    raise exception using errcode='55000',message='CASH_DATE_SOURCE_NOT_INSTALLED';end if;
   execute 'select projects.finance_access($1,$2,$3,$4,false)' using t,e,branch,cap;
  else
   cap:=case act when 'prepare' then 'people.payroll.settle' when 'approve' then case k when 'payroll_correction' then 'people.payroll.correction.approve' else 'people.payroll.approve' end else 'people.payroll.view' end;
   execute 'select people.require_access($1,$2,$3,$4)' using t,e,branch,cap;
   perform core.wave3_require_scope(t,'people.payroll.view',e,branch);
  end if;
 end loop;
end $$;

create function analytics.cash_source_installed(k text) returns boolean
language sql stable security definer set search_path='' as $$select case k
 when 'payroll_obligation' then to_regclass('people_payroll.obligations') is not null and to_regclass('people_payroll.obligation_effects') is not null and to_regclass('people_payroll.settlements') is not null
 when 'payroll_correction' then to_regclass('people_payroll.correction_balances') is not null and to_regclass('people_payroll.correction_balance_effects') is not null and to_regclass('people_payroll.correction_settlements') is not null
 when 'project_reimbursement' then to_regclass('projects.reimbursements') is not null and to_regclass('projects.reimbursement_effects') is not null
 else false end$$;

-- Private adapter over ACTUAL W4 stores. No shape shims, duplicated balances or dates.
create function analytics.cash_source_rows(t uuid,e uuid,b uuid,k text,before_date date,through_time timestamptz)
returns setof jsonb language plpgsql stable security definer set search_path='' as $$
declare q text;r record;source_hash text;proof jsonb;n integer:=0;begin
 if not analytics.cash_source_installed(k) then raise exception using errcode='55000',message='CASH_DATE_SOURCE_NOT_INSTALLED';end if;
 if k in('payroll_obligation','payroll_correction') then
  q:=format($q$with effects as (
   select o.id,o.branch_id,o.currency_code,o.account_id,o.amount original_amount,
    i.id issue_id,i.recorded_at issue_recorded_at,ij.id issue_journal,ij.posting_date issue_date,
    ef.id effect_id,ef.kind,ef.amount,ef.recorded_at,j.id journal_id,j.posting_date,j.status journal_status
   from %1$s o join %2$s p on p.tenant_id=o.tenant_id and p.legal_entity_id=o.legal_entity_id and p.id=o.%3$I
   join %4$s i on i.tenant_id=o.tenant_id and i.legal_entity_id=o.legal_entity_id and i.%5$I=o.id and i.kind='issue'
   join finance.journal_entries ij on ij.tenant_id=o.tenant_id and ij.id=p.posted_journal_id and ij.status='posted'
   join %4$s ef on ef.tenant_id=o.tenant_id and ef.legal_entity_id=o.legal_entity_id and ef.%5$I=o.id
   left join %6$s s on s.tenant_id=o.tenant_id and s.legal_entity_id=o.legal_entity_id and s.id=ef.source_id and ef.kind in('settle','settlement_reverse')
   left join finance.journal_entries j on j.tenant_id=o.tenant_id and j.id=case ef.kind when 'issue' then p.posted_journal_id
    when %7$L then p.reversal_journal_id when 'settle' then s.journal_id when 'settlement_reverse' then s.reversal_journal_id end
   where o.tenant_id=$1 and o.legal_entity_id=$2 and ($3 is null or o.branch_id=$3)
    and i.recorded_at<=$5 and ij.created_at<=$5 and ij.posting_date<$4 and ef.recorded_at<=$5
  ) select id,branch_id,currency_code,account_id,original_amount,issue_id,issue_journal,issue_date,
   coalesce(sum(amount) filter(where posting_date<$4),0) remaining,
   bool_or(journal_id is null or journal_status<>'posted') invalid,
   coalesce(jsonb_agg(jsonb_build_object('id',effect_id,'kind',kind,'amount',amount::text,'journalId',journal_id,
    'postingDate',posting_date::text,'recordedAt',analytics.process_utc(recorded_at)) order by effect_id) filter(where posting_date<$4),'[]') effects
  from effects group by id,branch_id,currency_code,account_id,original_amount,issue_id,issue_journal,issue_date order by id limit 10001$q$,
   case k when 'payroll_obligation' then 'people_payroll.obligations' else 'people_payroll.correction_balances' end,
   case k when 'payroll_obligation' then 'people_payroll.runs' else 'people_payroll.corrections' end,
   case k when 'payroll_obligation' then 'run_id' else 'correction_id' end,
   case k when 'payroll_obligation' then 'people_payroll.obligation_effects' else 'people_payroll.correction_balance_effects' end,
   case k when 'payroll_obligation' then 'obligation_id' else 'balance_id' end,
   case k when 'payroll_obligation' then 'people_payroll.settlements' else 'people_payroll.correction_settlements' end,
   case k when 'payroll_obligation' then 'run_reverse' else 'correction_reverse' end);
 else
  q:=$q$select o.id,o.branch_id,o.currency_code,o.account_id,o.amount original_amount,
   i.id issue_id,o.journal_id issue_journal,o.posting_date issue_date,
   coalesce(sum(ef.amount) filter(where ef.posting_date<$4),0) remaining,
   bool_or(j.id is null or j.status<>'posted' or j.posting_date<>ef.posting_date) invalid,
   coalesce(jsonb_agg(jsonb_build_object('id',ef.id,'kind',ef.kind,'amount',ef.amount::text,'journalId',ef.journal_id,
    'postingDate',ef.posting_date::text,'recordedAt',analytics.process_utc(ef.recorded_at)) order by ef.id) filter(where ef.posting_date<$4),'[]') effects
  from projects.reimbursements o
  join projects.reimbursement_effects i on i.tenant_id=o.tenant_id and i.legal_entity_id=o.legal_entity_id and i.obligation_id=o.id and i.kind='issue'
  join finance.journal_entries ij on ij.tenant_id=o.tenant_id and ij.id=o.journal_id and ij.status='posted'
  join projects.reimbursement_effects ef on ef.tenant_id=o.tenant_id and ef.legal_entity_id=o.legal_entity_id and ef.obligation_id=o.id
  left join finance.journal_entries j on j.tenant_id=o.tenant_id and j.id=ef.journal_id
  where o.tenant_id=$1 and o.legal_entity_id=$2 and ($3 is null or o.branch_id=$3)
   and o.posting_date<$4 and o.recorded_at<=$5 and i.recorded_at<=$5 and ij.created_at<=$5 and ef.recorded_at<=$5
  group by o.id,o.branch_id,o.currency_code,o.account_id,o.amount,i.id,o.journal_id,o.posting_date order by o.id limit 10001$q$;
 end if;
 for r in execute q using t,e,b,before_date,through_time loop
  n:=n+1;if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
  if r.invalid or r.remaining*r.original_amount<0 or abs(r.remaining)>abs(r.original_amount) then
   raise exception using errcode='55000',message='CASH_SOURCE_INTEGRITY_REQUIRED';end if;
  proof:=jsonb_build_object('kind',k,'id',r.id,'tenantId',t,'legalEntityId',e,'branchId',r.branch_id,'currency',r.currency_code,
   'originalAmount',r.original_amount::text,'accountId',r.account_id,'issueId',r.issue_id,'journalId',r.issue_journal,'issueDate',r.issue_date::text);
  source_hash:=encode(extensions.digest(proof::text,'sha256'),'hex');
  return next jsonb_build_object('sourceKind',k,'sourceId',r.id,'sourceHash',source_hash,'branchId',r.branch_id,'currency',r.currency_code,
   'originalAmount',r.original_amount::text,'remainingAmount',r.remaining::text,'inflow',r.original_amount<0,'issueDate',r.issue_date::text,
   'issueId',r.issue_id,'issueJournalId',r.issue_journal,'effects',r.effects);
 end loop;
end $$;

create function analytics.cash_date_current(t uuid,e uuid,k text,i uuid,through_time timestamptz) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'decisionId',d.id,'sourceHash',p.source_hash,'dueDate',p.due_date::text,'version',d.approved_version::text,
  'proposalHash',p.proposal_hash,'approvedAt',analytics.process_utc(d.recorded_at))
 from analytics.cash_date_decisions d join analytics.cash_date_proposals p on p.id=d.proposal_id
 where d.tenant_id=t and d.legal_entity_id=e and d.source_kind=k and d.source_id=i and d.decision='approved' and d.recorded_at<=through_time
 order by d.approved_version desc limit 1$$;

create function api.wave5_cash_date_authorize(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_kind text) returns uuid
language plpgsql stable security definer set search_path='' as $$begin
 perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_kind);
 return auth.uid();end $$;

create function api.wave5_cash_date_sources(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_kind text,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;last_id uuid;n integer;begin
 perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_kind);
 if p_branch_id is null then raise exception using errcode='42501',message='CASH_DATE_BRANCH_REQUIRED';end if;
 with all_rows as(select x from analytics.cash_source_rows(p_tenant_id,p_legal_entity_id,p_branch_id,p_kind,
  (statement_timestamp() at time zone 'UTC')::date+1,statement_timestamp()) x),bounded as(
  select x from all_rows where (p_after is null or (x->>'sourceId')::uuid>p_after) and (x->>'remainingAmount')::numeric<>0 order by x->>'sourceId' limit 51)
 select coalesce(jsonb_agg((x-array['effects','issueId','issueJournalId'])||jsonb_build_object('approved',analytics.cash_date_current(p_tenant_id,p_legal_entity_id,p_kind,(x->>'sourceId')::uuid,statement_timestamp())) order by x->>'sourceId'),'[]'),count(*)
 into rows,n from bounded;
 if n=51 then last_id:=(rows->49->>'sourceId')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('rows',rows,'next',last_id);
end $$;

create function api.wave5_cash_date_get(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare p analytics.cash_date_proposals%rowtype;d analytics.cash_date_decisions%rowtype;begin
 select * into p from analytics.cash_date_proposals where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_id;
 if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,p.source_kind);
 select * into d from analytics.cash_date_decisions where proposal_id=p.id;
 return jsonb_build_object('id',p.id,'sourceKind',p.source_kind,'sourceId',p.source_id,'sourceHash',p.source_hash,'dueDate',p.due_date::text,
  'reasonCode',p.reason_code,'proposalHash',p.proposal_hash,'expectedVersion',p.expected_version::text,'preparedBy',p.prepared_by,
  'preparedAt',analytics.process_utc(p.prepared_at),'decision',d.decision,'approvedVersion',d.approved_version::text,
  'currentApproval',analytics.cash_date_current(p_tenant_id,p_legal_entity_id,p.source_kind,p.source_id,statement_timestamp()));
end $$;

create function api.wave5_cash_date_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_issued_at timestamptz,p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p analytics.cash_date_proposals%rowtype;r jsonb;cur jsonb;h text;replay jsonb;receipt jsonb;
 i uuid;k text;source uuid;version bigint;new_version bigint;due date;decision text;begin
 if p_command_id is null or p_idempotency_key is null or p_issued_at is null or not isfinite(p_issued_at)
  or p_issued_at>clock_timestamp()+interval '5 minutes' or p_action not in('prepare','approve','reject') or p_action is null
  or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>8192 then
  raise exception using errcode='22023',message='CASH_DATE_COMMAND_INVALID';end if;
 i:=(p_payload->>'id')::uuid;
 if p_action='prepare' then
  if not(p_payload ?& array['id','sourceKind','sourceId','sourceHash','dueDate','reasonCode','expectedVersion'])
   or (p_payload-array['id','sourceKind','sourceId','sourceHash','dueDate','reasonCode','expectedVersion'])<>'{}'
   or exists(select 1 from jsonb_each(p_payload) where jsonb_typeof(value)<>'string')
   or coalesce(p_payload->>'sourceHash','')!~'^[a-f0-9]{64}$' or coalesce(p_payload->>'expectedVersion','')!~'^(0|[1-9][0-9]{0,15})$'
   or coalesce(p_payload->>'dueDate','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or coalesce(p_payload->>'reasonCode','') not in('payroll_calendar','payment_terms','reviewed_reschedule','correction_recovery') then
   raise exception using errcode='22023',message='CASH_DATE_COMMAND_INVALID';end if;
  k:=p_payload->>'sourceKind';source:=(p_payload->>'sourceId')::uuid;version:=(p_payload->>'expectedVersion')::bigint;due:=(p_payload->>'dueDate')::date;
 else
  if not(p_payload ?& array['id','proposalHash']) or (p_payload-array['id','proposalHash'])<>'{}'
   or exists(select 1 from jsonb_each(p_payload) where jsonb_typeof(value)<>'string') or coalesce(p_payload->>'proposalHash','')!~'^[a-f0-9]{64}$' then
   raise exception using errcode='22023',message='CASH_DATE_COMMAND_INVALID';end if;
  select * into p from analytics.cash_date_proposals where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=i;
  if not found then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
  k:=p.source_kind;source:=p.source_id;version:=p.expected_version;
 end if;
 perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,k,case when p_action='prepare' then 'prepare' else 'approve' end);
 h:=core.wave3_request_hash('analytics.cash_dates.'||p_action,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,
  jsonb_build_object('issuedAt',analytics.process_utc(p_issued_at),'payload',p_payload),version);
 replay:=core.wave3_replay(p_tenant_id,'analytics.cash_dates.'||p_action,p_command_id,p_idempotency_key,h);
 if replay is not null then return replay;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_legal_entity_id::text||':'||k||':'||source::text,512));
 cur:=analytics.cash_date_current(p_tenant_id,p_legal_entity_id,k,source,clock_timestamp());
 if version is distinct from coalesce((cur->>'version')::bigint,0) then raise exception using errcode='40001',message='CASH_DATE_VERSION_CONFLICT';end if;
 select x into r from analytics.cash_source_rows(p_tenant_id,p_legal_entity_id,p_branch_id,k,
  (statement_timestamp() at time zone 'UTC')::date+1,clock_timestamp()) x where x->>'sourceId'=source::text;
 if r is null or (r->>'remainingAmount')::numeric=0 then raise exception using errcode='55000',message='CASH_DATE_ISSUED_SOURCE_REQUIRED';end if;
 if p_action='prepare' then
  if i is null or version not between 0 and 9007199254740990 or due not between date '0001-01-01' and date '9999-12-31'
   or due<(r->>'issueDate')::date then raise exception using errcode='22023',message='CASH_DATE_COMMAND_INVALID';end if;
  if p_payload->>'sourceHash' is distinct from r->>'sourceHash' then raise exception using errcode='40001',message='CASH_DATE_SOURCE_CHANGED';end if;
  insert into analytics.cash_date_proposals(id,tenant_id,legal_entity_id,branch_id,source_kind,source_id,source_hash,expected_version,due_date,reason_code,proposal_hash,prepared_by)
   values(i,p_tenant_id,p_legal_entity_id,p_branch_id,k,source,r->>'sourceHash',version,due,p_payload->>'reasonCode',
    encode(extensions.digest(jsonb_build_object('scope',jsonb_build_array(p_tenant_id,p_legal_entity_id,p_branch_id),'payload',p_payload)::text,'sha256'),'hex'),auth.uid()) returning * into p;
  receipt:=jsonb_build_object('id',p.id,'version',version::text,'status','prepared','proposalHash',p.proposal_hash);
 else
  if p.prepared_by=auth.uid() then raise exception using errcode='42501',message='CASH_DATE_INDEPENDENT_APPROVER_REQUIRED';end if;
  if p.proposal_hash is distinct from p_payload->>'proposalHash' then raise exception using errcode='40001',message='CASH_DATE_PROPOSAL_CHANGED';end if;
  if p.source_hash is distinct from r->>'sourceHash' then raise exception using errcode='40001',message='CASH_DATE_SOURCE_CHANGED';end if;
  if exists(select 1 from analytics.cash_date_decisions where proposal_id=i) then raise exception using errcode='55000',message='CASH_DATE_ALREADY_DECIDED';end if;
  decision:=case p_action when 'approve' then 'approved' else 'rejected' end;new_version:=case when p_action='approve' then version+1 end;
  insert into analytics.cash_date_decisions values(p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,i,k,source,decision,new_version,auth.uid(),clock_timestamp());
  receipt:=jsonb_build_object('id',i,'version',coalesce(new_version,version)::text,'status',decision,'proposalHash',p.proposal_hash);
 end if;
 return core.wave3_finish_command(p_tenant_id,'analytics.cash_dates.'||p_action,p_command_id,'analytics.cash_date',i,p_idempotency_key,h,null,
  receipt,p_legal_entity_id,p_branch_id);
end $$;

-- Extend rather than edit/replay the reviewed bank/AR/AP source.
alter function api.wave5_cash_basis(uuid,uuid,uuid,date,date,timestamptz) rename to wave5_cash_basis_v2;
revoke all on function api.wave5_cash_basis_v2(uuid,uuid,uuid,date,date,timestamptz) from public,anon,authenticated;
create function api.wave5_cash_basis(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_start date,p_end date,p_recorded_through timestamptz) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare data jsonb;providers jsonb;statuses jsonb;family text;k text;row jsonb;d jsonb;rows jsonb;refs jsonb;st text;n integer;begin
 data:=(api.wave5_cash_basis_v2(p_tenant_id,p_legal_entity_id,p_branch_id,p_start,p_end,p_recorded_through)->>'canonicalText')::jsonb;
 providers:=data->'completeProviders';statuses:=data->'providerStatus';
 -- AR/AP use explicit directions in the new contract too.
 select coalesce(jsonb_agg(x||jsonb_build_object('inflow',x->>'provider'='receivables') order by x->>'provider',x->>'id'),'[]') into rows from jsonb_array_elements(data->'obligations') x;
 data:=jsonb_set(data,'{obligations}',rows);
 foreach family in array array['payroll','project_reimbursements'] loop
  rows:='[]';refs:='[]';st:='available';n:=0;
  if (family='payroll' and (not analytics.cash_source_installed('payroll_obligation') or not analytics.cash_source_installed('payroll_correction')))
   or (family='project_reimbursements' and not analytics.cash_source_installed('project_reimbursement')) then st:='source_not_installed';
  else
   begin
    perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,case family when 'payroll' then 'payroll_obligation' else 'project_reimbursement' end);
   exception when insufficient_privilege then st:=case when coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then 'mfa_required' else 'permission_required' end;end;
   if st='available' then
    foreach k in array case family when 'payroll' then array['payroll_obligation','payroll_correction'] else array['project_reimbursement'] end loop
     for row in select * from analytics.cash_source_rows(p_tenant_id,p_legal_entity_id,p_branch_id,k,p_start,p_recorded_through) loop
      n:=n+1;if n>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
      -- Also cover inactive source branches: no row may bypass current authority.
      begin perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,(row->>'branchId')::uuid,k);
      exception when insufficient_privilege then st:='permission_required';end;
      if (row->>'remainingAmount')::numeric=0 then continue;end if;
      d:=analytics.cash_date_current(p_tenant_id,p_legal_entity_id,k,(row->>'sourceId')::uuid,p_recorded_through);
      if d is null then if st='available' then st:='missing_payment_date';end if;continue;end if;
      if d->>'sourceHash' is distinct from row->>'sourceHash' then raise exception using errcode='55000',message='CASH_DATE_SOURCE_CHANGED';end if;
      if (d->>'dueDate')::date<p_start or (d->>'dueDate')::date>=p_end then continue;end if;
      rows:=rows||jsonb_build_array(jsonb_build_object('id',row->>'sourceId','branchId',row->>'branchId','currency',row->>'currency',
       'dueDate',d->>'dueDate','amount',abs((row->>'remainingAmount')::numeric)::text,'version',d->>'version','provider',family,'inflow',row->'inflow'));
      refs:=refs||jsonb_build_array(jsonb_build_object('kind',k,'id',row->>'sourceId','branchId',row->>'branchId',
       'sourceHash',row->>'sourceHash','originalAmount',row->>'originalAmount','issueId',row->>'issueId','journalId',row->>'issueJournalId',
       'issueDate',row->>'issueDate','dateRevision',d,'effects',row->'effects'));
      if jsonb_array_length(rows)>10000 or octet_length(refs::text)>8388608 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
     end loop;
    end loop;
   end if;
  end if;
  statuses:=jsonb_set(statuses,array[family],to_jsonb(st));
  if st='available' then
   providers:=providers||jsonb_build_array(family);data:=jsonb_set(data,'{obligations}',(data->'obligations')||rows);
   data:=jsonb_set(data,'{sources}',(data->'sources')||refs);
  end if;
 end loop;
 if jsonb_array_length(data->'controls')+jsonb_array_length(data->'obligations')>10000 or jsonb_array_length(data->'sources')>10000
  or (select coalesce(sum(jsonb_array_length(x->'effects')),0) from jsonb_array_elements(data->'sources') x where x ? 'effects')+jsonb_array_length(data->'sources')>10000 then
  raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 if exists(select x->>'id' from jsonb_array_elements(data->'obligations') x group by x->>'id' having count(*)>1) then
  raise exception using errcode='55000',message='CASH_OBLIGATION_ID_AMBIGUOUS';end if;
 data:=data||jsonb_build_object('contractRevision',3,'definition','dated_transaction_cash_all_obligations.v3','completeProviders',providers,
  'providerStatus',statuses,'exclusions',jsonb_build_array('overdue_before_horizon','unallocated_credits','recognition_on_or_after_opening'));
 if octet_length(data::text)>8388608 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 return jsonb_build_object('canonicalText',data::text,'sourceHash',encode(extensions.digest(data::text,'sha256'),'hex'));
end $$;

-- Freeze/reopen recheck each captured private source family, even with zero rows.
alter function api.wave5_cash_save(uuid,uuid,uuid,uuid,text,jsonb) rename to wave5_cash_save_v2;
revoke all on function api.wave5_cash_save_v2(uuid,uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;
create function api.wave5_cash_save(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid,p_source_hash text,p_parameters jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$declare basis jsonb;begin
 if not exists(select 1 from analytics.cash_scenario_revisions where id=p_id) then
  basis:=(api.wave5_cash_basis(p_tenant_id,p_legal_entity_id,p_branch_id,(p_parameters->>'horizonStart')::date,(p_parameters->>'horizonEnd')::date,(p_parameters->>'recordedThrough')::timestamptz)->>'canonicalText')::jsonb;
  if not(basis->'completeProviders' ?& array['bank_cash','receivables','payables','payroll','project_reimbursements']) then
   raise exception using errcode='55000',message='CASH_COMPLETE_PROVIDERS_REQUIRED';end if;
 end if;
 return api.wave5_cash_save_v2(p_tenant_id,p_legal_entity_id,p_branch_id,p_id,p_source_hash,p_parameters);
end $$;
alter function api.wave5_cash_get(uuid,uuid,uuid,uuid) rename to wave5_cash_get_v2;
revoke all on function api.wave5_cash_get_v2(uuid,uuid,uuid,uuid) from public,anon,authenticated;
create function api.wave5_cash_get(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare result jsonb;data jsonb;row jsonb;begin
 result:=api.wave5_cash_get_v2(p_tenant_id,p_legal_entity_id,p_branch_id,p_id);data:=(result->>'canonicalText')::jsonb;
 if data->'completeProviders' ? 'payroll' then perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,'payroll_obligation');end if;
 if data->'completeProviders' ? 'project_reimbursements' then perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,p_branch_id,'project_reimbursement');end if;
 for row in select * from jsonb_array_elements(data->'sources') where value->>'kind' in('payroll_obligation','payroll_correction','project_reimbursement') loop
  perform analytics.cash_date_access(p_tenant_id,p_legal_entity_id,(row->>'branchId')::uuid,row->>'kind');
 end loop;return result;
end $$;

-- Governed W3 codec/jobs are preserved; v2/pipeline documents retain their shape.
alter function finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb) rename to wave5_report_export_document_v2;
revoke all on function finance.wave5_report_export_document_v2(uuid,uuid,uuid,text,uuid,text,jsonb) from public,anon,authenticated;
create function finance.report_export_document(t uuid,e uuid,b uuid,resource text,i uuid,section text,filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare f jsonb;s jsonb;data jsonb;rows jsonb;meta jsonb;n integer;begin
 if resource is distinct from 'w5_cash' then return finance.wave5_report_export_document_v2(t,e,b,resource,i,section,filters);end if;
 s:=api.wave5_cash_get(t,e,b,i);data:=(s->>'canonicalText')::jsonb;
 if data->>'contractRevision'<>'3' then return finance.wave5_report_export_document_v2(t,e,b,resource,i,section,filters);end if;
 perform core.wave3_require_scope(t,'finance.reports.export',e,b);
 if section is distinct from 'buckets' or filters is null or jsonb_typeof(filters)<>'object' or (filters-'currency')<>'{}'
  or (filters ? 'currency' and (jsonb_typeof(filters->'currency')<>'string' or coalesce(filters->>'currency','')!~'^[A-Z]{3}$')) then
  raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
 if not(data->'completeProviders' ?& array['bank_cash','receivables','payables','payroll','project_reimbursements']) then
  raise exception using errcode='55000',message='CASH_COMPLETE_PROVIDERS_REQUIRED';end if;
 if exists(select 1 from jsonb_array_elements(data->'obligations') o where not exists(select 1 from jsonb_array_elements(data->'controls') c where c->>'currency'=o->>'currency')) then
  raise exception using errcode='55000',message='CASH_CURRENCY_MAPPING_REQUIRED';end if;
 with opening as(select x->>'currency' currency,sum((x->>'amount')::numeric) balance from jsonb_array_elements(data->'controls') x group by x->>'currency'),
 flows as(select o->>'currency' currency,coalesce((s#>>array['parameters','overrides',o->>'id','dueDate'])::date,(o->>'dueDate')::date) due_date,
  coalesce((s#>>array['parameters','overrides',o->>'id','remainingUnits'])::numeric/1000000,(o->>'amount')::numeric) amount,(o->>'inflow')::boolean inflow from jsonb_array_elements(data->'obligations') o),
 days as(select c.currency,c.balance,d::date bucket_date from opening c cross join generate_series((data->>'horizonStart')::date,(data->>'horizonEnd')::date-1,interval '1 day') d where filters->>'currency' is null or c.currency=filters->>'currency'),
 buckets as(select d.currency,d.bucket_date,d.balance,coalesce(sum(f.amount) filter(where f.inflow),0) inflow,coalesce(sum(f.amount) filter(where not f.inflow),0) outflow
  from days d left join flows f on f.currency=d.currency and f.due_date=d.bucket_date group by d.currency,d.bucket_date,d.balance)
 select coalesce(jsonb_agg(jsonb_build_object('date',bucket_date::text,'currency',currency,'inflow',inflow::text,'outflow',outflow::text,'balance',total::text) order by currency,bucket_date),'[]'),count(*) into rows,n
 from(select currency,bucket_date,inflow,outflow,balance+sum(inflow-outflow) over(partition by currency order by bucket_date) total from buckets order by currency,bucket_date limit 10001) x;
 if n>10000 then raise exception using errcode='54000',message='REPORT_EXPORT_ROW_LIMIT';end if;
 meta:=jsonb_build_object('as_of',data->>'horizonStart','generated_at',data->>'recordedThrough','horizon_start',data->>'horizonStart','horizon_end',data->>'horizonEnd',
  'calculation',data->>'definition','source_basis_hash',s->>'sourceHash','scenario_parameters',s->'parameters','exclusions',data->'exclusions','complete_providers',data->'completeProviders',
  'id',i,'version',1,'tenant_id',t,'legal_entity_id',e,'branch_id',b,'actor_id',auth.uid(),'working_branch_id',b,'source_type',resource,'source_id',i,'section',section,'filters',filters,'row_count',jsonb_array_length(rows));
 f:=jsonb_build_object('version',1,'metadata',meta,'rows',rows);
 if octet_length(f::text)>8388608 then raise exception using errcode='54000',message='REPORT_EXPORT_EVIDENCE_LIMIT';end if;return f;
end $$;

revoke all on function analytics.cash_date_access(uuid,uuid,uuid,text,text),analytics.cash_source_installed(text),analytics.cash_source_rows(uuid,uuid,uuid,text,date,timestamptz),analytics.cash_date_current(uuid,uuid,text,uuid,timestamptz),
 finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb) from public,anon,authenticated;
revoke all on function api.wave5_cash_date_authorize(uuid,uuid,uuid,text),api.wave5_cash_date_sources(uuid,uuid,uuid,text,uuid),api.wave5_cash_date_get(uuid,uuid,uuid,uuid),api.wave5_cash_date_command(uuid,uuid,uuid,uuid,uuid,timestamptz,text,jsonb),
 api.wave5_cash_basis(uuid,uuid,uuid,date,date,timestamptz),api.wave5_cash_save(uuid,uuid,uuid,uuid,text,jsonb),api.wave5_cash_get(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function api.wave5_cash_date_authorize(uuid,uuid,uuid,text),api.wave5_cash_date_sources(uuid,uuid,uuid,text,uuid),api.wave5_cash_date_get(uuid,uuid,uuid,uuid),api.wave5_cash_date_command(uuid,uuid,uuid,uuid,uuid,timestamptz,text,jsonb) to authenticated;
grant execute on function api.wave5_cash_basis(uuid,uuid,uuid,date,date,timestamptz),api.wave5_cash_save(uuid,uuid,uuid,uuid,text,jsonb),api.wave5_cash_get(uuid,uuid,uuid,uuid) to authenticated;

-- UNAPPLIED. Runtime adapter only; no account, scope, key or operator is seeded.
-- Derived delivery body SHA256 1a636229a0749cf9d6334ae49efe8ff38627b6a2d1bb642789a28e86efd1c663.
-- Keeps the earlier candidate and all Wave 3/4 sources byte-for-byte unchanged.
create table intelligence_control.runtime_worker_scopes(
 runtime_id uuid not null,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 enabled boolean not null default false,issued_at timestamptz not null default statement_timestamp(),expires_at timestamptz not null,
 primary key(runtime_id,tenant_id,legal_entity_id,branch_id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 check(isfinite(expires_at) and expires_at>issued_at and expires_at<=issued_at+interval '7 days'));
alter table intelligence_control.runtime_worker_scopes enable row level security;
alter table intelligence_control.runtime_worker_scopes force row level security;
revoke all on intelligence_control.runtime_worker_scopes from public,anon,authenticated;

create function intelligence_control.runtime_scope_allowed(r uuid,t uuid,e uuid,b uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from intelligence_control.runtime_worker_scopes s join core.branches br
  on br.tenant_id=s.tenant_id and br.legal_entity_id=s.legal_entity_id and br.id=s.branch_id
  where s.runtime_id=r and s.tenant_id=t and s.legal_entity_id=e and s.branch_id=b
   and s.enabled and s.issued_at<=statement_timestamp() and s.expires_at>statement_timestamp() and br.status='active')$$;
create function intelligence_control.runtime_tenant_allowed(r uuid,t uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from intelligence_control.runtime_worker_scopes s
  where s.runtime_id=r and s.tenant_id=t and intelligence_control.runtime_scope_allowed(r,t,s.legal_entity_id,s.branch_id))$$;
create function intelligence_control.runtime_worker_required(r uuid) returns void
language plpgsql stable security definer set search_path='' as $$begin
 perform intelligence_control.worker_required();
 if not exists(select 1 from intelligence_control.runtime_worker_scopes s
  where s.runtime_id=r and intelligence_control.runtime_scope_allowed(r,s.tenant_id,s.legal_entity_id,s.branch_id)) then
  raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;end$$;
revoke all on function intelligence_control.runtime_scope_allowed(uuid,uuid,uuid,uuid),
 intelligence_control.runtime_tenant_allowed(uuid,uuid),intelligence_control.runtime_worker_required(uuid) from public,anon,authenticated;

-- The separately designated operator can exercise the installed real MFA grant
-- API only within the exact owner-approved tenant/reason/deadline. Other operator
-- records and existing installed functions retain their contracts.
create table intelligence_control.runtime_operator_authorities(
 operator_id uuid primary key references intelligence_control.operators(actor_id),
 tenant_id uuid not null references core.tenants(id),reason text not null,
 issued_at timestamptz not null default statement_timestamp(),expires_at timestamptz not null,
 check(length(trim(reason)) between 10 and 500),
 check(isfinite(expires_at) and expires_at>issued_at and expires_at<=issued_at+interval '45 minutes'));
alter table intelligence_control.runtime_operator_authorities enable row level security;
alter table intelligence_control.runtime_operator_authorities force row level security;
revoke all on intelligence_control.runtime_operator_authorities from public,anon,authenticated;
create trigger immutable before update or delete on intelligence_control.runtime_operator_authorities
 for each row execute function analytics.immutable_evidence();
create function intelligence_control.runtime_operator_guard() returns trigger
language plpgsql security definer set search_path='' as $$declare a intelligence_control.runtime_operator_authorities%rowtype;begin
 select * into a from intelligence_control.runtime_operator_authorities where operator_id in(new.operator_id,new.issued_by)
  order by case when operator_id=new.issued_by then 0 else 1 end limit 1;
 if found and (new.operator_id<>a.operator_id or new.tenant_id<>a.tenant_id or new.issued_by<>a.operator_id or auth.uid() is distinct from a.operator_id
  or new.reason<>a.reason or new.issued_at<a.issued_at or new.issued_at>=a.expires_at or new.expires_at>a.expires_at) then
  raise exception using errcode='42501',message='RUNTIME_OPERATOR_SCOPE_DENIED';end if;
 return new;end$$;
revoke all on function intelligence_control.runtime_operator_guard() from public,anon,authenticated;
create trigger runtime_operator_scope before insert on intelligence_control.operator_tenant_grants
 for each row execute function intelligence_control.runtime_operator_guard();
create function api.wave5_runtime_delivery_worker(p_runtime_id uuid,p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare d intelligence_control.delivery_heads%rowtype;s intelligence_control.integration_subscriptions%rowtype;
 o intelligence_control.delivery_outcomes%rowtype;subscription billing.tenant_subscriptions%rowtype;v_state text;status integer;begin
 perform intelligence_control.runtime_worker_required(p_runtime_id);
 if p_action not in('readiness','claim','settle_acknowledged') and not exists(
  select 1 from intelligence_control.delivery_heads h join intelligence_control.integration_subscriptions s0
   on s0.tenant_id=h.tenant_id and s0.id=h.subscription_id
  where h.id=(p_payload->>'deliveryId')::uuid
   and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id)) then
  raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action='readiness' then return jsonb_build_object('contractRevision',1,'ready',true,'providers',jsonb_build_object('committed_webhook.v1',1,'synthetic_subscription.v1',1));end if;
 if p_action='claim' then
  -- A lease lost after send cannot be auto-retried. ACK rows can be reconciled
  -- separately; expired attempts with no outcome retain uncertain reservations.
  update intelligence_control.delivery_heads set state='unknown' where state='leased' and lease_until<=statement_timestamp()
   and exists(select 1 from intelligence_control.integration_subscriptions s0
    where s0.id=subscription_id and s0.tenant_id=delivery_heads.tenant_id
     and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id));
  insert into intelligence_control.delivery_heads(tenant_id,subscription_id,event_id)
   select s0.tenant_id,s0.id,e.id from intelligence_control.integration_subscriptions s0
   join analytics.pipeline_forecasts f on f.tenant_id=s0.tenant_id and f.legal_entity_id=s0.legal_entity_id and f.branch_id is not distinct from s0.branch_id
   join core.outbox_events e on e.tenant_id=f.tenant_id and e.aggregate_id=f.id and e.aggregate_type='pipeline_forecast' and e.topic='analytics.freeze_pipeline'
   where s0.enabled and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id)
    and e.created_at>=s0.created_at and not exists(select 1 from intelligence_control.delivery_heads h
    where h.tenant_id=s0.tenant_id and h.subscription_id=s0.id and h.event_id=e.id and h.generation=0)
   order by e.created_at,e.id limit 1000 on conflict do nothing;
  select h.* into d from intelligence_control.delivery_heads h where
   exists(select 1 from intelligence_control.integration_subscriptions s0 where s0.tenant_id=h.tenant_id and s0.id=h.subscription_id
    and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id))
   and state in('pending','retry') and available_at<=statement_timestamp()
   and attempt<8 order by available_at,id for update skip locked limit 1;
  if not found then return null;end if;
  select * into s from intelligence_control.integration_subscriptions where tenant_id=d.tenant_id and id=d.subscription_id and enabled;
  if not found then update intelligence_control.delivery_heads set state='dead_letter' where id=d.id;return null;end if;
  select * into subscription from billing.tenant_subscriptions where tenant_id=d.tenant_id;
  if d.period_start is null then
   d.period_start:=case when subscription.status='trialing' then coalesce(subscription.trial_started_at,subscription.created_at)
    else coalesce((select period_start from intelligence_control.quota_periods where tenant_id=d.tenant_id and metric_code='webhook.deliveries'
     and period_end=subscription.current_period_ends_at limit 1),date_trunc('month',statement_timestamp())) end;
   d.period_end:=case when subscription.status='trialing' then subscription.trial_ends_at else subscription.current_period_ends_at end;
  end if;
  if d.period_end is null then raise exception using errcode='55000',message='BILLING_PERIOD_UNAVAILABLE';end if;
  update intelligence_control.delivery_heads set attempt=attempt+1,state='leased',lease_id=gen_random_uuid(),lease_until=statement_timestamp()+interval '60 seconds',
   period_start=d.period_start,period_end=d.period_end where id=d.id returning * into d;
  insert into intelligence_control.delivery_attempts values(d.tenant_id,d.id,d.attempt,d.lease_id,s.key_version,s.version,statement_timestamp());
  begin
   return intelligence_control.delivery_authorize(d.id,d.lease_id);
  exception when insufficient_privilege then
   -- No send occurred. Keep this denied item from starving another tenant's
   -- queue; replay still requires a reasoned MFA review after access is fixed.
   update intelligence_control.delivery_heads set state='dead_letter' where id=d.id;
   return null;
  end;
 end if;
 if p_action='authorize' then return intelligence_control.delivery_authorize((p_payload->>'deliveryId')::uuid,(p_payload->>'leaseId')::uuid);end if;
 if p_action='key_ref' then
  perform intelligence_control.delivery_authorize((p_payload->>'deliveryId')::uuid,(p_payload->>'leaseId')::uuid);
  return to_jsonb((select s0.key_ref from intelligence_control.delivery_heads d0 join intelligence_control.integration_subscriptions s0 on s0.tenant_id=d0.tenant_id and s0.id=d0.subscription_id where d0.id=(p_payload->>'deliveryId')::uuid));
 end if;
 if p_action='outcome' then
  select * into d from intelligence_control.delivery_heads where id=(p_payload->>'deliveryId')::uuid and lease_id=(p_payload->>'leaseId')::uuid for update;
  if not found then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
  v_state:=p_payload->>'state';status:=(p_payload->>'httpStatus')::integer;
  if v_state not in('acknowledged','retry','unknown','dead_letter') or v_state is null
   or (v_state='acknowledged' and (status is null or status not between 200 and 299))
   or (v_state='unknown' and status is not null) or (v_state in('retry','dead_letter') and (status is null or status between 200 and 299))
   or (v_state='retry' and d.attempt>=8) or (v_state='dead_letter' and d.attempt<>8) then
   raise exception using errcode='22023',message='OUTCOME_MISMATCH';end if;
  select * into o from intelligence_control.delivery_outcomes where tenant_id=d.tenant_id and delivery_id=d.id and attempt=d.attempt;
  if found then
   if o.state<>v_state or o.http_status is distinct from status then raise exception using errcode='22023',message='IDEMPOTENCY_MISMATCH';end if;return '{}'::jsonb;
  end if;
  insert into intelligence_control.delivery_outcomes values(d.tenant_id,d.id,d.attempt,v_state,status,statement_timestamp());
  update intelligence_control.delivery_heads set state=v_state,available_at=statement_timestamp()+make_interval(secs=>least(3600,15*power(2,d.attempt-1)::integer)) where id=d.id;
  return '{}'::jsonb;
 end if;
 if p_action='settle_acknowledged' then
  for d in select * from intelligence_control.delivery_heads h where h.state='acknowledged' and exists(
   select 1 from intelligence_control.integration_subscriptions s0 where s0.tenant_id=h.tenant_id and s0.id=h.subscription_id
    and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id))
   and not exists(select 1 from intelligence_control.usage_events u where u.tenant_id=h.tenant_id and u.invocation_id=h.invocation_id)
   order by h.id for update skip locked limit 100 loop
   perform api.wave5_settle_usage(d.tenant_id,d.invocation_id,d.usage_event_id,'1');
  end loop;return '{}'::jsonb;
 end if;
 raise exception using errcode='22023',message='VALIDATION_ERROR';
end $$;
revoke all on function api.wave5_integration_manage(uuid,uuid,uuid,text,uuid,bigint,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_integration_manage(uuid,uuid,uuid,text,uuid,bigint,jsonb) to authenticated;

revoke all on function api.wave5_runtime_delivery_worker(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_runtime_delivery_worker(uuid,text,jsonb) to service_role;

create function api.wave5_runtime_worker(p_runtime_id uuid,p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare tenant uuid;entity uuid;branch uuid;s jsonb;rows jsonb;n integer;cursor uuid;begin
 perform intelligence_control.runtime_worker_required(p_runtime_id);
 if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if p_action like 'delivery.%' then
  return api.wave5_runtime_delivery_worker(p_runtime_id,substring(p_action from 10),p_payload);end if;
 if p_action='model.readiness' then return api.wave5_model_worker('readiness',p_payload);end if;
 if p_action like 'external.%' then
  select tenant_id,legal_entity_id,branch_id into tenant,entity,branch from intelligence_control.integration_credentials
   where token_hash=p_payload->>'tokenHash';
 elsif p_action='model.begin' then
  select f.tenant_id,f.legal_entity_id,f.branch_id into tenant,entity,branch from analytics.pipeline_forecasts f
   where f.tenant_id=(p_payload->>'tenantId')::uuid and f.id=(p_payload->>'sourceId')::uuid;
 elsif p_action='model.outcome' then
  select f.tenant_id,f.legal_entity_id,f.branch_id into tenant,entity,branch from intelligence_control.model_invocations i
   join analytics.pipeline_forecasts f on f.tenant_id=i.tenant_id and f.id=i.source_id
   where i.invocation_id=(p_payload->>'invocationId')::uuid;
 elsif p_action='entitlement' then
  s:=p_payload->'scope';tenant:=(s->>'tenantId')::uuid;entity:=(s->>'legalEntityId')::uuid;branch:=(s->>'branchId')::uuid;
 elsif p_action in('usage.reserve','usage.settle','subscription.apply','health.collect') then
  tenant:=(p_payload->>'tenantId')::uuid;
  if not intelligence_control.runtime_tenant_allowed(p_runtime_id,tenant) then
   raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
  if p_action='usage.reserve' then return api.wave5_reserve_usage(tenant,(p_payload->>'invocationId')::uuid,p_payload->>'metric',
   (p_payload->>'periodStart')::timestamptz,(p_payload->>'periodEnd')::timestamptz,p_payload->>'quantity');end if;
  if p_action='usage.settle' then return api.wave5_settle_usage(tenant,(p_payload->>'invocationId')::uuid,(p_payload->>'eventId')::uuid,p_payload->>'quantity');end if;
  if p_action='subscription.apply' then return api.apply_synthetic_subscription(tenant,(p_payload->>'revisionId')::uuid);end if;
  return api.wave5_health_collect((p_payload->>'collectionId')::uuid,tenant);
 elsif p_action='subscription.due' then
  select coalesce(jsonb_agg(jsonb_build_object('tenantId',tenant_id,'revisionId',id) order by id),'[]'),count(*) into rows,n
   from(select r.id,r.tenant_id from intelligence_control.subscription_revisions r
    join intelligence_control.synthetic_tenants t on t.tenant_id=r.tenant_id and t.allowed
    where intelligence_control.runtime_tenant_allowed(p_runtime_id,r.tenant_id)
     and r.trial_starts_at<=statement_timestamp() and r.trial_ends_at>statement_timestamp()
     and (p_payload->>'after' is null or r.id>(p_payload->>'after')::uuid)
     and not exists(select 1 from intelligence_control.subscription_activations a where a.tenant_id=r.tenant_id and a.revision_id=r.id)
     order by r.id limit 51) q;
  if n>50 then cursor:=(rows->49->>'revisionId')::uuid;rows:=rows-50;end if;
  return jsonb_build_object('contractRevision',1,'items',rows,'nextCursor',cursor);
 else raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 if not intelligence_control.runtime_scope_allowed(p_runtime_id,tenant,entity,branch) then
  raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action in('external.credential','external.reserve','external.dispatch') then
  return api.wave5_external_worker(substring(p_action from 10),p_payload);end if;
 if p_action='model.begin' then
  perform pg_advisory_xact_lock(hashtextextended(tenant::text||':wave5-runtime-model-budget',531));
  if not exists(select 1 from intelligence_control.model_invocations where invocation_id=(p_payload->>'invocationId')::uuid)
   and (select count(*) from intelligence_control.model_invocations where tenant_id=tenant)>=4 then
   raise exception using errcode='54000',message='MODEL_CALL_LIMIT';end if;
  if coalesce(p_payload->>'maxTokens','')!~ '^[1-9][0-9]{0,3}$' or (p_payload->>'maxTokens')::numeric>2000 then
   raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 end if;
 if p_action in('model.begin','model.outcome') then return api.wave5_model_worker(substring(p_action from 7),p_payload);end if;
 if p_action='entitlement' then return to_jsonb(api.wave5_worker_entitlement(s));end if;
 raise exception using errcode='22023',message='VALIDATION_ERROR';
end$$;
revoke all on function api.wave5_runtime_worker(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_runtime_worker(uuid,text,jsonb) to service_role;

-- UNINSTALLED candidate. Creates contracts only: no authorities, keys, jobs,
-- receiver registrations or synthetic activation are seeded by installation.
create table intelligence_control.edge_authorities(
 runtime_id uuid primary key,enabled boolean not null default false,
 issued_at timestamptz not null default statement_timestamp(),expires_at timestamptz not null,
 schedule_secret_id uuid not null,schedule_secret_hash text not null check(schedule_secret_hash ~ '^[a-f0-9]{64}$'),
 publishable_key text not null check(length(publishable_key) between 32 and 4096),
 job_ids bigint[] not null default '{}',
 check(isfinite(expires_at) and expires_at>issued_at and expires_at<=issued_at+interval '7 days'));
create table intelligence_control.edge_key_refs(
 runtime_id uuid not null references intelligence_control.edge_authorities(runtime_id),ref text not null,secret_id uuid not null,
 primary key(runtime_id,ref),check(ref in('w5/runtime/20261008/delivery/v1','w5/runtime/20261008/delivery/v2')));
create table intelligence_control.edge_ticks(
 runtime_id uuid not null references intelligence_control.edge_authorities(runtime_id),id uuid not null,
 kind text not null check(kind in('delivery','subscription','health')),state text not null check(state in('running','completed','failed','unknown')),
 started_at timestamptz not null default statement_timestamp(),lease_until timestamptz not null,
 primary key(runtime_id,id));
create index edge_running_tick_idx on intelligence_control.edge_ticks(runtime_id,kind,lease_until) where state='running';
create table intelligence_control.edge_tick_outcomes(
 runtime_id uuid not null,id uuid not null,success boolean not null,summary jsonb not null,
 recorded_at timestamptz not null default statement_timestamp(),primary key(runtime_id,id),
 foreign key(runtime_id,id) references intelligence_control.edge_ticks(runtime_id,id),
 check(jsonb_typeof(summary)='object' and octet_length(summary::text)<=2048));
create table intelligence_control.edge_receiver_receipts(
 runtime_id uuid not null references intelligence_control.edge_authorities(runtime_id),event_id uuid not null references core.outbox_events(id),
 tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,subscription_id uuid not null,
 key_version integer not null check(key_version in(1,2)),payload bytea not null check(octet_length(payload)<=8192),
 sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),signed_timestamp bigint not null,
 received_at timestamptz not null default statement_timestamp(),primary key(runtime_id,subscription_id,event_id),
 foreign key(tenant_id,subscription_id) references intelligence_control.integration_subscriptions(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id));
do $$declare rel text;begin
 foreach rel in array array['edge_authorities','edge_key_refs','edge_ticks','edge_tick_outcomes','edge_receiver_receipts'] loop
  execute format('alter table intelligence_control.%I enable row level security',rel);
  execute format('alter table intelligence_control.%I force row level security',rel);
  execute format('revoke all on intelligence_control.%I from public,anon,authenticated',rel);
 end loop;
 foreach rel in array array['edge_key_refs','edge_tick_outcomes','edge_receiver_receipts'] loop
  execute format('create trigger immutable before update or delete on intelligence_control.%I for each row execute function analytics.immutable_evidence()',rel);
 end loop;
end$$;

create function api.wave5_edge_control(p_runtime_id uuid,p_action text,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a intelligence_control.edge_authorities%rowtype;t intelligence_control.edge_ticks%rowtype;
 s intelligence_control.integration_subscriptions%rowtype;f analytics.pipeline_forecasts%rowtype;
 existing intelligence_control.edge_receiver_receipts%rowtype;v jsonb;b bytea;secret_value text;secret_id uuid;
 saved_claims text;source_tenant uuid;tick_id uuid;begin
 perform intelligence_control.runtime_worker_required(p_runtime_id);
 if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 select * into a from intelligence_control.edge_authorities where runtime_id=p_runtime_id and enabled
  and issued_at<=statement_timestamp() and expires_at>statement_timestamp() for update;
 if not found then raise exception using errcode='42501',message='RUNTIME_SCOPE_DENIED';end if;
 if p_action='begin_tick' then
  if (p_payload-array['tickId','kind','secretHash'])<>'{}' or not(p_payload ?& array['tickId','kind','secretHash'])
   or p_payload->>'kind' not in('delivery','subscription','health') or p_payload->>'secretHash' is distinct from a.schedule_secret_hash then
   raise exception using errcode='42501',message='WORKER_ACCESS_DENIED';end if;
  tick_id:=(p_payload->>'tickId')::uuid;
  if tick_id is null then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
  if exists(select 1 from intelligence_control.edge_ticks where runtime_id=p_runtime_id and id=tick_id) then
   return jsonb_build_object('permitted',false);end if;
  update intelligence_control.edge_ticks set state='unknown' where runtime_id=p_runtime_id and kind=p_payload->>'kind' and state='running' and lease_until<=statement_timestamp();
  if exists(select 1 from intelligence_control.edge_ticks where runtime_id=p_runtime_id and kind=p_payload->>'kind' and state='running') then
   return jsonb_build_object('permitted',false);end if;
  select tenant_id into source_tenant from intelligence_control.runtime_worker_scopes
   where runtime_id=p_runtime_id and intelligence_control.runtime_scope_allowed(p_runtime_id,tenant_id,legal_entity_id,branch_id) limit 1;
  insert into intelligence_control.edge_ticks(runtime_id,id,kind,state,lease_until)
   values(p_runtime_id,tick_id,p_payload->>'kind','running',statement_timestamp()+interval '90 seconds');
  return jsonb_build_object('permitted',true,'tenantId',source_tenant);
 elsif p_action='finish_tick' then
  if (p_payload-array['tickId','success','summary'])<>'{}' or not(p_payload ?& array['tickId','success','summary'])
   or jsonb_typeof(p_payload->'success')<>'boolean' or jsonb_typeof(p_payload->'summary')<>'object'
   or octet_length((p_payload->'summary')::text)>2048 then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
  select * into t from intelligence_control.edge_ticks where runtime_id=p_runtime_id and id=(p_payload->>'tickId')::uuid for update;
  if t.id is null or t.state<>'running' or t.lease_until<=statement_timestamp() then raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
  insert into intelligence_control.edge_tick_outcomes values(p_runtime_id,t.id,(p_payload->>'success')::boolean,p_payload->'summary',statement_timestamp());
  update intelligence_control.edge_ticks set state=case when (p_payload->>'success')::boolean then 'completed' else 'failed' end where runtime_id=p_runtime_id and id=t.id;
  return jsonb_build_object('recorded',true);
 elsif p_action='key' then
  if (p_payload-'ref')<>'{}' or not(p_payload ? 'ref') then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
  select k.secret_id into secret_id from intelligence_control.edge_key_refs k where k.runtime_id=p_runtime_id and k.ref=p_payload->>'ref';
  if secret_id is null then raise exception using errcode='42501',message='DELIVERY_KEY_UNAVAILABLE';end if;
  -- Only this runtime's two explicitly provisioned Vault IDs can be read. No
  -- caller-provided Vault ID/name and no existing project secret are discoverable.
  select decrypted_secret into secret_value from vault.decrypted_secrets where id=secret_id;
  if secret_value is null or secret_value !~ '^[a-f0-9]{64}$' then raise exception using errcode='55000',message='DELIVERY_KEY_UNAVAILABLE';end if;
  return jsonb_build_object('value',secret_value);
 elsif p_action in('receive','receive_probe') then
  if (p_payload-array['event','keyVersion','payloadBase64','sha256','timestamp','mode'])<>'{}'
   or not(p_payload ?& array['event','keyVersion','payloadBase64','sha256','timestamp','mode'])
   or p_payload->>'mode' not in('accept','redirect','timeout','reject')
   or (p_action='receive') is distinct from (p_payload->>'mode' in('accept','timeout')) then
   raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
  v:=p_payload->'event';b:=decode(p_payload->>'payloadBase64','base64');
  if octet_length(b)>8192 or convert_from(b,'UTF8')::jsonb is distinct from v
   or encode(extensions.digest(b,'sha256'),'hex') is distinct from p_payload->>'sha256'
   or (p_payload->>'timestamp')::bigint<extract(epoch from statement_timestamp())-300
   or (p_payload->>'timestamp')::bigint>extract(epoch from statement_timestamp())+30 then
   raise exception using errcode='22023',message='EVENT_CONTRACT_MISMATCH';end if;
  select s0.* into s from intelligence_control.integration_subscriptions s0
   where s0.id=case p_payload->>'mode'
    when 'accept' then '58699e8a-28fd-4356-8cad-87ce46e17ddd'::uuid
    when 'redirect' then '2bdbd842-5b94-464b-85fc-22d722498831'::uuid
    when 'timeout' then '0961e194-dc0b-4632-8c2d-65686fc9f111'::uuid
    when 'reject' then '360e7a9d-08a5-4349-854f-c2343ce2ff5d'::uuid end
    and s0.enabled and s0.key_version=(p_payload->>'keyVersion')::integer
    and s0.key_ref='w5/runtime/20261008/delivery/v'||(p_payload->>'keyVersion')
    and s0.url='https://xpdoufauvrbdmxgngetv.supabase.co/functions/v1/wave5-receiver/'||(p_payload->>'mode')
    and intelligence_control.runtime_scope_allowed(p_runtime_id,s0.tenant_id,s0.legal_entity_id,s0.branch_id);
  if not found then raise exception using errcode='42501',message='INTEGRATION_ACCESS_DENIED';end if;
  select f0.* into f from core.outbox_events o join analytics.pipeline_forecasts f0 on f0.tenant_id=o.tenant_id and f0.id=o.aggregate_id
   where o.id=(v->>'eventId')::uuid and o.tenant_id=s.tenant_id and o.topic='analytics.freeze_pipeline' and o.aggregate_type='pipeline_forecast'
    and f0.legal_entity_id=s.legal_entity_id and f0.branch_id=s.branch_id;
  if f.id is null or v is distinct from jsonb_build_object('eventId',(v->>'eventId')::uuid,'type','analytics.forecast.frozen.v1',
   'tenantId',s.tenant_id,'legalEntityId',s.legal_entity_id,'branchId',s.branch_id,'forecastId',f.id,'definitionVersion',1,'sourceHash',f.source_hash) then
   raise exception using errcode='42501',message='EVENT_CONTRACT_MISMATCH';end if;
  perform intelligence_control.quota_limit(s.tenant_id,'webhook.deliveries');
  saved_claims:=current_setting('request.jwt.claims',true);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',s.created_by,'role','authenticated','aal','aal1')::text,true);
  perform core.wave3_require_scope(s.tenant_id,'integrations.manage',s.legal_entity_id,s.branch_id);
  perform api.get_pipeline_forecast(s.tenant_id,s.legal_entity_id,s.branch_id,f.id);
  perform set_config('request.jwt.claims',coalesce(saved_claims,''),true);
  if p_action='receive_probe' then return jsonb_build_object('permitted',true);end if;
  select * into existing from intelligence_control.edge_receiver_receipts where runtime_id=p_runtime_id and subscription_id=s.id and event_id=(v->>'eventId')::uuid;
  if found then
   if existing.payload<>b or existing.sha256<>p_payload->>'sha256' then raise exception using errcode='23505',message='RECEIVER_DIGEST_CONFLICT';end if;
   return jsonb_build_object('acknowledged',true,'duplicate',true,'sha256',existing.sha256);end if;
  if not exists(select 1 from intelligence_control.delivery_heads d join intelligence_control.delivery_attempts da
   on da.tenant_id=d.tenant_id and da.delivery_id=d.id and da.attempt=d.attempt and da.lease_id=d.lease_id
   where d.tenant_id=s.tenant_id and d.subscription_id=s.id and d.event_id=(v->>'eventId')::uuid
    and d.state='leased' and d.lease_until>statement_timestamp() and da.key_version=s.key_version and da.subscription_version=s.version) then
   raise exception using errcode='42501',message='LEASE_UNAVAILABLE';end if;
  insert into intelligence_control.edge_receiver_receipts values(p_runtime_id,(v->>'eventId')::uuid,s.tenant_id,s.legal_entity_id,s.branch_id,s.id,
   (p_payload->>'keyVersion')::integer,b,p_payload->>'sha256',(p_payload->>'timestamp')::bigint,statement_timestamp());
  return jsonb_build_object('acknowledged',true,'duplicate',false,'sha256',p_payload->>'sha256');
 end if;
 raise exception using errcode='22023',message='WORKER_ACTION_INVALID';
end$$;
revoke all on function api.wave5_edge_control(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function api.wave5_edge_control(uuid,text,jsonb) to service_role;

-- UNINSTALLED infrastructure candidate. Enables the reviewed extensions but
-- creates no job/secret/authority. Jobs are a separate reviewed setup operation.
create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net with schema extensions;
create function intelligence_control.edge_schedule_tick(p_kind text) returns bigint
language plpgsql security definer set search_path='' as $$
declare a intelligence_control.edge_authorities%rowtype;k text;j bigint;begin
 if p_kind not in('delivery','subscription','health') then raise exception using errcode='22023',message='VALIDATION_ERROR';end if;
 select * into a from intelligence_control.edge_authorities where runtime_id='778237e3-3d4e-4871-8cc9-e08b07b989c7';
 if a.runtime_id is null then return null;end if;
 if not a.enabled or a.expires_at<=statement_timestamp() or not exists(select 1 from intelligence_control.runtime_worker_scopes s
  where s.runtime_id=a.runtime_id and intelligence_control.runtime_scope_allowed(a.runtime_id,s.tenant_id,s.legal_entity_id,s.branch_id)) then
  -- Only this authority's recorded job IDs and exact reviewed names are stopped.
  for j in select jobid from cron.job where jobid=any(a.job_ids)
   and jobname in('jentra-w5-20261009-delivery','jentra-w5-20261009-subscription','jentra-w5-20261009-health') loop
   perform cron.unschedule(j);end loop;
  update intelligence_control.edge_authorities set enabled=false where runtime_id=a.runtime_id;return null;
 end if;
 select decrypted_secret into k from vault.decrypted_secrets where id=a.schedule_secret_id;
 if k is null or encode(extensions.digest(k,'sha256'),'hex')<>a.schedule_secret_hash then raise exception using errcode='42501',message='WORKER_ACCESS_DENIED';end if;
 return net.http_post(url:='https://xpdoufauvrbdmxgngetv.supabase.co/functions/v1/wave5-runtime/schedule',
  headers:=jsonb_build_object('content-type','application/json','apikey',a.publishable_key,'x-jentra-schedule-key',k),
  body:=jsonb_build_object('tickId',gen_random_uuid(),'kind',p_kind),timeout_milliseconds:=70000);
end$$;
revoke all on function intelligence_control.edge_schedule_tick(text) from public,anon,authenticated,service_role;

